// Bootstrap shim — ensures _loginSubmit is callable even before the main
// script block finishes parsing. Forwards to the real implementation.
window._loginSubmit = function() {
  // If the real function is now defined (main block ran), call it
  if (typeof window.__loginSubmitReal === 'function') {
    window.__loginSubmitReal();
    return;
  }
  // Otherwise show a temporary loading message and retry once
  var btn = document.querySelector('.login-btn');
  if (btn) btn.textContent = 'Chargement…';
  setTimeout(function() {
    if (typeof window.__loginSubmitReal === 'function') {
      window.__loginSubmitReal();
    }
  }, 500);
};

