const ARROW_SVG = `<svg viewBox="0 0 60 16" xmlns="http://www.w3.org/2000/svg" style="width:54px;height:12px;display:block;margin:2px auto;"><line x1="0" y1="8" x2="47" y2="8" stroke="#06203B" stroke-width="1.2" opacity="0.25"/><polygon points="47,4 60,8 47,12" fill="#06203B" opacity="0.35"/></svg>`;

const AIRLINE_LOGO_BASE_URL = '/assets/airlines/'; // espelhado em public/ (antes: workspace.expaturtravel.com)
const AIRLINE_LOGO_DEFAULT = `${AIRLINE_LOGO_BASE_URL}default.svg`;
const AIRLINE_LOGO_CACHE_BUST = String(Date.now());

function _extractAirlineCode(value) {
  const raw = String(value || '').trim().toUpperCase();
  if (!raw) return '';
  if (/^[A-Z0-9]{2,3}$/.test(raw)) return raw.toLowerCase();
  const m = raw.match(/^([A-Z0-9]{2,3})\s*\d+/);
  return m ? m[1].toLowerCase() : '';
}

function getAirlineLogoCode(airline) {
  if (typeof airline === 'object' && airline) {
    const directCandidates = [
      airline.iata, airline.airline_iata, airline.marketing_carrier, airline.marketingCarrier,
      airline.marketingCarrierCode, airline.operating_carrier, airline.operatingCarrier, airline.operatingCarrierCode,
      airline.carrier, airline.carrierCode, airline.airlineCode, airline.code, airline.linked_airline_iata
    ];
    for (const candidate of directCandidates) {
      const directCode = _extractAirlineCode(candidate);
      if (directCode) return directCode;
    }

    if (Array.isArray(airline.airlineCodes)) {
      for (const candidate of airline.airlineCodes) {
        const listCode = _extractAirlineCode(candidate);
        if (listCode) return listCode;
      }
    }

    const fnLike = airline.fn || airline.flight_number || airline.flightNumber || airline.label || airline.flight || '';
    const fnCode = _extractAirlineCode(fnLike);
    if (fnCode) return fnCode;

    if (Array.isArray(airline.segments)) {
      for (const seg of airline.segments) {
        const deepCode = getAirlineLogoCode(seg);
        if (deepCode) return deepCode;
      }
    }
  }

  return _extractAirlineCode(airline);
}

function getAirlineLogoUrl(airline) {
  const code = getAirlineLogoCode(airline);
  return code ? `${AIRLINE_LOGO_BASE_URL}${code}.svg?v=${AIRLINE_LOGO_CACHE_BUST}` : `${AIRLINE_LOGO_DEFAULT}?v=${AIRLINE_LOGO_CACHE_BUST}`;
}

function getAirlineLogo(airline) {
  const safeAirline = esc((typeof airline === 'object' ? (airline.airline || airline.name || airline.fn || airline.flight_number || 'Airline') : (airline || 'Airline')));
  const code = getAirlineLogoCode(airline) || '';
  const src = code ? `${AIRLINE_LOGO_BASE_URL}${code}.svg?v=${AIRLINE_LOGO_CACHE_BUST}` : `${AIRLINE_LOGO_DEFAULT}?v=${AIRLINE_LOGO_CACHE_BUST}`;
  return `<img class="airline-logo-img" src="${src}" alt="${safeAirline}" data-airline-code="${code}" loading="eager" decoding="sync" crossorigin="anonymous" referrerpolicy="no-referrer" style="display:block;margin:4px auto;width:auto;max-width:84px;height:28px;max-height:28px;object-fit:contain;object-position:center center;" onerror="this.onerror=null;this.src='${AIRLINE_LOGO_DEFAULT}?v=${AIRLINE_LOGO_CACHE_BUST}';">`;
}

