// 
//  MILES COST CALCULATOR
// 
let milesRowId    = 0;
let _milesTotalBRL  = 0;   // live numeric total from miles calc
let _quoteFinalPrice = 0;  // set by buildPreview()
let _quoteCurrency   = '€';// set by buildPreview()
const MILES_ISSUERS = ['Smiles','Copa','Latam Pass','Latam Tabela Fixa','Air France','APM','Azul Fidelidade','QR Privilege Club','Consolidator','VISA / E.T.A','Volta Cancelada'];

//  Fornecedores list for Billet Cost tab (add/edit here) 
const COST_FORNECEDORES = [
  '— Sélectionner —',
];

function addMilesRow() {
  milesRowId++;
  const id  = milesRowId;
  const wrap = document.getElementById('miles-rows');
  const row  = document.createElement('div');
  row.className = 'miles-row-wrap';
  row.id = `miles-row-${id}`;
  row.draggable = true;
  const opts = MILES_ISSUERS.map(n => `<option value="${n}">${n}</option>`).join('');
  const fornOpts = COST_FORNECEDORES.map(n => `<option value="${n}">${n}</option>`).join('');
  row.innerHTML = `
    <span class="miles-drag-handle" title="Glisser pour réordonner"></span> <div style="flex:1.6;min-width:100px;"> <select id="mc-sel-${id}" onchange="onMilesIssuerChange(${id})">${opts}</select> </div> <div style="flex:1.6;min-width:100px;"> <select id="mc-forn-${id}" style="font-size:0.78rem;">${fornOpts}</select> </div> <div style="flex:1.2;min-width:90px;" id="mc-vol-wrap-${id}"> <input type="number" id="mc-vol-${id}"   min="0" step="1000"  placeholder="0"     oninput="calcMilesRow(${id})"> </div> <div style="flex:1;min-width:76px;" id="mc-cpm-wrap-${id}"> <input type="number" id="mc-cpm-${id}"   min="0" step="0.001" placeholder="0,000" oninput="calcMilesRow(${id})"> </div> <div style="flex:1;min-width:76px;" id="mc-fee-wrap-${id}"> <input type="number" id="mc-fee-${id}"   min="0" step="0.01"  placeholder="0,00"  oninput="calcMilesRow(${id})"> </div> <div style="flex:1;min-width:76px;display:flex;align-items:center;gap:4px;" id="mc-ext-wrap-${id}"> <input type="number" id="mc-ext-${id}" min="0" step="0.01" placeholder="0,00" oninput="calcMilesRow(${id})" style="flex:1;min-width:0;"> <select id="mc-visa-cur-${id}" onchange="calcMilesRow(${id})" style="display:none;flex:0 0 auto;width:52px;font-size:11px;padding:3px 2px;border-radius:5px;border:1px solid #ccc;background:#fff;"> <option value="USD">USD</option> <option value="EUR">EUR</option> </select> </div> <div class="miles-sub-box" id="mc-sub-${id}">R$ 0,00</div> <button class="miles-del-btn" onclick="removeMilesRow(${id})" title="Supprimer">×</button>`;
  wrap.appendChild(row);
  // Wire drag events
  row.addEventListener('dragstart', e => { e.dataTransfer.effectAllowed='move'; e.dataTransfer.setData('text/plain', row.id); row.classList.add('dragging'); });
  row.addEventListener('dragend',   () => { row.classList.remove('dragging'); document.querySelectorAll('.miles-row-wrap').forEach(r=>r.classList.remove('drag-over')); });
  row.addEventListener('dragover',  e => { e.preventDefault(); e.dataTransfer.dropEffect='move'; row.classList.add('drag-over'); });
  row.addEventListener('dragleave', () => row.classList.remove('drag-over'));
  row.addEventListener('drop', e => {
    e.preventDefault();
    row.classList.remove('drag-over');
    const srcId = e.dataTransfer.getData('text/plain');
    const src = document.getElementById(srcId);
    if (src && src !== row) wrap.insertBefore(src, row);
    calcMilesTotal();
  });
  calcMilesTotal();
}

function onMilesIssuerChange(id) {
  const sel        = document.getElementById(`mc-sel-${id}`)?.value;
  const hideVolCpm = sel === 'Consolidator' || sel === 'VISA / E.T.A' || sel === 'Volta Cancelada';
  const isVolta    = sel === 'Volta Cancelada';
  const isVisa     = sel === 'VISA / E.T.A';

  const volWrap     = document.getElementById(`mc-vol-wrap-${id}`);
  const cpmWrap     = document.getElementById(`mc-cpm-wrap-${id}`);
  const feeEl       = document.getElementById(`mc-fee-${id}`);
  const extWrap     = document.getElementById(`mc-ext-wrap-${id}`);
  const visaCurWrap = document.getElementById(`mc-visa-cur-wrap-${id}`);

  // Hide Vol & CPM for Consolidator / VISA E.T.A / Volta Cancelada
  if (volWrap) volWrap.style.visibility = hideVolCpm ? 'hidden' : '';
  if (cpmWrap) cpmWrap.style.visibility = hideVolCpm ? 'hidden' : '';

  // Volta Cancelada: taxas locked to 150; ext column repurposed as quantity (×taxa)
  // VISA/E.T.A: ext hidden (currency-based fee only)
  if (feeEl)   { feeEl.value = isVolta ? '150' : feeEl.value; feeEl.readOnly = isVolta; }
  if (extWrap) extWrap.style.visibility = isVisa ? 'hidden' : '';  // show for Volta

  // VISA / E.T.A: show currency dropdown right after Taxas; others: hide it
  if (visaCurWrap) visaCurWrap.style.display = isVisa ? '' : 'none';

  // Adapt ext input: for Volta → auto-fill with total pax (readonly); for others → decimal amount
  const extEl = document.getElementById(`mc-ext-${id}`);
  if (extEl) {
    if (isVolta) {
      // Auto-fill with total pax from the dossier itinerary
      const nA = parseInt(document.getElementById('pax-adultes')?.value) || 0;
      const nE = parseInt(document.getElementById('pax-enfants')?.value) || 0;
      const nB = parseInt(document.getElementById('pax-bebes')?.value)   || 0;
      const totalPax = Math.max(1, nA + nE + nB);
      extEl.placeholder = '1';
      extEl.step        = '1';
      extEl.min         = '1';
      extEl.value       = totalPax;
      extEl.readOnly    = true;
      extEl.title       = 'Nombre total de passagers (adultes + enfants + bébés) — calculé automatiquement';
      extEl.style.background = '#f0f4fa';
    } else {
      extEl.placeholder = '0,00';
      extEl.step        = '0.01';
      extEl.min         = '0';
      extEl.readOnly    = false;
      extEl.title       = '';
      extEl.style.background = '';
    }
  }

  // Zero out hidden fields
  if (hideVolCpm) {
    const volEl = document.getElementById(`mc-vol-${id}`);
    const cpmEl = document.getElementById(`mc-cpm-${id}`);
    if (volEl) volEl.value = '';
    if (cpmEl) cpmEl.value = '';
  }
  if (isVisa) {
    if (extEl) extEl.value = '';
  }
  if (isVolta) {
    if (feeEl) feeEl.value = '150';
    // Re-apply total pax autofill (in case extEl was not yet processed above)
    const _extElV = document.getElementById(`mc-ext-${id}`);
    if (_extElV) {
      const _nA = parseInt(document.getElementById('pax-adultes')?.value) || 0;
      const _nE = parseInt(document.getElementById('pax-enfants')?.value) || 0;
      const _nB = parseInt(document.getElementById('pax-bebes')?.value)   || 0;
      _extElV.value = Math.max(1, _nA + _nE + _nB);
    }
  }

  // Issuer defaults
  const ISSUER_DEFAULTS = {
    'QR Privilege Club':  { vol: 25750, cpm: 55,  fee: 1250 },
    'Smiles':             { cpm: 16.5,  fee: 33.64, ext: 130 },
    'Latam Pass':         { cpm: 28,    fee: 33.64 },
    'Latam Tabela Fixa':  { cpm: 28,    fee: 33.64 },
    'Copa':               { cpm: 70,    fee: 33.64 },
    'Air France':         { cpm: 80,    fee: 33.64 },
    'APM':                { cpm: 28,    fee: 33.64 },
  };
  const defaults = ISSUER_DEFAULTS[sel];
  if (defaults) {
    const volEl = document.getElementById(`mc-vol-${id}`);
    const cpmEl = document.getElementById(`mc-cpm-${id}`);
    const extEl2 = document.getElementById(`mc-ext-${id}`);
    if (defaults.vol != null && volEl  && !volEl.value)  volEl.value  = defaults.vol;
    if (defaults.cpm != null && cpmEl  && !cpmEl.value)  cpmEl.value  = defaults.cpm;
    if (defaults.fee != null && feeEl  && !feeEl.value)  feeEl.value  = defaults.fee;
    if (defaults.ext != null && extEl2 && !extEl2.value) extEl2.value = defaults.ext;
  }

  calcMilesRow(id);
}

function removeMilesRow(id) {
  const row = document.getElementById(`miles-row-${id}`);
  if (row) row.remove();
  calcMilesTotal();
}

async function calcMilesRow(id) {
  const sel    = document.getElementById(`mc-sel-${id}`)?.value;
  const isVisa  = sel === 'VISA / E.T.A';
  const isVolta = sel === 'Volta Cancelada';
  const cpm  = parseFloat(document.getElementById(`mc-cpm-${id}`)?.value) || 0;
  const vol  = parseFloat(document.getElementById(`mc-vol-${id}`)?.value) || 0;
  const fee  = parseFloat(document.getElementById(`mc-fee-${id}`)?.value) || 0;
  const ext  = parseFloat(document.getElementById(`mc-ext-${id}`)?.value) || 0;
  const el   = document.getElementById(`mc-sub-${id}`);

  if (isVisa) {
    // fee only (Taxas) is in the chosen currency (USD or EUR) → convert to BRL
    const visaCur = document.getElementById(`mc-visa-cur-${id}`)?.value || 'USD';
    const rawAmt  = fee;
    if (el) el.textContent = '…';
    try {
      const rate = await fetchBRLRate(visaCur === 'USD' ? '$' : '€');
      const sub  = rawAmt * rate;
      if (el) el.textContent = 'R$ ' + sub.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
    } catch(e) {
      if (el) el.textContent = 'Err FX';
    }
  } else if (isVolta) {
    // Volta Cancelada: sous-total = Taxas × Quantité (ext field repurposed as qty)
    const qty = Math.max(1, Math.round(ext) || 1);
    const sub = fee * qty;
    if (el) el.textContent = 'R$ ' + sub.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  } else {
    const sub = cpm * vol / 1000 + fee + ext;
    if (el) el.textContent = 'R$ ' + sub.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  }
  calcMilesTotal();
}

function calcMilesTotal() {
  let total = 0;
  document.querySelectorAll('.miles-row-wrap').forEach(row => {
    const rid    = row.id.replace('miles-row-','');
    const subEl  = document.getElementById(`mc-sub-${rid}`);
    // Parse the already-converted BRL value displayed in the sub box
    const subTxt = subEl?.textContent?.replace('R$','').replace(/\./g,'').replace(',','.').trim();
    const subVal = parseFloat(subTxt);
    if (!isNaN(subVal)) total += subVal;
  });
  _milesTotalBRL = total;
  const el = document.getElementById('miles-grand-total');
  if (el) el.textContent = 'R$ ' + total.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
  updateMilesSavings();
}

// Currency symbol → ISO code map
const _currencyISO = { '€':'EUR', '$':'USD', 'MAD':'MAD', 'R\$':'BRL', '£':'GBP', 'DOP':'DOP' };

const _fxCache = {}; // { 'EUR': { rate: 5.87, date: '2026-04-03' }, … }

// FX Worker URL (primary source for all currency → BRL rates)
const FX_WORKER_URL = 'https://fx-fetch-tarif.administration-a14.workers.dev';

async function fetchBRLRate(currencySymbol) {
  if (currencySymbol === 'R$') return 1;
  const from = _currencyISO[currencySymbol] || currencySymbol.toUpperCase() || 'EUR';
  const today = new Date().toISOString().slice(0, 10);

  // Return cached rate if already fetched today
  if (_fxCache[from] && _fxCache[from].date === today) {
    return _fxCache[from].rate;
  }

  let parsed = null;

  // 1) FX Worker (primary — SerpApi Google Finance via Cloudflare Worker)
  try {
    const r = await fetch(`${FX_WORKER_URL}/fx?from=${encodeURIComponent(from)}&to=BRL`, {
      signal: AbortSignal.timeout ? AbortSignal.timeout(8000) : undefined,
    });
    if (r.ok) {
      const d = await r.json();
      if (d.ok && typeof d.rate === 'number' && d.rate > 0) parsed = d.rate;
    }
  } catch(e) { /* fall through to CDN fallbacks */ }

  // 2) open.er-api.com — free, truly CORS-open, no key required
  if (parsed == null) {
    try {
      const r = await fetch(`https://open.er-api.com/v6/latest/${from}`);
      if (r.ok) {
        const d = await r.json();
        const rate = d?.rates?.BRL ?? null;
        if (rate != null) parsed = parseFloat(rate);
      }
    } catch(e) { /* fall through */ }
  }

  // 3) fawazahmed0 CDN — served via jsDelivr, CORS-open
  if (parsed == null) {
    try {
      const r = await fetch(`https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@latest/v1/currencies/${from.toLowerCase()}.json`);
      if (r.ok) {
        const d = await r.json();
        const rate = d?.[from.toLowerCase()]?.brl ?? null;
        if (rate != null) parsed = parseFloat(rate);
      }
    } catch(e) { /* fall through */ }
  }

  // 4) Frankfurter — ECB rates, CORS-open (EUR/GBP/USD only)
  if (parsed == null) {
    try {
      const r = await fetch(`https://api.frankfurter.app/latest?from=${from}&to=BRL`);
      if (r.ok) {
        const d = await r.json();
        const rate = d?.rates?.BRL ?? null;
        if (rate != null) parsed = parseFloat(rate);
      }
    } catch(e) { /* fall through */ }
  }

  if (parsed == null) throw new Error('Taux BRL introuvable pour ' + from);

  _fxCache[from] = { rate: parsed, date: today };
  return parsed;
}

async function updateMilesSavings() {
  const box = document.getElementById('miles-savings-box');
  if (!box) return;
  if (_quoteFinalPrice <= 0) {
    box.innerHTML = `<span style="font-size:0.78rem;color:var(--navy-faint);">Générez d'abord un devis pour voir le calcul.</span>`;
    return;
  }
  box.innerHTML = `<span style="font-size:0.78rem;color:var(--navy-faint);">Chargement du taux de change…</span>`;
  try {
    const rate   = await fetchBRLRate(_quoteCurrency);
    const ravCoef = _quoteCurrency === 'MAD' ? 0.935 : _quoteCurrency === '€' ? 0.97 : 0.95;
    const brl95  = _quoteFinalPrice * rate * ravCoef;
    const net    = brl95 - _milesTotalBRL;
    const fmtBRL = v => 'R$ ' + v.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
    const netColor = net >= 0 ? 'var(--success)' : 'var(--red)';
    const coefStr = ravCoef.toString().replace('.', ',');
    box.innerHTML = `
      <div style="display:grid;grid-template-columns:1fr auto;gap:4px 16px;font-size:0.78rem;line-height:2;"> <span style="color:var(--navy-faint);">Prix devis (${_quoteCurrency}) × taux BRL (${rate.toFixed(4)}) × ${coefStr}</span> <span style="text-align:right;font-weight:600;">${fmtBRL(brl95)}</span> <span style="color:var(--navy-faint);">− Coût total miles</span> <span style="text-align:right;font-weight:600;">− ${fmtBRL(_milesTotalBRL)}</span> <span style="font-weight:700;color:var(--navy);border-top:1px solid var(--border);padding-top:4px;">R.A.V brute estimée</span> <span style="text-align:right;font-weight:800;font-size:0.92rem;color:${netColor};border-top:1px solid var(--border);padding-top:4px;">${net >= 0 ? '' : '−'}${fmtBRL(Math.abs(net))}</span> </div>`;
  } catch(e) {
    box.innerHTML = `<span style="font-size:0.72rem;color:var(--red);">Erreur taux de change : ${e.message}</span>`;
  }
}

