// 
//  UTILS
// 
function toast(msg, type='info') {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.style.background = type==='error' ? '#c0392b' : type==='success' ? '#1a7a4e' : '#06203b';
  t.style.opacity = '1';
  clearTimeout(t._t);
  t._t = setTimeout(() => t.style.opacity='0', 3000);
}

function esc(str) {
  return String(str||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function fmtDateLong(iso) {
  if (!iso) return '—';
  const d = new Date(iso + 'T12:00:00Z');
  return d.toLocaleDateString('fr-FR', {day:'2-digit', month:'long', year:'numeric'});
}

function fmtDateWithYear(iso) {
  if (!iso) return '—';
  const d = new Date(iso + 'T12:00:00Z');
  return d.toLocaleDateString('fr-FR', {day:'2-digit', month:'long', year:'numeric'});
}

function fmtTimeDisplay(timeStr) {
  if (!timeStr || timeStr === '—') return timeStr || '—';
  // Handle SerpAPI datetime "YYYY-MM-DD HH:MM"
  const dtMatch = timeStr.match(/\d{4}-\d{2}-\d{2}[\sT](\d{1,2}):(\d{2})/);
  if (dtMatch) {
    return String(dtMatch[1]).padStart(2,'0') + ':' + dtMatch[2];
  }
  // Handle French format "9 heures 25" or "09 heures 25" or "9h25"
  const frMatch = timeStr.match(/^(\d{1,2})\s*h(?:eures?)?\s*(\d{2})/i);
  if (frMatch) {
    return String(parseInt(frMatch[1])).padStart(2,'0') + ':' + frMatch[2];
  }
  const m = timeStr.match(/^(\d{1,2}):(\d{2})(?:\s*(AM|PM))?/i);
  if (m) {
    let h = parseInt(m[1]), min = parseInt(m[2]);
    if (m[3]) {
      const pm = m[3].toUpperCase() === 'PM';
      if (pm && h !== 12) h += 12;
      if (!pm && h === 12) h = 0;
    }
    return String(h).padStart(2,'0') + ':' + String(min).padStart(2,'0');
  }
  return timeStr;
}

function fmtMin(min) {
  if (!min) return '—';
  const h = Math.floor(min/60);
  const m = String(min%60).padStart(2,'0');
  return String(h).padStart(2,'0') + ' Heures ' + m + ' min';
}

function addDays(iso, n) {
  const d = new Date(iso + 'T12:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0,10);
}

// 
//  TRIP TYPE
// 
function setTripType(type) {
  tripType = type;
  document.querySelectorAll('.trip-type-btn').forEach(b => b.classList.toggle('active', b.dataset.type === type));

  const isReturn    = type === 'return';
  const isMulticity = type === 'multicity';

  // Leg 1: span full inner grid width except in aller-retour (sits beside leg 2)
  document.getElementById('leg1-title').textContent = isMulticity ? 'Vol 1' : isReturn ? 'Vol Aller' : 'Vol';
  const leg1Card = document.getElementById('leg1-card');
  leg1Card.style.gridColumn = isReturn ? '' : (isMulticity ? '1' : '1 / -1');

  // Leg 2: only visible in aller-retour, sits in second column
  document.getElementById('leg2-card').style.display = isReturn ? '' : 'none';

  // Multi-city section
  document.getElementById('multicity-section').style.display = isMulticity ? '' : 'none';
  // Hide/show multicity leg cards inside the grid
  document.getElementById('multicity-legs').style.display = isMulticity ? 'contents' : 'none';

  if (isReturn) {
    const a1 = document.getElementById('arr1').value.toUpperCase();
    const d1 = document.getElementById('dep1').value.toUpperCase();
    document.getElementById('dep2').value = a1;
    document.getElementById('arr2').value = d1;
    selLeg2 = null;
    document.getElementById('results-leg2').innerHTML = '';
    document.getElementById('selected-leg2-info').innerHTML = '';
    document.getElementById('status-leg2').textContent = 'Saisissez la date et lancez la recherche.';
  }

  if (isMulticity && multiLegs.length === 0) {
    // Seed with 1 extra leg (Vol 2) — user can add more
    addMultiLeg();
  }

  updateLegTitles();
  updateDocAnnexe();
}

//  Multi-city: add a leg card
function addMultiLeg() {
  multiLegId++;
  const id = multiLegId;
  multiLegs.push({ id, dep:'', arr:'', date:'', sel: null });

  const wrap = document.getElementById('multicity-legs');
  const card = document.createElement('div');
  card.className = 'inner-leg-card';
  card.id = `multi-card-${id}`;
  const legIndex = multiLegs.length; // after push, 1-based
  card.style.gridColumn = '2'; // always right column in desktop
  card.style.marginBottom = '0'; // gap handled by grid
  card.innerHTML = `
    <div class="inner-leg-title" style="display:flex;justify-content:space-between;align-items:center;"> <span id="multi-title-${id}">Vol 2</span> <button onclick="removeMultiLeg(${id})" style="background:none;border:none;cursor:pointer;font-size:0.75rem;color:var(--red);font-weight:700;letter-spacing:0.05em;padding:0;">Supprimer</button> </div> <div class="row"> <div class="f1"> <label>Départ (IATA)</label> <input type="text" id="multi-dep-${id}" maxlength="3" placeholder="GRU" class="iata-input"
               oninput="this.value=this.value.toUpperCase();updateMultiLeg(${id});"> </div> <div class="f1"> <label>Arrivée (IATA)</label> <input type="text" id="multi-arr-${id}" maxlength="3" placeholder="MCP" class="iata-input"
               oninput="this.value=this.value.toUpperCase();updateMultiLeg(${id});"> </div> <div class="f2"> <label>Date de départ</label> <input type="date" id="multi-date-${id}" oninput="updateMultiLeg(${id});syncDateMins()"> </div> <div style="display:flex;align-items:flex-end;"> <button class="btn btn-navy btn-sm" onclick="searchMultiLeg(${id})" id="multi-btn-${id}">Rechercher</button> </div> </div> <div class="status-msg" id="multi-status-${id}">Saisissez les codes IATA, la date et lancez la recherche.</div> <div class="results-area" id="multi-results-${id}"></div> <div style="margin-top:0.7rem;" id="multi-selected-${id}"></div>`;
  wrap.appendChild(card);
  renumberMultiLegs();
  syncDateMins();
}

function removeMultiLeg(id) {
  multiLegs = multiLegs.filter(l => l.id !== id);
  const card = document.getElementById(`multi-card-${id}`);
  if (card) card.remove();
  renumberMultiLegs();
  syncDateMins();
}

function renumberMultiLegs() {
  multiLegs.forEach((l, idx) => {
    const title = document.getElementById(`multi-title-${l.id}`);
    if (title) title.textContent = `Vol ${idx + 2}`;
    // Recompute grid column: first extra leg sits in col 2, rest span full row
    const card = document.getElementById(`multi-card-${l.id}`);
    if (card) card.style.gridColumn = (idx === 0) ? '2' : '1 / -1';
  });
}


function syncDateMins() {
  //  Leg 1 min = today (quote date)
  const todayIso = new Date().toISOString().slice(0,10);
  const leg1El = document.getElementById('date-leg1');
  if (leg1El) { leg1El.min = todayIso; if (leg1El.value && leg1El.value < todayIso) leg1El.value = todayIso; }
  //  Fixed Leg 1 → Leg 2 (aller-retour)
  const d1 = document.getElementById('date-leg1')?.value || '';
  const d2el = document.getElementById('date-leg2');
  if (d2el) {
    d2el.min = d1;
    if (d2el.value && d1 && d2el.value < d1) d2el.value = d1;
  }

  //  Multi-city: each leg's min = previous leg's date
  // Leg 1 (fixed) is the base; multiLegs[0] min = leg1 date
  // multiLegs[i] min = multiLegs[i-1] date
  for (let i = 0; i < multiLegs.length; i++) {
    const prevDate = i === 0
      ? (document.getElementById('date-leg1')?.value || '')
      : (document.getElementById(`multi-date-${multiLegs[i-1].id}`)?.value || '');
    const dateEl = document.getElementById(`multi-date-${multiLegs[i].id}`);
    if (dateEl) {
      dateEl.min = prevDate;
      if (dateEl.value && prevDate && dateEl.value < prevDate) {
        dateEl.value = prevDate;
        updateMultiLeg(multiLegs[i].id);
      }
    }
  }
}

function updateMultiLeg(id) {
  const leg = multiLegs.find(l => l.id === id);
  if (!leg) return;
  leg.dep  = document.getElementById(`multi-dep-${id}`)?.value?.toUpperCase().trim() || '';
  leg.arr  = document.getElementById(`multi-arr-${id}`)?.value?.toUpperCase().trim() || '';
  leg.date = document.getElementById(`multi-date-${id}`)?.value || '';
}

async function searchMultiLeg(id) {
  const leg = multiLegs.find(l => l.id === id);
  if (!leg) return;
  updateMultiLeg(id);
  if (leg.dep.length < 2 || leg.arr.length < 2) { toast('Saisissez les codes IATA', 'error'); return; }
  if (!leg.date) { toast('Sélectionnez une date', 'error'); return; }
  const btn    = document.getElementById(`multi-btn-${id}`);
  const status = document.getElementById(`multi-status-${id}`);
  const results = document.getElementById(`multi-results-${id}`);
  btn.disabled = true; btn.textContent = '…';
  status.textContent = `Recherche ${leg.dep} → ${leg.arr} le ${fmtDateLong(leg.date)}…`;
  results.innerHTML = '';
  leg.sel = null;
  document.getElementById(`multi-selected-${id}`).innerHTML = '';
  try {
    const data = await serpFetch({
      engine: 'google_flights',
      departure_id: leg.dep,
      arrival_id:   leg.arr,
      outbound_date: leg.date,
      currency: 'EUR', hl: 'fr', type: '2'
    });
    const all = [...(data.best_flights||[]), ...(data.other_flights||[])];
    const flights = all.map(f => parseSerpFlight(f, leg.date));
    renderResultsFor(id, flights, leg.date, 'multi');
    status.textContent = flights.length ? '' : 'Aucun vol trouvé.';
  } catch(e) {
    status.textContent = 'Erreur : ' + (e.message || 'connexion impossible');
    toast('Erreur de recherche', 'error');
  }
  btn.disabled = false; btn.textContent = 'Rechercher';
}

// Flight data store (keyed by dropdown option value)
if (!window._flightMap) window._flightMap = {};

// Generic result renderer — dropdown version
function renderResultsFor(legId, flights, dateVal, mode) {
  const elId   = mode === 'multi' ? `multi-results-${legId}` : `results-leg${legId}`;
  const infoId = mode === 'multi' ? `multi-selected-${legId}` : `selected-leg${legId}-info`;
  const el = document.getElementById(elId);
  if (!el) return;
  el.innerHTML = '';
  if (!flights.length) return;

  const mapKey = `${mode}_${legId}`;
  const sorted = [...flights].sort((a,b) => (a.durMin||0)-(b.durMin||0));

  const sel = document.createElement('select');
  sel.className = 'flight-select';

  const placeholder = document.createElement('option');
  placeholder.value = '';
  placeholder.textContent = `— ${sorted.length} vol${sorted.length > 1 ? 's' : ''} trouvé${sorted.length > 1 ? 's' : ''} — sélectionnez —`;
  sel.appendChild(placeholder);

  sorted.forEach((f, idx) => {
    const key = `${mapKey}_${idx}`;
    window._flightMap[key] = f;
    const stops = f.stops === 0 ? 'Direct' : `${f.stops} escale${f.stops > 1 ? 's' : ''}`;
    const segs  = f.segments.length > 1
      ? '  [' + f.segments.map(s=>`${s.depCode}→${s.arrCode}`).join(' / ') + ']'
      : '';
    const opt = document.createElement('option');
    opt.value = key;
    opt.textContent = `${f.fn}  |  ${f.depCode} ${fmtTimeDisplay(f.depTime)} → ${f.arrCode} ${fmtTimeDisplay(f.arrTime)}  |  ${f.durStr}  |  ${stops}${segs}`;
    sel.appendChild(opt);
  });

  sel.onchange = () => {
    const infoEl = document.getElementById(infoId);
    if (!sel.value) {
      if (mode === 'multi') { const lg = multiLegs.find(l=>l.id===legId); if(lg) lg.sel=null; }
      else { if (legId===1) selLeg1=null; else selLeg2=null; }
      if (infoEl) infoEl.innerHTML = '';
      return;
    }
    const fc = JSON.parse(JSON.stringify(window._flightMap[sel.value]));
    if (mode === 'multi') {
      const lg = multiLegs.find(l=>l.id===legId);
      if (lg) lg.sel = fc;
    } else {
      if (legId===1) selLeg1=fc; else selLeg2=fc;
    }
    _itinWidgetRefreshIfOpen();

    // ── Auto-prefill CMN→DOH: fires from ANY trip type ──────────────────────────
    // Selecting a CMN→DOH flight in oneway or return mode auto-switches to
    // multicity and runs the full DOH→GRU (D+1) + GRU→MCP (D+2) flow.
    if (fc.depCode === 'CMN' && fc.arrCode === 'DOH') {
      // Step 1: switch to multicity if needed — this also creates the first extra leg
      if (tripType !== 'multicity') {
        setTripType('multicity');
      }
      // Step 2: ensure arr1 is set to DOH (it may not be if this was a oneway search
      // where dep1=CMN and arr1 was something else)
      const _arr1El = document.getElementById('arr1');
      if (_arr1El) _arr1El.value = 'DOH';
      // Step 2b: CMN→DOH→GRU→MCP always includes 2 checked bags — set automatically
      const _bagsQtyEl = document.getElementById('bags-qty');
      if (_bagsQtyEl && (parseInt(_bagsQtyEl.value) || 0) < 2) {
        _bagsQtyEl.value = '2';
      }

      // Step 3: determine position of this leg in the flat segment order
      const _isLeg1Fixed = (mode === 'fixed' && legId === 1);
      const _selSegIdx   = _isLeg1Fixed ? 0 : (multiLegs.findIndex(l => l.id === legId) + 1);
      const _needIdx0    = _selSegIdx;     // index for DOH→GRU leg
      const _needIdx1    = _selSegIdx + 1; // index for GRU→MCP leg
      while (multiLegs.length <= _needIdx1) addMultiLeg();

      const _baseDateIso = fc.depDate || fc.arrDate || document.getElementById('date-leg1')?.value || '';
      const _date1 = _baseDateIso ? addDays(_baseDateIso, 1) : '';
      const _date2 = _baseDateIso ? addDays(_baseDateIso, 2) : '';

      // Step 4: fill Vol 2 — DOH → GRU at D+1
      const _lg1 = multiLegs[_needIdx0];
      if (_lg1) {
        const _dep1el  = document.getElementById(`multi-dep-${_lg1.id}`);
        const _arr1elX = document.getElementById(`multi-arr-${_lg1.id}`);
        const _date1el = document.getElementById(`multi-date-${_lg1.id}`);
        if (_dep1el)  { _dep1el.value  = 'DOH'; updateMultiLeg(_lg1.id); }
        if (_arr1elX) { _arr1elX.value = 'GRU'; updateMultiLeg(_lg1.id); }
        if (_date1el && _date1) { _date1el.value = _date1; updateMultiLeg(_lg1.id); }
        _lg1.sel = null;
        const _sel1El = document.getElementById(`multi-selected-${_lg1.id}`);
        if (_sel1El) _sel1El.innerHTML = '';
        const _res1El = document.getElementById(`multi-results-${_lg1.id}`);
        if (_res1El) _res1El.innerHTML = '';
        const _sta1El = document.getElementById(`multi-status-${_lg1.id}`);
        if (_sta1El) _sta1El.textContent = 'Saisissez les codes IATA, la date et lancez la recherche.';
      }

      // Step 5: fill Vol 3 — GRU → MCP at D+2
      const _lg2 = multiLegs[_needIdx1];
      if (_lg2) {
        const _dep2el  = document.getElementById(`multi-dep-${_lg2.id}`);
        const _arr2el  = document.getElementById(`multi-arr-${_lg2.id}`);
        const _date2el = document.getElementById(`multi-date-${_lg2.id}`);
        if (_dep2el)  { _dep2el.value  = 'GRU'; updateMultiLeg(_lg2.id); }
        if (_arr2el)  { _arr2el.value  = 'MCP'; updateMultiLeg(_lg2.id); }
        if (_date2el && _date2) { _date2el.value = _date2; updateMultiLeg(_lg2.id); }
        _lg2.sel = null;
        const _sel2El = document.getElementById(`multi-selected-${_lg2.id}`);
        if (_sel2El) _sel2El.innerHTML = '';
        const _res2El = document.getElementById(`multi-results-${_lg2.id}`);
        if (_res2El) _res2El.innerHTML = '';
        const _sta2El = document.getElementById(`multi-status-${_lg2.id}`);
        if (_sta2El) _sta2El.textContent = 'Saisissez les codes IATA, la date et lancez la recherche.';
      }

      syncDateMins();
      buildPreview();
      toast('Itinéraire multi-destinations créé : DOH→GRU (J+1) · GRU→MCP (J+2) — recherche en cours…', 'success');
      // Flag both legs for auto-selection of best direct flight once results arrive
      window._autoSelectLegs = window._autoSelectLegs || {};
      if (_lg1) window._autoSelectLegs['multi_' + _lg1.id] = true;
      if (_lg2) window._autoSelectLegs['multi_' + _lg2.id] = true;
      if (_lg1) setTimeout(function() { searchMultiLeg(_lg1.id); }, 300);
      if (_lg2) setTimeout(function() { searchMultiLeg(_lg2.id); }, 1800);

    // ── CMN → GRU → pre-fill GRU → MCP at D+1 (multicity only) ──────────────
    } else if (tripType === 'multicity' && fc.depCode === 'CMN' && fc.arrCode === 'GRU') {
      const _isLeg1Fixed2 = (mode === 'fixed' && legId === 1);
      const _nextLg = _isLeg1Fixed2 ? multiLegs[0] : multiLegs[multiLegs.findIndex(l => l.id === legId) + 1];
      if (_nextLg) {
        const baseDateIso = fc.depDate || document.getElementById('date-leg1')?.value || '';
        const nextDate = baseDateIso ? addDays(baseDateIso, 1) : '';
        const depEl  = document.getElementById(`multi-dep-${_nextLg.id}`);
        const arrEl  = document.getElementById(`multi-arr-${_nextLg.id}`);
        const dateEl = document.getElementById(`multi-date-${_nextLg.id}`);
        if (depEl)  { depEl.value  = 'GRU'; updateMultiLeg(_nextLg.id); }
        if (arrEl)  { arrEl.value  = 'MCP'; updateMultiLeg(_nextLg.id); }
        if (dateEl && nextDate) { dateEl.value = nextDate; updateMultiLeg(_nextLg.id); }
        syncDateMins();
        toast('Vol suivant pre-rempli : GRU → MCP (J+1)', 'success');
      }
    }
    if (infoEl) infoEl.innerHTML =
      `<div class="flight-select-info">${esc(fc.fn)} · ${esc(fc.depCode)} ${esc(fmtTimeDisplay(fc.depTime))} → ${esc(fc.arrCode)} ${esc(fmtTimeDisplay(fc.arrTime))} · ${esc(fc.durStr)}</div>`;
  };

  el.appendChild(sel);

  // ── Auto-select: if this leg is flagged for auto-selection, pick best direct flight ──
  if (window._autoSelectLegs && window._autoSelectLegs[mapKey]) {
    delete window._autoSelectLegs[mapKey]; // consume flag
    // Pick direct flight (stops===0), fallback to shortest duration
    const _directFlight = sorted.find(function(f){ return f.stops === 0; });
    const _bestFlight   = _directFlight || sorted[0];
    if (_bestFlight) {
      // Find the option key for this flight
      const _bestIdx  = sorted.indexOf(_bestFlight);
      const _bestKey  = mapKey + '_' + _bestIdx;
      sel.value = _bestKey;
      // Fire onchange to trigger the full selection flow (updates selLeg, buildPreview, etc.)
      sel.dispatchEvent(new Event('change'));
    }
  }
}

function onAirportChange() {
  if (tripType === 'return') {
    document.getElementById('dep2').value = document.getElementById('arr1').value.toUpperCase();
    document.getElementById('arr2').value = document.getElementById('dep1').value.toUpperCase();
  }
  updateLegTitles();
  selLeg1 = null;
  document.getElementById('results-leg1').innerHTML = '';
  document.getElementById('selected-leg1-info').innerHTML = '';
  document.getElementById('status-leg1').textContent = 'Saisissez les codes IATA, la date et lancez la recherche.';
  checkWaMarocRoute();
  _itinWidgetRefreshIfOpen();
}

function checkWaMarocRoute() {
  const d1 = (document.getElementById('dep1')?.value||'').toUpperCase();
  const a1 = (document.getElementById('arr1')?.value||'').toUpperCase();
  let isCMNGRU = (d1==='CMN' && a1==='GRU');
  let isGRUMCP = false;
  if (tripType==='multicity') {
    multiLegs.forEach(function(ml){ if(ml.dep==='GRU'&&ml.arr==='MCP') isGRUMCP=true; });
  }
  const wrap = document.getElementById('wa-maroc-wrap');
  if (wrap) wrap.style.display = (isCMNGRU && isGRUMCP) ? '' : 'none';
}

function updateLegTitles() {
  const d1 = document.getElementById('dep1')?.value?.toUpperCase() || '—';
  const a1 = document.getElementById('arr1')?.value?.toUpperCase() || '—';
  const d2 = document.getElementById('dep2')?.value?.toUpperCase() || '—';
  const a2 = document.getElementById('arr2')?.value?.toUpperCase() || '—';
  document.getElementById('leg1-title').textContent = `Vol Aller — ${d1} → ${a1}`;
  if (tripType === 'return') document.getElementById('leg2-title').textContent = `Vol Retour — ${d2} → ${a2}`;
}

