// 
//  SERP API
// 
async function serpFetch(params) {
  try {
    const q = new URLSearchParams(params);
    const r = await fetch(SERP_PROXY_URL + '?' + q);
    const text = await r.text();
    const data = JSON.parse(text);
    if (r.ok && ('best_flights' in data || 'other_flights' in data || 'price_insights' in data)) return data;
  } catch (e) { /* fall through */ }
  const q2 = new URLSearchParams({...params, api_key: SERP_API_KEY, output: 'json'});
  const r2 = await fetch('https://serpapi.com/search?' + q2);
  if (!r2.ok) throw new Error('SerpAPI ' + r2.status);
  return r2.json();
}

function parseSerpFlight(f, dateVal) {
  const segs  = f.flights || [];
  const first = segs[0] || {};
  const last  = segs[segs.length-1] || first;
  const durMin = f.total_duration || 0;
  let curDate = dateVal;
  return {
    raw: f,
    fn:       segs.map(s => s.flight_number||'').filter(Boolean).join(' + ') || '—',
    airline:  [...new Set(segs.map(s => s.airline||'').filter(Boolean))].join(', '),
    aircraft: [...new Set(segs.map(s => s.airplane||'').filter(Boolean))],
    durMin,
    durStr: fmtMin(durMin),
    stops:  f.layovers?.length || 0,
    layovers: f.layovers || [],
    depCode: first.departure_airport?.id   || '',
    depName: first.departure_airport?.name || '',
    depTime: first.departure_airport?.time || '—',
    depDate: dateVal,
    depDateDisplay: fmtDateLong(dateVal),
    arrCode: last.arrival_airport?.id   || '',
    arrName: last.arrival_airport?.name || '',
    arrTime: last.arrival_airport?.time || '—',
    arrDate: segs.some(s=>s.overnight) ? addDays(dateVal,1) : dateVal,
    arrDateDisplay: fmtDateLong(segs.some(s=>s.overnight) ? addDays(dateVal,1) : dateVal),
    overnight: segs.some(s=>s.overnight),
    segments: segs.map(s => {
      const dep = curDate;
      const arr = s.overnight ? addDays(dep,1) : dep;
      curDate = arr;
      return {
        fn:       s.flight_number || '',
        airline:  s.airline || '',
        aircraft: s.airplane || '',
        depCode:  s.departure_airport?.id   || '',
        depName:  s.departure_airport?.name || '',
        depTime:  s.departure_airport?.time || '—',
        depDateDisplay: fmtDateLong(dep),
        arrCode:  s.arrival_airport?.id   || '',
        arrName:  s.arrival_airport?.name || '',
        arrTime:  s.arrival_airport?.time || '—',
        arrDateDisplay: fmtDateLong(arr),
        durMin:   s.duration || 0,
        durStr:   fmtMin(s.duration),
        overnight: s.overnight || false
      };
    })
  };
}

//  Search for a fixed leg (1 or 2, used for oneway/return)
const FLIGHT_CACHE_TTL = 7 * 24 * 60 * 60 * 1000; // 7 days in ms

function flightCacheKey(dep, arr, date) {
  return `expatur_flight_${dep}_${arr}_${date}`;
}
function flightCacheGet(dep, arr, date) {
  try {
    const raw = localStorage.getItem(flightCacheKey(dep, arr, date));
    if (!raw) return null;
    const entry = JSON.parse(raw);
    if (Date.now() - entry.ts > FLIGHT_CACHE_TTL) { localStorage.removeItem(flightCacheKey(dep, arr, date)); return null; }
    return entry.flights;
  } catch(e) { return null; }
}
function flightCacheSet(dep, arr, date, flights) {
  try {
    localStorage.setItem(flightCacheKey(dep, arr, date), JSON.stringify({ ts: Date.now(), flights }));
  } catch(e) { /* storage full — ignore */ }
}

async function searchLeg(leg) {
  const dep     = document.getElementById(`dep${leg}`)?.value?.toUpperCase().trim() || '';
  const arr     = document.getElementById(`arr${leg}`)?.value?.toUpperCase().trim() || '';
  const dateVal = document.getElementById(`date-leg${leg}`)?.value || '';
  if (dep.length < 2 || arr.length < 2) { toast('Saisissez les codes IATA départ et arrivée', 'error'); return; }
  if (!dateVal) { toast(`Sélectionnez une date pour le Vol ${leg}`, 'error'); return; }

  const btn     = document.getElementById(`btn-leg${leg}`);
  const status  = document.getElementById(`status-leg${leg}`);
  const results = document.getElementById(`results-leg${leg}`);
  if (leg === 1) { selLeg1 = null; document.getElementById('selected-leg1-info').innerHTML = ''; }
  else           { selLeg2 = null; document.getElementById('selected-leg2-info').innerHTML = ''; }
  results.innerHTML = '';

  // Check 7-day cache first
  const cached = flightCacheGet(dep, arr, dateVal);
  if (cached) {
    status.textContent = `Résultats en cache (${dep} → ${arr}) — aucune requête envoyée.`;
    renderResultsFor(leg, cached, dateVal, 'fixed');
    return;
  }

  btn.disabled = true; btn.textContent = '…';
  status.textContent = `Recherche ${dep} → ${arr} le ${fmtDateLong(dateVal)}…`;

  try {
    const data = await serpFetch({ engine:'google_flights', departure_id:dep, arrival_id:arr, outbound_date:dateVal, currency:'EUR', hl:'fr', type:'2' });
    const flights = [...(data.best_flights||[]), ...(data.other_flights||[])].map(f => parseSerpFlight(f, dateVal));
    flightCacheSet(dep, arr, dateVal, flights);
    renderResultsFor(leg, flights, dateVal, 'fixed');
    status.textContent = flights.length ? '' : 'Aucun vol trouvé pour cette date.';
  } catch(e) {
    status.textContent = 'Erreur : ' + (e.message || 'connexion impossible');
    toast('Erreur de recherche', 'error');
  }
  btn.disabled = false; btn.textContent = 'Rechercher';
}

