// Seeded with critical routes; CSV load enriches all lookups at runtime.
const IATA_CITY = {
  CMN:'Casablanca', CDG:'Paris', ORY:'Paris', LHR:'Londres', LGW:'Londres',
  JFK:'New York', EWR:'New York', MIA:'Miami', LAX:'Los Angeles', ATL:'Atlanta',
  GRU:'São Paulo', GIG:'Rio de Janeiro', BSB:'Brasília', CNF:'Belo Horizonte',
  MCP:'Macapá', BEL:'Belém', MAO:'Manaus', REC:'Recife', SSA:'Salvador',
  FOR:'Fortaleza', CWB:'Curitiba', POA:'Porto Alegre', FLN:'Florianópolis',
  PBM:'Paramaribo', SDQ:'Saint-Domingue', PUJ:'Punta Cana',
  AMS:'Amsterdam', FRA:'Francfort', MAD:'Madrid', BCN:'Barcelone',
  FCO:'Rome', MXP:'Milan', LIN:'Milan', ZRH:'Zurich', VIE:'Vienne',
  BRU:'Bruxelles', LIS:'Lisbonne', OPO:'Porto',
  DXB:'Dubaï', DOH:'Doha', CAI:'Le Caire', ADD:'Addis-Abeba',
  JNB:'Johannesburg', NBO:'Nairobi', LFW:'Lomé',
  RAK:'Marrakech', AGA:'Agadir', FEZ:'Fès', OUD:'Oujda', TNG:'Tanger', NDR:'Nador',
  PTY:'Panama City', BOG:'Bogotá', LIM:'Lima', EZE:'Buenos Aires',
  SCL:'Santiago', UIO:'Quito', MVD:'Montevideo', ASU:'Asunción',
  CCS:'Caracas', HAV:'La Havane',
  SXM:'Saint-Martin', PTP:'Pointe-à-Pitre', FDF:'Fort-de-France',
  AUA:'Aruba', CUR:'Curaçao', MBJ:'Montego Bay', KIN:'Kingston',
};
const IATA_NAME    = {}; // code → full airport name (from CSV)
const IATA_COUNTRY = {}; // code → country code (from CSV)

// Load full airport database from local CSV (vendored em public/ — antes vinha
// do servidor PHP workspace.expaturtravel.com, que bloqueava por CORS)
(function _loadAirportDB() {
  const _URL = '/assets/airportdata/airports.csv';
  fetch(_URL)
    .then(function(r) { return r.ok ? r.text() : Promise.reject(r.status); })
    .then(function(csv) {
      const lines = csv.split(/\r?\n/);
      // header: code,name,country,city
      for (var i = 1; i < lines.length; i++) {
        const row = lines[i].split(',');
        if (row.length < 2) continue;
        const code    = (row[0] || '').trim().toUpperCase();
        const name    = (row[1] || '').trim();
        const country = (row[2] || '').trim();
        const city    = (row[3] || '').trim();
        if (!code) continue;
        if (name)    IATA_NAME[code]    = name;
        if (country) IATA_COUNTRY[code] = country;
        // Only overwrite IATA_CITY if CSV has a city AND the seed map doesn't already have it
        if (city && !IATA_CITY[code]) IATA_CITY[code] = city;
        // For seeds without a city entry, fill from CSV city if missing
        else if (city && IATA_CITY[code] === code) IATA_CITY[code] = city;
      }
    })
    .catch(function(e) { console.warn('[airportDB] load failed:', e); });
})();

// Lookup helpers — available everywhere in the app
function iataCity(code)    { return IATA_CITY[code]    || code; }
function iataName(code)    { return IATA_NAME[code]    || code; }
function iataCountry(code) { return IATA_COUNTRY[code] || ''; }

