      // Compute GRU layover time — read directly from the DOM flight-strip elements
      // since legsData may be the merged version with no separate GRU entry.
      // Strategy: find the ticket whose last arrival apt-code is GRU (inbound),
      // and the ticket whose first departure apt-code is GRU (outbound).
      let _gruLayStr = '';
      try {
        const _toMinGRU = function(t) {
          const norm = typeof fmtTimeDisplay==='function' ? fmtTimeDisplay(String(t||'')) : String(t||'');
          const m = norm.match(/(\d{1,2}):(\d{2})/);
          return m ? parseInt(m[1])*60 + parseInt(m[2]) : NaN;
        };
        // Inbound GRU: last .apt-block.right .apt-time of the ticket whose last arrCode=GRU
        let _gruArrTime = '', _gruDepTime = '';
        Array.from(ticketEls).forEach(function(_tEl) {
          const _rightCodes = _tEl.querySelectorAll('.apt-block.right .apt-code');
          const _lastCode = _rightCodes.length ? _rightCodes[_rightCodes.length-1].textContent.trim().toUpperCase() : '';
          if (_lastCode === 'GRU') {
            const _rightTimes = _tEl.querySelectorAll('.apt-block.right .apt-time');
            _gruArrTime = _rightTimes.length ? _rightTimes[_rightTimes.length-1].textContent.trim() : '';
          }
          const _leftCodes = _tEl.querySelectorAll('.apt-block:not(.right) .apt-code');
          const _firstCode = _leftCodes.length ? _leftCodes[0].textContent.trim().toUpperCase() : '';
          if (_firstCode === 'GRU') {
            const _leftTimes = _tEl.querySelectorAll('.apt-block:not(.right) .apt-time');
            _gruDepTime = _leftTimes.length ? _leftTimes[0].textContent.trim() : '';
          }
        });
        // Also check legsData as fallback (for cases where DOM isn't populated yet)
        if (!_gruArrTime || !_gruDepTime) {
          const _ldGRUin  = legsData.find(function(l){ return l.arr==='GRU'; }) || {};
          const _ldGRUout = legsData.find(function(l){ return l.dep==='GRU'; }) || {};
          if (!_gruArrTime && _ldGRUin.arrTime)  _gruArrTime = _ldGRUin.arrTime;
          if (!_gruDepTime && _ldGRUout.depTime) _gruDepTime = _ldGRUout.depTime;
        }
        const _aM = _toMinGRU(_gruArrTime);
        const _dM = _toMinGRU(_gruDepTime);
        if (!isNaN(_aM) && !isNaN(_dM)) {
          const _df = _dM > _aM ? (_dM - _aM) : (24*60 - _aM + _dM);
          if (_df > 0) {
            const _h = Math.floor(_df/60), _mm = String(_df%60).padStart(2,'0');
            _gruLayStr = String(_h).padStart(2,'0') + 'h' + _mm;
          }
        }
      } catch(_) {}

      // Build one unified card from all ticketEls' flight-strips.
      // Detect the connecting airport between tickets by reading the last arrCode
