function downloadBookingConfirmation() {
  var ref = (document.getElementById('booking-ref')||{}).value || 'CONFIRMATION';
  ref = ref.trim() || 'CONFIRMATION';
  // Print/save the docs panel as PDF
  var link = document.createElement('a');
  link.href = 'javascript:void(0)';
  // Trigger browser print dialog focused on docs panel
  var prev = document.querySelector('.dv-panel.active');
  var docPanel = document.getElementById('dv-panel-docs');
  // Temporarily show only docs for printing
  document.querySelectorAll('.dv-panel').forEach(function(p){ p.dataset._wasActive = p.classList.contains('active') ? '1' : ''; p.classList.remove('active'); });
  docPanel.classList.add('active');
  setTimeout(function(){
    window.print();
    // Restore
    document.querySelectorAll('.dv-panel').forEach(function(p){ if(p.dataset._wasActive==='1') p.classList.add('active'); else p.classList.remove('active'); });
  }, 150);
}

//  Itinerary rolldown widget 
function toggleItinWidget() {
  var btn   = document.getElementById('itin-widget-btn');
  var panel = document.getElementById('itin-widget-panel');
  if (!btn || !panel) return;
  var isOpen = panel.classList.contains('open');
  if (isOpen) {
    panel.classList.remove('open');
    btn.classList.remove('open');
  } else {
    updateItineraryWidget();
    panel.classList.add('open');
    btn.classList.add('open');
  }
}

function updateItineraryWidget() {
  var content = document.getElementById('itin-widget-content');
  if (!content) return;

  var legs = [];
  var mode = (typeof tripType !== 'undefined') ? tripType : 'oneway';

  // Leg 1
  var d1 = (document.getElementById('dep1') || {}).value || '';
  var a1 = (document.getElementById('arr1') || {}).value || '';
  var dt1 = (document.getElementById('date-leg1') || {}).value || '';
  if (d1 || a1) {
    legs.push({ dep: d1.toUpperCase() || '—', arr: a1.toUpperCase() || '—', date: dt1, sel: (typeof selLeg1 !== 'undefined') ? selLeg1 : null });
  }

  // Leg 2 (return)
  if (mode === 'return') {
    var d2 = (document.getElementById('dep2') || {}).value || '';
    var a2 = (document.getElementById('arr2') || {}).value || '';
    var dt2 = (document.getElementById('date-leg2') || {}).value || '';
    if (d2 || a2) {
      legs.push({ dep: d2.toUpperCase() || '—', arr: a2.toUpperCase() || '—', date: dt2, sel: (typeof selLeg2 !== 'undefined') ? selLeg2 : null });
    }
  }

  // Multicity legs
  if (mode === 'multicity' && typeof multiLegs !== 'undefined') {
    multiLegs.forEach(function(l) {
      legs.push({ dep: (l.dep || '—').toUpperCase(), arr: (l.arr || '—').toUpperCase(), date: l.date || '', sel: l.sel || null });
    });
  }

  if (!legs.length || !legs[0].dep) {
    content.innerHTML = '<div class="itin-empty">Aucun vol saisi</div>';
    return;
  }

  var html = '';
  legs.forEach(function(leg, i) {
    var dateStr = leg.date ? (function(iso) {
      try { var d = new Date(iso + 'T12:00:00Z'); return d.toLocaleDateString('fr-FR', {day:'2-digit', month:'short', year:'numeric'}); } catch(e) { return iso; }
    })(leg.date) : '—';
    var fn = leg.sel && leg.sel.fn ? leg.sel.fn : '';
    var depTime = leg.sel && leg.sel.depTime ? leg.sel.depTime : '';
    var arrTime = leg.sel && leg.sel.arrTime ? leg.sel.arrTime : '';
    var stops = (leg.sel && typeof leg.sel.stops !== 'undefined') ? (leg.sel.stops === 0 ? 'Direct' : leg.sel.stops + ' escale' + (leg.sel.stops > 1 ? 's' : '')) : '';
    var timeStr = (depTime && arrTime) ? (depTime + '  ' + arrTime) : '';

    html += '<div class="itin-leg">';
    var airlineIata = (typeof getAirlineLogoCode === 'function') ? getAirlineLogoCode(fn || (leg.sel && (leg.sel.airline || leg.sel.label || leg.sel.fn)) || '') : (fn ? fn.substring(0, 2).toLowerCase() : '');
    var logoHtml = '';
    if (airlineIata) {
      var logoVer = (typeof AIRLINE_LOGO_CACHE_BUST !== 'undefined' ? AIRLINE_LOGO_CACHE_BUST : String(Date.now()));
      var logoSrc = ((typeof AIRLINE_LOGO_BASE_URL !== 'undefined' ? AIRLINE_LOGO_BASE_URL : '/assets/airlines/') + airlineIata + '.svg?v=' + logoVer);
      var logoFallback = ((typeof AIRLINE_LOGO_DEFAULT !== 'undefined' ? AIRLINE_LOGO_DEFAULT : '/assets/airlines/default.svg') + '?v=' + logoVer);
      logoHtml = `<img src="${logoSrc}" style="width:24px;height:24px;border-radius:4px;object-fit:contain;" onerror="this.onerror=null;this.src='${logoFallback}'" />`;
    }
    html += '<div style="flex:0 0 auto;display:flex;align-items:center;gap:0.5rem;">';
    if (logoHtml) html += logoHtml;
    html += '<div>';
    html += '<div class="itin-leg-codes">' + leg.dep + ' <span class="itin-leg-arrow"></span> ' + leg.arr + '</div>';
    if (fn) html += '<div class="itin-leg-fn">' + fn + '</div>';
    html += '</div></div>';
    html += '<div class="itin-leg-detail" style="flex:1;text-align:right;">';
    html += '<div style="font-weight:600;color:var(--navy);">' + dateStr + '</div>';
    if (timeStr) html += '<div>' + timeStr + '</div>';
    if (stops) html += '<div>' + stops + '</div>';
    html += '</div>';
    html += '</div>';
  });
  content.innerHTML = html;
}

// Auto-update widget when open after any flight selection
