function dvOpenPaiement() {
  try { openEmissionModal(); } catch(e) { console.warn('openEmissionModal error:', e); }
  dvSwitch('paiement');
}
function dvSwitch(tab) {
  // Save Paiement state when navigating away from it
  const currentActive = document.querySelector('.dv-panel.active');
  if (currentActive && currentActive.id === 'dv-panel-paiement' && tab !== 'paiement') {
    try { _emSaveState(); } catch(e) {}
  }
  // Toggle all tabs and panels (client/vols/couts use bk-panel-* read-only summaries)
  ['client','vols','couts','paiement','docs','billet','tasks'].forEach(function(t) {
    var btn = document.getElementById('dv-tab-'+t);
    var panId = (t==='client'||t==='vols'||t==='couts') ? 'bk-panel-'+t : 'dv-panel-'+t;
    var pan = document.getElementById(panId);
    if (btn) btn.classList.toggle('active', t === tab);
    if (pan) pan.classList.toggle('active', t === tab);
  });
  if (tab === 'client') { bkRenderClientSummary(); }
  if (tab === 'vols')   { bkRenderVolsSummary(); }
  if (tab === 'couts')  { bkRenderCoutsSummary(); }
  if (tab === 'billet') { setTimeout(openBilletModal, 0); }
  if (tab === 'tasks') { _loadTasks(); }
  if (tab === 'docs') { setTimeout(_blRestoreAndRefreshPaymentSection, 0); }
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

/* ── Booking read-only summary renderers ── */
function bkRenderClientSummary() {
  var el = document.getElementById('bk-client-content');
  if (!el) return;
  var ref = (document.getElementById('booking-ref')||{}).value || localStorage.getItem('expatur_active_dossier') || '';
  var data = null;
  try { data = JSON.parse(localStorage.getItem('expatur_client_' + ref) || 'null'); } catch(e) {}
  if (!data) {
    el.innerHTML = '<p style="color:var(--navy-faint);font-style:italic;font-size:0.9rem;">Aucun client renseigné. Complétez le profil dans <strong>Quoting → Client</strong>.</p>';
    return;
  }
  var rows = [
    ['Nom', [data.civilite, data.prenom, data.nom].filter(Boolean).join(' ') || '—'],
    ['Date de naissance', data.naissance || '—'],
    ['Nationalité', data.nationalite || '—'],
    ['Passeport', data.passport || '—'],
    ['Expiration passeport', data.passport_exp || '—'],
    ['Email', data.email || '—'],
    ['Téléphone', data.tel || '—'],
    ['WhatsApp', data.whatsapp || '—'],
    ['Adresse', [data.adresse, data.cp, data.ville, data.pays].filter(Boolean).join(', ') || '—'],
  ];
  if (data.notes) rows.push(['Notes', data.notes]);
  el.innerHTML = '<table style="width:100%;border-collapse:collapse;font-size:0.9rem;">' +
    rows.map(function(r) {
      return '<tr><td style="padding:0.45rem 1rem 0.45rem 0;color:#888;white-space:nowrap;vertical-align:top;width:40%;">' + r[0] + '</td>' +
             '<td style="padding:0.45rem 0;font-weight:500;color:var(--navy);">' + r[1] + '</td></tr>';
    }).join('') + '</table>';
}
window.bkRenderClientSummary = bkRenderClientSummary;

function bkRenderVolsSummary() {
  var el = document.getElementById('bk-vols-content');
  if (!el) return;
  var id = localStorage.getItem('expatur_active_dossier') || '';
  var dd = null;
  try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null'); } catch(e) {}
  var f = (dd && dd.fields) || {};
  var tripType = (dd && dd.tripType) || 'oneway';
  var html = '<table style="width:100%;border-collapse:collapse;font-size:0.9rem;">';
  var rows = [];
  rows.push(['Type de voyage', tripType==='return' ? 'Aller-Retour' : tripType==='multicity' ? 'Multi-destinations' : 'Aller simple']);
  if (tripType === 'multicity' && dd && dd.multiLegs && dd.multiLegs.length) {
    dd.multiLegs.forEach(function(leg, i) {
      rows.push(['Tronçon ' + (i+1), (leg.dep||'?') + ' → ' + (leg.arr||'?') + (leg.date ? ' · ' + leg.date : '')]);
    });
  } else {
    if (f['dep1'] || f['arr1']) rows.push(['Itinéraire', (f['dep1']||'?') + ' → ' + (f['arr1']||'?')]);
    if (f['date-leg1']) rows.push(['Date départ', f['date-leg1']]);
    if (tripType === 'return' && f['date-leg2']) rows.push(['Date retour', f['date-leg2']]);
  }
  if (f['travel-class']) rows.push(['Classe', f['travel-class']]);
  rows.push(['Passagers', [
    f['pax-adultes'] ? f['pax-adultes'] + ' adulte(s)' : '',
    f['pax-enfants'] ? f['pax-enfants'] + ' enfant(s)' : '',
    f['pax-bebes']   ? f['pax-bebes']   + ' bébé(s)'   : ''
  ].filter(Boolean).join(', ') || '—']);
  if (f['bags-qty']) rows.push(['Bagages', f['bags-qty'] + ' bagage(s)' + (f['bags-kg'] ? ' · ' + f['bags-kg'] + ' kg' : '')]);
  if (!f['dep1'] && !(dd && dd.multiLegs && dd.multiLegs.length)) {
    el.innerHTML = '<p style="color:var(--navy-faint);font-style:italic;font-size:0.9rem;">Aucun itinéraire renseigné. Complétez dans <strong>Quoting → Itinéraire</strong>.</p>';
    return;
  }
  html += rows.map(function(r) {
    return '<tr><td style="padding:0.45rem 1rem 0.45rem 0;color:#888;white-space:nowrap;vertical-align:top;width:40%;">' + r[0] + '</td>' +
           '<td style="padding:0.45rem 0;font-weight:500;color:var(--navy);">' + r[1] + '</td></tr>';
  }).join('');
  html += '</table>';
  // Custom lines
  if (dd && dd.customLines && dd.customLines.length) {
    html += '<div style="margin-top:1rem;padding-top:1rem;border-top:1px solid var(--border);"><strong style="font-size:0.8rem;color:#888;text-transform:uppercase;letter-spacing:0.05em;">Lignes personnalisées</strong>';
    dd.customLines.forEach(function(cl) {
      html += '<div style="margin-top:0.4rem;font-size:0.9rem;color:var(--navy);">· ' + (cl.label||'') + (cl.value ? ' : ' + cl.value : '') + '</div>';
    });
    html += '</div>';
  }
  el.innerHTML = html;
}
window.bkRenderVolsSummary = bkRenderVolsSummary;

function bkRenderCoutsSummary() {
  var el = document.getElementById('bk-couts-content');
  if (!el) return;
  var id = localStorage.getItem('expatur_active_dossier') || '';
  var dd = null;
  try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null'); } catch(e) {}
  var f = (dd && dd.fields) || {};
  var cur = f['currency'] || 'MAD';
  var fmt = function(v) { return v ? parseFloat(v).toLocaleString('fr-FR', {minimumFractionDigits:0}) + ' ' + cur : '—'; };
  var rows = [];
  if (f['price-adulte']) rows.push(['Prix adulte', fmt(f['price-adulte'])]);
  if (f['price-enfant']) rows.push(['Prix enfant', fmt(f['price-enfant'])]);
  if (f['price-bebe'])   rows.push(['Prix bébé',   fmt(f['price-bebe'])]);
  if (f['discount-value']) rows.push(['Remise', fmt(f['discount-value'])]);
  if (f['offer-name'])   rows.push(['Offre', f['offer-name']]);
  if (f['validity-date']) rows.push(['Validité', f['validity-date']]);
  if (f['vendeur-select']) rows.push(['Vendeur', f['vendeur-select']]);
  if (f['vendeur-commission']) rows.push(['Commission', f['vendeur-commission'] + (f['vendeur-commission-type']==='pct' ? ' %' : ' ' + cur)]);
  if (f['price-note'])   rows.push(['Note prix', f['price-note']]);
  if (!rows.length) {
    el.innerHTML = '<p style="color:var(--navy-faint);font-style:italic;font-size:0.9rem;">Aucune tarification renseignée. Complétez dans <strong>Quoting → Tarification</strong>.</p>';
    return;
  }
  el.innerHTML = '<table style="width:100%;border-collapse:collapse;font-size:0.9rem;">' +
    rows.map(function(r) {
      return '<tr><td style="padding:0.45rem 1rem 0.45rem 0;color:#888;white-space:nowrap;vertical-align:top;width:40%;">' + r[0] + '</td>' +
             '<td style="padding:0.45rem 0;font-weight:500;color:var(--navy);">' + r[1] + '</td></tr>';
    }).join('') + '</table>';
}
window.bkRenderCoutsSummary = bkRenderCoutsSummary;

/* ── Booking state helpers ── */
var _BOOKING_TABS = ['paiement','billet','docs','tasks','finance'];
function _isBookingEnabled() {
  var id = localStorage.getItem('expatur_active_dossier') || null;
  if (!id) return false;
  return localStorage.getItem('expatur_booked_' + id) === '1';
}
function _applyBookingTabState() {
  var booked = _isBookingEnabled();
  _BOOKING_TABS.forEach(function(t) {
    var btn = document.getElementById('qt-tab-' + t);
    if (!btn) return;
    if (booked) {
      btn.classList.remove('qt-tab-locked');
    } else {
      btn.classList.add('qt-tab-locked');
    }
  });
  var cta = document.getElementById('qt-book-cta');
  if (cta) cta.classList.toggle('booked', booked);
}
function _enableBooking() {
  var id = localStorage.getItem('expatur_active_dossier') || null;
  if (!id) {
    if (typeof toast === 'function') toast('⚠ Veuillez d\'abord créer ou ouvrir un ticket (onglet + Nouveau ticket)', 'error');
    else alert('Veuillez sélectionner ou créer un dossier avant de confirmer la réservation.');
    return;
  }
  if (_isBookingEnabled()) { quotingSwitch('paiement'); return; }
  localStorage.setItem('expatur_booked_' + id, '1');
  // Record the date when the booking was confirmed
  if (!localStorage.getItem('expatur_bookedAt_' + id)) {
    localStorage.setItem('expatur_bookedAt_' + id, new Date().toISOString());
  }
  _applyBookingTabState();
  // Update tab to show "closed" status
  _dossierRenderTabs();
  quotingSwitch('paiement');
  if (typeof openEmissionModal === 'function') { setTimeout(openEmissionModal, 200); }
}
window._enableBooking = _enableBooking;
window._applyBookingTabState = _applyBookingTabState;

/* ── Quoting section tab switcher ── */
var _lastQuotingTab = 'vols';
var _ALL_QT_TABS = ['vols','client','couts','paiement','billet','docs','tasks','finance'];
function quotingSwitch(tab) {
  // Block locked tabs
  if (_BOOKING_TABS.indexOf(tab) !== -1 && !_isBookingEnabled()) return;
  if (tab === 'index') tab = 'vols'; // index tab removed — redirect to default
  _lastQuotingTab = tab;
  // Toggle tab buttons
  _ALL_QT_TABS.forEach(function(t) {
    var btn = document.getElementById('qt-tab-'+t);
    if (btn) btn.classList.toggle('active', t === tab);
  });
  // Toggle panels
  ['vols','client','couts','paiement','billet','docs','tasks','finance'].forEach(function(t) {
    var pan = document.getElementById('dv-panel-'+t);
    if (pan) pan.classList.toggle('active', t === tab);
  });
  if (tab === 'couts') { setTimeout(function(){ if(typeof blPopulateCostFinancial==='function') blPopulateCostFinancial(); }, 50); }
  if (tab === 'billet') { setTimeout(function(){ if(typeof openBilletModal==='function') openBilletModal(); }, 0); }
  if (tab === 'finance') { setTimeout(function(){ if(typeof dossFinRenderPanel==='function') dossFinRenderPanel(); }, 50); }
  // Scroll the panels host back to top
  var _ph = document.getElementById('quoting-panels-host');
  if (_ph) _ph.scrollTop = 0; else window.scrollTo({ top: 0, behavior: 'smooth' });
}
window.quotingSwitch = quotingSwitch;

/* ── Move quoting panels into section-quoting on load ── */
function _initQuotingSection() {
  var host = document.getElementById('quoting-panels-host');
  if (!host) return;
  // Move all editing + booking panels (index lives in Booking sidebar)
  ['dv-panel-client','dv-panel-vols','dv-panel-couts','dv-panel-paiement','dv-panel-billet','dv-panel-docs','dv-panel-tasks','dv-panel-finance'].forEach(function(id) {
    var panel = document.getElementById(id);
    if (panel) host.appendChild(panel);
  });
  quotingSwitch('vols');
  setTimeout(function(){ if (typeof _applyBookingTabState === 'function') _applyBookingTabState(); }, 0);
}
window._initQuotingSection = _initQuotingSection;

/* ── Render quoting index table ── */
function qtRenderIndex() {
  var tbody = document.getElementById('qt-index-tbody');
  var statsEl = document.getElementById('qt-index-stats');
  if (!tbody) return;
  var list;
  try { list = JSON.parse(localStorage.getItem('expatur_dossier_list')||'[]'); } catch(e){ list=[]; }
  var q = ((document.getElementById('qt-index-search')||{}).value||'').toLowerCase().trim();
  var shown = list.slice().reverse().filter(function(d) {
    if (!q) return true;
    var dd; try { dd = JSON.parse(localStorage.getItem('expatur_dossier_'+d.id)||'null'); } catch(e){}
    var ref  = ((dd&&dd.fields&&dd.fields['booking-ref'])||d.label||'').toLowerCase();
    var name = (typeof _diPaxName==='function' ? _diPaxName(dd||{}) : '').toLowerCase();
    return ref.indexOf(q)>=0 || name.indexOf(q)>=0;
  });
  if (statsEl) statsEl.textContent = shown.length + ' devis' + (q ? ' trouvés' : ' au total');
  tbody.innerHTML = '';
  if (!shown.length) {
    tbody.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:2.5rem;color:var(--navy-faint);font-style:italic;">Aucun devis trouvé.</td></tr>';
    return;
  }
  var activeId = localStorage.getItem('expatur_active_dossier') || '';
  shown.forEach(function(d) {
    var dd; try { dd = JSON.parse(localStorage.getItem('expatur_dossier_'+d.id)||'null'); } catch(e){}
    var ref    = (dd&&dd.fields&&dd.fields['booking-ref']) || d.label || '—';
    var client = (typeof _diPaxName==='function') ? _diPaxName(dd||{}) : '—';
    var issued = (typeof _diIsIssued==='function') ? _diIsIssued(ref) : false;
    var tripType = (dd&&dd.tripType)||'oneway';
    var tripLabel = tripType==='return' ? 'Aller-Retour' : tripType==='multicity' ? 'Multi-dest.' : 'Aller simple';
    var statusHtml = issued
      ? '<span style="display:inline-flex;align-items:center;gap:4px;padding:2px 9px;border-radius:999px;font-size:0.58rem;font-weight:700;letter-spacing:0.1em;background:rgba(22,101,52,0.1);color:#166534;">✓ Émis</span>'
      : '<span style="display:inline-flex;align-items:center;gap:4px;padding:2px 9px;border-radius:999px;font-size:0.58rem;font-weight:700;letter-spacing:0.1em;background:rgba(216,5,5,0.08);color:var(--red);">⏳ En cours</span>';
    var isActive = d.id === activeId;
    var tr = document.createElement('tr');
    tr.style.cssText = 'cursor:pointer;transition:background 0.12s;' + (isActive ? 'background:rgba(6,32,59,0.04);' : '');
    tr.onmouseover = function(){ this.style.background='rgba(6,32,59,0.05)'; };
    tr.onmouseout  = function(){ this.style.background = isActive ? 'rgba(6,32,59,0.04)' : ''; };
    tr.innerHTML = [
      '<td style="font-family:monospace;font-weight:700;font-size:0.76rem;letter-spacing:0.06em;color:var(--navy);">'+(ref||'—')+(isActive?'&nbsp;<span style="font-size:0.5rem;background:var(--red);color:#fff;padding:1px 5px;border-radius:3px;vertical-align:middle;">actif</span>':'')+'</td>',
      '<td style="font-weight:500;color:var(--navy);">'+client+'</td>',
      '<td style="font-size:0.72rem;color:var(--navy-soft);">'+tripLabel+'</td>',
      '<td>'+statusHtml+'</td>',
      '<td style="text-align:center;"><button class="btn btn-navy btn-sm" onclick="event.stopPropagation();switchDossier(\''+d.id+'\');quotingSwitch(\'vols\');" style="font-size:0.6rem;padding:3px 9px;">Ouvrir</button></td>'
    ].join('');
    tr.onclick = function() { switchDossier(d.id); quotingSwitch('vols'); };
    tbody.appendChild(tr);
  });
}
window.qtRenderIndex = qtRenderIndex;

