//  FINANCIAL INLINE (Couts panel)
// 
function blPopulateCostFinancial() { blCalcPnL(); }

// 
//  TASKS  (with categories + due dates)
// 
var TASK_CATS = ['Check-in','Payments','Suriname Visa','Suriname I.C.F','QR code R.D','Volta Cancelada','Notas Fiscais','Facture','Diversos'];
var TASK_CAT_ICONS = {
  'Check-in':       '',
  'Payments':       '',
  'Notas Fiscais':  '',
  'Facture':        '',
  'Suriname Visa':  '',
  'Suriname I.C.F': '',
  'QR code R.D':    '',
  'Volta Cancelada':'',
  'Diversos':       ''
};
var _tasks=[];
function _taskRef(){var ref=(document.getElementById('booking-ref')||{}).value||'DEVIS';return (ref||'DEVIS').trim();}
function _tasksKey(){return 'tasks_v2_'+_taskRef();}
function _taskServerPersist(ref, tasks){
  ref = (ref||'DEVIS').trim();
  try {
    var clean = (tasks||[]).map(function(t){
      var c=Object.assign({},t);
      delete c._ref; delete c._pax; delete c._dossierId;
      return c;
    });
    if (typeof window.saveData === 'function') {
      Promise.resolve(window.saveData('task', ref, clean)).catch(function(err){ console.warn('task server persist failed', err); });
    }
  } catch(err) { console.warn('task server persist prep failed', err); }
}
function _saveTasks(){
  var ref = _taskRef();
  try { localStorage.setItem('tasks_v2_'+ref, JSON.stringify(_tasks)); } catch(_) {}
  _taskServerPersist(ref, _tasks);
  // Keep dashboard and Tarefas module in sync
  setTimeout(function() {
    if (typeof tarefasRender === 'function') {
      var tl = document.getElementById('tarefas-list-body');
      if (tl) tarefasRender();
    }
    if (typeof welcomeRefresh === 'function' && typeof _currentSection !== 'undefined' && _currentSection === 'welcome') {
      welcomeRefresh();
    }
  }, 0);
}
function _loadTasks(){
  var ref = _taskRef();
  try{
    if (window.taskStore && typeof window.taskStore.getTasksByDossier === 'function') {
      _tasks = window.taskStore.getTasksByDossier(ref) || [];
    } else {
      var s=localStorage.getItem('tasks_v2_'+ref); if(s) _tasks=JSON.parse(s); else _tasks=[];
    }
  }catch(_){_tasks=[];}
  renderTasks();
}
function addTask(){
  var inp  = document.getElementById('task-input');
  var prio = 'normal';
  var cat  = (document.getElementById('task-cat')||{}).value||'Diversos';
  var due  = (document.getElementById('task-due')||{}).value||'';
  var text = (inp||{}).value ? inp.value.trim() : '';
  if(!text)return;
  var ref = _taskRef();
  var taskData = {id:Date.now(),text:text,done:false,prio:prio,cat:cat,dueDate:due,dueDesc:''};
  if (window.taskStore && typeof window.taskStore.saveTask === 'function') {
    window.taskStore.saveTask(ref, taskData);
    try { _tasks = window.taskStore.getTasksByDossier(ref) || []; } catch(_) {}
  } else {
    _tasks.push(taskData);
    _saveTasks();
  }
  if(inp) inp.value='';
  var dueEl = document.getElementById('task-due');
  if(dueEl) { dueEl.value=''; dueEl.style.display='none'; }
  var dueSel = document.getElementById('task-due-select');
  if(dueSel) { dueSel.value=''; }
  renderTasks();
}
function toggleTask(id){var t=_tasks.find(function(t){return t.id===id;});if(t){t.done=!t.done;_saveTasks();renderTasks();}}
function deleteTask(id){
  _tasks=_tasks.filter(function(t){return t.id!==id;});
  if(typeof _deleteTaskFiles==='function') _deleteTaskFiles(id);
  _saveTasks();renderTasks();
}
function clearAllTasks(){if(!confirm('Effacer toutes les tâches de ce dossier ?'))return;_tasks=[];_saveTasks();renderTasks();}

// ── Import tasks from Excel file ──
function importTasksFromExcel(input) {
  var file = input.files && input.files[0];
  if (!file) return;
  var reader = new FileReader();

  reader.onload = async function(e) {
    try {
      var data = new Uint8Array(e.target.result);
      var wb = XLSX.read(data, {type:'array'});
      var ws = wb.Sheets[wb.SheetNames[0]];
      var rows = XLSX.utils.sheet_to_json(ws, {defval:''});
      if (!rows.length) { alert('Aucune donnée trouvée dans le fichier.'); return; }

      function col(row, aliases) {
        var keys = Object.keys(row);
        for (var i=0; i<aliases.length; i++) {
          for (var j=0; j<keys.length; j++) {
            if (String(keys[j]).trim().toLowerCase() === String(aliases[i]).toLowerCase()) {
              return (row[keys[j]] + '').trim();
            }
          }
        }
        return '';
      }

      var imported = 0, skipped = 0;
      var activeRef = _taskRef();

      var existing = [];
      try {
        if (window.taskStore && typeof window.taskStore.getTasksByDossier === 'function') {
          existing = window.taskStore.getTasksByDossier(activeRef) || [];
        } else {
          existing = _loadTasks() || [];
        }
      } catch(_) {
        existing = (_tasks || []).slice();
      }

      var merged = (existing || []).map(function(t){
        var c = Object.assign({}, t);
        delete c._ref; delete c._pax; delete c._dossierId;
        return c;
      });

      rows.forEach(function(row) {
        var text = col(row, ['description','tâche','tache','task','titre','title','nom','name']);
        if (!text) { skipped++; return; }

        var cat = col(row, ['catégorie','categorie','category','cat']);
        if (!cat || TASK_CATS.indexOf(cat) === -1) cat = 'Diversos';

        var prioRaw = (col(row, ['priorité','priorite','priority','prio']) || '').toLowerCase();
        var prio = ['haute','high'].indexOf(prioRaw) >= 0 ? 'haute'
                 : ['basse','low'].indexOf(prioRaw) >= 0 ? 'basse'
                 : 'normal';

        var dueRaw = col(row, ['échéance','echeance','due','date échéance','date echeance','deadline']);
        var due = '';
        if (dueRaw) {
          var num = parseFloat(dueRaw);
          if (!isNaN(num) && num > 1000) {
            var excelEpoch = new Date(1899, 11, 30);
            var d = new Date(excelEpoch.getTime() + num * 86400000);
            if (!isNaN(d.getTime())) due = d.toISOString().slice(0,16);
          } else {
            var d2 = new Date(dueRaw);
            if (!isNaN(d2.getTime())) due = d2.toISOString().slice(0,16);
          }
        }

        var comment = col(row, ['commentaire','comment','note','notes','remarque']);
        merged.push({
          id: Date.now() + Math.random(),
          text: text,
          done: false,
          prio: prio,
          cat: cat,
          dueDate: due,
          dueDesc: '',
          comment: comment || '',
          createdAt: new Date().toISOString()
        });
        imported++;
      });

      if (!imported) {
        alert('Aucune tâche valide importée.');
        return;
      }

      // Canonical single-write path: write the full dossier taskset once.
      try {
        if (typeof _tpWriteDossierTasks === 'function') {
          _tpWriteDossierTasks(activeRef, merged);
        } else {
          localStorage.setItem('tasks_v2_' + activeRef, JSON.stringify(merged));
        }

        if (typeof window.saveData === 'function') {
          await Promise.resolve(window.saveData('taskset', String((activeRef || 'DEVIS')).trim(), merged));
        }
      } catch (saveErr) {
        console.error('importTasksFromExcel server save failed', saveErr);
        alert('Import terminé localement, mais échec de sauvegarde serveur : ' + (saveErr && saveErr.message ? saveErr.message : saveErr));
      }

      try {
        _tasks = merged.slice();
      } catch(_) {}

      try {
        if (window.taskStore && typeof window.taskStore.refreshAllTaskUIs === 'function') {
          window.taskStore.refreshAllTaskUIs();
        }
      } catch(_) {}

      try { renderTasks(); } catch(_) {}
      try { if (typeof window.welcomeRefresh === 'function') window.welcomeRefresh(); } catch(_) {}

      alert(imported + ' tâche(s) importée(s)' + (skipped ? ' — ' + skipped + ' ligne(s) ignorée(s)' : '') + '.');
    } catch(err) {
      console.error(err);
      alert('Erreur import tâches: ' + (err && err.message ? err.message : err));
    } finally {
      try { input.value = ''; } catch(_) {}
    }
  };

  reader.readAsArrayBuffer(file);
}
function renderTasks(){
  var el = document.getElementById('tasks-list');
  if(!el) return;
  if(!_tasks.length){
    el.innerHTML='<div style="font-size:0.78rem;color:var(--navy-faint);padding:0.7rem 0;">Aucune tâche pour ce dossier.</div>';
    return;
  }
  // Group by category
  var groups = {};
  TASK_CATS.forEach(function(c){ groups[c]=[]; });
  _tasks.forEach(function(t){
    var c = t.cat || 'Diversos';
    if(!groups[c]) groups[c]=[];
    groups[c].push(t);
  });
  var html = '';
  TASK_CATS.forEach(function(cat){
    var items = groups[cat];
    if(!items || !items.length) return;
    var icon = TASK_CAT_ICONS[cat]||'';
    html += '<div style="margin-bottom:0.9rem;">';
    html += '<div style="display:flex;align-items:center;gap:0.5rem;font-size:0.62rem;font-weight:700;letter-spacing:0.16em;text-transform:uppercase;color:var(--gold);margin-bottom:0.35rem;padding-bottom:0.3rem;border-bottom:1px solid var(--gold20);">'
          + icon + ' ' + cat
          + '</div>';
    items.forEach(function(t){
      var dueFmt = '';
      if (t.spDisplay) {
        dueFmt = t.spDisplay;
      } else if(t.dueDate){
        try{
          var d = new Date(t.dueDate);
          if(!isNaN(d.getTime())){
            dueFmt = d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit',year:'numeric'})
                   + ' ' + d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});
          }
        }catch(_){}
      }
      var _dueColor = 'var(--navy-faint)';
      if (t.dueDate && !t.done) {
        var _now = new Date(), _due = new Date(t.dueDate);
        var _msLeft = _due - _now;
        if (_msLeft < 0) { _dueColor = 'var(--red)'; }
        else if (_msLeft < 12 * 3600 * 1000) { _dueColor = 'var(--red)'; }
        else if (_msLeft < 24 * 3600 * 1000) { _dueColor = '#e07b00'; }
      }
      var dueHtml = dueFmt
        ? '<span style="font-size:0.62rem;color:'+_dueColor+';">⏰ '+dueFmt+'</span>'
        : '';
      var dueDesc = (t.dueDesc && !dueFmt) ? '<span style="font-size:0.62rem;color:var(--navy-faint);">'+t.dueDesc+'</span>' : '';
      var commentHtml = t.comment
        ? '<div style="margin-top:4px;font-size:0.62rem;color:var(--navy-faint);font-style:italic;white-space:pre-wrap;line-height:1.5;padding:3px 7px;background:rgba(6,32,59,0.035);border-radius:3px;border-left:2px solid rgba(216,5,5,0.25);">'
          + t.comment.replace(/</g,'&lt;') + '</div>'
        : '';
      // Attachment badge
      var taskFiles = (typeof _loadTaskFiles === 'function') ? _loadTaskFiles(t.id) : [];
      var attachBadge = taskFiles.length
        ? '<span title="'+taskFiles.length+' document(s) joint(s)" style="display:inline-flex;align-items:center;gap:2px;font-size:0.58rem;background:rgba(6,32,59,0.08);border-radius:10px;padding:1px 6px;color:var(--navy);font-weight:600;vertical-align:middle;margin-left:6px;"> '+taskFiles.length+'</span>'
        : '';
      // Annexe indicator for linked categories
      var annexeHint = (['Suriname Visa','Suriname I.C.F','QR code R.D'].indexOf(t.cat) >= 0)
        ? '<span style="font-size:0.58rem;color:var(--gold);background:var(--gold10);border-radius:10px;padding:1px 6px;margin-left:4px;font-weight:600;vertical-align:middle;"> Annexe</span>'
        : '';
      html += '<div style="display:flex;align-items:flex-start;gap:0.65rem;padding:0.55rem 0.65rem;border-bottom:1px solid var(--border);background:'+(t.done?'rgba(6,32,59,0.02)':'white')+';">'
        + '<input type="checkbox"'+(t.done?' checked':'')+' onchange="toggleTask('+t.id+')" style="width:15px;height:15px;flex-shrink:0;margin-top:2px;cursor:pointer;" onclick="event.stopPropagation();">'
        + '<div style="flex:1;min-width:0;cursor:pointer;" onclick="_taskRowClick('+t.id+')" ondblclick="_taskRowDblClick('+t.id+');event.preventDefault();">'
        + '<div style="font-size:0.82rem;color:var(--navy);'+(t.done?'text-decoration:line-through;opacity:0.45;':'font-weight:500;')+';">'
        + t.text.replace(/</g,'&lt;')
        + attachBadge + annexeHint
        + '</div>'
        + (dueHtml||dueDesc ? '<div style="margin-top:3px;display:flex;gap:0.5rem;flex-wrap:wrap;">'+dueHtml+dueDesc+'</div>' : '')
        + commentHtml
        + '</div>'
        + '<button onclick="deleteTask('+t.id+')" style="background:none;border:none;cursor:pointer;font-size:0.75rem;color:var(--navy-faint);padding:0 3px;opacity:0.5;flex-shrink:0;" title="Supprimer"></button>'
        + '</div>';
    });
    html += '</div>';
  });
  el.innerHTML = html;
}

function confirmItinerary() {
  if (typeof updateItineraryWidget === 'function') {
    updateItineraryWidget();
  }
  quotingSwitch('client');
}

/* ============================================================
   MULTI-DOSSIER TAB SYSTEM
   ============================================================ */

const _DOSSIER_FIELDS = [
  'dep1','arr1','dep2','arr2','date-leg1','date-leg2',
  'pax-adultes','pax-enfants','pax-bebes',
  'bags-qty','bags-kg','travel-class','currency',
  'price-adulte','price-enfant','price-bebe',
  'discount-value','offer-name','recap-free-line','price-note',
  'booking-ref','validity-date','pax-name-1','wa-maroc-check',
  'wa-partner-check','wa-partner-select',
  'vendeur-select','vendeur-commission','vendeur-commission-type',
  'inv-diff-check','inv-diff-amount','inv-diff-currency'
];

// Return the current trip type radio value
function _dossierGetTripType() {
  const r = document.querySelector('input[name="trip-type"]:checked');
  return r ? r.value : 'oneway';
}

function _dossierSetTripType(v) {
  const r = document.querySelector('input[name="trip-type"][value="'+v+'"]');
  if (r) { r.checked = true; if (typeof changeTripType === 'function') changeTripType(v); }
}

// Serialize multi-legs rows
function _dossierSerializeMultiLegs() {
  const rows = [];
  document.querySelectorAll('#multi-legs-list .multi-leg-row').forEach(function(row) {
    const idx = row.dataset.legIndex;
    rows.push({
      dep: (document.getElementById('ml-dep-'+idx)||{}).value || '',
      arr: (document.getElementById('ml-arr-'+idx)||{}).value || '',
      date: (document.getElementById('ml-date-'+idx)||{}).value || '',
      label: (document.getElementById('ml-label-'+idx)||{}).value || ''
    });
  });
  return rows;
}

// Serialize custom lines
function _dossierSerializeCustomLines() {
  const lines = [];
  document.querySelectorAll('[id^="custom-line-row-"]').forEach(function(row) {
    const id = row.id.replace('custom-line-row-','');
    lines.push({
      id: id,
      name: (document.getElementById('cl-name-'+id)||{}).value || '',
      cat:  (document.getElementById('cl-cat-'+id)||{}).value || '',
      qty:  (document.getElementById('cl-qty-'+id)||{}).value || '',
      price:(document.getElementById('cl-price-'+id)||{}).value || ''
    });
  });
  return lines;
}

// Serialize passenger rows
function _dossierSerializePaxRows() {
  const rows = [];
  document.querySelectorAll('[id^="pax-row-"]').forEach(function(row) {
    const idx = row.id.replace('pax-row-','');
    rows.push({
      idx: idx,
      name: (document.getElementById('pax-name-'+idx)||{}).value || '',
      dob:  (document.getElementById('pax-dob-'+idx)||{}).value || '',
      type: (document.getElementById('pax-type-'+idx)||{}).value || '',
      pass: (document.getElementById('pax-passport-'+idx)||{}).value || ''
    });
  });
  return rows;
}

function _dossierSave(id) {
  const data = { tripType: _dossierGetTripType(), fields: {}, customLines: [], multiLegs: [], paxRows: [] };
  _DOSSIER_FIELDS.forEach(function(f) {
    const el = document.getElementById(f);
    if (!el) return;
    data.fields[f] = el.type === 'checkbox' ? el.checked : el.value;
  });
  data.customLines = _dossierSerializeCustomLines();
  data.multiLegs   = _dossierSerializeMultiLegs();
  data.paxRows     = _dossierSerializePaxRows();
  // label for display in tab
  data._label = (document.getElementById('booking-ref')||{}).value
             || (document.getElementById('pax-name-1')||{}).value
             || 'Nouveau dossier';
  try { localStorage.setItem('expatur_dossier_'+id, JSON.stringify(data)); } catch(e){}
}

function _dossierLoad(id) {
  let data;
  try { data = JSON.parse(localStorage.getItem('expatur_dossier_'+id)||'null'); } catch(e){}
  if (!data) return;
  _dossierResetUI();
  if (data.tripType) _dossierSetTripType(data.tripType);
  _DOSSIER_FIELDS.forEach(function(f) {
    if (!(f in data.fields)) return;
    const el = document.getElementById(f);
    if (!el) return;
    if (el.type === 'checkbox') el.checked = !!data.fields[f];
    else el.value = data.fields[f];
  });
  // Restore custom invoice value toggle visibility
  if (typeof _onInvDiffToggle === 'function') _onInvDiffToggle();
  // Restore passport thumbnail for this dossier
  if (typeof _cliLoadPassportThumb === 'function') setTimeout(_cliLoadPassportThumb, 0);
  // Restore custom lines
  if (data.customLines && data.customLines.length) {
    data.customLines.forEach(function(cl) {
      if (typeof addCustomLine === 'function') addCustomLine();
      // get last added row id
      const rows = document.querySelectorAll('[id^="custom-line-row-"]');
      if (!rows.length) return;
      const lastRow = rows[rows.length-1];
      const lid = lastRow.id.replace('custom-line-row-','');
      if (document.getElementById('cl-name-'+lid))  document.getElementById('cl-name-'+lid).value  = cl.name;
      if (document.getElementById('cl-cat-'+lid))   document.getElementById('cl-cat-'+lid).value   = cl.cat;
      if (document.getElementById('cl-qty-'+lid))   document.getElementById('cl-qty-'+lid).value   = cl.qty;
      if (document.getElementById('cl-price-'+lid)) document.getElementById('cl-price-'+lid).value = cl.price;
    });
  }
  // Trigger recalc if available
  if (typeof updateRecap === 'function') updateRecap();
  if (typeof updateDevis === 'function') updateDevis();
  // Update dossier info strip
  setTimeout(function(){ if (typeof updateDossierInfoStrip === 'function') updateDossierInfoStrip(); }, 0);
  // Apply booking tab lock/unlock state for this dossier
  setTimeout(function(){ if (typeof _applyBookingTabState === 'function') _applyBookingTabState(); }, 0);
}

function _generatePurchaseNumber() {
  var now = new Date();
  var year  = now.getFullYear().toString().slice(-2);
  var month = String(now.getMonth() + 1).padStart(2, '0');
  var randomNum = String(Math.floor(Math.random() * 9999) + 1).padStart(4, '0');
  return year + month + randomNum;
}

function _dossierResetUI() {
  // Reset all tracked fields
  _DOSSIER_FIELDS.forEach(function(f) {
    const el = document.getElementById(f);
    if (!el) return;
    if (el.type === 'checkbox') el.checked = false;
    else el.value = '';
  });
  // Remove custom lines
  document.querySelectorAll('[id^="custom-line-row-"]').forEach(function(r){ r.remove(); });
  //  Restore tarification defaults 
  var _setVal = function(id, val) {
    var el = document.getElementById(id);
    if (el) el.value = val;
  };
  _setVal('pax-adultes',  '1');
  _setVal('pax-enfants',  '0');
  _setVal('pax-bebes',    '0');
  _setVal('travel-class', 'Economy');
  _setVal('currency',     '€');
  _setVal('bags-qty',     '1');
  _setVal('bags-kg',      '23');
  // validity-date = today + 1
  var _tmrw = new Date(); _tmrw.setDate(_tmrw.getDate() + 1);
  _setVal('validity-date', _tmrw.toISOString().slice(0, 10));
  // auto-generate purchase number
  _setVal('booking-ref', _generatePurchaseNumber());
  // keep pax price boxes in sync
  if (typeof syncPaxPriceBoxes === 'function') syncPaxPriceBoxes();
  // update info strip
  setTimeout(function(){ if (typeof updateDossierInfoStrip === 'function') updateDossierInfoStrip(); }, 0);
}

// ── Ticketing Session helpers ────────────────────────────────────────────────
function _tsComputeStatus(id) {
  if (localStorage.getItem('expatur_booked_' + id) === '1') return 'closed';
  var data;
  try { data = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null'); } catch(e) {}
  if (!data) return 'draft';
  var f = data.fields || {};
  var hasName   = !!(f['pax-name-1'] || '').trim() || !!(f['cli-nom'] || '').trim() || (data.paxRows && data.paxRows.some(function(r){ return (r.name||'').trim(); }));
  var hasDep    = !!(f['dep1'] || '').trim();
  var hasArr    = !!(f['arr1'] || '').trim();
  var hasDate   = !!(f['date-leg1'] || '').trim();
  var hasPrice  = parseFloat(f['price-adulte']) > 0;
  if (hasName && hasDep && hasArr && hasDate && hasPrice) return 'ready';
  if (hasName || hasDep || hasArr || hasDate || hasPrice) return 'incomplete';
  return 'draft';
}

function _tsGetSmartLabel(data) {
  if (!data) return 'Nouveau ticket';
  var f = data.fields || {};
  var cliNom   = (f['cli-nom']   || '').trim();
  var paxName  = (f['pax-name-1']|| '').trim();
  var nameRaw  = cliNom || paxName;
  var nameLabel = nameRaw ? nameRaw.split(' ').pop().toUpperCase() : '';
  var arr = (f['arr1'] || '').trim().toUpperCase();
  if (!arr && data.multiLegs && data.multiLegs.length) {
    arr = (data.multiLegs[data.multiLegs.length-1].arr || '').trim().toUpperCase();
  }
  if (nameLabel && arr)  return nameLabel + '\u2013' + arr;
  if (nameLabel)         return nameLabel;
  if (arr)               return 'Vol\u2013' + arr;
  var ref = (f['booking-ref'] || '').trim() || (data._label || '').trim();
  return ref || 'Nouveau ticket';
}

// _dossierAutoSave removed (caused white-screen lag)
// ────────────────────────────────────────────────────────────────────────────

function _dossierRenderTabs() {
  let list;
  try { list = JSON.parse(localStorage.getItem('expatur_dossier_list')||'[]'); } catch(e){ list=[]; }
  const activeId = localStorage.getItem('expatur_active_dossier');
  const container = document.getElementById('dossier-tabs-list');
  if (!container) return;
  container.innerHTML = '';
  list.forEach(function(d) {
    const isActive = d.id === activeId;
    let labelData;
    try { labelData = JSON.parse(localStorage.getItem('expatur_dossier_'+d.id)||'null'); } catch(e){}
    const status = _tsComputeStatus(d.id);
    const label  = _tsGetSmartLabel(labelData);
    const statusTitles = { draft:'Brouillon', incomplete:'Incomplet', ready:'Prêt', closed:'Émis' };
    const statusTitle  = statusTitles[status] || status;
    const tab = document.createElement('div');
    tab.className = 'dossier-tab' + (isActive ? ' active' : '');
    tab.dataset.dossierId = d.id;
    tab.dataset.status = status;
    tab.title = statusTitle;
    tab.innerHTML = '<span class="d-status ' + status + '" title="' + statusTitle + '"></span>'
      + '<span class="d-ref" style="overflow:hidden;text-overflow:ellipsis;max-width:160px;">' + label + '</span>'
      + '<button class="d-close" onclick="_dossierClose(\''+d.id+'\',event)" title="Fermer">\u00d7</button>';
    tab.addEventListener('click', function(e) {
      if (e.target.classList.contains('d-close')) return;
      switchDossier(d.id);
      if (typeof closeDevisIndex === 'function') closeDevisIndex();
    });
    container.appendChild(tab);
  });
}

function switchDossier(id) {
  const activeId = localStorage.getItem('expatur_active_dossier');
  if (activeId && activeId !== id) {
    _dossierSave(activeId);
  }
  localStorage.setItem('expatur_active_dossier', id);
  _dossierLoad(id);
  _dossierRenderTabs();
  // Navigate to ticketing section when switching sessions
  if (typeof sidebarGo === 'function') sidebarGo('quoting');
}

function createNewDossier(prefill) {
  const id = 'dos_' + Date.now();
  let list;
  try { list = JSON.parse(localStorage.getItem('expatur_dossier_list')||'[]'); } catch(e){ list=[]; }
  // Always auto-generate a purchase number unless caller provides one
  const autoRef = (prefill && prefill.ref) ? prefill.ref : _generatePurchaseNumber();
  const label = autoRef;
  list.push({ id: id, label: label });
  try { localStorage.setItem('expatur_dossier_list', JSON.stringify(list)); } catch(e){}
  // Save empty state with the auto-ref pre-filled
  const emptyData = { tripType:'oneway', fields:{'booking-ref': autoRef}, customLines:[], multiLegs:[], paxRows:[], _label: label };
  if (prefill) {
    if (prefill.client) emptyData.fields['pax-name-1'] = prefill.client;
  }
  try { localStorage.setItem('expatur_dossier_'+id, JSON.stringify(emptyData)); } catch(e){}
  // Save current dossier before switching
  const activeId = localStorage.getItem('expatur_active_dossier');
  if (activeId) _dossierSave(activeId);
  localStorage.setItem('expatur_active_dossier', id);
  _dossierResetUI();
  // Set hidden booking-ref field
  var brEl = document.getElementById('booking-ref');
  if (brEl) brEl.value = autoRef;
  if (prefill && prefill.client && document.getElementById('pax-name-1'))
    document.getElementById('pax-name-1').value = prefill.client;
  _dossierRenderTabs();
  // Update dossier info strip
  if (typeof updateDossierInfoStrip === 'function') updateDossierInfoStrip();
  // New dossier is never booked — enforce locked tabs
  setTimeout(function(){ if (typeof _applyBookingTabState === 'function') _applyBookingTabState(); }, 0);
}

function _dossierIsEmpty(data) {
  if (!data) return true;
  var f = data.fields || {};
  var hasName  = !!(f['pax-name-1']||'').trim();
  var hasDep   = !!(f['dep1']||'').trim();
  var hasPrice = !!(f['price-adulte']||'').trim();
  var hasPax   = data.paxRows && data.paxRows.some(function(r){ return (r.name||'').trim(); });
  var hasLegs  = data.multiLegs && data.multiLegs.some(function(l){ return (l.dep||'').trim(); });
  var hasLabel = data._label && data._label !== 'Nouveau dossier';
  return !hasName && !hasDep && !hasPrice && !hasPax && !hasLegs && !hasLabel;
}

function _dossierClose(id, event) {
  if (event) event.stopPropagation();
  // Save active dossier first if different
  const activeId = localStorage.getItem('expatur_active_dossier');
  if (activeId && activeId === id) { try { _dossierSave(id); } catch(e){} }

  // Check if the dossier is effectively empty — if so, delete silently
  let data;
  try { data = JSON.parse(localStorage.getItem('expatur_dossier_'+id)||'null'); } catch(e){}
  const isEmpty = _dossierIsEmpty(data);
  const ref = (data && data.fields && data.fields['booking-ref']) || (data && data._label) || '';
  if (!isEmpty) {
    // Use inline confirm via tab data-attribute to avoid blocked native confirm()
    var tab = document.querySelector('.dossier-tab[data-dossier-id="'+id+'"]');
    if (!tab) tab = document.querySelector('[data-dossier-id="'+id+'"]');
    if (tab && !tab.dataset.closeConfirmed) {
      tab.dataset.closeConfirmed = '1';
      var refLabel = ref || id;
      if (typeof toast === 'function') toast('Cliquez à nouveau sur × pour fermer « '+refLabel+' »', 'error');
      setTimeout(function(){ if(tab) delete tab.dataset.closeConfirmed; }, 4000);
      return;
    }
    if (tab) delete tab.dataset.closeConfirmed;
  }

  let list;
  try { list = JSON.parse(localStorage.getItem('expatur_dossier_list')||'[]'); } catch(e){ list=[]; }
  list = list.filter(function(d){ return d.id !== id; });
  try { localStorage.setItem('expatur_dossier_list', JSON.stringify(list)); } catch(e){}
  // Only wipe localStorage entry if empty
  if (isEmpty) { try { localStorage.removeItem('expatur_dossier_'+id); } catch(e){} }

  if (activeId === id) {
    if (list.length) {
      localStorage.setItem('expatur_active_dossier', list[list.length-1].id);
      _dossierLoad(list[list.length-1].id);
    } else {
      localStorage.removeItem('expatur_active_dossier');
      _dossierResetUI();
      createNewDossier();
      return;
    }
  }
  _dossierRenderTabs();
}

// Auto-update tab label when booking-ref or pax-name-1 changes
(function() {
  function _autoUpdateLabel() {
    const activeId = localStorage.getItem('expatur_active_dossier');
    if (!activeId) return;
    const ref  = (document.getElementById('booking-ref')||{}).value || '';
    const name = (document.getElementById('pax-name-1')||{}).value || '';
    const newLabel = ref || name || 'Nouveau dossier';
    try {
      const data = JSON.parse(localStorage.getItem('expatur_dossier_'+activeId)||'{}');
      data._label = newLabel;
      localStorage.setItem('expatur_dossier_'+activeId, JSON.stringify(data));
    } catch(e){}
    // Re-render all tabs to get fresh smart label + status
    _dossierRenderTabs();
  }
  document.addEventListener('DOMContentLoaded', function() {
    // Auto-label + auto-save hooks on key label fields
    ['booking-ref','pax-name-1','dep1','arr1','cli-nom','cli-prenom','date-leg1','price-adulte'].forEach(function(fid) {
      const el = document.getElementById(fid);
      if (el) {
        el.addEventListener('input', _autoUpdateLabel);

      }
    });
    // Auto-save on all other tracked fields (status may change)
    var _autoSaveFields = ['pax-enfants','pax-bebes','price-enfant','price-bebe',
      'discount-value','offer-name','recap-free-line','price-note',
      'validity-date','wa-maroc-check','wa-partner-check','wa-partner-select',
      'vendeur-select','vendeur-commission','vendeur-commission-type',
      'travel-class','currency','bags-qty','bags-kg',
      'inv-diff-check','inv-diff-amount','inv-diff-currency'];
    _autoSaveFields.forEach(function(fid) {
      var el = document.getElementById(fid);
      if (el) {

      }
    });
  });
})();

// URL param integration: ?ref=XXX&client=NAME
(function() {
  document.addEventListener('DOMContentLoaded', function() {
    const params = new URLSearchParams(window.location.search);
    const ref    = params.get('ref')    || '';
    const client = params.get('client') || '';
    if (!ref && !client) return;
    // Check if a dossier with this ref already exists
    let list;
    try { list = JSON.parse(localStorage.getItem('expatur_dossier_list')||'[]'); } catch(e){ list=[]; }
    let existing = null;
    for (var i=0; i<list.length; i++) {
      try {
        var d = JSON.parse(localStorage.getItem('expatur_dossier_'+list[i].id)||'null');
        if (d && d.fields && d.fields['booking-ref'] === ref) { existing = list[i].id; break; }
      } catch(e){}
    }
    if (existing) {
      switchDossier(existing);
    } else {
      createNewDossier({ ref: ref, client: client });
    }
  });
})();

// Init: restore dossiers from localStorage on page load
(function() {
  document.addEventListener('DOMContentLoaded', function() {
    let list;
    try { list = JSON.parse(localStorage.getItem('expatur_dossier_list')||'[]'); } catch(e){ list=[]; }
    const activeId = localStorage.getItem('expatur_active_dossier');
    // If no dossiers at all, create the first one
    if (!list.length) {
      createNewDossier();
      return;
    }
    // Render tabs
    _dossierRenderTabs();
    // Load active dossier
    const toLoad = (activeId && list.find(function(d){ return d.id===activeId; }))
      ? activeId : list[list.length-1].id;
    localStorage.setItem('expatur_active_dossier', toLoad);
    _dossierLoad(toLoad);
    _dossierRenderTabs();
  });
})();

// 
// ÉMETTRE — Ticket emission + automatic task generation
// 

//  Validation: are all billet passenger fields filled? 
function _blCheckFilled() {
  var body = document.getElementById('bl-body');
  if (!body) return false;
  var nPax = parseInt(body.dataset.paxCount) || 0;
  if (nPax === 0) return false;
  for (var pi = 0; pi < nPax; pi++) {
    var nom    = (document.getElementById('bl-pax-' + pi + '-nom')    || {}).value || '';
    var prenom = (document.getElementById('bl-pax-' + pi + '-prenom') || {}).value || '';
    var dob    = (document.getElementById('bl-pax-' + pi + '-dob')    || {}).value || '';
    if (!nom.trim() || !prenom.trim() || !dob.trim()) return false;
  }
  return true;
}

// Called from billet body inputs to keep Émettre btn in sync
function _blUpdateEmettreBtn() {
  var btn = document.getElementById('bl-emettre-btn');
  if (!btn) return;
  var ok = _blCheckFilled();
  btn.disabled = !ok;
  btn.style.opacity    = ok ? '1'             : '0.4';
  btn.style.cursor     = ok ? 'pointer'        : 'not-allowed';
}

// Hook _blUpdateEmettreBtn onto billet body input events
document.addEventListener('DOMContentLoaded', function () {
  var body = document.getElementById('bl-body');
  if (body) {
    body.addEventListener('input',  _blUpdateEmettreBtn);
    body.addEventListener('change', _blUpdateEmettreBtn);
  }
});

// Intercept Émettre button — show confirm modal before emission
(function _wireEmettreConfirm() {
  function _setup() {
    var btn = document.getElementById('bl-emettre-btn');
    if (!btn || btn._confirmWired) return;
    btn._confirmWired = true;
    btn.removeAttribute('onclick');
    btn.addEventListener('click', function () {
      if (typeof window.xpConfirm !== 'function') {
        if (window.confirm('Confirmer l\'émission des billets ?')) window.emettreBillet();
        return;
      }
      window.xpConfirm(
        'Confirmer l\'émission des billets pour ce dossier ?<small>Cette action ne peut pas être annulée.</small>',
        { title: 'Émettre les billets', icon: '✈', okLabel: 'Émettre →', type: 'danger' }
      ).then(function (confirmed) {
        if (!confirmed) return;
        if (typeof window.emettreBillet !== 'function') return;
        try {
          window.emettreBillet();
        } catch (e) {
          console.error('[Expatur] emettreBillet threw:', e);
          toast('Erreur lors de l\'émission : ' + (e && e.message ? e.message : String(e)), 'error');
        }
      }).catch(function(e) {
        console.error('[Expatur] xpConfirm rejected:', e);
      });
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _setup);
  } else {
    _setup();
  }
})();

//  Airline code extraction 
function _extractAirlineCodes(fn) {
  // fn looks like "AF 1234" or "G3 8811" or "AF 123 + KL 456"
  var codes = [];
  if (!fn) return codes;
  fn.split('+').forEach(function (part) {
    var code = part.trim().split(/\s+/)[0];
    if (code) codes.push(code.toUpperCase());
  });
  return codes;
}

//  Collect all itinerary legs 
function _blGetAllLegs() {
  var legs = [];
  function pushLeg(sel, dateInput, depInput, arrInput) {
    var depCode = ((sel && sel.depCode) || (document.getElementById(depInput) || {}).value || '').toUpperCase();
    var arrCode = ((sel && sel.arrCode) || (document.getElementById(arrInput) || {}).value || '').toUpperCase();
    var depDate = (sel && sel.depDate)  || (document.getElementById(dateInput) || {}).value || '';
    var depTime = (sel && sel.depTime)  || '';
    var fn      = (sel && sel.fn)       || '';
    var aCodes  = _extractAirlineCodes(fn);
    // Also check segment-level airlines for more precise detection
    if (sel && sel.segments && sel.segments.length) {
      sel.segments.forEach(function (s) {
        var c = _extractAirlineCodes(s.fn);
        c.forEach(function (x) { if (aCodes.indexOf(x) < 0) aCodes.push(x); });
      });
    }
    var legSegs = (sel && sel.segments && sel.segments.length) ? sel.segments : [];
    if (depCode || arrCode) {
      legs.push({ depCode: depCode, arrCode: arrCode, depDate: depDate, depTime: depTime, fn: fn, airlineCodes: aCodes, segments: legSegs, arrTime: (sel && sel.arrTime) || '' });
    }
  }

  if (tripType === 'oneway' || tripType === 'return') {
    pushLeg(selLeg1, 'date-leg1', 'dep1', 'arr1');
    if (tripType === 'return') pushLeg(selLeg2, 'date-leg2', 'dep2', 'arr2');
  } else if (tripType === 'multicity') {
    // First leg uses fixed fields
    pushLeg(selLeg1, 'date-leg1', 'dep1', 'arr1');
    multiLegs.forEach(function (ml) {
      if (ml.sel) {
        var fn     = ml.sel.fn || '';
        var aCodes = _extractAirlineCodes(fn);
        if (ml.sel.segments && ml.sel.segments.length) {
          ml.sel.segments.forEach(function (s) {
            var c = _extractAirlineCodes(s.fn);
            c.forEach(function (x) { if (aCodes.indexOf(x) < 0) aCodes.push(x); });
          });
        }
        legs.push({
          depCode: (ml.sel.depCode || ml.dep || '').toUpperCase(),
          arrCode: (ml.sel.arrCode || ml.arr || '').toUpperCase(),
          depDate: ml.sel.depDate || ml.date || '',
          depTime: ml.sel.depTime || '',
          fn:      fn,
          airlineCodes: aCodes,
          segments: (ml.sel.segments && ml.sel.segments.length) ? ml.sel.segments : [],
          arrTime: ml.sel.arrTime || ''
        });
      }
    });
  }
  return legs;
}

