/* ───────────────────────────────────────────────────────────────
   LIVE CITY CLOCKS — data-clock-tz attribute on any element
   ─────────────────────────────────────────────────────────────── */
(function() {
  function _updateAllClocks() {
    var now = new Date();
    document.querySelectorAll('[data-clock-tz]').forEach(function(el) {
      try {
        el.textContent = new Intl.DateTimeFormat('fr-FR', {
          timeZone: el.getAttribute('data-clock-tz'),
          hour: '2-digit', minute: '2-digit', hour12: false
        }).format(now);
      } catch(e) {}
    });
    // Date display — all .page-full-date elements
    var days = ['Dimanche','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'];
    var months = ['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'];
    var dateStr = days[now.getDay()] + ' ' + now.getDate() + ' ' + months[now.getMonth()] + ' ' + now.getFullYear();
    document.querySelectorAll('.page-full-date').forEach(function(el) {
      el.textContent = dateStr;
    });
  }
  _updateAllClocks();
  setInterval(_updateAllClocks, 1000);
})();

