/* ═══════════════════════════════════════════════════════════════════════
   SERVER STORAGE BRIDGE — Fornecedores / Clientes / Tarefas
   Replaces legacy localStorage persistence with backend-backed shadow keys.
   Keeps synchronous localStorage semantics for the app, but hydrates from
   /finance/api.php and persists changes back to the server.
   ═══════════════════════════════════════════════════════════════════════ */
/* SERVER STORAGE BRIDGE (fornecedores/clientes/tarefas) — REMOVIDO (backend
   PHP extinto). Persistência agora: localStorage nativo + Supabase (storage.js). */

// ─────────────────────────────────────

/* ==========================================================================
   FULL SERVER-NATIVE BRIDGE v1
   Routes business data to /finance/api.php with zero persistent localStorage.
   Covers: vendeurs, fornecedores, clients, tasks, bookings, ticketing,
   finance/disponibilites, welcome dashboard hydration.
   ========================================================================== */
/* FULL SERVER-NATIVE BRIDGE v1 — REMOVIDO (backend PHP extinto).
   Substituía o localStorage por store em memória + /finance/api.php.
   Persistência agora: localStorage nativo + Supabase (src/js/storage.js). */

// ─────────────────────────────────────

(function(){
  /* FX display now handled by fx-pricing-serpapi-patch (BRL-centric).
     FX_PAIRS emptied to prevent legacy cross-rate chips from conflicting. */
  const FX_PAIRS = [];
  let __fxFetchPromise = null;
  let __fxLastLoadedAt = 0;

  function __findClockHeaderGroups(){
    return Array.from(document.querySelectorAll('.section-page-header > div')).filter(function(el){
      return el.querySelector && el.querySelector('[data-clock-tz]');
    });
  }

  function __ensureHeaderEnhancements(){
    __findClockHeaderGroups().forEach(function(group, idx){
      if (!group.querySelector('.header-fx-strip')) {
        const strip = document.createElement('div');
        strip.className = 'header-fx-strip';
        strip.innerHTML = FX_PAIRS.map(function(pair){
          const key = pair[0] + '/' + pair[1];
          return '<div class="header-fx-item loading" data-fx-key="' + key + '"><div class="fx-pair">' + key + '</div><div class="fx-val">…</div></div>';
        }).join('');
        group.appendChild(strip);
      }
      if (!group.querySelector('.header-admin-btn')) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'header-admin-btn';
        btn.textContent = 'Admin Users';
        btn.addEventListener('click', function(){
          if (typeof window.__openAdminPanel === 'function') window.__openAdminPanel();
        });
        group.appendChild(btn);
      }
    });
    __refreshHeaderAdminButtons();
  }

  function __refreshHeaderAdminButtons(){
    const isAdmin = !!(window.__serverSession && window.__serverSession.isAdmin);
    document.querySelectorAll('.header-admin-btn').forEach(function(btn){
      btn.style.display = isAdmin ? 'inline-flex' : 'none';
    });
    const fab = document.getElementById('admin-fab');
    if (fab) fab.style.display = isAdmin ? 'inline-flex' : 'none';
  }

  function __parseFxRateFromSerpApi(data){
    const candidates = [];
    const ab = data && data.answer_box ? data.answer_box : null;
    if (ab) {
      [ab.answer, ab.result, ab.snippet, ab.currency, ab.price, ab.value, ab.title].forEach(function(v){ if (typeof v === 'string') candidates.push(v); });
      if (ab.conversions && Array.isArray(ab.conversions)) {
        ab.conversions.forEach(function(c){ ['price','value','currency'].forEach(function(k){ if (typeof c[k] === 'string') candidates.push(c[k]); }); });
      }
      if (ab.list && Array.isArray(ab.list)) {
        ab.list.forEach(function(item){ if (item && typeof item.answer === 'string') candidates.push(item.answer); });
      }
    }
    const kg = data && data.knowledge_graph ? data.knowledge_graph : null;
    if (kg) [kg.description, kg.title].forEach(function(v){ if (typeof v === 'string') candidates.push(v); });
    const answer = candidates.join(' | ');
    const m = answer.replace(/,/g,'').match(/(?:^|\s)(\d+(?:\.\d+)?)(?:\s|$)/);
    return m ? Number(m[1]) : null;
  }

  async function __serpApiGoogleQuery(query){
    const params = new URLSearchParams({ engine:'google', q:query, google_domain:'google.com', hl:'en', gl:'us', no_cache:'true' });
    try {
      if (typeof SERP_PROXY_URL === 'string' && SERP_PROXY_URL) {
        const r = await fetch(SERP_PROXY_URL + '?' + params.toString(), { credentials:'omit' });
        const t = await r.text();
        const data = JSON.parse(t);
        if (r.ok) return data;
      }
    } catch (e) {}
    if (typeof SERP_API_KEY !== 'string' || !SERP_API_KEY) throw new Error('Missing SerpApi key');
    params.set('api_key', SERP_API_KEY);
    params.set('output', 'json');
    const r2 = await fetch('https://serpapi.com/search.json?' + params.toString(), { credentials:'omit' });
    if (!r2.ok) throw new Error('SerpApi ' + r2.status);
    return r2.json();
  }

  async function __loadFxRatesFromSerpApi(force){
    const now = Date.now();
    if (!force && __fxFetchPromise) return __fxFetchPromise;
    if (!force && __fxLastLoadedAt && now - __fxLastLoadedAt < 240000) return;
    __fxFetchPromise = (async function(){
      __ensureHeaderEnhancements();
      document.querySelectorAll('.header-fx-item').forEach(function(el){ el.classList.add('loading'); });
      const results = {};
      await Promise.all(FX_PAIRS.map(async function(pair){
        const key = pair[0] + '/' + pair[1];
        try {
          const data = await __serpApiGoogleQuery('1 ' + pair[0] + ' to ' + pair[1]);
          const rate = __parseFxRateFromSerpApi(data);
          if (typeof rate === 'number' && isFinite(rate)) results[key] = rate;
          else throw new Error('No rate parsed');
        } catch (e) {
          results[key] = null;
          console.error('FX load failed for', key, e);
        }
      }));
      document.querySelectorAll('.header-fx-item').forEach(function(el){
        const key = el.getAttribute('data-fx-key');
        const valEl = el.querySelector('.fx-val');
        el.classList.remove('loading','error');
        if (results[key] == null) {
          el.classList.add('error');
          if (valEl) valEl.textContent = 'ERR';
        } else {
          if (valEl) valEl.textContent = Number(results[key]).toFixed(2);
        }
      });
      __fxLastLoadedAt = Date.now();
    })().finally(function(){ __fxFetchPromise = null; });
    return __fxFetchPromise;
  }

  const __origUpdateAdminVisibility = (typeof window._updateAdminVisibility === 'function') ? window._updateAdminVisibility : null;
  window._updateAdminVisibility = function(){
    if (__origUpdateAdminVisibility) {
      try { __origUpdateAdminVisibility(); } catch(e) {}
    }
    __refreshHeaderAdminButtons();
  };

  const __origOpenAdminPanel = (typeof window.__openAdminPanel === 'function') ? window.__openAdminPanel : null;
  window.__openAdminPanel = function(){
    if (__origOpenAdminPanel) return __origOpenAdminPanel();
  };

  window.addEventListener('load', function(){
    __ensureHeaderEnhancements();
    __loadFxRatesFromSerpApi(true);
  });
  document.addEventListener('DOMContentLoaded', __ensureHeaderEnhancements);
  setInterval(function(){ __loadFxRatesFromSerpApi(false); }, 300000);
})();

