  /* ══════════════════════════════════════════════════════════════
     § 6. OVERRIDE window.dossFinRenderPanel
     ══════════════════════════════════════════════════════════════ */

  var _v36_origPanel = window.dossFinRenderPanel;

  window.dossFinRenderPanel = function() {
    var id = localStorage.getItem('expatur_active_dossier');
    if (!id) { if (_v36_origPanel) _v36_origPanel.call(this); return; }

    var activeBtn = document.querySelector('.doss-fin-tab.active');
    var tab = activeBtn ? activeBtn.dataset.dftab : null;

    if (tab === 'overview' || tab === 'receivables' || tab === 'expenses') {
      var data = _v36DossLoad(id);
      if (!data) { if (_v36_origPanel) _v36_origPanel.call(this); return; }
      if (tab === 'overview')    { _v36RenderOverview(id, data);    return; }
      if (tab === 'receivables') { _v36RenderReceivables(id, data); return; }
      if (tab === 'expenses')    { _v36RenderExpenses(id, data);    return; }
    }

    if (_v36_origPanel) _v36_origPanel.call(this);
  };

