(function() {
  'use strict';
  if (window._v37LayoutPatch) return;
  window._v37LayoutPatch = true;

  /* ══════════════════════════════════════════════════════════════
     § 1. DOSSIER WORKSPACE SHOW / HIDE
          The .app-shell contains the dossier workspace.
          It must be hidden when any section-page is active.
     ══════════════════════════════════════════════════════════════ */

  function _v37GetShell() {
    return document.querySelector('.app-shell');
  }

  /** Hide the dossier workspace (app-shell). Call when a section-page opens. */
  function _v37HideDossier() {
    var s = _v37GetShell();
    if (s) s.style.display = 'none';
  }

  /** Show the dossier workspace (app-shell). Hide all section-pages first. */
  function _v37ShowDossier() {
    // Hide all section-pages
    (window.SECTION_IDS || []).forEach(function(id) {
      var p = document.getElementById('section-' + id);
      if (p) p.classList.remove('open');
    });
    // Show workspace
    var s = _v37GetShell();
    if (s) s.style.display = '';
    // Update sidebar nav: no section active
    document.querySelectorAll('.sidebar-item').forEach(function(b) {
      b.classList.remove('active');
    });
  }

  // Expose globally so other code (e.g. dossier openers) can call it
  window._v37ShowDossierWorkspace = _v37ShowDossier;
  window._v37HideDossierWorkspace = _v37HideDossier;

  /* ══════════════════════════════════════════════════════════════
     § 2. OVERRIDE sidebarGo — add workspace toggle
          Called AFTER the original to sync visibility.
     ══════════════════════════════════════════════════════════════ */

  var _v37_origSidebarGo = window.sidebarGo;

  window.sidebarGo = function(section) {
    // Call original (handles fin gate, nav state, section refresh)
    if (_v37_origSidebarGo) _v37_origSidebarGo.call(this, section);

    // 'index' = show dossier workspace, hide sections
    if (section === 'index') {
      _v37ShowDossier();
      return;
    }

    // For all other sections: check if the target section actually opened
    // (fin gate may have blocked navigation and returned early)
    var target = document.getElementById('section-' + section);
    if (target && target.classList.contains('open')) {
      _v37HideDossier();
    }
    // If section didn't open (fin gate blocked), leave workspace as-is
  };

  /* ══════════════════════════════════════════════════════════════
     § 3. OVERRIDE dossier-workspace entry points
          Any path that should reveal the dossier workspace must
          call _v37ShowDossier().
     ══════════════════════════════════════════════════════════════ */

  // openDevisIndex — shows the dossier list (inside app-shell)
  var _v37_origOpenDevisIndex = window.openDevisIndex;
  window.openDevisIndex = function() {
    _v37ShowDossier();
    if (_v37_origOpenDevisIndex) _v37_origOpenDevisIndex.apply(this, arguments);
  };

  // createNewDossier — creates a dossier and opens the workspace
  var _v37_origCreateNew = window.createNewDossier;
  window.createNewDossier = function() {
    _v37ShowDossier();
    if (_v37_origCreateNew) _v37_origCreateNew.apply(this, arguments);
  };

  /* ══════════════════════════════════════════════════════════════
     § 4. INITIAL STATE — hide app-shell on load
          Welcome section is shown by DOMContentLoaded → app-shell hidden.
          If the dossier workspace was the last active view (rare),
          we still default to the welcome section.
     ══════════════════════════════════════════════════════════════ */

  // Run as soon as DOM is ready (DOMContentLoaded may have already fired)
  function _v37Init() {
    // If any section-page is already open, hide the app-shell
    var anyOpen = (window.SECTION_IDS || []).some(function(id) {
      var p = document.getElementById('section-' + id);
      return p && p.classList.contains('open');
    });
    if (anyOpen) {
      _v37HideDossier();
    } else {
      // If no section is active, hide app-shell by default
      // (sidebarGo('welcome') will be called shortly and will open the welcome section)
      _v37HideDossier();
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _v37Init);
  } else {
    _v37Init();
  }

  /* ══════════════════════════════════════════════════════════════
     § 5. SIDEBAR SCROLL-TO-TOP on section switch
          When switching between sections, scroll the section-page
          to the top so stale scroll position is not preserved.
     ══════════════════════════════════════════════════════════════ */

  var _v37_origSidebarGo2 = window.sidebarGo; // capture the already-overridden version
  window.sidebarGo = function(section) {
    _v37_origSidebarGo2.call(this, section);
    // Scroll the newly-opened section to the top
    var target = document.getElementById('section-' + section);
    if (target && target.classList.contains('open')) {
      target.scrollTop = 0;
    }
  };

  console.log('[Patch v3.7] Layout — app-shell/section-page toggle + scroll-to-top');

})(); // end Layout Patch v3.7

// ─────────────────────────────────────

(function() {
  'use strict';
  if (window._v38FinPatch) return;
  window._v38FinPatch = true;

  /* ══════════════════════════════════════════════════════════════
     § 1. PRIVATE HELPERS
     ══════════════════════════════════════════════════════════════ */

  var _FIN_KEY_38 = 'expatur_financeiro_lancamentos';

  function _finLoad38() {
    try { return JSON.parse(localStorage.getItem(_FIN_KEY_38) || '[]'); } catch(e) { return []; }
  }

  function _brl38(r) {
    if (!r) return 0;
    if (r.brl_amount != null && r.brl_amount !== '') return parseFloat(r.brl_amount) || 0;
    if (window.convertToBRL && window.normalizeCurrencyCode) {
      var iso  = window.normalizeCurrencyCode(r.original_currency || r.moeda || r.currency || 'BRL');
      var rate = parseFloat(r.fx_rate_to_brl) || 1;
      var raw  = parseFloat(r.original_amount || r.valor || r.amount || 0) || 0;
      return window.convertToBRL(raw, iso, rate);
    }
    return parseFloat(r.amount || r.valor || 0) || 0;
  }

  function _fmtBRL38(v) {
    return 'R$\u00a0' + (parseFloat(v) || 0).toLocaleString('pt-BR', {
      minimumFractionDigits: 2, maximumFractionDigits: 2
    });
  }

  function _esc38(s) {
    return (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function _today38() { return new Date().toISOString().slice(0, 10); }

  function _dateLabel38(d) {
    if (!d) return '\u2014';
    var p = d.split('-');
    if (p.length < 3) return d;
    return p[2] + '/' + p[1] + '/' + p[0];
  }

  function _dossRef38(id) {
    var dd; try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null'); } catch(e) {}
    return (dd && dd.fields && dd.fields['booking-ref']) || id;
  }

  function _getDossierIds38() {
    var list; try { list = JSON.parse(localStorage.getItem('expatur_dossier_list') || '[]'); } catch(e) { list = []; }
    return list.map(function(d) { return d.id; });
  }

  function _dossClient38(id) {
    var dd; try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null'); } catch(e) {}
    if (!dd) return id;
    var f = dd.fields || {};
    return f['client-name'] || f.clientName || f.client || id;
  }

  /* ══════════════════════════════════════════════════════════════
     § 2. _getAll38 — merge global + local, BRL-normalised
          This is the single source of truth for all Financeiro
          dashboard views. Global _FIN_KEY records take priority;
          local per-dossier records are included only when not
          already represented by a matching source_id.
     ══════════════════════════════════════════════════════════════ */

  function _getAll38() {
    var recv = [], exp = [], cred = [];
    var seenSids = Object.create(null);

    /* — Step 1: global lancamentos — */
    _finLoad38().forEach(function(r) {
      var sid = r.source_id || r.id;
      if (sid) seenSids[sid] = true;
      var ref = r.dossierRef || '';
      var brl = _brl38(r);

      if (r.tipo === 'entrada') {
        recv.push({
          _isGlobal: true, _dossierId: '', _dossierRef: ref, _client: r.fornecedor || '',
          source_id: sid, description: r.descricao || r.nota || '',
          amount: brl, paidAmount: (r.pago === 'pago') ? brl : 0, currency: 'BRL',
          dueDate: r.vencimento || '', payMethod: (r.source_type || '').replace(/_/g, ' '),
          status: r.pago === 'pago' ? 'paid' : (r.pago === 'atrasado' ? 'overdue' : 'pending'),
          notes: r.nota || r.installment_label || ''
        });
      } else if (r.tipo === 'saida') {
        exp.push({
          _isGlobal: true, _dossierId: '', _dossierRef: ref, _client: r.fornecedor || '',
          source_id: sid, description: r.descricao || r.nota || '',
          supplier: r.fornecedor || '', category: r.categoria || '',
          amount: brl, paidAmount: (r.pago === 'pago') ? brl : 0, currency: 'BRL',
          dueDate: r.vencimento || '',
          status: r.pago === 'pago' ? 'paid' : (r.pago === 'atrasado' ? 'overdue' : 'pending'),
          pnrRef: r.source_id || '', notes: r.nota || ''
        });
      }
    });

    /* — Step 2: per-dossier local records not yet in global — */
    _getDossierIds38().forEach(function(id) {
      var data; try { data = JSON.parse(localStorage.getItem('expatur_doss_finance_' + id) || 'null'); } catch(e) {}
      if (!data) return;
      var ref = _dossRef38(id);
      var cli = _dossClient38(id);

      (data.receivables || []).forEach(function(r) {
        if (r.source_id && seenSids[r.source_id]) return;
        if (r.id && seenSids[r.id]) return;
        var brl = _brl38(r) || parseFloat(r.amount) || 0;
        var paid = r.status === 'paid' ? brl : (parseFloat(r.paidAmount) || 0);
        recv.push(Object.assign({}, r, {
          _isGlobal: false, _dossierId: id, _dossierRef: ref, _client: cli,
          amount: brl, paidAmount: paid, currency: 'BRL'
        }));
      });

      (data.expenses || []).forEach(function(e) {
        if (e.source_id && seenSids[e.source_id]) return;
        if (e.id && seenSids[e.id]) return;
        var brl = _brl38(e) || parseFloat(e.amount) || 0;
        var paid = e.status === 'paid' ? brl : (parseFloat(e.paidAmount) || 0);
        exp.push(Object.assign({}, e, {
          _isGlobal: false, _dossierId: id, _dossierRef: ref, _client: cli,
          amount: brl, paidAmount: paid, currency: 'BRL'
        }));
      });

      (data.credits || []).forEach(function(c) {
        cred.push(Object.assign({}, c, { _dossierId: id, _dossierRef: ref, _client: cli }));
      });
    });

    return { recv: recv, exp: exp, cred: cred };
  }

  /* Expose on window so external callers and HTML oninput can use it */
  window.getAllFinanceLines = function() { return _getAll38(); };

  /* ══════════════════════════════════════════════════════════════
     § 3. finRenderDashboard — BRL KPIs, global+local data
     ══════════════════════════════════════════════════════════════ */

  window.finRenderDashboard = function() {
    var all    = _getAll38();
    var today  = _today38();

    var openRecv = 0, openExp = 0, overdueRecv = 0, overdueExp = 0, credOutstanding = 0;
    var forecastMarginTotal = 0, realMarginTotal = 0;

    all.recv.forEach(function(r) {
      var bal = (parseFloat(r.amount) || 0) - (parseFloat(r.paidAmount) || 0);
      if (bal > 0) openRecv += bal;
      if (bal > 0 && r.dueDate && r.dueDate < today) overdueRecv += bal;
    });
    all.exp.forEach(function(e) {
      var bal = (parseFloat(e.amount) || 0) - (parseFloat(e.paidAmount) || 0);
      if (bal > 0) openExp += bal;
      if (bal > 0 && e.dueDate && e.dueDate < today) overdueExp += bal;
    });
    all.cred.forEach(function(c) {
      credOutstanding += Math.max(0, (parseFloat(c.originalAmount) || 0) - (parseFloat(c.usedAmount) || 0));
    });

    /* Margin: use v3.6 BRL-aware compute if available, else raw dossFIN */
    var _ov = typeof window._v36ComputeOverview === 'function'
      ? window._v36ComputeOverview
      : (typeof window.dossFIN_computeOverview === 'function' ? window.dossFIN_computeOverview : null);
    _getDossierIds38().forEach(function(id) {
      if (!_ov) return;
      var ov = _ov(id);
      if (!ov) return;
      forecastMarginTotal += ov.forecastMargin || 0;
      realMarginTotal     += ov.realizedMargin || 0;
    });

    var grid = document.getElementById('fin-dash-kpi-grid');
    if (grid) {
      grid.innerHTML = [
        { label: 'Recebimentos em aberto', val: _fmtBRL38(openRecv),           color: 'blue',   sub: 'Saldo por receber (BRL)' },
        { label: 'Despesas em aberto',     val: _fmtBRL38(openExp),            color: 'amber',  sub: 'Saldo por pagar (BRL)' },
        { label: 'Recebimentos vencidos',  val: _fmtBRL38(overdueRecv),        color: '',       sub: 'Prazo ultrapassado' },
        { label: 'Despesas vencidas',      val: _fmtBRL38(overdueExp),         color: '',       sub: 'Prazo ultrapassado' },
        { label: 'Cr\u00e9ditos dispon\u00edveis', val: _fmtBRL38(credOutstanding), color: 'purple', sub: 'Saldo total de cr\u00e9ditos' },
        { label: 'Margem prevista total',  val: _fmtBRL38(forecastMarginTotal), color: forecastMarginTotal >= 0 ? 'green' : '', sub: 'Todos os dossiers (BRL)' },
        { label: 'Margem realizada total', val: _fmtBRL38(realMarginTotal),    color: realMarginTotal >= 0 ? 'green' : '',    sub: 'Recebido \u2212 Pago (BRL)' },
      ].map(function(k) {
        return '<div class="fin-dash-kpi ' + k.color + '">' +
          '<div class="fin-dash-kpi-label">' + _esc38(k.label) + '</div>' +
          '<div class="fin-dash-kpi-value">' + k.val + '</div>' +
          '<div class="fin-dash-kpi-sub">'   + _esc38(k.sub)   + '</div>' +
          '</div>';
      }).join('');
    }

    /* Overdue receivables */
    var odREl = document.getElementById('fin-dash-overdue-recv');
    if (odREl) {
      var odR = all.recv.filter(function(r) {
        var b = (parseFloat(r.amount) || 0) - (parseFloat(r.paidAmount) || 0);
        return b > 0 && r.dueDate && r.dueDate < today;
      });
      if (!odR.length) {
        odREl.innerHTML = '<div style="font-size:0.78rem;color:#16a34a;font-weight:600;">\u2713 Nenhum recebimento vencido</div>';
      } else {
        odREl.innerHTML = odR.slice(0, 5).map(function(r) {
          var bal = (parseFloat(r.amount) || 0) - (parseFloat(r.paidAmount) || 0);
          return '<div style="display:flex;justify-content:space-between;align-items:center;padding:0.4rem 0;border-bottom:1px solid var(--border);font-size:0.78rem;">' +
            '<div><span style="font-family:monospace;font-weight:700;color:var(--red);font-size:0.7rem;">' + _esc38(r._dossierRef) + '</span> ' + _esc38(r.description || r.descricao || '') + '<br>' +
            '<small style="color:var(--navy-faint);">Venc: ' + _dateLabel38(r.dueDate) + '</small></div>' +
            '<strong style="color:var(--red);">' + _fmtBRL38(bal) + '</strong></div>';
        }).join('');
      }
    }

    /* Overdue expenses */
    var odEEl = document.getElementById('fin-dash-overdue-exp');
    if (odEEl) {
      var odE = all.exp.filter(function(e) {
        var b = (parseFloat(e.amount) || 0) - (parseFloat(e.paidAmount) || 0);
        return b > 0 && e.dueDate && e.dueDate < today;
      });
      if (!odE.length) {
        odEEl.innerHTML = '<div style="font-size:0.78rem;color:#16a34a;font-weight:600;">\u2713 Nenhuma despesa vencida</div>';
      } else {
        odEEl.innerHTML = odE.slice(0, 5).map(function(e) {
          var bal = (parseFloat(e.amount) || 0) - (parseFloat(e.paidAmount) || 0);
          return '<div style="display:flex;justify-content:space-between;align-items:center;padding:0.4rem 0;border-bottom:1px solid var(--border);font-size:0.78rem;">' +
            '<div><span style="font-family:monospace;font-weight:700;color:var(--red);font-size:0.7rem;">' + _esc38(e._dossierRef) + '</span> ' + _esc38(e.supplier || e.fornecedor || '\u2014') + '<br>' +
            '<small style="color:var(--navy-faint);">Venc: ' + _dateLabel38(e.dueDate) + '</small></div>' +
            '<strong style="color:var(--red);">' + _fmtBRL38(bal) + '</strong></div>';
        }).join('');
      }
    }

    /* Open dossiers table */
    var tbody = document.getElementById('fin-dash-open-body');
    var emptyEl = document.getElementById('fin-dash-open-empty');
    if (tbody) {
      tbody.innerHTML = '';
      var computeOv = typeof window._v36ComputeOverview === 'function' ? window._v36ComputeOverview
        : (typeof window.dossFIN_computeOverview === 'function' ? window.dossFIN_computeOverview : null);
      var dIds = _getDossierIds38().filter(function(id) { return localStorage.getItem('expatur_booked_' + id) === '1'; });
      var rows = [];
      dIds.forEach(function(id) {
        if (!computeOv) return;
        var ov = computeOv(id);
        if (!ov) return;
        if (ov.balClientDue === 0 && ov.balSupplierDue === 0) return;
        rows.push({ ref: _dossRef38(id), client: _dossClient38(id), ov: ov });
      });
      if (!rows.length) {
        if (emptyEl) emptyEl.style.display = '';
      } else {
        if (emptyEl) emptyEl.style.display = 'none';
        rows.forEach(function(r) {
          var tr = document.createElement('tr');
          tr.innerHTML =
            '<td><span style="font-family:monospace;font-weight:700;font-size:0.8rem;">' + _esc38(r.ref) + '</span></td>' +
            '<td>' + _esc38(r.client) + '</td>' +
            '<td style="text-align:right;font-weight:700;color:var(--red);">' + _fmtBRL38(r.ov.balClientDue) + '</td>' +
            '<td style="text-align:right;font-weight:700;color:#f59e0b;">' + _fmtBRL38(r.ov.balSupplierDue) + '</td>' +
            '<td style="text-align:right;font-weight:700;color:' + (r.ov.forecastMargin >= 0 ? '#16a34a' : 'var(--red)') + ';">' + _fmtBRL38(r.ov.forecastMargin) + '</td>' +
            '<td><span class="fbadge fbadge-pending">Aberto</span></td>';
          tbody.appendChild(tr);
        });
      }
    }
  };

  /* ══════════════════════════════════════════════════════════════
     § 4. finRenderRecebimentos — BRL, global+local
     ══════════════════════════════════════════════════════════════ */

  window._v38RecvFilter = 'all';

  window.finRenderRecebimentos = function() {
    var all = _getAll38();
    var q   = ((document.getElementById('fin-recv-search') || {}).value || '').toLowerCase();
    var today = _today38();
    var filter = window._v38RecvFilter || 'all';

    var rows = all.recv.filter(function(r) {
      if (q) {
        var hay = (r.description || r.descricao || '') + ' ' + (r._dossierRef || '') + ' ' + (r._client || '');
        if (hay.toLowerCase().indexOf(q) < 0) return false;
      }
      if (filter === 'all') return true;
      var amt = parseFloat(r.amount) || 0, paid = parseFloat(r.paidAmount) || 0, bal = amt - paid;
      if (filter === 'paid')    return r.status === 'paid';
      if (filter === 'pending') return r.status === 'pending' || r.status === 'draft';
      if (filter === 'partial') return r.status === 'partial';
      if (filter === 'overdue') return bal > 0 && r.dueDate && r.dueDate < today;
      return true;
    });

    var tbody = document.getElementById('fin-recv-body');
    var empty = document.getElementById('fin-recv-empty');
    if (!tbody) return;
    tbody.innerHTML = '';
    if (!rows.length) { if (empty) empty.style.display = ''; return; }
    if (empty) empty.style.display = 'none';

    rows.forEach(function(r) {
      var amt = parseFloat(r.amount) || 0, paid = parseFloat(r.paidAmount) || 0, bal = amt - paid;
      var st  = r.status || 'pending';
      var badgeCls = { paid: 'fbadge-paid', partial: 'fbadge-partial', pending: 'fbadge-pending', overdue: 'fbadge-overdue', draft: 'fbadge-draft' }[st] || 'fbadge-draft';
      var tr = document.createElement('tr');
      tr.innerHTML =
        '<td><span style="font-family:monospace;font-weight:700;font-size:0.72rem;color:var(--red);">' + _esc38(r._dossierRef) + '</span></td>' +
        '<td>' + _esc38(r.description || r.descricao || '') + '</td>' +
        '<td>' + _dateLabel38(r.dueDate || r.vencimento) + '</td>' +
        '<td><span class="fbadge ' + badgeCls + '">' + _esc38(st) + '</span></td>' +
        '<td>' + _esc38(r.payMethod || (r.source_type || '').replace(/_/g, ' ') || '\u2014') + '</td>' +
        '<td style="text-align:right;font-weight:700;">' + _fmtBRL38(amt) + '</td>' +
        '<td style="text-align:right;color:#16a34a;font-weight:700;">' + _fmtBRL38(paid) + '</td>' +
        '<td style="text-align:right;font-weight:700;color:' + (bal > 0 ? 'var(--red)' : '#16a34a') + ';">' + _fmtBRL38(bal) + '</td>' +
        '<td style="font-size:0.68rem;color:var(--navy-faint);">' + _esc38(r.notes || r.nota || '') + '</td>';
      tbody.appendChild(tr);
    });
  };

  window.finSetRecvFilter = function(f) {
    window._v38RecvFilter = f;
    document.querySelectorAll('[data-rfilt]').forEach(function(b) { b.classList.toggle('active', b.dataset.rfilt === f); });
    window.finRenderRecebimentos();
  };

  /* ══════════════════════════════════════════════════════════════
     § 5. finRenderDespesas — BRL, global+local
     ══════════════════════════════════════════════════════════════ */

  window._v38ExpFilter = 'all';

  window.finRenderDespesas = function() {
    var all = _getAll38();
    var q   = ((document.getElementById('fin-exp-search') || {}).value || '').toLowerCase();
    var today = _today38();
    var filter = window._v38ExpFilter || 'all';

    var rows = all.exp.filter(function(e) {
      if (q) {
        var hay = (e.description || e.descricao || '') + ' ' + (e.supplier || e.fornecedor || '') + ' ' + (e._dossierRef || '');
        if (hay.toLowerCase().indexOf(q) < 0) return false;
      }
      if (filter === 'all') return true;
      var amt = parseFloat(e.amount) || 0, paid = parseFloat(e.paidAmount) || 0, bal = amt - paid;
      if (filter === 'paid')    return e.status === 'paid';
      if (filter === 'pending') return e.status === 'pending' || e.status === 'draft' || e.status === 'confirmed';
      if (filter === 'overdue') return bal > 0 && e.dueDate && e.dueDate < today;
      return true;
    });

    var tbody = document.getElementById('fin-exp-body');
    var empty = document.getElementById('fin-exp-empty');
    if (!tbody) return;
    tbody.innerHTML = '';
    if (!rows.length) { if (empty) empty.style.display = ''; return; }
    if (empty) empty.style.display = 'none';

    rows.forEach(function(e) {
      var amt = parseFloat(e.amount) || 0, paid = parseFloat(e.paidAmount) || 0, bal = amt - paid;
      var st  = e.status || 'pending';
      var badgeCls = { paid: 'fbadge-paid', confirmed: 'fbadge-confirmed', pending: 'fbadge-pending', overdue: 'fbadge-overdue', draft: 'fbadge-draft' }[st] || 'fbadge-draft';
      var tr = document.createElement('tr');
      tr.innerHTML =
        '<td><span style="font-family:monospace;font-weight:700;font-size:0.72rem;color:var(--red);">' + _esc38(e._dossierRef) + '</span></td>' +
        '<td>' + _esc38(e.supplier || e.fornecedor || '\u2014') + '</td>' +
        '<td>' + _esc38(e.category || e.categoria || '\u2014') + '</td>' +
        '<td>' + _dateLabel38(e.dueDate || e.vencimento) + '</td>' +
        '<td><span class="fbadge ' + badgeCls + '">' + _esc38(st) + '</span></td>' +
        '<td style="font-family:monospace;font-size:0.7rem;color:var(--gold);">' + _esc38(e.pnrRef || e.source_id || '\u2014') + '</td>' +
        '<td style="text-align:right;font-weight:700;">' + _fmtBRL38(amt) + '</td>' +
        '<td style="text-align:right;color:#16a34a;font-weight:700;">' + _fmtBRL38(paid) + '</td>' +
        '<td style="text-align:right;font-weight:700;color:' + (bal > 0 ? 'var(--red)' : '#16a34a') + ';">' + _fmtBRL38(bal) + '</td>';
      tbody.appendChild(tr);
    });
  };

  window.finSetExpFilter = function(f) {
    window._v38ExpFilter = f;
    document.querySelectorAll('[data-efilt]').forEach(function(b) { b.classList.toggle('active', b.dataset.efilt === f); });
    window.finRenderDespesas();
  };

  /* ══════════════════════════════════════════════════════════════
     § 6. finRenderLedger — BRL, global+local
     ══════════════════════════════════════════════════════════════ */

  window.finRenderLedger = function() {
    var all = _getAll38();
    var q   = ((document.getElementById('fin-ledger-search') || {}).value || '').toLowerCase();
    var container = document.getElementById('fin-ledger-list');
    if (!container) return;
    var today = _today38();

    var suppMap = Object.create(null);
    all.exp.forEach(function(e) {
      var sn = e.supplier || e.fornecedor || '\u2014';
      if (q && sn.toLowerCase().indexOf(q) < 0) return;
      if (!suppMap[sn]) suppMap[sn] = { name: sn, total: 0, paid: 0, overdue: 0, dossiers: Object.create(null), credits: 0 };
      var amt = parseFloat(e.amount) || 0, paid = parseFloat(e.paidAmount) || 0, bal = amt - paid;
      suppMap[sn].total += amt;
      suppMap[sn].paid  += paid;
      if (e._dossierRef) suppMap[sn].dossiers[e._dossierRef] = true;
      if (e.dueDate && e.dueDate < today && bal > 0) suppMap[sn].overdue += bal;
    });
    all.cred.forEach(function(c) {
      if (c.creditType !== 'supplier') return;
      var sn = c.owner || '\u2014';
      if (suppMap[sn]) suppMap[sn].credits += Math.max(0, (parseFloat(c.originalAmount) || 0) - (parseFloat(c.usedAmount) || 0));
    });

    var keys = Object.keys(suppMap);
    if (!keys.length) {
      container.innerHTML = '<div class="fin-empty">Nenhum fornecedor encontrado.</div>';
      return;
    }

    container.innerHTML = keys.map(function(sn) {
      var s       = suppMap[sn];
      var balance = s.total - s.paid;
      var dossList = Object.keys(s.dossiers).filter(Boolean).join(', ');
      return '<div class="forn-ledger-card">' +
        '<div class="forn-ledger-header">' +
          '<div><div class="forn-ledger-name">' + _esc38(s.name) + '</div>' +
          '<div style="font-size:0.6rem;color:rgba(255,255,255,0.55);margin-top:2px;">Dossiers: ' + _esc38(dossList || '\u2014') + '</div></div>' +
          '<div class="forn-ledger-total">Saldo: ' + _fmtBRL38(balance) + '</div>' +
        '</div>' +
        '<div class="forn-ledger-body"><div class="forn-ledger-stats">' +
          '<div class="forn-ledger-stat"><span class="forn-ledger-stat-label">Total em aberto</span>' +
            '<span class="forn-ledger-stat-val ' + (balance > 0 ? 'red' : 'green') + '">' + _fmtBRL38(balance) + '</span></div>' +
          '<div class="forn-ledger-stat"><span class="forn-ledger-stat-label">Em atraso</span>' +
            '<span class="forn-ledger-stat-val ' + (s.overdue > 0 ? 'red' : '') + '">' + _fmtBRL38(s.overdue) + '</span></div>' +
          '<div class="forn-ledger-stat"><span class="forn-ledger-stat-label">Total pago</span>' +
            '<span class="forn-ledger-stat-val green">' + _fmtBRL38(s.paid) + '</span></div>' +
          '<div class="forn-ledger-stat"><span class="forn-ledger-stat-label">Cr\u00e9dito dispon.</span>' +
            '<span class="forn-ledger-stat-val">' + _fmtBRL38(s.credits) + '</span></div>' +
        '</div></div>' +
      '</div>';
    }).join('');
  };

  /* ══════════════════════════════════════════════════════════════
     § 7. finRenderDossierPL — BRL, uses _v36ComputeOverview
     ══════════════════════════════════════════════════════════════ */

  window.finRenderDossierPL = function() {
    var q         = ((document.getElementById('fin-pl-search') || {}).value || '').toLowerCase();
    var container = document.getElementById('fin-pl-list');
    if (!container) return;

    var computeOv = typeof window._v36ComputeOverview === 'function' ? window._v36ComputeOverview
      : (typeof window.dossFIN_computeOverview === 'function' ? window.dossFIN_computeOverview : null);
    var dIds = _getDossierIds38().filter(function(id) { return localStorage.getItem('expatur_booked_' + id) === '1'; });

    if (!dIds.length) {
      container.innerHTML = '<div class="fin-empty">Nenhum dossier reservado encontrado.</div>';
      return;
    }

    var rows = [];
    dIds.forEach(function(id) {
      var ref = _dossRef38(id);
      var cli = _dossClient38(id);
      if (q && ref.toLowerCase().indexOf(q) < 0 && cli.toLowerCase().indexOf(q) < 0) return;
      var ov = computeOv ? computeOv(id) : null;
      if (ov) rows.push({ ref: ref, client: cli, ov: ov });
    });

    if (!rows.length) {
      container.innerHTML = '<div class="fin-empty">Nenhum dossier encontrado.</div>';
      return;
    }

    container.innerHTML = rows.map(function(r) {
      var margin = r.ov.forecastMargin;
      var pct    = r.ov.totalSale > 0 ? (margin / r.ov.totalSale * 100).toFixed(1) : '0.0';
      var color  = margin >= 0 ? 'positive' : 'negative';
      return '<div class="doss-pl-card">' +
        '<div class="doss-pl-header">' +
          '<div><div class="doss-pl-ref">' + _esc38(r.ref) + '</div>' +
          '<div class="doss-pl-client">' + _esc38(r.client) + '</div></div>' +
          '<div class="doss-pl-margin ' + color + '">' + _fmtBRL38(margin) + ' (' + pct + '%)</div>' +
        '</div>' +
        '<div class="doss-pl-body">' +
          '<div class="doss-pl-col"><span class="doss-pl-col-label">Venda</span><span class="doss-pl-col-val">' + _fmtBRL38(r.ov.totalSale) + '</span></div>' +
          '<div class="doss-pl-col"><span class="doss-pl-col-label">Custo</span><span class="doss-pl-col-val">' + _fmtBRL38(r.ov.totalCost) + '</span></div>' +
          '<div class="doss-pl-col"><span class="doss-pl-col-label">Recebido</span><span class="doss-pl-col-val" style="color:#16a34a;">' + _fmtBRL38(r.ov.totalRecv) + '</span></div>' +
          '<div class="doss-pl-col"><span class="doss-pl-col-label">Pago</span><span class="doss-pl-col-val" style="color:#f59e0b;">' + _fmtBRL38(r.ov.totalPaid) + '</span></div>' +
        '</div>' +
      '</div>';
    }).join('');
  };

  /* ══════════════════════════════════════════════════════════════
     § 8. Re-override finSwitchTab — use window.finRender* so that
          our overrides (not the closed-over originals) are called.
     ══════════════════════════════════════════════════════════════ */

  window.finSwitchTab = function(tab) {
    document.querySelectorAll('.fin-tab').forEach(function(b) {
      b.classList.toggle('active', b.dataset.fintab === tab);
    });
    document.querySelectorAll('.fin-panel').forEach(function(p) {
      p.classList.toggle('active', p.id === 'fin-panel-' + tab);
    });
    if (tab === 'dashboard')      window.finRenderDashboard();
    if (tab === 'fluxo')          { if (typeof window.finRenderFluxo       === 'function') window.finRenderFluxo(); }
    if (tab === 'recebimentos')   window.finRenderRecebimentos();
    if (tab === 'despesas')       window.finRenderDespesas();
    if (tab === 'credits')        { if (typeof window.finRenderGlobalCredits === 'function') window.finRenderGlobalCredits(); }
    if (tab === 'ledger')         window.finRenderLedger();
    if (tab === 'dossierpl')      window.finRenderDossierPL();
    if (tab === 'reconciliation') { if (typeof window.finRenderReconciliation === 'function') window.finRenderReconciliation(); }
    if (tab === 'lancamentos')    { if (typeof window.finRenderLancamentos    === 'function') window.finRenderLancamentos(); }
    if (tab === 'stripe')         { if (typeof window.finFetchStripeBalance   === 'function') window.finFetchStripeBalance(); }
  };

  /* ══════════════════════════════════════════════════════════════
     § 9. Re-override finRefresh — dashboard as default tab
     ══════════════════════════════════════════════════════════════ */

  window.finRefresh = function() {
    document.querySelectorAll('.fin-tab').forEach(function(b) { b.classList.remove('active'); });
    document.querySelectorAll('.fin-panel').forEach(function(p) { p.classList.remove('active'); });
    var btn = document.querySelector('.fin-tab[data-fintab="dashboard"]');
    var pan = document.getElementById('fin-panel-dashboard');
    if (btn) btn.classList.add('active');
    if (pan) pan.classList.add('active');
    window.finRenderDashboard();
    if (typeof window.finRenderKPIs === 'function') window.finRenderKPIs();
  };

  /* ══════════════════════════════════════════════════════════════
     § 10. Fix dossFinRenderPanel — remove null-data guard
           v3.6 had: if (!data) { fallback; return; }
           That caused dossiers with no local finance record to skip
           the BRL patched functions entirely. Now we always call
           _v36Render* regardless of whether local data exists.
     ══════════════════════════════════════════════════════════════ */

  var _v38_prevPanel = window.dossFinRenderPanel;
  window.dossFinRenderPanel = function() {
    var id = localStorage.getItem('expatur_active_dossier');
    if (!id) { if (typeof _v38_prevPanel === 'function') _v38_prevPanel.call(this); return; }

    var activeBtn = document.querySelector('.doss-fin-tab.active');
    var tab = activeBtn ? activeBtn.dataset.dftab : null;
    var data = null;
    try { data = JSON.parse(localStorage.getItem('expatur_doss_finance_' + id) || 'null'); } catch(e) {}

    if (tab === 'overview') {
      if (typeof window._v36RenderOverview === 'function') { window._v36RenderOverview(id, data); return; }
    }
    if (tab === 'receivables') {
      if (typeof window._v36RenderReceivables === 'function') { window._v36RenderReceivables(id, data); return; }
    }
    if (tab === 'expenses') {
      if (typeof window._v36RenderExpenses === 'function') { window._v36RenderExpenses(id, data); return; }
    }

    /* credits / suppliers / audit — delegate to previous chain */
    if (typeof _v38_prevPanel === 'function') _v38_prevPanel.call(this);
  };

  /* ══════════════════════════════════════════════════════════════
     § 11. Auto-refresh dossFinRenderPanel after cost sync
           Ensures billet cost lines appear immediately in the panel.
     ══════════════════════════════════════════════════════════════ */

  if (!window._v38CostRefreshW && typeof window.finAutoCreateCostPayments === 'function') {
    window._v38CostRefreshW = true;
    var _v38_prevCostPay = window.finAutoCreateCostPayments;
    window.finAutoCreateCostPayments = function() {
      if (typeof _v38_prevCostPay === 'function') _v38_prevCostPay.apply(this, arguments);
      setTimeout(function() {
        try { window.dossFinRenderPanel(); } catch(e) {}
      }, 150);
    };
  }

  console.log('[Patch v3.8] Bug fixes: global store visible in all panels \u00b7 all Financeiro views now BRL \u00b7 finSwitchTab/finRefresh re-overridden \u00b7 dossFinRenderPanel null-guard removed');

})(); // end Finance Bug-Fix Patch v3.8

// ─────────────────────────────────────

(function() {
  'use strict';
  if (window._v38StripeBRL) return;
  window._v38StripeBRL = true;

  /* ══════════════════════════════════════════════════════════════
     § 1. HELPERS
     ══════════════════════════════════════════════════════════════ */

  function _fmtN(v, sym) {
    return sym + '\u00a0' + (parseFloat(v) || 0).toLocaleString('pt-BR', {
      minimumFractionDigits: 2, maximumFractionDigits: 2
    });
  }
  function _fmtBRL(v) { return _fmtN(v, 'R$'); }

  function _sym(cur) {
    return cur === 'EUR' ? '\u20ac' : cur === 'USD' ? '$' : cur === 'BRL' ? 'R$' : cur;
  }

  /* Fetch BRL rate for an ISO currency code.
     Tries the locally-cached _fxCache first, then open.er-api.com,
     then Frankfurter as fallback. */
  function _fetchRate(iso) {
    if (iso === 'BRL') return Promise.resolve(1);
    // Try local cache first (populated by fetchBRLRate)
    try {
      if (window._fxCache && window._fxCache[iso] && window._fxCache[iso].rate) {
        return Promise.resolve(parseFloat(window._fxCache[iso].rate));
      }
    } catch(e) {}
    // Route through fetchBRLRate (which now uses the FX Worker as primary source)
    if (typeof window.fetchBRLRate === 'function') {
      var symMap = { EUR: '€', USD: '$', GBP: '£', MAD: 'MAD', DOP: 'DOP' };
      var sym = symMap[iso] || iso;
      return window.fetchBRLRate(sym).catch(function() { return 1; });
    }
    // Hard fallback: open.er-api.com
    return fetch('https://open.er-api.com/v6/latest/' + iso)
      .then(function(r) { return r.json(); })
      .then(function(d) {
        return (d && d.rates && d.rates.BRL) ? parseFloat(d.rates.BRL) : 1;
      })
      .catch(function() { return 1; });
  }

  /* Group Stripe response amounts by currency symbol */
  function _groupByCur(data) {
    var m = Object.create(null);
    function add(arr, key) {
      (arr || []).forEach(function(a) {
        var c = (a.currency || 'eur').toUpperCase();
        if (!m[c]) m[c] = { available: 0, instant: 0, pending: 0, reserved: 0 };
        m[c][key] += (a.amount || 0) / 100;
      });
    }
    add(data.available,          'available');
    add(data.instant_available,  'instant');
    add(data.pending,            'pending');
    add(data.reserved || data.connect_reserved, 'reserved');
    return m;
  }

  /* ══════════════════════════════════════════════════════════════
     § 2. MAIN STRIPE BALANCE GRID RENDERER (with BRL block)
     ══════════════════════════════════════════════════════════════ */

  function _renderStripeGrid(data, rates) {
    var grid = document.getElementById('fin-stripe-bal-grid');
    if (!grid) return;
    var currencies = _groupByCur(data);
    var html = '';

    Object.keys(currencies).forEach(function(cur) {
      var c     = currencies[cur];
      var sym   = _sym(cur);
      var fmt   = function(v) { return _fmtN(v, sym); };
      var total = c.available + c.pending + c.reserved;
      var rate  = cur === 'BRL' ? 1 : ((rates && rates[cur]) || 0);
      var hasBRL = rate > 0 && cur !== 'BRL';

      html +=
        '<div class="stripe-bal-card">' +
          '<div class="stripe-bal-header"><span class="stripe-bal-currency">' + cur + '</span></div>' +
          '<div class="stripe-bal-body">' +
            '<div class="stripe-bal-row">' +
              '<span class="stripe-bal-row-label">Dispon\u00edvel</span>' +
              '<span class="stripe-bal-row-val available">' + fmt(c.available) + '</span>' +
            '</div>' +
            (c.instant > 0 ?
              '<div class="stripe-bal-row">' +
                '<span class="stripe-bal-row-label">Dispon\u00edvel instant\u00e2neo</span>' +
                '<span class="stripe-bal-row-val available" style="opacity:0.75;">' + fmt(c.instant) + '</span>' +
              '</div>' : '') +
            '<div class="stripe-bal-row">' +
              '<span class="stripe-bal-row-label">A receber (pendente)</span>' +
              '<span class="stripe-bal-row-val pending">' + fmt(c.pending) + '</span>' +
            '</div>' +
            '<div class="stripe-bal-row">' +
              '<span class="stripe-bal-row-label">Reserva de risco</span>' +
              '<span class="stripe-bal-row-val reserved">' + fmt(c.reserved) + '</span>' +
            '</div>' +
            '<div class="stripe-bal-total">' +
              '<span class="stripe-bal-total-label">Total consolidado</span>' +
              '<span class="stripe-bal-total-val">' + fmt(total) + '</span>' +
            '</div>' +
            /* ── BRL CONVERSION BLOCK ── */
            (hasBRL ?
              '<div style="border-top:2px solid #635bff;margin-top:10px;padding-top:10px;">' +
                '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">' +
                  '<span style="font-size:0.6rem;font-weight:800;letter-spacing:0.12em;text-transform:uppercase;color:#635bff;">Total em BRL</span>' +
                  '<span style="font-weight:800;font-size:1.1rem;color:#635bff;">' + _fmtBRL(total * rate) + '</span>' +
                '</div>' +
                '<div style="display:flex;justify-content:space-between;align-items:center;font-size:0.68rem;margin-bottom:2px;">' +
                  '<span style="color:var(--navy-soft);">Dispon\u00edvel</span>' +
                  '<span style="color:#16a34a;font-weight:700;">' + _fmtBRL(c.available * rate) + '</span>' +
                '</div>' +
                '<div style="display:flex;justify-content:space-between;align-items:center;font-size:0.68rem;margin-bottom:5px;">' +
                  '<span style="color:var(--navy-soft);">Pendente</span>' +
                  '<span style="color:#f59e0b;font-weight:700;">' + _fmtBRL(c.pending * rate) + '</span>' +
                '</div>' +
                '<div style="font-size:0.52rem;color:var(--navy-faint);text-align:right;">' +
                  '1\u00a0' + cur + '\u00a0=\u00a0' + _fmtBRL(rate) + '\u00a0\u00b7\u00a0taxa do dia' +
                '</div>' +
              '</div>'
            : (cur === 'BRL' ?
              '<div style="margin-top:8px;font-size:0.58rem;color:#635bff;font-weight:700;letter-spacing:0.06em;text-align:center;text-transform:uppercase;">Conta BRL</div>'
            : '<div style="margin-top:8px;font-size:0.58rem;color:var(--navy-faint);text-align:right;">Taxa BRL a carregar\u2026</div>')) +
          '</div>' +
        '</div>';
    });

    if (!html) html = '<div style="padding:1rem;color:var(--navy-faint);font-size:0.85rem;">Nenhum saldo encontrado.</div>';
    grid.innerHTML = html;
  }

  /* ══════════════════════════════════════════════════════════════
     § 3. MINI STRIPE WIDGET RENDERER (Fluxo de Caixa panel)
     ══════════════════════════════════════════════════════════════ */

  function _renderStripeMini(data, rates) {
    var miniCards = document.getElementById('fin-fluxo-stripe-cards');
    var miniTs    = document.getElementById('fin-fluxo-stripe-ts');
    if (!miniCards) return;
    var currencies = _groupByCur(data);
    if (!Object.keys(currencies).length) {
      miniCards.innerHTML = '<div style="font-size:0.75rem;color:var(--navy-faint);">Nenhum saldo encontrado.</div>';
      return;
    }
    miniCards.innerHTML = Object.keys(currencies).map(function(cur) {
      var c     = currencies[cur];
      var sym   = _sym(cur);
      var fmt   = function(v) { return _fmtN(v, sym); };
      var rate  = cur === 'BRL' ? 1 : ((rates && rates[cur]) || 0);
      var total = c.available + c.pending + c.reserved;
      var brlBlock = (rate > 0 && cur !== 'BRL')
        ? '<div style="border-top:1.5px solid #635bff;margin-top:5px;padding-top:5px;">' +
            '<div style="display:flex;justify-content:space-between;align-items:center;font-size:0.72rem;">' +
              '<span style="color:#635bff;font-weight:800;font-size:0.58rem;letter-spacing:0.08em;text-transform:uppercase;">Total BRL</span>' +
              '<span style="font-weight:800;color:#635bff;">' + _fmtBRL(total * rate) + '</span>' +
            '</div>' +
            '<div style="font-size:0.52rem;color:var(--navy-faint);text-align:right;margin-top:1px;">' +
              '1\u00a0' + cur + '\u00a0=\u00a0' + _fmtBRL(rate) +
            '</div>' +
          '</div>'
        : (rate === 0 && cur !== 'BRL' ? '<div style="font-size:0.52rem;color:var(--navy-faint);margin-top:4px;text-align:right;">BRL a carregar\u2026</div>' : '');

      return '<div style="background:var(--white);border:1px solid var(--border);border-top:3px solid #635bff;border-radius:8px;padding:0.7rem 0.9rem;min-width:180px;flex:1;">' +
        '<div style="font-size:0.58rem;font-weight:800;letter-spacing:0.15em;color:#635bff;text-transform:uppercase;margin-bottom:0.4rem;">' + cur + '</div>' +
        '<div style="display:flex;justify-content:space-between;gap:1rem;font-size:0.72rem;padding:2px 0;">' +
          '<span style="color:var(--navy-soft);">Dispon\u00edvel</span><span style="font-weight:700;color:#16a34a;">' + fmt(c.available) + '</span></div>' +
        (c.instant > 0 ?
          '<div style="display:flex;justify-content:space-between;gap:1rem;font-size:0.72rem;padding:2px 0;">' +
            '<span style="color:var(--navy-soft);">Instant\u00e2neo</span><span style="font-weight:600;color:#16a34a;opacity:0.75;">' + fmt(c.instant) + '</span></div>' : '') +
        '<div style="display:flex;justify-content:space-between;gap:1rem;font-size:0.72rem;padding:2px 0;">' +
          '<span style="color:var(--navy-soft);">Pendente</span><span style="font-weight:600;color:#f59e0b;">' + fmt(c.pending) + '</span></div>' +
        '<div style="display:flex;justify-content:space-between;gap:1rem;font-size:0.72rem;padding:2px 0;">' +
          '<span style="color:var(--navy-soft);">Reserva</span><span style="font-weight:600;color:var(--red);">' + fmt(c.reserved) + '</span></div>' +
        brlBlock +
      '</div>';
    }).join('');

    if (miniTs) miniTs.textContent = '\u00b7 ' + new Date().toLocaleString('pt-BR');
  }

  /* ══════════════════════════════════════════════════════════════
     § 4. OVERRIDE finFetchStripeBalance
          Two-pass render:
            Pass 1 — immediate (no BRL, rates not yet loaded)
            Pass 2 — after rate fetch Promise.all resolves, re-render with BRL
     ══════════════════════════════════════════════════════════════ */

  window.finFetchStripeBalance = function() {
    var msg       = document.getElementById('fin-stripe-msg');
    var grid      = document.getElementById('fin-stripe-bal-grid');
    var miniCards = document.getElementById('fin-fluxo-stripe-cards');

    if (msg)       { msg.textContent = 'A buscar saldo\u2026'; msg.style.color = 'var(--navy-faint)'; }
    if (grid)      grid.innerHTML = '';
    if (miniCards) miniCards.innerHTML = '<div style="font-size:0.75rem;color:var(--navy-faint);padding:0.4rem 0;">A sincronizar\u2026</div>';

    var workerUrl = window.STRIPE_BALANCE_WORKER_URL || 'https://expatur-balance.administration-a14.workers.dev';

    fetch(workerUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'get_balance' })
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
      if (data.error) {
        var errMsg = 'Erro: ' + data.error;
        if (msg)       { msg.textContent = errMsg; msg.style.color = 'var(--red)'; }
        if (miniCards) miniCards.innerHTML = '<div style="font-size:0.75rem;color:var(--red);">' + errMsg + '</div>';
        return;
      }

      window._stripeBalanceCache   = data;
      window._stripeBalanceCacheTs = new Date();
      if (msg) msg.textContent = '';

      var upd = document.getElementById('fin-stripe-last-update');
      var ts  = new Date().toLocaleString('pt-BR');
      if (upd) upd.textContent = '\u00daltima atualiza\u00e7\u00e3o: ' + ts;

      /* Pass 1 — instant render without BRL totals */
      _renderStripeGrid(data, {});
      _renderStripeMini(data, {});

      /* Collect non-BRL currencies */
      var curs = Object.create(null);
      var allArrays = [data.available, data.pending, data.instant_available,
                       data.reserved, data.connect_reserved];
      allArrays.forEach(function(arr) {
        (arr || []).forEach(function(a) {
          var c = (a.currency || '').toUpperCase();
          if (c && c !== 'BRL') curs[c] = true;
        });
      });

      var isos = Object.keys(curs);
      if (!isos.length) return; // already BRL only

      /* Pass 2 — fetch rates then re-render with BRL totals */
      Promise.all(isos.map(function(iso) {
        return _fetchRate(iso).then(function(rate) { return { iso: iso, rate: rate }; });
      }))
      .then(function(results) {
        var rates = Object.create(null);
        results.forEach(function(r) { rates[r.iso] = r.rate; });
        _renderStripeGrid(data, rates);
        _renderStripeMini(data, rates);
      })
      .catch(function(e) {
        console.warn('[v3.8-stripe] BRL rate fetch error:', e);
      });
    })
    .catch(function(e) {
      var errMsg = 'Erro de comunica\u00e7\u00e3o: ' + e.message;
      if (msg)       { msg.textContent = errMsg; msg.style.color = 'var(--red)'; }
      if (miniCards) miniCards.innerHTML = '<div style="font-size:0.75rem;color:var(--red);">' + errMsg + '</div>';
    });
  };

  console.log('[Patch v3.8-S] Stripe balance BRL conversion active \u00b7 two-pass render \u00b7 live FX rates');

})(); // end Stripe BRL Conversion Patch v3.8-S

// ─────────────────────────────────────

/* ═══════════════════════════════════════════════════════════════════════════
   PATCH v3.8-R  —  Remaining Financeiro Views → BRL
   Covers: finRenderKPIs · finRenderFluxo · finRenderLancamentos ·
           finRenderGlobalCredits · finRenderReconciliation
   All views now use window.getAllFinanceLines() (→ _getAll38() merged
   global+local BRL-normalised data) and display amounts in R$.
   Depends on: v3.8 (window.getAllFinanceLines), v3.3 (window._fxToBRL)
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v38RPatch) return;
  window._v38RPatch = true;

  /* ── §0. Private helpers ─────────────────────────────────────────────── */

  function _fmtR(v) {
    return 'R$\u00a0' + (parseFloat(v) || 0).toLocaleString('pt-BR', {
      minimumFractionDigits: 2, maximumFractionDigits: 2
    });
  }

  function _esc(s) {
    return (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function _today() { return new Date().toISOString().slice(0, 10); }

  function _dLabel(d) {
    if (!d) return '\u2014';
    var p = d.split('-');
    return p.length < 3 ? d : p[2] + '/' + p[1] + '/' + p[0];
  }

  /* BRL converter: prefer stored brl_amount → window._fxEntryToBRL → raw */
  function _brlOf(it) {
    if (it.brl_amount != null && parseFloat(it.brl_amount) > 0)
      return parseFloat(it.brl_amount);
    if (typeof window._fxEntryToBRL === 'function')
      return window._fxEntryToBRL(it);
    return parseFloat(it.valor || it.amount || 0) || 0;
  }

  /* Convert an amount+currency pair to BRL */
  function _toBRL(amount, currency) {
    var v = parseFloat(amount) || 0;
    if (!currency || currency === 'BRL' || currency === 'R$') return v;
    if (typeof window._fxToBRL === 'function') return window._fxToBRL(v, currency);
    return v; // fallback: no conversion available
  }

  /* Return merged globalfinance lines (always BRL-normalised) */
  function _getAll() {
    if (typeof window.getAllFinanceLines === 'function')
      return window.getAllFinanceLines();
    return { recv: [], exp: [], cred: [] };
  }

  /* Load global lancamentos directly */
  function _loadGlobal() {
    try { return JSON.parse(localStorage.getItem('expatur_financeiro_lancamentos') || '[]'); }
    catch (e) { return []; }
  }

  /* Month divider label (YYYY-MM → "Abr 2026") */
  var _MONTHS = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
  function _monthLabel(ym) {
    var p = ym.split('-');
    return (_MONTHS[parseInt(p[1]) - 1] || p[1]) + ' ' + p[0];
  }

  /* Simple status badge (fluxo rows) */
  function _badgeSimple(pago, date) {
    var t = _today();
    if (pago === 'pago')      return '<span class="fin-badge-pago">Pago</span>';
    if (!date || date > t)    return '<span class="fin-badge-futuro">Futuro</span>';
    if (date === t)           return '<span class="fin-badge-pendente">Hoje</span>';
    return '<span class="fin-badge-vencido">Vencido</span>';
  }

  /* Full status badge (lançamentos rows — includes A vencer / Hoje) */
  function _badgeFull(it) {
    var t = _today();
    if (it.pago === 'pago')    return '<span class="fin-badge-pago">Pago</span>';
    if (!it.vencimento)        return '<span class="fin-badge-futuro">Pendente</span>';
    if (it.vencimento > t)     return '<span class="fin-badge-futuro">A vencer</span>';
    if (it.vencimento === t)   return '<span class="fin-badge-pendente">Hoje</span>';
    return '<span class="fin-badge-vencido">Vencido</span>';
  }

  /* ── §1. finRenderKPIs ───────────────────────────────────────────────── */
  /*
     Uses window.getAllFinanceLines() (= _getAll38()) so that per-dossier
     cost-calculator entries are included.  Amounts are already in BRL.
  */
  window.finRenderKPIs = function () {
    var kpiRow = document.getElementById('fin-kpi-row');
    if (!kpiRow) return;

    var all   = _getAll();
    var today = _today();
    var ym    = today.slice(0, 7);
    var f1    = ym + '-01';
    var lDay  = new Date(parseInt(today.slice(0, 4)), parseInt(today.slice(5, 7)), 0).getDate();
    var lM    = ym + '-' + ('0' + lDay).slice(-2);

    var entradaMes = 0, saidaMes = 0, pendente = 0, vencido = 0;

    all.recv.forEach(function (r) {
      var amt  = parseFloat(r.amount) || 0;
      var paid = parseFloat(r.paidAmount) || 0;
      var bal  = amt - paid;
      var due  = r.dueDate || today;
      if (due >= f1 && due <= lM) entradaMes += amt;
      if (r.status !== 'paid' && bal > 0) {
        if (due < today) vencido  += bal;
        else             pendente += bal;
      }
    });

    all.exp.forEach(function (e) {
      var amt  = parseFloat(e.amount) || 0;
      var paid = parseFloat(e.paidAmount) || 0;
      var bal  = amt - paid;
      var due  = e.dueDate || today;
      if (due >= f1 && due <= lM) saidaMes += amt;
      if (e.status !== 'paid' && bal > 0) {
        if (due < today) vencido  += bal;
        else             pendente += bal;
      }
    });

    kpiRow.innerHTML = [
      { label: 'Entradas m\u00eas (BRL)', value: _fmtR(entradaMes), cls: 'green'  },
      { label: 'Sa\u00eddas m\u00eas (BRL)',   value: _fmtR(saidaMes),   cls: ''       },
      { label: 'A vencer (BRL)',          value: _fmtR(pendente),   cls: 'blue'   },
      { label: 'Vencidos (BRL)',          value: _fmtR(vencido),    cls: 'orange' }
    ].map(function (k) {
      return '<div class="fin-kpi ' + k.cls + '">'
        + '<div class="fin-kpi-label">' + _esc(k.label) + '</div>'
        + '<div class="fin-kpi-value">' + k.value + '</div>'
        + '</div>';
    }).join('');
  };

  /* ── §2. finRenderFluxo ──────────────────────────────────────────────── */
  /*
     Rebuilds Fluxo table from global lançamentos + booking payments.
     All amounts shown in BRL via _brlOf / _toBRL.
     Period and type filters are read from active DOM buttons since the
     closure-local _finPeriod / _finTypeFilter are inaccessible.
  */
  window.finRenderFluxo = function () {
    window.finRenderKPIs();

    var tbody = document.getElementById('fin-fluxo-body');
    var empty = document.getElementById('fin-fluxo-empty');
    if (!tbody) return;

    var today    = _today();
    var allItems = [];

    /* Global lançamentos */
    _loadGlobal().forEach(function (it) {
      allItems.push({
        date:       it.vencimento || (it.createdAt && it.createdAt.slice(0, 10)) || today,
        desc:       it.descricao  || '',
        categoria:  it.categoria  || '\u2014',
        fornecedor: it.fornecedor || '\u2014',
        ref:        it.dossierRef || '',
        brl:        _brlOf(it),
        tipo:       it.tipo,
        pago:       it.pago,
        id:         it.id,
        source:     'lancamento'
      });
    });

    /* Booking payment records */
    try {
      Object.keys(localStorage)
        .filter(function (k) { return k.indexOf('expatur_payments_') === 0; })
        .forEach(function (k) {
          var ref = k.replace('expatur_payments_', '').replace(/_/g, '-').replace(/^-+|-+$/g, '');
          var arr; try { arr = JSON.parse(localStorage.getItem(k) || '[]'); } catch (e) { arr = []; }
          arr.forEach(function (p) {
            var brl = (p.brl_amount != null)
              ? parseFloat(p.brl_amount) || 0
              : _toBRL(parseFloat(p.amount) || 0, p.currency || 'EUR');
            allItems.push({
              date:       p.date || today,
              desc:       'Pagamento cliente' + (p.customer && p.customer.name ? ' \u2014 ' + p.customer.name : ''),
              categoria:  'Receita - Booking',
              fornecedor: (p.customer && p.customer.name) || '\u2014',
              ref:        ref,
              brl:        brl,
              tipo:       'entrada',
              pago:       p.status === 'paid' ? 'pago' : 'pendente',
              id:         null,
              source:     'booking'
            });
          });
        });
    } catch (e) {}

    /* Period filter — read from active button */
    var periodBtn = document.querySelector('.fin-filter-btn[data-period].active');
    var periodDays = periodBtn ? parseInt(periodBtn.dataset.period) || 0 : 0;
    if (periodDays > 0) {
      var cutoff = new Date(); cutoff.setDate(cutoff.getDate() - periodDays);
      var future = new Date(); future.setDate(future.getDate() + periodDays);
      var cs = cutoff.toISOString().slice(0, 10), fs = future.toISOString().slice(0, 10);
      allItems = allItems.filter(function (it) { return it.date >= cs && it.date <= fs; });
    }

    /* Type filter */
    var typeBtn = document.querySelector('.fin-filter-btn[data-ftype].active');
    var typeFilter = typeBtn ? typeBtn.dataset.ftype : 'all';
    if (typeFilter !== 'all') {
      allItems = allItems.filter(function (it) { return it.tipo === typeFilter; });
    }

    allItems.sort(function (a, b) { return b.date.localeCompare(a.date); });

    if (!allItems.length) {
      tbody.innerHTML = '';
      if (empty) empty.style.display = '';
      return;
    }
    if (empty) empty.style.display = 'none';

    var curMonth = null, html = '';
    allItems.forEach(function (it) {
      var mk = it.date.slice(0, 7);
      if (mk !== curMonth) {
        curMonth = mk;
        html += '<tr><td colspan="8" class="fin-month-divider">' + _monthLabel(mk) + '</td></tr>';
      }
      var amtCls = it.tipo === 'entrada' ? 'fin-amount-entrada' : 'fin-amount-saida';
      var sign   = it.tipo === 'entrada' ? '+' : '\u2212';
      var statusBadge = _badgeSimple(it.pago, it.date);
      var delBtn = it.id
        ? '<button onclick="finDeleteItem(' + JSON.stringify(it.id) + ')" style="background:none;border:none;cursor:pointer;color:var(--navy-faint);font-size:0.9rem;padding:0 4px;line-height:1;" title="Excluir">\u00d7</button>'
        : '';
      html += '<tr>'
        + '<td style="white-space:nowrap;">'                                           + _dLabel(it.date)      + '</td>'
        + '<td>'                                                                        + _esc(it.desc)        + '</td>'
        + '<td><span style="font-size:0.72rem;color:var(--navy-soft);">'               + _esc(it.categoria)   + '</span></td>'
        + '<td>'                                                                        + _esc(it.fornecedor)  + '</td>'
        + '<td><span style="font-family:monospace;font-size:0.78rem;">'                + _esc(it.ref)         + '</span></td>'
        + '<td style="text-align:right;" class="' + amtCls + '">' + sign + _fmtR(it.brl) + '</td>'
        + '<td>' + statusBadge + '</td>'
        + '<td>' + delBtn + '</td>'
        + '</tr>';
    });
    tbody.innerHTML = html;
  };

  /* Re-wire period / type filter buttons */
  window.finSetPeriod = function (days, btn) {
    document.querySelectorAll('.fin-filter-btn[data-period]').forEach(function (b) { b.classList.remove('active'); });
    if (btn) btn.classList.add('active');
    window.finRenderFluxo();
  };
  window.finSetTypeFilter = function (type, btn) {
    document.querySelectorAll('.fin-filter-btn[data-ftype]').forEach(function (b) { b.classList.remove('active'); });
    if (btn) btn.classList.add('active');
    window.finRenderFluxo();
  };

  /* ── §3. finRenderLancamentos ────────────────────────────────────────── */
  /*
     Lançamentos is the manual-entry ledger — data source stays global
     lançamentos (finLoad).  Only the amount display is patched to BRL.
     CRUD buttons (edit/delete/toggle) are preserved verbatim.
  */
  window.finRenderLancamentos = function () {
    var tbody = document.getElementById('fin-lanc-body');
    var empty = document.getElementById('fin-lanc-empty');
    if (!tbody) return;

    var items = _loadGlobal();
    var today = _today();

    /* Read active filter from DOM */
    var lancBtn = document.querySelector('.fin-filter-btn[data-lcat].active');
    var lancFilter = lancBtn ? lancBtn.dataset.lcat : 'all';
    if (lancFilter === 'saida')       items = items.filter(function (it) { return it.tipo === 'saida'; });
    if (lancFilter === 'entrada')     items = items.filter(function (it) { return it.tipo === 'entrada'; });
    if (lancFilter === 'fixas')       items = items.filter(function (it) { return (it.categoria || '').startsWith('Fixas'); });
    if (lancFilter === 'variaveis')   items = items.filter(function (it) { return (it.categoria || '').startsWith('Vari\u00e1veis'); });
    if (lancFilter === 'pendentes')   items = items.filter(function (it) { return it.pago !== 'pago'; });
    if (lancFilter === 'recorrentes') items = items.filter(function (it) { return !!it.recorrente; });

    items.sort(function (a, b) { return (a.vencimento || '').localeCompare(b.vencimento || ''); });

    if (!items.length) {
      tbody.innerHTML = '';
      if (empty) empty.style.display = '';
      return;
    }
    if (empty) empty.style.display = 'none';

    var html = '';
    items.forEach(function (it) {
      var amtCls = it.tipo === 'entrada' ? 'fin-amount-entrada' : 'fin-amount-saida';
      var sign   = it.tipo === 'entrada' ? '+' : '\u2212';
      var recurLabel = it.recorrente
        ? '<span style="background:rgba(59,130,246,0.1);color:#1e40af;border:1px solid rgba(59,130,246,0.2);border-radius:4px;padding:1px 6px;font-size:0.6rem;font-weight:700;">Todo dia ' + _esc(it.recurDia || '?') + '</span>'
        : '\u2014';
      var pagoToggle = '<button onclick="finTogglePago(' + JSON.stringify(it.id) + ')" '
        + 'style="background:none;border:none;cursor:pointer;font-size:0.85rem;padding:0 2px;" title="Alternar status">'
        + (it.pago === 'pago' ? '\u2705' : '\u2b1c') + '</button>';
      html += '<tr>'
        + '<td style="white-space:nowrap;">'               + _dLabel(it.vencimento) + '</td>'
        + '<td>' + _esc(it.descricao) + (it.nota ? '<div style="font-size:0.68rem;color:var(--navy-faint);">' + _esc(it.nota) + '</div>' : '') + '</td>'
        + '<td><span style="font-size:0.72rem;color:var(--navy-soft);">' + _esc(it.categoria || '\u2014') + '</span></td>'
        + '<td>'                                            + _esc(it.fornecedor || '\u2014') + '</td>'
        + '<td>'                                            + recurLabel + '</td>'
        + '<td style="text-align:right;" class="' + amtCls + '">' + sign + _fmtR(_brlOf(it)) + '</td>'
        + '<td>' + _badgeFull(it) + '&nbsp;' + pagoToggle + '</td>'
        + '<td style="white-space:nowrap;">'
          + '<button onclick="finEditLancamento(' + JSON.stringify(it.id) + ')" '
          + 'style="background:none;border:1px solid var(--border);border-radius:4px;cursor:pointer;font-size:0.7rem;padding:2px 7px;color:var(--navy-soft);margin-right:3px;" title="Editar">\u270f</button>'
          + '<button onclick="finDeleteItem(' + JSON.stringify(it.id) + ')" '
          + 'style="background:none;border:none;cursor:pointer;color:var(--navy-faint);font-size:0.9rem;padding:0 4px;line-height:1;" title="Excluir">\u00d7</button>'
        + '</td>'
        + '</tr>';
    });
    tbody.innerHTML = html;
  };

  /* Re-wire lançamentos category filter button */
  window.finSetLancFilter = function (cat, btn) {
    document.querySelectorAll('.fin-filter-btn[data-lcat]').forEach(function (b) { b.classList.remove('active'); });
    if (btn) btn.classList.add('active');
    window.finRenderLancamentos();
  };

  /* ── §4. finRenderGlobalCredits ─────────────────────────────────────── */
  /*
     Was never exposed on window (only called conditionally).
     Now properly overrides with BRL-converted credit amounts.
     Uses window.getAllFinanceLines() for merged data.
     Credit amounts in _getAll38() keep their original currency,
     so we convert via _toBRL().
  */
  window.finRenderGlobalCredits = function () {
    var all   = _getAll();
    var tbody = document.getElementById('fin-cred-body');
    var empty = document.getElementById('fin-cred-empty');
    if (!tbody) return;
    tbody.innerHTML = '';
    if (!all.cred.length) { if (empty) empty.style.display = ''; return; }
    if (empty) empty.style.display = 'none';

    var typeLabels = {
      client: 'Cr\u00e9dito cliente', supplier: 'Cr\u00e9dito fornecedor',
      internal: 'Ajuste interno', voucher: 'Voucher'
    };
    var today = _today();

    all.cred.forEach(function (c) {
      var origNat = parseFloat(c.originalAmount) || 0;
      var usedNat = parseFloat(c.usedAmount)     || 0;
      var remNat  = Math.max(0, origNat - usedNat);
      /* Convert to BRL */
      var cur     = c.currency || 'BRL';
      var orig    = _toBRL(origNat, cur);
      var used    = _toBRL(usedNat, cur);
      var rem     = _toBRL(remNat,  cur);

      var expired  = c.expiryDate && c.expiryDate < today;
      var status   = expired ? 'Expirado' : rem <= 0 ? 'Utilizado' : 'Dispon\u00edvel';
      var badgeCls = (expired || rem <= 0) ? 'fbadge-void' : 'fbadge-credit';

      var tr = document.createElement('tr');
      tr.innerHTML =
        '<td><span class="fbadge fbadge-credit" style="font-size:0.56rem;">' + _esc(typeLabels[c.creditType] || c.creditType || '\u2014') + '</span></td>' +
        '<td>' + _esc(c.owner || '\u2014') + '</td>' +
        '<td><span style="font-family:monospace;font-size:0.72rem;font-weight:700;color:var(--red);">' + _esc(c._dossierRef || '') + '</span></td>' +
        '<td>' + _esc(c.reason || '\u2014') + '</td>' +
        '<td>' + _dLabel(c.expiryDate) + '</td>' +
        '<td style="text-align:right;font-weight:700;">' + _fmtR(orig) + '</td>' +
        '<td style="text-align:right;">' + _fmtR(used) + '</td>' +
        '<td style="text-align:right;font-weight:700;color:' + (rem > 0 ? '#4338ca' : '#6b7280') + ';">' + _fmtR(rem) + '</td>' +
        '<td><span class="fbadge ' + badgeCls + '">' + status + '</span></td>';
      tbody.appendChild(tr);
    });
  };

  /* ── §5. finRenderReconciliation ─────────────────────────────────────── */
  /*
     Uses window.getAllFinanceLines() (merged BRL data).
     Amounts already in BRL — no secondary conversion needed.
  */
  window.finRenderReconciliation = function () {
    var all    = _getAll();
    var today  = _today();
    var recvEl = document.getElementById('fin-recon-recv');
    var expEl  = document.getElementById('fin-recon-exp');

    /* Receivables not fully reconciled */
    var pendRecv = all.recv.filter(function (r) { return r.status !== 'paid'; });
    if (recvEl) {
      if (!pendRecv.length) {
        recvEl.innerHTML = '<div style="font-size:0.78rem;color:#16a34a;font-weight:600;">\u2713 Todos os recebimentos reconciliados</div>';
      } else {
        recvEl.innerHTML = '<div style="overflow-x:auto;"><table class="fin-table" style="font-size:0.74rem;"><thead><tr>'
          + '<th>Dossier</th><th>Descri\u00e7\u00e3o</th>'
          + '<th style="text-align:right;">Restante (BRL)</th><th>Status</th>'
          + '</tr></thead><tbody>'
          + pendRecv.map(function (r) {
              var bal = (parseFloat(r.amount) || 0) - (parseFloat(r.paidAmount) || 0);
              return '<tr>'
                + '<td style="font-family:monospace;font-size:0.68rem;font-weight:700;color:var(--red);">' + _esc(r._dossierRef || '') + '</td>'
                + '<td>' + _esc(r.description || '') + '</td>'
                + '<td style="text-align:right;font-weight:700;color:var(--red);">' + _fmtR(bal) + '</td>'
                + '<td><span class="fbadge fbadge-pending">' + _esc(r.status || '\u2014') + '</span></td>'
                + '</tr>';
            }).join('')
          + '</tbody></table></div>';
      }
    }

    /* Expenses not fully paid */
    var pendExp = all.exp.filter(function (e) { return e.status !== 'paid'; });
    if (expEl) {
      if (!pendExp.length) {
        expEl.innerHTML = '<div style="font-size:0.78rem;color:#16a34a;font-weight:600;">\u2713 Todas as despesas pagas</div>';
      } else {
        expEl.innerHTML = '<div style="overflow-x:auto;"><table class="fin-table" style="font-size:0.74rem;"><thead><tr>'
          + '<th>Dossier</th><th>Fornecedor</th>'
          + '<th style="text-align:right;">Restante (BRL)</th><th>Status</th>'
          + '</tr></thead><tbody>'
          + pendExp.map(function (e) {
              var bal = (parseFloat(e.amount) || 0) - (parseFloat(e.paidAmount) || 0);
              return '<tr>'
                + '<td style="font-family:monospace;font-size:0.68rem;font-weight:700;color:var(--red);">' + _esc(e._dossierRef || '') + '</td>'
                + '<td>' + _esc(e.supplier || '\u2014') + '</td>'
                + '<td style="text-align:right;font-weight:700;color:#f59e0b;">' + _fmtR(bal) + '</td>'
                + '<td><span class="fbadge fbadge-pending">' + _esc(e.status || '\u2014') + '</span></td>'
                + '</tr>';
            }).join('')
          + '</tbody></table></div>';
      }
    }
  };

  /* ── §6. Re-wire finSwitchTab & finRefresh ───────────────────────────── */
  /*
     Re-override both to ensure all new window.finRender* functions are
     dispatched correctly (no more closure-local references from v3.6/v3.8).
  */
  window.finSwitchTab = function (tab) {
    document.querySelectorAll('.fin-tab').forEach(function (b) {
      b.classList.toggle('active', b.dataset.fintab === tab);
    });
    document.querySelectorAll('.fin-panel').forEach(function (p) {
      p.classList.toggle('active', p.id === 'fin-panel-' + tab);
    });
    if (tab === 'dashboard')      window.finRenderDashboard();
    if (tab === 'fluxo')          window.finRenderFluxo();
    if (tab === 'recebimentos')   window.finRenderRecebimentos();
    if (tab === 'despesas')       window.finRenderDespesas();
    if (tab === 'credits')        window.finRenderGlobalCredits();
    if (tab === 'ledger')         window.finRenderLedger();
    if (tab === 'dossierpl')      window.finRenderDossierPL();
    if (tab === 'reconciliation') window.finRenderReconciliation();
    if (tab === 'lancamentos')    window.finRenderLancamentos();
    if (tab === 'stripe') {
      if (typeof window.finFetchStripeBalance === 'function') window.finFetchStripeBalance();
    }
  };

  window.finRefresh = function () {
    document.querySelectorAll('.fin-tab').forEach(function (b) { b.classList.remove('active'); });
    document.querySelectorAll('.fin-panel').forEach(function (p) { p.classList.remove('active'); });
    var btn = document.querySelector('.fin-tab[data-fintab="dashboard"]');
    var pan = document.getElementById('fin-panel-dashboard');
    if (btn) btn.classList.add('active');
    if (pan) pan.classList.add('active');
    window.finRenderDashboard();
    window.finRenderKPIs();
  };

  console.log('[Patch v3.8-R] Fluxo \xb7 Lan\u00e7amentos \xb7 KPIs \xb7 Credits \xb7 Reconcilia\u00e7\u00e3o \u2192 BRL \xb7 merged data active');

})(); // end Patch v3.8-R

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.9 — Finance Sync
   Guard: window._v39FinSync
   ─ Fixes due dates on cost lines (bizday vs. Volta Cancelada calendar day)
   ─ Writes all cost/tarifcost/PNL entries to Finance > Despesas (global + per-dossier)
   ─ Writes all receivables to Finance > Recebimento (global already done, adds per-dossier)
   ─ Bootstrap: backfills per-dossier Finance from global lancamentos
   ─ Exposes window.v39SyncDossier(id) for manual re-sync
   ══════════════════════════════════════════════════════════════════════════ */
(function() {
  if (window._v39FinSync) return;
  window._v39FinSync = true;

  /* ── Helpers ──────────────────────────────────────────────────────────── */

  function _today39() {
    return new Date().toISOString().slice(0, 10);
  }

  function _nextBizDay39(fromISO) {
    var d = fromISO ? new Date(fromISO.slice(0, 10) + 'T12:00:00') : new Date();
    d.setDate(d.getDate() + 1);
    while (d.getDay() === 0 || d.getDay() === 6) d.setDate(d.getDate() + 1);
    return d.toISOString().slice(0, 10);
  }

  function _nextCalDay39(fromISO) {
    var d = fromISO ? new Date(fromISO.slice(0, 10) + 'T12:00:00') : new Date();
    d.setDate(d.getDate() + 1);
    return d.toISOString().slice(0, 10);
  }

  function _bookedAtDate39(id) {
    if (!id) return _today39();
    var raw = localStorage.getItem('expatur_bookedAt_' + id);
    return raw ? raw.slice(0, 10) : _today39();
  }

  function _dossRef39(id) {
    var dd = null;
    try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null'); } catch(e){}
    return (dd && dd.fields && dd.fields['booking-ref']) || id;
  }

  function _idForRef39(ref) {
    if (!ref) return null;
    var list = [];
    try { list = JSON.parse(localStorage.getItem('expatur_dossier_list') || '[]'); } catch(e){}
    for (var i = 0; i < list.length; i++) {
      var d = list[i];
      var dd = null;
      try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + d.id) || 'null'); } catch(e){}
      if (dd && dd.fields && dd.fields['booking-ref'] === ref) return d.id;
      if (d.label === ref) return d.id;
    }
    return null;
  }

  function _activeId39() {
    return localStorage.getItem('expatur_active_dossier') || null;
  }

  function _firstDep39(id) {
    var ref = _dossRef39(id);
    if (ref) {
      var key = 'expatur_billet_' + ref.replace(/[^a-zA-Z0-9]/g, '_');
      var billet = null;
      try { billet = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e){}
      if (billet && billet.legs && billet.legs[0] && billet.legs[0].depDate) return billet.legs[0].depDate;
    }
    var el = document.getElementById('dep-date-0') || document.getElementById('date-leg1');
    return (el && el.value) ? el.value : _today39();
  }

  function _isVC39(forn) {
    if (!forn) return false;
    var u = forn.toUpperCase();
    return u.indexOf('VOLTA') >= 0 && u.indexOf('CANCEL') >= 0;
  }

  /* ── Global upsert (re-impl of private _finUpsert) ─────────────────── */
  var _FIN_KEY39 = 'expatur_financeiro_lancamentos';

  function _globalUpsert39(rec) {
    var items = [];
    try { items = JSON.parse(localStorage.getItem(_FIN_KEY39) || '[]'); } catch(e){}
    var idx = -1;
    for (var i = 0; i < items.length; i++) {
      if (items[i].source_id && items[i].source_id === rec.source_id) { idx = i; break; }
    }
    var ts = new Date().toISOString();
    if (idx >= 0) {
      items[idx] = Object.assign(items[idx], rec, { updatedAt: ts });
    } else {
      items.push(Object.assign({
        id: 'fin' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),
        createdAt: ts
      }, rec));
    }
    try { localStorage.setItem(_FIN_KEY39, JSON.stringify(items)); } catch(e){}
  }

  /* ── Per-dossier expense upsert ─────────────────────────────────────── */
  function _upsertDE39(id, rec) {
    if (!id || !rec.source_id) return;
    var key = 'expatur_doss_finance_' + id;
    var data = null;
    try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e){}
    if (!data) return; // shell must exist (init'd on BOOK)
    var arr = data.expenses || [];
    var idx = -1;
    for (var i = 0; i < arr.length; i++) {
      if (arr[i].source_id && arr[i].source_id === rec.source_id) { idx = i; break; }
    }
    var ts = new Date().toISOString();
    if (idx >= 0) {
      arr[idx] = Object.assign(arr[idx], rec, { updatedAt: ts });
    } else {
      arr.push(Object.assign({
        id: 'dfe' + Date.now() + '_' + Math.random().toString(36).slice(2, 5),
        createdAt: ts
      }, rec));
    }
    data.expenses = arr;
    try { localStorage.setItem(key, JSON.stringify(data)); } catch(e){}
  }

  /* ── Per-dossier receivable upsert ──────────────────────────────────── */
  function _upsertDR39(id, rec) {
    if (!id || !rec.source_id) return;
    var key = 'expatur_doss_finance_' + id;
    var data = null;
    try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e){}
    if (!data) return;
    var arr = data.receivables || [];
    var idx = -1;
    for (var i = 0; i < arr.length; i++) {
      if (arr[i].source_id && arr[i].source_id === rec.source_id) { idx = i; break; }
    }
    var ts = new Date().toISOString();
    if (idx >= 0) {
      arr[idx] = Object.assign(arr[idx], rec, { updatedAt: ts });
    } else {
      arr.push(Object.assign({
        id: 'dfr' + Date.now() + '_' + Math.random().toString(36).slice(2, 5),
        createdAt: ts
      }, rec));
    }
    data.receivables = arr;
    try { localStorage.setItem(key, JSON.stringify(data)); } catch(e){}
  }

  /* ══════════════════════════════════════════════════════════════
     § 1.  syncCostLinesToDossierFinanceExpensesAndSuppliers
           Fix due dates · add per-dossier write
     ══════════════════════════════════════════════════════════════ */
  if (typeof window.syncCostLinesToDossierFinanceExpensesAndSuppliers === 'function' && !window._v39CostWrap) {
    window._v39CostWrap = true;
    var _origCostSync39 = window.syncCostLinesToDossierFinanceExpensesAndSuppliers;

    window.syncCostLinesToDossierFinanceExpensesAndSuppliers = function(opts) {
      if (!opts || !opts.costLines || !opts.costLines.length) return 0;

      var ref        = opts.dossierRef || '';
      var id         = opts.dossierId || _idForRef39(ref) || _activeId39();
      var bookedDate = _bookedAtDate39(id);
      var firstDep   = id ? _firstDep39(id) : _today39();

      // Recalculate vencimento per business rules
      var patchedLines = opts.costLines.map(function(cl) {
        var venc = _isVC39(cl.fornecedor)
          ? _nextCalDay39(cl.vencimento || firstDep)   // VOLTA CANCELADA: 1 calendar day after departure
          : _nextBizDay39(bookedDate);                  // Default: 1 biz day after booking date
        return Object.assign({}, cl, { vencimento: venc });
      });

      // Original writes to global lancamentos
      var added = _origCostSync39(Object.assign({}, opts, { costLines: patchedLines }));

      // Also write to per-dossier expenses
      if (id) {
        patchedLines.forEach(function(cl) {
          if (!cl.fornecedor || !cl.amount) return;
          var sid = 'emission_' + ref.replace(/[^a-zA-Z0-9]/g, '_')
                  + '_leg' + cl.legIdx + '_' + cl.rid + '_'
                  + cl.fornecedor.replace(/\s+/g, '_').toLowerCase();
          var iso  = (typeof window.normalizeCurrencyCode === 'function')
                   ? window.normalizeCurrencyCode(cl.currency || 'BRL') : 'BRL';
          var rate = (iso === 'BRL') ? 1 : (parseFloat(cl.fx_rate_to_brl) || 1);
          var brl  = (iso === 'BRL') ? parseFloat(cl.amount) : parseFloat(cl.amount) * rate;
          brl = parseFloat(brl.toFixed(2));
          _upsertDE39(id, {
            tipo: 'saida',
            descricao: 'Repasse ' + cl.fornecedor + (ref ? ' \u2014 ' + ref : ''),
            fornecedor: cl.fornecedor,
            amount: brl,
            original_amount: parseFloat(cl.amount),
            original_currency: iso,
            fx_rate_to_brl: rate,
            brl_amount: brl,
            categoria: 'Vari\u00e1veis - Operacional',
            dossierRef: ref,
            vencimento: cl.vencimento,
            pago: 'pendente',
            source_type: 'emission_cost',
            source_id: sid
          });
        });
      }
      return added;
    };
  }

  /* ══════════════════════════════════════════════════════════════
     § 2.  dossFinSyncFromTarification
           Also create Despesas entry for the cost forecast
     ══════════════════════════════════════════════════════════════ */
  if (typeof window.dossFinSyncFromTarification === 'function' && !window._v39TarifWrap) {
    window._v39TarifWrap = true;
    var _origTarifSync39 = window.dossFinSyncFromTarification;

    window.dossFinSyncFromTarification = function() {
      _origTarifSync39(); // original: saves forecast + renders UI
      try {
        var id = localStorage.getItem('expatur_active_dossier');
        if (!id) return;
        var dd = null;
        try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null'); } catch(e){}
        var cost = (dd && dd.finForecast && dd.finForecast.cost) || 0;
        if (!cost) return;
        var ref        = (dd && dd.fields && dd.fields['booking-ref']) || id;
        var bookedDate = _bookedAtDate39(id);
        var sid        = 'tarifcost_' + id;
        var rec = {
          tipo: 'saida',
          descricao: 'Custo Tarifica\u00e7\u00e3o \u2014 ' + ref,
          fornecedor: 'Tarifica\u00e7\u00e3o',
          amount: parseFloat(cost.toFixed(2)),
          original_amount: parseFloat(cost.toFixed(2)),
          original_currency: 'BRL',
          fx_rate_to_brl: 1,
          brl_amount: parseFloat(cost.toFixed(2)),
          categoria: 'Vari\u00e1veis - Operacional',
          dossierRef: ref,
          vencimento: _nextBizDay39(bookedDate),
          pago: 'pendente',
          source_type: 'tarification_cost',
          source_id: sid
        };
        _globalUpsert39(rec);
        _upsertDE39(id, rec);
      } catch(e) { console.warn('[v3.9] dossFinSyncFromTarification expense sync error', e); }
    };
  }

  /* ══════════════════════════════════════════════════════════════
     § 3.  capturePnlSnapshot
           Also sync Stripe fee and commission to Despesas
     ══════════════════════════════════════════════════════════════ */
  if (typeof window.capturePnlSnapshot === 'function' && !window._v39PnlWrap) {
    window._v39PnlWrap = true;
    var _origPnl39 = window.capturePnlSnapshot;

    window.capturePnlSnapshot = function(ref) {
      _origPnl39(ref); // original captures + stores snapshot
      if (!ref) return;
      try {
        var snap = null;
        try { snap = JSON.parse(localStorage.getItem('expatur_pnl_' + ref) || 'null'); } catch(e){}
        if (!snap) return;
        var id         = _idForRef39(ref) || _activeId39();
        var bookedDate = _bookedAtDate39(id);
        var venc       = _nextBizDay39(bookedDate);
        var safeRef    = ref.replace(/[^a-zA-Z0-9]/g, '_');

        // Stripe fee
        if (snap.payMode === 'stripe' && snap.payFee > 0) {
          var sfRec = {
            tipo: 'saida',
            descricao: 'Taxa Stripe \u2014 ' + ref,
            fornecedor: 'Stripe',
            amount: parseFloat(snap.payFee.toFixed(2)),
            original_amount: parseFloat(snap.payFee.toFixed(2)),
            original_currency: 'BRL',
            fx_rate_to_brl: 1,
            brl_amount: parseFloat(snap.payFee.toFixed(2)),
            categoria: 'Custos Financeiros',
            dossierRef: ref,
            vencimento: venc,
            pago: 'pendente',
            source_type: 'pnl_stripe_fee',
            source_id: 'stripefee_' + safeRef
          };
          _globalUpsert39(sfRec);
          if (id) _upsertDE39(id, sfRec);
        }

        // Vendor commission
        if (snap.vendeur && snap.commBRL > 0) {
          var vn      = snap.vendeur.replace(/\s+/g, '_').toLowerCase();
          var commRec = {
            tipo: 'saida',
            descricao: 'Comiss\u00e3o ' + snap.vendeur + ' \u2014 ' + ref,
            fornecedor: snap.vendeur,
            amount: parseFloat(snap.commBRL.toFixed(2)),
            original_amount: parseFloat(snap.commBRL.toFixed(2)),
            original_currency: 'BRL',
            fx_rate_to_brl: 1,
            brl_amount: parseFloat(snap.commBRL.toFixed(2)),
            categoria: 'Comiss\u00f5es',
            dossierRef: ref,
            vencimento: venc,
            pago: 'pendente',
            source_type: 'pnl_commission',
            source_id: 'commission_' + safeRef + '_' + vn
          };
          _globalUpsert39(commRec);
          if (id) _upsertDE39(id, commRec);
        }
      } catch(e) { console.warn('[v3.9] capturePnlSnapshot expense sync error', e); }
    };
  }

  /* ══════════════════════════════════════════════════════════════
     § 4.  syncPaiementToDossierFinanceReceivable
           Also write to per-dossier receivables
     ══════════════════════════════════════════════════════════════ */
  if (typeof window.syncPaiementToDossierFinanceReceivable === 'function' && !window._v39PmtWrap) {
    window._v39PmtWrap = true;
    var _origPmt39 = window.syncPaiementToDossierFinanceReceivable;

    window.syncPaiementToDossierFinanceReceivable = function(opts) {
      _origPmt39(opts); // write to global
      if (!opts || !opts.source_id) return;
      try {
        var ref = opts.dossierRef || '';
        var id  = opts.dossierId || _idForRef39(ref) || _activeId39();
        if (!id) return;
        var iso = (typeof window.normalizeCurrencyCode === 'function')
                ? window.normalizeCurrencyCode(opts.moeda) : 'BRL';
        var brl = parseFloat(opts.brl_amount) ||
                  (iso === 'BRL' ? parseFloat(opts.valor) : null) ||
                  parseFloat(opts.valor) || 0;
        _upsertDR39(id, {
          tipo: 'entrada',
          descricao: opts.descricao || 'Recebimento',
          fornecedor: opts.fornecedor || '',
          amount: parseFloat(brl.toFixed(2)),
          original_amount: parseFloat(opts.valor) || 0,
          original_currency: iso,
          fx_rate_to_brl: opts.fx_rate_to_brl || (iso === 'BRL' ? 1 : null),
          brl_amount: parseFloat(brl.toFixed(2)),
          categoria: 'Receita - Booking',
          dossierRef: ref,
          vencimento: opts.vencimento || _today39(),
          pago: opts.pago || 'pendente',
          source_type: opts.source_type || 'paiement_oob',
          source_id: opts.source_id
        });
      } catch(e) { console.warn('[v3.9] syncPaiement per-dossier error', e); }
    };
  }

  /* ══════════════════════════════════════════════════════════════
     § 5.  createStripe7525Receivables
           Also write instalments to per-dossier receivables
     ══════════════════════════════════════════════════════════════ */
  if (typeof window.createStripe7525Receivables === 'function' && !window._v39StripeWrap) {
    window._v39StripeWrap = true;
    var _origStripe39 = window.createStripe7525Receivables;

    window.createStripe7525Receivables = function(opts) {
      _origStripe39(opts); // write instalments to global
      if (!opts || !opts.source_id) return;
      try {
        var ref   = opts.dossierRef || '';
        var id    = opts.dossierId || _idForRef39(ref) || _activeId39();
        if (!id) return;
        var iso   = (typeof window.normalizeCurrencyCode === 'function')
                  ? window.normalizeCurrencyCode(opts.currency) : 'BRL';
        var gross = parseFloat(opts.gross_amount) || 0;
        var rate  = (iso === 'BRL') ? 1 : (parseFloat(opts.fx_rate_to_brl) || 1);
        var payDate = opts.payment_date || _today39();
        var isPaid  = (opts.status === 'paid' || opts.status === 'pago');
        var descB   = opts.descricao || ('Venda Stripe' + (ref ? ' \u2014 ' + ref : ''));

        function _addD39(dateStr, n) {
          var d = new Date(dateStr + 'T12:00:00'); d.setDate(d.getDate() + n);
          return d.toISOString().slice(0, 10);
        }

        [{ no:1, pct:75, due:payDate,               pago:isPaid?'pago':'pendente' },
         { no:2, pct:25, due:_addD39(payDate, 120), pago:'pendente'              }
        ].forEach(function(inst) {
          var amount = parseFloat((gross * inst.pct / 100).toFixed(2));
          var brl    = (iso === 'BRL') ? amount : parseFloat((amount * rate).toFixed(2));
          var sid    = opts.source_id + '_inst' + inst.no;
          _upsertDR39(id, {
            tipo: 'entrada',
            descricao: descB + ' \u2014 ' + inst.pct + '% inst.' + inst.no,
            fornecedor: opts.fornecedor || '',
            amount: brl,
            original_amount: amount,
            original_currency: iso,
            fx_rate_to_brl: rate,
            brl_amount: brl,
            categoria: 'Receita - Booking',
            dossierRef: ref,
            vencimento: inst.due,
            pago: inst.pago,
            source_type: 'stripe_invoice',
            source_id: sid,
            installment_no: inst.no,
            share_percent: inst.pct
          });
        });
      } catch(e) { console.warn('[v3.9] createStripe75 per-dossier error', e); }
    };
  }

  /* ══════════════════════════════════════════════════════════════
     § 6.  saveBilletData hook
           Trigger cost sync (DOM available) after every billet save
     ══════════════════════════════════════════════════════════════ */
  if (typeof window.saveBilletData === 'function' && !window._v39BilletWrap) {
    window._v39BilletWrap = true;
    var _origSBD39 = window.saveBilletData;
    window.saveBilletData = function() {
      _origSBD39();
      setTimeout(function() {
        try {
          if (typeof window.finAutoCreateCostPayments === 'function') {
            window.finAutoCreateCostPayments();
          }
        } catch(e) { console.warn('[v3.9] saveBilletData cost sync error', e); }
      }, 50);
    };
  }

  /* ══════════════════════════════════════════════════════════════
     § 7.  Bootstrap sync
           Backfill per-dossier Finance from global lancamentos
           for all already-booked dossiers
     ══════════════════════════════════════════════════════════════ */
  function _bootstrapSync39() {
    var list   = []; try { list   = JSON.parse(localStorage.getItem('expatur_dossier_list') || '[]'); } catch(e){}
    var global = []; try { global = JSON.parse(localStorage.getItem(_FIN_KEY39) || '[]'); } catch(e){}
    var count  = 0;

    list.forEach(function(d) {
      var id = d.id;
      if (localStorage.getItem('expatur_booked_' + id) !== '1') return;

      // Ensure finance shell exists
      if (!localStorage.getItem('expatur_doss_finance_' + id)) {
        if (typeof window.dossFIN_init === 'function') {
          try { window.dossFIN_init(id); } catch(e){}
        } else return;
      }

      var ref = _dossRef39(id);

      global.forEach(function(it) {
        if (!it.source_id) return;
        var itRef = it.dossierRef || '';
        if (itRef !== ref && itRef !== id) return;
        var brl = parseFloat(it.brl_amount) || parseFloat(it.valor) || 0;
        var rec = {
          tipo: it.tipo,
          descricao: it.descricao || '',
          fornecedor: it.fornecedor || '',
          amount: brl,
          original_amount: parseFloat(it.original_amount || it.valor) || 0,
          original_currency: it.original_currency || it.moeda || 'BRL',
          fx_rate_to_brl: it.fx_rate_to_brl || 1,
          brl_amount: brl,
          categoria: it.categoria || '',
          dossierRef: ref,
          vencimento: it.vencimento || _today39(),
          pago: it.pago || 'pendente',
          source_type: it.source_type || '',
          source_id: it.source_id
        };
        if (it.tipo === 'saida')   { _upsertDE39(id, rec); count++; }
        if (it.tipo === 'entrada') { _upsertDR39(id, rec); count++; }
      });
    });
    return count;
  }

  /* ══════════════════════════════════════════════════════════════
     § 8.  Public API — window.v39SyncDossier(id)
           Manual full re-sync for a single dossier
     ══════════════════════════════════════════════════════════════ */
  window.v39SyncDossier = function(id) {
    if (!id) id = localStorage.getItem('expatur_active_dossier');
    if (!id) { console.warn('[v3.9] v39SyncDossier: no dossier ID'); return 0; }

    // Ensure shell
    if (!localStorage.getItem('expatur_doss_finance_' + id)) {
      if (typeof window.dossFIN_init === 'function') {
        try { window.dossFIN_init(id); } catch(e){}
      }
    }

    var ref    = _dossRef39(id);
    var global = []; try { global = JSON.parse(localStorage.getItem(_FIN_KEY39) || '[]'); } catch(e){}
    var count  = 0;

    global.forEach(function(it) {
      var itRef = it.dossierRef || '';
      if (itRef !== ref && itRef !== id) return;
      if (!it.source_id) return;
      var brl = parseFloat(it.brl_amount) || parseFloat(it.valor) || 0;
      var rec = {
        tipo: it.tipo,
        descricao: it.descricao || '',
        fornecedor: it.fornecedor || '',
        amount: brl,
        original_amount: parseFloat(it.original_amount || it.valor) || 0,
        original_currency: it.original_currency || it.moeda || 'BRL',
        fx_rate_to_brl: it.fx_rate_to_brl || 1,
        brl_amount: brl,
        categoria: it.categoria || '',
        dossierRef: ref,
        vencimento: it.vencimento || _today39(),
        pago: it.pago || 'pendente',
        source_type: it.source_type || '',
        source_id: it.source_id
      };
      if (it.tipo === 'saida')   { _upsertDE39(id, rec); count++; }
      if (it.tipo === 'entrada') { _upsertDR39(id, rec); count++; }
    });

    if (typeof window.dossFinRenderPanel === 'function') {
      try { window.dossFinRenderPanel(); } catch(e){}
    }
    console.log('[v3.9] v39SyncDossier(' + id + ') — ' + count + ' records synced to per-dossier');
    return count;
  };

  /* ── Run bootstrap on load ────────────────────────────────────── */
  try {
    var _bc = _bootstrapSync39();
    console.log('[Patch v3.9] Finance Sync active \u2014 due-date fix \u00b7 per-dossier write \u00b7 PNL/Tarifcost \u00b7 Recebimento \u00b7 ' + _bc + ' records bootstrapped');
  } catch(e) {
    console.warn('[Patch v3.9] bootstrap error', e);
  }

})(); // end Patch v3.9

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.10 — Unified Despesas Renderer
   Guard: window._v310ExpensesFix

   ROOT CAUSES FIXED:
   1. _v36RenderExpenses filters global records by dossierRef using storage value
      (_v36DossRef reads expatur_dossier_[id].fields['booking-ref']).
      If the user changed the booking-ref DOM field without an explicit dossier
      save (saveBilletData does NOT save to expatur_dossier_[id]), the stored ref
      is stale. The sync writes dossierRef = DOM value. These two differ → filter
      returns zero records → Despesas tab appears empty.
   2. When _v36DossLoad(id) returns null (finance shell not yet created),
      the v3.6 panel falls back to the original _renderExpenses which reads only
      data.expenses (legacy old-style fields). Synced records (fornecedor/categoria/
      vencimento/pago/brl_amount) are not shown; renderer expects supplier/category/
      dueDate/status/paidAmount — the field mismatch the user reported.
   3. No auto-refresh on dossFinTab('expenses') after cost sync completes.

   FIX STRATEGY:
   - Replace window._v36RenderExpenses (the function v3.8 already calls) with a
     fully unified renderer that:
     a) Matches global records by STORAGE ref OR DOSSIER ID OR DOM booking-ref
        value (three-way lookup) → eliminates stale-ref miss
     b) Works safely when data (finance shell) is null
     c) Normalises both new-style (fornecedor/vencimento/pago/brl_amount) and
        legacy old-style (supplier/dueDate/status/paidAmount) fields
     d) Deduplicates global vs local by source_id
     e) Shows BRL totals in footer
   - Also override window.dossFinRenderPanel so the expenses tab always routes to
     the new renderer even when the DOM tab query returns null (fallback via
     _dossFinActiveTab captured from original call)
   ══════════════════════════════════════════════════════════════════════════ */
(function() {
  if (window._v310ExpensesFix) return;
  window._v310ExpensesFix = true;

  var _FIN_KEY310 = 'expatur_financeiro_lancamentos';

  /* ── Helpers ────────────────────────────────────────────────────────── */

  function _esc310(s) {
    return (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function _dateLbl310(d) {
    if (!d) return '\u2014';
    var p = (d + '').split('-');
    return p.length === 3 ? p[2] + '/' + p[1] + '/' + p[0] : d;
  }

  function _fmtBRL310(v) {
    var n = parseFloat(v) || 0;
    return 'R$\u00a0' + n.toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  function _brlOf310(r) {
    if (!r) return 0;
    var brl = parseFloat(r.brl_amount);
    if (!isNaN(brl) && brl > 0) return brl;
    if (typeof window._fxEntryToBRL === 'function') {
      try { var v = window._fxEntryToBRL(r); if (v > 0) return v; } catch(e){}
    }
    var iso  = r.original_currency || r.moeda || r.currency || 'BRL';
    var rate = parseFloat(r.fx_rate_to_brl) || 1;
    var raw  = parseFloat(r.original_amount != null ? r.original_amount : (r.amount != null ? r.amount : r.valor)) || 0;
    return (iso === 'BRL') ? raw : raw * rate;
  }

  function _finLoad310() {
    try { return JSON.parse(localStorage.getItem(_FIN_KEY310) || '[]'); } catch(e) { return []; }
  }

  // Multi-strategy dossier-ref lookup:
  //   1. expatur_dossier_[id].fields['booking-ref']   (canonical storage)
  //   2. The active dossier ID itself                 (fallback)
  //   3. DOM booking-ref input value                  (live DOM — survives stale storage)
  function _dossRefs310(id) {
    var refs = {};
    if (id) refs[id] = true;
    // Storage ref
    try {
      var dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null');
      if (dd && dd.fields && dd.fields['booking-ref']) refs[dd.fields['booking-ref']] = true;
    } catch(e){}
    // DOM ref (handles stale-storage case)
    try {
      var domRef = ((document.getElementById('booking-ref') || {}).value || '').trim();
      if (domRef) refs[domRef] = true;
    } catch(e){}
    return refs;
  }

  /* ── Normalise any expense record to a unified display struct ────── */
  function _normalizeExp310(r) {
    // Detect new-style synced records: have tipo:'saida' or fornecedor/categoria fields
    var isNew = r.tipo === 'saida' ||
                r.fornecedor !== undefined ||
                r.categoria  !== undefined ||
                r.vencimento !== undefined ||
                r.source_type !== undefined;

    var brl;
    if (isNew) {
      brl = _brlOf310(r);
      var pago      = r.pago || 'pendente';
      var statusKey = pago === 'pago' ? 'paid' : (pago === 'atrasado' ? 'overdue' : 'pending');
      return {
        _id:       r.source_id || r.id || '',
        supplier:  r.fornecedor || r.supplier || '\u2014',
        category:  r.categoria  || r.category  || '\u2014',
        dateVal:   r.vencimento || r.dueDate   || '',
        statusKey: statusKey,
        pnrRef:    r.source_id  || r.pnrRef    || '',
        brl:       brl,
        paidBRL:   pago === 'pago' ? brl : 0,
        remBRL:    pago === 'pago' ? 0   : brl,
        notes:     r.nota || r.notes || '',
        isSync:    true   // show "sync" badge, no edit/delete
      };
    }

    // Legacy old-style (manual entries with supplier/dueDate/status)
    var amt   = parseFloat(r.amount)     || 0;
    var paid  = parseFloat(r.paidAmount) || 0;
    brl = _brlOf310(r) || amt;
    var status  = r.status || 'draft';
    var isPaid  = (status === 'paid' || status === 'pago');
    var remFrac = (amt > 0) ? Math.max(0, amt - paid) / amt : 1;
    return {
      _id:       r.id || '',
      supplier:  r.supplier || '\u2014',
      category:  r.category || '\u2014',
      dateVal:   r.dueDate  || '',
      statusKey: isPaid ? 'paid' : (status === 'overdue' ? 'overdue' : (status === 'confirmed' ? 'confirmed' : 'pending')),
      pnrRef:    r.pnrRef   || '',
      brl:       brl,
      paidBRL:   isPaid ? brl : (amt > 0 ? brl * paid / amt : 0),
      remBRL:    isPaid ? 0   : brl * remFrac,
      notes:     r.notes || '',
      isSync:    false  // has edit/delete buttons
    };
  }

  /* ══════════════════════════════════════════════════════════════════
     Unified Despesas renderer
     Reads from:
       1. Global expatur_financeiro_lancamentos (tipo=saida, dossierRef match)
       2. Per-dossier data.expenses (old-style manual entries not in global)
     Normalises both old and new field schemas → renders in BRL
  ══════════════════════════════════════════════════════════════════ */
  function _renderExpenses310(id, data) {
    var tbody   = document.getElementById('doss-fin-exp-body');
    var empty   = document.getElementById('doss-fin-exp-empty');
    var totalEl = document.getElementById('doss-fin-exp-total');
    if (!tbody) return;

    // Build set of all valid dossierRef values for this dossier
    var refs = _dossRefs310(id);   // {ref1: true, id: true, domRef: true}

    // Load global synced expense records matching this dossier
    var globalRecs = _finLoad310().filter(function(r) {
      return r.tipo === 'saida' && refs[r.dossierRef || ''];
    });

    // Build dedup set from global records
    var gSids = Object.create(null);
    globalRecs.forEach(function(r) {
      if (r.source_id) gSids[r.source_id] = true;
      if (r.id)        gSids[r.id]        = true;
    });

    // Local-only records (manual entries not already in global by source_id/id)
    var localOnly = ((data && data.expenses) || []).filter(function(e) {
      return !(e.id && gSids[e.id]) && !(e.source_id && gSids[e.source_id]);
    });

    var allRows = globalRecs.concat(localOnly);
    tbody.innerHTML = '';

    if (!allRows.length) {
      if (empty)   empty.style.display = '';
      if (totalEl) totalEl.innerHTML   = '';
      return;
    }
    if (empty) empty.style.display = 'none';

    var BADGE  = { paid:'fbadge-paid', confirmed:'fbadge-confirmed', pending:'fbadge-pending', overdue:'fbadge-overdue', draft:'fbadge-draft' };
    var LABELS = { paid:'Pago',        confirmed:'Confirmado',       pending:'Pendente',       overdue:'Vencido',        draft:'Rascunho'    };

    var totalBRL = 0, paidBRL = 0;

    allRows.forEach(function(r) {
      var n = _normalizeExp310(r);
      totalBRL += n.brl;
      paidBRL  += n.paidBRL;

      var badgeCls    = BADGE[n.statusKey]  || 'fbadge-draft';
      var statusLabel = LABELS[n.statusKey] || n.statusKey;
      var actionCell  = n.isSync
        ? '<span style="font-size:0.6rem;color:var(--navy-faint);">sync</span>'
        : '<button class="db-action-btn" onclick="dossFinEditLine(\'exp\',\'' + _esc310(n._id) + '\')" title="Editar">&#9999;</button>' +
          '<button class="db-action-btn del" onclick="dossFinDeleteLine(\'exp\',\'' + _esc310(n._id) + '\')" title="Apagar">&times;</button>';

      var tr = document.createElement('tr');
      tr.innerHTML =
        '<td>' + _esc310(n.supplier) + '</td>' +
        '<td><span class="fbadge fbadge-draft" style="font-size:0.54rem;">' + _esc310(n.category) + '</span></td>' +
        '<td>' + _dateLbl310(n.dateVal) + '</td>' +
        '<td class="td-status"><span class="fbadge ' + badgeCls + '">' + statusLabel + '</span></td>' +
        '<td style="font-family:monospace;font-size:0.72rem;color:var(--gold);">' + _esc310(n.pnrRef) + '</td>' +
        '<td class="td-amt">' + _fmtBRL310(n.brl) + '</td>' +
        '<td class="td-amt" style="color:#16a34a;">' + _fmtBRL310(n.paidBRL) + '</td>' +
        '<td class="td-amt" style="color:' + (n.remBRL > 0 ? 'var(--red)' : '#16a34a') + ';">' + _fmtBRL310(n.remBRL) + '</td>' +
        '<td style="font-size:0.72rem;color:var(--navy-faint);">' + _esc310(n.notes) + '</td>' +
        '<td style="white-space:nowrap;">' + actionCell + '</td>';
      tbody.appendChild(tr);
    });

    if (totalEl) {
      var remBRL = totalBRL - paidBRL;
      totalEl.innerHTML =
        '<span style="color:var(--navy-soft);font-size:0.72rem;">Total:</span> <strong>' + _fmtBRL310(totalBRL) + '</strong>' +
        '&nbsp;&nbsp;<span style="color:var(--navy-soft);font-size:0.72rem;">Pago:</span> <strong style="color:#16a34a;">' + _fmtBRL310(paidBRL) + '</strong>' +
        '&nbsp;&nbsp;<span style="color:var(--navy-soft);font-size:0.72rem;">Restante:</span> <strong style="color:' + (remBRL > 0 ? 'var(--red)' : '#16a34a') + ';">' + _fmtBRL310(remBRL) + '</strong>';
    }
  }

  /* ── Replace window._v36RenderExpenses ──────────────────────────
     v3.8 already calls window._v36RenderExpenses(id, data) for the
     expenses tab. Replacing it here means the corrected renderer runs
     without needing another dossFinRenderPanel override layer.
  ────────────────────────────────────────────────────────────────── */
  window._v36RenderExpenses = _renderExpenses310;

  /* ── Extra safety: override dossFinRenderPanel for expenses tab ──
     Guards against the case where DOM tab query returns null (no
     .doss-fin-tab.active element found) and the chain falls back to
     the original IIFE renderer that reads only data.expenses.
  ────────────────────────────────────────────────────────────────── */
  var _prev310 = window.dossFinRenderPanel;
  window.dossFinRenderPanel = function() {
    var id = localStorage.getItem('expatur_active_dossier');
    if (!id) { if (typeof _prev310 === 'function') _prev310.call(this); return; }

    // Detect active doss-fin tab from DOM
    var activeBtn = document.querySelector('.doss-fin-tab.active');
    var tab = activeBtn ? activeBtn.dataset.dftab : null;

    if (tab === 'expenses') {
      // Always use the unified renderer regardless of whether finance shell exists
      var data = null;
      try { data = JSON.parse(localStorage.getItem('expatur_doss_finance_' + id) || 'null'); } catch(e){}
      // Auto-init shell if booked and missing
      if (!data && localStorage.getItem('expatur_booked_' + id) === '1') {
        if (typeof window.dossFIN_init === 'function') {
          try { data = window.dossFIN_init(id); } catch(e){}
        }
      }
      if (!data && localStorage.getItem('expatur_booked_' + id) !== '1') {
        // Unbooked: show Finance-not-available message via prev chain
        if (typeof _prev310 === 'function') _prev310.call(this);
        return;
      }
      _renderExpenses310(id, data);
      return;
    }

    // All other tabs: delegate to previous chain
    if (typeof _prev310 === 'function') _prev310.call(this);
  };

  /* ── Hook dossFinTab to guarantee re-render after cost sync ─────
     The v3.8 finAutoCreateCostPayments wrapper calls dossFinRenderPanel
     after 150ms, but it renders the currently active tab (usually
     'overview'). When the user then manually clicks 'Despesas', the
     tab click triggers the corrected renderer. No extra hook needed —
     window.dossFinRenderPanel now correctly routes expenses → _renderExpenses310.
     However, expose a convenience function for manual refresh:
  ────────────────────────────────────────────────────────────────── */
  window.v310RefreshDespesas = function() {
    var id = localStorage.getItem('expatur_active_dossier');
    if (!id) return;
    var data = null;
    try { data = JSON.parse(localStorage.getItem('expatur_doss_finance_' + id) || 'null'); } catch(e){}
    _renderExpenses310(id, data);
  };

  /* ── Also hook finAutoCreateCostPayments to trigger Despesas
     refresh if Despesas tab is currently visible ─────────────────── */
  if (typeof window.finAutoCreateCostPayments === 'function' && !window._v310CostRefreshW) {
    window._v310CostRefreshW = true;
    var _prev310CostPay = window.finAutoCreateCostPayments;
    window.finAutoCreateCostPayments = function() {
      if (typeof _prev310CostPay === 'function') _prev310CostPay.apply(this, arguments);
      setTimeout(function() {
        try {
          // Refresh Despesas if it's the active doss-fin tab
          var activeBtn = document.querySelector('.doss-fin-tab.active');
          if (activeBtn && activeBtn.dataset.dftab === 'expenses') {
            window.v310RefreshDespesas();
          } else {
            // Otherwise schedule a full panel refresh so totals stay in sync
            window.dossFinRenderPanel();
          }
        } catch(e){}
      }, 200);
    };
  }

  console.log('[Patch v3.10] Unified Despesas renderer active \u2014 multi-ref match \u00b7 field normalisation \u00b7 BRL totals \u00b7 null-safe');

})(); // end Patch v3.10

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.11 — Bookings Layout Fix
   Guard: window._v311BookingsLayout

   ROOT CAUSE:
   Two compounding issues cause the page cut and header overlap:

   A) #bookings-detail uses position:absolute; inset:0; z-index:20
      • It's positioned relative to #section-bookings (position:relative)
      • The main .topbar is position:sticky; z-index:300 — outside the section,
        NOT inside .app-shell, so it stays visible when the bookings section opens
      • The topbar (z-index:300) sits ABOVE the detail overlay (z-index:20),
        covering the .bkd-topbar and the top ~65-77px of every booking detail view
      • Additionally, #section-bookings has overflow:hidden, so the absolute child
        is clipped to the section's bounding box — if that box is ever shorter than
        the viewport due to flex layout quirks, content is silently cut off

   B) #section-bookings has overflow:hidden (overrides .section-page overflow-y:auto)
      • Clips the bookings list when it has more rows than can fit in ~100vh
      • Combined with display:flex; flex-direction:column, the flex container does
        not grow beyond its initial height, so table rows beyond the first screen
        are invisible (overflow:hidden cuts them)

   FIX:
   1. Change #bookings-detail.open to position:fixed; inset:0; z-index:350
      → escapes the overflow:hidden clip from parent
      → covers the entire viewport (z-index 350 > topbar 300, < sidebar 500)
      → .bkd-topbar (sticky top:0 inside) now sticks to viewport top, fully visible
      → topbar is visually covered by the detail overlay (desired: clean full-screen view)

   2. Change #section-bookings.open overflow to overflow-y:auto
      → restores scrollability for the bookings list
      → matches the original .section-page intent (overflow-y:auto)
   ══════════════════════════════════════════════════════════════════════════ */
(function() {
  if (window._v311BookingsLayout) return;
  window._v311BookingsLayout = true;

  /* ── Inject CSS overrides ──────────────────────────────────────────── */
  var style = document.createElement('style');
  style.id = 'patch-v311-bookings';
  style.textContent =
    /* ── Fix A: bookings detail overlay ──────────────────────────────────
       Switch from position:absolute (clips behind topbar, clipped by overflow:hidden)
       to position:fixed (full viewport, above topbar z-index:300, below sidebar z-index:500).
       overflow-y:auto restated explicitly so the detail scrolls internally.        */
    '#bookings-detail.open{' +
      'position:fixed!important;' +
      'top:0!important;right:0!important;bottom:0!important;left:0!important;' +
      'z-index:350!important;' +
      'overflow-y:auto!important;' +
    '}' +

    /* ── Fix E: desktop sidebar offset — sidebar always visible ── */
    '@media(min-width:769px){' +
      '#bookings-detail.open{' +
        'left:230px!important;' +
        'width:calc(100vw - 230px)!important;' +
      '}' +
    '}' +

    /* ── Fix B: bookings list section ─────────────────────────────────────
       Remove overflow:hidden (clips rows beyond initial height).
       Restore overflow-y:auto so long lists are scrollable within the section.
       Ensure min-height:100vh so the section fills the viewport.                  */
    '#section-bookings.open{' +
      'overflow:visible!important;' +
      'overflow-y:auto!important;' +
      'min-height:100vh;' +
    '}' +

    /* ── Fix C: toolbar offset ─────────────────────────────────────────────
       .bk-toolbar is sticky top:77px (accounts for visible main topbar).
       When the detail overlay is open, it covers everything anyway, so no
       change needed for the toolbar itself. But ensure the toolbar doesn't
       sit on top of the bookings-detail when both are present:               */
    '.bk-toolbar{z-index:10;}' +

    /* ── Fix D: .bkd-topbar inside the fixed overlay ───────────────────────
       With the detail now position:fixed, bkd-topbar (position:sticky; top:0)
       sticks to the top of the fixed container = top of viewport.
       z-index raised above any other sticky elements inside the detail:        */
    '.bkd-topbar{position:sticky;top:0;z-index:20;}';

  document.head.appendChild(style);

  /* ── Scroll-to-top when opening detail ─────────────────────────────── */
  if (typeof window.bookingsOpenDetail === 'function' && !window._v311BkdWrap) {
    window._v311BkdWrap = true;
    var _origBkOpen = window.bookingsOpenDetail;
    window.bookingsOpenDetail = function(dossierId) {
      _origBkOpen(dossierId);
      // With position:fixed, the detail element scrolls independently.
      // Scroll-to-top is already called inside bookingsOpenDetail (det.scrollTop=0)
      // but ensure body scroll position is also reset to avoid visual jump:
      try { window.scrollTo(0, 0); } catch(e) {}
    };
  }

  console.log('[Patch v3.11] Bookings layout fixed \u2014 detail=position:fixed z-index:350 \u00b7 section overflow restored');
})(); // end Patch v3.11

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.12 — P&L Total Cost Sync
   Guard: window._v312PnlTotalCost

   ROOT CAUSE:
   The v3.9 capturePnlSnapshot override reads snap.payFee and snap.commBRL
   but never reads snap.totalCost. The total operational cost from the Cost
   Calculator (miles-grand-total, always in BRL) is captured in the snapshot
   but never written to Finance > Despesas.

   FIX:
   Wrap the current window.capturePnlSnapshot (= v3.9 override) to also
   upsert a pnl_total_cost record immediately after the existing fee/commission
   sync. Stable source_id: 'pnl_total_cost__[safeRef]'.

   RENDERING:
   The v3.10 _renderExpenses310 renderer already includes all tipo:'saida'
   records filtered by dossierRef — no renderer changes needed. pnl_total_cost
   rows normalise via _normalizeExp310's new-style path (fornecedor/categoria/
   vencimento/pago/brl_amount) and appear in the table and footer totals.
   ══════════════════════════════════════════════════════════════════════════ */
(function() {
  if (window._v312PnlTotalCost) return;
  window._v312PnlTotalCost = true;

  var _FIN312 = 'expatur_financeiro_lancamentos';

  /* ── Private helpers (same pattern as v3.9 — needed because v3.9 helpers
     are IIFE-private and not exposed on window) ────────────────────────── */

  function _today312() { return new Date().toISOString().slice(0, 10); }

  function _nextBizDay312(fromISO) {
    var d = fromISO ? new Date(fromISO.slice(0, 10) + 'T12:00:00') : new Date();
    d.setDate(d.getDate() + 1);
    while (d.getDay() === 0 || d.getDay() === 6) d.setDate(d.getDate() + 1);
    return d.toISOString().slice(0, 10);
  }

  function _bookedAt312(id) {
    if (!id) return _today312();
    var raw = localStorage.getItem('expatur_bookedAt_' + id);
    return raw ? raw.slice(0, 10) : _today312();
  }

  function _idForRef312(ref) {
    if (!ref) return null;
    var list = []; try { list = JSON.parse(localStorage.getItem('expatur_dossier_list') || '[]'); } catch(e){}
    for (var i = 0; i < list.length; i++) {
      var dd = null; try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + list[i].id) || 'null'); } catch(e){}
      if (dd && dd.fields && dd.fields['booking-ref'] === ref) return list[i].id;
      if (list[i].label === ref) return list[i].id;
    }
    return null;
  }

  function _activeId312() { return localStorage.getItem('expatur_active_dossier') || null; }

  function _globalUpsert312(rec) {
    var items = []; try { items = JSON.parse(localStorage.getItem(_FIN312) || '[]'); } catch(e){}
    var idx = -1;
    for (var i = 0; i < items.length; i++) {
      if (items[i].source_id && items[i].source_id === rec.source_id) { idx = i; break; }
    }
    var ts = new Date().toISOString();
    if (idx >= 0) {
      items[idx] = Object.assign(items[idx], rec, { updatedAt: ts });
    } else {
      items.push(Object.assign({ id: 'fin' + Date.now() + '_' + Math.random().toString(36).slice(2, 6), createdAt: ts }, rec));
    }
    try { localStorage.setItem(_FIN312, JSON.stringify(items)); } catch(e){}
  }

  function _upsertDE312(id, rec) {
    if (!id || !rec.source_id) return;
    var key  = 'expatur_doss_finance_' + id;
    var data = null; try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e){}
    if (!data) return;
    var arr  = data.expenses || [];
    var idx  = -1;
    for (var i = 0; i < arr.length; i++) {
      if (arr[i].source_id && arr[i].source_id === rec.source_id) { idx = i; break; }
    }
    var ts = new Date().toISOString();
    if (idx >= 0) {
      arr[idx] = Object.assign(arr[idx], rec, { updatedAt: ts });
    } else {
      arr.push(Object.assign({ id: 'dfe' + Date.now() + '_' + Math.random().toString(36).slice(2, 5), createdAt: ts }, rec));
    }
    data.expenses = arr;
    try { localStorage.setItem(key, JSON.stringify(data)); } catch(e){}
  }

  /* ══════════════════════════════════════════════════════════════
     Override capturePnlSnapshot
     Wraps the v3.9 override, which itself wraps the original.
     Adds the missing pnl_total_cost record.
  ══════════════════════════════════════════════════════════════ */
  if (typeof window.capturePnlSnapshot === 'function' && !window._v312PnlWrap) {
    window._v312PnlWrap = true;
    var _prev312Pnl = window.capturePnlSnapshot;

    window.capturePnlSnapshot = function(ref) {
      _prev312Pnl(ref); // runs full chain: original → v3.9 (stripe_fee + commission)
      if (!ref) return;
      try {
        // Read back the snapshot that the original just stored
        var snap = null;
        try { snap = JSON.parse(localStorage.getItem('expatur_pnl_' + ref) || 'null'); } catch(e){}
        if (!snap) return;

        // The totalCost field is in BRL (stripped from miles-grand-total R$ widget)
        var totalCost = parseFloat(snap.totalCost) || 0;
        if (totalCost <= 0) return; // nothing to sync if no cost entered

        var id         = _idForRef312(ref) || _activeId312();
        var bookedDate = _bookedAt312(id);
        var venc       = _nextBizDay312(bookedDate);
        var safeRef    = ref.replace(/[^a-zA-Z0-9]/g, '_');

        // Stable source_id — deterministic per dossier ref, so re-saves update
        // the same record rather than creating duplicates
        var sid = 'pnl_total_cost__' + safeRef;

        var rec = {
          tipo:              'saida',
          descricao:         'Custo total P\u0026L \u2014 ' + ref,
          fornecedor:        'Custo Operacional',
          amount:            parseFloat(totalCost.toFixed(2)),
          original_amount:   parseFloat(totalCost.toFixed(2)),
          original_currency: 'BRL',
          fx_rate_to_brl:    1,
          brl_amount:        parseFloat(totalCost.toFixed(2)),
          categoria:         'pnl_cost',
          dossierRef:        ref,
          vencimento:        venc,
          pago:              'pendente',
          nota:              'Synced from P\u0026L total cost',
          source_type:       'pnl_total_cost',
          source_id:         sid,
          recorrente:        false
        };

        _globalUpsert312(rec);    // → expatur_financeiro_lancamentos
        if (id) _upsertDE312(id, rec); // → expatur_doss_finance_[id].expenses[]

      } catch(e) { console.warn('[v3.12] pnl_total_cost sync error', e); }
    };
  }

  /* ══════════════════════════════════════════════════════════════
     Manual re-sync for any dossier whose P&L snapshot is already
     stored but whose pnl_total_cost record was never written.
     Runs once on page load — safe (upsert is idempotent).
  ══════════════════════════════════════════════════════════════ */
  (function _backfillPnlTotalCost() {
    var list = []; try { list = JSON.parse(localStorage.getItem('expatur_dossier_list') || '[]'); } catch(e){}
    var count = 0;
    list.forEach(function(d) {
      var id = d.id;
      var dd = null; try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null'); } catch(e){}
      var ref = (dd && dd.fields && dd.fields['booking-ref']) || '';
      if (!ref) return;
      var snap = null; try { snap = JSON.parse(localStorage.getItem('expatur_pnl_' + ref) || 'null'); } catch(e){}
      if (!snap) return;
      var totalCost = parseFloat(snap.totalCost) || 0;
      if (totalCost <= 0) return;
      var items = []; try { items = JSON.parse(localStorage.getItem(_FIN312) || '[]'); } catch(e){}
      var safeRef = ref.replace(/[^a-zA-Z0-9]/g, '_');
      var sid     = 'pnl_total_cost__' + safeRef;
      var exists  = items.some(function(x) { return x.source_id === sid; });
      if (exists) return; // already synced — don't overwrite
      var bookedDate = _bookedAt312(id);
      var venc = _nextBizDay312(bookedDate);
      var rec = {
        tipo:'saida', descricao:'Custo total P\u0026L \u2014 '+ref,
        fornecedor:'Custo Operacional',
        amount:parseFloat(totalCost.toFixed(2)),
        original_amount:parseFloat(totalCost.toFixed(2)),
        original_currency:'BRL', fx_rate_to_brl:1,
        brl_amount:parseFloat(totalCost.toFixed(2)),
        categoria:'pnl_cost', dossierRef:ref, vencimento:venc,
        pago:'pendente', nota:'Synced from P\u0026L total cost (backfill)',
        source_type:'pnl_total_cost', source_id:sid, recorrente:false
      };
      _globalUpsert312(rec);
      _upsertDE312(id, rec);
      count++;
    });
    if (count > 0) console.log('[v3.12] backfill: ' + count + ' pnl_total_cost record(s) added');
  })();

  console.log('[Patch v3.12] P\u0026L total cost sync active \u2014 source_id pattern: pnl_total_cost__[ref]');

})(); // end Patch v3.12

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.13 — Row-by-row Cost Calculator → Finance > Despesas
   Guard: window._v313CostCalcRows

   ROOT CAUSE:
   The v3.9 dossFinSyncFromTarification wrapper reads only the grand total
   from #miles-grand-total and creates a single consolidated record:
     source_id: 'tarifcost_[dossierId]'
   This gives one expense line for the entire Cost Calculator tab,
   regardless of how many individual programme rows the user entered.

   FIX:
   Wrap the current window.dossFinSyncFromTarification (= v3.9 override)
   so that AFTER the original chain runs we:
     1. Iterate every .miles-row-wrap in #miles-rows
     2. For each row, read the programme selector (mc-sel-${rid}) and the
        computed BRL subtotal display (mc-sub-${rid})
     3. Upsert one expense record per row:
          source_type: 'cost_calculator_line'
          source_id:   'costcalc_line__[dossierId]__[rid]'
     4. Delete any stale costcalc_line__ records for this dossier whose
        rid is no longer present in the DOM (row was removed by user)
     5. Delete / suppress the old consolidated tarifcost_[id] record so it
        no longer pollutes Despesas (done via removing it from both stores)

   The v3.10 _renderExpenses310 renderer already shows all tipo:'saida'
   records filtered by dossierRef — no renderer changes needed.
   ══════════════════════════════════════════════════════════════════════════ */
(function() {
  if (window._v313CostCalcRows) return;
  window._v313CostCalcRows = true;

  var _FIN313 = 'expatur_financeiro_lancamentos';

  /* ── Private helpers (same pattern as v3.9 / v3.12) ──────────────────── */

  function _today313() { return new Date().toISOString().slice(0, 10); }

  function _nextBizDay313(fromISO) {
    var d = fromISO ? new Date(fromISO.slice(0, 10) + 'T12:00:00') : new Date();
    d.setDate(d.getDate() + 1);
    while (d.getDay() === 0 || d.getDay() === 6) d.setDate(d.getDate() + 1);
    return d.toISOString().slice(0, 10);
  }

  function _bookedAt313(id) {
    if (!id) return _today313();
    var raw = localStorage.getItem('expatur_bookedAt_' + id);
    return raw ? raw.slice(0, 10) : _today313();
  }

  function _activeId313() { return localStorage.getItem('expatur_active_dossier') || null; }

  function _idForRef313(ref) {
    if (!ref) return null;
    var list = []; try { list = JSON.parse(localStorage.getItem('expatur_dossier_list') || '[]'); } catch(e){}
    for (var i = 0; i < list.length; i++) {
      var dd = null; try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + list[i].id) || 'null'); } catch(e){}
      if (dd && dd.fields && dd.fields['booking-ref'] === ref) return list[i].id;
      if (list[i].label === ref) return list[i].id;
    }
    return null;
  }

  function _finLoad313() {
    try { return JSON.parse(localStorage.getItem(_FIN313) || '[]'); } catch(e) { return []; }
  }

  function _finSave313(items) {
    try { localStorage.setItem(_FIN313, JSON.stringify(items)); } catch(e){}
  }

  function _globalUpsert313(rec) {
    var items = _finLoad313();
    var idx = -1;
    for (var i = 0; i < items.length; i++) {
      if (items[i].source_id && items[i].source_id === rec.source_id) { idx = i; break; }
    }
    var ts = new Date().toISOString();
    if (idx >= 0) {
      items[idx] = Object.assign(items[idx], rec, { updatedAt: ts });
    } else {
      items.push(Object.assign({ id: 'fin' + Date.now() + '_' + Math.random().toString(36).slice(2, 6), createdAt: ts }, rec));
    }
    _finSave313(items);
  }

  function _globalDeleteBySid313(sid) {
    var items = _finLoad313();
    var filtered = items.filter(function(r) { return r.source_id !== sid; });
    if (filtered.length !== items.length) _finSave313(filtered);
  }

  // Remove all global records whose source_id starts with a given prefix
  function _globalDeleteByPrefix313(prefix) {
    var items = _finLoad313();
    var filtered = items.filter(function(r) { return !(r.source_id && r.source_id.indexOf(prefix) === 0); });
    if (filtered.length !== items.length) _finSave313(filtered);
  }

  function _upsertDE313(id, rec) {
    if (!id || !rec.source_id) return;
    var key  = 'expatur_doss_finance_' + id;
    var data = null; try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e){}
    if (!data) return;
    var arr  = data.expenses || [];
    var idx  = -1;
    for (var i = 0; i < arr.length; i++) {
      if (arr[i].source_id && arr[i].source_id === rec.source_id) { idx = i; break; }
    }
    var ts = new Date().toISOString();
    if (idx >= 0) {
      arr[idx] = Object.assign(arr[idx], rec, { updatedAt: ts });
    } else {
      arr.push(Object.assign({ id: 'dfe' + Date.now() + '_' + Math.random().toString(36).slice(2, 5), createdAt: ts }, rec));
    }
    data.expenses = arr;
    try { localStorage.setItem(key, JSON.stringify(data)); } catch(e){}
  }

  function _deleteDEBySid313(id, sid) {
    if (!id || !sid) return;
    var key  = 'expatur_doss_finance_' + id;
    var data = null; try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e){}
    if (!data) return;
    var arr = (data.expenses || []).filter(function(r) { return r.source_id !== sid; });
    data.expenses = arr;
    try { localStorage.setItem(key, JSON.stringify(data)); } catch(e){}
  }

  // Remove per-dossier expense rows whose source_id starts with a given prefix
  function _deleteDEByPrefix313(id, prefix) {
    if (!id || !prefix) return;
    var key  = 'expatur_doss_finance_' + id;
    var data = null; try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e){}
    if (!data) return;
    var arr = (data.expenses || []).filter(function(r) {
      return !(r.source_id && r.source_id.indexOf(prefix) === 0);
    });
    data.expenses = arr;
    try { localStorage.setItem(key, JSON.stringify(data)); } catch(e){}
  }

  /* ── Parse BRL display text → float ──────────────────────────────────── */
  function _parseBRL313(txt) {
    if (!txt) return 0;
    // Remove currency symbol, non-breaking spaces, thousand separators
    // Format used in app: "R$ 1.234,56" (fr-FR locale via toLocaleString)
    var s = (txt + '').replace(/R\$|\u00a0|\s/g, '').trim();
    // fr-FR: thousands = '.', decimal = ','
    s = s.replace(/\./g, '').replace(',', '.');
    var v = parseFloat(s);
    return isNaN(v) ? 0 : v;
  }

  /* ══════════════════════════════════════════════════════════════
     Core: read all Cost Calculator rows from DOM and sync them
     one-by-one into Finance > Despesas.
     Returns the list of rids found (for stale-row cleanup).
  ══════════════════════════════════════════════════════════════ */
  function _syncCostCalcRows313(id, vencimento) {
    var container = document.getElementById('miles-rows');
    if (!container) return [];

    var rows = container.querySelectorAll('.miles-row-wrap');
    var seenRids = [];

    rows.forEach(function(rowEl) {
      // Row ID is "miles-row-${rid}"; extract rid
      var rid = (rowEl.id || '').replace('miles-row-', '').trim();
      if (!rid) return;
      seenRids.push(rid);

      // Programme / issuer selector
      var selEl = document.getElementById('mc-sel-' + rid);
      var programme = selEl ? (selEl.options[selEl.selectedIndex] || {}).text || selEl.value || '' : '';
      programme = programme.trim();

      // Fournisseur selector
      var fornEl = document.getElementById('mc-forn-' + rid);
      var fournisseur = fornEl ? (fornEl.options[fornEl.selectedIndex] || {}).text || fornEl.value || '' : '';
      fournisseur = fournisseur.trim();

      // Use fournisseur as primary label, fall back to programme
      var label = fournisseur || programme || 'Linha ' + rid;

      // Subtotal BRL — the computed display element mc-sub-${rid}
      var subEl = document.getElementById('mc-sub-' + rid);
      var brl = _parseBRL313(subEl ? subEl.textContent : '0');
      if (brl <= 0) return; // skip rows with no cost yet

      var sid = 'costcalc_line__' + id + '__' + rid;

      // Description combines programme + fournisseur for clarity
      var descParts = [];
      if (programme) descParts.push(programme);
      if (fournisseur && fournisseur !== programme) descParts.push(fournisseur);
      var descricao = 'Custo CC \u2014 ' + (descParts.join(' / ') || rid);

      var rec = {
        tipo:              'saida',
        descricao:         descricao,
        fornecedor:        label,
        amount:            parseFloat(brl.toFixed(2)),
        original_amount:   parseFloat(brl.toFixed(2)),
        original_currency: 'BRL',
        fx_rate_to_brl:    1,
        brl_amount:        parseFloat(brl.toFixed(2)),
        categoria:         'cost_calculator',
        dossierRef:        id, // will be overwritten with booking-ref below
        vencimento:        vencimento,
        pago:              'pendente',
        nota:              'Synced from Cost Calculator row ' + rid,
        source_type:       'cost_calculator_line',
        source_id:         sid,
        recorrente:        false
      };

      // Prefer booking-ref as dossierRef if available
      try {
        var dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null');
        if (dd && dd.fields && dd.fields['booking-ref']) rec.dossierRef = dd.fields['booking-ref'];
      } catch(e){}
      // Also use DOM booking-ref as fallback (handles stale storage)
      try {
        var domRef = ((document.getElementById('booking-ref') || {}).value || '').trim();
        if (domRef) rec.dossierRef = domRef;
      } catch(e){}

      _globalUpsert313(rec);
      _upsertDE313(id, rec);
    });

    return seenRids;
  }

  /* ── Remove stale rows (present in storage but no longer in DOM) ──────── */
  function _purgeStaleRows313(id, seenRids) {
    var prefix = 'costcalc_line__' + id + '__';
    var seenSet = Object.create(null);
    seenRids.forEach(function(r) { seenSet[prefix + r] = true; });

    // Global
    var items = _finLoad313();
    var filtered = items.filter(function(r) {
      if (!r.source_id) return true;
      if (r.source_id.indexOf(prefix) !== 0) return true; // different dossier or type
      return seenSet[r.source_id]; // keep if still in DOM
    });
    if (filtered.length !== items.length) _finSave313(filtered);

    // Per-dossier
    var key  = 'expatur_doss_finance_' + id;
    var data = null; try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e){}
    if (data && data.expenses) {
      data.expenses = data.expenses.filter(function(r) {
        if (!r.source_id) return true;
        if (r.source_id.indexOf(prefix) !== 0) return true;
        return seenSet[r.source_id];
      });
      try { localStorage.setItem(key, JSON.stringify(data)); } catch(e){}
    }
  }

  /* ── Remove the old consolidated tarifcost_[id] record ───────────────── */
  function _removeConsolidatedTarifcost313(id) {
    var sid = 'tarifcost_' + id;
    _globalDeleteBySid313(sid);
    _deleteDEBySid313(id, sid);
  }

  /* ══════════════════════════════════════════════════════════════
     Override dossFinSyncFromTarification
     Wraps the v3.9 override (which itself wraps the original).
     After the existing chain runs, we:
       1. Remove the consolidated tarifcost_[id] record
       2. Sync each Cost Calculator row individually
       3. Purge any stale rows
  ══════════════════════════════════════════════════════════════ */
  if (typeof window.dossFinSyncFromTarification === 'function' && !window._v313TarifWrap) {
    window._v313TarifWrap = true;
    var _prev313Tarif = window.dossFinSyncFromTarification;

    window.dossFinSyncFromTarification = function() {
      // Run original chain first (v3.9 → original): writes tarifcost_[id]
      _prev313Tarif.apply(this, arguments);

      try {
        var id = _activeId313();
        if (!id) return;

        var bookedDate = _bookedAt313(id);
        var vencimento = _nextBizDay313(bookedDate);

        // 1. Remove the consolidated tarifcost record (replaced by per-row entries)
        _removeConsolidatedTarifcost313(id);

        // 2. Sync each row individually
        var seenRids = _syncCostCalcRows313(id, vencimento);

        // 3. Purge rows that no longer exist in DOM
        if (seenRids.length >= 0) {
          _purgeStaleRows313(id, seenRids);
        }

        // 4. Refresh Despesas panel if it's currently visible
        setTimeout(function() {
          try {
            var activeBtn = document.querySelector('.doss-fin-tab.active');
            if (activeBtn && activeBtn.dataset.dftab === 'expenses') {
              if (typeof window.v310RefreshDespesas === 'function') window.v310RefreshDespesas();
            } else {
              if (typeof window.dossFinRenderPanel === 'function') window.dossFinRenderPanel();
            }
          } catch(e){}
        }, 250);

      } catch(e) { console.warn('[v3.13] row sync error', e); }
    };
  }

  /* ══════════════════════════════════════════════════════════════
     Also hook calcMilesTotal / the "Recalcular" / row-change events
     so that if the user edits a cost row and the total is recalculated,
     the per-row sync re-runs automatically.

     Strategy: wrap calcMilesTotal (called after every row edit) to
     trigger a debounced dossFinSyncFromTarification call.
  ══════════════════════════════════════════════════════════════ */
  var _v313DebTimer = null;
  function _v313DebouncedSync() {
    clearTimeout(_v313DebTimer);
    _v313DebTimer = setTimeout(function() {
      try {
        if (typeof window.dossFinSyncFromTarification === 'function') {
          window.dossFinSyncFromTarification();
        }
      } catch(e){}
    }, 600);
  }

  if (typeof window.calcMilesTotal === 'function' && !window._v313CalcWrap) {
    window._v313CalcWrap = true;
    var _prev313Calc = window.calcMilesTotal;
    window.calcMilesTotal = function() {
      var result = _prev313Calc.apply(this, arguments);
      _v313DebouncedSync();
      return result;
    };
  }

  /* ══════════════════════════════════════════════════════════════
     On-load backfill: for dossiers that already have a tarifcost
     record but no costcalc_line__ records, we cannot backfill from
     DOM (DOM is ephemeral). We only clean up stale tarifcost records
     when the Cost Calculator panel is actually open and rows are visible.
     (Nothing to do on load if DOM rows aren't present.)
  ══════════════════════════════════════════════════════════════ */

  console.log('[Patch v3.13] Row-by-row Cost Calculator sync active \u2014 source_id pattern: costcalc_line__[id]__[rid]');

})(); // end Patch v3.13

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.14 — Cost Calculator Metadata Columns in Finance > Despesas
   Guard: window._v314CostCalcMeta

   WHAT THIS PATCH DOES
   ────────────────────
   1. Wraps dossFinSyncFromTarification (after v3.13) to enrich each
      costcalc_line__ record with four extra stored fields:
        programme    → text of the mc-sel-${rid} programme selector
        volume_miles → numeric value of mc-vol-${rid}
        cpm_brl      → numeric value of mc-cpm-${rid}
        taxas_brl    → numeric value of mc-fee-${rid}

   2. Injects four extra <th> cells into the static Despesas table header
      (Programme | Vol. Miles | C.P.M (R$) | Taxas (R$)) immediately
      after the "Fornecedor" column.

   3. Replaces window._v36RenderExpenses (the Despesas renderer exposed by
      v3.10) with a new version that renders those extra columns for every
      row, showing "—" for non-CC rows.

   INSERTION POINTS
   ────────────────
   • Sync:     window.dossFinSyncFromTarification (new wrapper, _v314TarifWrap)
   • Header:   document.getElementById('doss-fin-exp-body')
                 .closest('table').tHead.rows[0]  (DOM injection at load)
   • Renderer: window._v36RenderExpenses (re-assigned to _renderExpenses314)

   FIELD STORAGE (per expense record)
   ───────────────────────────────────
   programme:    string  — programme/issuer name (mc-sel text)
   volume_miles: number  — miles volume (mc-vol value)
   cpm_brl:      number  — cost per mile in BRL (mc-cpm value)
   taxas_brl:    number  — taxas/fees in BRL (mc-fee value)
   ══════════════════════════════════════════════════════════════════════════ */
(function() {
  if (window._v314CostCalcMeta) return;
  window._v314CostCalcMeta = true;

  var _FINK = 'expatur_financeiro_lancamentos';

  /* ── Private helpers ──────────────────────────────────────────────────── */

  function _finLoad314() {
    try { return JSON.parse(localStorage.getItem(_FINK) || '[]'); } catch(e) { return []; }
  }
  function _finSave314(items) {
    try { localStorage.setItem(_FINK, JSON.stringify(items)); } catch(e) {}
  }

  function _activeId314() {
    return localStorage.getItem('expatur_active_dossier') || null;
  }

  function _readSel314(id) {
    var el = document.getElementById(id);
    if (!el) return '';
    if (el.tagName === 'SELECT' && el.options && el.options[el.selectedIndex]) {
      return (el.options[el.selectedIndex].text || el.value || '').trim();
    }
    return (el.value || el.textContent || '').trim();
  }

  function _readNum314(id) {
    var el = document.getElementById(id);
    if (!el) return 0;
    var raw = (el.value || el.textContent || '').replace(',', '.').replace(/[^\d.\-]/g, '');
    var v = parseFloat(raw);
    return isNaN(v) ? 0 : v;
  }

  /* Patch a single record in global store by source_id */
  function _patchGlobal314(sid, extra) {
    var items = _finLoad314();
    var found = false;
    for (var i = 0; i < items.length; i++) {
      if (items[i].source_id === sid) {
        Object.assign(items[i], extra, { updatedAt: new Date().toISOString() });
        found = true;
        break;
      }
    }
    if (found) _finSave314(items);
  }

  /* Patch a single record in per-dossier store by source_id */
  function _patchDE314(id, sid, extra) {
    if (!id || !sid) return;
    var key = 'expatur_doss_finance_' + id;
    var data = null;
    try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e) {}
    if (!data || !Array.isArray(data.expenses)) return;
    var found = false;
    for (var i = 0; i < data.expenses.length; i++) {
      if (data.expenses[i].source_id === sid) {
        Object.assign(data.expenses[i], extra, { updatedAt: new Date().toISOString() });
        found = true;
        break;
      }
    }
    if (found) try { localStorage.setItem(key, JSON.stringify(data)); } catch(e) {}
  }

  /* ══════════════════════════════════════════════════════════════
     §1. SYNC EXTENSION
     Wrap dossFinSyncFromTarification (post-v3.13) to enrich each
     costcalc_line__ record with extra fields from the DOM.
     This runs AFTER v3.13's row sync has already upserted the base
     records, so we only need to patch the extra fields onto them.
  ══════════════════════════════════════════════════════════════ */
  function _enrichCCRows314(id) {
    var container = document.getElementById('miles-rows');
    if (!container || !id) return;

    container.querySelectorAll('.miles-row-wrap').forEach(function(rowEl) {
      var rid = (rowEl.id || '').replace('miles-row-', '').trim();
      if (!rid) return;

      var programme    = _readSel314('mc-sel-' + rid);
      var fournisseur  = _readSel314('mc-forn-' + rid);
      var volume_miles = _readNum314('mc-vol-' + rid);
      var cpm_brl      = _readNum314('mc-cpm-' + rid);
      var taxas_brl    = _readNum314('mc-fee-' + rid);

      var extra = {
        programme:    programme || fournisseur || '',
        volume_miles: volume_miles,
        cpm_brl:      cpm_brl,
        taxas_brl:    taxas_brl
      };

      var sid = 'costcalc_line__' + id + '__' + rid;
      _patchGlobal314(sid, extra);
      _patchDE314(id, sid, extra);
    });
  }

  if (typeof window.dossFinSyncFromTarification === 'function' && !window._v314TarifWrap) {
    window._v314TarifWrap = true;
    var _prev314 = window.dossFinSyncFromTarification;
    window.dossFinSyncFromTarification = function() {
      _prev314.apply(this, arguments);
      try {
        var id = _activeId314();
        if (id) _enrichCCRows314(id);
      } catch(e) { console.warn('[v3.14] enrich error', e); }
    };
  }

  /* ══════════════════════════════════════════════════════════════
     §2. HEADER INJECTION
     Inject the four extra <th> cells right after the "Fornecedor"
     column (position 0) in the static Despesas table header.
     Guard: data-v314-header attribute on the <tr>.
  ══════════════════════════════════════════════════════════════ */
  function _injectExpHeader314() {
    var tbody = document.getElementById('doss-fin-exp-body');
    if (!tbody) return;
    var table = tbody.closest('table');
    if (!table || !table.tHead || !table.tHead.rows[0]) return;
    var tr = table.tHead.rows[0];
    if (tr.dataset.v314) return; // already injected
    tr.dataset.v314 = '1';

    // The extra <th> cells go AFTER index 0 (Fornecedor), BEFORE index 1 (Categoria).
    // We insert in reverse order (Programme last → ends up at index 1).
    var TH_STYLE = 'white-space:nowrap;';
    var extras = [
      { label: 'Programme',    align: 'left'  },
      { label: 'Vol. (Miles)', align: 'right' },
      { label: 'C.P.M (R$)',   align: 'right' },
      { label: 'Taxas (R$)',   align: 'right' }
    ];
    // Insert at position 1 (after Fornecedor at 0) — insert all at once by
    // building a fragment and inserting before tr.cells[1].
    var refCell = tr.cells[1]; // "Categoria"
    extras.forEach(function(spec) {
      var th = document.createElement('th');
      th.textContent = spec.label;
      if (spec.align === 'right') th.style.textAlign = 'right';
      th.style.whiteSpace = 'nowrap';
      tr.insertBefore(th, refCell);
    });
  }

  /* ══════════════════════════════════════════════════════════════
     §3. DESPESAS RENDERER (replaces _renderExpenses310)
     Adds Programme | Vol. (Miles) | C.P.M (R$) | Taxas (R$) columns.
     Non-CC rows show "—" in these cells.
     All other logic mirrors _renderExpenses310 from v3.10.
  ══════════════════════════════════════════════════════════════ */

  /* Re-implement helpers that were IIFE-private in v3.10 */
  function _esc314(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;')
      .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function _fmtBRL314(v) {
    var n = parseFloat(v) || 0;
    return 'R$\u00a0' + n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  function _fmtNum314(v) {
    var n = parseFloat(v) || 0;
    return n === 0 ? '\u2014' : n.toLocaleString('pt-BR', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
  }

  function _dateLbl314(d) {
    if (!d) return '\u2014';
    try {
      var p = String(d).slice(0, 10).split('-');
      return p[2] + '/' + p[1] + '/' + p[0];
    } catch(e) { return d; }
  }

  function _brlOf314(r) {
    if (r.brl_amount != null) return parseFloat(r.brl_amount) || 0;
    var amt  = parseFloat(r.amount || r.paidAmount || 0);
    var rate = parseFloat(r.fx_rate_to_brl) || 1;
    return amt * rate;
  }

  function _dossRefs314(id) {
    var refs = Object.create(null);
    if (id) refs[id] = true;
    // Storage booking-ref
    try {
      var dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null');
      if (dd && dd.fields && dd.fields['booking-ref']) refs[dd.fields['booking-ref']] = true;
    } catch(e) {}
    // Live DOM booking-ref
    try {
      var domRef = ((document.getElementById('booking-ref') || {}).value || '').trim();
      if (domRef) refs[domRef] = true;
    } catch(e) {}
    return refs;
  }

  function _finLoad314b() {
    try { return JSON.parse(localStorage.getItem(_FINK) || '[]'); } catch(e) { return []; }
  }

  function _normalizeExp314(r) {
    var isNew = r.tipo === 'saida' ||
                r.fornecedor !== undefined ||
                r.categoria  !== undefined ||
                r.vencimento !== undefined ||
                r.source_type !== undefined;

    var brl = _brlOf314(r);
    if (isNew) {
      var pago      = r.pago || 'pendente';
      var statusKey = pago === 'pago' ? 'paid' : (pago === 'atrasado' ? 'overdue' : 'pending');
      return {
        _id:          r.source_id || r.id || '',
        supplier:     r.fornecedor || r.supplier || '\u2014',
        category:     r.categoria  || r.category  || '\u2014',
        dateVal:      r.vencimento || r.dueDate   || '',
        statusKey:    statusKey,
        pnrRef:       r.source_id  || r.pnrRef    || '',
        brl:          brl,
        paidBRL:      pago === 'pago' ? brl : 0,
        remBRL:       pago === 'pago' ? 0   : brl,
        notes:        r.nota || r.notes || '',
        isSync:       true,
        isCC:         r.source_type === 'cost_calculator_line',
        programme:    r.programme    || '',
        volume_miles: r.volume_miles || 0,
        cpm_brl:      r.cpm_brl      || 0,
        taxas_brl:    r.taxas_brl    || 0
      };
    }

    // Legacy manual entries
    var amt    = parseFloat(r.amount)     || 0;
    var paid   = parseFloat(r.paidAmount) || 0;
    brl = _brlOf314(r) || amt;
    var status = r.status || 'draft';
    var isPaid = (status === 'paid' || status === 'pago');
    var remFrac = (amt > 0) ? Math.max(0, amt - paid) / amt : 1;
    return {
      _id:          r.id || '',
      supplier:     r.supplier || '\u2014',
      category:     r.category || '\u2014',
      dateVal:      r.dueDate  || '',
      statusKey:    isPaid ? 'paid' : (status === 'overdue' ? 'overdue' : (status === 'confirmed' ? 'confirmed' : 'pending')),
      pnrRef:       r.pnrRef   || '',
      brl:          brl,
      paidBRL:      isPaid ? brl : (amt > 0 ? brl * paid / amt : 0),
      remBRL:       isPaid ? 0   : brl * remFrac,
      notes:        r.notes || '',
      isSync:       false,
      isCC:         false,
      programme:    '',
      volume_miles: 0,
      cpm_brl:      0,
      taxas_brl:    0
    };
  }

  function _renderExpenses314(id, data) {
    // Ensure header is injected (idempotent)
    _injectExpHeader314();

    var tbody   = document.getElementById('doss-fin-exp-body');
    var empty   = document.getElementById('doss-fin-exp-empty');
    var totalEl = document.getElementById('doss-fin-exp-total');
    if (!tbody) return;

    var refs = _dossRefs314(id);

    // Global synced records for this dossier
    var globalRecs = _finLoad314b().filter(function(r) {
      return r.tipo === 'saida' && refs[r.dossierRef || ''];
    });

    // Build dedup set
    var gSids = Object.create(null);
    globalRecs.forEach(function(r) {
      if (r.source_id) gSids[r.source_id] = true;
      if (r.id)        gSids[r.id]        = true;
    });

    // Local-only manual entries not already in global
    var localOnly = ((data && data.expenses) || []).filter(function(e) {
      return !(e.id && gSids[e.id]) && !(e.source_id && gSids[e.source_id]);
    });

    var allRows = globalRecs.concat(localOnly);
    tbody.innerHTML = '';

    if (!allRows.length) {
      if (empty)   empty.style.display = '';
      if (totalEl) totalEl.innerHTML   = '';
      return;
    }
    if (empty) empty.style.display = 'none';

    var BADGE  = { paid: 'fbadge-paid', confirmed: 'fbadge-confirmed', pending: 'fbadge-pending', overdue: 'fbadge-overdue', draft: 'fbadge-draft' };
    var LABELS = { paid: 'Pago',        confirmed: 'Confirmado',       pending: 'Pendente',       overdue: 'Vencido',        draft: 'Rascunho'    };

    var totalBRL = 0, paidBRL = 0;

    allRows.forEach(function(r) {
      var n = _normalizeExp314(r);
      totalBRL += n.brl;
      paidBRL  += n.paidBRL;

      var badgeCls    = BADGE[n.statusKey]  || 'fbadge-draft';
      var statusLabel = LABELS[n.statusKey] || n.statusKey;

      var actionCell = n.isSync
        ? '<span style="font-size:0.6rem;color:var(--navy-faint);">sync</span>'
        : '<button class="db-action-btn" onclick="dossFinEditLine(\'exp\',\'' + _esc314(n._id) + '\')" title="Editar">&#9999;</button>' +
          '<button class="db-action-btn del" onclick="dossFinDeleteLine(\'exp\',\'' + _esc314(n._id) + '\')" title="Apagar">&times;</button>';

      // Extra CC metadata cells — populated for CC rows, "—" for others
      var programmeTD    = n.isCC && n.programme    ? _esc314(n.programme)        : '\u2014';
      var volumeTD       = n.isCC && n.volume_miles ? _fmtNum314(n.volume_miles)  : '\u2014';
      var cpmTD          = n.isCC && n.cpm_brl      ? _fmtBRL314(n.cpm_brl)      : '\u2014';
      var taxasTD        = n.isCC && n.taxas_brl    ? _fmtBRL314(n.taxas_brl)    : '\u2014';

      // Programme badge style (subtle highlight for CC rows)
      var progStyle = n.isCC
        ? 'display:inline-block;background:rgba(6,32,59,0.06);border-radius:3px;padding:1px 5px;font-size:0.67rem;white-space:nowrap;'
        : 'color:var(--navy-faint);font-size:0.7rem;';

      var tr = document.createElement('tr');
      // Row highlight for CC rows
      if (n.isCC) tr.style.background = 'rgba(251,191,36,0.04)';

      tr.innerHTML =
        // Fornecedor (col 0)
        '<td>' + _esc314(n.supplier) + '</td>' +
        // Programme (col 1 — injected by §2)
        '<td><span style="' + progStyle + '">' + programmeTD + '</span></td>' +
        // Volume Miles (col 2)
        '<td style="text-align:right;font-family:monospace;font-size:0.72rem;">' + volumeTD + '</td>' +
        // CPM (col 3)
        '<td style="text-align:right;font-family:monospace;font-size:0.72rem;">' + cpmTD + '</td>' +
        // Taxas (col 4)
        '<td style="text-align:right;font-family:monospace;font-size:0.72rem;">' + taxasTD + '</td>' +
        // Categoria (col 5)
        '<td><span class="fbadge fbadge-draft" style="font-size:0.54rem;">' + _esc314(n.category) + '</span></td>' +
        // Vencimento (col 6)
        '<td style="white-space:nowrap;">' + _dateLbl314(n.dateVal) + '</td>' +
        // Status (col 7)
        '<td class="td-status"><span class="fbadge ' + badgeCls + '">' + statusLabel + '</span></td>' +
        // Referência (col 8)
        '<td style="font-family:monospace;font-size:0.68rem;color:var(--gold);max-width:130px;overflow:hidden;text-overflow:ellipsis;" title="' + _esc314(n.pnrRef) + '">' + _esc314(n.pnrRef) + '</td>' +
        // Valor BRL (col 9)
        '<td class="td-amt" style="white-space:nowrap;">' + _fmtBRL314(n.brl) + '</td>' +
        // Pago (col 10)
        '<td class="td-amt" style="color:#16a34a;white-space:nowrap;">' + _fmtBRL314(n.paidBRL) + '</td>' +
        // Restante (col 11)
        '<td class="td-amt" style="color:' + (n.remBRL > 0 ? 'var(--red)' : '#16a34a') + ';white-space:nowrap;">' + _fmtBRL314(n.remBRL) + '</td>' +
        // Notas (col 12)
        '<td style="font-size:0.7rem;color:var(--navy-faint);max-width:140px;overflow:hidden;text-overflow:ellipsis;" title="' + _esc314(n.notes) + '">' + _esc314(n.notes) + '</td>' +
        // Actions (col 13)
        '<td style="white-space:nowrap;">' + actionCell + '</td>';

      tbody.appendChild(tr);
    });

    if (totalEl) {
      var remBRL = totalBRL - paidBRL;
      totalEl.innerHTML =
        '<span style="color:var(--navy-soft);font-size:0.72rem;">Total:</span> <strong>' + _fmtBRL314(totalBRL) + '</strong>' +
        '&nbsp;&nbsp;<span style="color:var(--navy-soft);font-size:0.72rem;">Pago:</span> <strong style="color:#16a34a;">' + _fmtBRL314(paidBRL) + '</strong>' +
        '&nbsp;&nbsp;<span style="color:var(--navy-soft);font-size:0.72rem;">Restante:</span> <strong style="color:' + (remBRL > 0 ? 'var(--red)' : '#16a34a') + ';">' + _fmtBRL314(remBRL) + '</strong>';
    }
  }

  /* ── Replace the exposed renderer ───────────────────────────────────────
     v3.8 and v3.10 both call window._v36RenderExpenses(id, data).
     Replacing it here means every path (dossFinTab, dossFinRenderPanel,
     v310RefreshDespesas, etc.) immediately uses the extended renderer.
  ────────────────────────────────────────────────────────────────────────── */
  window._v36RenderExpenses = _renderExpenses314;

  /* ── Also patch window.v310RefreshDespesas to use updated renderer ────── */
  var _prev314Refresh = window.v310RefreshDespesas;
  window.v310RefreshDespesas = function() {
    try {
      var id   = localStorage.getItem('expatur_active_dossier');
      var data = null;
      if (id) try { data = JSON.parse(localStorage.getItem('expatur_doss_finance_' + id) || 'null'); } catch(e) {}
      _renderExpenses314(id, data);
    } catch(e) {
      if (typeof _prev314Refresh === 'function') _prev314Refresh.apply(this, arguments);
    }
  };

  /* ══════════════════════════════════════════════════════════════
     §4. INIT — inject header now (DOM is ready at script-append time)
         and also hook dossFinRenderPanel so header is injected
         whenever the Finance panel is opened fresh.
  ══════════════════════════════════════════════════════════════ */
  setTimeout(_injectExpHeader314, 200);

  var _prev314Panel = window.dossFinRenderPanel;
  window.dossFinRenderPanel = function() {
    if (typeof _prev314Panel === 'function') _prev314Panel.apply(this, arguments);
    setTimeout(_injectExpHeader314, 0);
  };

  console.log('[Patch v3.14] CC metadata columns active — programme / volume_miles / cpm_brl / taxas_brl stored and rendered in Despesas.');

})(); // end Patch v3.14

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.15 — Correct Accounting: TOTAL VENDAS / TOTAL RECEBIDO / SALDO DEVEDOR CLIENT
   Guard: window._v315AccountingFix

   ROOT CAUSE
   ──────────
   _v36ComputeOverview (v3.6, re-exposed via window._v36ComputeOverview)
   computes  totalSale  by summing ALL tipo:'entrada' receivable records.
   That value is NOT the gross client price — it is the sum of whatever
   payment records happen to have been entered.  Consequences:
     • Before any payment records exist → totalSale = 0
     • If Stripe 75/25 splits + OOB payments both exist → totalSale inflated
     • TOTAL VENDAS card, SALDO DEVEDOR, and open-dossier dashboard table
       all show wrong numbers derived from this incorrect base.

   CORRECT DEFINITIONS
   ───────────────────
   TOTAL VENDAS      = gross client sale price  (TARIF TOTAL in BRL)
   TOTAL RECEBIDO    = sum of confirmed payments received  (pago=pago, BRL)
   SALDO DEVEDOR CLIENT = TOTAL VENDAS − TOTAL RECEBIDO

   SOURCE OF TRUTH FOR TOTAL VENDAS (priority order)
   ─────────────────────────────────────────────────
   1. expatur_pnl_[ref].grossSell
      Set by capturePnlSnapshot() when BOOK is clicked.
      Already BRL-converted: (cur==='R$') ? price : price * rate
      Most accurate value.

   2. expatur_dossier_[id].finForecast.sale  (with saleCurrency check)
      Set by dossFinSyncFromTarification() from dd.fields['total-price'].
      v3.15 augments this write to also store saleCurrency so future reads
      can trust it when currency = R$/BRL.

   3. Sum of tipo:'entrada' receivable records in BRL
      Legacy fallback — same as current logic.  Only used when neither
      PNL snapshot nor finForecast.sale is available.

   SOURCE OF TRUTH FOR TOTAL RECEBIDO
   ────────────────────────────────────
   Sum of tipo:'entrada' records where pago==='pago' (in BRL).
   For local-only entries with partial paidAmount, apply the paid/amount
   ratio (same as current logic).  This is CORRECT and unchanged.

   INSERTION POINTS
   ────────────────
   • window._v36ComputeOverview  — replaced entirely
   • window.dossFIN_computeOverview — aliased to same function
   • window.dossFinSyncFromTarification — thin wrapper to also store
     saleCurrency in finForecast (so future non-BRL devis can be trusted)

   CASCADING EFFECT (no renderer changes needed)
   ─────────────────────────────────────────────
   All downstream code already reads ov.totalSale / ov.totalRecv /
   ov.balClientDue from the compute function result:
     • _v36RenderOverview           (dossier Finance > Vue d'ensemble)
     • finRenderDossierPL           (P&L dossier summary list)
     • finRenderDashboard open-dossiers table
     • Global KPI forecastMarginTotal / realMarginTotal aggregation
   Fixing the compute function propagates to all of them.
   ══════════════════════════════════════════════════════════════════════════ */
(function() {
  if (window._v315AccountingFix) return;
  window._v315AccountingFix = true;

  var _FINK = 'expatur_financeiro_lancamentos';

  /* ── Private helpers ──────────────────────────────────────────────────── */

  function _finLoad315() {
    try { return JSON.parse(localStorage.getItem(_FINK) || '[]'); } catch(e) { return []; }
  }

  function _brlOf315(r) {
    if (r.brl_amount != null && r.brl_amount !== '') return parseFloat(r.brl_amount) || 0;
    var amt  = parseFloat(r.amount || r.valor || 0);
    var rate = parseFloat(r.fx_rate_to_brl) || 1;
    return amt * rate;
  }

  /* Build set of all valid dossierRef values for a given dossier id */
  function _dossRefs315(id) {
    var refs = Object.create(null);
    if (id) refs[id] = true;
    try {
      var dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null');
      if (dd && dd.fields && dd.fields['booking-ref']) refs[dd.fields['booking-ref']] = true;
    } catch(e) {}
    // Also try live DOM booking-ref
    try {
      var domRef = ((document.getElementById('booking-ref') || {}).value || '').trim();
      if (domRef) refs[domRef] = true;
    } catch(e) {}
    return refs;
  }

  /* Get the booking-ref string for a dossier */
  function _bookingRef315(id) {
    try {
      var dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null');
      if (dd && dd.fields && dd.fields['booking-ref']) return dd.fields['booking-ref'];
    } catch(e) {}
    return null;
  }

  /* ══════════════════════════════════════════════════════════════
     _getTarifTotalBRL315(id, fallback)
     Returns TARIF TOTAL in BRL for the dossier.
     Priority: PNL snapshot grossSell → finForecast.sale (BRL) → fallback
  ══════════════════════════════════════════════════════════════ */
  function _getTarifTotalBRL315(id, fallback) {
    // ── Priority 1: PNL snapshot grossSell (BRL-converted at booking time) ──
    var ref = _bookingRef315(id);
    if (ref) {
      try {
        var snap = JSON.parse(localStorage.getItem('expatur_pnl_' + ref) || 'null');
        if (snap && parseFloat(snap.grossSell) > 0) {
          return parseFloat(snap.grossSell);
        }
      } catch(e) {}
    }

    // ── Priority 2: finForecast.sale if BRL (no conversion needed) ──
    try {
      var dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null');
      if (dd && dd.finForecast && parseFloat(dd.finForecast.sale) > 0) {
        var cur = dd.finForecast.saleCurrency || '';
        // Trust it as BRL if explicitly flagged BRL
        if (cur === 'BRL' || cur === 'R$') {
          return parseFloat(dd.finForecast.sale);
        }
        // If no currency info but a sale exists, use it as-is
        // (may be in EUR — still better than 0 for SALDO purposes)
        if (!cur && parseFloat(dd.finForecast.sale) > 0) {
          return parseFloat(dd.finForecast.sale);
        }
      }
    } catch(e) {}

    // ── Priority 3: sum of receivable records (legacy fallback) ──
    return fallback || 0;
  }

  /* ══════════════════════════════════════════════════════════════
     CORRECTED _v36ComputeOverview
     Replaces the v3.6 version exposed via window._v36ComputeOverview.

     TOTAL VENDAS      = TARIF TOTAL in BRL  (from PNL snapshot)
     TOTAL RECEBIDO    = sum of confirmed received  (pago=pago, BRL)
     SALDO DEVEDOR     = TOTAL VENDAS − TOTAL RECEBIDO
  ══════════════════════════════════════════════════════════════ */
  function _computeOverview315(id) {
    /* Load dossier metadata */
    var dd = null;
    try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null'); } catch(e) {}

    /* Load per-dossier finance shell */
    var data = null;
    try { data = JSON.parse(localStorage.getItem('expatur_doss_finance_' + id) || 'null'); } catch(e) {}

    /* Get all global finance records for this dossier */
    var refs = _dossRefs315(id);
    var globalRecs = _finLoad315().filter(function(r) {
      return refs[r.dossierRef || ''];
    });

    /* ── Aggregate from global records ──────────────────────── */
    var sumRecvBRL    = 0;  // sum of ALL entrada records (used as fallback for TOTAL VENDAS)
    var totalRecv     = 0;  // TOTAL RECEBIDO: confirmed received in BRL
    var totalCost     = 0;  // sum of all expenses in BRL
    var totalPaid     = 0;  // confirmed paid to suppliers in BRL
    var credAvail     = 0;

    var globalSids = Object.create(null);

    globalRecs.forEach(function(r) {
      var brl = _brlOf315(r);
      if (r.tipo === 'entrada') {
        sumRecvBRL += brl;
        // TOTAL RECEBIDO: only count records where payment is confirmed
        if (r.pago === 'pago') totalRecv += brl;
      } else if (r.tipo === 'saida') {
        totalCost += brl;
        if (r.pago === 'pago') totalPaid += brl;
      }
      if (r.source_id) globalSids[r.source_id] = true;
      if (r.id)        globalSids[r.id]        = true;
    });

    /* ── Aggregate from per-dossier shell (local-only entries) ─ */
    if (data) {
      (data.receivables || []).forEach(function(r) {
        // Skip if already counted in global
        if ((r.id && globalSids[r.id]) || (r.source_id && globalSids[r.source_id])) return;
        var brl  = _brlOf315(r);
        var amt  = parseFloat(r.amount) || 0;
        var paid = parseFloat(r.paidAmount) || 0;
        sumRecvBRL += brl;
        // Determine received amount for this record
        var isPaid = (r.status === 'paid' || r.status === 'pago' || r.pago === 'pago');
        if (isPaid) {
          totalRecv += brl;
        } else if (paid > 0 && amt > 0) {
          // Partial payment — apply ratio
          totalRecv += brl * (paid / amt);
        }
      });

      (data.expenses || []).forEach(function(e) {
        if ((e.id && globalSids[e.id]) || (e.source_id && globalSids[e.source_id])) return;
        var brl  = _brlOf315(e);
        var amt  = parseFloat(e.amount) || 0;
        var paid = parseFloat(e.paidAmount) || 0;
        totalCost += brl;
        var isPaid = (e.status === 'paid' || e.status === 'pago' || e.pago === 'pago');
        if (isPaid) {
          totalPaid += brl;
        } else if (paid > 0 && amt > 0) {
          totalPaid += brl * (paid / amt);
        }
      });

      (data.credits || []).forEach(function(c) {
        credAvail += Math.max(0, (parseFloat(c.originalAmount) || 0) - (parseFloat(c.usedAmount) || 0));
      });
    }

    /* ════════════════════════════════════════════════════════
       TOTAL VENDAS = TARIF TOTAL in BRL
       Use PNL snapshot grossSell as the authoritative source.
       sumRecvBRL is only the fallback of last resort.
    ════════════════════════════════════════════════════════ */
    var totalSale = _getTarifTotalBRL315(id, sumRecvBRL);

    /* ════════════════════════════════════════════════════════
       SALDO DEVEDOR CLIENT = TOTAL VENDAS − TOTAL RECEBIDO
       Floor at 0 (no negative balance shown when overpaid).
    ════════════════════════════════════════════════════════ */
    var balClientDue = Math.max(0, totalSale - totalRecv);

    /* Forecast cost from finForecast if available (cost side only) */
    var forecastCost = totalCost;
    if (dd && dd.finForecast && parseFloat(dd.finForecast.cost) > 0) {
      forecastCost = parseFloat(dd.finForecast.cost);
    }

    return {
      totalSale:      parseFloat(totalSale.toFixed(2)),      // TOTAL VENDAS = TARIF TOTAL (BRL)
      totalCost:      parseFloat(totalCost.toFixed(2)),      // total operational costs (BRL)
      forecastMargin: parseFloat((totalSale - forecastCost).toFixed(2)),
      realizedMargin: parseFloat((totalRecv - totalPaid).toFixed(2)),
      totalRecv:      parseFloat(totalRecv.toFixed(2)),      // TOTAL RECEBIDO = confirmed received (BRL)
      totalPaid:      parseFloat(totalPaid.toFixed(2)),      // confirmed paid to suppliers (BRL)
      balClientDue:   parseFloat(balClientDue.toFixed(2)),   // SALDO DEVEDOR = TOTAL VENDAS - TOTAL RECEBIDO
      balSupplierDue: parseFloat(Math.max(0, totalCost - totalPaid).toFixed(2)),
      credAvail:      parseFloat(credAvail.toFixed(2))
    };
  }

  /* ── Replace both compute functions with the corrected version ────────── */
  window._v36ComputeOverview    = _computeOverview315;
  window.dossFIN_computeOverview = _computeOverview315;

  /* ══════════════════════════════════════════════════════════════
     Also augment dossFinSyncFromTarification to persist saleCurrency
     alongside finForecast.sale so priority-2 lookup can trust it.
  ══════════════════════════════════════════════════════════════ */
  if (typeof window.dossFinSyncFromTarification === 'function' && !window._v315TarifWrap) {
    window._v315TarifWrap = true;
    var _prev315Tarif = window.dossFinSyncFromTarification;
    window.dossFinSyncFromTarification = function() {
      _prev315Tarif.apply(this, arguments);
      try {
        var id = localStorage.getItem('expatur_active_dossier');
        if (!id) return;
        var ddStr = localStorage.getItem('expatur_dossier_' + id);
        if (!ddStr) return;
        var dd2 = JSON.parse(ddStr);
        if (!dd2 || !dd2.finForecast) return;

        // Detect currency from DOM (devis currency selector) or stored field
        var curEl = document.getElementById('currency');
        var currency = curEl
          ? (curEl.value || '€')
          : ((dd2.fields && (dd2.fields['currency'] || dd2.fields['devise'])) || '€');

        // Normalize to ISO
        var iso = currency === 'R$' ? 'BRL'
          : currency === '€'  ? 'EUR'
          : currency === '$'  ? 'USD'
          : currency;

        dd2.finForecast.saleCurrency = iso;
        localStorage.setItem('expatur_dossier_' + id, JSON.stringify(dd2));
      } catch(e) { console.warn('[v3.15] saleCurrency patch error', e); }
    };
  }

  /* ══════════════════════════════════════════════════════════════
     Refresh any currently-open Finance panel so the corrected
     values appear immediately without requiring a page reload.
  ══════════════════════════════════════════════════════════════ */
  setTimeout(function() {
    try {
      if (typeof window.dossFinRenderPanel === 'function') window.dossFinRenderPanel();
    } catch(e) {}
    try {
      if (typeof window.finRefresh === 'function') window.finRefresh();
    } catch(e) {}
  }, 300);

  console.log('[Patch v3.15] Accounting fix active:',
    'TOTAL VENDAS = snap.grossSell | TOTAL RECEBIDO = sum(pago=pago entrada) | SALDO DEVEDOR = TOTAL VENDAS - TOTAL RECEBIDO');

})(); // end Patch v3.15

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.16 — Definitive CC Row Sync (single-pass, all 6 DOM fields)
   Guard: window._v316CCFullSync

   ROOT CAUSE OF PRIOR FAILURE
   ───────────────────────────
   v3.13 wrote records with only: programme (in description), fournisseur,
   brl_amount.  The extra fields (volume_miles, cpm_brl, taxas_brl,
   programme as a stored field) were missing from the written record.

   v3.14 attempted a two-pass fix: let v3.13 write, then patch extra fields
   via _patchGlobal314 / _patchDE314.  This failed because both passes ran
   synchronously inside the same call stack — the localStorage write from
   v3.13 and the read inside _patchGlobal314 used the same JS thread, but
   the `_readNum314` calls were returning 0 for input elements whose value
   hadn't been committed to `.value` at patch time (browser event loop
   issue with numeric inputs).

   FIX
   ───
   Single-pass write: one function reads ALL 6 DOM fields per row and
   writes the complete record in ONE upsert. No two-pass, no patching.
   v3.16 wraps the current chain (v3.15 → v3.14 → v3.13 → v3.9 → original)
   and, after the chain runs (for its non-CC side-effects), calls its own
   definitive CC row sync that OVERWRITES whatever v3.13 wrote because both
   use the same source_id — upsert merges in favour of the last write.

   FIELDS READ PER ROW
   ───────────────────
   mc-sel-${rid}   → programme   (SELECT option text)
   mc-forn-${rid}  → fournisseur  (SELECT option text)
   mc-vol-${rid}   → volume_miles (INPUT number .value)
   mc-cpm-${rid}   → cpm_brl      (INPUT number .value)
   mc-fee-${rid}   → taxas_brl    (INPUT number .value)
   mc-sub-${rid}   → brl_amount   (display span textContent, parsed)

   RENDERER
   ────────
   Replaces window._v36RenderExpenses with _renderExpenses316.
   The renderer fully controls its own <thead> (injected dynamically,
   replacing any v3.14-injected header) and renders 4 extra columns:
     Programme | Vol. (Miles) | C.P.M (R$) | Taxas (R$)
   Non-CC rows get "—" in those cells.
   ══════════════════════════════════════════════════════════════════════════ */
(function() {
  if (window._v316CCFullSync) return;
  window._v316CCFullSync = true;

  var _FINK = 'expatur_financeiro_lancamentos';

  /* ── Helpers ──────────────────────────────────────────────────────────── */

  function _finLoad316()        { try { return JSON.parse(localStorage.getItem(_FINK) || '[]'); } catch(e) { return []; } }
  function _finSave316(items)   { try { localStorage.setItem(_FINK, JSON.stringify(items)); } catch(e) {} }
  function _activeId316()       { return localStorage.getItem('expatur_active_dossier') || null; }

  function _today316()          { return new Date().toISOString().slice(0, 10); }

  function _nextBizDay316(fromISO) {
    var d = fromISO ? new Date(fromISO.slice(0, 10) + 'T12:00:00') : new Date();
    d.setDate(d.getDate() + 1);
    while (d.getDay() === 0 || d.getDay() === 6) d.setDate(d.getDate() + 1);
    return d.toISOString().slice(0, 10);
  }

  function _bookedAt316(id) {
    var raw = id ? localStorage.getItem('expatur_bookedAt_' + id) : null;
    return raw ? raw.slice(0, 10) : _today316();
  }

  /* Read SELECT option text */
  function _selText316(elId) {
    var el = document.getElementById(elId);
    if (!el) return '';
    if (el.tagName === 'SELECT') {
      var idx = el.selectedIndex;
      return idx >= 0 && el.options[idx] ? (el.options[idx].text || el.value || '').trim() : (el.value || '').trim();
    }
    return (el.value || el.textContent || '').trim();
  }

  /* Read numeric INPUT value — handles comma decimal, filters non-numeric */
  function _numVal316(elId) {
    var el = document.getElementById(elId);
    if (!el) return 0;
    /* Try .valueAsNumber first (most reliable for <input type="number">) */
    if (typeof el.valueAsNumber === 'number' && !isNaN(el.valueAsNumber)) return el.valueAsNumber;
    var raw = (el.value || '').replace(',', '.').replace(/[^\d.\-]/g, '');
    var v = parseFloat(raw);
    return isNaN(v) ? 0 : v;
  }

  /* Parse the BRL display text from mc-sub-${rid} span */
  function _parseBRL316(txt) {
    if (!txt) return 0;
    var s = (txt + '').replace(/R\$|\u00a0|\s/g, '').trim().replace(/\./g, '').replace(',', '.');
    var v = parseFloat(s);
    return isNaN(v) ? 0 : v;
  }

  /* Upsert in global lancamentos store */
  function _globalUpsert316(rec) {
    var items = _finLoad316();
    var idx = -1;
    for (var i = 0; i < items.length; i++) {
      if (items[i].source_id && items[i].source_id === rec.source_id) { idx = i; break; }
    }
    var ts = new Date().toISOString();
    if (idx >= 0) {
      items[idx] = Object.assign({}, items[idx], rec, { updatedAt: ts });
    } else {
      items.push(Object.assign({ id: 'fin316_' + Date.now() + Math.random().toString(36).slice(2,5), createdAt: ts }, rec));
    }
    _finSave316(items);
  }

  /* Delete from global store by source_id */
  function _globalDel316(sid) {
    var items = _finLoad316();
    var filtered = items.filter(function(r) { return r.source_id !== sid; });
    if (filtered.length !== items.length) _finSave316(filtered);
  }

  /* Upsert in per-dossier shell */
  function _deUpsert316(id, rec) {
    if (!id || !rec.source_id) return;
    var key = 'expatur_doss_finance_' + id;
    var data = null; try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e) {}
    if (!data) return;
    var arr = data.expenses || [];
    var idx = -1;
    for (var i = 0; i < arr.length; i++) {
      if (arr[i].source_id && arr[i].source_id === rec.source_id) { idx = i; break; }
    }
    var ts = new Date().toISOString();
    if (idx >= 0) {
      arr[idx] = Object.assign({}, arr[idx], rec, { updatedAt: ts });
    } else {
      arr.push(Object.assign({ id: 'dfe316_' + Date.now() + Math.random().toString(36).slice(2,4), createdAt: ts }, rec));
    }
    data.expenses = arr;
    try { localStorage.setItem(key, JSON.stringify(data)); } catch(e) {}
  }

  /* Delete from per-dossier shell by source_id */
  function _deDel316(id, sid) {
    if (!id || !sid) return;
    var key = 'expatur_doss_finance_' + id;
    var data = null; try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e) {}
    if (!data) return;
    data.expenses = (data.expenses || []).filter(function(r) { return r.source_id !== sid; });
    try { localStorage.setItem(key, JSON.stringify(data)); } catch(e) {}
  }

  /* Delete all records whose source_id matches a prefix (for stale row cleanup) */
  function _purgeByPrefix316(id, prefix) {
    // Global
    var items = _finLoad316();
    var filt = items.filter(function(r) { return !(r.source_id && r.source_id.indexOf(prefix) === 0); });
    if (filt.length !== items.length) _finSave316(filt);
    // Per-dossier
    if (!id) return;
    var key = 'expatur_doss_finance_' + id;
    var data = null; try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e) {}
    if (!data) return;
    data.expenses = (data.expenses || []).filter(function(r) { return !(r.source_id && r.source_id.indexOf(prefix) === 0); });
    try { localStorage.setItem(key, JSON.stringify(data)); } catch(e) {}
  }

  /* ══════════════════════════════════════════════════════════════
     _syncCCRowsFull316(id, vencimento)
     THE DEFINITIVE SINGLE-PASS CC ROW SYNC.
     Reads all 6 DOM fields per row and writes the complete record
     in one upsert. Returns list of seen rids for stale cleanup.
  ══════════════════════════════════════════════════════════════ */
  function _syncCCRowsFull316(id, vencimento) {
    var container = document.getElementById('miles-rows');
    if (!container || !id) return [];

    /* Resolve the canonical dossierRef (booking-ref > DOM > id) */
    var dossierRef = id;
    try {
      var dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null');
      if (dd && dd.fields && dd.fields['booking-ref']) dossierRef = dd.fields['booking-ref'];
    } catch(e) {}
    try {
      var domRef = ((document.getElementById('booking-ref') || {}).value || '').trim();
      if (domRef) dossierRef = domRef;
    } catch(e) {}

    var rows = container.querySelectorAll('.miles-row-wrap');
    var seenRids = [];

    rows.forEach(function(rowEl) {
      var rid = (rowEl.id || '').replace('miles-row-', '').trim();
      if (!rid) return;
      seenRids.push(rid);

      /* ── Read ALL 6 DOM fields ── */
      var programme    = _selText316('mc-sel-'  + rid);   // SELECT: programme/issuer
      var fournisseur  = _selText316('mc-forn-' + rid);   // SELECT: fournisseur
      var volume_miles = _numVal316( 'mc-vol-'  + rid);   // INPUT number: miles volume
      var cpm_brl      = _numVal316( 'mc-cpm-'  + rid);   // INPUT number: cost per mile
      var taxas_brl    = _numVal316( 'mc-fee-'  + rid);   // INPUT number: taxas/fees
      var subEl        = document.getElementById('mc-sub-' + rid);
      var brl          = _parseBRL316(subEl ? subEl.textContent : '0');

      /* Skip rows with zero subtotal */
      if (brl <= 0) return;

      var sid   = 'costcalc_line__' + id + '__' + rid;
      var label = fournisseur || programme || ('Linha ' + rid);

      var descParts = [];
      if (programme)                        descParts.push(programme);
      if (fournisseur && fournisseur !== programme) descParts.push(fournisseur);
      var descricao = 'Custo CC \u2014 ' + (descParts.join(' / ') || rid);

      /* ── Write COMPLETE record in one upsert ── */
      var rec = {
        tipo:              'saida',
        descricao:         descricao,
        fornecedor:        label,
        /* ── CC metadata fields ── */
        programme:         programme    || fournisseur || '',
        volume_miles:      parseFloat(volume_miles.toFixed ? volume_miles.toFixed(0) : volume_miles) || 0,
        cpm_brl:           parseFloat(cpm_brl.toFixed      ? cpm_brl.toFixed(4)      : cpm_brl)      || 0,
        taxas_brl:         parseFloat(taxas_brl.toFixed    ? taxas_brl.toFixed(2)    : taxas_brl)    || 0,
        /* ── Money fields ── */
        amount:            parseFloat(brl.toFixed(2)),
        original_amount:   parseFloat(brl.toFixed(2)),
        original_currency: 'BRL',
        fx_rate_to_brl:    1,
        brl_amount:        parseFloat(brl.toFixed(2)),
        /* ── Accounting fields ── */
        categoria:         'cost_calculator',
        dossierRef:        dossierRef,
        vencimento:        vencimento,
        pago:              'pendente',
        nota:              'CC row ' + rid + (volume_miles > 0 ? ' | ' + Math.round(volume_miles).toLocaleString('pt-BR') + ' miles' : ''),
        source_type:       'cost_calculator_line',
        source_id:         sid,
        recorrente:        false
      };

      _globalUpsert316(rec);
      _deUpsert316(id, rec);
    });

    return seenRids;
  }

  /* ══════════════════════════════════════════════════════════════
     Wrap dossFinSyncFromTarification — definitive CC sync overlay
     Calls the existing chain first (for its non-CC side-effects:
     tarifcost removal, saleCurrency, stripe/pnl, etc.), then runs
     _syncCCRowsFull316 which OVERWRITES each costcalc_line__ record
     with the complete 6-field version. Since upsert matches by
     source_id, the overwrite is clean and atomic.
  ══════════════════════════════════════════════════════════════ */
  if (typeof window.dossFinSyncFromTarification === 'function' && !window._v316TarifWrap) {
    window._v316TarifWrap = true;
    var _prev316Tarif = window.dossFinSyncFromTarification;

    window.dossFinSyncFromTarification = function() {
      /* Run existing chain (v3.15 → v3.14 → v3.13 → v3.9 → original) */
      _prev316Tarif.apply(this, arguments);

      try {
        var id = _activeId316();
        if (!id) return;

        var vencimento = _nextBizDay316(_bookedAt316(id));

        /* Belt-and-suspenders: remove any consolidated tarifcost record */
        _globalDel316('tarifcost_' + id);
        _deDel316(id, 'tarifcost_' + id);

        /* DEFINITIVE single-pass sync — overwrites v3.13 partial records */
        var seenRids = _syncCCRowsFull316(id, vencimento);

        /* Purge stale rows (rows removed from CC tab since last sync) */
        var prefix = 'costcalc_line__' + id + '__';
        var seenSet = Object.create(null);
        seenRids.forEach(function(r) { seenSet[prefix + r] = true; });

        // Global purge of stale rids (keep only seenSet)
        var items = _finLoad316();
        var filtItems = items.filter(function(r) {
          if (!r.source_id || r.source_id.indexOf(prefix) !== 0) return true;
          return seenSet[r.source_id];
        });
        if (filtItems.length !== items.length) _finSave316(filtItems);

        // Per-dossier purge
        var key = 'expatur_doss_finance_' + id;
        var data = null; try { data = JSON.parse(localStorage.getItem(key) || 'null'); } catch(e) {}
        if (data && data.expenses) {
          data.expenses = data.expenses.filter(function(r) {
            if (!r.source_id || r.source_id.indexOf(prefix) !== 0) return true;
            return seenSet[r.source_id];
          });
          try { localStorage.setItem(key, JSON.stringify(data)); } catch(e) {}
        }

        /* Refresh Despesas panel if visible */
        setTimeout(function() {
          try { window.v310RefreshDespesas(); } catch(e) {
            try { window.dossFinRenderPanel(); } catch(ex) {}
          }
        }, 200);

      } catch(e) { console.warn('[v3.16] CC full sync error', e); }
    };
  }

  /* ══════════════════════════════════════════════════════════════
     RENDERER — _renderExpenses316
     Replaces window._v36RenderExpenses.
     Controls its own <thead> and renders all 4 extra columns.
  ══════════════════════════════════════════════════════════════ */

  /* Renderer private helpers */
  function _esc316(s) {
    return String(s == null ? '' : s)
      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function _fmtBRL316(v) {
    var n = parseFloat(v) || 0;
    return 'R$\u00a0' + n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  function _fmtMiles316(v) {
    var n = parseFloat(v) || 0;
    return n === 0 ? '\u2014' : Math.round(n).toLocaleString('pt-BR');
  }
  function _fmtRate316(v) {
    var n = parseFloat(v) || 0;
    return n === 0 ? '\u2014' : n.toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 4 });
  }
  function _dateLbl316(d) {
    if (!d) return '\u2014';
    try { var p = String(d).slice(0,10).split('-'); return p[2]+'/'+p[1]+'/'+p[0]; } catch(e) { return d; }
  }
  function _brlOf316(r) {
    if (r.brl_amount != null && r.brl_amount !== '') return parseFloat(r.brl_amount) || 0;
    return (parseFloat(r.amount || r.valor || 0)) * (parseFloat(r.fx_rate_to_brl) || 1);
  }
  function _dossRefs316(id) {
    var refs = Object.create(null);
    if (id) refs[id] = true;
    try { var dd=JSON.parse(localStorage.getItem('expatur_dossier_'+id)||'null'); if(dd&&dd.fields&&dd.fields['booking-ref']) refs[dd.fields['booking-ref']]=true; } catch(e){}
    try { var dr=((document.getElementById('booking-ref')||{}).value||'').trim(); if(dr) refs[dr]=true; } catch(e){}
    return refs;
  }

  function _normalizeExp316(r) {
    var isNew = r.tipo==='saida'||r.fornecedor!==undefined||r.categoria!==undefined||r.vencimento!==undefined||r.source_type!==undefined;
    var brl   = _brlOf316(r);
    if (isNew) {
      var pago = r.pago || 'pendente';
      var sk   = pago==='pago' ? 'paid' : (pago==='atrasado' ? 'overdue' : 'pending');
      return {
        _id:          r.source_id || r.id || '',
        supplier:     r.fornecedor  || r.supplier  || '\u2014',
        category:     r.categoria   || r.category  || '\u2014',
        dateVal:      r.vencimento  || r.dueDate   || '',
        statusKey:    sk,
        pnrRef:       r.source_id   || r.pnrRef    || '',
        brl:          brl,
        paidBRL:      pago==='pago' ? brl : 0,
        remBRL:       pago==='pago' ? 0   : brl,
        notes:        r.nota || r.notes || '',
        isSync:       true,
        isCC:         r.source_type === 'cost_calculator_line',
        programme:    r.programme    != null ? String(r.programme)    : '',
        volume_miles: r.volume_miles != null ? parseFloat(r.volume_miles) || 0 : 0,
        cpm_brl:      r.cpm_brl      != null ? parseFloat(r.cpm_brl)      || 0 : 0,
        taxas_brl:    r.taxas_brl    != null ? parseFloat(r.taxas_brl)    || 0 : 0
      };
    }
    // Legacy manual entry
    var amt  = parseFloat(r.amount) || 0;
    var paid = parseFloat(r.paidAmount) || 0;
    brl      = _brlOf316(r) || amt;
    var st   = r.status || 'draft';
    var ip   = (st==='paid'||st==='pago');
    return {
      _id: r.id||'', supplier: r.supplier||'\u2014', category: r.category||'\u2014',
      dateVal: r.dueDate||'', statusKey: ip?'paid':(st==='overdue'?'overdue':(st==='confirmed'?'confirmed':'pending')),
      pnrRef: r.pnrRef||'', brl: brl,
      paidBRL: ip?brl:(amt>0?brl*paid/amt:0), remBRL: ip?0:brl*(amt>0?Math.max(0,amt-paid)/amt:1),
      notes: r.notes||'', isSync: false, isCC: false,
      programme:'', volume_miles:0, cpm_brl:0, taxas_brl:0
    };
  }

  /* ── Dynamic thead injection ────────────────────────────────────────────
     Replaces whatever header the table has (including v3.14 injection)
     with the definitive 14-column header.
  ────────────────────────────────────────────────────────────────────────── */
  function _setExpHeader316(table) {
    if (!table || !table.tHead) return;
    table.tHead.innerHTML =
      '<tr>' +
        '<th>Fornecedor</th>' +
        '<th>Programme</th>' +
        '<th style="text-align:right;white-space:nowrap;">Vol.\u00a0(Miles)</th>' +
        '<th style="text-align:right;white-space:nowrap;">C.P.M\u00a0(R$)</th>' +
        '<th style="text-align:right;white-space:nowrap;">Taxas\u00a0(R$)</th>' +
        '<th>Categoria</th>' +
        '<th style="white-space:nowrap;">Vencimento</th>' +
        '<th>Status</th>' +
        '<th style="white-space:nowrap;">Refer\u00eancia</th>' +
        '<th class="td-amt" style="white-space:nowrap;">Valor\u00a0(BRL)</th>' +
        '<th class="td-amt" style="white-space:nowrap;">Pago</th>' +
        '<th class="td-amt" style="white-space:nowrap;">Restante</th>' +
        '<th>Notas</th>' +
        '<th></th>' +
      '</tr>';
  }

  function _renderExpenses316(id, data) {
    var tbody   = document.getElementById('doss-fin-exp-body');
    var empty   = document.getElementById('doss-fin-exp-empty');
    var totalEl = document.getElementById('doss-fin-exp-total');
    if (!tbody) return;

    /* Update thead */
    var table = tbody.closest ? tbody.closest('table') : tbody.parentNode;
    while (table && table.tagName !== 'TABLE') table = table.parentNode;
    _setExpHeader316(table);

    var refs = _dossRefs316(id);
    var globalRecs = _finLoad316().filter(function(r) {
      return r.tipo === 'saida' && refs[r.dossierRef || ''];
    });
    var gSids = Object.create(null);
    globalRecs.forEach(function(r) {
      if (r.source_id) gSids[r.source_id] = true;
      if (r.id)        gSids[r.id]        = true;
    });
    var localOnly = ((data && data.expenses) || []).filter(function(e) {
      return !(e.id && gSids[e.id]) && !(e.source_id && gSids[e.source_id]);
    });

    var allRows = globalRecs.concat(localOnly);
    tbody.innerHTML = '';

    if (!allRows.length) {
      if (empty)   empty.style.display = '';
      if (totalEl) totalEl.innerHTML   = '';
      return;
    }
    if (empty) empty.style.display = 'none';

    var BADGE  = { paid:'fbadge-paid', confirmed:'fbadge-confirmed', pending:'fbadge-pending', overdue:'fbadge-overdue', draft:'fbadge-draft' };
    var LABELS = { paid:'Pago', confirmed:'Confirmado', pending:'Pendente', overdue:'Vencido', draft:'Rascunho' };

    var totalBRL = 0, paidBRL = 0;

    allRows.forEach(function(r) {
      var n = _normalizeExp316(r);
      totalBRL += n.brl;
      paidBRL  += n.paidBRL;

      var badgeCls    = BADGE[n.statusKey]  || 'fbadge-draft';
      var statusLabel = LABELS[n.statusKey] || n.statusKey;
      var actionCell  = n.isSync
        ? '<span style="font-size:0.6rem;color:var(--navy-faint);">sync</span>'
        : '<button class="db-action-btn" onclick="dossFinEditLine(\'exp\',\'' + _esc316(n._id) + '\')" title="Editar">&#9999;</button>' +
          '<button class="db-action-btn del" onclick="dossFinDeleteLine(\'exp\',\'' + _esc316(n._id) + '\')" title="Apagar">&times;</button>';

      /* ── CC metadata cells ── */
      var ccProg  = n.isCC && n.programme    ? '<span style="display:inline-block;background:rgba(6,32,59,0.07);border-radius:3px;padding:1px 5px;font-size:0.66rem;white-space:nowrap;">' + _esc316(n.programme) + '</span>' : '<span style="color:var(--navy-faint);">\u2014</span>';
      var ccVol   = n.isCC && n.volume_miles > 0 ? '<span style="font-family:monospace;font-size:0.72rem;">' + _fmtMiles316(n.volume_miles) + '</span>' : '<span style="color:var(--navy-faint);">\u2014</span>';
      var ccCpm   = n.isCC && n.cpm_brl      > 0 ? '<span style="font-family:monospace;font-size:0.72rem;">' + _fmtRate316(n.cpm_brl) + '</span>'     : '<span style="color:var(--navy-faint);">\u2014</span>';
      var ccTaxas = n.isCC && n.taxas_brl    > 0 ? '<span style="font-family:monospace;font-size:0.72rem;">' + _fmtBRL316(n.taxas_brl) + '</span>'    : '<span style="color:var(--navy-faint);">\u2014</span>';

      var tr = document.createElement('tr');
      if (n.isCC) tr.style.background = 'rgba(251,191,36,0.04)';

      tr.innerHTML =
        /* 0 Fornecedor  */ '<td style="font-weight:600;">' + _esc316(n.supplier) + '</td>' +
        /* 1 Programme   */ '<td>' + ccProg + '</td>' +
        /* 2 Vol (Miles) */ '<td style="text-align:right;">' + ccVol + '</td>' +
        /* 3 CPM         */ '<td style="text-align:right;">' + ccCpm + '</td>' +
        /* 4 Taxas       */ '<td style="text-align:right;">' + ccTaxas + '</td>' +
        /* 5 Categoria   */ '<td><span class="fbadge fbadge-draft" style="font-size:0.54rem;">' + _esc316(n.category) + '</span></td>' +
        /* 6 Vencimento  */ '<td style="white-space:nowrap;font-size:0.8rem;">' + _dateLbl316(n.dateVal) + '</td>' +
        /* 7 Status      */ '<td class="td-status"><span class="fbadge ' + badgeCls + '">' + statusLabel + '</span></td>' +
        /* 8 Referência  */ '<td style="font-family:monospace;font-size:0.65rem;color:var(--gold);max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + _esc316(n.pnrRef) + '">' + _esc316(n.pnrRef) + '</td>' +
        /* 9 Valor BRL   */ '<td class="td-amt" style="white-space:nowrap;">' + _fmtBRL316(n.brl) + '</td>' +
        /* 10 Pago       */ '<td class="td-amt" style="color:#16a34a;white-space:nowrap;">' + _fmtBRL316(n.paidBRL) + '</td>' +
        /* 11 Restante   */ '<td class="td-amt" style="color:' + (n.remBRL>0?'var(--red)':'#16a34a') + ';white-space:nowrap;">' + _fmtBRL316(n.remBRL) + '</td>' +
        /* 12 Notas      */ '<td style="font-size:0.7rem;color:var(--navy-faint);max-width:130px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + _esc316(n.notes) + '">' + _esc316(n.notes) + '</td>' +
        /* 13 Actions    */ '<td style="white-space:nowrap;">' + actionCell + '</td>';

      tbody.appendChild(tr);
    });

    if (totalEl) {
      var remBRL = totalBRL - paidBRL;
      totalEl.innerHTML =
        '<span style="color:var(--navy-soft);font-size:0.72rem;">Total:</span> <strong>' + _fmtBRL316(totalBRL) + '</strong>' +
        '\u00a0\u00a0<span style="color:var(--navy-soft);font-size:0.72rem;">Pago:</span> <strong style="color:#16a34a;">' + _fmtBRL316(paidBRL) + '</strong>' +
        '\u00a0\u00a0<span style="color:var(--navy-soft);font-size:0.72rem;">Restante:</span> <strong style="color:' + (remBRL>0?'var(--red)':'#16a34a') + ';">' + _fmtBRL316(remBRL) + '</strong>';
    }
  }

  /* ── Replace both the window-exposed renderer and the refresh helper ── */
  window._v36RenderExpenses = _renderExpenses316;

  window.v310RefreshDespesas = function() {
    try {
      var id   = _activeId316();
      var data = null;
      if (id) try { data = JSON.parse(localStorage.getItem('expatur_doss_finance_' + id) || 'null'); } catch(e) {}
      _renderExpenses316(id, data);
    } catch(e) { console.warn('[v3.16] refresh error', e); }
  };

  /* ── Patch dossFinRenderPanel so the new renderer is used on every open ─ */
  var _prev316Panel = window.dossFinRenderPanel;
  if (typeof _prev316Panel === 'function' && !window._v316PanelWrap) {
    window._v316PanelWrap = true;
    window.dossFinRenderPanel = function() {
      if (typeof _prev316Panel === 'function') _prev316Panel.apply(this, arguments);
      /* After the chain renders, if expenses tab is active re-run our renderer */
      setTimeout(function() {
        try {
          var ab = document.querySelector('.doss-fin-tab.active');
          if (ab && ab.dataset.dftab === 'expenses') window.v310RefreshDespesas();
        } catch(e) {}
      }, 0);
    };
  }

  console.log('[Patch v3.16] Definitive CC sync active: reads mc-sel/mc-forn/mc-vol/mc-cpm/mc-fee/mc-sub per row in ONE pass.');

})(); // end Patch v3.16

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.17 — Cost Calculator: Leg SELECT column
   Guard: window._v317LegColumn

   FEATURE
   ───────
   Adds a "Trecho" (leg) SELECT as the FIRST editable column of every Cost
   Calculator row, immediately after the drag handle. Options are populated
   from the validated itinerary legs already present in the billet record.

   Option format:    CDG → GRU — AF123
   Hover tooltip:    CDG → GRU — AF123\nPNR: ABC123\nTicket: 2201234567890
   (PNR + ticket only if already saved in expatur_billet_[ref])

   PERSISTENCE
   ───────────
   CC row state (including selected leg index) is saved to:
     expatur_cc_rows_[ref]    (JSON array: [{rid, leg_idx, prog, forn, ...}])
   Restored on page load and whenever the billet modal populates #bl-body.

   LEG DATA SOURCE (priority)
   ──────────────────────────
   1. document.getElementById('bl-body').dataset.legsJson  — live DOM (billet open)
   2. localStorage expatur_billet_[ref].legs               — previously saved billet
   3. [] — empty (placeholder only, no options until billet is saved)

   FINANCE SYNC EXTENSION
   ──────────────────────
   dossFinSyncFromTarification is wrapped to also write linked leg metadata
   onto the matching costcalc_line__ records in both storage locations:
     linked_leg_idx, linked_leg_label, linked_leg_dep, linked_leg_arr, linked_leg_fn

   HEADER INJECTION
   ────────────────
   "Trecho" header div inserted after the drag-handle spacer in .miles-hdr-row.
   Idempotent (skipped if [data-leg-hdr] already present).
   ══════════════════════════════════════════════════════════════════════════ */
(function() {
  if (window._v317LegColumn) return;
  window._v317LegColumn = true;

  /* ── Storage key helpers ─────────────────────────────────────────────── */
  function _getBookingRef317() {
    var el = document.getElementById('booking-ref');
    return (el ? (el.value || '').trim() : '') || 'DEVIS';
  }
  function _ccStorageKey317() {
    return 'expatur_cc_rows_' + _getBookingRef317().replace(/[^a-zA-Z0-9]/g, '_');
  }
  function _billetStorageKey317() {
    return 'expatur_billet_' + _getBookingRef317().replace(/[^a-zA-Z0-9]/g, '_');
  }

  /* ── Leg data source ─────────────────────────────────────────────────── */
  function _getMilesLegs317() {
    // Priority 1: live DOM (billet panel rendered)
    try {
      var blBody = document.getElementById('bl-body');
      if (blBody && blBody.dataset.legsJson) {
        var legs = JSON.parse(blBody.dataset.legsJson);
        if (Array.isArray(legs) && legs.length > 0) return legs;
      }
    } catch(e) {}
    // Priority 2: saved billet record
    try {
      var rec = JSON.parse(localStorage.getItem(_billetStorageKey317()) || 'null');
      if (rec && Array.isArray(rec.legs) && rec.legs.length > 0) return rec.legs;
    } catch(e) {}
    return [];
  }

  /* ── Label + tooltip ─────────────────────────────────────────────────── */
  function _legLabel317(leg) {
    var dep = leg.dep || leg.depCode || '';
    var arr = leg.arr || leg.arrCode || '';
    var fn  = leg.fn  || leg.flightNumber || '';
    return dep + ' \u2192 ' + arr + (fn ? ' \u2014 ' + fn : '');
  }

  function _updateLegTooltip317(rid) {
    var sel = document.getElementById('mc-leg-' + rid);
    if (!sel) return;
    var idx = parseInt(sel.value, 10);
    if (isNaN(idx) || idx < 0) { sel.title = ''; return; }
    var legs = _getMilesLegs317();
    var leg  = legs[idx];
    if (!leg) { sel.title = ''; return; }

    var tooltip = _legLabel317(leg);
    try {
      var rec = JSON.parse(localStorage.getItem(_billetStorageKey317()) || 'null');
      if (rec) {
        var pnr = rec.isMC ? (leg.pnr || rec.masterPnr || '') : (rec.masterPnr || '');
        if (pnr) tooltip += '\nPNR: ' + pnr;
        if (Array.isArray(rec.pax) && rec.pax[0] && Array.isArray(rec.pax[0].etkts)) {
          var tkt = rec.pax[0].etkts[idx];
          if (tkt) tooltip += '\nTicket: ' + tkt;
        }
      }
    } catch(e) {}
    sel.title = tooltip;
  }

  /* ── Populate options on an existing SELECT ──────────────────────────── */
  function _populateLegSel317(rid, selectedIdx) {
    var sel = document.getElementById('mc-leg-' + rid);
    if (!sel) return;
    var legs = _getMilesLegs317();
    var prev = (selectedIdx !== undefined && !isNaN(selectedIdx))
               ? selectedIdx
               : parseInt(sel.value, 10);

    sel.innerHTML = '<option value="-1">\u2014 Selecionar trecho \u2014</option>';
    legs.forEach(function(leg, i) {
      var opt = document.createElement('option');
      opt.value = i;
      opt.textContent = _legLabel317(leg);
      sel.appendChild(opt);
    });
    sel.value = (!isNaN(prev) && prev >= 0 && prev < legs.length) ? prev : '-1';
    _updateLegTooltip317(rid);
  }

  /* ── Build leg SELECT div for a new row ──────────────────────────────── */
  function _makeLegDiv317(rid) {
    var div = document.createElement('div');
    div.style.cssText = 'flex:1.8;min-width:130px;';
    div.setAttribute('data-leg-col', '1');

    var sel = document.createElement('select');
    sel.id = 'mc-leg-' + rid;
    sel.style.cssText = 'width:100%;font-size:12px;padding:2px 4px;' +
                        'border:1px solid #c8d6e5;border-radius:4px;' +
                        'background:#fff;cursor:pointer;';
    sel.innerHTML = '<option value="-1">\u2014 Selecionar trecho \u2014</option>';

    // Populate immediately in case billet data is available
    var legs = _getMilesLegs317();
    legs.forEach(function(leg, i) {
      var opt = document.createElement('option');
      opt.value = i;
      opt.textContent = _legLabel317(leg);
      sel.appendChild(opt);
    });

    sel.addEventListener('change', function() {
      _updateLegTooltip317(rid);
      _saveCCRows317();
    });

    div.appendChild(sel);
    return div;
  }

  /* ── Header injection ────────────────────────────────────────────────── */
  function _injectLegHeader317() {
    var hdrRow = document.querySelector('.miles-hdr-row');
    if (!hdrRow || hdrRow.querySelector('[data-leg-hdr]')) return;

    var hdrDiv = document.createElement('div');
    hdrDiv.className = 'miles-col-hdr';
    hdrDiv.style.cssText = 'flex:1.8;min-width:130px;';
    hdrDiv.setAttribute('data-leg-hdr', '1');
    hdrDiv.textContent = 'Trecho';

    // Insert after children[0] (drag-handle spacer)
    var anchor = hdrRow.children[0];
    if (anchor && anchor.nextSibling) {
      hdrRow.insertBefore(hdrDiv, anchor.nextSibling);
    } else {
      hdrRow.appendChild(hdrDiv);
    }
  }

  /* ── Persist CC row state ────────────────────────────────────────────── */
  function _saveCCRows317() {
    try {
      var container = document.getElementById('miles-rows');
      if (!container) return;
      var saved = [];
      container.querySelectorAll('.miles-row-wrap').forEach(function(rowEl) {
        var rid = (rowEl.id || '').replace('miles-row-', '').trim();
        if (!rid) return;
        var legSel  = document.getElementById('mc-leg-'  + rid);
        var progSel = document.getElementById('mc-sel-'  + rid);
        var fornSel = document.getElementById('mc-forn-' + rid);
        var volEl   = document.getElementById('mc-vol-'  + rid);
        var cpmEl   = document.getElementById('mc-cpm-'  + rid);
        var feeEl   = document.getElementById('mc-fee-'  + rid);
        var extEl   = document.getElementById('mc-ext-'  + rid);
        saved.push({
          rid:     rid,
          leg_idx: legSel  ? parseInt(legSel.value, 10) : -1,
          prog:    progSel ? progSel.value               : '',
          forn:    fornSel ? fornSel.value               : '',
          vol:     volEl   ? (isNaN(volEl.valueAsNumber) ? 0 : (volEl.valueAsNumber || 0)) : 0,
          cpm:     cpmEl   ? (isNaN(cpmEl.valueAsNumber) ? 0 : (cpmEl.valueAsNumber || 0)) : 0,
          fee:     feeEl   ? (isNaN(feeEl.valueAsNumber) ? 0 : (feeEl.valueAsNumber || 0)) : 0,
          ext:     extEl   ? (extEl.value || '')          : ''
        });
      });
      localStorage.setItem(_ccStorageKey317(), JSON.stringify(saved));
    } catch(e) { console.warn('[v3.17] saveCCRows error', e); }
  }

  /* ── Restore CC row state (populate leg selects on existing rows) ─────── */
  function _restoreCCRows317() {
    try {
      var saved = JSON.parse(localStorage.getItem(_ccStorageKey317()) || 'null');
      var container = document.getElementById('miles-rows');
      if (!container) { _injectLegHeader317(); return; }

      // First ensure all existing rows have a leg SELECT injected
      container.querySelectorAll('.miles-row-wrap').forEach(function(rowEl) {
        var rid = (rowEl.id || '').replace('miles-row-', '').trim();
        if (!rid) return;
        if (!document.getElementById('mc-leg-' + rid)) {
          var legDiv = _makeLegDiv317(rid);
          if (rowEl.children.length > 1) {
            rowEl.insertBefore(legDiv, rowEl.children[1]);
          } else {
            rowEl.appendChild(legDiv);
          }
        }
      });

      // Then restore saved selections
      if (Array.isArray(saved)) {
        saved.forEach(function(rowData) {
          if (!rowData.rid) return;
          _populateLegSel317(rowData.rid,
            (rowData.leg_idx >= 0) ? rowData.leg_idx : undefined);
        });
      } else {
        // No saved data — still populate options if billet is available
        container.querySelectorAll('.miles-row-wrap').forEach(function(rowEl) {
          var rid = (rowEl.id || '').replace('miles-row-', '').trim();
          if (rid) _populateLegSel317(rid);
        });
      }

      _injectLegHeader317();
    } catch(e) { console.warn('[v3.17] restoreCCRows error', e); }
  }

  /* ── Wrap addMilesRow ────────────────────────────────────────────────── */
  if (typeof window.addMilesRow === 'function' && !window._v317AddMilesRowWrap) {
    window._v317AddMilesRowWrap = true;
    var _origAddMilesRow317 = window.addMilesRow;
    window.addMilesRow = function() {
      _origAddMilesRow317.apply(this, arguments);
      // Grab the last added row
      var container = document.getElementById('miles-rows');
      if (!container) return;
      var rows = container.querySelectorAll('.miles-row-wrap');
      var lastRow = rows[rows.length - 1];
      if (!lastRow) return;
      var rid = (lastRow.id || '').replace('miles-row-', '').trim();
      if (!rid) return;

      // Inject leg SELECT as children[1] (after drag handle at [0])
      if (!document.getElementById('mc-leg-' + rid)) {
        var legDiv = _makeLegDiv317(rid);
        if (lastRow.children.length > 1) {
          lastRow.insertBefore(legDiv, lastRow.children[1]);
        } else {
          lastRow.appendChild(legDiv);
        }
      }
      _injectLegHeader317();
    };
  }

  /* ── Wrap openBilletModal to refresh leg SELECTs after render ────────── */
  if (typeof window.openBilletModal === 'function' && !window._v317BilletModalWrap) {
    window._v317BilletModalWrap = true;
    var _origOpenBilletModal317 = window.openBilletModal;
    window.openBilletModal = function() {
      _origOpenBilletModal317.apply(this, arguments);
      // legsJson is set synchronously inside openBilletModal; a short
      // setTimeout ensures the DOM is flushed before we read it back.
      setTimeout(function() {
        var container = document.getElementById('miles-rows');
        if (!container) return;
        container.querySelectorAll('.miles-row-wrap').forEach(function(rowEl) {
          var rid = (rowEl.id || '').replace('miles-row-', '').trim();
          if (!rid || !document.getElementById('mc-leg-' + rid)) return;
          var cur = parseInt(document.getElementById('mc-leg-' + rid).value, 10);
          _populateLegSel317(rid, (!isNaN(cur) && cur >= 0) ? cur : undefined);
        });
      }, 150);
    };
  }

  /* ── Wrap calcMilesTotal to auto-save CC state ───────────────────────── */
  if (typeof window.calcMilesTotal === 'function' && !window._v317CalcWrap) {
    window._v317CalcWrap = true;
    var _origCalcMilesTotal317 = window.calcMilesTotal;
    window.calcMilesTotal = function() {
      _origCalcMilesTotal317.apply(this, arguments);
      setTimeout(_saveCCRows317, 50);
    };
  }

  /* ── Finance sync: extend costcalc records with linked leg metadata ───── */
  function _patchFinLegData317() {
    var id = localStorage.getItem('expatur_active_dossier');
    if (!id) return;
    var legs = _getMilesLegs317();
    if (!legs.length) return;

    var container = document.getElementById('miles-rows');
    if (!container) return;

    container.querySelectorAll('.miles-row-wrap').forEach(function(rowEl) {
      var rid = (rowEl.id || '').replace('miles-row-', '').trim();
      if (!rid) return;
      var sel = document.getElementById('mc-leg-' + rid);
      if (!sel) return;
      var idx = parseInt(sel.value, 10);
      if (isNaN(idx) || idx < 0 || idx >= legs.length) return;

      var leg = legs[idx];
      var sid = 'costcalc_line__' + id + '__' + rid;
      var meta = {
        linked_leg_idx:   idx,
        linked_leg_label: _legLabel317(leg),
        linked_leg_dep:   leg.dep || leg.depCode || '',
        linked_leg_arr:   leg.arr || leg.arrCode || '',
        linked_leg_fn:    leg.fn  || leg.flightNumber || ''
      };

      // Patch global lancamentos
      try {
        var FINK = 'expatur_financeiro_lancamentos';
        var allRecs = JSON.parse(localStorage.getItem(FINK) || '[]');
        var hit = false;
        allRecs = allRecs.map(function(r) {
          if (r.source_id === sid || r.id === sid) { hit = true; return Object.assign({}, r, meta); }
          return r;
        });
        if (hit) localStorage.setItem(FINK, JSON.stringify(allRecs));
      } catch(e) {}

      // Patch per-dossier shell expenses
      try {
        var ddFKey = 'expatur_doss_finance_' + id;
        var ddf = JSON.parse(localStorage.getItem(ddFKey) || 'null');
        if (ddf && Array.isArray(ddf.expenses)) {
          var patched = false;
          ddf.expenses = ddf.expenses.map(function(e) {
            if (e.source_id === sid || e.id === sid) { patched = true; return Object.assign({}, e, meta); }
            return e;
          });
          if (patched) localStorage.setItem(ddFKey, JSON.stringify(ddf));
        }
      } catch(e) {}
    });
  }

  if (typeof window.dossFinSyncFromTarification === 'function' && !window._v317FinLegWrap) {
    window._v317FinLegWrap = true;
    var _prev317Tarif = window.dossFinSyncFromTarification;
    window.dossFinSyncFromTarification = function() {
      _prev317Tarif.apply(this, arguments);
      try { _patchFinLegData317(); } catch(e) { console.warn('[v3.17] finLegWrap error', e); }
    };
  }

  /* ── Init ────────────────────────────────────────────────────────────── */
  function _init317() {
    _injectLegHeader317();
    _restoreCCRows317();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _init317);
  } else {
    setTimeout(_init317, 200);
  }

  console.log('[Patch v3.17] Leg column active: addMilesRow wrapped | leg SELECT per row | CC state → expatur_cc_rows_* | Finance linked_leg_* meta on sync');

})(); // end Patch v3.17

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.18 — TRECHO completion + Finance > Despesas DETAILS column
   Guard: window._v318TrechoDetails

   WHAT THIS PATCH DOES
   ────────────────────
   1. Protects the TRECHO (leg) SELECT column in Cost Calculator:
      · wraps onMilesIssuerChange to ensure mc-leg-* div is ALWAYS visible,
        even for VOLTA CANCELADA / VISA / ETA / Consolidator rows
      · these special types still show the TRECHO dropdown so the user can
        associate the row with the correct itinerary leg

   2. Extends Finance sync to write three extra fields onto every
      costcalc_line__ expense record:
        · linked_flight_date   — ISO date of the linked leg (leg.date)
        · linked_airline_iata  — 2-char airline code derived from flight number
        · linked_pnr           — PNR for that leg (masterPnr or MC leg.pnr)
      On-load backfill patches existing records that v3.17 wrote without these.

   3. Replaces window._v36RenderExpenses with a 15-column renderer that adds
      a DETAILS column after Programme:
        Format: CDG → GRU — 2026-05-14 — AF — PNR ABC123
        All parts are optional — only present parts are joined by " — "
        Non-CC rows fall back to programme name or "—"
        VOLTA CANCELADA / VISA / ETA rows show their programme name as DETAILS

   COLUMN ORDER (15 columns)
   ─────────────────────────
   Fornecedor | Programme | DETAILS | Vol.(Miles) | C.P.M(R$) | Taxas(R$)
   | Categoria | Vencimento | Status | Referência | Valor(BRL)
   | Pago | Restante | Notas | [actions]

   HELPERS RE-IMPLEMENTED (v3.16 equivalents, suffixed 318)
   ─────────────────────────────────────────────────────────
   All private v3.16 helpers (_brlOf316, _fmtBRL316, etc.) are inaccessible
   outside their IIFE. v3.18 re-implements minimal copies suffixed _318.
   ══════════════════════════════════════════════════════════════════════════ */
(function () {
  if (window._v318TrechoDetails) return;
  window._v318TrechoDetails = true;

  /* ═══════════════════════════════════════════════════════════════
     SECTION 1 — Shared helpers
  ═══════════════════════════════════════════════════════════════ */

  var _FINK318 = 'expatur_financeiro_lancamentos';

  function _esc318(s) {
    return String(s == null ? '' : s)
      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function _fmtBRL318(v) {
    var n = parseFloat(v) || 0;
    return 'R$\u00a0' + n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  function _fmtMiles318(v) {
    var n = parseFloat(v) || 0;
    return n === 0 ? '\u2014' : Math.round(n).toLocaleString('pt-BR');
  }
  function _fmtRate318(v) {
    var n = parseFloat(v) || 0;
    return n === 0 ? '\u2014' : n.toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 4 });
  }
  function _dateLbl318(d) {
    if (!d) return '\u2014';
    try { var p = String(d).slice(0, 10).split('-'); return p[2] + '/' + p[1] + '/' + p[0]; } catch (e) { return d; }
  }
  function _brlOf318(r) {
    if (r.brl_amount != null && r.brl_amount !== '') return parseFloat(r.brl_amount) || 0;
    return (parseFloat(r.amount || r.valor || 0)) * (parseFloat(r.fx_rate_to_brl) || 1);
  }
  function _activeId318() {
    return localStorage.getItem('expatur_active_dossier') || null;
  }
  function _dossRefs318(id) {
    var refs = Object.create(null);
    if (id) refs[id] = true;
    try {
      var dd = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null');
      if (dd && dd.fields && dd.fields['booking-ref']) refs[dd.fields['booking-ref']] = true;
    } catch (e) {}
    try {
      var dr = ((document.getElementById('booking-ref') || {}).value || '').trim();
      if (dr) refs[dr] = true;
    } catch (e) {}
    return refs;
  }
  function _finLoad318() {
    try { return JSON.parse(localStorage.getItem(_FINK318) || '[]'); } catch (e) { return []; }
  }
  function _normalizeExp318(r) {
    var isNew = r.tipo === 'saida' || r.fornecedor !== undefined || r.categoria !== undefined ||
                r.vencimento !== undefined || r.source_type !== undefined;
    var brl = _brlOf318(r);
    if (isNew) {
      var pago = r.pago || 'pendente';
      var sk   = pago === 'pago' ? 'paid' : (pago === 'atrasado' ? 'overdue' : 'pending');
      return {
        _id:              r.source_id || r.id || '',
        supplier:         r.fornecedor || r.supplier || '\u2014',
        category:         r.categoria  || r.category  || '\u2014',
        dateVal:          r.vencimento || r.dueDate   || '',
        statusKey:        sk,
        pnrRef:           r.source_id  || r.pnrRef    || '',
        brl:              brl,
        paidBRL:          pago === 'pago' ? brl : 0,
        remBRL:           pago === 'pago' ? 0   : brl,
        notes:            r.nota || r.notes || '',
        isSync:           true,
        isCC:             r.source_type === 'cost_calculator_line',
        programme:        r.programme     != null ? String(r.programme)    : '',
        volume_miles:     r.volume_miles  != null ? parseFloat(r.volume_miles)  || 0 : 0,
        cpm_brl:          r.cpm_brl       != null ? parseFloat(r.cpm_brl)       || 0 : 0,
        taxas_brl:        r.taxas_brl     != null ? parseFloat(r.taxas_brl)     || 0 : 0,
        /* v3.17 / v3.18 leg metadata */
        linked_leg_label:  r.linked_leg_label    || '',
        linked_leg_dep:    r.linked_leg_dep       || '',
        linked_leg_arr:    r.linked_leg_arr       || '',
        linked_leg_fn:     r.linked_leg_fn        || '',
        linked_flight_date: r.linked_flight_date  || '',
        linked_airline_iata: r.linked_airline_iata || '',
        linked_pnr:        r.linked_pnr           || ''
      };
    }
    /* Legacy manual record */
    var amt  = parseFloat(r.amount) || 0;
    var paid = parseFloat(r.paidAmount) || 0;
    brl      = _brlOf318(r) || amt;
    var st   = r.status || 'draft';
    var ip   = (st === 'paid' || st === 'pago');
    return {
      _id: r.id || '', supplier: r.supplier || '\u2014', category: r.category || '\u2014',
      dateVal: r.dueDate || '', statusKey: ip ? 'paid' : (st === 'overdue' ? 'overdue' : (st === 'confirmed' ? 'confirmed' : 'pending')),
      pnrRef: r.pnrRef || '', brl: brl,
      paidBRL: ip ? brl : (amt > 0 ? brl * paid / amt : 0),
      remBRL:  ip ? 0   : brl * (amt > 0 ? Math.max(0, amt - paid) / amt : 1),
      notes: r.notes || '', isSync: false, isCC: false,
      programme: '', volume_miles: 0, cpm_brl: 0, taxas_brl: 0,
      linked_leg_label: '', linked_leg_dep: '', linked_leg_arr: '', linked_leg_fn: '',
      linked_flight_date: '', linked_airline_iata: '', linked_pnr: ''
    };
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 2 — DETAILS cell builder
  ═══════════════════════════════════════════════════════════════ */

  function _fmtDate318(iso) {
    if (!iso) return '';
    try {
      var d = new Date(iso + 'T12:00:00Z');
      return d.toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' });
    } catch (e) { return iso; }
  }

  function _buildDetails318(n) {
    /* n = normalized record from _normalizeExp318 */
    var parts = [];

    /* TRECHO (dep → arr — fn) or full label */
    var trecho = '';
    if (n.linked_leg_dep && n.linked_leg_arr) {
      trecho = n.linked_leg_dep + ' \u2192 ' + n.linked_leg_arr;
      if (n.linked_leg_fn) trecho += ' \u2014 ' + n.linked_leg_fn;
    } else if (n.linked_leg_label) {
      trecho = n.linked_leg_label;
    }
    if (trecho) parts.push(trecho);

    /* Flight date */
    if (n.linked_flight_date) parts.push(_fmtDate318(n.linked_flight_date));

    /* Airline IATA */
    if (n.linked_airline_iata) parts.push(n.linked_airline_iata);

    /* PNR */
    if (n.linked_pnr) parts.push('PNR\u00a0' + n.linked_pnr);

    if (parts.length) return parts.join(' \u2014 ');

    /* Fallback: programme name as description */
    if (n.programme) return n.programme;

    return '';
  }

  function _detailsTD318(n) {
    var d = _buildDetails318(n);
    if (!d) return '<td style="color:var(--navy-faint);">\u2014</td>';
    var escaped = _esc318(d);
    return '<td style="font-size:0.64rem;font-family:monospace;max-width:200px;' +
           'overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--navy);" ' +
           'title="' + escaped + '">' + escaped + '</td>';
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 3 — 15-column Despesas renderer (replaces v3.16)
  ═══════════════════════════════════════════════════════════════ */

  function _setExpHeader318(table) {
    if (!table || !table.tHead) return;
    table.tHead.innerHTML =
      '<tr>' +
        '<th>Fornecedor</th>' +
        '<th>Programme</th>' +
        '<th style="max-width:200px;">D\u00e9tails</th>' +
        '<th style="text-align:right;white-space:nowrap;">Vol.\u00a0(Miles)</th>' +
        '<th style="text-align:right;white-space:nowrap;">C.P.M\u00a0(R$)</th>' +
        '<th style="text-align:right;white-space:nowrap;">Taxas\u00a0(R$)</th>' +
        '<th>Categoria</th>' +
        '<th style="white-space:nowrap;">Vencimento</th>' +
        '<th>Status</th>' +
        '<th style="white-space:nowrap;">Refer\u00eancia</th>' +
        '<th class="td-amt" style="white-space:nowrap;">Valor\u00a0(BRL)</th>' +
        '<th class="td-amt" style="white-space:nowrap;">Pago</th>' +
        '<th class="td-amt" style="white-space:nowrap;">Restante</th>' +
        '<th>Notas</th>' +
        '<th></th>' +
      '</tr>';
  }

  function _renderExpenses318(id, data) {
    var tbody   = document.getElementById('doss-fin-exp-body');
    var empty   = document.getElementById('doss-fin-exp-empty');
    var totalEl = document.getElementById('doss-fin-exp-total');
    if (!tbody) return;

    /* Update thead */
    var table = tbody;
    while (table && table.tagName !== 'TABLE') table = table.parentNode;
    _setExpHeader318(table);

    var refs      = _dossRefs318(id);
    var globalRecs = _finLoad318().filter(function (r) {
      return r.tipo === 'saida' && refs[r.dossierRef || ''];
    });
    var gSids = Object.create(null);
    globalRecs.forEach(function (r) {
      if (r.source_id) gSids[r.source_id] = true;
      if (r.id)        gSids[r.id]        = true;
    });
    var localOnly = ((data && data.expenses) || []).filter(function (e) {
      return !(e.id && gSids[e.id]) && !(e.source_id && gSids[e.source_id]);
    });

    var allRows = globalRecs.concat(localOnly);
    tbody.innerHTML = '';

    if (!allRows.length) {
      if (empty)   empty.style.display = '';
      if (totalEl) totalEl.innerHTML   = '';
      return;
    }
    if (empty) empty.style.display = 'none';

    var BADGE  = { paid: 'fbadge-paid', confirmed: 'fbadge-confirmed', pending: 'fbadge-pending', overdue: 'fbadge-overdue', draft: 'fbadge-draft' };
    var LABELS = { paid: 'Pago', confirmed: 'Confirmado', pending: 'Pendente', overdue: 'Vencido', draft: 'Rascunho' };

    var totalBRL = 0, paidBRL = 0;

    allRows.forEach(function (r) {
      var n = _normalizeExp318(r);
      totalBRL += n.brl;
      paidBRL  += n.paidBRL;

      var badgeCls    = BADGE[n.statusKey]  || 'fbadge-draft';
      var statusLabel = LABELS[n.statusKey] || n.statusKey;
      var actionCell  = n.isSync
        ? '<span style="font-size:0.6rem;color:var(--navy-faint);">sync</span>'
        : '<button class="db-action-btn" onclick="dossFinEditLine(\'exp\',\'' + _esc318(n._id) + '\')" title="Editar">&#9999;</button>' +
          '<button class="db-action-btn del" onclick="dossFinDeleteLine(\'exp\',\'' + _esc318(n._id) + '\')" title="Apagar">&times;</button>';

      /* CC metadata cells */
      var ccProg  = n.isCC && n.programme
        ? '<span style="display:inline-block;background:rgba(6,32,59,0.07);border-radius:3px;padding:1px 5px;font-size:0.66rem;white-space:nowrap;">' + _esc318(n.programme) + '</span>'
        : '<span style="color:var(--navy-faint);">\u2014</span>';
      var ccVol   = n.isCC && n.volume_miles > 0
        ? '<span style="font-family:monospace;font-size:0.72rem;">' + _fmtMiles318(n.volume_miles) + '</span>'
        : '<span style="color:var(--navy-faint);">\u2014</span>';
      var ccCpm   = n.isCC && n.cpm_brl > 0
        ? '<span style="font-family:monospace;font-size:0.72rem;">' + _fmtRate318(n.cpm_brl) + '</span>'
        : '<span style="color:var(--navy-faint);">\u2014</span>';
      var ccTaxas = n.isCC && n.taxas_brl > 0
        ? '<span style="font-family:monospace;font-size:0.72rem;">' + _fmtBRL318(n.taxas_brl) + '</span>'
        : '<span style="color:var(--navy-faint);">\u2014</span>';

      var tr = document.createElement('tr');
      if (n.isCC) tr.style.background = 'rgba(251,191,36,0.04)';

      tr.innerHTML =
        /* 0  Fornecedor  */ '<td style="font-weight:600;">' + _esc318(n.supplier) + '</td>' +
        /* 1  Programme   */ '<td>' + ccProg + '</td>' +
        /* 2  DETAILS     */ _detailsTD318(n) +
        /* 3  Vol (Miles) */ '<td style="text-align:right;">' + ccVol + '</td>' +
        /* 4  CPM         */ '<td style="text-align:right;">' + ccCpm + '</td>' +
        /* 5  Taxas       */ '<td style="text-align:right;">' + ccTaxas + '</td>' +
        /* 6  Categoria   */ '<td><span class="fbadge fbadge-draft" style="font-size:0.54rem;">' + _esc318(n.category) + '</span></td>' +
        /* 7  Vencimento  */ '<td style="white-space:nowrap;font-size:0.8rem;">' + _dateLbl318(n.dateVal) + '</td>' +
        /* 8  Status      */ '<td class="td-status"><span class="fbadge ' + badgeCls + '">' + statusLabel + '</span></td>' +
        /* 9  Referência  */ '<td style="font-family:monospace;font-size:0.65rem;color:var(--gold);max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + _esc318(n.pnrRef) + '">' + _esc318(n.pnrRef) + '</td>' +
        /* 10 Valor BRL   */ '<td class="td-amt" style="white-space:nowrap;">' + _fmtBRL318(n.brl) + '</td>' +
        /* 11 Pago        */ '<td class="td-amt" style="color:#16a34a;white-space:nowrap;">' + _fmtBRL318(n.paidBRL) + '</td>' +
        /* 12 Restante    */ '<td class="td-amt" style="color:' + (n.remBRL > 0 ? 'var(--red)' : '#16a34a') + ';white-space:nowrap;">' + _fmtBRL318(n.remBRL) + '</td>' +
        /* 13 Notas       */ '<td style="font-size:0.7rem;color:var(--navy-faint);max-width:130px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + _esc318(n.notes) + '">' + _esc318(n.notes) + '</td>' +
        /* 14 Actions     */ '<td style="white-space:nowrap;">' + actionCell + '</td>';

      tbody.appendChild(tr);
    });

    if (totalEl) {
      var remBRL = totalBRL - paidBRL;
      totalEl.innerHTML =
        '<span style="color:var(--navy-soft);font-size:0.72rem;">Total:</span> <strong>' + _fmtBRL318(totalBRL) + '</strong>' +
        '\u00a0\u00a0<span style="color:var(--navy-soft);font-size:0.72rem;">Pago:</span> <strong style="color:#16a34a;">' + _fmtBRL318(paidBRL) + '</strong>' +
        '\u00a0\u00a0<span style="color:var(--navy-soft);font-size:0.72rem;">Restante:</span> <strong style="color:' + (remBRL > 0 ? 'var(--red)' : '#16a34a') + ';">' + _fmtBRL318(remBRL) + '</strong>';
    }
  }

  /* Replace all renderer entry points */
  window._v36RenderExpenses = _renderExpenses318;
  window.v310RefreshDespesas = function () {
    try {
      var id   = _activeId318();
      var data = null;
      if (id) try { data = JSON.parse(localStorage.getItem('expatur_doss_finance_' + id) || 'null'); } catch (e) {}
      _renderExpenses318(id, data);
    } catch (e) { console.warn('[v3.18] refresh error', e); }
  };

  /* Re-override panel so new renderer fires on every tab open */
  var _prev318Panel = window.dossFinRenderPanel;
  if (typeof _prev318Panel === 'function' && !window._v318PanelWrap) {
    window._v318PanelWrap = true;
    window.dossFinRenderPanel = function () {
      if (typeof _prev318Panel === 'function') _prev318Panel.apply(this, arguments);
      setTimeout(function () {
        try {
          var ab = document.querySelector('.doss-fin-tab.active');
          if (ab && ab.dataset.dftab === 'expenses') window.v310RefreshDespesas();
        } catch (e) {}
      }, 0);
    };
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 4 — Finance sync extension (flight_date, airline_iata, pnr)
  ═══════════════════════════════════════════════════════════════ */

  function _getBookingRef318() {
    var el = document.getElementById('booking-ref');
    return (el ? (el.value || '').trim() : '') || 'DEVIS';
  }
  function _billetKey318() {
    return 'expatur_billet_' + _getBookingRef318().replace(/[^a-zA-Z0-9]/g, '_');
  }
  function _getMilesLegsWithRecord318() {
    /* Returns { legs: [], record: null|{} } */
    try {
      var blBody = document.getElementById('bl-body');
      if (blBody && blBody.dataset.legsJson) {
        var legs = JSON.parse(blBody.dataset.legsJson);
        if (Array.isArray(legs) && legs.length > 0) {
          var rec318 = null;
          try { rec318 = JSON.parse(localStorage.getItem(_billetKey318()) || 'null'); } catch (e) {}
          return { legs: legs, record: rec318 };
        }
      }
    } catch (e) {}
    try {
      var r318 = JSON.parse(localStorage.getItem(_billetKey318()) || 'null');
      if (r318 && Array.isArray(r318.legs) && r318.legs.length > 0) return { legs: r318.legs, record: r318 };
    } catch (e) {}
    return { legs: [], record: null };
  }
  function _guessAirlineIata318(fn) {
    return (typeof window.getAirlineLogoCode === 'function') ? String(window.getAirlineLogoCode(fn || '') || '').toUpperCase() : '';
  }

  function _patchLegMetaOnRecords318(sid, meta) {
    /* Patch global lancamentos */
    try {
      var allRecs = _finLoad318();
      var hit = false;
      allRecs = allRecs.map(function (r) {
        if (r.source_id === sid || r.id === sid) { hit = true; return Object.assign({}, r, meta); }
        return r;
      });
      if (hit) localStorage.setItem(_FINK318, JSON.stringify(allRecs));
    } catch (e) {}

    /* Patch per-dossier shell */
    var id = _activeId318();
    if (!id) return;
    try {
      var ddFKey = 'expatur_doss_finance_' + id;
      var ddf = JSON.parse(localStorage.getItem(ddFKey) || 'null');
      if (ddf && Array.isArray(ddf.expenses)) {
        var patched = false;
        ddf.expenses = ddf.expenses.map(function (e) {
          if (e.source_id === sid || e.id === sid) { patched = true; return Object.assign({}, e, meta); }
          return e;
        });
        if (patched) localStorage.setItem(ddFKey, JSON.stringify(ddf));
      }
    } catch (e) {}
  }

  function _patchFinLegMeta318() {
    var id = _activeId318();
    if (!id) return;
    var data = _getMilesLegsWithRecord318();
    var legs = data.legs;
    if (!legs.length) return;
    var rec  = data.record;

    var container = document.getElementById('miles-rows');
    if (!container) return;

    container.querySelectorAll('.miles-row-wrap').forEach(function (rowEl) {
      var rid = (rowEl.id || '').replace('miles-row-', '').trim();
      if (!rid) return;
      var sel = document.getElementById('mc-leg-' + rid);
      if (!sel) return;
      var idx = parseInt(sel.value, 10);
      if (isNaN(idx) || idx < 0 || idx >= legs.length) return;

      var leg = legs[idx];
      var sid = 'costcalc_line__' + id + '__' + rid;

      /* PNR: MC uses per-leg PNR, single/return uses masterPnr */
      var pnr = rec
        ? (rec.isMC ? (leg.pnr || rec.masterPnr || '') : (rec.masterPnr || ''))
        : '';

      var meta = {
        linked_flight_date:   leg.date || leg.depDate || '',
        linked_airline_iata:  _guessAirlineIata318(leg.fn || leg.label || ''),
        linked_pnr:           pnr
      };

      _patchLegMetaOnRecords318(sid, meta);
    });
  }

  /* Wrap dossFinSyncFromTarification (separate from v3.17 wrap) */
  if (typeof window.dossFinSyncFromTarification === 'function' && !window._v318FinLegWrap) {
    window._v318FinLegWrap = true;
    var _prev318Tarif = window.dossFinSyncFromTarification;
    window.dossFinSyncFromTarification = function () {
      _prev318Tarif.apply(this, arguments);
      try { _patchFinLegMeta318(); } catch (e) { console.warn('[v3.18] finLegMeta error', e); }
    };
  }

  /* On-load backfill: patch any existing CC records that are missing the new fields */
  function _backfillLegMeta318() {
    var id = _activeId318();
    if (!id) return;
    var data = _getMilesLegsWithRecord318();
    if (!data.legs.length) return;

    /* Only patch records that have linked_leg_idx but are missing linked_flight_date */
    var allRecs = _finLoad318();
    var needsPatch = allRecs.filter(function (r) {
      return r.source_type === 'cost_calculator_line' &&
             r.linked_leg_idx != null &&
             !r.linked_flight_date;
    });
    if (!needsPatch.length) return;

    /* Use saved CC rows state to recover leg index per rid */
    var ccKey = 'expatur_cc_rows_' + _getBookingRef318().replace(/[^a-zA-Z0-9]/g, '_');
    var ccRows = [];
    try { ccRows = JSON.parse(localStorage.getItem(ccKey) || '[]'); } catch (e) {}

    needsPatch.forEach(function (r) {
      /* Extract rid from source_id: costcalc_line__[id]__[rid] */
      var sidParts = (r.source_id || '').split('__');
      if (sidParts.length < 3) return;
      var rid = sidParts[sidParts.length - 1];

      /* Get leg_idx from live DOM first, then from saved CC state */
      var legSel = document.getElementById('mc-leg-' + rid);
      var idx = legSel ? parseInt(legSel.value, 10) : NaN;
      if (isNaN(idx) || idx < 0) {
        var rowState = ccRows.find(function (cr) { return cr.rid === rid; });
        idx = rowState ? parseInt(rowState.leg_idx, 10) : NaN;
      }
      if (isNaN(idx) || idx < 0 || idx >= data.legs.length) return;

      var leg = data.legs[idx];
      var pnr = data.record
        ? (data.record.isMC ? (leg.pnr || data.record.masterPnr || '') : (data.record.masterPnr || ''))
        : '';

      _patchLegMetaOnRecords318(r.source_id || r.id, {
        linked_flight_date:  leg.date || leg.depDate || '',
        linked_airline_iata: _guessAirlineIata318(leg.fn || leg.label || ''),
        linked_pnr:          pnr
      });
    });
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 5 — Protect TRECHO (mc-leg-*) visibility
     onMilesIssuerChange hides vol/cpm wraps but must NEVER hide
     the leg SELECT div regardless of issuer/programme type.
  ═══════════════════════════════════════════════════════════════ */

  if (typeof window.onMilesIssuerChange === 'function' && !window._v318IssuerWrap) {
    window._v318IssuerWrap = true;
    var _origIssuerChange318 = window.onMilesIssuerChange;
    window.onMilesIssuerChange = function (id) {
      _origIssuerChange318.apply(this, arguments);
      /* Always ensure leg SELECT container is visible */
      try {
        var legSel = document.getElementById('mc-leg-' + id);
        if (legSel && legSel.parentNode) {
          var legDiv = legSel.parentNode;
          if (legDiv.style.visibility === 'hidden') legDiv.style.visibility = '';
          if (legDiv.style.display    === 'none')   legDiv.style.display    = '';
        }
      } catch (e) {}
    };
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 6 — Init
  ═══════════════════════════════════════════════════════════════ */

  function _init318() {
    /* Refresh Despesas if panel is already visible */
    try {
      var ab = document.querySelector('.doss-fin-tab.active');
      if (ab && ab.dataset.dftab === 'expenses') window.v310RefreshDespesas();
    } catch (e) {}
    /* Backfill existing CC records with flight_date / airline_iata / pnr */
    setTimeout(_backfillLegMeta318, 400);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _init318);
  } else {
    setTimeout(_init318, 250);
  }

  console.log('[Patch v3.18] TRECHO protection + DETAILS column active: 15-col Despesas renderer, leg meta backfill, onMilesIssuerChange guarded.');

})(); // end Patch v3.18

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.19 — Live Itinerary → TRECHO sync
   Guard: window._v319LiveItinLegs

   ROOT CAUSE FIXED
   ────────────────
   v3.17/v3.18 read legs from billet storage only (expatur_billet_[ref].legs
   and #bl-body.dataset.legsJson). The billet record is only written when
   "Sauvegarder" is clicked inside the Ticketing modal. Until then, Cost
   Calculator TRECHO dropdowns showed no options even though the itinerary
   was fully defined in Itinéraire.

   NEW SOURCE PRIORITY
   ───────────────────
   1. Live DOM / globals — dep1/arr1/selLeg1, dep2/arr2/selLeg2, multiLegs[].
      This reflects exactly what is currently entered in Itinéraire, whether
      or not a flight search has been run.
   2. #bl-body.dataset.legsJson  — billet panel rendered (may have richer fn)
   3. expatur_billet_[ref].legs  — saved billet record
   4. [] (no options)

   AUTO-REFRESH TRIGGERS
   ─────────────────────
   TRECHO dropdowns are repopulated (with debounce 80ms) whenever:
   • Any flight is selected in search results  ← _itinWidgetRefreshIfOpen wrap
   • Trip type changes (aller simple / aller-retour / multi)  ← setTripType wrap
   • confirmItinerary() is called             ← confirmItinerary wrap
   • A multi-city leg dep/arr is typed        ← updateMultiLeg wrap
   • dep1/arr1/date-leg1/dep2/arr2/date-leg2 inputs change  ← addEventListener
   • A new CC row is added (addMilesRow)      ← second-level addMilesRow wrap

   GLOBAL EXPORTS
   ──────────────
   window._ccGetLiveLegs   = _getLiveItineraryLegs319
   window._ccRefreshTrechos = _refreshAllTrechos319
   ══════════════════════════════════════════════════════════════════════════ */
(function () {
  if (window._v319LiveItinLegs) return;
  window._v319LiveItinLegs = true;

  /* ═══════════════════════════════════════════════════════════════
     1. Live itinerary leg builder
        Reads tripType / selLeg1 / selLeg2 / multiLegs from the
        page globals (defined at lines 3677-3680), plus the IATA
        DOM inputs that are always live-updated by the user.
  ═══════════════════════════════════════════════════════════════ */
  function _getLiveItineraryLegs319() {
    var legs = [];

    /* Safe access to page-level globals */
    var tt    = (typeof tripType   !== 'undefined') ? tripType   : 'oneway';
    var sl1   = (typeof selLeg1    !== 'undefined') ? selLeg1    : null;
    var sl2   = (typeof selLeg2    !== 'undefined') ? selLeg2    : null;
    var mLegs = (typeof multiLegs  !== 'undefined') ? multiLegs  : [];

    function _val(id)       { return ((document.getElementById(id) || {}).value || '').trim(); }
    function _iata(id)      { return _val(id).toUpperCase(); }
    function _fn(selObj)    { return (selObj && selObj.fn && selObj.fn !== '\u2014') ? selObj.fn : ''; }
    function _airline(selObj) { return (selObj && selObj.airline) ? selObj.airline : ''; }

    var dep1  = _iata('dep1');
    var arr1  = _iata('arr1');
    var date1 = _val('date-leg1');

    if (tt === 'return') {
      /* Leg 2 dep/arr may be readonly mirrors of leg 1; fall back to swapped values */
      var dep2  = _iata('dep2')  || arr1;
      var arr2  = _iata('arr2')  || dep1;
      var date2 = _val('date-leg2');
      if (dep1 || arr1) {
        legs.push({ dep: dep1, arr: arr1, date: date1, fn: _fn(sl1), label: 'Vol Aller',   airline: _airline(sl1) });
      }
      if (dep2 || arr2) {
        legs.push({ dep: dep2, arr: arr2, date: date2, fn: _fn(sl2), label: 'Vol Retour',  airline: _airline(sl2) });
      }
    } else if (tt === 'oneway') {
      if (dep1 || arr1) {
        legs.push({ dep: dep1, arr: arr1, date: date1, fn: _fn(sl1), label: 'Aller Simple', airline: _airline(sl1) });
      }
    } else {
      /* multicity */
      if (dep1 || arr1) {
        var fn1mc = _fn(sl1) || 'Tron\u00e7on 1';
        legs.push({ dep: dep1, arr: arr1, date: date1, fn: _fn(sl1), label: fn1mc, airline: _airline(sl1) });
      }
      mLegs.forEach(function (l, i) {
        var mdep = (l.dep || '').toUpperCase().trim();
        var marr = (l.arr || '').toUpperCase().trim();
        if (!mdep && !marr) return;
        var mDate = _val('multi-date-' + l.id) || l.date || '';
        var fnMC  = _fn(l.sel) || ('Tron\u00e7on ' + (i + 2));
        legs.push({ dep: mdep, arr: marr, date: mDate, fn: _fn(l.sel), label: fnMC, airline: _airline(l.sel) });
      });
    }

    /* If at least one leg has an IATA code, use live data */
    if (legs.some(function (lg) { return lg.dep || lg.arr; })) return legs;

    /* Fallback 2: billet panel DOM (richer fn from flight search) */
    try {
      var blBody = document.getElementById('bl-body');
      if (blBody && blBody.dataset.legsJson) {
        var parsed = JSON.parse(blBody.dataset.legsJson);
        if (Array.isArray(parsed) && parsed.length > 0) return parsed;
      }
    } catch (e) {}

    /* Fallback 3: saved billet record */
    try {
      var bRef = (_val('booking-ref') || 'DEVIS');
      var bKey = 'expatur_billet_' + bRef.replace(/[^a-zA-Z0-9]/g, '_');
      var bRec = JSON.parse(localStorage.getItem(bKey) || 'null');
      if (bRec && Array.isArray(bRec.legs) && bRec.legs.length > 0) return bRec.legs;
    } catch (e) {}

    return [];
  }

  /* ═══════════════════════════════════════════════════════════════
     2. Label + tooltip helpers
  ═══════════════════════════════════════════════════════════════ */
  function _legLabel319(leg) {
    var dep = leg.dep || leg.depCode || '';
    var arr = leg.arr || leg.arrCode || '';
    var fn  = leg.fn  || leg.flightNumber || '';
    return dep + ' \u2192 ' + arr + (fn ? ' \u2014 ' + fn : '');
  }

  function _updateTooltip319(rid, legs, sel) {
    sel = sel || document.getElementById('mc-leg-' + rid);
    if (!sel) return;
    var idx = parseInt(sel.value, 10);
    if (isNaN(idx) || idx < 0) { sel.title = ''; return; }
    if (!legs) legs = _getLiveItineraryLegs319();
    var leg = legs[idx];
    if (!leg) { sel.title = ''; return; }
    var tip = _legLabel319(leg);
    try {
      var bRef = (((document.getElementById('booking-ref') || {}).value || '').trim()) || 'DEVIS';
      var rec  = JSON.parse(localStorage.getItem('expatur_billet_' + bRef.replace(/[^a-zA-Z0-9]/g, '_')) || 'null');
      if (rec) {
        var pnr = rec.isMC ? (leg.pnr || rec.masterPnr || '') : (rec.masterPnr || '');
        if (pnr) tip += '\nPNR: ' + pnr;
        if (Array.isArray(rec.pax) && rec.pax[0] && Array.isArray(rec.pax[0].etkts)) {
          var tkt = rec.pax[0].etkts[idx];
          if (tkt) tip += '\nTicket: ' + tkt;
        }
      }
    } catch (e) {}
    sel.title = tip;
  }

  /* ═══════════════════════════════════════════════════════════════
     3. Populate a single TRECHO SELECT with live itinerary legs
        Preserves existing selected value if it is still valid.
  ═══════════════════════════════════════════════════════════════ */
  function _populateLegSel319(rid, forcedIdx) {
    var sel = document.getElementById('mc-leg-' + rid);
    if (!sel) return;
    var legs = _getLiveItineraryLegs319();
    var prev = (forcedIdx !== undefined && !isNaN(parseInt(forcedIdx, 10)))
               ? parseInt(forcedIdx, 10)
               : parseInt(sel.value, 10);

    sel.innerHTML = '<option value="-1">\u2014 Selecionar trecho \u2014</option>';
    legs.forEach(function (leg, i) {
      var opt = document.createElement('option');
      opt.value = i;
      opt.textContent = _legLabel319(leg);
      sel.appendChild(opt);
    });
    /* Restore or default */
    sel.value = (!isNaN(prev) && prev >= 0 && prev < legs.length) ? String(prev) : '-1';
    _updateTooltip319(rid, legs, sel);
  }

  /* ═══════════════════════════════════════════════════════════════
     4. Refresh ALL TRECHO selects (debounced 80 ms)
  ═══════════════════════════════════════════════════════════════ */
  var _refreshTimer319 = null;
  function _refreshAllTrechos319() {
    clearTimeout(_refreshTimer319);
    _refreshTimer319 = setTimeout(function () {
      var container = document.getElementById('miles-rows');
      if (!container) return;
      container.querySelectorAll('.miles-row-wrap').forEach(function (rowEl) {
        var rid = (rowEl.id || '').replace('miles-row-', '').trim();
        if (rid && document.getElementById('mc-leg-' + rid)) {
          _populateLegSel319(rid);
        }
      });
    }, 80);
  }

  /* ═══════════════════════════════════════════════════════════════
     5. Hook into all itinerary change events
  ═══════════════════════════════════════════════════════════════ */

  /* 5a. _itinWidgetRefreshIfOpen — called after EVERY leg selection AND
         right after trip-type changes (line 4301). This is the most
         comprehensive hook: covers selLeg1=fc, selLeg2=fc, lg.sel=fc. */
  if (typeof window._itinWidgetRefreshIfOpen === 'function' && !window._v319ItinRefreshWrap) {
    window._v319ItinRefreshWrap = true;
    var _origItinRefresh319 = window._itinWidgetRefreshIfOpen;
    window._itinWidgetRefreshIfOpen = function () {
      _origItinRefresh319.apply(this, arguments);
      _refreshAllTrechos319();
    };
  }

  /* 5b. setTripType — user switches between oneway / return / multicity */
  if (typeof window.setTripType === 'function' && !window._v319TripTypeWrap) {
    window._v319TripTypeWrap = true;
    var _origSetTripType319 = window.setTripType;
    window.setTripType = function () {
      _origSetTripType319.apply(this, arguments);
      _refreshAllTrechos319();
    };
  }

  /* 5c. confirmItinerary — "Confirmer l'itinéraire" button */
  if (typeof window.confirmItinerary === 'function' && !window._v319ConfirmItinWrap) {
    window._v319ConfirmItinWrap = true;
    var _origConfirmItin319 = window.confirmItinerary;
    window.confirmItinerary = function () {
      _origConfirmItin319.apply(this, arguments);
      _refreshAllTrechos319();
    };
  }

  /* 5d. updateMultiLeg — called when multi-city dep/arr is typed */
  if (typeof window.updateMultiLeg === 'function' && !window._v319MultiLegWrap) {
    window._v319MultiLegWrap = true;
    var _origUpdateMultiLeg319 = window.updateMultiLeg;
    window.updateMultiLeg = function () {
      _origUpdateMultiLeg319.apply(this, arguments);
      _refreshAllTrechos319();
    };
  }

  /* 5e. DOM input listeners on fixed itinerary fields (typed IATA / date) */
  ['dep1', 'arr1', 'date-leg1', 'dep2', 'arr2', 'date-leg2'].forEach(function (id) {
    var el = document.getElementById(id);
    if (el && !el._v319listener) {
      el._v319listener = true;
      el.addEventListener('input', _refreshAllTrechos319);
      el.addEventListener('change', _refreshAllTrechos319);
    }
  });

  /* 5f. addMilesRow second-level wrap: repopulate the newly-created row's
         SELECT with live data (v3.17 already injected the SELECT element;
         this populates it correctly instead of relying on billet fallback) */
  if (typeof window.addMilesRow === 'function' && !window._v319AddMilesRowWrap) {
    window._v319AddMilesRowWrap = true;
    var _origAddMilesRow319 = window.addMilesRow;
    window.addMilesRow = function () {
      _origAddMilesRow319.apply(this, arguments);
      /* Use a short delay so v3.17's row injection completes first */
      setTimeout(function () {
        var container = document.getElementById('miles-rows');
        if (!container) return;
        var rows = container.querySelectorAll('.miles-row-wrap');
        if (!rows.length) return;
        var lastRow = rows[rows.length - 1];
        var rid = (lastRow.id || '').replace('miles-row-', '').trim();
        if (rid && document.getElementById('mc-leg-' + rid)) {
          _populateLegSel319(rid);
        }
      }, 60);
    };
  }

  /* ═══════════════════════════════════════════════════════════════
     6. Also override the v3.17/v3.18 private _getMilesLegs* calls
        by exposing the live getter globally so future patches can
        call window._ccGetLiveLegs() for consistent behaviour.
  ═══════════════════════════════════════════════════════════════ */
  window._ccGetLiveLegs   = _getLiveItineraryLegs319;
  window._ccRefreshTrechos = _refreshAllTrechos319;

  /* ═══════════════════════════════════════════════════════════════
     7. Init — populate all existing rows on patch load
  ═══════════════════════════════════════════════════════════════ */
  function _init319() {
    _refreshAllTrechos319();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _init319);
  } else {
    setTimeout(_init319, 300);
  }

  console.log('[Patch v3.19] Live itinerary sync active: reads tripType/selLeg1/selLeg2/multiLegs; hooks: _itinWidgetRefreshIfOpen, setTripType, confirmItinerary, updateMultiLeg, DOM inputs, addMilesRow.');

})(); // end Patch v3.19

