// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.21 — Roundtrip TRECHO grouping
   Guard: window._v321RoundtripTrecho

   WHAT THIS PATCH DOES
   ────────────────────
   Replaces the leg-builder and SELECT-population logic introduced in v3.19
   with a trip-type-aware version that handles roundtrip as ONE grouped option.

   TRIP TYPE BEHAVIOUR
   ───────────────────
   oneway   → unchanged: one option   → e.g.  "CDG-GRU AF456"
   return   → GROUPED:   one option   → e.g.  "CDG-IAH-CDG AF98/AF99"
   multicity→ unchanged: N options, one per leg

   ROUNDTRIP GROUPED LEG OBJECT
   ─────────────────────────────
   {
     dep:                  outbound dep IATA (e.g. 'CDG')
     arr:                  outbound arr IATA (e.g. 'IAH')
     date:                 outbound departure date (ISO)
     fn:                   'AF98/AF99'  (outbound/return joint)
     label:                'CDG-IAH-CDG AF98/AF99'   (compact display)
     linked_leg_type:      'roundtrip_group'
     outbound_dep:         'CDG'
     outbound_arr:         'IAH'
     outbound_date:        '2026-08-26'
     outbound_fn:          'AF98'
     return_dep:           'IAH'
     return_arr:           'CDG'
     return_date:          '2026-09-02'
     return_fn:            'AF99'
   }

   HOVER TOOLTIP for roundtrip group
   ───────────────────────────────────
   CDG → IAH — 26/08 — AF98
   IAH → CDG — 02/09 — AF99
   PNR: ABC123
   Ticket: 2201234567890

   FINANCE SYNC IMPACT
   ───────────────────
   For a roundtrip_group leg:
   · linked_leg_dep / linked_leg_arr  = outbound dep / arr
   · linked_leg_fn                    = 'AF98/AF99' (joint)
   · linked_leg_label                 = 'CDG-IAH-CDG AF98/AF99'
   · linked_flight_date               = outbound date
   No breaking change to stored record keys — downstream renderers
   (_buildDetails318/320) read dep/arr/fn and will show the compact form.

   WHAT IS NOT CHANGED
   ───────────────────
   · All hook wrappers from v3.19 (setTripType, _itinWidgetRefreshIfOpen,
     confirmItinerary, updateMultiLeg, DOM listeners, addMilesRow) remain
     in place — they already call window._ccRefreshTrechos() which this
     patch updates.
   · One-way and multi-city leg building logic is unchanged.
   · v3.17 SELECT element injection is unchanged.
   · v3.18 Finance sync and onMilesIssuerChange protection are unchanged.
   · v3.20 Despesas column layout is unchanged.
   ══════════════════════════════════════════════════════════════════════════ */
(function () {
  if (window._v321RoundtripTrecho) return;
  window._v321RoundtripTrecho = true;

  /* ═══════════════════════════════════════════════════════════════
     1. Helpers
  ═══════════════════════════════════════════════════════════════ */

  function _val321(id)    { return ((document.getElementById(id) || {}).value || '').trim(); }
  function _iata321(id)   { return _val321(id).toUpperCase(); }
  function _fn321(selObj) { return (selObj && selObj.fn && selObj.fn !== '\u2014') ? selObj.fn : ''; }
  function _airline321(selObj) { return (selObj && selObj.airline) ? selObj.airline : ''; }

  /* Format ISO date as DD/MM for compact tooltip */
  function _shortDate321(iso) {
    if (!iso) return '';
    try {
      var p = String(iso).slice(0, 10).split('-');
      return p[2] + '/' + p[1];
    } catch (e) { return iso; }
  }

  /* ═══════════════════════════════════════════════════════════════
     2. Leg builder — replaces _getLiveItineraryLegs319
        Returns ONE option for roundtrip (grouped), N options for
        multicity, ONE option for oneway.
  ═══════════════════════════════════════════════════════════════ */
  function _getLiveItineraryLegs321() {
    var legs = [];

    /* Safe access to page-level globals */
    var tt    = (typeof tripType  !== 'undefined') ? tripType  : 'oneway';
    var sl1   = (typeof selLeg1   !== 'undefined') ? selLeg1   : null;
    var sl2   = (typeof selLeg2   !== 'undefined') ? selLeg2   : null;
    var mLegs = (typeof multiLegs !== 'undefined') ? multiLegs : [];

    var dep1  = _iata321('dep1');
    var arr1  = _iata321('arr1');
    var date1 = _val321('date-leg1');
    var fn1   = _fn321(sl1);

    if (tt === 'return') {
      /* ── ROUNDTRIP: one grouped option ── */
      var dep2  = _iata321('dep2')  || arr1;
      var arr2  = _iata321('arr2')  || dep1;
      var date2 = _val321('date-leg2');
      var fn2   = _fn321(sl2);

      if (dep1 || arr1 || dep2 || arr2) {
        /* Compact label: CDG-IAH-CDG AF98/AF99 */
        var routePart = (dep1 || '?') + '-' + (arr1 || '?') + '-' + (dep1 || '?');
        var fnPart    = fn1 && fn2 ? fn1 + '/' + fn2 : (fn1 || fn2 || '');
        var compactLabel = routePart + (fnPart ? ' ' + fnPart : '');

        legs.push({
          /* Standard fields (dep/arr/date/fn refer to the outbound leg) */
          dep:  dep1,
          arr:  arr1,
          date: date1,
          fn:   fnPart,      /* 'AF98/AF99' — joint display */
          label: compactLabel,
          airline: _airline321(sl1),
          /* Roundtrip group marker */
          linked_leg_type: 'roundtrip_group',
          /* Outbound detail */
          outbound_dep:  dep1,
          outbound_arr:  arr1,
          outbound_date: date1,
          outbound_fn:   fn1,
          /* Return detail */
          return_dep:  dep2,
          return_arr:  arr2,
          return_date: date2,
          return_fn:   fn2
        });
      }

    } else if (tt === 'oneway') {
      /* ── ONE-WAY: single option, unchanged logic ── */
      if (dep1 || arr1) {
        var owLabel = (dep1 || '?') + '-' + (arr1 || '?') + (fn1 ? ' ' + fn1 : '');
        legs.push({
          dep: dep1, arr: arr1, date: date1, fn: fn1,
          label: owLabel,
          airline: _airline321(sl1),
          linked_leg_type: 'oneway'
        });
      }

    } else {
      /* ── MULTICITY: one option per leg, unchanged logic ── */
      if (dep1 || arr1) {
        var fn1mc   = fn1 || 'Tron\u00e7on 1';
        var mc1Label = (dep1 || '?') + '-' + (arr1 || '?') + (fn1 ? ' ' + fn1 : '');
        legs.push({
          dep: dep1, arr: arr1, date: date1, fn: fn1,
          label: mc1Label,
          airline: _airline321(sl1),
          linked_leg_type: 'multicity'
        });
      }
      mLegs.forEach(function (l, i) {
        var mdep = (l.dep || '').toUpperCase().trim();
        var marr = (l.arr || '').toUpperCase().trim();
        if (!mdep && !marr) return;
        var mDate = _val321('multi-date-' + l.id) || l.date || '';
        var fnMC  = _fn321(l.sel) || ('Tron\u00e7on ' + (i + 2));
        var mcLabel = (mdep || '?') + '-' + (marr || '?') + (fnMC ? ' ' + fnMC : '');
        legs.push({
          dep: mdep, arr: marr, date: mDate, fn: _fn321(l.sel),
          label: mcLabel,
          airline: _airline321(l.sel),
          linked_leg_type: 'multicity'
        });
      });
    }

    /* If at least one leg has IATA data, use live data */
    if (legs.some(function (lg) { return lg.dep || lg.arr; })) return legs;

    /* Fallback 2: billet panel DOM */
    try {
      var blBody = document.getElementById('bl-body');
      if (blBody && blBody.dataset.legsJson) {
        var parsed = JSON.parse(blBody.dataset.legsJson);
        if (Array.isArray(parsed) && parsed.length > 0) {
          /* If the saved billet has exactly 2 legs and isMC=false, merge them */
          var bRec2 = null;
          try {
            var bRef2 = (_val321('booking-ref') || 'DEVIS');
            bRec2 = JSON.parse(localStorage.getItem(
              'expatur_billet_' + bRef2.replace(/[^a-zA-Z0-9]/g, '_')) || 'null');
          } catch (e) {}
          if (bRec2 && !bRec2.isMC && parsed.length === 2) {
            return [_buildRoundtripGroup321(parsed[0], parsed[1])];
          }
          return parsed;
        }
      }
    } catch (e) {}

    /* Fallback 3: saved billet record */
    try {
      var bRef3 = (_val321('booking-ref') || 'DEVIS');
      var bKey  = 'expatur_billet_' + bRef3.replace(/[^a-zA-Z0-9]/g, '_');
      var bRec  = JSON.parse(localStorage.getItem(bKey) || 'null');
      if (bRec && Array.isArray(bRec.legs) && bRec.legs.length > 0) {
        /* If saved billet was a non-MC 2-leg trip, group them */
        if (!bRec.isMC && bRec.legs.length === 2) {
          return [_buildRoundtripGroup321(bRec.legs[0], bRec.legs[1])];
        }
        return bRec.legs;
      }
    } catch (e) {}

    return [];
  }

  /* Helper: build a roundtrip_group leg from two saved leg objects */
  function _buildRoundtripGroup321(l1, l2) {
    var dep1 = l1.dep || l1.depCode || '';
    var arr1 = l1.arr || l1.arrCode || '';
    var fn1  = l1.fn  || l1.flightNumber || '';
    var fn2  = l2.fn  || l2.flightNumber || '';
    var routePart = dep1 + '-' + arr1 + '-' + dep1;
    var fnPart    = fn1 && fn2 ? fn1 + '/' + fn2 : (fn1 || fn2 || '');
    return {
      dep: dep1, arr: arr1, date: l1.date || l1.depDate || '',
      fn: fnPart, label: routePart + (fnPart ? ' ' + fnPart : ''),
      linked_leg_type: 'roundtrip_group',
      outbound_dep: dep1, outbound_arr: arr1,
      outbound_date: l1.date || l1.depDate || '', outbound_fn: fn1,
      return_dep: l2.dep || l2.depCode || '', return_arr: l2.arr || l2.arrCode || '',
      return_date: l2.date || l2.depDate || '', return_fn: fn2
    };
  }

  /* ═══════════════════════════════════════════════════════════════
     3. Label — compact cell text (already stored in leg.label)
  ═══════════════════════════════════════════════════════════════ */
  function _legLabel321(leg) {
    /* Use pre-built label if available (all new legs have it) */
    if (leg.label) return leg.label;
    /* Fallback for billet-fallback legs that only have dep/arr/fn */
    var dep = leg.dep || leg.depCode || '';
    var arr = leg.arr || leg.arrCode || '';
    var fn  = leg.fn  || leg.flightNumber || '';
    if (leg.linked_leg_type === 'roundtrip_group') {
      return dep + '-' + arr + '-' + dep + (fn ? ' ' + fn : '');
    }
    return dep + '-' + arr + (fn ? ' ' + fn : '');
  }

  /* ═══════════════════════════════════════════════════════════════
     4. Tooltip — multi-line hover detail
  ═══════════════════════════════════════════════════════════════ */
  function _buildTooltip321(leg, bRec) {
    var lines = [];

    if (leg.linked_leg_type === 'roundtrip_group') {
      /* Two-line tooltip: outbound + return */
      var ob = (leg.outbound_dep || leg.dep || '') + ' \u2192 ' + (leg.outbound_arr || leg.arr || '');
      if (leg.outbound_date) ob += ' \u2014 ' + _shortDate321(leg.outbound_date);
      if (leg.outbound_fn)   ob += ' \u2014 ' + leg.outbound_fn;
      lines.push(ob);

      var ret = (leg.return_dep || '') + ' \u2192 ' + (leg.return_arr || '');
      if (leg.return_date) ret += ' \u2014 ' + _shortDate321(leg.return_date);
      if (leg.return_fn)   ret += ' \u2014 ' + leg.return_fn;
      if (ret.trim() && ret !== ' \u2192 ') lines.push(ret);

    } else {
      /* One-way / multicity: single-line */
      var l = (leg.dep || '') + ' \u2192 ' + (leg.arr || '');
      if (leg.date) l += ' \u2014 ' + _shortDate321(leg.date);
      if (leg.fn)   l += ' \u2014 ' + leg.fn;
      lines.push(l);
    }

    /* PNR + ticket from saved billet record */
    if (bRec) {
      var pnr = bRec.isMC ? (leg.pnr || bRec.masterPnr || '') : (bRec.masterPnr || '');
      if (pnr) lines.push('PNR: ' + pnr);
      if (Array.isArray(bRec.pax) && bRec.pax[0] && Array.isArray(bRec.pax[0].etkts)) {
        /* For roundtrip group show both tickets if present */
        if (leg.linked_leg_type === 'roundtrip_group') {
          var t1 = bRec.pax[0].etkts[0];
          var t2 = bRec.pax[0].etkts[1];
          if (t1 || t2) lines.push('Ticket: ' + [t1, t2].filter(Boolean).join(' / '));
        } else {
          /* idx is ambiguous here — best effort: first ticket */
          var tkt = bRec.pax[0].etkts[0];
          if (tkt) lines.push('Ticket: ' + tkt);
        }
      }
    }

    return lines.join('\n');
  }

  function _updateTooltip321(rid, legs, sel) {
    sel  = sel  || document.getElementById('mc-leg-' + rid);
    if (!sel) return;
    var idx = parseInt(sel.value, 10);
    if (isNaN(idx) || idx < 0) { sel.title = ''; return; }
    if (!legs) legs = _getLiveItineraryLegs321();
    var leg = legs[idx];
    if (!leg) { sel.title = ''; return; }

    /* Try to read billet record for PNR / ticket */
    var bRec = null;
    try {
      var bRef = ((_val321('booking-ref') || '').trim()) || 'DEVIS';
      bRec = JSON.parse(localStorage.getItem(
        'expatur_billet_' + bRef.replace(/[^a-zA-Z0-9]/g, '_')) || 'null');
    } catch (e) {}

    sel.title = _buildTooltip321(leg, bRec);
  }

  /* ═══════════════════════════════════════════════════════════════
     5. Populate a single TRECHO SELECT (replaces _populateLegSel319)
  ═══════════════════════════════════════════════════════════════ */
  function _populateLegSel321(rid, forcedIdx) {
    var sel = document.getElementById('mc-leg-' + rid);
    if (!sel) return;
    var legs = _getLiveItineraryLegs321();
    var prev = (forcedIdx !== undefined && !isNaN(parseInt(forcedIdx, 10)))
               ? parseInt(forcedIdx, 10)
               : parseInt(sel.value, 10);

    sel.innerHTML = '<option value="-1">\u2014 Selecionar trecho \u2014</option>';
    legs.forEach(function (leg, i) {
      var opt = document.createElement('option');
      opt.value       = i;
      opt.textContent = _legLabel321(leg);
      sel.appendChild(opt);
    });
    /* Restore previous selection if still valid */
    sel.value = (!isNaN(prev) && prev >= 0 && prev < legs.length) ? String(prev) : '-1';
    _updateTooltip321(rid, legs, sel);
  }

  /* ═══════════════════════════════════════════════════════════════
     6. Refresh ALL TRECHO selects (debounced 80 ms)
        Replaces window._ccRefreshTrechos
  ═══════════════════════════════════════════════════════════════ */
  var _refreshTimer321 = null;
  function _refreshAllTrechos321() {
    clearTimeout(_refreshTimer321);
    _refreshTimer321 = setTimeout(function () {
      var container = document.getElementById('miles-rows');
      if (!container) return;
      container.querySelectorAll('.miles-row-wrap').forEach(function (rowEl) {
        var rid = (rowEl.id || '').replace('miles-row-', '').trim();
        if (rid && document.getElementById('mc-leg-' + rid)) {
          _populateLegSel321(rid);
        }
      });
    }, 80);
  }

  /* ═══════════════════════════════════════════════════════════════
     7. Replace global entry points used by all hook wrappers
        (v3.19 hooks already call window._ccRefreshTrechos and
         window._ccGetLiveLegs — updating these is sufficient)
  ═══════════════════════════════════════════════════════════════ */
  window._ccGetLiveLegs    = _getLiveItineraryLegs321;
  window._ccRefreshTrechos = _refreshAllTrechos321;

  /* ═══════════════════════════════════════════════════════════════
     8. Re-wire the addMilesRow wrap so NEW rows get populated via
        the v3.21 populate function (v3.19's wrap still calls the
        old v3.19 private _populateLegSel319 for the last row).
        We add a second-level wrap on top of v3.19's.
  ═══════════════════════════════════════════════════════════════ */
  if (typeof window.addMilesRow === 'function' && !window._v321AddMilesRowWrap) {
    window._v321AddMilesRowWrap = true;
    var _prev321AddMilesRow = window.addMilesRow;
    window.addMilesRow = function () {
      _prev321AddMilesRow.apply(this, arguments);
      setTimeout(function () {
        var container = document.getElementById('miles-rows');
        if (!container) return;
        var rows = container.querySelectorAll('.miles-row-wrap');
        if (!rows.length) return;
        var lastRow = rows[rows.length - 1];
        var rid = (lastRow.id || '').replace('miles-row-', '').trim();
        if (rid && document.getElementById('mc-leg-' + rid)) {
          _populateLegSel321(rid);
        }
      }, 100);
    };
  }

  /* ═══════════════════════════════════════════════════════════════
     9. Init
  ═══════════════════════════════════════════════════════════════ */
  function _init321() {
    _refreshAllTrechos321();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _init321);
  } else {
    setTimeout(_init321, 350);
  }

  console.log('[Patch v3.21] Roundtrip TRECHO grouping active. Return=one option (CDG-IAH-CDG AF98/AF99), oneway/multicity unchanged.');

})(); // end Patch v3.21

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.22 — Dossier-scoped Finance + Row Management (select/edit/delete)
   Guard: window._v322DossierScope

   ROOT CAUSE OF DATA LEAK
   ───────────────────────
   _dossRefs315() / _dossRefs320() / _dossRefs318() add the LIVE DOM
   booking-ref to the filter set. When the DOM value is empty string '',
   records with dossierRef==='' (e.g. Stripe fee lines written with
   dossierRef:'') pass the filter in EVERY dossier → cross-booking leak.
   The _v36RenderReceivables filter at line 20072 uses the same pattern.

   FIX
   ───
   _dossRefs322(id): strict version — only id + STORED booking-ref (no DOM).
   Filter expressions require   dr && refs[dr]   so empty-string records
   are unconditionally excluded.
   Replaces: _computeOverview315 → window._v36ComputeOverview
                                    window.dossFIN_computeOverview
   Replaces: _v36RenderReceivables → receivables tab renderer
   Replaces: _renderExpenses320    → expenses tab renderer (window._v36RenderExpenses)
   Replaces: _renderCredits        → credits tab renderer
   Replaces: _renderSuppliers      → suppliers tab renderer
   Replaces: _renderAudit          → audit tab renderer
   Extends:  dossFinDeleteLine     → also removes from global store

   ROW MANAGEMENT — what is added per tab
   ───────────────────────────────────────
   Recebimentos : checkbox per row, select-all, edit, delete, bulk-delete bar
   Despesas     : checkbox per row, select-all, edit (manual), delete, bulk-delete bar
   Créditos     : checkbox per row, select-all, EDIT (new), delete, bulk-delete bar
   Fornecedores : delete-item button on each supplier's expense row
   Auditoria    : "Limpar auditoria" button (clears all audit entries)

   GLOBAL HELPERS EXPOSED
   ──────────────────────
   window.dossFinSelectAll322(lineType, cb)
   window.dossFinRowCheckChange322(lineType)
   window.dossFinClearSelection322(lineType)
   window.dossFinBulkDelete322(lineType)
   window.dossFinDeleteSyncedRecord322(sid)
   ══════════════════════════════════════════════════════════════════════════ */
(function () {
  if (window._v322DossierScope) return;
  window._v322DossierScope = true;

  /* ═══════════════════════════════════════════════════════════════
     SECTION 1 — Shared helpers (all suffixed _322)
  ═══════════════════════════════════════════════════════════════ */

  var _FINK322 = 'expatur_financeiro_lancamentos';

  function _finLoad322()  { try { return JSON.parse(localStorage.getItem(_FINK322)||'[]'); } catch(e) { return []; } }
  function _finSave322(a) { try { localStorage.setItem(_FINK322, JSON.stringify(a)); } catch(e) {} }

  function _activeId322()  { return localStorage.getItem('expatur_active_dossier') || null; }
  function _dossLoad322(id) { try { return JSON.parse(localStorage.getItem('expatur_doss_finance_'+id)||'null'); } catch(e) { return null; } }
  function _dossSave322(id,d) { try { localStorage.setItem('expatur_doss_finance_'+id, JSON.stringify(d)); } catch(e) {} }

  function _esc322(s) {
    return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function _fmt322(v, cur) {
    var c = cur||'BRL', n = parseFloat(v)||0;
    var sym = c==='BRL'?'R$\u00a0':c==='USD'?'$\u00a0':'\u20ac\u00a0';
    return sym + n.toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2});
  }
  function _date322(d) {
    if (!d) return '\u2014';
    var p = String(d).slice(0,10).split('-'); return p[2]+'/'+p[1]+'/'+p[0];
  }
  function _brl322(r) {
    if (r.brl_amount!=null && r.brl_amount!=='') return parseFloat(r.brl_amount)||0;
    var amt  = parseFloat(r.amount||r.valor||0)||0;
    var rate = parseFloat(r.fx_rate_to_brl)||1;
    return amt * rate;
  }
  function _uid322() { return 'fl_'+Date.now()+'_'+Math.random().toString(36).slice(2,7); }
  function _today322() { return new Date().toISOString().slice(0,10); }

  /* ── STRICT dossier-ref filter set ──────────────────────────────
     KEY FIX: never adds empty string, never reads live DOM value.
     Only id + the STORED booking-ref are trusted.
  ─────────────────────────────────────────────────────────────── */
  function _dossRefs322(id) {
    var refs = Object.create(null);
    if (!id) return refs;
    refs[id] = true;
    try {
      var dd = JSON.parse(localStorage.getItem('expatur_dossier_'+id)||'null');
      var br = dd && dd.fields && dd.fields['booking-ref'];
      if (br && br.trim()) refs[br.trim()] = true;
    } catch(e) {}
    /* DELIBERATELY NO DOM booking-ref — avoids empty-string contamination */
    return refs;
  }

  /* ─ Global lancamentos: records for this dossier only ──────── */
  function _globalForDossier322(id, tipo) {
    var refs = _dossRefs322(id);
    return _finLoad322().filter(function(r) {
      var dr = r.dossierRef||'';
      return dr && refs[dr] && (!tipo || r.tipo === tipo);
    });
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 2 — Inject minimal bulk-bar CSS (once)
  ═══════════════════════════════════════════════════════════════ */
  if (!document.getElementById('v322-styles')) {
    var sty = document.createElement('style');
    sty.id = 'v322-styles';
    sty.textContent = [
      '.v322-bulk-bar{display:none;align-items:center;gap:8px;flex-wrap:wrap;',
        'background:linear-gradient(90deg,rgba(6,32,59,0.09),rgba(212,175,55,0.1));',
        'border:1px solid rgba(6,32,59,0.13);border-radius:6px;',
        'padding:7px 12px;margin-bottom:8px;font-size:0.72rem;}',
      '.v322-bulk-bar.visible{display:flex;}',
      '.v322-bulk-bar .v322-count{font-weight:700;color:var(--navy);}',
      '.v322-bulk-bar .v322-btn{padding:3px 10px;border-radius:4px;border:none;',
        'cursor:pointer;font-size:0.7rem;font-weight:700;font-family:inherit;}',
      '.v322-bulk-bar .v322-btn-del{background:var(--red);color:#fff;}',
      '.v322-bulk-bar .v322-btn-clr{background:rgba(6,32,59,0.1);color:var(--navy);}',
      '.v322-chk{width:14px;height:14px;cursor:pointer;accent-color:var(--navy);}',
      '.doss-fin-table th.v322-chk-th{width:28px;padding:4px 8px;}',
      '.doss-fin-table td.v322-chk-td{padding:4px 8px;}',
    ].join('');
    document.head.appendChild(sty);
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 3 — Selection state and bulk-action helpers
  ═══════════════════════════════════════════════════════════════ */

  /* Per-tab selection: { recv:{id:true,...}, exp:{id:true,...}, cred:{id:true,...} } */
  var _sel322 = { recv:{}, exp:{}, cred:{} };

  /* Get or create the bulk bar div above a table body */
  function _getBulkBar322(lineType) {
    var bid = 'v322-bulk-bar-' + lineType;
    var el  = document.getElementById(bid);
    if (el) return el;
    /* Insert before the overflow-x:auto wrapper or before the table */
    var tbody = document.getElementById('doss-fin-' + (lineType==='cred'?'cred':(lineType==='recv'?'recv':'exp')) + '-body');
    if (!tbody) return null;
    var table = tbody;
    while (table && table.tagName !== 'TABLE') table = table.parentNode;
    if (!table) return null;
    var wrapper = table.parentNode;
    el = document.createElement('div');
    el.id = bid;
    el.className = 'v322-bulk-bar';
    wrapper.parentNode.insertBefore(el, wrapper);
    return el;
  }

  function _updateBulkBar322(lineType) {
    var sel = _sel322[lineType] || {};
    var ids = Object.keys(sel).filter(function(k){ return sel[k]; });
    var bar = _getBulkBar322(lineType);
    if (!bar) return;
    if (!ids.length) {
      bar.classList.remove('visible');
      bar.innerHTML = '';
      return;
    }
    bar.classList.add('visible');
    bar.innerHTML =
      '<span class="v322-count">' + ids.length + ' selecionado(s)</span>' +
      '<button class="v322-btn v322-btn-del" onclick="dossFinBulkDelete322(\'' + lineType + '\')">Apagar selecionados</button>' +
      '<button class="v322-btn v322-btn-clr" onclick="dossFinClearSelection322(\'' + lineType + '\')">Limpar seleção</button>';
  }

  window.dossFinSelectAll322 = function(lineType, cb) {
    var sel = _sel322[lineType] = {};
    var tbody = document.getElementById('doss-fin-' + (lineType==='cred'?'cred':(lineType==='recv'?'recv':'exp')) + '-body');
    if (!tbody) return;
    tbody.querySelectorAll('.v322-row-chk').forEach(function(c) {
      c.checked = cb.checked;
      if (cb.checked && c.dataset.lid) sel[c.dataset.lid] = true;
    });
    _updateBulkBar322(lineType);
  };

  window.dossFinRowCheckChange322 = function(lineType, lid, cb) {
    if (!_sel322[lineType]) _sel322[lineType] = {};
    if (cb.checked) _sel322[lineType][lid] = true;
    else            delete _sel322[lineType][lid];
    _updateBulkBar322(lineType);
    /* Sync select-all checkbox */
    var allChk = document.getElementById('v322-all-' + lineType);
    if (!allChk) return;
    var tbody = document.getElementById('doss-fin-' + (lineType==='cred'?'cred':(lineType==='recv'?'recv':'exp')) + '-body');
    if (!tbody) return;
    var all   = tbody.querySelectorAll('.v322-row-chk');
    var checked = tbody.querySelectorAll('.v322-row-chk:checked');
    allChk.indeterminate = checked.length > 0 && checked.length < all.length;
    allChk.checked = checked.length > 0 && checked.length === all.length;
  };

  window.dossFinClearSelection322 = function(lineType) {
    _sel322[lineType] = {};
    var tbody = document.getElementById('doss-fin-' + (lineType==='cred'?'cred':(lineType==='recv'?'recv':'exp')) + '-body');
    if (tbody) tbody.querySelectorAll('.v322-row-chk').forEach(function(c){ c.checked=false; });
    var allChk = document.getElementById('v322-all-' + lineType);
    if (allChk) { allChk.checked=false; allChk.indeterminate=false; }
    _updateBulkBar322(lineType);
  };

  /* ─ Delete a record from the global lancamentos store ────────── */
  window.dossFinDeleteSyncedRecord322 = function(sid) {
    if (!sid) return;
    var all = _finLoad322();
    var next = all.filter(function(r){ return (r.source_id||r.id||'') !== sid; });
    if (next.length < all.length) _finSave322(next);
  };

  /* ─ Enhanced dossFinDeleteLine: also purges global store ──────── */
  window.dossFinDeleteLine = function(lineType, lineId) {
    if (!confirm('Apagar esta linha?')) return;
    var id = _activeId322();
    if (!id) return;
    /* Remove from per-dossier store */
    var data = _dossLoad322(id);
    if (data) {
      if (lineType==='recv')   data.receivables = (data.receivables||[]).filter(function(x){ return x.id!==lineId && x.source_id!==lineId; });
      if (lineType==='exp')    data.expenses    = (data.expenses||[]).filter(function(x)   { return x.id!==lineId && x.source_id!==lineId; });
      if (lineType==='credit') data.credits     = (data.credits||[]).filter(function(x)    { return x.id!==lineId && x.source_id!==lineId; });
      if (typeof dossFIN_addAudit === 'function') dossFIN_addAudit(id,'Linha financeira apagada','gray',lineId);
      _dossSave322(id, data);
    }
    /* Also remove from global lancamentos store (covers synced records) */
    window.dossFinDeleteSyncedRecord322(lineId);
    /* Refresh */
    if (typeof window.dossFinRenderPanel==='function') window.dossFinRenderPanel();
    if (typeof toast==='function') toast('Linha apagada','info');
  };

  /* ─ Bulk delete ──────────────────────────────────────────────── */
  window.dossFinBulkDelete322 = function(lineType) {
    var sel = _sel322[lineType] || {};
    var ids = Object.keys(sel).filter(function(k){ return sel[k]; });
    if (!ids.length) return;
    if (!confirm('Apagar ' + ids.length + ' linha(s) selecionada(s)?')) return;
    var id   = _activeId322();
    var data = id ? _dossLoad322(id) : null;
    ids.forEach(function(lid) {
      if (data) {
        if (lineType==='recv')   data.receivables = (data.receivables||[]).filter(function(x){ return x.id!==lid && x.source_id!==lid; });
        if (lineType==='exp')    data.expenses    = (data.expenses||[]).filter(function(x)   { return x.id!==lid && x.source_id!==lid; });
        if (lineType==='credit') data.credits     = (data.credits||[]).filter(function(x)    { return x.id!==lid && x.source_id!==lid; });
      }
      window.dossFinDeleteSyncedRecord322(lid);
    });
    if (id && data) {
      if (typeof dossFIN_addAudit==='function') dossFIN_addAudit(id,'Bulk delete: '+ids.length+' linha(s)','gray','');
      _dossSave322(id, data);
    }
    _sel322[lineType] = {};
    if (typeof window.dossFinRenderPanel==='function') window.dossFinRenderPanel();
    if (typeof toast==='function') toast(ids.length+' linha(s) apagada(s)','info');
  };

  /* ═══════════════════════════════════════════════════════════════
     SECTION 4 — Checkbox thead helper
  ═══════════════════════════════════════════════════════════════ */
  function _chkTh322(lineType) {
    return '<th class="v322-chk-th"><input type="checkbox" class="v322-chk" ' +
           'id="v322-all-' + lineType + '" ' +
           'onchange="dossFinSelectAll322(\'' + lineType + '\',this)" title="Selecionar todos"></th>';
  }
  function _chkTd322(lineType, lid) {
    return '<td class="v322-chk-td"><input type="checkbox" class="v322-chk v322-row-chk" ' +
           'data-lid="' + _esc322(lid) + '" ' +
           'onchange="dossFinRowCheckChange322(\'' + lineType + '\',\'' + _esc322(lid) + '\',this)"></td>';
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 5 — computeOverview322
     Replaces _computeOverview315 / window._v36ComputeOverview.
     KEY FIX: _dossRefs322 — strict filter, no empty-string leak.
  ═══════════════════════════════════════════════════════════════ */
  function _computeOverview322(id) {
    var dd = null;
    try { dd = JSON.parse(localStorage.getItem('expatur_dossier_'+id)||'null'); } catch(e) {}
    var data = _dossLoad322(id);

    /* Strictly scoped global records */
    var globalRecs = _globalForDossier322(id, null); /* all tipos */

    var sumRecvBRL=0, totalRecv=0, totalCost=0, totalPaid=0, credAvail=0;
    var gSids = Object.create(null);

    globalRecs.forEach(function(r) {
      var brl = _brl322(r);
      if (r.tipo==='entrada') {
        sumRecvBRL += brl;
        if (r.pago==='pago') totalRecv += brl;
      } else if (r.tipo==='saida') {
        totalCost += brl;
        if (r.pago==='pago') totalPaid += brl;
      }
      if (r.source_id) gSids[r.source_id]=true;
      if (r.id)        gSids[r.id]=true;
    });

    if (data) {
      (data.receivables||[]).forEach(function(r) {
        if ((r.id&&gSids[r.id])||(r.source_id&&gSids[r.source_id])) return;
        var brl=_brl322(r), amt=parseFloat(r.amount)||0, paid=parseFloat(r.paidAmount)||0;
        sumRecvBRL += brl;
        var isPaid = (r.status==='paid'||r.status==='pago'||r.pago==='pago');
        if (isPaid) totalRecv += brl;
        else if (paid>0&&amt>0) totalRecv += brl*(paid/amt);
      });
      (data.expenses||[]).forEach(function(e) {
        if ((e.id&&gSids[e.id])||(e.source_id&&gSids[e.source_id])) return;
        var brl=_brl322(e), amt=parseFloat(e.amount)||0, paid=parseFloat(e.paidAmount)||0;
        totalCost += brl;
        var isPaid = (e.status==='paid'||e.status==='pago'||e.pago==='pago');
        if (isPaid) totalPaid += brl;
        else if (paid>0&&amt>0) totalPaid += brl*(paid/amt);
      });
      (data.credits||[]).forEach(function(c) {
        credAvail += Math.max(0,(parseFloat(c.originalAmount)||0)-(parseFloat(c.usedAmount)||0));
      });
    }

    /* TOTAL VENDAS: PNL snapshot → finForecast.sale (BRL) → sumRecvBRL */
    var totalSale = sumRecvBRL;
    try {
      var refs322 = _dossRefs322(id);
      var keys322 = Object.keys(refs322);
      for (var ki=0; ki<keys322.length; ki++) {
        var snap = JSON.parse(localStorage.getItem('expatur_pnl_'+keys322[ki])||'null');
        if (snap && parseFloat(snap.grossSell)>0) { totalSale=parseFloat(snap.grossSell); break; }
      }
    } catch(e) {}
    if (totalSale===sumRecvBRL && dd && dd.finForecast) {
      var fs = parseFloat(dd.finForecast.sale)||0;
      if (fs>0 && (dd.finForecast.saleCurrency==='BRL'||!dd.finForecast.saleCurrency)) totalSale=fs;
    }

    var forecastCost = totalCost;
    if (dd && dd.finForecast && parseFloat(dd.finForecast.cost)>0) forecastCost=parseFloat(dd.finForecast.cost);

    return {
      totalSale:      parseFloat(totalSale.toFixed(2)),
      totalCost:      parseFloat(totalCost.toFixed(2)),
      forecastMargin: parseFloat((totalSale-forecastCost).toFixed(2)),
      realizedMargin: parseFloat((totalRecv-totalPaid).toFixed(2)),
      totalRecv:      parseFloat(totalRecv.toFixed(2)),
      totalPaid:      parseFloat(totalPaid.toFixed(2)),
      balClientDue:   parseFloat(Math.max(0,totalSale-totalRecv).toFixed(2)),
      balSupplierDue: parseFloat(Math.max(0,totalCost-totalPaid).toFixed(2)),
      credAvail:      parseFloat(credAvail.toFixed(2))
    };
  }

  window._v36ComputeOverview    = _computeOverview322;
  window.dossFIN_computeOverview = _computeOverview322;

  /* ═══════════════════════════════════════════════════════════════
     SECTION 6 — Overview renderer (BRL, uses new computeOverview)
  ═══════════════════════════════════════════════════════════════ */
  function _renderOverview322(id, data) {
    var ov = _computeOverview322(id);
    if (!ov) return;
    var grid = document.getElementById('doss-fin-overview-kpis');
    if (grid) {
      grid.innerHTML = [
        {label:'Total vendas',          val:_fmt322(ov.totalSale,'BRL'),      color:'',      sub:'Recebível total (BRL)'},
        {label:'Total custo',           val:_fmt322(ov.totalCost,'BRL'),      color:'',      sub:'Despesas totais (BRL)'},
        {label:'Margem prevista',       val:_fmt322(ov.forecastMargin,'BRL'), color:ov.forecastMargin>=0?'green':'',  sub:'Venda − Custo'},
        {label:'Margem realizada',      val:_fmt322(ov.realizedMargin,'BRL'), color:ov.realizedMargin>=0?'green':'', sub:'Recebido − Pago'},
        {label:'Total recebido',        val:_fmt322(ov.totalRecv,'BRL'),      color:'blue',  sub:'Do cliente (BRL)'},
        {label:'Total pago',            val:_fmt322(ov.totalPaid,'BRL'),      color:'amber', sub:'A fornecedores (BRL)'},
        {label:'Saldo devedor client',  val:_fmt322(ov.balClientDue,'BRL'),   color:'',      sub:'Por receber'},
        {label:'Saldo devedor forn.',   val:_fmt322(ov.balSupplierDue,'BRL'), color:'amber', sub:'Por pagar'},
        {label:'Créditos disponíveis',  val:_fmt322(ov.credAvail,'BRL'),      color:'blue',  sub:'Saldo de créditos'}
      ].map(function(k) {
        return '<div class="doss-fin-kpi '+k.color+'">' +
          '<div class="doss-fin-kpi-label">'+_esc322(k.label)+'</div>' +
          '<div class="doss-fin-kpi-value">'+k.val+'</div>' +
          '<div class="doss-fin-kpi-sub">'+_esc322(k.sub)+'</div>' +
        '</div>';
      }).join('');
    }
    var mb = document.getElementById('doss-fin-margin-box');
    if (mb) {
      var margin = ov.forecastMargin;
      var pct    = ov.totalSale>0 ? (margin/ov.totalSale*100).toFixed(1) : '0.0';
      var col    = margin>=0 ? '#16a34a' : 'var(--red)';
      mb.innerHTML =
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:0.5rem;">' +
        '<span style="font-size:0.72rem;color:var(--navy-soft);">Margem bruta</span>' +
        '<span style="font-size:1.15rem;font-weight:700;color:'+col+';">'+_fmt322(margin,'BRL')+'</span></div>' +
        '<div style="display:flex;justify-content:space-between;align-items:center;">' +
        '<span style="font-size:0.72rem;color:var(--navy-soft);">% margem sobre venda</span>' +
        '<span style="font-size:0.88rem;font-weight:700;color:'+col+';">'+pct+'%</span></div>' +
        '<div style="margin-top:0.75rem;background:var(--light);border-radius:4px;height:6px;overflow:hidden;">' +
        '<div style="height:100%;width:'+Math.min(100,Math.abs(parseFloat(pct)))+'%;background:'+col+';border-radius:4px;transition:width 0.4s;"></div></div>';
    }
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 7 — Recebimentos renderer (strict scope + checkboxes)
  ═══════════════════════════════════════════════════════════════ */
  function _renderRecv322(id, data) {
    var tbody   = document.getElementById('doss-fin-recv-body');
    var empty   = document.getElementById('doss-fin-recv-empty');
    var totalEl = document.getElementById('doss-fin-recv-total');
    if (!tbody) return;

    /* Strict scope */
    var globalRecs = _globalForDossier322(id, 'entrada');
    var gSids = Object.create(null);
    globalRecs.forEach(function(r){ if(r.source_id) gSids[r.source_id]=true; if(r.id) gSids[r.id]=true; });
    var localOnly = ((data&&data.receivables)||[]).filter(function(r){
      return !(r.id&&gSids[r.id]) && !(r.source_id&&gSids[r.source_id]);
    });
    var allRows = globalRecs.concat(localOnly);

    /* Update thead with checkbox column */
    var table = tbody; while(table && table.tagName!=='TABLE') table=table.parentNode;
    if (table && table.tHead) {
      table.tHead.innerHTML = '<tr>' + _chkTh322('recv') +
        '<th>Descri\u00e7\u00e3o</th><th>Vencimento</th><th>Status</th><th>M\u00e9todo</th>' +
        '<th class="td-amt">Valor\u00a0(BRL)</th><th class="td-amt">Pago</th>' +
        '<th class="td-amt">Restante</th><th>Notas</th><th></th></tr>';
    }

    tbody.innerHTML = '';
    _sel322.recv = {};

    if (!allRows.length) {
      if (empty) empty.style.display=''; if (totalEl) totalEl.innerHTML='';
      _updateBulkBar322('recv'); return;
    }
    if (empty) empty.style.display='none';

    var BADGE  = {paid:'fbadge-paid',partial:'fbadge-partial',pending:'fbadge-pending',overdue:'fbadge-overdue',draft:'fbadge-draft'};
    var LABELS = {paid:'Pago',partial:'Parcial',pending:'Pendente',overdue:'Vencido',draft:'Rascunho'};
    var totalBRL=0, paidBRL=0;

    allRows.forEach(function(r) {
      var isSync = (r.tipo==='entrada');
      var brl    = _brl322(r);
      var lid, desc, dateVal, sk, payMethod, notes, isPago;
      if (isSync) {
        isPago   = (r.pago==='pago');
        lid      = r.source_id||r.id||_uid322();
        desc     = r.descricao||r.nota||'\u2014';
        dateVal  = r.vencimento||r.expected_release_date||'';
        sk       = r.pago==='pago'?'paid':(r.pago==='atrasado'?'overdue':'pending');
        payMethod= r.source_type?r.source_type.replace(/_/g,' '):'\u2014';
        notes    = r.nota||r.installment_label||'';
      } else {
        var amt=parseFloat(r.amount)||0, paid=parseFloat(r.paidAmount)||0;
        isPago   = (r.status==='paid'||r.status==='pago');
        lid      = r.id||_uid322();
        desc     = r.description||'\u2014';
        dateVal  = r.dueDate||'';
        sk       = r.status||'pending';
        payMethod= r.payMethod||'\u2014';
        notes    = r.notes||'';
      }
      totalBRL += brl;
      if (isPago) paidBRL += brl;
      else if (!isSync) { var a=parseFloat(r.amount)||0,p=parseFloat(r.paidAmount)||0; if(p>0&&a>0) paidBRL+=brl*(p/a); }

      var badgeCls = BADGE[sk]||'fbadge-pending';
      var lbl      = LABELS[sk]||sk;
      var paidAmt  = isPago ? brl : (isSync?0:(_brl322(r)*((parseFloat(r.paidAmount)||0)/Math.max(1,(parseFloat(r.amount)||1)))));
      var remAmt   = brl - paidAmt;

      var actionCell = isSync
        ? '<span style="font-size:0.6rem;color:var(--navy-faint);">sync</span>'
        : '<button class="db-action-btn" onclick="dossFinEditLine(\'recv\',\''+_esc322(lid)+'\')" title="Editar">&#9999;</button>' +
          '<button class="db-action-btn del" onclick="dossFinDeleteLine(\'recv\',\''+_esc322(lid)+'\')" title="Apagar">&times;</button>';

      var tr = document.createElement('tr');
      tr.innerHTML =
        _chkTd322('recv', lid) +
        '<td>'+_esc322(desc)+'<br><small style="color:var(--navy-faint);font-size:0.6rem;">'+_esc322(r.payType||r.source_type||'')+'</small></td>' +
        '<td>'+_date322(dateVal)+'</td>' +
        '<td class="td-status"><span class="fbadge '+badgeCls+'">'+lbl+'</span></td>' +
        '<td>'+_esc322(payMethod)+'</td>' +
        '<td class="td-amt">'+_fmt322(brl,'BRL')+'</td>' +
        '<td class="td-amt" style="color:#16a34a;">'+_fmt322(paidAmt,'BRL')+'</td>' +
        '<td class="td-amt" style="color:'+(remAmt>0?'var(--red)':'#16a34a')+';">'+_fmt322(remAmt,'BRL')+'</td>' +
        '<td style="font-size:0.72rem;color:var(--navy-faint);">'+_esc322(notes)+'</td>' +
        '<td style="white-space:nowrap;">'+actionCell+'</td>';
      tbody.appendChild(tr);
    });

    if (totalEl) {
      var rem=totalBRL-paidBRL;
      totalEl.innerHTML = '<span style="color:var(--navy-soft);font-size:0.72rem;">Total:</span> <strong>'+_fmt322(totalBRL,'BRL')+'</strong>' +
        '&nbsp;&nbsp;<span style="color:var(--navy-soft);font-size:0.72rem;">Pago:</span> <strong style="color:#16a34a;">'+_fmt322(paidBRL,'BRL')+'</strong>' +
        '&nbsp;&nbsp;<span style="color:var(--navy-soft);font-size:0.72rem;">Restante:</span> <strong style="color:'+(rem>0?'var(--red)':'#16a34a')+';">'+_fmt322(rem,'BRL')+'</strong>';
    }
    _updateBulkBar322('recv');
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 8 — Despesas renderer (strict scope + checkboxes)
     Replaces _renderExpenses320 / window._v36RenderExpenses.
     Preserves v3.20 column order and pnl footer.
  ═══════════════════════════════════════════════════════════════ */

  /* Re-use v3.20's DETAILS helper via global if available, else fallback */
  function _buildDetails322(n) {
    var parts=[];
    var trecho='';
    if (n.linked_leg_dep&&n.linked_leg_arr) {
      trecho=n.linked_leg_dep+' \u2192 '+n.linked_leg_arr;
      if (n.linked_leg_fn) trecho+=' \u2014 '+n.linked_leg_fn;
    } else if (n.linked_leg_label) { trecho=n.linked_leg_label; }
    if (trecho) parts.push(trecho);
    if (n.linked_flight_date) {
      try {
        var dp=n.linked_flight_date.slice(0,10).split('-');
        parts.push(dp[2]+'/'+dp[1]+'/'+dp[0]);
      } catch(e){}
    }
    if (n.linked_airline_iata) parts.push(n.linked_airline_iata);
    if (n.linked_pnr) parts.push('PNR\u00a0'+n.linked_pnr);
    if (parts.length) return parts.join(' \u2014 ');
    if (n.programme) return n.programme;
    return '';
  }

  function _normalizeExp322(r) {
    var brl = _brl322(r);
    var isNew = r.tipo==='saida'||r.fornecedor!==undefined||r.categoria!==undefined||r.source_type!==undefined;
    if (isNew) {
      var pago=r.pago||'pendente';
      var sk=pago==='pago'?'paid':(pago==='atrasado'?'overdue':'pending');
      return {
        _id:r.source_id||r.id||'', supplier:r.fornecedor||r.supplier||'\u2014',
        category:r.categoria||r.category||'\u2014', dateVal:r.vencimento||r.dueDate||'',
        statusKey:sk, pnrRef:r.source_id||r.pnrRef||'', brl:brl,
        paidBRL:pago==='pago'?brl:0, remBRL:pago==='pago'?0:brl,
        notes:r.nota||r.notes||'', isSync:true,
        isCC:r.source_type==='cost_calculator_line',
        programme:r.programme!=null?String(r.programme):'',
        volume_miles:r.volume_miles!=null?parseFloat(r.volume_miles)||0:0,
        cpm_brl:r.cpm_brl!=null?parseFloat(r.cpm_brl)||0:0,
        taxas_brl:r.taxas_brl!=null?parseFloat(r.taxas_brl)||0:0,
        linked_leg_label:r.linked_leg_label||'', linked_leg_dep:r.linked_leg_dep||'',
        linked_leg_arr:r.linked_leg_arr||'', linked_leg_fn:r.linked_leg_fn||'',
        linked_flight_date:r.linked_flight_date||'', linked_airline_iata:r.linked_airline_iata||'',
        linked_pnr:r.linked_pnr||''
      };
    }
    var amt=parseFloat(r.amount)||0, paid=parseFloat(r.paidAmount)||0;
    var st=r.status||'draft', ip=(st==='paid'||st==='pago');
    return {
      _id:r.id||'', supplier:r.supplier||'\u2014', category:r.category||'\u2014',
      dateVal:r.dueDate||'', statusKey:ip?'paid':(st==='overdue'?'overdue':(st==='confirmed'?'confirmed':'pending')),
      pnrRef:r.pnrRef||'', brl:brl,
      paidBRL:ip?brl:(amt>0?brl*paid/amt:0), remBRL:ip?0:brl*(amt>0?Math.max(0,amt-paid)/amt:1),
      notes:r.notes||'', isSync:false, isCC:false,
      programme:'', volume_miles:0, cpm_brl:0, taxas_brl:0,
      linked_leg_label:'', linked_leg_dep:'', linked_leg_arr:'', linked_leg_fn:'',
      linked_flight_date:'', linked_airline_iata:'', linked_pnr:''
    };
  }

  function _fmtMiles322(v) { var n=parseFloat(v)||0; return n===0?'\u2014':Math.round(n).toLocaleString('pt-BR'); }
  function _fmtRate322(v)  { var n=parseFloat(v)||0; return n===0?'\u2014':n.toLocaleString('pt-BR',{minimumFractionDigits:3,maximumFractionDigits:4}); }

  function _getPnlFooter322() {
    var el = document.getElementById('doss-fin-pnl-footer');
    if (el) return el;
    var totalEl = document.getElementById('doss-fin-exp-total');
    if (!totalEl) return null;
    var footer = document.createElement('div');
    footer.id = 'doss-fin-pnl-footer';
    footer.style.cssText = 'margin-top:10px;padding:10px 14px;border-radius:6px;' +
      'background:linear-gradient(90deg,rgba(6,32,59,0.07) 0%,rgba(212,175,55,0.10) 100%);' +
      'border:1px solid rgba(6,32,59,0.13);font-size:0.76rem;';
    totalEl.parentNode.insertBefore(footer, totalEl.nextSibling);
    return footer;
  }

  function _renderExp322(id, data) {
    var tbody   = document.getElementById('doss-fin-exp-body');
    var empty   = document.getElementById('doss-fin-exp-empty');
    var totalEl = document.getElementById('doss-fin-exp-total');
    if (!tbody) return;

    /* Strict scope */
    var globalRecs = _globalForDossier322(id, 'saida');
    var gSids = Object.create(null);
    globalRecs.forEach(function(r){ if(r.source_id) gSids[r.source_id]=true; if(r.id) gSids[r.id]=true; });
    var localOnly = ((data&&data.expenses)||[]).filter(function(e){
      return !(e.id&&gSids[e.id]) && !(e.source_id&&gSids[e.source_id]);
    });
    var allRows = globalRecs.concat(localOnly);

    /* Update thead (13-col v3.20 order + checkbox) */
    var table = tbody; while(table&&table.tagName!=='TABLE') table=table.parentNode;
    if (table && table.tHead) {
      table.tHead.innerHTML = '<tr>' + _chkTh322('exp') +
        '<th class="td-amt" style="white-space:nowrap;">Valor\u00a0(BRL)</th><th></th>' +
        '<th>Categoria</th><th>Fornecedor</th><th>Programme</th>' +
        '<th style="max-width:200px;">D\u00e9tails</th>' +
        '<th style="text-align:right;white-space:nowrap;">Vol.\u00a0(Miles)</th>' +
        '<th style="text-align:right;white-space:nowrap;">C.P.M\u00a0(R$)</th>' +
        '<th style="text-align:right;white-space:nowrap;">Taxas\u00a0(R$)</th>' +
        '<th style="white-space:nowrap;">Vencimento</th><th>Status</th>' +
        '<th class="td-amt" style="white-space:nowrap;">Pago</th>' +
        '<th class="td-amt" style="white-space:nowrap;">Restante</th></tr>';
    }

    tbody.innerHTML = '';
    _sel322.exp = {};

    /* Split pnl_total_cost rows */
    var mainRows=[], pnlRows=[];
    allRows.forEach(function(r){
      var sid=r.source_id||r.id||'';
      if (sid.indexOf('pnl_total_cost')===0) pnlRows.push(r);
      else mainRows.push(r);
    });

    if (!mainRows.length) {
      if (empty) empty.style.display=''; if (totalEl) totalEl.innerHTML='';
    } else {
      if (empty) empty.style.display='none';
      var BADGE  = {paid:'fbadge-paid',confirmed:'fbadge-confirmed',pending:'fbadge-pending',overdue:'fbadge-overdue',draft:'fbadge-draft'};
      var LABELS = {paid:'Pago',confirmed:'Confirmado',pending:'Pendente',overdue:'Vencido',draft:'Rascunho'};
      var totalBRL=0, paidBRL=0;

      mainRows.forEach(function(r) {
        var n = _normalizeExp322(r);
        totalBRL += n.brl; paidBRL += n.paidBRL;
        var badgeCls=BADGE[n.statusKey]||'fbadge-draft', lbl=LABELS[n.statusKey]||n.statusKey;
        var remColor = n.remBRL>0?'var(--red)':'#16a34a';
        var lid = n._id || _uid322();
        var actionCell = n.isSync
          ? '<span style="font-size:0.6rem;color:var(--navy-faint);">sync</span>'
          : '<button class="db-action-btn" onclick="dossFinEditLine(\'exp\',\''+_esc322(lid)+'\')" title="Editar">&#9999;</button>' +
            '<button class="db-action-btn del" onclick="dossFinDeleteLine(\'exp\',\''+_esc322(lid)+'\')" title="Apagar">&times;</button>';
        var ccProg = n.isCC&&n.programme
          ? '<span style="display:inline-block;background:rgba(6,32,59,0.07);border-radius:3px;padding:1px 5px;font-size:0.66rem;white-space:nowrap;">'+_esc322(n.programme)+'</span>'
          : '<span style="color:var(--navy-faint);">\u2014</span>';
        var ccVol   = n.isCC&&n.volume_miles>0 ? '<span style="font-family:monospace;font-size:0.72rem;">'+_fmtMiles322(n.volume_miles)+'</span>' : '<span style="color:var(--navy-faint);">\u2014</span>';
        var ccCpm   = n.isCC&&n.cpm_brl>0      ? '<span style="font-family:monospace;font-size:0.72rem;">'+_fmtRate322(n.cpm_brl)+'</span>'    : '<span style="color:var(--navy-faint);">\u2014</span>';
        var ccTaxas = n.isCC&&n.taxas_brl>0    ? '<span style="font-family:monospace;font-size:0.72rem;">'+_fmt322(n.taxas_brl,'BRL')+'</span>': '<span style="color:var(--navy-faint);">\u2014</span>';
        var det=_buildDetails322(n),detCell=det
          ?'<td style="font-size:0.64rem;font-family:monospace;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--navy);" title="'+_esc322(det)+'">'+_esc322(det)+'</td>'
          :'<td style="color:var(--navy-faint);">\u2014</td>';

        var tr=document.createElement('tr');
        if (n.isCC) tr.style.background='rgba(251,191,36,0.04)';
        tr.innerHTML =
          _chkTd322('exp', lid) +
          '<td class="td-amt" style="white-space:nowrap;font-weight:700;color:var(--navy);">'+_fmt322(n.brl,'BRL')+'</td>' +
          '<td style="white-space:nowrap;">'+actionCell+'</td>' +
          '<td><span class="fbadge fbadge-draft" style="font-size:0.54rem;">'+_esc322(n.category)+'</span></td>' +
          '<td style="font-weight:600;">'+_esc322(n.supplier)+'</td>' +
          '<td>'+ccProg+'</td>' +
          detCell +
          '<td style="text-align:right;">'+ccVol+'</td>' +
          '<td style="text-align:right;">'+ccCpm+'</td>' +
          '<td style="text-align:right;">'+ccTaxas+'</td>' +
          '<td style="white-space:nowrap;font-size:0.8rem;">'+_date322(n.dateVal)+'</td>' +
          '<td class="td-status"><span class="fbadge '+badgeCls+'">'+lbl+'</span></td>' +
          '<td class="td-amt" style="color:#16a34a;white-space:nowrap;">'+_fmt322(n.paidBRL,'BRL')+'</td>' +
          '<td class="td-amt" style="color:'+remColor+';white-space:nowrap;">'+_fmt322(n.remBRL,'BRL')+'</td>';
        tbody.appendChild(tr);
      });

      if (totalEl) {
        var rem=totalBRL-paidBRL;
        totalEl.innerHTML='<span style="color:var(--navy-soft);font-size:0.72rem;">Total:</span> <strong>'+_fmt322(totalBRL,'BRL')+'</strong>' +
          '&nbsp;&nbsp;<span style="color:var(--navy-soft);font-size:0.72rem;">Pago:</span> <strong style="color:#16a34a;">'+_fmt322(paidBRL,'BRL')+'</strong>' +
          '&nbsp;&nbsp;<span style="color:var(--navy-soft);font-size:0.72rem;">Restante:</span> <strong style="color:'+(rem>0?'var(--red)':'#16a34a')+';">'+_fmt322(rem,'BRL')+'</strong>';
      }
    }

    /* PNL footer block */
    var footerEl = _getPnlFooter322();
    if (footerEl) {
      if (!pnlRows.length) { footerEl.style.display='none'; footerEl.innerHTML=''; }
      else {
        footerEl.style.display='';
        var html='<div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;">' +
          '<span style="font-weight:700;color:var(--navy);font-size:0.72rem;letter-spacing:0.04em;text-transform:uppercase;">&#9654;\u00a0P&L\u00a0/\u00a0Custo\u00a0Total</span>';
        pnlRows.forEach(function(r){
          var n=_normalizeExp322(r);
          var lbl=(n.supplier&&n.supplier!=='\u2014'?n.supplier:n._id||'PNL').replace(/^pnl_total_cost__[^_]+__?/,'');
          if (!lbl) lbl='PNL';
          var rc=n.remBRL>0?'var(--red)':'#16a34a';
          html+='<span style="display:inline-flex;align-items:center;gap:6px;background:rgba(255,255,255,0.65);border:1px solid rgba(6,32,59,0.15);border-radius:5px;padding:4px 10px;">' +
            '<span style="color:var(--navy-soft);font-size:0.68rem;">'+_esc322(lbl)+'</span>' +
            '<strong style="font-size:0.78rem;color:var(--navy);">'+_fmt322(n.brl,'BRL')+'</strong>' +
            (n.paidBRL>0?'<span style="font-size:0.66rem;color:#16a34a;">Pago:\u00a0'+_fmt322(n.paidBRL,'BRL')+'</span>':'') +
            (n.remBRL>0?'<span style="font-size:0.66rem;color:'+rc+';">Resto:\u00a0'+_fmt322(n.remBRL,'BRL')+'</span>':'') +
            '</span>';
        });
        html+='</div>';
        footerEl.innerHTML=html;
      }
    }
    _updateBulkBar322('exp');
  }

  /* Expose for v310RefreshDespesas */
  window._v36RenderExpenses    = _renderExp322;
  window.v310RefreshDespesas   = function() {
    try {
      var id=_activeId322(), data=null;
      if (id) try { data=JSON.parse(localStorage.getItem('expatur_doss_finance_'+id)||'null'); } catch(e) {}
      _renderExp322(id, data);
    } catch(e) { console.warn('[v3.22] exp refresh error',e); }
  };

  /* ═══════════════════════════════════════════════════════════════
     SECTION 9 — Créditos renderer (strict scope + checkboxes + edit)
  ═══════════════════════════════════════════════════════════════ */
  function _renderCred322(id, data) {
    var tbody = document.getElementById('doss-fin-cred-body');
    var empty = document.getElementById('doss-fin-cred-empty');
    if (!tbody) return;

    var table = tbody; while(table&&table.tagName!=='TABLE') table=table.parentNode;
    if (table && table.tHead) {
      table.tHead.innerHTML = '<tr>' + _chkTh322('cred') +
        '<th>Tipo</th><th>Titular</th><th>Motivo</th><th>Expira</th>' +
        '<th class="td-amt">Valor orig.</th><th class="td-amt">Utilizado</th>' +
        '<th class="td-amt">Dispon\u00edvel</th><th>Status</th><th></th></tr>';
    }

    var rows = (data&&data.credits)||[];
    tbody.innerHTML = '';
    _sel322.cred = {};

    if (!rows.length) { if (empty) empty.style.display=''; _updateBulkBar322('cred'); return; }
    if (empty) empty.style.display='none';

    var typeLabels={client:'Cr\u00e9dito cliente',supplier:'Cr\u00e9dito fornecedor',internal:'Ajuste interno',voucher:'Voucher'};
    rows.forEach(function(c) {
      var remaining=Math.max(0,(parseFloat(c.originalAmount)||0)-(parseFloat(c.usedAmount)||0));
      var expired=c.expiryDate&&c.expiryDate<_today322();
      var status=expired?'Expirado':remaining<=0?'Utilizado':'Dispon\u00edvel';
      var badgeCls=expired||remaining<=0?'fbadge-void':'fbadge-credit';
      var lid=c.id||_uid322();
      var tr=document.createElement('tr');
      tr.innerHTML =
        _chkTd322('cred', lid) +
        '<td><span class="fbadge fbadge-credit" style="font-size:0.56rem;">'+_esc322(typeLabels[c.creditType]||c.creditType)+'</span></td>' +
        '<td>'+_esc322(c.owner||'\u2014')+'</td>' +
        '<td>'+_esc322(c.reason||'\u2014')+'</td>' +
        '<td>'+_date322(c.expiryDate)+'</td>' +
        '<td class="td-amt">'+_fmt322(c.originalAmount,c.currency)+'</td>' +
        '<td class="td-amt">'+_fmt322(c.usedAmount||0,c.currency)+'</td>' +
        '<td class="td-amt" style="color:'+(remaining>0?'#4338ca':'#6b7280')+';">'+_fmt322(remaining,c.currency)+'</td>' +
        '<td class="td-status"><span class="fbadge '+badgeCls+'">'+status+'</span></td>' +
        '<td style="white-space:nowrap;">' +
          '<button class="db-action-btn" onclick="dossFinEditLine(\'credit\',\''+_esc322(lid)+'\')" title="Editar">&#9999;</button>' +
          '<button class="db-action-btn del" onclick="dossFinDeleteLine(\'credit\',\''+_esc322(lid)+'\')" title="Apagar">&times;</button>' +
        '</td>';
      tbody.appendChild(tr);
    });
    _updateBulkBar322('cred');
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 10 — Fornecedores renderer (strict scope + per-item delete)
  ═══════════════════════════════════════════════════════════════ */
  function _renderSupp322(id, data) {
    var container = document.getElementById('doss-fin-supp-list');
    if (!container) return;

    /* Strict scope: only data.expenses (already per-dossier) */
    var expenses = (data&&data.expenses)||[];
    var suppMap = {};
    expenses.forEach(function(e) {
      var sn=e.supplier||'\u2014';
      if (!suppMap[sn]) suppMap[sn]={name:sn,total:0,paid:0,items:[]};
      suppMap[sn].total += parseFloat(e.amount)||0;
      suppMap[sn].paid  += parseFloat(e.paidAmount)||0;
      suppMap[sn].items.push(e);
    });

    var keys=Object.keys(suppMap);
    if (!keys.length) {
      container.innerHTML='<div class="doss-fin-empty">Nenhum fornecedor ligado. Registe uma despesa para associar um fornecedor.</div>';
      return;
    }

    /* Also include synced global records for display (read-only) */
    var globalExp = _globalForDossier322(id,'saida');
    globalExp.forEach(function(e) {
      var sn=e.fornecedor||e.supplier||'(sync)';
      if (!suppMap[sn]) suppMap[sn]={name:sn,total:0,paid:0,items:[]};
      /* Avoid double-counting items already in local */
      var lid=e.source_id||e.id||'';
      var dup=suppMap[sn].items.some(function(x){ return (x.id&&x.id===lid)||(x.source_id&&x.source_id===lid); });
      if (!dup) {
        suppMap[sn].total += parseFloat(e.brl_amount||e.amount||0);
        suppMap[sn].paid  += e.pago==='pago'?parseFloat(e.brl_amount||e.amount||0):0;
        suppMap[sn].items.push(Object.assign({},e,{_isGlobalSync:true}));
      }
    });

    keys = Object.keys(suppMap);
    container.innerHTML = keys.map(function(sn) {
      var s=suppMap[sn], bal=s.total-s.paid;
      return '<div class="forn-ledger-card" style="margin-bottom:0.75rem;">' +
        '<div class="forn-ledger-header"><div class="forn-ledger-name">'+_esc322(s.name)+'</div>' +
        '<div style="font-size:0.72rem;color:rgba(255,255,255,0.75);">'+s.items.length+' linha(s)</div></div>' +
        '<div class="forn-ledger-body"><div class="forn-ledger-stats">' +
          '<div class="forn-ledger-stat"><span class="forn-ledger-stat-label">Total</span><span class="forn-ledger-stat-val">'+_fmt322(s.total,'BRL')+'</span></div>' +
          '<div class="forn-ledger-stat"><span class="forn-ledger-stat-label">Pago</span><span class="forn-ledger-stat-val green">'+_fmt322(s.paid,'BRL')+'</span></div>' +
          '<div class="forn-ledger-stat"><span class="forn-ledger-stat-label">Restante</span><span class="forn-ledger-stat-val '+(bal>0?'red':'green')+'">'+_fmt322(bal,'BRL')+'</span></div>' +
          '<div class="forn-ledger-stat"><span class="forn-ledger-stat-label">Itens</span><span class="forn-ledger-stat-val">'+s.items.length+'</span></div>' +
        '</div>' +
        '<table class="doss-fin-table" style="font-size:0.72rem;"><thead><tr>' +
          '<th>Categoria</th><th>Ref</th><th>Vencimento</th><th style="text-align:right;">Valor</th><th>Status</th><th></th></tr></thead><tbody>' +
        s.items.map(function(e){
          var lid=e.id||e.source_id||'';
          var del=e._isGlobalSync
            ? '<button class="db-action-btn del" onclick="dossFinDeleteLine(\'exp\',\''+_esc322(lid)+'\')" title="Apagar sync">&times;</button>'
            : '<button class="db-action-btn del" onclick="dossFinDeleteLine(\'exp\',\''+_esc322(lid)+'\')" title="Apagar">&times;</button>';
          return '<tr><td>'+_esc322(e.category||e.categoria||'\u2014')+'</td>' +
            '<td style="font-family:monospace;font-size:0.68rem;">'+_esc322(e.pnrRef||e.source_id||'\u2014')+'</td>' +
            '<td>'+_date322(e.dueDate||e.vencimento)+'</td>' +
            '<td style="text-align:right;font-weight:700;">'+_fmt322(e.brl_amount||e.amount||0,'BRL')+'</td>' +
            '<td><span class="fbadge fbadge-'+(e.status||e.pago||'draft')+'">'+_esc322(e.status||e.pago||'draft')+'</span></td>' +
            '<td>'+del+'</td></tr>';
        }).join('') +
        '</tbody></table></div></div>';
    }).join('');
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 11 — Auditoria renderer (clear-all button)
  ═══════════════════════════════════════════════════════════════ */
  function _renderAudit322(id, data) {
    var container=document.getElementById('doss-fin-audit-list');
    if (!container) return;
    var audit=(data&&data.audit)||[];

    /* Ensure a header row with "Limpar tudo" exists */
    var headerEl=document.getElementById('doss-fin-audit-header');
    if (!headerEl) {
      headerEl=document.createElement('div');
      headerEl.id='doss-fin-audit-header';
      headerEl.style.cssText='display:flex;justify-content:flex-end;margin-bottom:10px;';
      container.parentNode.insertBefore(headerEl, container);
    }
    headerEl.innerHTML = audit.length
      ? '<button class="db-action-btn del" style="font-size:0.7rem;" onclick="dossFinClearAudit322()">Limpar auditoria</button>'
      : '';

    if (!audit.length) {
      container.innerHTML='<div class="doss-fin-empty">Nenhuma a\u00e7\u00e3o financeira registada ainda.</div>';
      return;
    }
    container.innerHTML = audit.map(function(a) {
      var d=new Date(a.ts);
      var ts=d.toLocaleDateString('pt-BR')+' '+d.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
      return '<div class="audit-row">' +
        '<div class="audit-dot '+_esc322(a.color||'gray')+'"></div>' +
        '<div class="audit-time">'+ts+'</div>' +
        '<div class="audit-action">'+_esc322(a.action)+'<small>'+_esc322(a.ref||'')+'</small></div>' +
        '</div>';
    }).join('');
  }

  window.dossFinClearAudit322 = function() {
    if (!confirm('Limpar todo o histórico de auditoria deste dossier?')) return;
    var id=_activeId322(); if (!id) return;
    var data=_dossLoad322(id); if (!data) return;
    data.audit=[];
    _dossSave322(id, data);
    if (typeof window.dossFinRenderPanel==='function') window.dossFinRenderPanel();
    if (typeof toast==='function') toast('Auditoria limpa','info');
  };

  /* ═══════════════════════════════════════════════════════════════
     SECTION 12 — Replace dossFinRenderPanel to use v3.22 renderers
  ═══════════════════════════════════════════════════════════════ */
  var _prev322Panel = window.dossFinRenderPanel;
  window.dossFinRenderPanel = function() {
    var id = _activeId322();
    if (!id) { if (typeof _prev322Panel==='function') _prev322Panel.apply(this,arguments); return; }
    var data = _dossLoad322(id);
    if (!data) {
      if (localStorage.getItem('expatur_booked_'+id)==='1') {
        if (typeof dossFIN_init==='function') data=dossFIN_init(id);
        else { data={id:id,status:'open',receivables:[],expenses:[],credits:[],audit:[]}; _dossSave322(id,data); }
      } else {
        var container=document.getElementById('dv-panel-finance');
        if (container) {
          var card=container.querySelector('.card');
          if (card) card.innerHTML='<div style="padding:2rem;text-align:center;color:var(--navy-faint);font-size:0.88rem;font-style:italic;">Le module Finance sera disponible après avoir cliqué sur <strong>BOOK</strong>.</div>';
        }
        return;
      }
    }
    /* Read active tab */
    var activeTab='overview';
    document.querySelectorAll('.doss-fin-tab').forEach(function(b){ if(b.classList.contains('active')) activeTab=b.dataset.dftab||'overview'; });
    switch(activeTab) {
      case 'overview':    _renderOverview322(id, data);  break;
      case 'receivables': _renderRecv322(id, data);      break;
      case 'expenses':    _renderExp322(id, data);       break;
      case 'credits':     _renderCred322(id, data);      break;
      case 'suppliers':   _renderSupp322(id, data);      break;
      case 'audit':       _renderAudit322(id, data);     break;
      default:
        if (typeof _prev322Panel==='function') _prev322Panel.apply(this,arguments);
    }
  };

  /* Also wrap dossFinRenderPanel panel after tab switch */
  var _prevDossFinTab322 = window.dossFinTab;
  if (typeof _prevDossFinTab322==='function' && !window._v322TabWrap) {
    window._v322TabWrap = true;
    window.dossFinTab = function(tab) {
      /* Switch active CSS classes */
      document.querySelectorAll('.doss-fin-tab').forEach(function(b){ b.classList.toggle('active',b.dataset.dftab===tab); });
      document.querySelectorAll('.doss-fin-panel').forEach(function(p){ p.classList.toggle('active',p.id==='doss-fin-panel-'+tab); });
      window.dossFinRenderPanel();
    };
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 13 — Re-wire panel wrap on Finance panel open
  ═══════════════════════════════════════════════════════════════ */
  if (!window._v322PanelWrap) {
    window._v322PanelWrap = true;
    /* On every Finance tab activation inside a dossier, re-render */
    var _origDossFinPanel = window.dossFinRenderPanel;
    /* Wrap dossFinTab to always use v3.22 renderers after CSS switch */
    /* (already done above) */
  }

  /* ═══════════════════════════════════════════════════════════════
     SECTION 14 — Init
  ═══════════════════════════════════════════════════════════════ */
  function _init322() {
    try {
      var ab=document.querySelector('.doss-fin-tab.active');
      if (ab) window.dossFinRenderPanel();
    } catch(e) {}
  }

  if (document.readyState==='loading') document.addEventListener('DOMContentLoaded',_init322);
  else setTimeout(_init322, 250);

  console.log('[Patch v3.22] Dossier-scoped Finance active. Strict _dossRefs322 (no DOM leak). Row management: recv/exp/cred checkboxes + bulk delete. Suppliers: per-item delete. Audit: clear-all.');

})(); // end Patch v3.22

