/* ═══════════════════════════════════════════════════════════════════════
   Patch v3.23 — Finance > Despesas DETAILS column wrapping fix
   ─────────────────────────────────────────────────────────────────────
   Problem : detCell uses white-space:nowrap + text-overflow:ellipsis
             which truncates long DETAILS strings.
   Fix     : Post-process tr.cells[6] (DETAILS col) after every render —
             apply white-space:normal + word-break:break-word so the cell
             wraps and the row auto-expands. Full content stays in title=
             attribute (already set by _renderExp322) for hover tooltip.
   Guard   : window._v323DetailsWrap
   ═══════════════════════════════════════════════════════════════════════ */
(function() {
  'use strict';

  if (window._v323DetailsWrap) return;
  window._v323DetailsWrap = true;

  /* ── Core fix ─────────────────────────────────────────────────────── */
  function _fixDetailsCells323() {
    var tbody = document.getElementById('doss-fin-exp-body');
    if (!tbody) return;
    tbody.querySelectorAll('tr').forEach(function(tr) {
      /* Column indices (v3.22 with checkbox at position 0):
         0=chk  1=valor  2=actions  3=categoria  4=fornecedor
         5=programme  6=détails  7=vol  8=cpm  9=taxas … */
      var td = tr.cells[6];
      if (!td) return;
      var txt = td.textContent.trim();
      if (txt === '\u2014' || txt === '') return;   // skip empty / dash cells
      td.style.whiteSpace    = 'normal';
      td.style.wordBreak     = 'break-word';
      td.style.overflowWrap  = 'break-word';
      td.style.textOverflow  = '';
      td.style.overflow      = 'visible';
      td.style.lineHeight    = '1.4';
      td.style.verticalAlign = 'top';
      td.style.maxWidth      = '220px';
    });
  }

  /* ── Hook into v310RefreshDespesas ────────────────────────────────── */
  var _prev323Refresh = window.v310RefreshDespesas;
  window.v310RefreshDespesas = function() {
    if (typeof _prev323Refresh === 'function') _prev323Refresh.apply(this, arguments);
    setTimeout(_fixDetailsCells323, 0);
  };

  /* ── Hook into dossFinRenderPanel (expenses tab) ──────────────────── */
  var _prev323Panel = window.dossFinRenderPanel;
  window.dossFinRenderPanel = function() {
    if (typeof _prev323Panel === 'function') _prev323Panel.apply(this, arguments);
    /* Only post-process when the expenses tab is active */
    var ab = document.querySelector('.doss-fin-tab.active');
    if (ab && ab.dataset && ab.dataset.dftab === 'expenses') {
      setTimeout(_fixDetailsCells323, 0);
    }
  };

  /* ── Initial fix on load (in case panel already rendered) ─────────── */
  setTimeout(_fixDetailsCells323, 400);

  console.log('[Patch v3.23] DETAILS column wrapping active. tr.cells[6] white-space:normal + word-break:break-word. Hover title unchanged.');

})(); // end Patch v3.23

