  window.fin326SaveEdit = function() {
    if (!_editCtx326) return;
    var tbl = _editCtx326.tbl, did = _editCtx326.did, rid = _editCtx326.rid;
    var gv = function(id) {
      var el = document.getElementById(id);
      return el ? (el.tagName === 'INPUT' && el.type === 'number'
        ? (parseFloat(el.value) || 0) : el.value.trim()) : '';
    };
    var ts = new Date().toISOString();

    if (tbl === 'recv') {
      var d = _load326(did); if (!d) return;
      d.receivables = d.receivables.map(function(r) {
        if (r.id !== rid) return r;
        var dsc = String(gv('f326-a')||'');
        return Object.assign({}, r, {
          description:dsc, descricao:dsc,
          amount:gv('f326-b'), dueDate:gv('f326-c'), vencimento:gv('f326-c'),
          status:gv('f326-d'), payMethod:gv('f326-e'),
          notes:gv('f326-f'), nota:gv('f326-f'), _updAt:ts
        });
      });
      _save326(did, d);
    } else if (tbl === 'exp') {
      var d = _load326(did); if (!d) return;
      d.expenses = d.expenses.map(function(e) {
        if (e.id !== rid) return e;
        var sup = String(gv('f326-a')||''), cat = String(gv('f326-b')||'');
        var dsc = String(gv('f326-c')||'');
        return Object.assign({}, e, {
          supplier:sup, fornecedor:sup,
          category:cat, categoria:cat,
          description:dsc, descricao:dsc,
          amount:gv('f326-d'), dueDate:gv('f326-e'), vencimento:gv('f326-e'),
          status:gv('f326-f'), pnrRef:gv('f326-g'),
          notes:gv('f326-h'), nota:gv('f326-h'), _updAt:ts
        });
      });
      _save326(did, d);
    } else if (tbl === 'cred') {
      var d = _load326(did); if (!d) return;
      d.credits = d.credits.map(function(c) {
        if (c.id !== rid) return c;
        return Object.assign({}, c, {
          creditType:gv('f326-a'), owner:gv('f326-b'), reason:gv('f326-c'),
          originalAmount:gv('f326-d'), usedAmount:gv('f326-e'),
          expiryDate:gv('f326-f'), _updAt:ts
        });
      });
      _save326(did, d);
    } else if (tbl === 'lanc') {
      var arr = _loadGlobal326();
      arr = arr.map(function(it) {
        if (it.id !== rid) return it;
        var amt = gv('f326-d');
        return Object.assign({}, it, {
          descricao:gv('f326-a'), categoria:gv('f326-b'), fornecedor:gv('f326-c'),
          amount:amt, brl_amount:amt, vencimento:gv('f326-e'),
          tipo:gv('f326-f'), pago:gv('f326-g'), nota:gv('f326-h'), _updAt:ts
        });
      });
      _saveGlobal326(arr);
    }

    fin326CloseEdit();
    _refresh326(tbl);
    if (typeof toast === 'function') toast('Linha actualizada', 'success');
  };

