  window.finRenderFluxo = (function(_prev) {
    return function() {
      _prev.apply(this, arguments);
      _injectChkTh326('fluxo');

      var panel = document.getElementById('fin-panel-fluxo');
      if (panel) {
        var sd = panel.querySelector('[style*="overflow-x"]');
        if (sd) _ensureBulk326('fluxo', sd.parentNode);
      }

      var tbody = document.getElementById('fin-fluxo-body');
      if (!tbody) return;
      _sel326.fluxo = {};

      tbody.querySelectorAll('tr').forEach(function(tr) {
        if (!tr.cells.length) return;
        /* Month-divider row: extend colspan */
        var fc = tr.cells[0];
        if (fc && fc.classList && fc.classList.contains('fin-month-divider')) {
          fc.colSpan = (parseInt(fc.colSpan)||8) + 1;
          return;
        }
        /* Skip rows already decorated */
        if (tr.dataset.fin326k) return;
        /* Extract id from delete-button onclick */
        var del = tr.querySelector('button[onclick*="finDeleteItem"]');
        if (!del) return;
        var m = (del.getAttribute('onclick')||'').match(/finDeleteItem\(["']([^"']+)["']\)/);
        if (!m) return;
        var rid = m[1];
        tr.dataset.fin326k = rid;
        var td = document.createElement('td');
        td.className = 'fin326-chk-col';
        td.innerHTML = '<input type="checkbox" class="fin326-rchk"' +
          ' onclick="event.stopPropagation()"' +
          ' onchange="fin326ToggleRow(\'fluxo\',\''+_esc326(rid)+'\',this)">';
        tr.insertBefore(td, tr.cells[0]);
      });

      _setupDrag326('fluxo', tbody);
      _updateBulk326('fluxo');
    };
  }(window.finRenderFluxo));

