/* ══════════════════════════════════════════════════════════════════════════════
   PATCH v3.27 — Unified status actions across ALL financial tables
   ─────────────────────────────────────────────────────────────────────────────
   Adds to every financial table (per-dossier v3.22 + global v3.26):
     • "Marcar como pago"       — Despesas / Expenses (exp)
     • "Marcar como recebido"   — Recebimentos / Receivables (recv)
     • "Marcar pendente"        — undo for both
   Implementation:
     Per-dossier (v3.22): wrap dossFinSelectAll322 + dossFinRowCheckChange322
       on window; re-inject buttons into v322-bulk-bar after every bar update.
       Read checked row IDs from .v322-row-chk:checked[data-lid].
       Write to expatur_doss_finance_[id] + expatur_financeiro_lancamentos.
     Global (v3.26): inject buttons once into fin326-bulk-{tbl} bar after first
       render. Read selected rows from tr.fin326-selected[data-fin326k].
       Write to expatur_doss_finance_[dossierId] + expatur_financeiro_lancamentos.
   Guard: window._v327StatusActions
   ══════════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v327StatusActions) return;
  window._v327StatusActions = true;

  /* ══ §1. SELF-CONTAINED STORAGE HELPERS ══════════════════════════════════ */

  var _GKEY327 = 'expatur_financeiro_lancamentos';

  function _activeId327() {
    return localStorage.getItem('expatur_active_dossier') || '';
  }
  function _loadDoss327(did) {
    try { return JSON.parse(localStorage.getItem('expatur_doss_finance_' + did) || 'null'); } catch(e) { return null; }
  }
  function _saveDoss327(did, data) {
    try { localStorage.setItem('expatur_doss_finance_' + did, JSON.stringify(data)); } catch(e) {}
  }
  function _loadGlobal327() {
    try { return JSON.parse(localStorage.getItem(_GKEY327) || '[]'); } catch(e) { return []; }
  }
  function _saveGlobal327(arr) {
    try { localStorage.setItem(_GKEY327, JSON.stringify(arr)); } catch(e) {}
  }

  /* ══ §2. CSS ══════════════════════════════════════════════════════════════ */

  var _sty327 = document.createElement('style');
  _sty327.id  = 'fin327-styles';
  _sty327.textContent = [
    /* Per-dossier status buttons — blend with v322-btn style */
    '.v322-bulk-bar .fin327-doss-status-btn{',
    '  padding:3px 10px;border-radius:4px;border:none;cursor:pointer;',
    '  font-size:0.7rem;font-weight:700;font-family:inherit;transition:filter .12s;}',
    '.v322-bulk-bar .fin327-doss-mark-paid{background:#16a34a;color:#fff;}',
    '.v322-bulk-bar .fin327-doss-mark-recv{background:#16a34a;color:#fff;}',
    '.v322-bulk-bar .fin327-doss-mark-pending{background:rgba(6,32,59,0.12);color:var(--navy);}',
    '.v322-bulk-bar .fin327-doss-status-btn:hover{filter:brightness(1.12);}',
    /* Global v3.26 status buttons — blend with fin326-bulk-edit style */
    '.fin327-global-mark-paid{border-color:#16a34a !important;color:#16a34a !important;}',
    '.fin327-global-mark-recv{border-color:#16a34a !important;color:#16a34a !important;}',
    '.fin327-global-mark-paid:hover{background:#16a34a !important;color:#fff !important;}',
    '.fin327-global-mark-recv:hover{background:#16a34a !important;color:#fff !important;}'
  ].join('');
  document.head.appendChild(_sty327);

  /* ══ §3. PER-DOSSIER STATUS UPDATE LOGIC ════════════════════════════════ */

  /* Read checked row IDs from the per-dossier table body */
  function _getDossCheckedIds327(lineType) {
    var bodyId = 'doss-fin-' + (lineType === 'recv' ? 'recv' : 'exp') + '-body';
    var tbody  = document.getElementById(bodyId);
    var ids    = [];
    if (!tbody) return ids;
    tbody.querySelectorAll('.v322-row-chk:checked').forEach(function(c) {
      if (c.dataset.lid) ids.push(c.dataset.lid);
    });
    return ids;
  }

  /* Core: update per-dossier + global store for a set of row IDs */
  function _applyStatusDoss327(lineType, ids, newStatus) {
    if (!ids.length) return 0;
    var id   = _activeId327();
    var pago = (newStatus === 'paid') ? 'pago' : 'pendente';
    var ts   = new Date().toISOString();

    /* Per-dossier store */
    var data = id ? _loadDoss327(id) : null;
    if (data) {
      var arr  = lineType === 'recv' ? data.receivables : data.expenses;
      var tipo = lineType === 'recv' ? 'entrada' : 'saida';
      if (arr) {
        data[lineType === 'recv' ? 'receivables' : 'expenses'] = arr.map(function(r) {
          if (ids.indexOf(r.id) >= 0 || ids.indexOf(r.source_id) >= 0) {
            var patch = { pago: pago, status: newStatus, _updAt: ts };
            if (newStatus === 'paid') patch.paidAmount = r.amount;
            else patch.paidAmount = 0;
            return Object.assign({}, r, patch);
          }
          return r;
        });
        _saveDoss327(id, data);
      }
    }

    /* Global lancamentos store (covers synced records) */
    var tipo327 = lineType === 'recv' ? 'entrada' : 'saida';
    var global  = _loadGlobal327();
    var changed = false;
    global = global.map(function(r) {
      if (r.tipo === tipo327 && (ids.indexOf(r.source_id) >= 0 || ids.indexOf(r.id) >= 0)) {
        changed = true;
        return Object.assign({}, r, { pago: pago, status: newStatus, _updAt: ts });
      }
      return r;
    });
    if (changed) _saveGlobal327(global);

    return ids.length;
  }

  /* ─ Public handlers called by injected buttons ─ */

  window.dossFinBulkMarkPaid327 = function() {
    var ids = _getDossCheckedIds327('exp');
    var n   = _applyStatusDoss327('exp', ids, 'paid');
    if (!n) return;
    if (typeof window.dossFinRenderPanel === 'function') window.dossFinRenderPanel();
    if (typeof window.finRenderDespesas  === 'function') window.finRenderDespesas();
    if (typeof toast === 'function') toast(n + ' despesa(s) marcada(s) como paga(s)', 'success');
  };

  window.dossFinBulkMarkReceived327 = function() {
    var ids = _getDossCheckedIds327('recv');
    var n   = _applyStatusDoss327('recv', ids, 'paid');
    if (!n) return;
    if (typeof window.dossFinRenderPanel    === 'function') window.dossFinRenderPanel();
    if (typeof window.finRenderRecebimentos === 'function') window.finRenderRecebimentos();
    if (typeof toast === 'function') toast(n + ' recebimento(s) marcado(s) como recebido(s)', 'success');
  };

  window.dossFinBulkMarkPending327 = function(lineType) {
    var ids = _getDossCheckedIds327(lineType);
    var n   = _applyStatusDoss327(lineType, ids, 'pending');
    if (!n) return;
    if (typeof window.dossFinRenderPanel === 'function') window.dossFinRenderPanel();
    var refreshFn = lineType === 'recv' ? window.finRenderRecebimentos : window.finRenderDespesas;
    if (typeof refreshFn === 'function') refreshFn();
    if (typeof toast === 'function') toast(n + ' linha(s) marcada(s) como pendente(s)', 'info');
  };

  /* ─ Inject status buttons into v3.22 bulk bar (called after bar update) ─ */

  function _injectDossStatusBtns327(lineType) {
    if (lineType !== 'exp' && lineType !== 'recv') return;
    var bar = document.getElementById('v322-bulk-bar-' + lineType);
    if (!bar || !bar.classList.contains('visible')) return;
    /* Idempotent: skip if already injected (bar.innerHTML was just regenerated
       by _updateBulkBar322 so this check is reliable) */
    if (bar.querySelector('.fin327-doss-status-btn')) return;

    var delBtn = bar.querySelector('.v322-btn-del');
    if (!delBtn) return;

    var fragment = document.createDocumentFragment();

    if (lineType === 'exp') {
      var bPaid = document.createElement('button');
      bPaid.className = 'v322-btn fin327-doss-status-btn fin327-doss-mark-paid';
      bPaid.innerHTML = '&#10003; Marcar como pago';
      bPaid.onclick   = function() { window.dossFinBulkMarkPaid327(); };
      fragment.appendChild(bPaid);

      var bPend = document.createElement('button');
      bPend.className = 'v322-btn fin327-doss-status-btn fin327-doss-mark-pending';
      bPend.innerHTML = '\u21ba Marcar pendente';
      bPend.onclick   = function() { window.dossFinBulkMarkPending327('exp'); };
      fragment.appendChild(bPend);
    } else {
      var bRecv = document.createElement('button');
      bRecv.className = 'v322-btn fin327-doss-status-btn fin327-doss-mark-recv';
      bRecv.innerHTML = '&#10003; Marcar como recebido';
      bRecv.onclick   = function() { window.dossFinBulkMarkReceived327(); };
      fragment.appendChild(bRecv);

      var bPend2 = document.createElement('button');
      bPend2.className = 'v322-btn fin327-doss-status-btn fin327-doss-mark-pending';
      bPend2.innerHTML = '\u21ba Marcar pendente';
      bPend2.onclick   = function() { window.dossFinBulkMarkPending327('recv'); };
      fragment.appendChild(bPend2);
    }

    /* Insert before "Apagar" button */
    bar.insertBefore(fragment, delBtn);
  }

  /* ─ Wrap v3.22 window selection handlers ─ */
  /* _updateBulkBar322 is private, but it's always called synchronously INSIDE
     these window functions before they return, so our post-call injection works. */

  function _wrapForStatusInjection327(fnName) {
    if (typeof window[fnName] !== 'function') return;
    var _prev = window[fnName];
    window[fnName] = function() {
      _prev.apply(this, arguments);
      /* arguments[0] is always lineType ('recv' | 'exp' | 'cred') */
      _injectDossStatusBtns327(arguments[0]);
    };
  }

  _wrapForStatusInjection327('dossFinSelectAll322');
  _wrapForStatusInjection327('dossFinRowCheckChange322');

  /* ══ §4. GLOBAL TABLE STATUS UPDATE LOGIC (v3.26) ══════════════════════ */

  /* Read all selected dossier+row pairs from a global fin326 table */
  function _getGlobalSelected327(tbl) {
    var bodyId = { recv:'fin-recv-body', exp:'fin-exp-body', cred:'fin-cred-body',
                   fluxo:'fin-fluxo-body', lanc:'fin-lanc-body' }[tbl];
    var tbody  = document.getElementById(bodyId);
    var result = []; /* [{did, rid}] */
    if (!tbody) return result;
    tbody.querySelectorAll('tr.fin326-selected[data-fin326k]').forEach(function(tr) {
      var k = tr.dataset.fin326k;
      var p = k.indexOf('|');
      if (p < 0) return;
      result.push({ did: k.slice(0, p), rid: k.slice(p + 1) });
    });
    return result;
  }

  /* Core: apply status update for global table rows */
  function _applyStatusGlobal327(tbl, newStatus) {
    var items = _getGlobalSelected327(tbl);
    if (!items.length) return 0;

    var lineType = (tbl === 'recv') ? 'recv' : 'exp';
    var pago     = (newStatus === 'paid') ? 'pago' : 'pendente';
    var tipo327  = (tbl === 'recv') ? 'entrada' : 'saida';
    var ts       = new Date().toISOString();

    /* Group by dossier for efficient storage I/O */
    var byDoss = Object.create(null);
    items.forEach(function(u) {
      if (!byDoss[u.did]) byDoss[u.did] = [];
      byDoss[u.did].push(u.rid);
    });

    Object.keys(byDoss).forEach(function(did) {
      var rids = byDoss[did];
      var data = _loadDoss327(did);
      if (!data) return;
      var arrKey = (lineType === 'recv') ? 'receivables' : 'expenses';
      if (!data[arrKey]) return;
      data[arrKey] = data[arrKey].map(function(r) {
        if (rids.indexOf(r.id) >= 0) {
          var patch = { pago: pago, status: newStatus, _updAt: ts };
          if (newStatus === 'paid') patch.paidAmount = r.amount;
          else patch.paidAmount = 0;
          return Object.assign({}, r, patch);
        }
        return r;
      });
      _saveDoss327(did, data);
    });

    /* Global lancamentos for synced rows */
    var allRids = items.map(function(u){ return u.rid; });
    var global  = _loadGlobal327();
    var changed = false;
    global = global.map(function(r) {
      if (r.tipo === tipo327 &&
          (allRids.indexOf(r.source_id) >= 0 || allRids.indexOf(r.id) >= 0)) {
        changed = true;
        return Object.assign({}, r, { pago: pago, status: newStatus, _updAt: ts });
      }
      return r;
    });
    if (changed) _saveGlobal327(global);

    return items.length;
  }

  /* ─ Public handlers for global tables ─ */

  window.fin327MarkPaid = function(tbl) {
    var n = _applyStatusGlobal327(tbl, 'paid');
    if (!n) return;
    var label = (tbl === 'recv') ? 'recebimento(s) marcado(s) como recebido(s)'
                                 : 'despesa(s) marcada(s) como paga(s)';
    var refresh = (tbl === 'recv') ? window.finRenderRecebimentos : window.finRenderDespesas;
    if (typeof refresh === 'function') refresh();
    if (typeof window.finRenderFluxo === 'function') window.finRenderFluxo();
    if (typeof toast === 'function') toast(n + ' ' + label, 'success');
  };

  window.fin327MarkPending = function(tbl) {
    var n = _applyStatusGlobal327(tbl, 'pending');
    if (!n) return;
    var refresh = (tbl === 'recv') ? window.finRenderRecebimentos : window.finRenderDespesas;
    if (typeof refresh === 'function') refresh();
    if (typeof toast === 'function') toast(n + ' linha(s) marcada(s) como pendente(s)', 'info');
  };

  /* ─ Inject status buttons into v3.26 global bulk bars ─ */
  /* These bars persist across renders (created once by _ensureBulk326),
     so we inject once via a guard flag on the bar element itself. */

  function _injectGlobalStatusBtns327(tbl) {
    if (tbl !== 'exp' && tbl !== 'recv') return;
    var bar = document.getElementById('fin326-bulk-' + tbl);
    if (!bar) return;
    if (bar.dataset.fin327Injected) return; /* idempotent */
    var delBtn = bar.querySelector('.fin326-bulk-del');
    if (!delBtn) return;

    var isRecv  = (tbl === 'recv');
    var mainLbl = isRecv ? '&#10003; Marcar como recebido' : '&#10003; Marcar como pago';
    var mainFn  = 'fin327MarkPaid(\'' + tbl + '\')';
    var pendFn  = 'fin327MarkPending(\'' + tbl + '\')';

    var bMain = document.createElement('button');
    bMain.className = 'fin326-bulk-edit fin327-global-status-btn ' +
      (isRecv ? 'fin327-global-mark-recv' : 'fin327-global-mark-paid');
    bMain.innerHTML = mainLbl;
    bMain.setAttribute('onclick', mainFn);

    var bPend = document.createElement('button');
    bPend.className = 'fin326-bulk-edit fin327-global-status-btn fin327-global-mark-pending';
    bPend.innerHTML = '\u21ba Marcar pendente';
    bPend.setAttribute('onclick', pendFn);

    bar.insertBefore(bMain, delBtn);
    bar.insertBefore(bPend, delBtn);
    bar.dataset.fin327Injected = '1';
  }

  /* ─ Wrap global render functions to trigger button injection ─ */

  window.finRenderDespesas = (function(_prev327Exp) {
    return function() {
      _prev327Exp.apply(this, arguments);
      _injectGlobalStatusBtns327('exp');
    };
  }(window.finRenderDespesas));

  window.finRenderRecebimentos = (function(_prev327Recv) {
    return function() {
      _prev327Recv.apply(this, arguments);
      _injectGlobalStatusBtns327('recv');
    };
  }(window.finRenderRecebimentos));

  /* ══ §5. SUMMARY LOG ════════════════════════════════════════════════════ */

  console.log('[Patch v3.27] Unified status actions active.',
    'Per-dossier (v3.22): dossFinBulkMarkPaid327 / dossFinBulkMarkReceived327 / dossFinBulkMarkPending327.',
    'Global (v3.26): fin327MarkPaid / fin327MarkPending.',
    'Tables: recv (mark received), exp (mark paid), both (mark pending).',
    'Storage: per-dossier expatur_doss_finance_[id] + global expatur_financeiro_lancamentos.');

})(); // end Patch v3.27

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════════
   PATCH v3.28 — Paiement / Émission form: prefill defaults
   ─────────────────────────────────────────────────────────────────────────────
   Problem:
     • openEmissionModal() calls _emRestoreState() first. When state restores,
       the fresh-defaults block is SKIPPED entirely — client fields are never
       refreshed from the Client onglet.
     • em-inv-due defaults to '0' (Aujourd'hui), should default to '1' (1 jour).
     • em-stripe-pw has no prefill at all.
   Fix:
     Wrap window.openEmissionModal so that AFTER the original runs, we always:
       1. Overwrite em-inv-name  with prenom+nom from Client onglet (if available)
       2. Overwrite em-inv-email with cli-email (if available)
       3. Overwrite em-inv-phone with cli-tel   (if available)
       4. Set em-inv-due to '1' and call emUpdateDueDate()
       5. Set em-stripe-pw to '12345' if it is currently empty
   Guard: window._v328PaiementPrefill
   ══════════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v328PaiementPrefill) return;
  window._v328PaiementPrefill = true;

  /* ── Core prefill function ─────────────────────────────────────────────── */

  function _prefill328() {

    /* 1 + 2 + 3 — Client fields: always overwrite if client data is present */

    var prenom   = ((document.getElementById('cli-prenom') || {}).value || '').trim().toUpperCase();
    var nom      = ((document.getElementById('cli-nom')    || {}).value || '').trim().toUpperCase();
    var fullName = [prenom, nom].filter(Boolean).join(' ')
                  /* fallback: first pax line if client onglet is empty */
                  || ((document.getElementById('pax-name-1') || {}).value || '').trim().toUpperCase();

    var email    = ((document.getElementById('cli-email') || {}).value || '').trim();
    var phone    = ((document.getElementById('cli-tel')   || {}).value || '').trim();

    var nameEl   = document.getElementById('em-inv-name');
    var emailEl  = document.getElementById('em-inv-email');
    var phoneEl  = document.getElementById('em-inv-phone');

    /* Fill only when we have actual client data (never clobber manually-typed
       values with an empty string) */
    if (nameEl  && fullName) nameEl.value  = fullName;
    if (emailEl && email)    emailEl.value = email;
    if (phoneEl && phone)    phoneEl.value = phone;

    /* 4 — Délai de règlement: always default to 1 jour */

    var dueEl = document.getElementById('em-inv-due');
    if (dueEl) {
      dueEl.value = '1';
      if (typeof emUpdateDueDate === 'function') emUpdateDueDate();
    }

    /* 5 — Password: prefill with '12345' only when field is empty
       (preserves anything the user has already typed during this session) */

    var pwEl = document.getElementById('em-stripe-pw');
    if (pwEl && !pwEl.value) pwEl.value = '12345';
  }

  /* ── Wrap openEmissionModal ────────────────────────────────────────────── */

  var _prevOpen328 = window.openEmissionModal;

  window.openEmissionModal = function () {
    /* Run the original (handles state restore, amount display, etc.) */
    if (typeof _prevOpen328 === 'function') _prevOpen328.apply(this, arguments);
    /* Always apply fresh client data + correct defaults after the original */
    try { _prefill328(); } catch (e) { console.warn('[v3.28] prefill error', e); }
  };

  console.log('[Patch v3.28] Paiement prefill active.',
    'em-inv-name/email/phone <- Client onglet.',
    'em-inv-due  <- 1 jour (default).',
    'em-stripe-pw <- 12345 (when empty).');

})(); // end Patch v3.28

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════════
   PATCH v3.29 — Fix Financeiro: working checkboxes + delete in Fluxo & Lançamentos
   ─────────────────────────────────────────────────────────────────────────────
   Root cause of v3.26 failures for fluxo/lanc:
     • Post-inject wrapper searched for delete buttons via onClick regex.
     • `JSON.stringify(id)` produced "id" (double-quoted), breaking the HTML
       attribute: onclick="finDeleteItem("fin_xxx")" → getAttribute returns
       only 'finDeleteItem(' (value terminates at inner "), so regex never matched,
       no checkbox was injected into any row.
     • Delete buttons themselves were silently broken for same reason.
   Fix:
     • Full replacement of finRenderFluxo and finRenderLancamentos (like recv/exp/cred).
     • All IDs in onclick attributes use single-quote delimiters → valid HTML.
     • New fin329Delete() replaces finDeleteItem() for these tables.
     • finTogglePago wrapped to re-render with v3.29 renderers after local render.
     • Uses v3.26 internals exposed as window._fin326_* for seamless selection state.
   Guard: window._v329FluxoLanc
   ══════════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v329FluxoLanc) return;
  window._v329FluxoLanc = true;

  /* ══ §1. STORAGE HELPERS ═════════════════════════════════════════════════ */

  var _GKEY329 = 'expatur_financeiro_lancamentos';
  function _loadGlobal329() {
    try { return JSON.parse(localStorage.getItem(_GKEY329) || '[]'); } catch (e) { return []; }
  }
  function _saveGlobal329(arr) {
    try { localStorage.setItem(_GKEY329, JSON.stringify(arr)); } catch (e) {}
  }

  /* ══ §2. FORMATTING HELPERS ══════════════════════════════════════════════ */

  function _esc329(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }
  function _fmtBRL329(v) {
    var n = parseFloat(v) || 0;
    return 'R$\u00a0' + n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  function _dl329(d) {
    if (!d) return '\u2014';
    var p = d.split('-');
    return p.length === 3 ? p[2] + '/' + p[1] + '/' + p[0] : d;
  }
  function _today329() { return new Date().toISOString().slice(0, 10); }
  function _brlOf329(it) {
    if (it.brl_amount != null && parseFloat(it.brl_amount) > 0)
      return parseFloat(it.brl_amount);
    if (typeof window._fxEntryToBRL === 'function')
      return window._fxEntryToBRL(it);
    return parseFloat(it.valor || it.amount || 0) || 0;
  }
  function _toBRL329(amount, currency) {
    var v = parseFloat(amount) || 0;
    if (!currency || currency === 'BRL' || currency === 'R$') return v;
    if (typeof window._fxToBRL === 'function') return window._fxToBRL(v, currency);
    return v;
  }
  var _MO329 = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
  function _monthLabel329(ym) {
    var p = ym.split('-');
    return (_MO329[parseInt(p[1]) - 1] || p[1]) + ' ' + p[0];
  }
  function _badgeSimple329(pago, date) {
    var t = _today329();
    if (pago === 'pago')     return '<span class="fin-badge-pago">Pago</span>';
    if (!date || date > t)   return '<span class="fin-badge-futuro">Futuro</span>';
    if (date === t)          return '<span class="fin-badge-pendente">Hoje</span>';
    return '<span class="fin-badge-vencido">Vencido</span>';
  }
  function _badgeFull329(it) {
    var t = _today329();
    if (it.pago === 'pago')    return '<span class="fin-badge-pago">Pago</span>';
    if (!it.vencimento)        return '<span class="fin-badge-futuro">Pendente</span>';
    if (it.vencimento > t)     return '<span class="fin-badge-futuro">A vencer</span>';
    if (it.vencimento === t)   return '<span class="fin-badge-pendente">Hoje</span>';
    return '<span class="fin-badge-vencido">Vencido</span>';
  }

  /* ══ §3. BRIDGE TO V3.26 INTERNALS ══════════════════════════════════════ */

  function _clearSel329(tbl) {
    if (window._fin326_sel) window._fin326_sel[tbl] = {};
  }
  function _injectChkTh329(tbl) {
    if (typeof window._fin326_injectChkTh === 'function') window._fin326_injectChkTh(tbl);
  }
  function _ensureBulk329(tbl, parent) {
    if (typeof window._fin326_ensureBulk === 'function') window._fin326_ensureBulk(tbl, parent);
  }
  function _setupDrag329(tbl, tbody) {
    if (typeof window._fin326_setupDrag === 'function') window._fin326_setupDrag(tbl, tbody);
  }
  function _updateBulk329(tbl) {
    if (typeof window._fin326_updateBulk === 'function') window._fin326_updateBulk(tbl);
  }

  /* ══ §4. DELETE HANDLER (single-quoted IDs — no HTML attribute breakage) ═ */

  window.fin329Delete = function (rid) {
    if (!confirm('Apagar este lançamento?')) return;
    _saveGlobal329(_loadGlobal329().filter(function (x) { return x.id !== rid; }));
    if (typeof window.finRenderFluxo === 'function') window.finRenderFluxo();
    if (typeof window.finRenderLancamentos === 'function') window.finRenderLancamentos();
    if (typeof toast === 'function') toast('Lançamento apagado', 'info');
  };

  /* ══ §5. WRAP finTogglePago ══════════════════════════════════════════════
     The original finTogglePago (line ~13337) calls LOCAL finRenderLancamentos
     and finRenderFluxo (its own IIFE closure, not window.*). After it runs,
     we re-render via window.* to restore v3.29 checkboxes and controls.    */
  var _prevTogglePago329 = window.finTogglePago;
  window.finTogglePago = function (id) {
    if (typeof _prevTogglePago329 === 'function') _prevTogglePago329.apply(this, arguments);
    if (typeof window.finRenderLancamentos === 'function') window.finRenderLancamentos();
    if (typeof window.finRenderFluxo === 'function') window.finRenderFluxo();
  };

  /* ══ §6. finRenderFluxo — FULL REPLACEMENT ═══════════════════════════════
     Supersedes the v3.26 post-inject wrapper which failed because it tried
     to extract row IDs by parsing onClick attributes that were broken HTML.  */
  window.finRenderFluxo = function () {
    /* KPI row */
    if (typeof window.finRenderKPIs === 'function') window.finRenderKPIs();

    /* Inject select-all th into thead (guarded by _fin326_hdr flag) */
    _injectChkTh329('fluxo');

    /* Ensure bulk action bar above table */
    var panel = document.getElementById('fin-panel-fluxo');
    if (panel) {
      var sd = panel.querySelector('[style*="overflow-x"]');
      if (sd) _ensureBulk329('fluxo', sd.parentNode);
    }

    var tbody = document.getElementById('fin-fluxo-body');
    var empty = document.getElementById('fin-fluxo-empty');
    if (!tbody) return;

    var today = _today329();
    var allItems = [];

    /* ── Global lançamentos ── */
    _loadGlobal329().forEach(function (it) {
      allItems.push({
        date:      it.vencimento || (it.createdAt && it.createdAt.slice(0, 10)) || today,
        desc:      it.descricao  || '',
        categoria: it.categoria  || '\u2014',
        forn:      it.fornecedor || '\u2014',
        ref:       it.dossierRef || '',
        brl:       _brlOf329(it),
        tipo:      it.tipo,
        pago:      it.pago,
        id:        it.id,
        src:       'lanc'
      });
    });

    /* ── Booking payments ── */
    try {
      Object.keys(localStorage)
        .filter(function (k) { return k.indexOf('expatur_payments_') === 0; })
        .forEach(function (k) {
          var ref = k.replace('expatur_payments_', '').replace(/_/g, '-').replace(/^-+|-+$/g, '');
          var arr; try { arr = JSON.parse(localStorage.getItem(k) || '[]'); } catch (e) { arr = []; }
          arr.forEach(function (p) {
            var brl = (p.brl_amount != null)
              ? parseFloat(p.brl_amount) || 0
              : _toBRL329(parseFloat(p.amount) || 0, p.currency || 'EUR');
            allItems.push({
              date:      p.date || today,
              desc:      'Pagamento cliente' + (p.customer && p.customer.name ? ' \u2014 ' + p.customer.name : ''),
              categoria: 'Receita - Booking',
              forn:      (p.customer && p.customer.name) || '\u2014',
              ref:       ref,
              brl:       brl,
              tipo:      'entrada',
              pago:      p.status === 'paid' ? 'pago' : 'pendente',
              id:        null,
              src:       'booking'
            });
          });
        });
    } catch (e) {}

    /* ── Period filter ── */
    var pBtn = document.querySelector('.fin-filter-btn[data-period].active');
    var pDays = pBtn ? parseInt(pBtn.dataset.period) || 0 : 0;
    if (pDays > 0) {
      var cDate = new Date(); cDate.setDate(cDate.getDate() - pDays);
      var fDate = new Date(); fDate.setDate(fDate.getDate() + pDays);
      var cs = cDate.toISOString().slice(0, 10), fs = fDate.toISOString().slice(0, 10);
      allItems = allItems.filter(function (it) { return it.date >= cs && it.date <= fs; });
    }

    /* ── Type filter ── */
    var tBtn = document.querySelector('.fin-filter-btn[data-ftype].active');
    var tf = tBtn ? tBtn.dataset.ftype : 'all';
    if (tf !== 'all') allItems = allItems.filter(function (it) { return it.tipo === tf; });

    allItems.sort(function (a, b) { return b.date.localeCompare(a.date); });

    _clearSel329('fluxo');
    tbody.innerHTML = '';

    if (!allItems.length) {
      if (empty) empty.style.display = '';
      _updateBulk329('fluxo');
      return;
    }
    if (empty) empty.style.display = 'none';

    var curMonth = null;
    allItems.forEach(function (it) {
      /* Month divider */
      var mk = it.date.slice(0, 7);
      if (mk !== curMonth) {
        curMonth = mk;
        var mTr = document.createElement('tr');
        var mTd = document.createElement('td');
        mTd.colSpan = 9; /* 8 data columns + 1 checkbox column */
        mTd.className = 'fin-month-divider';
        mTd.textContent = _monthLabel329(mk);
        mTr.appendChild(mTd);
        tbody.appendChild(mTr);
      }

      var amtCls = it.tipo === 'entrada' ? 'fin-amount-entrada' : 'fin-amount-saida';
      var sign   = it.tipo === 'entrada' ? '+' : '\u2212';
      var badge  = _badgeSimple329(it.pago, it.date);
      var rid    = it.id || '';

      var tr = document.createElement('tr');
      if (rid) tr.dataset.fin326k = rid; /* only lançamento rows are selectable */

      /* Checkbox cell — lançamentos only (booking rows have no id, cannot be deleted) */
      var chkCell = rid
        ? '<td class="fin326-chk-col">' +
            '<input type="checkbox" class="fin326-rchk" onclick="event.stopPropagation()"' +
            ' onchange="fin326ToggleRow(\'fluxo\',\'' + _esc329(rid) + '\',this)">' +
          '</td>'
        : '<td class="fin326-chk-col"></td>';

      /* Delete button — lançamentos only, single-quoted ID → valid HTML */
      var delBtn = rid
        ? '<button onclick="fin329Delete(\'' + _esc329(rid) + '\')"' +
          ' style="background:none;border:none;cursor:pointer;color:var(--navy-faint);' +
          'font-size:0.9rem;padding:0 4px;line-height:1;" title="Excluir">\u00d7</button>'
        : '';

      tr.innerHTML =
        chkCell +
        '<td style="white-space:nowrap;">'                                          + _dl329(it.date)      + '</td>' +
        '<td>'                                                                       + _esc329(it.desc)     + '</td>' +
        '<td><span style="font-size:0.72rem;color:var(--navy-soft);">'              + _esc329(it.categoria) + '</span></td>' +
        '<td>'                                                                       + _esc329(it.forn)     + '</td>' +
        '<td><span style="font-family:monospace;font-size:0.78rem;">'               + _esc329(it.ref)      + '</span></td>' +
        '<td style="text-align:right;" class="' + amtCls + '">' + sign + _fmtBRL329(it.brl) + '</td>' +
        '<td>'                                                                       + badge                + '</td>' +
        '<td>'                                                                       + delBtn               + '</td>';

      tbody.appendChild(tr);
    });

    _setupDrag329('fluxo', tbody);
    _updateBulk329('fluxo');
  };

  /* ══ §7. finRenderLancamentos — FULL REPLACEMENT ══════════════════════════ */
  window.finRenderLancamentos = function () {
    _injectChkTh329('lanc');

    var panel = document.getElementById('fin-panel-lancamentos');
    if (panel) {
      var sd = panel.querySelector('[style*="overflow-x"]');
      if (sd) _ensureBulk329('lanc', sd.parentNode);
    }

    var tbody = document.getElementById('fin-lanc-body');
    var empty = document.getElementById('fin-lanc-empty');
    if (!tbody) return;

    var items = _loadGlobal329();
    var today = _today329();

    /* ── Category filter ── */
    var lBtn = document.querySelector('.fin-filter-btn[data-lcat].active');
    var lf   = lBtn ? lBtn.dataset.lcat : 'all';
    if (lf === 'saida')       items = items.filter(function (it) { return it.tipo === 'saida'; });
    if (lf === 'entrada')     items = items.filter(function (it) { return it.tipo === 'entrada'; });
    if (lf === 'fixas')       items = items.filter(function (it) { return (it.categoria || '').startsWith('Fixas'); });
    if (lf === 'variaveis')   items = items.filter(function (it) { return (it.categoria || '').startsWith('Vari\u00e1veis'); });
    if (lf === 'pendentes')   items = items.filter(function (it) { return it.pago !== 'pago'; });
    if (lf === 'recorrentes') items = items.filter(function (it) { return !!it.recorrente; });

    items.sort(function (a, b) { return (a.vencimento || '').localeCompare(b.vencimento || ''); });

    _clearSel329('lanc');
    tbody.innerHTML = '';

    if (!items.length) {
      if (empty) empty.style.display = '';
      _updateBulk329('lanc');
      return;
    }
    if (empty) empty.style.display = 'none';

    items.forEach(function (it) {
      var amtCls = it.tipo === 'entrada' ? 'fin-amount-entrada' : 'fin-amount-saida';
      var sign   = it.tipo === 'entrada' ? '+' : '\u2212';
      var badge  = _badgeFull329(it);
      var rid    = it.id || '';

      var recurLabel = it.recorrente
        ? '<span style="background:rgba(59,130,246,0.1);color:#1e40af;' +
          'border:1px solid rgba(59,130,246,0.2);border-radius:4px;' +
          'padding:1px 6px;font-size:0.6rem;font-weight:700;">Todo dia ' +
          _esc329(it.recurDia || '?') + '</span>'
        : '\u2014';

      /* Pago toggle — single-quoted ID → valid HTML */
      var pagoToggle = rid
        ? '<button onclick="finTogglePago(\'' + _esc329(rid) + '\')"' +
          ' style="background:none;border:none;cursor:pointer;font-size:0.85rem;' +
          'padding:0 2px;" title="Alternar status">' +
          (it.pago === 'pago' ? '\u2705' : '\u2b1c') + '</button>'
        : '';

      /* Edit + Delete — single-quoted IDs */
      var actBtns = rid
        ? '<button onclick="fin326OpenEdit(\'lanc\',null,\'' + _esc329(rid) + '\')"' +
          ' style="background:none;border:1px solid var(--border);border-radius:4px;' +
          'cursor:pointer;font-size:0.7rem;padding:2px 7px;color:var(--navy-soft);' +
          'margin-right:3px;" title="Editar">&#9999;</button>' +
          '<button onclick="fin329Delete(\'' + _esc329(rid) + '\')"' +
          ' style="background:none;border:none;cursor:pointer;color:var(--navy-faint);' +
          'font-size:0.9rem;padding:0 4px;line-height:1;" title="Apagar">&#215;</button>'
        : '';

      var tr = document.createElement('tr');
      if (rid) tr.dataset.fin326k = rid;

      tr.innerHTML =
        '<td class="fin326-chk-col">' + (rid
          ? '<input type="checkbox" class="fin326-rchk" onclick="event.stopPropagation()"' +
            ' onchange="fin326ToggleRow(\'lanc\',\'' + _esc329(rid) + '\',this)">'
          : '') + '</td>' +
        '<td style="white-space:nowrap;">'                                         + _dl329(it.vencimento) + '</td>' +
        '<td>' + _esc329(it.descricao) +
          (it.nota
            ? '<div style="font-size:0.68rem;color:var(--navy-faint);">' + _esc329(it.nota) + '</div>'
            : '') + '</td>' +
        '<td><span style="font-size:0.72rem;color:var(--navy-soft);">'            + _esc329(it.categoria || '\u2014') + '</span></td>' +
        '<td>'                                                                      + _esc329(it.fornecedor || '\u2014') + '</td>' +
        '<td>'                                                                      + recurLabel + '</td>' +
        '<td style="text-align:right;" class="' + amtCls + '">' + sign + _fmtBRL329(_brlOf329(it)) + '</td>' +
        '<td>'                                                                      + badge + '&nbsp;' + pagoToggle + '</td>' +
        '<td style="white-space:nowrap;">'                                         + actBtns + '</td>';

      tbody.appendChild(tr);
    });

    _setupDrag329('lanc', tbody);
    _updateBulk329('lanc');
  };

  console.log('[Patch v3.29] finRenderFluxo + finRenderLancamentos fully replaced.',
    'Checkboxes, select-all, drag-select, delete, and edit all fixed.',
    'Single-quoted IDs in onclick prevent HTML attribute breakage.');

})(); // end Patch v3.29

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════════
   PATCH v3.30 — Unified Supplier Linkage + Clickable Fornecedor Detail View
   ─────────────────────────────────────────────────────────────────────────────

   CURRENT LOGIC CHAIN (found in audit):
     • Fornecedores DB: expatur_fornecedores → nome-only identification (no id)
     • CC rows: mc-forn-${rid} option.text = f.nome, saved as { forn: supplierName }
     • Finance sync: fornecedor = supplierName (free-text, no stable id)
     • source_id = 'costcalc_line__dossierId__rid' (stable, deterministic)
     • v3.17 adds linked_leg_* metadata to finance rows after sync
     • v3.24 adds linked_pnr via _propagatePnr324() after billet save
     • v3.14 adds programme, volume_miles, cpm_brl, taxas_brl to finance rows
     • No supplier detail view — clicking opens edit modal only

   GAPS FOUND:
     1. No stable fornecedor.id — identity only by exact name match
     2. forn_id not stored in CC row state or finance rows
     3. No clickable supplier detail / master-detail flow
     4. _ensureSupplierExists auto-creates with no id and minimal data

   THIS PATCH:
     §1. Migrate existing fornecedores → add stable id field
     §2. Wrap fornSave → id guaranteed on every create/update
     §3. Wrap dossFinSyncFromTarification → enrich expense rows with fornecedor_id
     §4. Override fornRender → data attributes + event delegation → click = detail
     §5. openFornDetails330(idOrName) + renderFornDetails330(forn)
         – Section A: master data
         – Section B: linked CC / Tarification rows
         – Section C: other Finance / Despesas rows
         – Section D: operational data (trecho / PNR / flight)
         – Section E: summary totals (at top)

   Guard: window._v330FornDetails
   ══════════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v330FornDetails) return;
  window._v330FornDetails = true;

  /* ══ §0. CONSTANTS ═══════════════════════════════════════════════════════ */
  var _FKEY330 = 'expatur_fornecedores';
  var _GFIN330 = 'expatur_financeiro_lancamentos';

  /* ══ §1. STABLE ID HELPERS + MIGRATION ══════════════════════════════════ */

  function _uid330() {
    return 'forn_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7);
  }
  function _normName330(s) {
    return (s || '').trim().toLowerCase().replace(/\s+/g, ' ');
  }
  function _loadForns330() {
    try { return JSON.parse(localStorage.getItem(_FKEY330) || '[]'); } catch (e) { return []; }
  }
  function _saveForns330(arr) {
    try { localStorage.setItem(_FKEY330, JSON.stringify(arr)); } catch (e) {}
  }
  function _loadGlobalFin330() {
    try { return JSON.parse(localStorage.getItem(_GFIN330) || '[]'); } catch (e) { return []; }
  }

  /* One-time migration: give every existing fornecedor a stable id */
  (function _migrate330() {
    try {
      var forns = _loadForns330();
      var changed = false;
      var ts = Date.now();
      forns = forns.map(function (f, i) {
        if (f.id) return f;
        changed = true;
        return Object.assign({}, f, { id: 'forn_' + (ts + i) + '_' + Math.random().toString(36).slice(2, 6) });
      });
      if (changed) _saveForns330(forns);
    } catch (e) { console.warn('[v3.30] migration error', e); }
  }());

  /* ══ §2. WRAP fornSave — guarantee id on every create / update ═══════════ */
  if (typeof window.fornSave === 'function' && !window._v330FornSaveWrap) {
    window._v330FornSaveWrap = true;
    var _prevFornSave330 = window.fornSave;
    window.fornSave = function () {
      _prevFornSave330.apply(this, arguments);
      /* Ensure the record that was just saved has an id */
      try {
        var forns = _loadForns330();
        var changed = false;
        var ts = Date.now();
        forns = forns.map(function (f, i) {
          if (f.id) return f;
          changed = true;
          return Object.assign({}, f, { id: 'forn_' + (ts + i) + '_' + Math.random().toString(36).slice(2, 6) });
        });
        if (changed) _saveForns330(forns);
      } catch (e) {}
    };
  }

  /* ══ §3. FINANCE SYNC ENRICHMENT — add fornecedor_id ════════════════════
     Wraps dossFinSyncFromTarification.  After the full existing chain runs
     (v3.9 → v3.13 → v3.14 → v3.17 → v3.18 → v3.24 → v3.27 → v3.30), we
     scan the global lancamentos store and patch missing fornecedor_id fields
     by normalized-name lookup.                                               */
  if (typeof window.dossFinSyncFromTarification === 'function' && !window._v330SyncWrap) {
    window._v330SyncWrap = true;
    var _prev330Sync = window.dossFinSyncFromTarification;
    window.dossFinSyncFromTarification = function () {
      _prev330Sync.apply(this, arguments);
      /* 500 ms after the chain completes — all earlier patches have had time to write */
      setTimeout(function () {
        try {
          var forns = _loadForns330();
          var nameToId = {};
          forns.forEach(function (f) { if (f.id) nameToId[_normName330(f.nome)] = f.id; });

          var rows = _loadGlobalFin330();
          var changed = false;
          rows = rows.map(function (r) {
            if (r.fornecedor_id) return r;
            var fid = nameToId[_normName330(r.fornecedor || '')];
            if (!fid) return r;
            changed = true;
            return Object.assign({}, r, { fornecedor_id: fid });
          });
          if (changed) localStorage.setItem(_GFIN330, JSON.stringify(rows));
        } catch (e) { console.warn('[v3.30] enrich fornecedor_id error', e); }
      }, 500);
    };
  }

  /* ══ §4. LOOKUP HELPERS ══════════════════════════════════════════════════ */

  /* Find a fornecedor by its id or by normalized name */
  function _findForn330(idOrName) {
    if (!idOrName) return null;
    var forns = _loadForns330();
    /* "name:..." prefix is the fallback when no id was available at render time */
    if (String(idOrName).indexOf('name:') === 0) {
      var rawName = idOrName.slice(5);
      var n = _normName330(rawName);
      return forns.filter(function (f) { return _normName330(f.nome) === n; })[0] || null;
    }
    var byId = forns.filter(function (f) { return f.id === idOrName; })[0];
    if (byId) return byId;
    var n2 = _normName330(idOrName);
    return forns.filter(function (f) { return _normName330(f.nome) === n2; })[0] || null;
  }

  /* Collect all finance rows linked to a supplier — global + per-dossier, deduped */
  function _getAllFornRows330(forn) {
    if (!forn) return [];
    var fornId   = forn.id || '';
    var normNome = _normName330(forn.nome);

    function matches(r) {
      if (fornId && r.fornecedor_id && r.fornecedor_id === fornId) return true;
      return _normName330(r.fornecedor || '') === normNome;
    }

    /* Global store first */
    var globalRows = _loadGlobalFin330().filter(matches);
    var seen = {};
    globalRows.forEach(function (r) { if (r.source_id) seen[r.source_id] = true; });

    /* Per-dossier stores (for rows not mirrored to global) */
    var extra = [];
    try {
      Object.keys(localStorage).forEach(function (k) {
        if (k.indexOf('expatur_doss_finance_') !== 0) return;
        var data = null;
        try { data = JSON.parse(localStorage.getItem(k) || 'null'); } catch (e) {}
        if (!data || !Array.isArray(data.expenses)) return;
        data.expenses.forEach(function (e) {
          if (!matches(e)) return;
          if (e.source_id && seen[e.source_id]) return; /* already in global */
          extra.push(e);
          if (e.source_id) seen[e.source_id] = true;
        });
      });
    } catch (e) {}

    return globalRows.concat(extra);
  }

  /* ══ §5. OVERRIDE fornRender — click → detail view ══════════════════════ */
  if (typeof window.fornRender === 'function' && !window._v330FornRenderWrap) {
    window._v330FornRenderWrap = true;
    var _prevFornRender330 = window.fornRender;

    window.fornRender = function () {
      _prevFornRender330.apply(this, arguments);

      var tbody = document.getElementById('forn-table-body');
      if (!tbody) return;

      /* Replicate the same filter the original uses to get the same ordering */
      var q    = ((document.getElementById('forn-search')      || {}).value || '').toLowerCase();
      var tipo = ((document.getElementById('forn-filter-tipo') || {}).value || '');
      var data = _loadForns330();
      if (q || tipo) {
        data = data.filter(function (f) {
          var m = !q
            || (f.nome    || '').toLowerCase().indexOf(q) > -1
            || (f.pais    || '').toLowerCase().indexOf(q) > -1
            || (f.cnpj    || '').toLowerCase().indexOf(q) > -1
            || (f.contato || '').toLowerCase().indexOf(q) > -1
            || (f.email   || '').toLowerCase().indexOf(q) > -1;
          return m && (!tipo || f.tipo === tipo);
        });
      }

      /* Tag each tr with the supplier id */
      tbody.querySelectorAll('tr').forEach(function (tr, i) {
        if (tr.querySelector('.db-empty')) return;
        var forn = data[i];
        if (!forn) return;
        tr.dataset.forn330 = forn.id || ('name:' + forn.nome);
        tr.style.cursor = 'pointer';
        tr.title = 'Clique para ver o perfil de ' + forn.nome;
      });

      /* Event delegation on tbody (added once, survives innerHTML resets on children) */
      if (!tbody.dataset.forn330Click) {
        tbody.dataset.forn330Click = '1';
        tbody.addEventListener('click', function (e) {
          if (e.target.closest('.db-action-btn')) return; /* let edit / delete through */
          var tr = e.target.closest('tr[data-forn330]');
          if (!tr || !tr.dataset.forn330) return;
          window.openFornDetails330(tr.dataset.forn330);
        });
      }
    };
  }

  /* ══ §6. SUPPLIER DETAIL PANEL ═══════════════════════════════════════════ */

  /* ── Build overlay DOM once ────────────────────────────────────────────── */
  function _buildDetailPanel330() {
    if (document.getElementById('forn330-overlay')) return;

    var css = document.createElement('style');
    css.id  = 'forn330-styles';
    css.textContent = [
      '#forn330-overlay{display:none;position:fixed;inset:0;z-index:9500;',
      '  background:rgba(6,32,59,0.55);align-items:flex-start;justify-content:center;',
      '  overflow-y:auto;padding:2rem 1rem;}',
      '#forn330-overlay.open{display:flex;}',
      '#forn330-panel{background:#fff;border-radius:12px;',
      '  box-shadow:0 16px 72px rgba(0,0,0,0.26);width:100%;max-width:1020px;',
      '  margin:0 auto;overflow:hidden;}',
      '#forn330-hdr{display:flex;align-items:center;justify-content:space-between;',
      '  padding:1.1rem 1.5rem;background:var(--navy,#06203b);color:#fff;gap:1rem;}',
      '#forn330-hdr-text{flex:1;min-width:0;}',
      '#forn330-title{font-size:1.05rem;font-weight:700;letter-spacing:0.02em;}',
      '#forn330-subtitle{font-size:0.7rem;color:rgba(255,255,255,0.6);margin-top:2px;}',
      '#forn330-hdr-actions{display:flex;gap:0.5rem;flex-shrink:0;}',
      '.forn330-hdr-btn{background:rgba(255,255,255,0.14);border:1px solid rgba(255,255,255,0.2);',
      '  color:#fff;border-radius:5px;cursor:pointer;font-size:0.65rem;font-weight:700;',
      '  letter-spacing:0.07em;text-transform:uppercase;padding:4px 12px;transition:background .12s;}',
      '.forn330-hdr-btn:hover{background:rgba(255,255,255,0.22);}',
      '.forn330-close-btn{background:rgba(255,255,255,0.12);border:none;color:#fff;',
      '  border-radius:50%;width:32px;height:32px;cursor:pointer;font-size:1.1rem;',
      '  display:flex;align-items:center;justify-content:center;flex-shrink:0;}',
      '.forn330-close-btn:hover{background:rgba(255,255,255,0.22);}',
      '#forn330-body{padding:1.4rem 1.5rem;}',
      '.forn330-kpi-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));',
      '  gap:0.7rem;margin-bottom:1.5rem;}',
      '.forn330-kpi{background:rgba(6,32,59,0.035);border:1px solid rgba(6,32,59,0.08);',
      '  border-radius:8px;padding:0.7rem 0.85rem;}',
      '.forn330-kpi-label{font-size:0.56rem;font-weight:700;letter-spacing:0.1em;',
      '  text-transform:uppercase;color:var(--navy-soft,#3a5068);margin-bottom:0.2rem;}',
      '.forn330-kpi-val{font-size:1rem;font-weight:700;color:var(--navy,#06203b);}',
      '.forn330-sect{margin-bottom:1.4rem;}',
      '.forn330-sect-title{font-size:0.6rem;font-weight:700;letter-spacing:0.12em;',
      '  text-transform:uppercase;color:var(--navy-soft,#3a5068);margin-bottom:0.6rem;',
      '  padding-bottom:0.35rem;border-bottom:1px solid rgba(6,32,59,0.08);}',
      '.forn330-kv{display:flex;gap:0.5rem;align-items:baseline;margin-bottom:0.38rem;}',
      '.forn330-kv-l{font-size:0.58rem;font-weight:700;letter-spacing:0.08em;',
      '  text-transform:uppercase;color:var(--navy-soft,#3a5068);min-width:110px;flex-shrink:0;}',
      '.forn330-kv-v{font-size:0.76rem;color:var(--navy,#06203b);}',
      '.forn330-table{width:100%;border-collapse:collapse;font-size:0.7rem;}',
      '.forn330-table th{text-align:left;padding:4px 8px;color:var(--navy-soft,#3a5068);',
      '  font-weight:700;font-size:0.58rem;letter-spacing:0.08em;text-transform:uppercase;',
      '  border-bottom:1px solid rgba(6,32,59,0.1);}',
      '.forn330-table td{padding:5px 8px;border-bottom:1px solid rgba(6,32,59,0.05);',
      '  vertical-align:top;}',
      '.forn330-table tr:last-child td{border-bottom:none;}',
      '.forn330-empty{color:var(--navy-faint,#8899aa);font-style:italic;font-size:0.71rem;padding:0.5rem 0;}',
      '.forn330-badge-paid{background:#dcfce7;color:#15803d;border:1px solid #bbf7d0;',
      '  border-radius:4px;padding:1px 7px;font-size:0.62rem;font-weight:700;}',
      '.forn330-badge-pend{background:#fee2e2;color:#b91c1c;border:1px solid #fca5a5;',
      '  border-radius:4px;padding:1px 7px;font-size:0.62rem;font-weight:700;}',
      '.forn330-badge-part{background:#fef9c3;color:#a16207;border:1px solid #fde68a;',
      '  border-radius:4px;padding:1px 7px;font-size:0.62rem;font-weight:700;}',
      '.forn330-op-grid{display:grid;grid-template-columns:1fr 1fr;gap:1.2rem;}'
    ].join('');
    document.head.appendChild(css);

    var ov = document.createElement('div');
    ov.id  = 'forn330-overlay';
    ov.innerHTML =
      '<div id="forn330-panel">' +
        '<div id="forn330-hdr">' +
          '<div id="forn330-hdr-text">' +
            '<div id="forn330-title"></div>' +
            '<div id="forn330-subtitle"></div>' +
          '</div>' +
          '<div id="forn330-hdr-actions">' +
            '<button class="forn330-hdr-btn" id="forn330-edit-btn" onclick="window._forn330EditCurrent()">✏ Editar</button>' +
            '<button class="forn330-hdr-btn" id="forn330-sync-btn" onclick="window._forn330Sync()">↻ Sincronizar</button>' +
          '</div>' +
          '<button class="forn330-close-btn" onclick="closeFornDetails330()">&#215;</button>' +
        '</div>' +
        '<div id="forn330-body"></div>' +
      '</div>';
    ov.addEventListener('click', function (e) { if (e.target === ov) closeFornDetails330(); });
    document.body.appendChild(ov);

    /* Escape key closes the panel */
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') {
        var ov2 = document.getElementById('forn330-overlay');
        if (ov2 && ov2.classList.contains('open')) closeFornDetails330();
      }
    });
  }

  /* ── Formatting helpers ────────────────────────────────────────────────── */
  function _esc330(s) {
    return String(s == null ? '' : s)
      .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function _fmtBRL330(v) {
    var n = parseFloat(v) || 0;
    return 'R$\u00a0' + n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  function _dl330(d) {
    if (!d) return '\u2014';
    var p = d.split('-');
    return p.length === 3 ? p[2]+'/'+p[1]+'/'+p[0] : d;
  }
  function _badge330(pago) {
    var p = (pago || '').toLowerCase();
    if (p === 'pago' || p === 'paid')
      return '<span class="forn330-badge-paid">Pago</span>';
    if (p === 'partial' || p === 'parcial')
      return '<span class="forn330-badge-part">Parcial</span>';
    return '<span class="forn330-badge-pend">Pendente</span>';
  }
  function _kv330(label, value) {
    return '<div class="forn330-kv">' +
      '<span class="forn330-kv-l">' + label + '</span>' +
      '<span class="forn330-kv-v">' + (value || '\u2014') + '</span>' +
      '</div>';
  }
  function _sect330(title, content) {
    return '<div class="forn330-sect">' +
      '<div class="forn330-sect-title">' + title + '</div>' +
      content +
      '</div>';
  }
  function _tbl330(heads, rowsHtml) {
    var empty = '<tr><td colspan="' + heads.length + '" class="forn330-empty">Nenhum registo encontrado.</td></tr>';
    return '<div style="overflow-x:auto;">' +
      '<table class="forn330-table"><thead><tr>' +
        heads.map(function (h) { return '<th>' + h + '</th>'; }).join('') +
      '</tr></thead><tbody>' + (rowsHtml || empty) + '</tbody></table></div>';
  }

  /* ── Current fornecedor context (for header buttons) ────────────────────── */
  var _currentForn330 = null;

  window._forn330EditCurrent = function () {
    if (!_currentForn330) return;
    var forns = _loadForns330();
    var idx   = forns.findIndex(function (f) { return f.id === _currentForn330.id; });
    if (idx < 0) return;
    closeFornDetails330();
    /* Clear filters so fornOpen(i) maps correctly (i = full-array index) */
    setTimeout(function () {
      var sEl = document.getElementById('forn-search');
      var tEl = document.getElementById('forn-filter-tipo');
      if (sEl) sEl.value = '';
      if (tEl) tEl.value = '';
      if (typeof window.fornRender === 'function') window.fornRender();
      if (typeof window.fornOpen  === 'function') window.fornOpen(idx);
    }, 80);
  };

  window._forn330Sync = function () {
    if (typeof window.dossFinSyncFromTarification === 'function') {
      window.dossFinSyncFromTarification();
      if (typeof toast === 'function') toast('Sincronizando…', 'info');
      /* Re-render detail after sync completes */
      setTimeout(function () {
        if (_currentForn330) window.openFornDetails330(_currentForn330.id || _currentForn330.nome);
      }, 900);
    } else {
      if (typeof toast === 'function') toast('Sincronização não disponível', 'error');
    }
  };

  /* ── Main entry points ──────────────────────────────────────────────────── */
  window.openFornDetails330 = function (idOrName) {
    var forn = _findForn330(idOrName);
    if (!forn) {
      if (typeof toast === 'function') toast('Fornecedor não encontrado', 'error');
      return;
    }
    _buildDetailPanel330();
    _currentForn330 = forn;
    _renderFornDetails330(forn);
    var ov = document.getElementById('forn330-overlay');
    if (ov) ov.classList.add('open');
  };

  window.closeFornDetails330 = function () {
    var ov = document.getElementById('forn330-overlay');
    if (ov) ov.classList.remove('open');
  };

  /* ── Core renderer ──────────────────────────────────────────────────────── */
  function _renderFornDetails330(forn) {
    var titleEl = document.getElementById('forn330-title');
    var subtEl  = document.getElementById('forn330-subtitle');
    var bodyEl  = document.getElementById('forn330-body');
    if (!titleEl || !bodyEl) return;

    titleEl.textContent = forn.nome || '(sem nome)';
    subtEl.textContent  = [forn.tipo, forn.pais].filter(Boolean).join(' \u00b7 ');

    /* ─ Collect linked rows ─────────────────────────────────────────────── */
    var allRows   = _getAllFornRows330(forn);
    var ccRows    = allRows.filter(function (r) { return r.source_type === 'cost_calculator_line'; });
    var otherRows = allRows.filter(function (r) { return r.source_type !== 'cost_calculator_line'; });

    /* ─ Summary totals ──────────────────────────────────────────────────── */
    var totalBRL = 0, paidBRL = 0, pendBRL = 0;
    var dossierSet = {};
    allRows.forEach(function (r) {
      var a = parseFloat(r.brl_amount || r.amount || r.valor || 0) || 0;
      totalBRL += a;
      var p = (r.pago || r.status || '').toLowerCase();
      if (p === 'pago' || p === 'paid') paidBRL += a; else pendBRL += a;
      if (r.dossierRef) dossierSet[r.dossierRef] = true;
    });

    /* ─ Section E: KPIs (shown at top) ─────────────────────────────────── */
    var kpiHtml = '<div class="forn330-kpi-grid">' +
      [
        { l: 'Total despesas',  v: _fmtBRL330(totalBRL), c: 'var(--navy,#06203b)' },
        { l: 'Total pago',      v: _fmtBRL330(paidBRL),  c: '#15803d' },
        { l: 'Total pendente',  v: _fmtBRL330(pendBRL),  c: '#b91c1c' },
        { l: 'Dossiers',        v: Object.keys(dossierSet).length, c: 'var(--navy,#06203b)' },
        { l: 'Linhas de custo', v: ccRows.length,  c: 'var(--navy,#06203b)' },
        { l: 'Lançamentos fin.',v: otherRows.length, c: 'var(--navy,#06203b)' }
      ].map(function (k) {
        return '<div class="forn330-kpi">' +
          '<div class="forn330-kpi-label">' + k.l + '</div>' +
          '<div class="forn330-kpi-val" style="color:' + k.c + ';">' + k.v + '</div>' +
          '</div>';
      }).join('') +
    '</div>';

    /* ─ Section A: Master data ──────────────────────────────────────────── */
    var masterHtml =
      '<div style="display:grid;grid-template-columns:1fr 1fr;gap:0.25rem 2.5rem;">' +
        _kv330('Tipo', forn.tipo
          ? '<span style="background:#e0e7ff;color:#3730a3;border-radius:4px;padding:1px 8px;font-size:0.62rem;font-weight:700;">'+_esc330(forn.tipo)+'</span>'
          : '') +
        _kv330('País', _esc330(forn.pais)) +
        _kv330('Pessoa', forn.tipoPessoa === 'PF' ? 'Física (CPF)' : 'Jurídica (CNPJ)') +
        _kv330(forn.tipoPessoa === 'PF' ? 'CPF' : 'CNPJ', _esc330(forn.cnpj)) +
        _kv330('Contato', _esc330(forn.contato)) +
        _kv330('Email', forn.email
          ? '<a href="mailto:'+_esc330(forn.email)+'" style="color:var(--navy);">'+_esc330(forn.email)+'</a>'
          : '') +
        _kv330('WhatsApp', forn.whatsapp
          ? '<a href="https://wa.me/'+forn.whatsapp.replace(/\D/g,'')+'" target="_blank" style="color:#25D366;font-weight:700;">'+_esc330(forn.whatsapp)+'</a>'
          : '') +
        _kv330('Website', forn.site
          ? '<a href="'+_esc330(forn.site)+'" target="_blank" style="color:var(--red,#c00);">'+_esc330(forn.site)+'</a>'
          : '') +
        (forn.notas
          ? '<div style="grid-column:1/-1;">' + _kv330('Notas', _esc330(forn.notas)) + '</div>'
          : '') +
        (forn.id
          ? '<div style="grid-column:1/-1;">' + _kv330('ID interno', '<span style="font-family:monospace;font-size:0.63rem;color:var(--navy-faint,#8899aa);">'+_esc330(forn.id)+'</span>') + '</div>'
          : '') +
      '</div>';

    /* ─ Section B: CC / Tarification rows ──────────────────────────────── */
    var ccHeads = ['Dossier','Emissor / Prog.','Trecho','PNR','Miles','CPM (R$)','Taxas (R$)','Total BRL','Status','Venc.'];
    var ccBodyHtml = ccRows.length ? ccRows.map(function (r) {
      var leg = '';
      if (r.linked_leg_dep || r.linked_leg_arr) {
        leg = (r.linked_leg_dep||'?') + ' \u2192 ' + (r.linked_leg_arr||'?');
        if (r.linked_leg_fn) leg += ' \u2014 ' + r.linked_leg_fn;
      } else if (r.linked_leg_label) {
        leg = r.linked_leg_label;
      }
      return '<tr>' +
        '<td style="font-family:monospace;font-weight:700;font-size:0.68rem;color:var(--red,#c00);">' + _esc330(r.dossierRef||'\u2014') + '</td>' +
        '<td>' + _esc330(r.programme || r.fornecedor || '\u2014') + '</td>' +
        '<td style="white-space:nowrap;font-size:0.68rem;">' + _esc330(leg || '\u2014') + '</td>' +
        '<td style="font-family:monospace;font-size:0.68rem;">' + _esc330(r.linked_pnr || '\u2014') + '</td>' +
        '<td style="text-align:right;">' + (r.volume_miles ? Number(r.volume_miles).toLocaleString('pt-BR') : '\u2014') + '</td>' +
        '<td style="text-align:right;">' + (r.cpm_brl   ? _fmtBRL330(r.cpm_brl)   : '\u2014') + '</td>' +
        '<td style="text-align:right;">' + (r.taxas_brl ? _fmtBRL330(r.taxas_brl) : '\u2014') + '</td>' +
        '<td style="text-align:right;font-weight:700;">' + _fmtBRL330(r.brl_amount||r.amount||0) + '</td>' +
        '<td>' + _badge330(r.pago || r.status) + '</td>' +
        '<td style="white-space:nowrap;">' + _dl330(r.vencimento) + '</td>' +
        '</tr>';
    }).join('') : '';

    /* ─ Section C: Other Finance / Despesas rows ────────────────────────── */
    var finHeads = ['Dossier','Descrição','Categoria','Total BRL','Status','Venc.','Trecho','PNR'];
    var finBodyHtml = otherRows.length ? otherRows.map(function (r) {
      var leg = r.linked_leg_label
        || ((r.linked_leg_dep || r.linked_leg_arr)
            ? (r.linked_leg_dep||'?') + ' \u2192 ' + (r.linked_leg_arr||'?')
            : '');
      return '<tr>' +
        '<td style="font-family:monospace;font-weight:700;font-size:0.68rem;color:var(--red,#c00);">' + _esc330(r.dossierRef||'\u2014') + '</td>' +
        '<td style="max-width:200px;word-break:break-word;">' + _esc330(r.descricao||r.description||'\u2014') + '</td>' +
        '<td style="font-size:0.67rem;color:var(--navy-soft,#3a5068);">' + _esc330(r.categoria||'\u2014') + '</td>' +
        '<td style="text-align:right;font-weight:700;">' + _fmtBRL330(r.brl_amount||r.amount||r.valor||0) + '</td>' +
        '<td>' + _badge330(r.pago || r.status) + '</td>' +
        '<td style="white-space:nowrap;">' + _dl330(r.vencimento) + '</td>' +
        '<td style="font-size:0.67rem;">' + _esc330(leg || '\u2014') + '</td>' +
        '<td style="font-family:monospace;font-size:0.68rem;">' + _esc330(r.linked_pnr || '\u2014') + '</td>' +
        '</tr>';
    }).join('') : '';

    /* ─ Section D: Operational data (Trecho + PNR + Flight) ────────────── */
    var pnrMap    = {}, trechoMap = {};
    allRows.forEach(function (r) {
      if (r.linked_pnr && r.linked_pnr !== '\u2014') pnrMap[r.linked_pnr] = true;
      var dep = r.linked_leg_dep, arr = r.linked_leg_arr;
      if (dep || arr) {
        var k = (dep||'?') + '\u2192' + (arr||'?');
        if (!trechoMap[k]) trechoMap[k] = {
          dep: dep, arr: arr,
          fn:      r.linked_leg_fn      || '',
          date:    r.linked_flight_date || '',
          airline: r.linked_airline_iata|| ''
        };
      }
    });
    var pnrs    = Object.keys(pnrMap);
    var trechos = Object.keys(trechoMap);
    var opHtml;
    if (pnrs.length || trechos.length) {
      opHtml = '<div class="forn330-op-grid">';
      if (pnrs.length) {
        opHtml += '<div>' +
          '<div style="font-size:0.6rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:var(--navy-soft,#3a5068);margin-bottom:0.4rem;">PNRs vinculados</div>' +
          pnrs.map(function (p) {
            return '<div style="font-family:monospace;font-size:0.84rem;font-weight:700;color:var(--navy,#06203b);margin-bottom:3px;">' + _esc330(p) + '</div>';
          }).join('') +
          '</div>';
      }
      if (trechos.length) {
        opHtml += '<div>' +
          '<div style="font-size:0.6rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:var(--navy-soft,#3a5068);margin-bottom:0.4rem;">Trechos operados</div>' +
          trechos.map(function (k) {
            var t = trechoMap[k];
            return '<div style="margin-bottom:6px;">' +
              '<strong style="font-size:0.8rem;">' + _esc330((t.dep||'?') + ' \u2192 ' + (t.arr||'?')) + '</strong>' +
              (t.fn      ? ' <span style="font-family:monospace;font-size:0.68rem;color:var(--navy-soft);">' + _esc330(t.fn) + '</span>' : '') +
              (t.airline ? ' <span style="background:#f0f9ff;color:#0369a1;border:1px solid #bae6fd;border-radius:3px;padding:0 5px;font-size:0.6rem;font-weight:700;">' + _esc330(t.airline) + '</span>' : '') +
              (t.date    ? '<br><span style="font-size:0.65rem;color:var(--navy-faint);">' + _dl330(t.date) + '</span>' : '') +
              '</div>';
          }).join('') +
          '</div>';
      }
      opHtml += '</div>';
    } else {
      opHtml = '<div class="forn330-empty">Nenhum dado operacional disponível. ' +
        'Certifique-se que as linhas do Cost Calculator foram sincronizadas e que o Billet/Tickets foi preenchido.</div>';
    }

    /* ─ Compose final HTML ────────────────────────────────────────────────── */
    bodyEl.innerHTML =
      kpiHtml +
      _sect330('A \u2014 Dados Cadastrais', masterHtml) +
      _sect330('B \u2014 Linhas de Custo (Tarification / Cost Calculator)',
        ccRows.length
          ? _tbl330(ccHeads, ccBodyHtml)
          : '<div class="forn330-empty">Nenhuma linha de custo vinculada. ' +
            'Selecione este fornecedor no Cost Calculator e sincronize com Finance.</div>') +
      (otherRows.length
        ? _sect330('C \u2014 Finance / Despesas (outros registos)', _tbl330(finHeads, finBodyHtml))
        : '') +
      _sect330('D \u2014 Dados Operacionais (Trecho / PNR / Voo)', opHtml);
  }

  console.log('[Patch v3.30] Fornecedor detail view active.',
    'Stable IDs migrated. Click any supplier row → detail panel.',
    'Sections: KPI summary, master data (A), CC rows (B), Finance rows (C), Operational (D).',
    'Finance rows enriched with fornecedor_id on next sync.');

})(); // end Patch v3.30

// ─────────────────────────────────────

/* ══════════════════════════════════════════════════════════════════════════════
   PATCH v3.31 — Unified Financeiro Row Selection & Robust Bulk Delete
   ─────────────────────────────────────────────────────────────────────────────
   Root causes fixed:

   A) SILENT DELETE FAILURE for recv / exp rows with empty dossierId
      Global lançamentos displayed in Recebimentos / Despesas tabs carry
      _dossierId: '' (set at line ~20590 by _getAll38).  When the user checks
      those rows and clicks "Apagar selecionadas", fin326BulkDelete calls the
      private _del326('recv','',rid) inside the v3.26 IIFE.
      _del326 calls _load326('') → localStorage.getItem('expatur_doss_finance_')
      → null → early return → item is never removed from storage.
      Same issue with fin326DeleteRow individual × buttons on such rows.

   B) HEADER GUARD STALE — _injectChkTh326 sets _hdr326[tbl+'_chk']=true once.
      If the table is ever reconstructed (e.g. a panel is removed/re-added),
      the guard blocks re-injection but the <th> is gone → no select-all checkbox.

   C) BULK BAR MISSING — _ensureBulk326 queries [style*="overflow-x"] to find
      the scroll container parent.  If no element has an *inline* overflow-x
      style, sd is null → bar created but never appended to DOM → _updateBulk326
      cannot find it → bar never shows.

   Fix strategy:
     • Replace fin326BulkDelete with _delRobust331 which handles ALL cases:
         – empty did  → delete from global expatur_financeiro_lancamentos
                        + scan all expatur_doss_finance_* as fallback
         – non-empty did → delete from per-dossier store
         – fluxo/lanc → always global store
     • Replace fin326DeleteRow with same robust logic
     • _fixHdrGuard331: DOM-aware guard check; resets flag if <th> is missing
     • _ensureBulkBar331: falls back to panel root when scroll-wrap not found
     • Wrap all 5 renderers (recv/exp/cred/fluxo/lanc) with pre/post hooks

   Guard: window._v331BulkFix
   Tabs updated: Recebimentos, Despesas, Créditos, Fluxo de Caixa, Lançamentos
   ══════════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v331BulkFix) return;
  window._v331BulkFix = true;

  /* ══ §1. STORAGE — robust, self-contained delete helpers ════════════════ */

  var _GKEY331 = 'expatur_financeiro_lancamentos';

  function _loadG331() {
    try { return JSON.parse(localStorage.getItem(_GKEY331) || '[]'); } catch(e) { return []; }
  }
  function _saveG331(arr) {
    try { localStorage.setItem(_GKEY331, JSON.stringify(arr)); } catch(e) {}
  }

  /* Remove rid from global lancamentos store */
  function _delGlobal331(rid) {
    var arr = _loadG331();
    var next = arr.filter(function(x) { return x.id !== rid; });
    if (next.length !== arr.length) _saveG331(next);
  }

  /* Remove rid from one per-dossier store */
  function _delDossier331(tbl, did, rid) {
    try {
      var k = 'expatur_doss_finance_' + did;
      var d = JSON.parse(localStorage.getItem(k) || 'null');
      if (!d) return;
      var field = tbl === 'recv' ? 'receivables' : tbl === 'exp' ? 'expenses' : 'credits';
      var arr = d[field];
      if (!Array.isArray(arr)) return;
      var next = arr.filter(function(x) { return x.id !== rid; });
      if (next.length !== arr.length) {
        d[field] = next;
        localStorage.setItem(k, JSON.stringify(d));
      }
    } catch(e) {}
  }

  /* Scan every expatur_doss_finance_* key (fallback when dossierId unknown) */
  function _delAllDossiers331(tbl, rid) {
    try {
      Object.keys(localStorage).forEach(function(k) {
        if (k.indexOf('expatur_doss_finance_') !== 0) return;
        var d = JSON.parse(localStorage.getItem(k) || 'null');
        if (!d) return;
        var field = tbl === 'recv' ? 'receivables' : tbl === 'exp' ? 'expenses' : 'credits';
        var arr = d[field];
        if (!Array.isArray(arr)) return;
        var next = arr.filter(function(x) { return x.id !== rid; });
        if (next.length !== arr.length) {
          d[field] = next;
          localStorage.setItem(k, JSON.stringify(d));
        }
      });
    } catch(e) {}
  }

  /*
   * _delRobust331(tbl, did, rid)
   *   tbl : 'recv'|'exp'|'cred'|'fluxo'|'lanc'
   *   did : dossierId — empty string / null for global items
   *   rid : item id
   *
   * Routing:
   *   fluxo / lanc     → global store only
   *   non-empty did    → per-dossier store
   *   empty / null did → global store + all dossier stores (belt-and-suspenders)
   */
  function _delRobust331(tbl, did, rid) {
    if (!rid) return;
    if (tbl === 'fluxo' || tbl === 'lanc') {
      _delGlobal331(rid);
      return;
    }
    if (did) {
      _delDossier331(tbl, did, rid);
    } else {
      /* Global row — dossierId is '' or null */
      _delGlobal331(rid);          /* removes from expatur_financeiro_lancamentos */
      _delAllDossiers331(tbl, rid); /* belt-and-suspenders: any per-dossier copy */
    }
  }

  /* ══ §2. REFRESH AFTER DELETE ═══════════════════════════════════════════ */

  function _refresh331(tbl) {
    var map = {
      recv:  'finRenderRecebimentos',
      exp:   'finRenderDespesas',
      cred:  'finRenderGlobalCredits',
      lanc:  'finRenderLancamentos',
      fluxo: 'finRenderFluxo'
    };
    if (map[tbl] && typeof window[map[tbl]] === 'function') {
      try { window[map[tbl]](); } catch(e) {}
    }
    if (typeof window.finRenderKPIs === 'function') {
      try { window.finRenderKPIs(); } catch(e) {}
    }
  }

  /* ══ §3. REPLACE fin326BulkDelete ════════════════════════════════════════
     The previous version called the private _del326() function inside v3.26,
     which silently failed on empty dossierId.  This replacement is fully
     self-contained using _delRobust331.                                      */

  window.fin326BulkDelete = function(tbl) {
    var sel = window._fin326_sel;
    if (!sel || !sel[tbl]) return;
    var keys = Object.keys(sel[tbl]);
    if (!keys.length) return;
    var n = keys.length;
    var plural = n !== 1;
    if (!confirm('Apagar ' + n + ' linha' + (plural ? 's' : '') +
        ' selecionada' + (plural ? 's' : '') + '?')) return;

    var isGlobal = (tbl === 'fluxo' || tbl === 'lanc');
    keys.forEach(function(k) {
      if (isGlobal) {
        _delRobust331(tbl, null, k);
      } else {
        var p = k.indexOf('|');
        var did = p >= 0 ? k.slice(0, p) : '';
        var rid = p >= 0 ? k.slice(p + 1) : k;
        _delRobust331(tbl, did, rid);
      }
    });

    sel[tbl] = {};
    _refresh331(tbl);
    if (typeof toast === 'function')
      toast(n + ' linha' + (plural ? 's' : '') + ' apagada' + (plural ? 's' : ''), 'info');
  };

  /* ══ §4. REPLACE fin326DeleteRow ═════════════════════════════════════════
     Individual × delete button on recv/exp/cred rows.  Same empty-did fix.  */

  window.fin326DeleteRow = function(tbl, did, rid) {
    if (!confirm('Apagar esta linha?')) return;
    _delRobust331(tbl, did, rid);
    /* Remove from current selection state so bulk count updates correctly */
    var sel = window._fin326_sel;
    if (sel && sel[tbl]) {
      var key = (did ? did : '') + '|' + rid;
      delete sel[tbl][key];
      /* Also try without pipe in case key format differs */
      delete sel[tbl][rid];
      if (typeof window._fin326_updateBulk === 'function') window._fin326_updateBulk(tbl);
    }
    _refresh331(tbl);
    if (typeof toast === 'function') toast('Linha apagada', 'info');
  };

  /* ══ §5. DOM-AWARE HEADER GUARD RESET ════════════════════════════════════
     _injectChkTh326 uses _hdr326[tbl+'_chk'] guard to avoid double-injection.
     If the <th> is removed from the DOM while the guard stays true, the
     select-all checkbox disappears permanently.  Before each render we check
     the DOM; if the th is absent despite the guard, we reset it.            */

  var _tbodyIds331 = {
    recv:'fin-recv-body', exp:'fin-exp-body', cred:'fin-cred-body',
    fluxo:'fin-fluxo-body', lanc:'fin-lanc-body'
  };

  function _fixHdrGuard331(tbl) {
    var hdr = window._fin326_hdr;
    if (!hdr || !hdr[tbl + '_chk']) return; /* guard not set → no problem */
    var tbody = document.getElementById(_tbodyIds331[tbl]);
    if (!tbody) return;
    var tblEl = tbody.closest('table');
    if (!tblEl) return;
    if (!tblEl.querySelector('thead .fin326-chk-col')) {
      /* th is missing despite guard being true → reset so it re-injects */
      delete hdr[tbl + '_chk'];
      delete hdr[tbl + '_act'];
    }
  }

  /* ══ §6. ROBUST BULK BAR PLACEMENT ═══════════════════════════════════════
     _ensureBulk326 queries panel.querySelector('[style*="overflow-x"]') to
     find the scroll container.  If no element carries that *inline* style
     the bar is created but never appended → invisible.  Here we fall back
     to the panel element itself.                                             */

  var _panelIds331 = {
    recv:'fin-panel-recebimentos', exp:'fin-panel-despesas',
    cred:'fin-panel-credits', fluxo:'fin-panel-fluxo', lanc:'fin-panel-lancamentos'
  };

  function _ensureBulkBar331(tbl) {
    /* Already in DOM — nothing to do */
    if (document.getElementById('fin326-bulk-' + tbl)) return;
    if (typeof window._fin326_ensureBulk !== 'function') return;
    var panel = document.getElementById(_panelIds331[tbl]);
    if (!panel) return;
    /* Try the inline-style scroll wrapper first (existing approach) */
    var scrollWrap = panel.querySelector('[style*="overflow-x"]');
    var parent = scrollWrap ? scrollWrap.parentNode : panel;
    window._fin326_ensureBulk(tbl, parent);
  }

  /* ══ §7. WRAP ALL 5 RENDERERS ════════════════════════════════════════════
     Pre-render  : fix stale header guard (so select-all th is always present)
     Post-render : ensure bulk bar is placed in DOM (robust fallback parent)  */

  var _renderFnMap331 = {
    recv:  'finRenderRecebimentos',
    exp:   'finRenderDespesas',
    cred:  'finRenderGlobalCredits',
    fluxo: 'finRenderFluxo',
    lanc:  'finRenderLancamentos'
  };

  Object.keys(_renderFnMap331).forEach(function(tbl) {
    var fnName = _renderFnMap331[tbl];
    var prev   = window[fnName];
    if (typeof prev !== 'function') return;
    window[fnName] = function() {
      _fixHdrGuard331(tbl);         /* reset guard if <th> was lost from DOM */
      prev.apply(this, arguments);  /* run the full underlying renderer       */
      _ensureBulkBar331(tbl);       /* ensure bulk bar is placed in DOM       */
    };
  });

  console.log(
    '[Patch v3.31] Robust bulk delete active for recv/exp/cred/fluxo/lanc.',
    'Fixed: empty-dossierId silent delete, stale header guard, bulk-bar placement.',
    'fin326BulkDelete + fin326DeleteRow fully replaced with self-contained versions.'
  );

})(); // end Patch v3.31

