/* ═══════════════════════════════════════════════════════════════════
   Patch v3.32 — Three consolidated fixes
   1. Ticketing autosave / localStorage persistence
   2. Notas Fiscais task — R.A.V brute field
   3. Fluxo de Caixa — filter pnl_total_cost duplicate rows
   ═══════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v332) return;
  window._v332 = true;

  /* ─────────────────────────────────────────────────────────────────
     §1. TICKETING AUTOSAVE
     Wrap quotingSwitch to save dossier + billet data before switching.
     Also wire a delegated listener on the panels host for continuous
     draft persistence on any panel input/change.
     ───────────────────────────────────────────────────────────────── */

  var _orig332QS = window.quotingSwitch;
  window.quotingSwitch = function (tab) {
    var id = localStorage.getItem('expatur_active_dossier') || '';
    if (id) {
      // Save dossier fields (Tarification, Client, Vols, Paiement sections)
      if (typeof _dossierSave === 'function') { try { _dossierSave(id); } catch (e) {} }
      // Save billet / ticket data
      if (typeof window.saveBilletData === 'function') { try { window.saveBilletData(); } catch (e) {} }
    }
    if (typeof _orig332QS === 'function') { _orig332QS.call(this, tab); }
  };

  // Panel draft auto-save removed (caused white-screen lag)

  /* ─────────────────────────────────────────────────────────────────
     §2. NOTAS FISCAIS — R.A.V BRUTE FIELD
     Injects an "R.A.V brute" input into the NF section whenever a
     Notas Fiscais task is opened.  Pre-fills from the task's stored
     ravBrutValue, falling back to the P&L snapshot (expatur_pnl_[ref]).
     Saves on every keystroke via window._nf332SaveRavBrut().
     ───────────────────────────────────────────────────────────────── */

  function _nf332GetPnlRef() {
    /* Try booking-ref input first (most reliable when dossier is open) */
    try {
      var refEl = document.getElementById('booking-ref');
      if (refEl && refEl.value && refEl.value.trim()) return refEl.value.trim();
    } catch(_) {}
    /* Fall back to active dossier in localStorage */
    var id = localStorage.getItem('expatur_active_dossier') || '';
    if (!id) return '';
    try {
      var d = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null');
      return (d && d.fields && d.fields['booking-ref']) || id;
    } catch (e) { return id; }
  }

  function _nf332InjectField(taskId) {
    var nfSection = document.getElementById('task-detail-nf-section');
    if (!nfSection || nfSection.style.display === 'none') return;

    // Find task (global _tasks array)
    var t = null;
    try { t = _tasks.find(function (x) { return x.id === taskId; }); } catch (e) {}
    if (!t || t.cat !== 'Notas Fiscais') return;

    // Inject wrapper once per modal open
    var wrap = document.getElementById('task-detail-rav-brut-wrap');
    if (!wrap) {
      wrap = document.createElement('div');
      wrap.id = 'task-detail-rav-brut-wrap';
      wrap.style.cssText = 'margin-top:0.75rem;padding-top:0.65rem;border-top:1px solid rgba(251,191,36,0.3);';
      wrap.innerHTML =
        '<div style="font-size:0.6rem;font-weight:700;letter-spacing:0.14em;text-transform:uppercase;' +
        'color:var(--navy);opacity:0.55;margin-bottom:0.45rem;">Valor de N.F (RAV bruta)</div>' +
        '<input id="task-detail-rav-brut" type="number" step="0.01" placeholder="0.00" ' +
        'readonly disabled ' +
        'style="width:100%;box-sizing:border-box;font-size:0.88rem;padding:0.45rem 0.7rem;' +
        'border:1px solid rgba(6,32,59,0.12);border-radius:5px;font-family:inherit;color:var(--navy);background:#f0f4fa;cursor:default;">';
      nfSection.appendChild(wrap);
    }

    // Pre-fill: task's stored ravBrutValue first, then PnL snapshot
    var inp = document.getElementById('task-detail-rav-brut');
    if (!inp) return;
    if (t.ravBrutValue != null && t.ravBrutValue !== '') {
      inp.value = t.ravBrutValue;
      return;
    }
    try {
      /* Try task's stored _pnlRef first (set at emission time), then active dossier */
      var ref = (t._pnlRef || '').trim() || _nf332GetPnlRef();
      if (ref) {
        var snap = JSON.parse(localStorage.getItem('expatur_pnl_' + ref) || 'null');
        if (snap && snap.ravBrut != null) {
          inp.value = parseFloat(snap.ravBrut).toFixed(2);
        }
      }
    } catch (e) {}
  }

  // Exposed: saves RAV field value to the task on every keystroke
  window._nf332SaveRavBrut = function () {
    var inp = document.getElementById('task-detail-rav-brut');
    if (!inp) return;
    var val = inp.value.trim();
    var taskId = _taskDetailId; // global var set by openTaskDetail
    if (!taskId) return;
    try {
      var t = _tasks.find(function (x) { return x.id === taskId; });
      if (t) {
        t.ravBrutValue = val;
        if (typeof _saveTasks === 'function') _saveTasks();
      }
    } catch (e) {}
  };

  // Wrap openTaskDetail to inject the RAV field after the modal is populated
  var _orig332OTD = window.openTaskDetail;
  window.openTaskDetail = function (taskId) {
    if (typeof _orig332OTD === 'function') _orig332OTD.call(this, taskId);
    try { _nf332InjectField(taskId); } catch (e) {}
  };

  // Patch _refreshNFBox to also surface ravBrutValue in the display box
  var _orig332RNF = window._refreshNFBox;
  window._refreshNFBox = function () {
    if (typeof _orig332RNF === 'function') _orig332RNF.call(this);
    try {
      var box = document.getElementById('nf-display-box');
      if (!box || box.style.display === 'none') return;
      var nfTask = _tasks.slice().reverse().find(function (t) {
        return t.cat === 'Notas Fiscais' && t.nfNumber;
      });
      if (nfTask && nfTask.ravBrutValue) {
        var ravEl = document.getElementById('nf-box-rav332');
        if (!ravEl) {
          ravEl = document.createElement('div');
          ravEl.id = 'nf-box-rav332';
          ravEl.style.cssText = 'font-size:0.72rem;color:var(--navy-faint);margin-top:3px;';
          box.appendChild(ravEl);
        }
        var num = parseFloat(nfTask.ravBrutValue);
        ravEl.textContent = 'R.A.V brute: R$\u00a0' + (isNaN(num)
          ? nfTask.ravBrutValue
          : num.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
      }
    } catch (e) {}
  };

  /* ─────────────────────────────────────────────────────────────────
     §3. FLUXO DE CAIXA — FILTER pnl_total_cost ROWS
     Wraps window.finRenderFluxo to temporarily suppress
     pnl_total_cost records from expatur_financeiro_lancamentos
     while the renderer runs, then restores the original data.
     Records are NOT deleted — they remain in the global store and
     are still visible in the Lançamentos tab.
     ───────────────────────────────────────────────────────────────── */

  var _GKEY332 = 'expatur_financeiro_lancamentos';
  var _prev332Fluxo = window.finRenderFluxo;
  if (typeof _prev332Fluxo === 'function') {
    window.finRenderFluxo = function () {
      var raw = null;
      try { raw = localStorage.getItem(_GKEY332); } catch (e) {}
      if (!raw) {
        return _prev332Fluxo.apply(this, arguments);
      }
      var filtered = raw;
      try {
        var arr = JSON.parse(raw);
        filtered = JSON.stringify(arr.filter(function (it) {
          if (it.source_type === 'pnl_total_cost') return false;
          if (it.source_id && it.source_id.indexOf('pnl_total_cost__') === 0) return false;
          return true;
        }));
      } catch (e) {}
      try { localStorage.setItem(_GKEY332, filtered); } catch (e) {}
      try {
        return _prev332Fluxo.apply(this, arguments);
      } finally {
        try { localStorage.setItem(_GKEY332, raw); } catch (e) {}
      }
    };
  }

  console.log(
    '[Patch v3.32] Loaded — Ticketing autosave | NF R.A.V brute field | Fluxo pnl_total_cost filter.'
  );

})(); // end Patch v3.32

