/* ═══════════════════════════════════════════════════════════════════
   Patch v3.33 — Volta Cancelada: correct vencimento = flight date + 1 calendar day
   Two-pronged fix:
   §1  Outer-wrap syncCostLinesToDossierFinanceExpensesAndSuppliers so that
       for VC lines cl.vencimento is pre-loaded from billet.legs[legIdx].depDate
       (v3.9 then adds exactly +1 calendar day to the right leg's date).
   §2  Post-fix wrapper around finAutoCreateCostPayments that repairs any VC
       records Path-1 wrote with finNextOpenDay (business-day skip) by
       rewriting their vencimento in expatur_financeiro_lancamentos to
       flightDate + 1 calendar day, using billet storage for authoritative dates.
   Normal (non-VC) rows are untouched.
   ═══════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v333) return;
  window._v333 = true;

  /* ── Private helpers ─────────────────────────────────────────────── */

  function _isVC333(forn) {
    if (!forn) return false;
    var u = forn.toUpperCase();
    return u.indexOf('VOLTA') >= 0 && u.indexOf('CANCEL') >= 0;
  }

  // Exactly +1 calendar day, no weekend skip
  function _calPlusOne333(dateISO) {
    if (!dateISO) return '';
    var d = new Date(dateISO.slice(0, 10) + 'T12:00:00');
    d.setDate(d.getDate() + 1);
    return d.toISOString().slice(0, 10);
  }

  // Billet legs for a ref → array of leg objects (authoritative source of depDate)
  function _billetLegs333(ref) {
    if (!ref) return [];
    var key = 'expatur_billet_' + ref.replace(/[^a-zA-Z0-9]/g, '_');
    try {
      var b = JSON.parse(localStorage.getItem(key) || 'null');
      return (b && Array.isArray(b.legs)) ? b.legs : [];
    } catch (e) { return []; }
  }

  // DOM fallback: collect dep-date-{n} values in order
  function _domLegDates333() {
    var dates = [];
    document.querySelectorAll('[id^="dep-date-"]').forEach(function (el) {
      dates.push(el.value || '');
    });
    return dates;
  }

  // Authoritative flight date for a specific leg: billet first, then DOM
  function _legFlightDate333(ref, legIdx) {
    var legs = _billetLegs333(ref);
    if (legs[legIdx] && legs[legIdx].depDate) return legs[legIdx].depDate;
    var dom = _domLegDates333();
    return (dom[legIdx] || '');
  }

  // Extract legIdx from a nota / source_id string for a VC record.
  // Path-1 nota format:  emission_{ref}_{legIdx}_Volta Cancelada
  // Path-2 source_id:    emission_{safeRef}_leg{legIdx}_{rid}_volta_cancelada
  function _extractLegIdx333(str) {
    if (!str) return 0;
    // Path-2 pattern: _leg{n}_
    var m1 = str.match(/_leg(\d+)_/i);
    if (m1) return parseInt(m1[1], 10);
    // Path-1 pattern: _{n}_Volta[ _]Cancelada (the last numeric segment before the forn name)
    var m2 = str.match(/_(\d+)_Volta[\s_]Cancelada/i);
    if (m2) return parseInt(m2[1], 10);
    return 0;
  }

  /* ── §1. Pre-fix: outer wrapper for syncCostLinesToDossierFinanceExpensesAndSuppliers ── */
  /*
     v3.9's inner wrapper computes:
       venc = _isVC ? _nextCalDay39(cl.vencimento || firstDep) : _nextBizDay39(bookedDate)
     So if we set cl.vencimento = billet.legs[legIdx].depDate BEFORE v3.9 runs,
     v3.9 will do _nextCalDay39(flightDate) = flightDate + 1 calendar day. Correct.
  */
  if (typeof window.syncCostLinesToDossierFinanceExpensesAndSuppliers === 'function'
      && !window._v333CostWrap) {
    window._v333CostWrap = true;
    var _prev333Sync = window.syncCostLinesToDossierFinanceExpensesAndSuppliers;

    window.syncCostLinesToDossierFinanceExpensesAndSuppliers = function (opts) {
      if (!opts || !opts.costLines || !opts.costLines.length) {
        return _prev333Sync.apply(this, arguments);
      }

      var ref    = opts.dossierRef || '';
      var hasVC  = opts.costLines.some(function (cl) { return _isVC333(cl.fornecedor); });
      if (!hasVC) return _prev333Sync.apply(this, arguments);

      var patched = opts.costLines.map(function (cl) {
        if (!_isVC333(cl.fornecedor)) return cl;
        var legIdx     = (cl.legIdx != null) ? parseInt(cl.legIdx, 10) : 0;
        var flightDate = _legFlightDate333(ref, legIdx);
        if (!flightDate) return cl; // no date found → leave unchanged, v3.9 uses its fallback
        // Set to the raw flight date; v3.9 will add +1 calendar day via _nextCalDay39
        return Object.assign({}, cl, { vencimento: flightDate });
      });

      return _prev333Sync.call(this, Object.assign({}, opts, { costLines: patched }));
    };
  }

  /* ── §2. Post-fix: repair Path-1 records written by finAutoCreateCostPayments ── */
  /*
     finAutoCreateCostPayments (original) uses finNextOpenDay(legDate) for VC rows,
     which skips weekends — e.g. flight on Friday → Monday instead of Saturday.
     After the original runs we scan expatur_financeiro_lancamentos for VC records
     belonging to this dossier that lack a source_id (Path-1 fingerprint) and
     rewrite their vencimento to flightDate + 1 calendar day.
  */
  function _vc333FixGlobalRecords(ref) {
    if (!ref) return;
    var KEY = 'expatur_financeiro_lancamentos';
    var items = [];
    try { items = JSON.parse(localStorage.getItem(KEY) || '[]'); } catch (e) { return; }

    var changed = false;
    items.forEach(function (it) {
      // Only Path-1 records (no source_id) for VC rows of this dossier
      if (!_isVC333(it.fornecedor)) return;
      if (it.dossierRef !== ref) return;
      if (it.source_id) return; // Path-2 record — already handled by §1

      var legIdx     = _extractLegIdx333(it.nota || '');
      var flightDate = _legFlightDate333(ref, legIdx);
      if (!flightDate) return;

      var correctVenc = _calPlusOne333(flightDate);
      if (it.vencimento !== correctVenc) {
        it.vencimento  = correctVenc;
        it.updatedAt   = new Date().toISOString();
        changed        = true;
      }
    });

    if (changed) {
      try { localStorage.setItem(KEY, JSON.stringify(items)); } catch (e) {}
    }
  }

  if (typeof window.finAutoCreateCostPayments === 'function' && !window._v333VCFix) {
    window._v333VCFix = true;
    var _prev333FACP = window.finAutoCreateCostPayments;

    window.finAutoCreateCostPayments = function () {
      var ref = (document.getElementById('booking-ref') || {}).value || '';
      _prev333FACP.apply(this, arguments);
      if (ref) { try { _vc333FixGlobalRecords(ref); } catch (e) {} }
    };
  }

  // Manual re-sync helper (callable from console if needed)
  window.v333FixVCVencimentos = function (ref) {
    ref = ref || (document.getElementById('booking-ref') || {}).value || '';
    if (!ref) { if (typeof toast === 'function') toast('Ref. obrigatória', 'error'); return; }
    _vc333FixGlobalRecords(ref);
    if (typeof toast === 'function') toast('Volta Cancelada: vencimentos corrigidos', 'success');
  };

  console.log(
    '[Patch v3.33] Volta Cancelada vencimento fix loaded — flight_date + 1 calendar day (billet leg date, no weekend skip).'
  );

})(); // end Patch v3.33

// ─────────────────────────────────────

/* ═══════════════════════════════════════════════════════════════════════════
   Patch v3.35 — Unified Task System
   · _tasksKey override for cross-dossier saves
   · window._uniOpenTask(taskId, ref) — universal editor opener
   · _uniRefreshAll335() — refresh all three task surfaces after any mutation
   · Booking detail: data-task-id attrs + delegated click → _uniOpenTask
   · Tarefas (v3.5): row click delegation → _uniOpenTask
   · Tasks index (main menu): row click delegation → _uniOpenTask
   · _diToggleTask + _v35ToggleDone: also refresh all views after toggle
   · Hover/pointer CSS for .bkd-task-row
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  if (window._v335) return;
  window._v335 = true;

  /* ── §1. _tasksKey override mechanism ────────────────────────────────── */
  // Store original _tasksKey (global function declaration → reachable via window)
  var _origTasksKey335 = window._tasksKey || (typeof _tasksKey === 'function' ? _tasksKey : null);

  // Override slot — set to a full localStorage key string (e.g. 'tasks_v2_REF') during
  // cross-dossier edit; null otherwise.
  window._uniTaskKeyOverride = null;

  // Replace _tasksKey globally so _saveTasks() writes to the right store
  window._tasksKey = function () {
    if (window._uniTaskKeyOverride) return window._uniTaskKeyOverride;
    if (typeof _origTasksKey335 === 'function') return _origTasksKey335();
    var ref = (document.getElementById('booking-ref') || {}).value || 'DEVIS';
    return 'tasks_v2_' + ref.trim();
  };

  /* ── §2. _uniRefreshAll335() ─────────────────────────────────────────── */
  function _uniRefreshAll335() {
    // Ticketing > Tâches panel (active dossier only)
    try { if (typeof renderTasks === 'function') renderTasks(); } catch (e) {}
    // Tarefas floating section (all dossiers)
    try { if (typeof window.tarefasRender === 'function') window.tarefasRender(); } catch (e) {}
    // Tasks index (main menu, all dossiers)
    try { if (typeof renderTasksIndex === 'function') renderTasksIndex(); } catch (e) {}
    // Booking detail — refresh task section if overlay is open
    var dosId = window._v335BkdActiveDossId;
    if (dosId) {
      var det = document.getElementById('bookings-detail');
      if (det && det.classList.contains('open')) {
        try { _v335RefreshBkdTasks(dosId); } catch (e) {}
      }
    }
  }
  window._uniRefreshAll = _uniRefreshAll335;

  // Refresh only the tasks section inside an open booking detail without
  // re-rendering the whole overlay (avoids flicker + lost scroll position).
  function _v335RefreshBkdTasks(dossierId) {
    var dosData;
    try { dosData = JSON.parse(localStorage.getItem('expatur_dossier_' + dossierId) || 'null'); } catch (e) {}
    if (!dosData) return;
    var ref = (dosData.fields && dosData.fields['booking-ref']) || '';
    if (!ref) return;
    var tasks = [];
    try { tasks = JSON.parse(localStorage.getItem('tasks_v2_' + ref.trim()) || '[]'); } catch (e) {}

    // Find the tasks section inside #bkd-body
    var body = document.getElementById('bkd-body');
    if (!body) return;
    // The tasks section is a .bkd-section whose title contains '✅'
    var sections = body.querySelectorAll('.bkd-section');
    var taskSection = null;
    for (var i = 0; i < sections.length; i++) {
      var titleEl = sections[i].querySelector('.bkd-section-title');
      if (titleEl && titleEl.textContent.indexOf('Tâches') >= 0) { taskSection = sections[i]; break; }
    }
    if (!taskSection) return;

    // Rebuild tasks HTML
    var sectionBody = taskSection.querySelector('.bkd-section-body');
    if (!sectionBody) return;

    if (!tasks.length) {
      sectionBody.innerHTML = '<p style="color:var(--navy-faint);font-style:italic;font-size:0.8rem;margin:0;">Aucune tâche associée à ce dossier.</p>';
      return;
    }

    var rowHtml = '';
    tasks.forEach(function (t, idx) {
      var text   = t.text || t.title || '(tâche)';
      var done   = !!t.done;
      var cat    = t.cat || t.category || '';
      var due    = t.dueDate || t.due || '';
      var dueStr = '';
      if (due) { try { dueStr = new Date(due).toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' }); } catch (e) { dueStr = due; } }
      rowHtml += '<div class="bkd-task-row v335-clickable"'
        + ' data-task-id="' + t.id + '"'
        + ' data-ref="' + (ref.trim().replace(/"/g, '&quot;')) + '"'
        + ' style="cursor:pointer;">'
        + '<span class="bkd-task-icon">'
          + (done ? '<span style="color:#16a34a;">&#10003;</span>' : '<span style="color:#d97706;">&#9675;</span>')
        + '</span>'
        + '<div style="flex:1;min-width:0;">'
          + '<div class="bkd-task-text' + (done ? ' done' : '') + '">'
            + String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
          + '</div>'
          + (cat
              ? '<div class="bkd-task-cat">'
                  + String(cat).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
                + '</div>'
              : '')
        + '</div>'
        + (dueStr ? '<span class="bkd-task-due">' + dueStr + '</span>' : '')
        + '</div>';
    });
    sectionBody.innerHTML = rowHtml;
    // Re-wire delegation since we replaced innerHTML
    _v335WireBkdClicks(body, ref.trim());
  }

  /* ── §3. _uniOpenTask(taskId, ref) ──────────────────────────────────── */
  window._uniOpenTask = function (taskId, ref) {
    var id = (typeof taskId === 'number') ? taskId : (isNaN(Number(taskId)) ? taskId : Number(taskId));
    var targetRef = (ref || '').trim();

    // Determine active dossier ref
    var activeRef = '';
    try {
      if (typeof _origTasksKey335 === 'function') {
        activeRef = _origTasksKey335().replace('tasks_v2_', '').trim();
      } else {
        activeRef = (document.getElementById('booking-ref') || {}).value || '';
      }
    } catch (e) {}

    if (!targetRef || targetRef === activeRef) {
      // Same dossier — call openTaskDetail directly
      if (typeof openTaskDetail === 'function') openTaskDetail(id);
      return;
    }

    // ── Cross-dossier path ──
    var crossKey = 'tasks_v2_' + targetRef;
    var crossTasks = [];
    try { crossTasks = JSON.parse(localStorage.getItem(crossKey) || '[]'); } catch (e) {}
    // Find the task (compare both as strings and numbers)
    var found = null;
    for (var i = 0; i < crossTasks.length; i++) {
      if (String(crossTasks[i].id) === String(id)) { found = crossTasks[i]; break; }
    }
    if (!found) {
      console.warn('[v3.35] _uniOpenTask: task', id, 'not found in', crossKey);
      return;
    }

    // Stash originals
    var origTasks335   = _tasks.slice();
    var origOverride   = window._uniTaskKeyOverride;
    var origClose335   = window.closeTaskDetail;
    var origDetailId   = typeof _taskDetailId !== 'undefined' ? _taskDetailId : null;

    // Determine active dossier key so we can restore it properly
    var activeKey = typeof _origTasksKey335 === 'function' ? _origTasksKey335() : null;

    // Inject cross-dossier tasks
    _tasks.length = 0;
    crossTasks.forEach(function (t) { _tasks.push(t); });
    window._uniTaskKeyOverride = crossKey;

    // Temporary closeTaskDetail that restores everything then calls _uniRefreshAll335
    window.closeTaskDetail = function () {
      // Read back (in case user toggled done / saved NF number)
      var saved = [];
      try { saved = JSON.parse(localStorage.getItem(crossKey) || '[]'); } catch (e) {}

      // Restore active dossier _tasks from localStorage
      _tasks.length = 0;
      if (activeKey) {
        try { JSON.parse(localStorage.getItem(activeKey) || '[]').forEach(function (t) { _tasks.push(t); }); } catch (e) {}
      } else {
        origTasks335.forEach(function (t) { _tasks.push(t); });
      }

      // Restore overrides
      window._uniTaskKeyOverride = origOverride;
      window.closeTaskDetail     = origClose335;

      // Close the modal (call original)
      if (typeof origClose335 === 'function') origClose335.call(this);

      // Refresh all views
      setTimeout(_uniRefreshAll335, 0);
    };

    // Open the modal with cross-dossier task (numeric id already resolved)
    if (typeof openTaskDetail === 'function') openTaskDetail(id);
  };

  /* ── §4. Booking detail: delegated click ─────────────────────────────── */
  // CSS: hover state for .bkd-task-row
  var _bkdStyle335 = document.createElement('style');
  _bkdStyle335.textContent =
    '.bkd-task-row.v335-clickable{transition:background 0.12s;}' +
    '.bkd-task-row.v335-clickable:hover{background:rgba(6,32,59,0.045);border-radius:5px;}';
  document.head.appendChild(_bkdStyle335);

  function _v335WireBkdClicks(bodyEl, ref) {
    if (!bodyEl) return;
    if (bodyEl._v335ClickHandler) bodyEl.removeEventListener('click', bodyEl._v335ClickHandler);
    bodyEl._v335ClickHandler = function (e) {
      var row = e.target.closest ? e.target.closest('.bkd-task-row') : null;
      if (!row) return;
      var tid  = row.getAttribute('data-task-id');
      var tref = row.getAttribute('data-ref') || ref || '';
      if (!tid) return;
      window._uniOpenTask(tid, tref);
    };
    bodyEl.addEventListener('click', bodyEl._v335ClickHandler);
  }

  // Track current booking detail dossier ID for _uniRefreshAll335
  window._v335BkdActiveDossId = null;

  // Wrap bookingsOpenDetail
  if (typeof window.bookingsOpenDetail === 'function' && !window._v335BkdWrap) {
    window._v335BkdWrap = true;
    var _origBkdOpen335 = window.bookingsOpenDetail;
    window.bookingsOpenDetail = function (dossierId) {
      window._v335BkdActiveDossId = dossierId;
      _origBkdOpen335.apply(this, arguments);

      // Post-process: add data attrs to .bkd-task-row elements
      var body = document.getElementById('bkd-body');
      if (!body) return;

      // Resolve ref
      var ref335 = (document.getElementById('bkd-ref') || {}).textContent || '';
      if (!ref335 || ref335 === '—') {
        var dd = null;
        try { dd = JSON.parse(localStorage.getItem('expatur_dossier_' + dossierId) || 'null'); } catch (e) {}
        ref335 = (dd && dd.fields && dd.fields['booking-ref']) || '';
      }

      // Load tasks to map by index
      var tasks335 = [];
      try { tasks335 = JSON.parse(localStorage.getItem('tasks_v2_' + ref335.trim()) || '[]'); } catch (e) {}

      // Assign data attrs by index
      var rows335 = body.querySelectorAll('.bkd-task-row');
      rows335.forEach(function (row, idx) {
        if (tasks335[idx]) {
          row.setAttribute('data-task-id', tasks335[idx].id);
          row.setAttribute('data-ref', ref335.trim());
          row.classList.add('v335-clickable');
          row.style.cursor = 'pointer';
        }
      });

      // Wire delegation
      _v335WireBkdClicks(body, ref335.trim());
    };

    // Also clear tracker on detail close
    var _origBkdClose335 = window.bookingsCloseDetail;
    if (typeof _origBkdClose335 === 'function') {
      window.bookingsCloseDetail = function () {
        _origBkdClose335.apply(this, arguments);
        window._v335BkdActiveDossId = null;
      };
    }
  }

  /* §5. (REMOVED) Tarefas row click wiring — superseded by v3.51 delegation.
     _v335WireTarefasClicks no-oped to prevent old _uniOpenTask routing. */
  function _v335WireTarefasClicks() { /* no-op — v3.51 owns Tarefas clicks */ }

  // Wrap tarefasRender (kept for chain — click wiring removed)
  if (typeof window.tarefasRender === 'function') {
    var _origTarefasRender335 = window.tarefasRender;
    window.tarefasRender = function () {
      _origTarefasRender335.apply(this, arguments);
    };
    window.tpRender = window.tarefasRender;
  }

  /* ── §6. Tasks index (main menu): row click delegation ───────────────── */
  function _v335WireIndexClicks() {
    var tbody = document.getElementById('di-tasks-body');
    if (!tbody) return;
    if (tbody._v335ClickHandler) tbody.removeEventListener('click', tbody._v335ClickHandler);
    tbody._v335ClickHandler = function (e) {
      if (e.target && e.target.type === 'checkbox') return;
      var tr = e.target.closest ? e.target.closest('tr') : null;
      if (!tr) return;
      var cb = tr.querySelector('input[type="checkbox"]');
      if (!cb) return;
      // Pattern: _diToggleTask('dossierId', taskId, this.checked)
      var onchangeStr = cb.getAttribute('onchange') || '';
      var m = onchangeStr.match(/_diToggleTask\('([^']+)',\s*([^,]+),/);
      if (!m) return;
      var dossierId = m[1];
      var taskId    = m[2].trim();
      // Resolve ref from dossierId
      var dosData = null;
      try { dosData = JSON.parse(localStorage.getItem('expatur_dossier_' + dossierId) || 'null'); } catch (e) {}
      var tref = (dosData && dosData.fields && dosData.fields['booking-ref']) || '';
      if (tref) {
        window._uniOpenTask(Number(taskId) || taskId, tref);
      }
    };
    tbody.addEventListener('click', tbody._v335ClickHandler);
  }

  // Wrap renderTasksIndex to wire clicks after each render
  if (typeof window.renderTasksIndex === 'function' || typeof renderTasksIndex === 'function') {
    var _origRTI335 = window.renderTasksIndex || renderTasksIndex;
    window.renderTasksIndex = function () {
      _origRTI335.apply(this, arguments);
      try { _v335WireIndexClicks(); } catch (e) {}
    };
  }

  /* ── §7. _diToggleTask: also refresh Tarefas + Ticketing after toggle ── */
  if (typeof window._diToggleTask === 'function' || typeof _diToggleTask === 'function') {
    var _origDiToggle335 = window._diToggleTask || _diToggleTask;
    window._diToggleTask = function (dossierId, taskId, checked) {
      _origDiToggle335.apply(this, arguments);
      // Also sync in-memory _tasks if this is the active dossier
      var activeId = localStorage.getItem('expatur_active_dossier') || '';
      if (activeId === dossierId) {
        var dosData = null;
        try { dosData = JSON.parse(localStorage.getItem('expatur_dossier_' + dossierId) || 'null'); } catch (e) {}
        var ref335b = (dosData && dosData.fields && dosData.fields['booking-ref']) || '';
        if (ref335b) {
          try {
            _tasks.length = 0;
            JSON.parse(localStorage.getItem('tasks_v2_' + ref335b.trim()) || '[]').forEach(function (t) { _tasks.push(t); });
          } catch (e) {}
          try { if (typeof renderTasks === 'function') renderTasks(); } catch (e) {}
        }
      }
      // Refresh Tarefas section
      try { if (typeof window.tarefasRender === 'function') window.tarefasRender(); } catch (e) {}
      // Refresh booking detail task section
      if (window._v335BkdActiveDossId) {
        try { _v335RefreshBkdTasks(window._v335BkdActiveDossId); } catch (e) {}
      }
    };
  }

  /* ── §8. _v35ToggleDone: also sync _tasks + refresh other surfaces ───── */
  if (typeof window._v35ToggleDone === 'function') {
    var _origV35Toggle335 = window._v35ToggleDone;
    window._v35ToggleDone = function (taskId, ref) {
      _origV35Toggle335.apply(this, arguments);
      // Sync _tasks if this is the active dossier
      var activeKey = typeof _origTasksKey335 === 'function' ? _origTasksKey335() : null;
      if (activeKey && activeKey === 'tasks_v2_' + (ref || '').trim()) {
        try {
          _tasks.length = 0;
          JSON.parse(localStorage.getItem(activeKey) || '[]').forEach(function (t) { _tasks.push(t); });
          if (typeof renderTasks === 'function') renderTasks();
        } catch (e) {}
      }
      // Refresh Tasks index
      try { if (typeof renderTasksIndex === 'function') renderTasksIndex(); } catch (e) {}
      // Refresh booking detail
      if (window._v335BkdActiveDossId) {
        try { _v335RefreshBkdTasks(window._v335BkdActiveDossId); } catch (e) {}
      }
    };
  }

  /* ── §9. Wire index clicks on initial render ─────────────────────────── */
  // Run wiring once now in case the Tasks section is already open
  setTimeout(function () {
    try { _v335WireIndexClicks(); }  catch (e) {}
    try { _v335WireTarefasClicks(); } catch (e) {}
  }, 300);

  console.log('[Patch v3.35] Unified task system loaded — booking detail, Tarefas, Tasks index all share editor + store.');

})(); // end Patch v3.35

// ─────────────────────────────────────

/* ═══════════════════════════════════════════════════════════════════════════
   Patch v3.36 — 5-fix patch
   §1  Tasks: index-based row wiring for Tarefas + Tasks Index (bypasses
       malformed-attribute extraction)
   §2  Tarification: "Ajouter une ligne" → "=" inline with Ligne libre input
   §3  Cost Calculator: "Ajouter une ligne" → "+" inline with Coût total
   §4  UI Cleanup: remove Fournisseurs btn, Imprimer, qt-book-cta;
       move Télécharger PDF below Générer le devis
   §5  Client: rename → "Save changes", dirty-state tracking, auto-switch
       to Tarification after save
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  if (window._v336) return;
  window._v336 = true;

  /* ═══════════════════════════════════════════════════════════════════════
     §1  TASKS — reliable index-based row wiring
     Problem: _v35Row generates onclick attributes using JSON.stringify()
     inside double-quoted HTML attrs → malformed HTML → getAttribute()
     returns truncated string → regex fails → no task opens.
     Fix: after each tarefasRender(), re-derive the filtered+sorted task
     list using the same window._tpState and window.filterTasks/sortTasks/
     groupTasks APIs, then match rows by DOM index.
     ═══════════════════════════════════════════════════════════════════════ */

  /* ── 1a. Tarefas rows ──────────────────────────────────────────────── */
  /* (REMOVED) _v336WireTarefasRows — per-row click wiring to _uniOpenTask removed.
     v3.51 delegation on #tarefas-list-body → _tarefasOpenTask owns all Tarefas clicks. */
  function _v336WireTarefasRows() { /* no-op — v3.51 owns Tarefas clicks */ }

  // Wrap tarefasRender (chain preserved, click wiring removed)
  if (typeof window.tarefasRender === 'function') {
    var _prevTR336 = window.tarefasRender;
    window.tarefasRender = function () {
      _prevTR336.apply(this, arguments);
    };
    window.tpRender = window.tarefasRender;
  }

  /* ── 1b. Tasks Index rows (main Tasks menu) ──────────────────────────── */
  // The onchange attribute uses single-quoted dossierId (no HTML encoding
  // issue) and a bare numeric taskId, so regex is reliable here.
  function _v336WireIndexRows() {
    var tbody = document.getElementById('di-tasks-body');
    if (!tbody) return;
    // Remove stale delegation listener before adding new one
    if (tbody._v336delegated) tbody.removeEventListener('click', tbody._v336delegated);
    tbody._v336delegated = function (e) {
      if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'BUTTON')) return;
      // Walk up to <tr>
      var tr = null;
      var el = e.target;
      while (el && el !== tbody) {
        if (el.tagName === 'TR') { tr = el; break; }
        el = el.parentElement;
      }
      if (!tr) return;
      var cb = tr.querySelector('input[type="checkbox"]');
      if (!cb) return;
      var oc = cb.getAttribute('onchange') || '';
      // Pattern: _diToggleTask('dossierId', numericId, this.checked)
      var m = oc.match(/_diToggleTask\('([^']+)',\s*(\d+),/);
      if (!m) return;
      var dossierId = m[1];
      var taskId    = parseInt(m[2], 10);
      var dosData   = null;
      try { dosData = JSON.parse(localStorage.getItem('expatur_dossier_' + dossierId) || 'null'); } catch (_) {}
      var tref = (dosData && dosData.fields && dosData.fields['booking-ref']) || '';
      if (typeof window._uniOpenTask === 'function') window._uniOpenTask(taskId, tref);
      else if (typeof openTaskDetail === 'function') openTaskDetail(taskId);
    };
    tbody.addEventListener('click', tbody._v336delegated);
  }

  // Wrap renderTasksIndex
  if (typeof window.renderTasksIndex === 'function' || typeof renderTasksIndex === 'function') {
    var _prevRTI336 = window.renderTasksIndex || renderTasksIndex;
    window.renderTasksIndex = function () {
      _prevRTI336.apply(this, arguments);
      try { _v336WireIndexRows(); } catch (_) {}
    };
  }

  // Run immediately in case a task surface is already visible
  setTimeout(function () {
    try { _v336WireTarefasRows(); } catch (_) {}
    try { _v336WireIndexRows();   } catch (_) {}
  }, 450);

  /* ═══════════════════════════════════════════════════════════════════════
     §2-5  DOM mutations — run once the DOM is fully ready
     ═══════════════════════════════════════════════════════════════════════ */
  function _v336DomSetup() {

    /* ── §2  Tarification: remove first "Ajouter une ligne", add "=" ───── */
    // Hide the "Ajouter une ligne" button that calls addCustomLine()
    var addCustBtn = null;
    document.querySelectorAll('#dv-panel-couts button').forEach(function (b) {
      if (!addCustBtn && b.getAttribute('onclick') === 'addCustomLine()') addCustBtn = b;
    });
    if (addCustBtn) addCustBtn.style.display = 'none';

    // Wrap the "Ligne libre" input with a flex row and add an "=" button
    var recapInput = document.getElementById('recap-free-line');
    if (recapInput && !document.getElementById('v336-recap-wrap')) {
      var wrap336 = document.createElement('div');
      wrap336.id = 'v336-recap-wrap';
      wrap336.style.cssText = 'display:flex;gap:6px;align-items:center;width:100%;';
      recapInput.parentNode.insertBefore(wrap336, recapInput);
      wrap336.appendChild(recapInput);
      recapInput.style.flex = '1';
      var eqBtn = document.createElement('button');
      eqBtn.type = 'button';
      eqBtn.className = 'btn btn-gold btn-sm';
      eqBtn.id = 'v336-eq-btn';
      eqBtn.style.cssText = 'flex:0 0 34px;min-width:34px;height:34px;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:1.05rem;padding:0;';
      eqBtn.textContent = '=';
      eqBtn.title = 'Ajouter une ligne personnalisée';
      eqBtn.onclick = function () { if (typeof addCustomLine === 'function') addCustomLine(); };
      wrap336.appendChild(eqBtn);
    }

    /* ── §3  Cost Calculator: remove second "Ajouter une ligne", add "+" ─ */
    var addMilesBtn = null;
    document.querySelectorAll('#dv-panel-couts button').forEach(function (b) {
      if (!addMilesBtn && b.getAttribute('onclick') === 'addMilesRow()') addMilesBtn = b;
    });
    if (addMilesBtn) {
      addMilesBtn.style.display = 'none';
      // Add "+" button to the right of the grand total span
      var grandTotal = document.getElementById('miles-grand-total');
      if (grandTotal && !document.getElementById('v336-plus-btn')) {
        var plusBtn = document.createElement('button');
        plusBtn.type = 'button';
        plusBtn.id = 'v336-plus-btn';
        plusBtn.className = 'btn btn-navy btn-sm';
        plusBtn.style.cssText = 'flex:0 0 32px;min-width:32px;height:32px;display:inline-flex;align-items:center;justify-content:center;font-weight:700;font-size:1.1rem;padding:0;margin-left:8px;vertical-align:middle;';
        plusBtn.textContent = '+';
        plusBtn.title = 'Ajouter une ligne';
        plusBtn.onclick = function () { if (typeof addMilesRow === 'function') addMilesRow(); };
        grandTotal.parentNode.appendChild(plusBtn);
      }
    }

    /* ── §4a  Remove Fournisseurs button from Cost Calculator header ────── */
    // The button is the first ✏ Fournisseurs btn inside .miles-calc-card
    var milesCard = document.querySelector('.miles-calc-card');
    if (milesCard) {
      var fornBtn = milesCard.querySelector('button[onclick*="blManageFornecedores"]');
      if (fornBtn) {
        var fornWrap = fornBtn.parentElement;
        // Hide the entire wrapper div (preserves layout, avoids partial removal)
        if (fornWrap && fornWrap !== milesCard) fornWrap.style.display = 'none';
        else fornBtn.style.display = 'none';
      }
    }

    /* ── §4b  Remove Imprimer button ────────────────────────────────────── */
    document.querySelectorAll('#dv-panel-couts button').forEach(function (b) {
      if (b.getAttribute('onclick') === 'window.print()') b.style.display = 'none';
    });

    /* ── §4c  Move Télécharger PDF below Générer le devis ───────────────── */
    var dlBtn  = document.querySelector('#dv-panel-couts button[onclick="generatePDF()"]');
    var genBtn = document.querySelector('#dv-panel-couts .btn-primary[onclick="buildPreview()"]');
    if (dlBtn && genBtn && !document.getElementById('v336-dl-pdf-btn')) {
      // Hide the original in the toolbar
      dlBtn.style.display = 'none';

      // Create new PDF button below "Générer le devis"
      var newDlBtn = document.createElement('button');
      newDlBtn.type = 'button';
      newDlBtn.id = 'v336-dl-pdf-btn';
      newDlBtn.className = 'btn btn-gold';
      newDlBtn.style.cssText = 'margin-top:0.5rem;display:block;width:100%;';
      newDlBtn.textContent = 'Télécharger PDF';
      newDlBtn.onclick = function () { if (typeof generatePDF === 'function') generatePDF(); };

      // Also make the "Générer" button full-width for visual alignment
      genBtn.style.width = '100%';
      genBtn.style.display = 'block';

      var genParent = genBtn.parentElement; // div with margin-top:1.4rem
      if (genBtn.nextSibling) genParent.insertBefore(newDlBtn, genBtn.nextSibling);
      else genParent.appendChild(newDlBtn);
    }

    /* ── §4d  Remove Prochaine étape / BOOK CTA block ───────────────────── */
    var ctaBlock = document.getElementById('qt-book-cta');
    if (ctaBlock) ctaBlock.style.display = 'none';

    /* ── §5  Client "Save changes" — dirty tracking + auto-switch ─────── */
    _v336PatchClientSave();
  }

  /* ── §5 detailed implementation ─────────────────────────────────────── */
  function _v336PatchClientSave() {
    // Find the save button (by onclick attribute or text)
    var btn = null;
    document.querySelectorAll('button').forEach(function (b) {
      if (!btn && b.getAttribute('onclick') === 'clientSave()') btn = b;
    });
    if (!btn) {
      document.querySelectorAll('button').forEach(function (b) {
        if (!btn && (b.textContent || '').trim() === 'Enregistrer le client') btn = b;
      });
    }
    if (!btn) return;

    // Rename and mark as patched
    btn.textContent = 'Save changes';
    btn.id = btn.id || 'v336-client-save-btn';
    btn.removeAttribute('onclick');

    // Dirty-state helpers
    function _setEnabled(on) {
      btn.disabled = !on;
      btn.style.opacity    = on ? '1'         : '0.38';
      btn.style.cursor     = on ? 'pointer'    : 'not-allowed';
      btn.style.pointerEvents = on ? ''        : 'none';
    }
    _setEnabled(false); // start disabled (pristine)

    // Collect all client form field IDs
    var _CLI_IDS = ['cli-civilite','cli-prenom','cli-nom','cli-dob','cli-nationalite',
                    'cli-passport','cli-passport-exp','cli-email','cli-tel','cli-whatsapp',
                    'cli-adresse','cli-cp','cli-ville','cli-pays','cli-notes'];

    function _snapshot() {
      return JSON.stringify(_CLI_IDS.map(function (id) {
        var el = document.getElementById(id);
        return el ? el.value : '';
      }));
    }

    var _pristine = _snapshot(); // baseline

    function _checkDirty() {
      _setEnabled(_snapshot() !== _pristine);
    }

    function _watchFields() {
      _CLI_IDS.forEach(function (id) {
        var el = document.getElementById(id);
        if (!el || el._v336w) return;
        el._v336w = true;
        el.addEventListener('input',  _checkDirty);
        el.addEventListener('change', _checkDirty);
      });
    }
    _watchFields();

    // Click handler: save → reset dirty → switch to Tarification
    btn.addEventListener('click', function () {
      if (btn.disabled) return;
      if (typeof clientSave === 'function') clientSave();
      _pristine = _snapshot(); // reset baseline after save
      _setEnabled(false);
      // Navigate to Tarification
      if (typeof quotingSwitch === 'function') quotingSwitch('couts');
    });

    // Snapshot refresh when the Client tab is activated
    // (so that loading a client record doesn't appear "dirty")
    if (typeof window.quotingSwitch === 'function' && !window._v336qsWrap) {
      window._v336qsWrap = true;
      var _prevQS336 = window.quotingSwitch;
      window.quotingSwitch = function (tab) {
        _prevQS336.apply(this, arguments);
        if (tab === 'client') {
          setTimeout(function () {
            _pristine = _snapshot();
            _setEnabled(false);
            _watchFields(); // re-attach to any newly rendered fields
          }, 80);
        }
      };
    }
  }

  // Kick off DOM mutations
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _v336DomSetup);
  } else {
    setTimeout(_v336DomSetup, 0);
  }

  console.log('[Patch v3.36] 5-fix patch loaded — Tasks wiring, UI cleanup, Client save flow.');

})(); // end Patch v3.36

// ─────────────────────────────────────

/* ═══════════════════════════════════════════════════════════════════════════
   Patch v3.37 — 6-fix DOM + logic patch
   §1  Cost Calculator total row: reorder [+] [COÛT TOTAL] [value] right-aligned
   §2  inv-diff-wrap: compact + inline vendeur / commission / WA
   §3  vendeur ↔ wa-partner-select bidirectional sync
   §4  Tarification "=" → "+" beside Ligne libre, move custom-lines below,
       hide old Lignes personnalisées block
   §5  Générer le devis + Télécharger PDF — same row, right-aligned
   (§6  RAV label + readonly done inline; NF task desc done inline)
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  if (window._v337) return;
  window._v337 = true;

  /* ── §3  vendeur ↔ wa-partner-select bidirectional sync ─────────────── */
  var _v337syncing = false;

  function _v337VendeurToWA(vendeurVal) {
    if (_v337syncing) return;
    var lower = (vendeurVal || '').toLowerCase();
    if (lower !== 'othman' && lower !== 'sami') return;
    _v337syncing = true;
    try {
      var waCheck = document.getElementById('wa-partner-check');
      var waSel   = document.getElementById('wa-partner-select');
      if (waSel) waSel.value = lower;
      if (waCheck && !waCheck.checked) {
        waCheck.checked = true;
        if (typeof _togglePartnerSelect === 'function') _togglePartnerSelect();
      }
      if (typeof buildPreview === 'function') buildPreview();
    } finally { _v337syncing = false; }
  }

  function _v337WAToVendeur(waVal) {
    if (_v337syncing) return;
    var lower = (waVal || '').toLowerCase();
    if (lower !== 'othman' && lower !== 'sami') return;
    _v337syncing = true;
    try {
      var vSel = document.getElementById('vendeur-select');
      if (vSel) {
        vSel.value = lower.charAt(0).toUpperCase() + lower.slice(1);
        if (typeof blCalcPnL === 'function') blCalcPnL();
      }
    } finally { _v337syncing = false; }
  }

  function _v337WireSync() {
    var vSel  = document.getElementById('vendeur-select');
    var waSel = document.getElementById('wa-partner-select');
    if (vSel && !vSel._v337sync) {
      vSel._v337sync = true;
      vSel.addEventListener('change', function () { _v337VendeurToWA(this.value); });
    }
    if (waSel && !waSel._v337sync) {
      waSel._v337sync = true;
      waSel.addEventListener('change', function () { _v337WAToVendeur(this.value); });
    }
  }

  /* ── §1-2,4-5  DOM mutations ─────────────────────────────────────────── */
  function _v337DomSetup() {

    /* ── §1  Cost Calculator total row ──────────────────────────────────── */
    var plusBtn    = document.getElementById('v336-plus-btn');
    var grandTotal = document.getElementById('miles-grand-total');
    if (plusBtn && grandTotal && !grandTotal._v337done) {
      grandTotal._v337done = true;
      var totalContainer = grandTotal.parentNode;
      totalContainer.style.justifyContent = 'flex-end';
      totalContainer.style.gap = '6px';

      // Shrink the + button
      plusBtn.style.cssText = 'flex:0 0 22px;min-width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-weight:700;font-size:0.8rem;padding:0;border-radius:4px;margin-left:0;vertical-align:middle;';

      // Insert label between + and value
      if (!document.getElementById('v337-total-label')) {
        var lbl = document.createElement('span');
        lbl.id = 'v337-total-label';
        lbl.textContent = 'COÛT TOTAL';
        lbl.style.cssText = 'font-size:0.62rem;font-weight:800;letter-spacing:0.09em;text-transform:uppercase;color:var(--navy);opacity:0.75;';
        totalContainer.insertBefore(lbl, grandTotal);
        totalContainer.insertBefore(plusBtn, lbl);
      }
      // Reduce red total font size
      grandTotal.style.fontSize = '0.9rem';
    }

    /* ── §2  inv-diff-wrap: compact + inline vendeur / commission / WA ── */
    var invWrap   = document.getElementById('inv-diff-wrap');
    var vCommWrap = document.getElementById('vendeur-commission-wrap');
    var waWrap    = document.getElementById('wa-partner-wrap');
    if (invWrap && vCommWrap && waWrap && !invWrap._v337compact) {
      invWrap._v337compact = true;
      invWrap.style.marginTop = '0.45rem';
      invWrap.style.padding   = '0.4rem 0.7rem';

      var parent = invWrap.parentNode;
      if (!document.getElementById('v337-compact-row')) {
        var row = document.createElement('div');
        row.id = 'v337-compact-row';
        row.style.cssText = 'display:flex;align-items:flex-start;gap:0.5rem;flex-wrap:wrap;margin-top:0.5rem;';
        parent.insertBefore(row, invWrap);

        invWrap.style.flex = '0 1 auto';
        invWrap.style.minWidth = '170px';
        row.appendChild(invWrap);

        vCommWrap.style.flex = '1';
        vCommWrap.style.minWidth = '155px';
        vCommWrap.style.padding  = '0.4rem 0.65rem';
        row.appendChild(vCommWrap);

        waWrap.style.flex = '1';
        waWrap.style.minWidth = '155px';
        waWrap.style.marginTop = '0';
        row.appendChild(waWrap);
      }
    }

    /* ── §4  Tarification: "=" → "+", move custom-lines, hide old block ─ */
    var eqBtn = document.getElementById('v336-eq-btn') || document.getElementById('v337-recap-plus-btn');
    if (eqBtn && eqBtn.textContent === '=') {
      eqBtn.textContent = '+';
      eqBtn.id = 'v337-recap-plus-btn';
    }

    var recapWrap  = document.getElementById('v336-recap-wrap');
    var customRows = document.getElementById('custom-lines-rows');
    if (recapWrap && customRows && !recapWrap._v337customMoved) {
      recapWrap._v337customMoved = true;
      var oldParent = customRows.parentNode;
      if (recapWrap.nextSibling) {
        recapWrap.parentNode.insertBefore(customRows, recapWrap.nextSibling);
      } else {
        recapWrap.parentNode.appendChild(customRows);
      }
      customRows.style.marginTop = '4px';
      // Hide the old "Lignes personnalisées" wrapper
      if (oldParent) {
        var hasTitle = Array.prototype.some.call(oldParent.childNodes, function(n) {
          return (n.textContent || '').trim().indexOf('Lignes personnalis') >= 0;
        });
        if (hasTitle) oldParent.style.display = 'none';
      }
    }

    /* ── §5  Générer devis + Télécharger PDF — same row, right-aligned ── */
    var newDlBtn = document.getElementById('v336-dl-pdf-btn');
    var genBtn   = document.querySelector('#dv-panel-couts .btn-primary[onclick="buildPreview()"]');
    if (newDlBtn && genBtn && !newDlBtn._v337samerow) {
      newDlBtn._v337samerow = true;
      genBtn.style.width   = '';
      genBtn.style.display = '';
      newDlBtn.style.marginTop = '0';
      newDlBtn.style.display   = '';
      newDlBtn.style.width     = '';

      var genParent = genBtn.parentNode;
      if (!document.getElementById('v337-btn-row')) {
        var btnRow = document.createElement('div');
        btnRow.id  = 'v337-btn-row';
        btnRow.style.cssText = 'display:flex;justify-content:flex-end;gap:0.5rem;align-items:center;flex-wrap:wrap;';
        genParent.insertBefore(btnRow, genBtn);
        genBtn.style.width   = 'auto';
        newDlBtn.style.width = 'auto';
        btnRow.appendChild(genBtn);
        btnRow.appendChild(newDlBtn);
      }
    }

    /* ── Wire sync ─────────────────────────────────────────────────────── */
    _v337WireSync();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _v337DomSetup);
  } else {
    setTimeout(_v337DomSetup, 0);
  }

  // Re-wire on tab switch
  if (typeof window.quotingSwitch === 'function' && !window._v337qsWrap) {
    window._v337qsWrap = true;
    var _prevQS337 = window.quotingSwitch;
    window.quotingSwitch = function (tab) {
      _prevQS337.apply(this, arguments);
      if (tab === 'couts' || tab === 'tarif') setTimeout(_v337DomSetup, 80);
    };
  }

  console.log('[Patch v3.37] Loaded — total row compact, inv-diff inline, vendeur\u2194WA sync, recap +, custom-lines moved, same-row PDF/devis, RAV readonly, NF task desc.');
})(); // end Patch v3.37

