/* ═══════════════════════════════════════════════════════════════════════════
   Patch v3.44 — Auto-categorize uncategorized tasks
   Scans all tasks across all dossier refs, finds tasks with no meaningful
   category (empty, missing, or 'Diversos' default), infers category from
   title using the existing _AUTO_CAT_RULES scoring engine, updates storage,
   and refreshes the UI.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v344) return;
  window._v344 = true;

  /* ═══════════════════════════════════════════════════════════════════════
     §1 — Enhanced category inference from title
     Wraps existing _autoCategorizeSuggest with accent stripping and
     additional keyword coverage. Returns an existing category or null.
     ═══════════════════════════════════════════════════════════════════════ */
  function _normalizeText(str) {
    return (str || '').toLowerCase().trim()
      .replace(/\s+/g, ' ')
      /* strip accents */
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  }

  function _inferCategoryFromTitle(title) {
    if (!title || !title.trim()) return null;

    var norm = _normalizeText(title);

    /* Use the existing AUTO_CAT_RULES engine if available */
    if (typeof _autoCategorizeSuggest === 'function') {
      var result = _autoCategorizeSuggest(title);
      /* _autoCategorizeSuggest returns 'Diversos' when score < 3.
         We want to distinguish "confidently matched" from "fallback".
         Re-run the scoring to check if we got a real match. */
      if (result && result !== 'Diversos') return result;
    }

    /* Extended keyword matching for edge cases the base engine misses */
    var extraRules = [
      { cat: 'Check-in',        kw: ['check-in', 'check in', 'checkin', 'boarding pass', 'carte embarquement', 'cartao embarque'] },
      { cat: 'Payments',        kw: ['payment', 'paiement', 'pagamento', 'pagar', 'pago', 'remise', 'transferencia', 'wire', 'boleto', 'pix', 'deposito'] },
      { cat: 'Suriname Visa',   kw: ['suriname visa', 'visa suriname', 'visto suriname', 'visa srn'] },
      { cat: 'Suriname I.C.F',  kw: ['i.c.f', 'icf', 'immigration card', 'formulario imigracao', 'immigration form', 'suriname icf'] },
      { cat: 'QR code R.D',     kw: ['qr code', 'qr-code', 'republica dominicana', 'dominicana qr', 'rd qr', 'e-ticket rd', 'punta cana qr', 'santo domingo qr'] },
      { cat: 'Volta Cancelada',  kw: ['volta cancelada', 'retour annule', 'return cancelled', 'cancelamento', 'cancellation', 'remarcacao', 'rebook', 'cancelar'] },
      { cat: 'Notas Fiscais',   kw: ['nota fiscal', 'nf-e', 'nfe', 'danfe', 'emitir n.f', 'emitir nf', 'numero n.f', 'numero nf'] },
      { cat: 'Facture',         kw: ['facture', 'invoice', 'fatura', 'factura', 'bill'] }
    ];

    for (var i = 0; i < extraRules.length; i++) {
      var rule = extraRules[i];
      for (var j = 0; j < rule.kw.length; j++) {
        if (norm.indexOf(_normalizeText(rule.kw[j])) >= 0) {
          /* Verify this category exists in the app */
          var cats = (window.catStore && typeof window.catStore.getAllCategories === 'function')
            ? window.catStore.getAllCategories() : [];
          if (cats.indexOf(rule.cat) >= 0) return rule.cat;
        }
      }
    }

    return null; /* No confident match — leave uncategorized */
  }
  window._inferCategoryFromTitle = _inferCategoryFromTitle;

  /* ═══════════════════════════════════════════════════════════════════════
     §2 — Auto-categorization processor
     Scans all tasks_v2_* keys, finds uncategorized tasks, infers category,
     updates raw storage, refreshes UI.
     ═══════════════════════════════════════════════════════════════════════ */
  function _isUncategorized(task) {
    var cat = (task.category || task.cat || '').trim();
    return !cat || cat === 'Diversos';
  }

  function autoCategorizeUncategorizedTasks(opts) {
    opts = opts || {};
    var silent = !!opts.silent;

    /* Gather all dossier refs */
    var refs = [];
    if (typeof _tpGetAllDossierRefs === 'function') {
      refs = _tpGetAllDossierRefs();
    }
    /* Also check STANDALONE and IMPORTADAS */
    ['STANDALONE', 'IMPORTADAS'].forEach(function (r) {
      if (refs.indexOf(r) < 0 && localStorage.getItem('tasks_v2_' + r)) refs.push(r);
    });
    /* Also scan all tasks_v2_* keys in localStorage */
    for (var k = 0; k < localStorage.length; k++) {
      var key = localStorage.key(k);
      if (key && key.indexOf('tasks_v2_') === 0) {
        var ref = key.substring(9);
        if (refs.indexOf(ref) < 0) refs.push(ref);
      }
    }

    var totalUpdated = 0;
    var totalScanned = 0;

    refs.forEach(function (ref) {
      var storageKey = 'tasks_v2_' + ref;
      var raw;
      try { raw = JSON.parse(localStorage.getItem(storageKey) || '[]'); } catch (e) { return; }
      if (!Array.isArray(raw) || raw.length === 0) return;

      var modified = false;
      raw.forEach(function (task) {
        totalScanned++;
        if (!_isUncategorized(task)) return; /* Already categorized — skip */

        var title = task.text || task.title || '';
        var inferred = _inferCategoryFromTitle(title);
        if (!inferred) return; /* No confident match */

        /* Update the task — set both cat and category fields */
        task.cat = inferred;
        task.category = inferred;
        modified = true;
        totalUpdated++;
      });

      if (modified) {
        try { localStorage.setItem(storageKey, JSON.stringify(raw)); } catch (e) {}
      }
    });

    /* Also scan expatur_dossiers (legacy imported tasks) */
    try {
      var expRaw = localStorage.getItem('expatur_dossiers');
      var expDossiers = expRaw ? JSON.parse(expRaw) : [];
      var expModified = false;
      expDossiers.forEach(function (d) {
        (d.tasks || []).forEach(function (task) {
          totalScanned++;
          var cat = (task.category || task.cat || '').trim();
          if (cat && cat !== 'Diversos') return;

          var title = task.title || task.text || '';
          var inferred = _inferCategoryFromTitle(title);
          if (!inferred) return;

          task.category = inferred;
          task.cat = inferred;
          expModified = true;
          totalUpdated++;
        });
      });
      if (expModified) {
        localStorage.setItem('expatur_dossiers', JSON.stringify(expDossiers));
      }
    } catch (e) {}

    /* Refresh UIs */
    if (typeof window.tarefasRender === 'function') window.tarefasRender();
    if (typeof window.welcomeRefresh === 'function') setTimeout(window.welcomeRefresh, 50);
    if (window.taskStore && typeof window.taskStore.refreshAllTaskUIs === 'function') {
      window.taskStore.refreshAllTaskUIs();
    }

    /* Toast */
    if (!silent && typeof toast === 'function') {
      if (totalUpdated > 0) {
        toast(totalUpdated + ' tarefa(s) categorizada(s) automaticamente', 'success');
      } else {
        toast('Nenhuma tarefa sem categoria encontrada (' + totalScanned + ' verificadas)', 'info');
      }
    }

    return { scanned: totalScanned, updated: totalUpdated };
  }
  window.autoCategorizeUncategorizedTasks = autoCategorizeUncategorizedTasks;

  /* ═══════════════════════════════════════════════════════════════════════
     §3 — Hook into import flow
     Wrap tarefasImportXlsxOpen's confirm callback to auto-categorize
     after import completes.
     ═══════════════════════════════════════════════════════════════════════ */
  /* Wrap tarefasRender to run auto-categorize once after page load */
  var _v344RanOnce = false;
  var _prevTR344 = window.tarefasRender;
  window.tarefasRender = function () {
    _prevTR344.apply(this, arguments);
    if (!_v344RanOnce) {
      _v344RanOnce = true;
      /* Auto-categorize silently on first Tarefas render */
      setTimeout(function () {
        autoCategorizeUncategorizedTasks({ silent: true });
      }, 200);
    }
  };
  window.tpRender = window.tarefasRender;

  /* ═══════════════════════════════════════════════════════════════════════
     §4 — Add manual "Auto-categorize" button in Tarefas toolbar
     Inject into the compact toolbar (v3.43) after it's created.
     ═══════════════════════════════════════════════════════════════════════ */
  var _origInjectToolbar344 = window._tpInjectToolbar;
  window._tpInjectToolbar = function () {
    _origInjectToolbar344.apply(this, arguments);
    /* Add the auto-categorize button to the toolbar row */
    _v344InjectAutoCatButton();
  };

  function _v344InjectAutoCatButton() {
    var wrap = document.getElementById('v343-toolbar-wrap');
    if (!wrap) return;
    if (wrap.querySelector('#v344-autocat-btn')) return; /* already injected */

    /* Find the row with the search/filter/new-task buttons */
    var actionRow = wrap.querySelector('div[style*="flex-wrap:wrap"]');
    if (!actionRow) {
      /* Fallback: find the second div child */
      var divs = wrap.querySelectorAll(':scope > div');
      if (divs.length >= 2) actionRow = divs[1];
    }
    if (!actionRow) return;

    var btn = document.createElement('button');
    btn.id = 'v344-autocat-btn';
    btn.style.cssText = 'display:inline-flex;align-items:center;gap:0.3rem;background:rgba(216,167,5,0.1);border:1px solid var(--gold,#d8a705);border-radius:20px;padding:0.28rem 0.7rem;font-size:0.71rem;font-weight:600;color:var(--navy);cursor:pointer;font-family:inherit;transition:all 0.15s;white-space:nowrap;';
    btn.innerHTML = '🏷️ Auto-categorizar';
    btn.title = 'Categorizar automaticamente tarefas importadas sem categoria';
    btn.onclick = function () {
      autoCategorizeUncategorizedTasks({ silent: false });
    };
    /* Insert before the "Nova tarefa" button if present */
    var newTaskBtn = actionRow.querySelector('.v343-new-task-btn');
    if (newTaskBtn) {
      actionRow.insertBefore(btn, newTaskBtn);
    } else {
      actionRow.appendChild(btn);
    }
  }

  /* Auto-categorize header button — now part of Ações dropdown, skip injection */
  function _v344InjectHeaderButton() {
    return; // v3.100: moved into Ações dropdown in static HTML
    var header = document.querySelector('#section-tarefas .section-page-header');
    if (!header || header.querySelector('#v344-autocat-header-btn')) return;
    var rightArea = header.querySelector('div[style*="flex-shrink:0"]');
    if (!rightArea) rightArea = header.lastElementChild;
    if (!rightArea) return;

    var btn = document.createElement('button');
    btn.id = 'v344-autocat-header-btn';
    btn.className = 'btn btn-sm';
    btn.style.cssText = 'display:inline-flex;align-items:center;gap:0.4rem;white-space:nowrap;background:rgba(216,167,5,0.1);border:1px solid var(--gold,#d8a705);border-radius:8px;padding:0.35rem 0.75rem;font-size:0.72rem;font-weight:600;color:var(--navy);cursor:pointer;font-family:inherit;';
    btn.innerHTML = '🏷️ Auto-categorizar';
    btn.title = 'Categorizar automaticamente tarefas sem categoria';
    btn.onclick = function () {
      autoCategorizeUncategorizedTasks({ silent: false });
    };
    /* Insert before the import button */
    var importBtn = rightArea.querySelector('[onclick*="tarefasImportXlsx"]');
    if (importBtn) {
      rightArea.insertBefore(btn, importBtn);
    } else {
      rightArea.appendChild(btn);
    }
  }

  /* ═══════════════════════════════════════════════════════════════════════
     §5 — Init
     ═══════════════════════════════════════════════════════════════════════ */
  function _v344Init() {
    _v344InjectHeaderButton();
    /* If toolbar already exists, inject button now */
    _v344InjectAutoCatButton();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { setTimeout(_v344Init, 400); });
  } else {
    setTimeout(_v344Init, 400);
  }

  console.log('[Patch v3.44] Auto-categorize uncategorized tasks — keyword engine + manual button.');
})();

// ─────────────────────────────────────

/* ═══════════════════════════════════════════════════════════════════════════
   Patch v3.45 — Fix initial Tarefas click bug + robust auto-categorize save
   ═══════════════════════════════════════════════════════════════════════════
   ROOT CAUSE of click bug:
   The core render functions (_v35Row, _tpTaskRow) are closure references
   captured inside _v35Render/tpRender. The v3.43 override of window._tpTaskRow
   never takes effect because the closure ignores window._tpTaskRow.
   Result: rows render WITH inline onclick="window.taskStore.openTaskEverywhere()"
   and WITHOUT data-task-id attributes.
   The inline onclick fires BEFORE any delegated handler can intercept it,
   navigating away from Tarefas. The v3.43 delegation handler on
   #tarefas-list-body only matches [data-task-id] which doesn't exist.

   FIX:
   §1 — After every render, strip inline onclick from .tarefas-task-row
        and inject data-task-id/data-task-ref via direct task-array matching
   §2 — Use a MutationObserver as belt-and-suspenders for dynamically added rows
   §3 — Intercept openTaskEverywhere to prevent navigation when in Tarefas
   §4 — Ensure auto-categorize saves to raw storage AND re-renders
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v345) return;
  window._v345 = true;

  /* ═══════════════════════════════════════════════════════════════════════
     §1 — Post-render row normalization
     Strips inline onclick, adds data-task-id/data-task-ref using the
     same task source as the renderer.
     ═══════════════════════════════════════════════════════════════════════ */
  function _v345NormalizeRows() {
    var listBody = document.getElementById('tarefas-list-body');
    if (!listBody) return;

    var rows = listBody.querySelectorAll('.tarefas-task-row');
    if (rows.length === 0) return;

    /* Get the ordered task array matching the current render.
       Use _v35GetAllTasks + window.filterTasks/sortTasks (same as _v35Render)
       with fallback to taskStore methods. */
    var all = [];
    if (typeof window._v35GetAllTasks === 'function') {
      all = window._v35GetAllTasks();
    } else if (window.taskStore && typeof window.taskStore.getAllTasks === 'function') {
      all = window.taskStore.getAllTasks();
    }

    var st = window._tpState || {};

    /* Filter — use the same function _v35Render uses */
    var filtered = all;
    if (typeof window.filterTasks === 'function') {
      filtered = window.filterTasks(all, {
        status:   st.status === 'all' ? undefined : st.status,
        priority: st.priority === 'all' ? undefined : st.priority,
        category: st.category === 'all' ? undefined : st.category,
        due:      st.due === 'all' ? undefined : st.due,
        dossier:  st.dossier === 'all' ? undefined : st.dossier,
        q: st.q || ''
      });
    }

    /* Sort — same as _v35Render */
    if (typeof window.sortTasks === 'function') {
      filtered = window.sortTasks(filtered, st.sort || 'default');
    }

    /* Group — flatten in same order as renderer */
    var ordered = [];
    if (st.group && st.group !== 'none' && typeof window.groupTasks === 'function') {
      var grps = window.groupTasks(filtered, st.group);
      Object.keys(grps).sort().forEach(function (k) {
        grps[k].forEach(function (t) { ordered.push(t); });
      });
    } else {
      ordered = filtered.slice();
    }

    /* Process each row */
    rows.forEach(function (row, idx) {
      var t = ordered[idx];
      if (!t) return;

      /* Always set data-task-id (even if already present — ensure correctness) */
      row.setAttribute('data-task-id', String(t.id));
      row.setAttribute('data-task-ref', t._ref || '');

      /* Strip inline onclick to prevent openTaskEverywhere navigation.
         We must do this because inline onclick fires before delegation. */
      if (row.hasAttribute('onclick')) {
        row.removeAttribute('onclick');
      }
      /* Also clear the onclick property (for handlers set via DOM property) */
      row.onclick = null;

      /* Ensure cursor */
      row.style.cursor = 'pointer';
    });
  }
  window._v345NormalizeRows = _v345NormalizeRows;

  /* ═══════════════════════════════════════════════════════════════════════
     §1b — Install delegation (reuse v3.43 if present, or install our own)
     ═══════════════════════════════════════════════════════════════════════ */
  function _v345InstallDelegation() {
    var listBody = document.getElementById('tarefas-list-body');
    if (!listBody) return;

    /* If v3.43 delegation already installed and working, just ensure it's there */
    if (listBody._v343Delegated) return;

    /* Install our own as fallback */
    if (listBody._v345Delegated) return;

    listBody._v345Delegated = function (e) {
      if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'BUTTON')) return;
      var row = e.target.closest ? e.target.closest('.tarefas-task-row[data-task-id]') : null;
      if (!row) return;

      e.stopPropagation();

      var taskId = row.getAttribute('data-task-id');
      var taskRef = row.getAttribute('data-task-ref') || '';
      if (!taskId) return;
      var tid = isNaN(Number(taskId)) ? taskId : Number(taskId);

      var task = null;
      if (window.taskStore && typeof window.taskStore.getTaskById === 'function') {
        task = window.taskStore.getTaskById(tid);
      }
      if (!task) task = { id: tid, _ref: taskRef };

      /* ALL tasks open locally — no linked/unlinked split, no Ticketing navigation */
      if (typeof window._tarefasOpenTask === 'function') {
        window._tarefasOpenTask(tid, taskRef);
      }
    };

    listBody.addEventListener('click', listBody._v345Delegated);
  }

  /* ═══════════════════════════════════════════════════════════════════════
     §2 — MutationObserver: catch any innerHTML replacement of task rows
     ═══════════════════════════════════════════════════════════════════════ */
  function _v345StartObserver() {
    var listBody = document.getElementById('tarefas-list-body');
    if (!listBody || listBody._v345Observer) return;

    listBody._v345Observer = new MutationObserver(function () {
      /* Debounce — rows just changed, normalize after DOM settles */
      clearTimeout(listBody._v345ObsTimer);
      listBody._v345ObsTimer = setTimeout(function () {
        _v345NormalizeRows();
        _v345InstallDelegation();
      }, 15);
    });

    listBody._v345Observer.observe(listBody, { childList: true, subtree: false });
  }

  /* ═══════════════════════════════════════════════════════════════════════
     §3 — Intercept openTaskEverywhere when in Tarefas section
     Prevents the inline onclick from navigating away if it somehow fires.
     ═══════════════════════════════════════════════════════════════════════ */
  if (window.taskStore && typeof window.taskStore.openTaskEverywhere === 'function') {
    var _origOpenTE = window.taskStore.openTaskEverywhere;
    window.taskStore.openTaskEverywhere = function (taskId, opts) {
      /* If currently in Tarefas, ALWAYS open locally via _tarefasOpenTask.
         No linked/unlinked split. No navigation to Ticketing. */
      if (typeof window._currentSection !== 'undefined' && window._currentSection === 'tarefas') {
        var task = null;
        if (typeof window.taskStore.getTaskById === 'function') {
          task = window.taskStore.getTaskById(taskId);
        }
        var ref = (task && task._ref) || '';
        if (typeof window._tarefasOpenTask === 'function') {
          window._tarefasOpenTask(taskId, ref);
        }
        return;
      }
      /* Not in Tarefas — let original behavior run */
      _origOpenTE.apply(this, arguments);
    };
  }

  /* ═══════════════════════════════════════════════════════════════════════
     §4 — Robust auto-categorize with persistent save
     Override autoCategorizeUncategorizedTasks to ensure raw storage update.
     ═══════════════════════════════════════════════════════════════════════ */
  var _origAutoCat = window.autoCategorizeUncategorizedTasks;
  window.autoCategorizeUncategorizedTasks = function (opts) {
    opts = opts || {};
    var silent = !!opts.silent;
    var totalUpdated = 0;
    var totalScanned = 0;

    /* Gather ALL refs from every source */
    var refs = [];
    if (typeof _tpGetAllDossierRefs === 'function') {
      try { refs = _tpGetAllDossierRefs(); } catch (e) {}
    }
    ['STANDALONE', 'IMPORTADAS', 'DEVIS'].forEach(function (r) {
      if (refs.indexOf(r) < 0) {
        try { if (localStorage.getItem('tasks_v2_' + r)) refs.push(r); } catch (e) {}
      }
    });
    /* Scan all tasks_v2_* keys */
    for (var k = 0; k < localStorage.length; k++) {
      var key = localStorage.key(k);
      if (key && key.indexOf('tasks_v2_') === 0) {
        var ref = key.substring(9);
        if (refs.indexOf(ref) < 0) refs.push(ref);
      }
    }

    /* Process each ref's raw tasks */
    refs.forEach(function (ref) {
      var storageKey = 'tasks_v2_' + ref;
      var raw;
      try { raw = JSON.parse(localStorage.getItem(storageKey) || '[]'); } catch (e) { return; }
      if (!Array.isArray(raw) || raw.length === 0) return;

      var modified = false;
      raw.forEach(function (task) {
        totalScanned++;
        var cat = (task.category || task.cat || '').trim();
        if (cat && cat !== 'Diversos') return; /* Already categorized */

        var title = task.text || task.title || '';
        var inferred = null;
        if (typeof window._inferCategoryFromTitle === 'function') {
          inferred = window._inferCategoryFromTitle(title);
        } else if (typeof window.taskAutoCategory === 'function') {
          var result = window.taskAutoCategory(title);
          if (result && result !== 'Diversos') inferred = result;
        }
        if (!inferred) return;

        /* Update both fields in raw storage */
        task.cat = inferred;
        task.category = inferred;
        modified = true;
        totalUpdated++;
      });

      if (modified) {
        try { localStorage.setItem(storageKey, JSON.stringify(raw)); } catch (e) {}
      }
    });

    /* Also process expatur_dossiers (legacy import store) */
    try {
      var expRaw = localStorage.getItem('expatur_dossiers');
      var expDossiers = expRaw ? JSON.parse(expRaw) : [];
      var expModified = false;
      expDossiers.forEach(function (d) {
        (d.tasks || []).forEach(function (task) {
          totalScanned++;
          var cat = (task.category || task.cat || '').trim();
          if (cat && cat !== 'Diversos') return;

          var title = task.title || task.text || '';
          var inferred = null;
          if (typeof window._inferCategoryFromTitle === 'function') {
            inferred = window._inferCategoryFromTitle(title);
          } else if (typeof window.taskAutoCategory === 'function') {
            var result = window.taskAutoCategory(title);
            if (result && result !== 'Diversos') inferred = result;
          }
          if (!inferred) return;

          task.category = inferred;
          task.cat = inferred;
          expModified = true;
          totalUpdated++;
        });
      });
      if (expModified) {
        localStorage.setItem('expatur_dossiers', JSON.stringify(expDossiers));
      }
    } catch (e) {}

    /* Refresh all UIs */
    if (typeof window.tarefasRender === 'function') window.tarefasRender();
    if (typeof window.welcomeRefresh === 'function') setTimeout(window.welcomeRefresh, 50);
    if (window.taskStore && typeof window.taskStore.refreshAllTaskUIs === 'function') {
      try { window.taskStore.refreshAllTaskUIs(); } catch (e) {}
    }

    /* Toast */
    if (!silent && typeof toast === 'function') {
      if (totalUpdated > 0) {
        toast(totalUpdated + ' tarefa(s) categorizada(s) automaticamente', 'success');
      } else {
        toast('Nenhuma tarefa sem categoria encontrada (' + totalScanned + ' verificadas)', 'info');
      }
    }

    return { scanned: totalScanned, updated: totalUpdated };
  };

  /* ═══════════════════════════════════════════════════════════════════════
     §5 — Wrap tarefasRender for immediate row normalization
     ═══════════════════════════════════════════════════════════════════════ */
  var _prevTR345 = window.tarefasRender;
  window.tarefasRender = function () {
    _prevTR345.apply(this, arguments);
    /* Run normalization synchronously + with a tiny delay for safety */
    _v345NormalizeRows();
    _v345InstallDelegation();
    /* Also run after a small delay to catch any async DOM updates */
    setTimeout(function () {
      _v345NormalizeRows();
      _v345InstallDelegation();
    }, 20);
  };
  window.tpRender = window.tarefasRender;

  /* ═══════════════════════════════════════════════════════════════════════
     §6 — Hook sidebarGo to ensure Tarefas is interactive on open
     ═══════════════════════════════════════════════════════════════════════ */
  var _origSidebarGo = window.sidebarGo;
  window.sidebarGo = function (section) {
    _origSidebarGo.apply(this, arguments);
    if (section === 'tarefas') {
      /* Ensure rows are normalized after the render triggered by sidebarGo */
      setTimeout(function () {
        _v345NormalizeRows();
        _v345InstallDelegation();
        _v345StartObserver();
      }, 50);
      /* Safety net — run again after toolbar injection settles */
      setTimeout(function () {
        _v345NormalizeRows();
      }, 200);
    }
  };

  /* ═══════════════════════════════════════════════════════════════════════
     §7 — Init: start observer if Tarefas is already visible
     ═══════════════════════════════════════════════════════════════════════ */
  function _v345Init() {
    var tarefasSection = document.getElementById('section-tarefas');
    if (tarefasSection && tarefasSection.classList.contains('open')) {
      _v345NormalizeRows();
      _v345InstallDelegation();
      _v345StartObserver();
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { setTimeout(_v345Init, 500); });
  } else {
    setTimeout(_v345Init, 500);
  }

  console.log('[Patch v3.45] Fix initial Tarefas click bug + robust auto-categorize save.');
})();

// ─────────────────────────────────────

/* ═══════════════════════════════════════════════════════════════════════════
   Patch v3.46 — Category dashboard in Tarefas (chips header)
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v346) return;
  window._v346 = true;

  /* ═══════════════════════════════════════════════════════════════════════
     CSS
     ═══════════════════════════════════════════════════════════════════════ */
  var css346 = document.createElement('style');
  css346.textContent = [
    /* Category dashboard */
    '#v346-cat-dashboard { display:flex;flex-wrap:wrap;gap:0.35rem;padding:0.5rem 0.2rem 0.3rem;align-items:center; }',
    '.v346-cat-chip { display:inline-flex;align-items:center;gap:0.3rem;background:rgba(6,32,59,0.04);border:1px solid var(--border);border-radius:20px;padding:0.3rem 0.7rem;font-size:0.68rem;font-weight:600;color:var(--navy);cursor:pointer;font-family:inherit;transition:all 0.15s;white-space:nowrap; }',
    '.v346-cat-chip:hover { background:rgba(216,167,5,0.12);border-color:var(--gold,#d8a705); }',
    '.v346-cat-chip .v346-count { display:inline-flex;align-items:center;justify-content:center;min-width:18px;height:18px;border-radius:9px;background:var(--navy);color:#fff;font-size:0.55rem;font-weight:700;padding:0 4px; }',
    /* Category popup */
    '#v346-cat-popup { display:none;position:fixed;inset:0;z-index:3050;background:rgba(6,32,59,0.45);align-items:center;justify-content:center; }',
    '#v346-cat-popup.open { display:flex; }',
    '#v346-cat-popup-inner { background:#fff;border-radius:12px;max-width:600px;width:94%;max-height:80vh;overflow-y:auto;box-shadow:0 8px 40px rgba(6,32,59,0.22); }',
    '#v346-cat-popup-inner .tarefas-task-row { cursor:pointer;transition:background 0.12s; }',
    '#v346-cat-popup-inner .tarefas-task-row:hover { background:rgba(182,146,73,0.07); }'
  ].join('\n');
  document.head.appendChild(css346);

  /* (§A removed — replaced by v3.47 settings wheel + read-only modal) */

  /* ═══════════════════════════════════════════════════════════════════════
     §B — CATEGORY DASHBOARD HEADER
     ═══════════════════════════════════════════════════════════════════════ */

  /* Get task counts per category */
  function _v346GetCategoryCounts() {
    var all = [];
    if (window.taskStore && typeof window.taskStore.getAllTasks === 'function') {
      all = window.taskStore.getAllTasks();
    } else if (typeof window._v35GetAllTasks === 'function') {
      all = window._v35GetAllTasks();
    }

    var counts = {};
    all.forEach(function (t) {
      if (t.done || t.status === 'done') return; /* only pending */
      var cat = t.category || t.cat || 'Diversos';
      counts[cat] = (counts[cat] || 0) + 1;
    });
    return counts;
  }

  /* Render the category bar */
  function _v346RenderCatDashboard() {
    var existing = document.getElementById('v346-cat-dashboard');
    if (existing) existing.remove();

    var listBody = document.getElementById('tarefas-list-body');
    if (!listBody) return;
    var parent = listBody.parentNode;
    if (!parent) return;

    var cats = [];
    try {
      if (window.catStore && typeof window.catStore.getAllCategories === 'function') {
        cats = window.catStore.getAllCategories();
      }
    } catch (e) {}
    if (!cats.length) return;

    var counts = _v346GetCategoryCounts();

    var bar = document.createElement('div');
    bar.id = 'v346-cat-dashboard';

    cats.forEach(function (cat) {
      var count = counts[cat] || 0;
      var icon = (typeof _CAT_ICONS_TP !== 'undefined' && _CAT_ICONS_TP[cat]) ? _CAT_ICONS_TP[cat] + ' ' : '';
      var chip = document.createElement('button');
      chip.className = 'v346-cat-chip';
      chip.setAttribute('data-category', cat);
      chip.innerHTML = icon + _esc(cat) + ' <span class="v346-count">' + count + '</span>';
      chip.onclick = function () { _v346OpenCategoryPopup(cat); };
      bar.appendChild(chip);
    });

    /* Insert before the toolbar or list body — o toolbar pode estar noutro
       wrapper (patches v3.100+ reestruturam o DOM), validar o pai antes */
    var toolbar = document.getElementById('v343-toolbar-wrap') || document.getElementById('tp-toolbar') || document.getElementById('tp-stats-bar');
    if (toolbar && toolbar.parentNode === parent) {
      parent.insertBefore(bar, toolbar);
    } else if (toolbar && toolbar.parentNode) {
      toolbar.parentNode.insertBefore(bar, toolbar);
    } else {
      parent.insertBefore(bar, listBody);
    }
  }

  /* ── Category popup ── */
  function _v346EnsurePopupDOM() {
    if (document.getElementById('v346-cat-popup')) return;
    var popup = document.createElement('div');
    popup.id = 'v346-cat-popup';
    popup.onclick = function (e) { if (e.target === popup) _v346CloseCategoryPopup(); };
    popup.innerHTML =
      '<div id="v346-cat-popup-inner">'
      + '<div style="padding:1rem 1.2rem 0.7rem;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;">'
      +   '<div style="display:flex;align-items:center;gap:0.5rem;">'
      +     '<span id="v346-cat-popup-icon" style="font-size:1.2rem;"></span>'
      +     '<span id="v346-cat-popup-title" style="font-size:0.95rem;font-weight:700;color:var(--navy);"></span>'
      +     '<span id="v346-cat-popup-count" style="font-size:0.68rem;color:var(--navy-faint);"></span>'
      +   '</div>'
      +   '<button onclick="_v346CloseCategoryPopup()" style="background:none;border:none;cursor:pointer;font-size:1.2rem;color:var(--navy-faint);padding:0 4px;">✕</button>'
      + '</div>'
      + '<div id="v346-cat-popup-list" style="padding:0.5rem 0;max-height:60vh;overflow-y:auto;"></div>'
      + '</div>';
    document.body.appendChild(popup);

    /* Install delegation on the popup list */
    var popupList = popup.querySelector('#v346-cat-popup-list');
    if (popupList) {
      popupList.addEventListener('click', function (e) {
        if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'BUTTON')) return;
        var row = e.target.closest ? e.target.closest('.tarefas-task-row[data-task-id]') : null;
        if (!row) return;
        e.stopPropagation();

        var taskId = row.getAttribute('data-task-id');
        var taskRef = row.getAttribute('data-task-ref') || '';
        if (!taskId) return;
        var tid = isNaN(Number(taskId)) ? taskId : Number(taskId);

        /* Close the category popup first */
        _v346CloseCategoryPopup();

        /* Open the task using the existing system */
        var task = null;
        if (window.taskStore && typeof window.taskStore.getTaskById === 'function') {
          task = window.taskStore.getTaskById(tid);
        }

        /* ALL tasks open locally via _tarefasOpenTask — no Ticketing navigation */
        if (typeof window._tarefasOpenTask === 'function') {
          window._tarefasOpenTask(tid, taskRef);
        }
      });
    }
  }

  function _v346OpenCategoryPopup(category) {
    _v346EnsurePopupDOM();

    var popup = document.getElementById('v346-cat-popup');
    var titleEl = document.getElementById('v346-cat-popup-title');
    var iconEl = document.getElementById('v346-cat-popup-icon');
    var countEl = document.getElementById('v346-cat-popup-count');
    var listEl = document.getElementById('v346-cat-popup-list');

    if (!popup || !listEl) return;

    /* Get tasks in this category */
    var all = [];
    if (window.taskStore && typeof window.taskStore.getAllTasks === 'function') {
      all = window.taskStore.getAllTasks();
    } else if (typeof window._v35GetAllTasks === 'function') {
      all = window._v35GetAllTasks();
    }

    var filtered = all.filter(function (t) {
      var cat = t.category || t.cat || 'Diversos';
      return cat === category;
    });

    /* Sort: pending first, then by due date */
    filtered.sort(function (a, b) {
      var aDone = !!(a.done || a.status === 'done');
      var bDone = !!(b.done || b.status === 'done');
      if (aDone !== bDone) return aDone ? 1 : -1;
      var aD = a.dueDate || a.due || '';
      var bD = b.dueDate || b.due || '';
      if (aD && bD) return aD < bD ? -1 : 1;
      if (aD) return -1;
      if (bD) return 1;
      return 0;
    });

    /* Update header */
    var icon = (typeof _CAT_ICONS_TP !== 'undefined' && _CAT_ICONS_TP[category]) ? _CAT_ICONS_TP[category] : '📌';
    if (iconEl) iconEl.textContent = icon;
    if (titleEl) titleEl.textContent = category;
    if (countEl) countEl.textContent = filtered.length + ' tarefa(s)';

    /* Render rows — reuse the same row structure as Tarefas */
    if (filtered.length === 0) {
      listEl.innerHTML = '<div style="text-align:center;padding:2rem;color:var(--navy-faint);font-size:0.78rem;">Nenhuma tarefa nesta categoria.</div>';
    } else {
      listEl.innerHTML = filtered.map(function (t) {
        var isDone = !!(t.done || t.status === 'done');
        var prio = (t.priority || t.prio || 'normal').replace('normale', 'normal');
        var title = t.title || t.text || '(sem título)';
        var ref = t._ref || '?';
        var prioMap = {haute:'Alta',alta:'Alta',high:'Alta',normal:'Normal',normale:'Normal',basse:'Baixa',baixa:'Baixa',low:'Baixa'};
        var prioLabel = prioMap[prio] || prio;
        var prioCls = (prio === 'haute' || prio === 'alta' || prio === 'high') ? 'haute' : (prio === 'basse' || prio === 'baixa' || prio === 'low') ? 'basse' : 'normale';

        var dueStr = '', dueColor = 'var(--navy-faint)';
        if (t.dueDate) {
          try {
            var d = new Date(t.dueDate);
            if (!isNaN(d.getTime())) {
              dueStr = d.toLocaleDateString('fr-FR', {day:'2-digit',month:'2-digit'});
              if (!isDone) {
                var ms = d - new Date();
                if (ms < 0) dueColor = 'var(--red)';
                else if (ms < 86400000) dueColor = '#e07b00';
              }
            }
          } catch (_) {}
        }

        return '<div class="tarefas-task-row" data-task-id="' + t.id + '" data-task-ref="' + _esc(ref) + '" '
          + 'style="padding:0.55rem 1rem;display:flex;align-items:center;gap:0.6rem;cursor:pointer;">'
          + '<div style="flex:1;min-width:0;">'
          +   '<div style="font-size:0.82rem;color:var(--navy);' + (isDone ? 'text-decoration:line-through;opacity:0.45;' : 'font-weight:500;') + ';">'
          +     _esc(title)
          +   '</div>'
          +   '<div style="display:flex;gap:0.4rem;align-items:center;margin-top:0.15rem;flex-wrap:wrap;">'
          +     '<span style="font-size:0.6rem;color:var(--navy-faint);background:rgba(6,32,59,0.06);border-radius:8px;padding:1px 6px;">' + _esc(ref) + '</span>'
          +     (dueStr ? '<span style="font-size:0.6rem;color:' + dueColor + ';">⏰ ' + dueStr + '</span>' : '')
          +   '</div>'
          + '</div>'
          + '<div style="flex:0 0 auto;">'
          +   '<span class="tarefas-task-prio ' + prioCls + '" style="font-size:0.55rem;">' + prioLabel + '</span>'
          + '</div>'
          + (isDone ? '<span style="font-size:0.75rem;">✅</span>' : '')
          + '</div>';
      }).join('');
    }

    /* Show popup */
    popup.classList.add('open');
  }
  window._v346OpenCategoryPopup = _v346OpenCategoryPopup;

  function _v346CloseCategoryPopup() {
    var popup = document.getElementById('v346-cat-popup');
    if (popup) popup.classList.remove('open');
  }
  window._v346CloseCategoryPopup = _v346CloseCategoryPopup;

  /* ═══════════════════════════════════════════════════════════════════════
     §C — Hook tarefasRender to refresh category dashboard
     ═══════════════════════════════════════════════════════════════════════ */
  var _prevTR346 = window.tarefasRender;
  window.tarefasRender = function () {
    _prevTR346.apply(this, arguments);
    setTimeout(_v346RenderCatDashboard, 12);
  };
  window.tpRender = window.tarefasRender;

  /* ═══════════════════════════════════════════════════════════════════════
     §D — Init
     ═══════════════════════════════════════════════════════════════════════ */
  function _v346Init() {
    _v346RenderCatDashboard();
    _v346EnsurePopupDOM();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { setTimeout(_v346Init, 450); });
  } else {
    setTimeout(_v346Init, 450);
  }

  console.log('[Patch v3.46] Category dashboard.');
})();

