        if (ref) {
          storageKey = 'tasks_v2_' + ref;
          try { allTasks = JSON.parse(localStorage.getItem(storageKey) || '[]'); } catch (e) { allTasks = []; }
        }
        /* Ensure the task itself is in allTasks */
