/* ══════════════════════════════════════════════════════════════════════════
   Patch v3.53 — Definitive Tarefas local opener lifecycle fix
   Guard: window._v353

   ROOT CAUSE ANALYSIS
   ───────────────────
   v3.43's tarefasRender wrapper calls its CLOSURE-SCOPED _v343InstallDelegation
   via a 5ms setTimeout after every render. This local function cannot be
   overridden via window._v343InstallDelegation (v3.51's neutralization fails).
   It removes the current _v343Delegated handler and installs a NEW v3.43
   handler that splits linked→_openTaskAndPopup (Ticketing) / unlinked→local.
   v3.51's _v351InstallDelegation runs at 20ms — a RACE CONDITION.
   Result: first click works (v3.51 init wins), but after close/rerender,
   v3.43's 5ms handler can win, routing linked tasks to Ticketing.

   On re-entry (leave Tarefas → return), v3.45's MutationObserver can
   also reinstall old delegation.

   FIX: CAPTURE-PHASE event listener.
   ─────────────────────────────────
   Capture phase fires BEFORE bubble phase (including inline onclick).
   A single capture handler on #tarefas-list-body intercepts ALL task
   row clicks before any competing handler sees them.
   stopImmediatePropagation() kills the inline onclick + all bubble handlers.
   Routes everything through _tarefasOpenTask → local popup.
   Race conditions become irrelevant: capture always wins.

   ADDITIONAL:
   - Kill v3.45 MutationObserver (prevents old handler reinstall)
   - Reassert capture handler after closeTaskDetail restore + rerender
   - Reassert on sidebarGo('tarefas') re-entry
   - _v345NormalizeRows still runs (sets data-task-id) — useful
   ══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v353) return;
  window._v353 = true;
  /* v3.53 body REMOVED — capture-phase handler, _tarefasOpenTask wrapper,
     openTaskEverywhere intercept all superseded by v3.51.
     Only _v353Ensure is preserved as a no-op for v3.54 compatibility. */
  window._v353Ensure = function () {};
  console.log('[Patch v3.53] REMOVED — superseded by v3.51.');
  return; /* early exit — old body below is dead code */

  function _v353InstallCapture() {
    var listBody = document.getElementById('tarefas-list-body');
    if (!listBody || listBody._v353Capture) return;

    listBody._v353Capture = function (e) {
      /* Let checkboxes and buttons through */
      if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'BUTTON' ||
          e.target.tagName === 'SELECT' || e.target.tagName === 'TEXTAREA')) return;

      var row = e.target.closest ? e.target.closest('.tarefas-task-row') : null;
      if (!row) return;

      /* Kill ALL propagation — no inline onclick, no bubble handlers */
      e.stopImmediatePropagation();
      e.preventDefault();

      /* Get task info from data attributes (set by _v345NormalizeRows) */
      var taskId  = row.getAttribute('data-task-id') || '';
      var taskRef = row.getAttribute('data-task-ref') || '';

      /* Fallback: extract from inline onclick text if data attr missing */
      if (!taskId) {
        var oc = row.getAttribute('onclick') || '';
        var m  = oc.match(/openTaskEverywhere\s*\(\s*(\d+)/);
        if (m) taskId = m[1];
      }

      if (!taskId) return;
      var tid = isNaN(Number(taskId)) ? taskId : Number(taskId);

      if (typeof window._tarefasOpenTask === 'function') {
        window._tarefasOpenTask(tid, taskRef);
      }
    };

    /* CAPTURE: true — this is the key */
    listBody.addEventListener('click', listBody._v353Capture, true);
  }

  /* ═══════════════════════════════════════════════════════════════════════
     §2 — KILL v3.45 MUTATIONOBSERVER
     It reinstalls _v345InstallDelegation on DOM changes, which is
     harmless now (capture wins) but wastes cycles and adds confusion.
     ═══════════════════════════════════════════════════════════════════════ */
  function _v353KillObserver() {
    var listBody = document.getElementById('tarefas-list-body');
    if (listBody && listBody._v345Observer) {
      listBody._v345Observer.disconnect();
      listBody._v345Observer = null;
    }
  }

  /* ═══════════════════════════════════════════════════════════════════════
     §3 — ENSURE function: normalize rows + install capture handler
     Called after every render, close, and re-entry.
     ═══════════════════════════════════════════════════════════════════════ */
  function _v353Ensure() {
    /* _v345NormalizeRows sets data-task-id/data-task-ref on rows */
    if (typeof window._v345NormalizeRows === 'function') {
      try { window._v345NormalizeRows(); } catch (e) {}
    }
    _v353InstallCapture();
    _v353KillObserver();
  }
  window._v353Ensure = _v353Ensure;

  /* ═══════════════════════════════════════════════════════════════════════
     §4 — WRAP _tarefasOpenTask to reassert after close
     After v3.51's closeTaskDetail restores + rerenders, we must
     re-ensure the capture handler and row normalization.
     ═══════════════════════════════════════════════════════════════════════ */
  var _orig353TarefasOpen = window._tarefasOpenTask;

  window._tarefasOpenTask = function (taskId, ref) {
    _orig353TarefasOpen.call(this, taskId, ref);

    /* After openTaskDetail ran, closeTaskDetail is now v3.51's override.
       Wrap it to add our reassert step after the close completes. */
    var v351Close = window.closeTaskDetail;
    if (v351Close && !v351Close._v353Wrapped) {
      var wrappedClose = function () {
        v351Close.apply(this, arguments);
        /* v3.51's close calls setTimeout(tarefasRender, 0).
           Our ensure must run AFTER that render completes.
           tarefasRender is sync (the base render), but the wrapper chain
           schedules timeouts at 5ms/20ms/etc. Run after all settle. */
        setTimeout(_v353Ensure, 40);
        setTimeout(_v353Ensure, 300);
      };
      wrappedClose._v353Wrapped = true;
      window.closeTaskDetail = wrappedClose;
    }
  };

  /* Keep aliases pointing to the same function */
  window._openTaskDetailInTarefas  = window._tarefasOpenTask;
  window._openStandaloneTaskDetail = window._tarefasOpenTask;

  /* ═══════════════════════════════════════════════════════════════════════
     §5 — HOOK sidebarGo for re-entry into Tarefas
     ═══════════════════════════════════════════════════════════════════════ */
  var _prevSidebar353 = window.sidebarGo;
  window.sidebarGo = function (section) {
    _prevSidebar353.apply(this, arguments);
    if (section === 'tarefas') {
      /* Run ensure after sidebarGo's tarefasRender completes */
      setTimeout(_v353Ensure, 60);
      setTimeout(_v353Ensure, 350);
    }
  };

  /* ═══════════════════════════════════════════════════════════════════════
     §6 — HOOK tarefasRender for direct calls
     Ensure capture handler survives every render, including calls from
     auto-categorize, filter changes, etc.
     ═══════════════════════════════════════════════════════════════════════ */
  var _prevTR353 = window.tarefasRender;
  window.tarefasRender = function () {
    try { _prevTR353.apply(this, arguments); } catch (e) {
      console.warn('[v3.53] tarefasRender chain error:', e);
    }
    /* Synchronous ensure — sets data attrs + capture handler immediately */
    _v353Ensure();
    /* Safety pass after all wrapper timeouts settle */
    setTimeout(_v353Ensure, 40);
  };
  window.tpRender = window.tarefasRender;

  /* ═══════════════════════════════════════════════════════════════════════
     §7 — NEUTRALIZE v3.45 taskStore.openTaskEverywhere linked/unlinked
           split (belt-and-suspenders — capture already wins, but this
           ensures the wrapper chain can't route to Ticketing even if
           an inline onclick somehow fires).
     ═══════════════════════════════════════════════════════════════════════ */
  if (window.taskStore && typeof window.taskStore.openTaskEverywhere === 'function') {
    var _origOTE353 = window.taskStore.openTaskEverywhere;
    window.taskStore.openTaskEverywhere = function (taskId, opts) {
      if (typeof window._currentSection !== 'undefined' && window._currentSection === 'tarefas') {
        /* ALWAYS local. No linked/unlinked split. */
        var task = null;
        if (typeof window.taskStore.getTaskById === 'function') {
          task = window.taskStore.getTaskById(taskId);
        }
        window._tarefasOpenTask(taskId, (task && task._ref) || '');
        return;
      }
      _origOTE353.apply(this, arguments);
    };
  }

  /* ═══════════════════════════════════════════════════════════════════════
     INIT
     ═══════════════════════════════════════════════════════════════════════ */
  function _v353Init() {
    _v353Ensure();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { setTimeout(_v353Init, 800); });
  } else {
    setTimeout(_v353Init, 800);
  }

  console.log('[Patch v3.53] Capture-phase Tarefas click handler — bypasses all bubble-phase conflicts.');
})();

