/* ═══════════════════════════════════════════════════════════════════════════
   Patch v3.62 — Clear stale passport UI on new blank ticketing

   BUG: Opening a new dossier / new ticketing shows the PREVIOUS dossier's
   passport thumbnail, scan preview, and prefilled passport fields.

   ROOT CAUSE:
   - createNewDossier() calls _dossierResetUI() which only clears fields
     in _DOSSIER_FIELDS — client/passport fields are NOT in that list.
   - _dossierLoad() calls _cliLoadPassportThumb() which loads from
     expatur_cli_passport_{ref} — correct for the new ref, BUT the DOM
     still has old scan preview, result card, and passport input values
     from the previous dossier.
   - switchDossier() similarly doesn't clear client state.
   - clientLoad(ref) exists but is NEVER called automatically.
   - The scan globals (_cliPassportFields, _cliPassportFile) persist
     across dossier switches in memory.

   FIX:
   1) Create _cliClearPassportUIState() — single authoritative reset helper
   2) Hook into createNewDossier, switchDossier, _dossierResetUI
   3) Harden _cliLoadPassportThumb with client-presence guard
   4) On dossier switch, call clientLoad(newRef) to restore correct client
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v362) return;
  window._v362 = true;

  /* ═══════════════════════════════════════════════════════════════════════
     §1 — _cliClearPassportUIState(opts)
     Single authoritative reset for ALL passport-related transient state.
     opts.clearFields: also clear passport input values (for blank dossier)
     opts.clearAllClient: also clear ALL client input fields
     ═══════════════════════════════════════════════════════════════════════ */
  function _cliClearPassportUIState(opts) {
    opts = opts || {};

    /* 1a. Clear transient scan globals */
    window._cliPassportFields = null;
    window._cliPassportFile = null;

    /* 1b. Clear scan preview image */
    var previewImg = document.getElementById('cli-scan-preview-img');
    if (previewImg) { previewImg.style.display = 'none'; previewImg.src = ''; }

    /* 1c. Clear scan result card */
    var resultCard = document.getElementById('cli-scan-result-card');
    if (resultCard) resultCard.style.display = 'none';

    /* 1d. Clear scan result grid content */
    var resultGrid = document.getElementById('cli-scan-result-grid');
    if (resultGrid) resultGrid.innerHTML = '';

    /* 1e. Disable apply button */
    var applyBtn = document.getElementById('cli-scan-apply-btn');
    if (applyBtn) applyBtn.disabled = true;

    /* 1f. Clear scan status text */
    var scanStatus = document.getElementById('cli-scan-status');
    if (scanStatus) scanStatus.textContent = '';

    /* 1g. Hide passport thumbnail */
    var thumbWrap = document.getElementById('cli-passport-thumb');
    if (thumbWrap) thumbWrap.style.display = 'none';

    /* 1h. Clear thumbnail image source */
    var thumbImg = document.getElementById('cli-passport-thumb-img');
    if (thumbImg) thumbImg.src = '';

    /* 1i. Clear thumbnail labels */
    if (thumbWrap) {
      var nameEl = thumbWrap.querySelector('.cli-pp-name');
      if (nameEl) nameEl.textContent = '';
      var dateEl = thumbWrap.querySelector('.cli-pp-date');
      if (dateEl) dateEl.textContent = '';
    }

    /* 1j. Clear passport input fields when requested (blank dossier) */
    if (opts.clearFields) {
      var ppInput = document.getElementById('cli-passport');
      if (ppInput) ppInput.value = '';
      var ppExp = document.getElementById('cli-passport-exp');
      if (ppExp) ppExp.value = '';
    }

    /* 1k. Clear ALL client input fields when requested (brand new dossier) */
    if (opts.clearAllClient) {
      var _clientFields = [
        'cli-civilite', 'cli-prenom', 'cli-nom', 'cli-dob',
        'cli-nationalite', 'cli-passport', 'cli-passport-exp',
        'cli-email', 'cli-tel', 'cli-whatsapp',
        'cli-adresse', 'cli-cp', 'cli-ville', 'cli-pays', 'cli-notes'
      ];
      _clientFields.forEach(function (fid) {
        var el = document.getElementById(fid);
        if (!el) return;
        if (el.tagName === 'SELECT') el.selectedIndex = 0;
        else el.value = '';
      });
    }
  }
  window._cliClearPassportUIState = _cliClearPassportUIState;

  /* ═══════════════════════════════════════════════════════════════════════
     §2 — _cliHasSelectedClient()
     Returns true only if there is a real client name in the form.
     ═══════════════════════════════════════════════════════════════════════ */
  function _cliHasSelectedClient() {
    var nom = (document.getElementById('cli-nom') || {}).value || '';
    var prenom = (document.getElementById('cli-prenom') || {}).value || '';
    var paxName = (document.getElementById('pax-name-1') || {}).value || '';
    return !!(nom.trim() || prenom.trim() || paxName.trim());
  }
  window._cliHasSelectedClient = _cliHasSelectedClient;

  /* ═══════════════════════════════════════════════════════════════════════
     §3 — HOOK: createNewDossier
     After creating a new blank dossier, clear ALL passport + client state.
     ═══════════════════════════════════════════════════════════════════════ */
  var _origCreateNewDossier62 = window.createNewDossier;
  window.createNewDossier = function (prefill) {
    /* Call original — creates dossier, resets UI, sets new ref */
    if (typeof _origCreateNewDossier62 === 'function') {
      _origCreateNewDossier62.apply(this, arguments);
    }

    /* Now clear stale passport + client state */
    var hasPrefillClient = !!(prefill && prefill.client);
    _cliClearPassportUIState({
      clearFields: true,
      clearAllClient: !hasPrefillClient /* clear all client fields unless prefill provides one */
    });

    /* If prefill has a client name, load their data from DB if available */
    if (hasPrefillClient) {
      _v362TryLoadClientFromDB(prefill.client);
    }
  };

  /* ═══════════════════════════════════════════════════════════════════════
     §4 — HOOK: switchDossier
     On dossier switch, clear stale passport state, then load correct
     client data for the target dossier.
     ═══════════════════════════════════════════════════════════════════════ */
  var _origSwitchDossier62 = window.switchDossier;
  window.switchDossier = function (id) {
    /* Clear stale passport UI BEFORE the switch */
    _cliClearPassportUIState({ clearFields: true, clearAllClient: true });

    /* Call original — loads dossier, calls _dossierResetUI + _dossierLoad */
    if (typeof _origSwitchDossier62 === 'function') {
      _origSwitchDossier62.apply(this, arguments);
    }

    /* After load, restore correct client data for this dossier */
    setTimeout(function () {
      var ref = (document.getElementById('booking-ref') || {}).value || '';
      if (ref && typeof window.clientLoad === 'function') {
        window.clientLoad(ref);
      }
      /* Load passport thumb for this dossier (only if client data exists) */
      if (_cliHasSelectedClient()) {
        if (typeof window._cliLoadPassportThumb === 'function') {
          window._cliLoadPassportThumb();
        }
      } else {
        /* No client for this dossier → ensure passport stays hidden */
        _cliClearPassportUIState({ clearFields: false });
      }
    }, 150);
  };

  /* ═══════════════════════════════════════════════════════════════════════
     §5 — HOOK: _dossierResetUI
     After resetting dossier fields, also clear passport state.
     ═══════════════════════════════════════════════════════════════════════ */
  var _origDossierResetUI62 = window._dossierResetUI;
  window._dossierResetUI = function () {
    if (typeof _origDossierResetUI62 === 'function') {
      _origDossierResetUI62.apply(this, arguments);
    }
    /* Clear passport UI — fields will be restored by clientLoad if needed */
    _cliClearPassportUIState({ clearFields: true, clearAllClient: true });
  };

  /* ═══════════════════════════════════════════════════════════════════════
     §6 — HOOK: _dossierLoad
     After loading a dossier, restore correct client + passport state.
     ═══════════════════════════════════════════════════════════════════════ */
  var _origDossierLoad62 = window._dossierLoad;
  window._dossierLoad = function (id) {
    /* Call original — resets UI, loads dossier fields, calls _cliLoadPassportThumb */
    if (typeof _origDossierLoad62 === 'function') {
      _origDossierLoad62.apply(this, arguments);
    }

    /* After fields are set, load the correct client data for this dossier */
    setTimeout(function () {
      var ref = (document.getElementById('booking-ref') || {}).value || '';
      if (ref && typeof window.clientLoad === 'function') {
        window.clientLoad(ref);
      }
      /* Re-check: if no client after load, hide passport again */
      setTimeout(function () {
        if (!_cliHasSelectedClient()) {
          _cliClearPassportUIState({ clearFields: false });
        }
      }, 50);
    }, 100);
  };

  /* ═══════════════════════════════════════════════════════════════════════
     §7 — HARDEN: _cliLoadPassportThumb
     Add guard: don't show thumb if no client is selected.
     ═══════════════════════════════════════════════════════════════════════ */
  var _origLoadThumb62 = window._cliLoadPassportThumb;
  window._cliLoadPassportThumb = function () {
    /* Guard: if no client is selected, hide thumb and return */
    if (!_cliHasSelectedClient()) {
      var thumbWrap = document.getElementById('cli-passport-thumb');
      if (thumbWrap) thumbWrap.style.display = 'none';
      return;
    }
    /* Has client → call original to load from dossier-scoped storage */
    if (typeof _origLoadThumb62 === 'function') {
      _origLoadThumb62.apply(this, arguments);
    }
  };

  /* ═══════════════════════════════════════════════════════════════════════
     §8 — HELPER: try to load client from global DB by name
     Used when createNewDossier has a prefill.client string.
     ═══════════════════════════════════════════════════════════════════════ */
  function _v362TryLoadClientFromDB(clientName) {
    if (!clientName) return;
    var norm = clientName.trim().toUpperCase();
    try {
      var db = JSON.parse(localStorage.getItem('expatur_clients_db') || '[]');
      for (var i = 0; i < db.length; i++) {
        var c = db[i];
        var fullName = ((c.prenom || '') + ' ' + (c.nom || '')).trim().toUpperCase();
        if (fullName === norm || (c.nom || '').toUpperCase() === norm) {
          /* Found — load into client fields */
          if (typeof window.cliDbLoadClient === 'function') {
            window.cliDbLoadClient(c.id);
          }
          return;
        }
      }
    } catch (e) {}
  }

  /* ═══════════════════════════════════════════════════════════════════════
     INIT — clear any stale state if currently on a blank dossier
     ═══════════════════════════════════════════════════════════════════════ */
  function _v362Init() {
    /* If current dossier has no client, clear passport UI */
    if (!_cliHasSelectedClient()) {
      _cliClearPassportUIState({ clearFields: true });
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { setTimeout(_v362Init, 800); });
  } else {
    setTimeout(_v362Init, 800);
  }

  console.log('[Patch v3.62] Stale passport cleared on new blank ticketing.');
})();

