(function () {
  'use strict';
  if (window._v369c) return;
  window._v369c = true;

  /* ═══════════════════════════════════════════════════════════════════
     PAYOUT BUTTON — WordPress-safe implementation (v3.86)

     Strategy:
     • The button lives in static HTML: <button id="qt-payout-btn" class="qt-payout-btn">
     • Visibility is PURELY CSS-class-driven: .is-visible shows it
     • JS only toggles the class and binds the click — never creates/inserts
     • A MutationObserver re-binds if WordPress theme/plugin rerenders the bar
     • Multiple init hooks (DOMContentLoaded, load, quotingSwitch, section open)
     ═══════════════════════════════════════════════════════════════════ */

  var _payoutBound86 = false; /* de-dup flag for click binding */

  /* §A — Fallback: create the button if the static HTML is missing
     (e.g. someone loaded an older HTML shell). Runs once. */
  function _ensurePayoutButton86() {
    if (document.getElementById('qt-payout-btn')) return;
    var host = document.getElementById('qt-tabs-bar')
            || document.querySelector('#section-quoting .section-page-header');
    if (!host) return;
    var btn = document.createElement('button');
    btn.id = 'qt-payout-btn';
    btn.className = 'qt-payout-btn';
    btn.type = 'button';
    btn.textContent = '\u25B6 PAYOUT';
    var sep = host.querySelector('.qt-tab-sep');
    if (sep) host.insertBefore(btn, sep);
    else host.appendChild(btn);
  }

  /* §B — Visibility sync: toggle .is-visible based on active tab + booking state.
     Uses both _lastQuotingTab AND the DOM active-tab class as source of truth. */
  function _syncPayoutButton() {
    _ensurePayoutButton86();
    var btn = document.getElementById('qt-payout-btn');
    if (!btn) return;

    /* Determine active tab from DOM first, fall back to JS state */
    var activeTab = window._lastQuotingTab || 'vols';
    try {
      var activeEl = document.querySelector('#qt-tabs-bar .dv-tab.active');
      if (activeEl && activeEl.id) {
        var m = activeEl.id.match(/^qt-tab-(.+)$/);
        if (m) activeTab = m[1];
      }
    } catch(e) {}

    /* Sempre visível na aba Tarification — mesmo com booking já feito.
       Esconder quando booked fazia o botão "desaparecer" ao reabrir um
       dossier já pago (flags hidratados do Supabase) e conflitava com o
       ui-fixes.js, que o força visível. Clicar de novo é idempotente. */
    if (activeTab === 'couts') {
      btn.classList.add('is-visible');
    } else {
      btn.classList.remove('is-visible');
    }
  }
  window._syncPayoutButton = _syncPayoutButton;
  window._installPayoutButton = _ensurePayoutButton86; /* compat alias */

  /* §C — Click binding: full payout→payment flow with try/catch on each step */
  function _bindPayoutButton() {
    var btn = document.getElementById('qt-payout-btn');
    if (!btn) return;
    if (btn._payout86Bound) return; /* prevent double-bind */
    btn._payout86Bound = true;

    /* Remove any legacy inline onclick */
    btn.removeAttribute('onclick');

    btn.addEventListener('click', function(e) {
      e.stopPropagation();

      /* 1. Require active dossier */
      var id = null;
      try { id = localStorage.getItem('expatur_active_dossier') || null; } catch(ex) {}
      if (!id) {
        if (typeof toast === 'function') {
          toast('Veuillez d\'abord ouvrir un dossier (cliquez sur un ticket dans la barre latérale)', 'error');
        } else {
          alert('Veuillez d\'abord ouvrir un dossier avant de cliquer sur PAYOUT.');
        }
        return;
      }

      /* 2. Set booked flag */
      try {
        localStorage.setItem('expatur_booked_' + id, '1');
        if (!localStorage.getItem('expatur_bookedAt_' + id)) {
          localStorage.setItem('expatur_bookedAt_' + id, new Date().toISOString());
        }
      } catch(ex) { console.warn('[v3.86] booking flag error:', ex); }

      /* 3. Unlock booking-phase tabs */
      try { if (typeof window._applyBookingTabState === 'function') window._applyBookingTabState(); }
      catch(ex) { console.warn('[v3.86] _applyBookingTabState:', ex); }

      try { if (typeof window._dossierRenderTabs === 'function') window._dossierRenderTabs(); }
      catch(ex) { console.warn('[v3.86] _dossierRenderTabs:', ex); }

      /* 4. Switch to Paiement tab */
      var switched = false;
      try {
        if (typeof window.quotingSwitch === 'function') {
          window.quotingSwitch('paiement');
          switched = true;
        }
      } catch(ex) { console.warn('[v3.86] quotingSwitch:', ex); }

      if (!switched) {
        /* DOM-level fallback */
        try {
          ['vols','client','couts','paiement','billet','docs','tasks','finance'].forEach(function(t) {
            var tb = document.getElementById('qt-tab-' + t);
            if (tb) tb.classList.toggle('active', t === 'paiement');
            var pn = document.getElementById('dv-panel-' + t);
            if (pn) pn.classList.toggle('active', t === 'paiement');
          });
          window._lastQuotingTab = 'paiement';
        } catch(ex) { console.warn('[v3.86] fallback switch:', ex); }
      }

      /* 5. Open the emission / payment modal */
      try {
        if (typeof window.openEmissionModal === 'function') {
          setTimeout(function() {
            try { window.openEmissionModal(); } catch(ex) { console.warn('[v3.86] openEmissionModal:', ex); }
          }, 250);
        }
      } catch(ex) {}

      /* 6. Sync button visibility (should hide now that booking is enabled) */
      _syncPayoutButton();

      /* 7. Scroll to top */
      try {
        var ph = document.getElementById('quoting-panels-host');
        if (ph) ph.scrollTop = 0; else window.scrollTo({ top: 0, behavior: 'smooth' });
      } catch(ex) {}

      if (typeof toast === 'function') toast('Réservation confirmée — passage en Paiement', 'success');
    });
  }
  window._bindPayoutButton = _bindPayoutButton;

  /* §D — Hook into quotingSwitch (wrapper chain) — but also set up
     direct listeners and observer so we never depend solely on this. */
  var _prev369cQS = window.quotingSwitch;
  window.quotingSwitch = function (tab) {
    try { if (typeof _prev369cQS === 'function') _prev369cQS.apply(this, arguments); } catch(ex) {}
    _syncPayoutButton();
  };

  /* §E — MutationObserver: if WordPress rerenders #qt-tabs-bar or
     #section-quoting, re-bind the button and re-sync visibility. */
  function _observeQuotingHeader86() {
    var target = document.getElementById('section-quoting')
              || document.getElementById('qt-tabs-bar');
    if (!target || typeof MutationObserver === 'undefined') return;

    var observer = new MutationObserver(function(mutations) {
      var needsRebind = false;
      for (var i = 0; i < mutations.length; i++) {
        if (mutations[i].addedNodes && mutations[i].addedNodes.length) {
          needsRebind = true;
          break;
        }
      }
      if (needsRebind) {
        /* The bar may have been replaced — re-ensure, re-bind, re-sync */
        var btn = document.getElementById('qt-payout-btn');
        if (btn && !btn._payout86Bound) {
          _bindPayoutButton();
        } else if (!btn) {
          _ensurePayoutButton86();
          _bindPayoutButton();
        }
        _syncPayoutButton();
      }
    });
    observer.observe(target, { childList: true, subtree: true });
  }

  /* §F — Direct tab-button click listeners (bypass wrapper chain) */
  function _attachDirectTabListeners86() {
    var bar = document.getElementById('qt-tabs-bar');
    if (!bar) return;
    if (bar._tabListeners86) return;
    bar._tabListeners86 = true;
    bar.querySelectorAll('.dv-tab').forEach(function(tab) {
      tab.addEventListener('click', function() {
        setTimeout(_syncPayoutButton, 60);
      });
    });
  }

  /* §G — Multi-hook init: DOMContentLoaded, window.load, and immediate if ready */
  function _fullInit86() {
    _ensurePayoutButton86();
    _bindPayoutButton();
    _syncPayoutButton();
    _attachDirectTabListeners86();
    _observeQuotingHeader86();
  }

  /* Immediate if DOM already loaded */
  if (document.readyState !== 'loading') {
    setTimeout(_fullInit86, 100);
  }
  /* DOMContentLoaded — first chance */
  document.addEventListener('DOMContentLoaded', function() { setTimeout(_fullInit86, 100); });
  /* window.load — last resort for slow WordPress themes */
  window.addEventListener('load', function() { setTimeout(_fullInit86, 300); });

  /* Also re-sync after dossier switches */
  var _prev86DL = window._dossierLoad;
  if (typeof _prev86DL === 'function') {
    window._dossierLoad = function() {
      _prev86DL.apply(this, arguments);
      setTimeout(_syncPayoutButton, 200);
    };
  }

  console.log('[Patch v3.69c] PAYOUT button installer + visibility sync.');
})();

