/* ═══════════════════════════════════════════════════════════════════════
   PART K — Supplier expense row: inject "Payer" button into per-dossier
            expense table rows for partial payment access
   ═══════════════════════════════════════════════════════════════════════ */

/* We wrap the per-dossier expense renderer to inject a "Payer" button
   on each expense row that opens the partial payment modal. */

function _injectPayerButtons() {
  var tbody = document.getElementById('doss-fin-exp-body');
  if (!tbody) return;

  var dossierId = localStorage.getItem('expatur_active_dossier');
  if (!dossierId) return;

  var rows = tbody.querySelectorAll('tr');
  rows.forEach(function(tr) {
    /* Skip if already injected */
    if (tr.querySelector('.v374-payer-btn')) return;

    /* Find the expense ID from the checkbox or data attribute */
    var chk = tr.querySelector('.v322-row-chk');
    var expId = chk && chk.dataset.lid;
    if (!expId) return;

    /* Find the last td (actions column) */
    var tds = tr.querySelectorAll('td');
    if (!tds.length) return;
    var lastTd = tds[tds.length - 1];

    var btn = document.createElement('button');
    btn.className = 'v374-payer-btn';
    btn.textContent = 'Payer';
    btn.style.cssText = 'background:var(--navy,#06203b);color:#fff;border:none;border-radius:4px;padding:2px 8px;font-size:0.62rem;font-weight:700;cursor:pointer;margin-left:4px;';
    btn.addEventListener('click', function(e) {
      e.stopPropagation();
      window.openSupplierPaymentModal(dossierId, expId, {
        title: 'Paiement fournisseur'
      });
    });
    lastTd.appendChild(btn);
  });
}

/* Wrap dossFinRenderPanel if it exists */
var _prevDossFinRenderPanel = window.dossFinRenderPanel;
if (typeof _prevDossFinRenderPanel === 'function') {
  window.dossFinRenderPanel = function() {
    _prevDossFinRenderPanel.apply(this, arguments);
    setTimeout(_injectPayerButtons, 50);
  };
}

/* Also inject after per-dossier expense renderers */
var _prevV36RenderExpenses = window._v36RenderExpenses;
if (typeof _prevV36RenderExpenses === 'function') {
  window._v36RenderExpenses = function() {
    _prevV36RenderExpenses.apply(this, arguments);
    setTimeout(_injectPayerButtons, 50);
  };
}


/* ═══════════════════════════════════════════════════════════════════════
   PART L — Vue d'ensemble / Saldo devedor forn. synchronization
   ═══════════════════════════════════════════════════════════════════════ */

/* The _v36ComputeOverview function already computes totalPaid from
   exp.paidAmount and exp.status. The issue is that when status changes
   via the mutation pipeline, the data read by _v36ComputeOverview must
   see the updated paidAmount/status. Since we now persist through
   finApplySupplierPayment → localStorage, the compute function will
   read fresh data.

   To additionally ensure recomputed expense state is used, we wrap
   the overview renderer to pre-normalize all expense records. */

var _prevV36RenderOverview = window._v36RenderOverview;
if (typeof _prevV36RenderOverview === 'function') {
  window._v36RenderOverview = function(id, data) {
    /* Pre-normalize expenses in-memory before rendering */
    if (data && Array.isArray(data.expenses)) {
      data.expenses = data.expenses.map(function(e) {
        return window.finRecomputeExpenseState(e);
      });
    }
    _prevV36RenderOverview.call(this, id, data);
  };
}


