/* ══════════════════════════════════════════════════════════════════════════════
   PATCH v3.75 — OOB Full-Store Sync + Unified Overview Normalization
   ─────────────────────────────────────────────────────────────────────────────
   Two focused fixes:
     1) OOB (PIX/Virement/Cash) payments with receipt at creation or fetch time
        immediately force ALL linked stores to paid: payment history, fluxo
        lancamento, per-dossier receivable, and invoice store.
     2) Every active overview compute path normalizes supplier expenses through
        finRecomputeExpenseState before aggregation, ensuring totalPaid and
        balSupplierDue are always consistent.
   ══════════════════════════════════════════════════════════════════════════════ */
(function() {
'use strict';

/* ═══════════════════════════════════════════════════════════════════════
   §1.  OOB FULL-STORE FORCE-PAID HELPER
   ═══════════════════════════════════════════════════════════════════════

   Given a payment record that is OOB (pix/virement/cash) AND has a receipt
   URL, this helper writes "paid" into every linked store so no view shows
   a stale "pending" while payment history already says "paid".

   Stores touched:
     A. expatur_financeiro_lancamentos  (fluxo — match by dossierRef + invoiceId or amount+date)
     B. expatur_doss_finance_[id].receivables  (per-dossier receivable)
     C. expatur_em_invoice_[ref]  (invoice store — _blStoreStripeInvoice target)
     D. expatur_payments_[ref]  (payment history — already handled by finNormalizeOobPaidRecord)
*/

window._v375OobForceAllStoresPaid = function(rec) {
  if (!rec) return;
  // Do NOT force-paid later offline installments (#2+)
  if (rec._isOfflineInstallment && rec._installmentIndex > 0) return;
  var type  = ((rec.type) || '').toLowerCase();
  var isOob = type === 'pix' || type === 'virement' || type === 'cash';
  if (!isOob) return;

  var hasReceipt = !!(rec.stripeReceiptUrl || rec.receipt_pdf || rec.receiptPdfUrl);
  if (!hasReceipt) return;

  var invoiceId  = rec.stripeInvoiceId || '';
  var ref        = '';
  try {
    ref = (document.getElementById('booking-ref') || {}).value || '';
    ref = ref.trim();
  } catch(e) {}
  var dossierId  = '';
  try { dossierId = localStorage.getItem('expatur_active_dossier') || ''; } catch(e) {}
  var paidAt     = rec.paidAt || rec.registeredAt || new Date().toISOString();

  console.log('[v3.75] OOB force-paid all stores', {
    type: type, invoiceId: invoiceId, ref: ref, dossierId: dossierId, hasReceipt: true
  });

  /* ── A. Fluxo lancamentos ── */
  try {
    var lancKey  = 'expatur_financeiro_lancamentos';
    var lanc     = JSON.parse(localStorage.getItem(lancKey) || '[]');
    var lancDirty = false;

    lanc = lanc.map(function(r) {
      if (r.tipo !== 'entrada') return r;
      /* Match: same dossierRef AND (same invoiceId, or same amount+date when no invoiceId) */
      var refMatch = ref && (r.dossierRef === ref || r.dossierRef === dossierId);
      if (!refMatch) return r;

      var idMatch   = invoiceId && (r.source_id === invoiceId || r.id === invoiceId || r.nota === invoiceId);
      var amtMatch  = !invoiceId && rec.amount && (parseFloat(r.valor) === parseFloat(rec.amount));

      if (idMatch || amtMatch) {
        if (r.pago !== 'pago') {
          lancDirty = true;
          return Object.assign({}, r, {
            pago:   'pago',
            status: 'paid',
            _updAt: paidAt
          });
        }
      }
      return r;
    });

    if (lancDirty) {
      localStorage.setItem(lancKey, JSON.stringify(lanc));
      console.log('[v3.75] Fluxo lancamento forced to pago for OOB ref=' + ref);
    }
  } catch(e) { console.warn('[v3.75] fluxo force-paid error', e); }

  /* ── B. Per-dossier receivable ── */
  if (dossierId) {
    try {
      var dKey  = 'expatur_doss_finance_' + dossierId;
      var dData = JSON.parse(localStorage.getItem(dKey) || 'null');
      if (dData && Array.isArray(dData.receivables)) {
        var recvDirty = false;
        dData.receivables = dData.receivables.map(function(rv) {
          var idMatch  = invoiceId && (rv.id === invoiceId || rv.source_id === invoiceId);
          var amtMatch = !invoiceId && rec.amount && (parseFloat(rv.amount) === parseFloat(rec.amount));

          if ((idMatch || amtMatch) && rv.status !== 'paid') {
            recvDirty = true;
            return Object.assign({}, rv, {
              status:     'paid',
              pago:       'pago',
              paidAmount: rv.amount,
              paidAt:     paidAt
            });
          }
          return rv;
        });
        if (recvDirty) {
          localStorage.setItem(dKey, JSON.stringify(dData));
          console.log('[v3.75] Per-dossier receivable forced to paid for dossierId=' + dossierId);
        }
      }
    } catch(e) { console.warn('[v3.75] receivable force-paid error', e); }
  }

  /* ── C. Invoice store ── */
  if (ref) {
    try {
      var invKey = 'expatur_em_invoice_' + ref.replace(/[^a-zA-Z0-9]/g, '_');
      var invRaw = localStorage.getItem(invKey);
      if (invRaw) {
        var inv = JSON.parse(invRaw);
        if (inv && inv.status !== 'paid') {
          inv.status = 'paid';
          inv.paidAt = paidAt;
          if (!inv.receiptPdfUrl) {
            inv.receiptPdfUrl = rec.stripeReceiptUrl || rec.receipt_pdf || rec.receiptPdfUrl || '';
          }
          localStorage.setItem(invKey, JSON.stringify(inv));
          console.log('[v3.75] Invoice store forced to paid for ref=' + ref);
          /* Also update in-memory _lastStripeInvoiceData so Documents tab refreshes */
          if (window._lastStripeInvoiceData && window._lastStripeInvoiceData.invoiceId) {
            window._lastStripeInvoiceData.status = 'paid';
            if (!window._lastStripeInvoiceData.receiptPdfUrl) {
              window._lastStripeInvoiceData.receiptPdfUrl = inv.receiptPdfUrl;
            }
          }
        }
      }
    } catch(e) { console.warn('[v3.75] invoice store force-paid error', e); }
  }
};


/* ═══════════════════════════════════════════════════════════════════════
   §2.  OVERRIDE savePaymentRecord — OOB with receipt → force all stores
   ═══════════════════════════════════════════════════════════════════════
   v3.74 already wraps savePaymentRecord to normalize OOB records.
   We wrap again to ALSO call _v375OobForceAllStoresPaid so that fluxo,
   receivable, and invoice store are written as paid immediately.
*/

var _prev75SavePayRec = window.savePaymentRecord;
window.savePaymentRecord = function(record) {
  /* Let v3.74 wrapper normalize + save first */
  if (typeof _prev75SavePayRec === 'function') {
    _prev75SavePayRec(record);
  }

  /* After the record is saved, if it's OOB with receipt, force remaining stores */
  var type  = ((record && record.type) || '').toLowerCase();
  var isOob = type === 'pix' || type === 'virement' || type === 'cash';
  var hasReceipt = !!(record && (record.stripeReceiptUrl || record.receipt_pdf));

  if (isOob && hasReceipt) {
    window._v375OobForceAllStoresPaid(record);
    /* Refresh surfaces once more after force-paid writes */
    if (typeof window.finRefreshAllFinanceSurfaces === 'function') {
      setTimeout(function() {
        window.finRefreshAllFinanceSurfaces({ source: 'v375-oob-force-paid', type: type });
      }, 150);
    }
  }
};


/* ═══════════════════════════════════════════════════════════════════════
   §3.  OVERRIDE emCheckInvoiceStatus — on receipt fetch, force all stores
   ═══════════════════════════════════════════════════════════════════════
   When "Vérifier" returns status/receipt from Stripe, scan payment history
   for matching OOB records and force-paid if they now have a receipt.
*/

var _prev75EmCheck = window.emCheckInvoiceStatus;
if (typeof _prev75EmCheck === 'function') {
  window.emCheckInvoiceStatus = async function(invoiceId, dueDate) {
    /* Call the v3.74 wrapper which calls the original */
    var result = _prev75EmCheck.apply(this, arguments);

    /* After the check resolves, scan payment history for OOB records
       that now have a receipt and force-paid all stores */
    var afterCheck = function() {
      try {
        var ref = '';
        try { ref = (document.getElementById('booking-ref') || {}).value || ''; ref = ref.trim(); } catch(e) {}
        if (!ref) return;

        var payKey = 'expatur_payments_' + ref.replace(/[^a-zA-Z0-9]/g, '_');
        var hist   = JSON.parse(localStorage.getItem(payKey) || '[]');
        var dirty  = false;

        hist = hist.map(function(p) {
          /* Normalize the record itself first (v3.74 helper) */
          var norm = (typeof window.finNormalizeOobPaidRecord === 'function')
            ? window.finNormalizeOobPaidRecord(p, p) : p;

          if (norm.status !== p.status) dirty = true;

          /* Force all stores if now paid */
          var type  = ((norm.type) || '').toLowerCase();
          var isOob = type === 'pix' || type === 'virement' || type === 'cash';
          if (isOob && norm.status === 'paid') {
            window._v375OobForceAllStoresPaid(norm);
          }

          return norm;
        });

        if (dirty) {
          localStorage.setItem(payKey, JSON.stringify(hist));
        }
      } catch(e) { console.warn('[v3.75] emCheckInvoiceStatus post-hook error', e); }

      if (typeof window.finRefreshAllFinanceSurfaces === 'function') {
        window.finRefreshAllFinanceSurfaces({ source: 'v375-invoice-status-check', invoiceId: invoiceId });
      }
    };

    if (result && typeof result.then === 'function') {
      result.then(afterCheck);
    } else {
      setTimeout(afterCheck, 600);
    }
    return result;
  };
}


/* ═══════════════════════════════════════════════════════════════════════
   §4.  OVERRIDE finAutoCreateFluxoEntrada — OOB with receipt → pago
   ═══════════════════════════════════════════════════════════════════════
   The original always creates fluxo entries with status='pendente',
   even when the payment is OOB and receipt already exists.
   Wrap it so if the payment record's receipt is known, fluxo starts as 'pago'.
*/

var _prev75FluxoEntrada = window.finAutoCreateFluxoEntrada;
if (typeof _prev75FluxoEntrada === 'function') {
  window.finAutoCreateFluxoEntrada = function(opts) {
    /* Check if OOB receipt is available via recent emission context */
    if (opts && opts.status === 'pendente') {
      try {
        var ref = opts.dossierRef || '';
        if (ref) {
          var payKey = 'expatur_payments_' + ref.replace(/[^a-zA-Z0-9]/g, '_');
          var hist   = JSON.parse(localStorage.getItem(payKey) || '[]');
          /* Find most recent OOB record with receipt for this ref */
          for (var i = hist.length - 1; i >= 0; i--) {
            var p    = hist[i];
            var pType = ((p.type) || '').toLowerCase();
            var isOob = pType === 'pix' || pType === 'virement' || pType === 'cash';
            if (isOob && (p.stripeReceiptUrl || p.receipt_pdf) && p.status === 'paid') {
              opts.status = 'pago';
              console.log('[v3.75] finAutoCreateFluxoEntrada: OOB receipt detected, starting as pago');
              break;
            }
          }
        }
      } catch(e) {}
    }
    _prev75FluxoEntrada.call(this, opts);
  };
}


/* ═══════════════════════════════════════════════════════════════════════
   §5.  UNIFIED OVERVIEW NORMALIZATION
   ═══════════════════════════════════════════════════════════════════════

   The file has multiple compute layers that end up assigned to
   window._v36ComputeOverview and window.dossFIN_computeOverview:

     v3.6:   _v36ComputeOverview  (original, line ~19940)
     v3.15:  _computeOverview315  (replaces it, line ~24007)
     v3.22:  _computeOverview322  (replaces it, line ~27115)
     v3.52:  _computeOverview352  (replaces it, line ~37662)  ← AUTHORITATIVE

   The last reassignment wins: _computeOverview352 is currently live on
   window._v36ComputeOverview and window.dossFIN_computeOverview.

   All these functions read expenses with `parseFloat(e.paidAmount)` and
   status checks, but they don't normalize through finRecomputeExpenseState.
   When partial payments update paidAmount via the mutation pipeline but
   the overview function reads raw fields without re-deriving them from
   the payments[] array, the overview can drift.

   Fix:  Wrap window._v36ComputeOverview (the authoritative one) so it
   pre-normalizes data.expenses through finRecomputeExpenseState before
   computing.  Also alias dossFIN_computeOverview to the same wrapper.

   v3.74 already wrapped _v36RenderOverview, but that only normalizes
   the data object passed to the renderer — it doesn't help when the
   compute function itself loads data fresh from localStorage.  We need
   to wrap the compute function, not just the renderer.
*/

var _prev75Compute = window._v36ComputeOverview;
window._v36ComputeOverview = function(id) {
  /* Pre-normalize expenses in the per-dossier finance store BEFORE
     the compute function reads them, so it sees canonical paidAmount/status. */
  try {
    var dKey  = 'expatur_doss_finance_' + id;
    var dData = JSON.parse(localStorage.getItem(dKey) || 'null');
    if (dData && Array.isArray(dData.expenses)) {
      var dirty = false;
      dData.expenses = dData.expenses.map(function(e) {
        var norm = window.finRecomputeExpenseState(e);
        /* Check if normalization changed anything */
        if (norm.paidAmount !== (parseFloat(e.paidAmount) || 0) ||
            norm.status !== e.status ||
            norm.pago !== e.pago) {
          dirty = true;
        }
        return norm;
      });
      /* Write back only if something changed, so compute reads fresh state */
      if (dirty) {
        localStorage.setItem(dKey, JSON.stringify(dData));
      }
    }
  } catch(e) { console.warn('[v3.75] overview pre-normalize error', e); }

  /* Also normalize global lancamentos expense rows for this dossier.
     The compute functions check r.pago === 'pago' for global rows,
     which must reflect partial payment state accurately. */
  try {
    var ref    = '';
    var dd     = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null');
    if (dd && dd.fields) ref = (dd.fields['booking-ref'] || '').trim();

    if (ref) {
      var lancKey  = 'expatur_financeiro_lancamentos';
      var lanc     = JSON.parse(localStorage.getItem(lancKey) || '[]');
      var lancDirty = false;

      lanc = lanc.map(function(r) {
        if (r.tipo !== 'saida') return r;
        if (r.dossierRef !== ref && r.dossierRef !== id) return r;

        /* For global expense rows, derive pago from payments[] if they exist */
        if (Array.isArray(r.payments) && r.payments.length > 0) {
          var norm = window.finRecomputeExpenseState(r);
          var newPago = norm.pago === 'parcial' ? 'pendente' : norm.pago; /* lancamentos only support pago/pendente */
          if (r.pago !== newPago) {
            lancDirty = true;
            return Object.assign({}, r, { pago: newPago, status: norm.status, _updAt: new Date().toISOString() });
          }
        }
        return r;
      });

      if (lancDirty) {
        localStorage.setItem(lancKey, JSON.stringify(lanc));
      }
    }
  } catch(e) {}

  /* Now call the real compute function with clean data */
  return _prev75Compute.call(this, id);
};

/* Alias dossFIN_computeOverview to the same wrapped version */
window.dossFIN_computeOverview = window._v36ComputeOverview;


/* ═══════════════════════════════════════════════════════════════════════
   §6.  ENSURE finApplySupplierPayment mirrors ALL legacy fields
   ═══════════════════════════════════════════════════════════════════════
   finRecomputeExpenseState already returns status/pago/paidAmount/
   balanceAmount/payments.  But let's ensure that after ANY mutation
   the per-dossier store's expense object also has these mirrored:
     - pago (parcial is kept as 'parcial' in per-dossier store for v3.74 modal;
             in lancamentos it maps to 'pendente' since lancamentos only know pago/pendente)
     - _updAt timestamp
   This is already done by finApplySupplierPayment writing finRecomputeExpenseState
   output back to dData.expenses.  No code change needed — just verify the existing
   finRecomputeExpenseState returns all fields.  We add _updAt for audit trail.
*/

var _prev75ApplySupplier = window.finApplySupplierPayment;
window.finApplySupplierPayment = function(dossierId, expenseId, mutation) {
  var result = _prev75ApplySupplier.call(this, dossierId, expenseId, mutation);
  if (result) {
    /* Ensure _updAt is present on the persisted expense */
    try {
      var dKey  = 'expatur_doss_finance_' + dossierId;
      var dData = JSON.parse(localStorage.getItem(dKey) || 'null');
      if (dData && Array.isArray(dData.expenses)) {
        var dirty = false;
        dData.expenses = dData.expenses.map(function(e) {
          if (String(e.id) === String(expenseId)) {
            if (!e._updAt) {
              dirty = true;
              return Object.assign({}, e, { _updAt: new Date().toISOString() });
            }
          }
          return e;
        });
        if (dirty) localStorage.setItem(dKey, JSON.stringify(dData));
      }
    } catch(e) {}
  }
  return result;
};


/* ═══════════════════════════════════════════════════════════════════════
   §7.  SUMMARY LOG
   ═══════════════════════════════════════════════════════════════════════ */

console.log('[Patch v3.75] OOB Full-Store Sync + Unified Overview active.',
  'OOB paths: savePaymentRecord → _v375OobForceAllStoresPaid (fluxo+receivable+invoiceStore).',
  'emCheckInvoiceStatus → post-receipt force-paid.',
  'finAutoCreateFluxoEntrada → auto-pago when OOB receipt exists.',
  'Overview: _v36ComputeOverview (= _computeOverview352) wrapped with pre-normalization.',
  'dossFIN_computeOverview aliased to same wrapper.',
  'finApplySupplierPayment → _updAt mirror.');

})(); // end Patch v3.75

