/* ══════════════════════════════════════════════════════════════════════════════
   PATCH v3.76 — Hardened OOB Sync + Deterministic Overview Normalization
   ─────────────────────────────────────────────────────────────────────────────
   Final surgical pass.  Two remaining issues only:
     1) OOB synchronization must be fully authoritative at write-time across
        ALL stores (payment history, fluxo, receivable, invoice store).
     2) Overview "Saldo devedor forn." must use one canonical normalization rule
        through finRecomputeExpenseState before every aggregation.
   ══════════════════════════════════════════════════════════════════════════════ */
(function() {
'use strict';


/* ═══════════════════════════════════════════════════════════════════════
   §1.  REPLACE _v375OobForceAllStoresPaid WITH HARDENED VERSION
   ═══════════════════════════════════════════════════════════════════════

   The v3.75 version had two matching weaknesses:
     A. Fluxo matching: amtMatch only fired when !invoiceId, and could match
        wrong rows when multiple entries share the same amount.
     B. Receipt URL was not mirrored to fluxo or receivable rows.

   This replacement strengthens matching (invoiceId → amount+date → amount-only
   as last resort) and mirrors receipt URL + paidAt to all stores.
*/

window._v375OobForceAllStoresPaid = function(rec) {
  if (!rec) return;
  // Do NOT force-paid later offline installments (#2+)
  if (rec._isOfflineInstallment && rec._installmentIndex > 0) return;
  var type  = ((rec.type) || '').toLowerCase();
  var isOob = type === 'pix' || type === 'virement' || type === 'cash';
  if (!isOob) return;

  var hasReceipt = !!(rec.stripeReceiptUrl || rec.receipt_pdf || rec.receiptPdfUrl);
  if (!hasReceipt) return;

  var receiptUrl = rec.stripeReceiptUrl || rec.receipt_pdf || rec.receiptPdfUrl || '';
  var invoiceId  = rec.stripeInvoiceId || '';
  var recAmount  = parseFloat(rec.amount) || 0;
  var recDate    = (rec.date || rec.registeredAt || '').slice(0, 10);
  var ref        = '';
  try { ref = (document.getElementById('booking-ref') || {}).value || ''; ref = ref.trim(); } catch(e) {}
  var dossierId  = '';
  try { dossierId = localStorage.getItem('expatur_active_dossier') || ''; } catch(e) {}
  var paidAt     = rec.paidAt || rec.registeredAt || new Date().toISOString();

  console.log('[v3.76] OOB force-paid all stores', {
    type: type, invoiceId: invoiceId, ref: ref, dossierId: dossierId,
    amount: recAmount, hasReceipt: true
  });

  /* ── Matching helper: score a candidate row against the payment record.
       Returns 0 (no match), 1 (weak), 2 (medium), 3 (strong). ── */
  function _matchScore(row, matchRef) {
    /* ref must match */
    var rowRef = row.dossierRef || '';
    if (matchRef && rowRef !== matchRef && rowRef !== dossierId) return 0;

    /* Strong: invoiceId matches */
    if (invoiceId) {
      if ((row.source_id && row.source_id === invoiceId) ||
          (row.id && row.id === invoiceId) ||
          (row.stripeInvoiceId && row.stripeInvoiceId === invoiceId) ||
          (row.nota && row.nota === invoiceId)) return 3;
    }

    /* Medium: amount AND date match */
    var rowAmt  = parseFloat(row.valor || row.amount) || 0;
    var rowDate = (row.vencimento || row.date || row.dueDate || '').slice(0, 10);
    if (recAmount > 0 && Math.abs(rowAmt - recAmount) < 0.01 && recDate && rowDate === recDate) return 2;

    /* Weak: amount matches (no date) — only use if no invoiceId */
    if (!invoiceId && recAmount > 0 && Math.abs(rowAmt - recAmount) < 0.01) return 1;

    return 0;
  }

  /* ── A. Fluxo lancamentos ── */
  try {
    var lancKey   = 'expatur_financeiro_lancamentos';
    var lanc      = JSON.parse(localStorage.getItem(lancKey) || '[]');
    var lancDirty = false;
    var bestScore = 0;
    var bestIdx   = -1;

    /* First pass: find the best-matching unpaid entrada row */
    for (var li = 0; li < lanc.length; li++) {
      var r = lanc[li];
      if (r.tipo !== 'entrada') continue;
      if (r.pago === 'pago') continue; /* already paid, skip */
      var s = _matchScore(r, ref);
      if (s > bestScore) { bestScore = s; bestIdx = li; }
      if (s === 3) break; /* perfect match, stop early */
    }

    if (bestIdx >= 0 && bestScore >= 1) {
      lanc[bestIdx] = Object.assign({}, lanc[bestIdx], {
        pago:             'pago',
        status:           'paid',
        _updAt:           paidAt,
        stripeReceiptUrl: receiptUrl
      });
      lancDirty = true;
    }

    if (lancDirty) {
      localStorage.setItem(lancKey, JSON.stringify(lanc));
      console.log('[v3.76] Fluxo forced pago (score=' + bestScore + ') for ref=' + ref);
    }
  } catch(e) { console.warn('[v3.76] fluxo force-paid error', e); }

  /* ── B. Per-dossier receivable ── */
  if (dossierId) {
    try {
      var dKey  = 'expatur_doss_finance_' + dossierId;
      var dRaw  = localStorage.getItem(dKey);
      if (dRaw) {
        var dData     = JSON.parse(dRaw);
        var recvDirty = false;

        if (dData && Array.isArray(dData.receivables)) {
          var rBestScore = 0, rBestIdx = -1;

          for (var ri = 0; ri < dData.receivables.length; ri++) {
            var rv = dData.receivables[ri];
            if (rv.status === 'paid' || rv.pago === 'pago') continue;

            var rs = 0;
            /* Strong: invoiceId match */
            if (invoiceId && (rv.id === invoiceId || rv.source_id === invoiceId ||
                rv.stripeInvoiceId === invoiceId)) rs = 3;
            /* Medium: amount+date */
            else if (recAmount > 0 && Math.abs((parseFloat(rv.amount) || 0) - recAmount) < 0.01) {
              var rvDate = (rv.dueDate || rv.date || '').slice(0, 10);
              rs = (recDate && rvDate === recDate) ? 2 : (!invoiceId ? 1 : 0);
            }

            if (rs > rBestScore) { rBestScore = rs; rBestIdx = ri; }
            if (rs === 3) break;
          }

          if (rBestIdx >= 0 && rBestScore >= 1) {
            dData.receivables[rBestIdx] = Object.assign({}, dData.receivables[rBestIdx], {
              status:           'paid',
              pago:             'pago',
              paidAmount:       dData.receivables[rBestIdx].amount,
              paidAt:           paidAt,
              stripeReceiptUrl: receiptUrl
            });
            recvDirty = true;
          }
        }

        if (recvDirty) {
          localStorage.setItem(dKey, JSON.stringify(dData));
          console.log('[v3.76] Receivable forced paid (score=' + rBestScore + ') for dossierId=' + dossierId);
        }
      }
    } catch(e) { console.warn('[v3.76] receivable force-paid error', e); }
  }

  /* ── C. Invoice store ── */
  if (ref) {
    try {
      var invKey = 'expatur_em_invoice_' + ref.replace(/[^a-zA-Z0-9]/g, '_');
      var invRaw = localStorage.getItem(invKey);
      if (invRaw) {
        var inv = JSON.parse(invRaw);
        if (inv && inv.status !== 'paid') {
          inv.status        = 'paid';
          inv.paidAt        = paidAt;
          inv.receiptPdfUrl = inv.receiptPdfUrl || receiptUrl;
          localStorage.setItem(invKey, JSON.stringify(inv));
          console.log('[v3.76] Invoice store forced paid for ref=' + ref);
        }
      }
      /* Mirror to in-memory _lastStripeInvoiceData */
      if (window._lastStripeInvoiceData) {
        window._lastStripeInvoiceData.status        = 'paid';
        window._lastStripeInvoiceData.receiptPdfUrl  = window._lastStripeInvoiceData.receiptPdfUrl || receiptUrl;
      }
    } catch(e) { console.warn('[v3.76] invoice store force-paid error', e); }
  }

  /* ── D. Also update Documents tab panel in-place if visible ── */
  try {
    if (typeof window._blUpdatePaymentSection === 'function') window._blUpdatePaymentSection();
  } catch(e) {}
};


/* ═══════════════════════════════════════════════════════════════════════
   §2.  HARDEN savePaymentRecord WRAPPER
   ═══════════════════════════════════════════════════════════════════════
   The v3.75 wrapper is already in place. We re-wrap to also handle a
   subtle gap: the record's status field must be set to 'paid' BEFORE
   it is persisted, not just normalized afterward.  The v3.74 wrapper
   calls finNormalizeOobPaidRecord which does this, but the v3.75
   wrapper's hasReceipt check also needs to consider receiptPdfUrl.
*/

var _prev76SavePayRec = window.savePaymentRecord;
window.savePaymentRecord = function(record) {
  /* Pre-normalize: if OOB + receipt, force record.status = 'paid' BEFORE persist */
  /* BUT: respect offline installment index — only #1 is auto-paid */
  if (record) {
    var type76  = ((record.type) || '').toLowerCase();
    var isOob76 = type76 === 'pix' || type76 === 'virement' || type76 === 'cash';
    var hasRcpt = !!(record.stripeReceiptUrl || record.receipt_pdf || record.receiptPdfUrl);
    var isLaterInstallment = record._isOfflineInstallment && (record._installmentIndex > 0);
    if (isOob76 && hasRcpt && !isLaterInstallment) {
      record.status = 'paid';
      record.paidAt = record.paidAt || record.registeredAt || new Date().toISOString();
      if (!record.stripeReceiptUrl && (record.receipt_pdf || record.receiptPdfUrl)) {
        record.stripeReceiptUrl = record.receipt_pdf || record.receiptPdfUrl;
      }
    }
  }

  /* Delegate to v3.75 wrapper (which delegates to v3.74 → original) */
  if (typeof _prev76SavePayRec === 'function') {
    _prev76SavePayRec(record);
  }
};


/* ═══════════════════════════════════════════════════════════════════════
   §3.  HARDEN emCheckInvoiceStatus — ensure receipt propagation
   ═══════════════════════════════════════════════════════════════════════
   The v3.75 wrapper scans payment history after the check resolves and
   calls _v375OobForceAllStoresPaid for any OOB record that became paid.
   That logic is correct.  One gap: the original emCheckInvoiceStatus
   (line ~5590) only sets p.stripeReceiptUrl when `!p.stripeReceiptUrl`,
   so if receipt_pdf arrives but the field was already set to a different
   URL, it won't update.  We add a post-wrapper that ensures every
   matching payment row has both receipt fields synced.
*/

var _prev76EmCheck = window.emCheckInvoiceStatus;
if (typeof _prev76EmCheck === 'function') {
  window.emCheckInvoiceStatus = async function(invoiceId, dueDate) {
    var result = _prev76EmCheck.apply(this, arguments);

    var postHook = function() {
      try {
        var ref = '';
        try { ref = ((document.getElementById('booking-ref') || {}).value || '').trim(); } catch(e) {}
        if (!ref) return;

        var payKey = 'expatur_payments_' + ref.replace(/[^a-zA-Z0-9]/g, '_');
        var hist   = JSON.parse(localStorage.getItem(payKey) || '[]');
        var dirty  = false;

        hist = hist.map(function(p) {
          if (!p.stripeInvoiceId || p.stripeInvoiceId !== invoiceId) return p;

          /* Sync receipt fields bidirectionally */
          var rcpt = p.stripeReceiptUrl || p.receipt_pdf || p.receiptPdfUrl || '';
          if (rcpt && !p.stripeReceiptUrl) { p.stripeReceiptUrl = rcpt; dirty = true; }
          if (rcpt && !p.receiptPdfUrl)    { p.receiptPdfUrl = rcpt;    dirty = true; }

          /* If OOB + receipt, ensure status is paid */
          var pType = ((p.type) || '').toLowerCase();
          var isOob = pType === 'pix' || pType === 'virement' || pType === 'cash';
          if (isOob && rcpt && p.status !== 'paid') {
            p.status = 'paid';
            p.paidAt = p.paidAt || new Date().toISOString();
            dirty = true;
          }

          /* Force all downstream stores */
          if (isOob && p.status === 'paid' && rcpt) {
            window._v375OobForceAllStoresPaid(p);
          }

          return p;
        });

        if (dirty) {
          localStorage.setItem(payKey, JSON.stringify(hist));
        }
      } catch(e) { console.warn('[v3.76] emCheckInvoiceStatus post-hook error', e); }

      if (typeof window.finRefreshAllFinanceSurfaces === 'function') {
        window.finRefreshAllFinanceSurfaces({ source: 'v376-invoice-status-check', invoiceId: invoiceId });
      }
    };

    if (result && typeof result.then === 'function') {
      result.then(postHook);
    } else {
      setTimeout(postHook, 650);
    }
    return result;
  };
}


/* ═══════════════════════════════════════════════════════════════════════
   §4.  DETERMINISTIC OVERVIEW NORMALIZATION
   ═══════════════════════════════════════════════════════════════════════

   AUTHORITATIVE COMPUTE FUNCTION:
     window._v36ComputeOverview  (= _computeOverview352 as replaced by v3.75 wrapper)
     window.dossFIN_computeOverview  (aliased to same)

   The v3.75 wrapper pre-normalizes per-dossier expenses and global
   lancamento saida rows that have payments[].  Two remaining gaps:

     A. Per-dossier expenses with legacy inconsistency: status='paid'
        but paidAmount=0 (or vice versa).  finRecomputeExpenseState
        already handles this — it derives status from payments[] or
        paidAmount, not the other way around.  But v3.75's dirty-check
        compared norm.paidAmount !== (parseFloat(e.paidAmount) || 0),
        which could miss status-only corrections.

     B. Per-dossier receivables with stale status after OOB force-paid
        are already correct because §1 writes them directly.

   Fix: Replace the v3.75 overview wrapper with a strictly correct one
   that normalizes ALL per-dossier expenses unconditionally (not just
   when dirty-check triggers) and adds the finExpensePaidAmount helper.
*/

/* ── Helper: canonical paid amount from any expense object ── */
window.finExpensePaidAmount = function(exp) {
  var norm = window.finRecomputeExpenseState(exp || {});
  return parseFloat(norm.paidAmount) || 0;
};

/* ── Replace the overview wrapper ── */
var _prev76Compute = window._v36ComputeOverview;
window._v36ComputeOverview = function(id) {

  /* Step 1: Normalize ALL per-dossier expenses unconditionally.
     This is a cheap operation (no network, just arithmetic) and
     guarantees the compute function sees canonical state. */
  try {
    var dKey  = 'expatur_doss_finance_' + id;
    var dRaw  = localStorage.getItem(dKey);
    if (dRaw) {
      var dData = JSON.parse(dRaw);
      if (dData && Array.isArray(dData.expenses) && dData.expenses.length > 0) {
        var dirty = false;
        dData.expenses = dData.expenses.map(function(e) {
          var norm = window.finRecomputeExpenseState(e);

          /* Detect any field that changed */
          if (norm.paidAmount    !== (parseFloat(e.paidAmount) || 0) ||
              norm.balanceAmount !== (parseFloat(e.balanceAmount) || 0) ||
              norm.status        !== (e.status || 'pending') ||
              norm.pago          !== (e.pago || 'pendente')) {
            dirty = true;
          }
          return norm;
        });
        if (dirty) {
          localStorage.setItem(dKey, JSON.stringify(dData));
        }
      }
    }
  } catch(e) { console.warn('[v3.76] overview expense-normalize error', e); }

  /* Step 2: Normalize global lancamentos saida rows for this dossier.
     Derive pago from payments[] if present; also fix rows where
     paidAmount > 0 but pago is still 'pendente'. */
  try {
    var ref76  = '';
    var dd76   = null;
    try { dd76 = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null'); } catch(e) {}
    if (dd76 && dd76.fields) ref76 = (dd76.fields['booking-ref'] || '').trim();

    if (ref76) {
      var lancKey76  = 'expatur_financeiro_lancamentos';
      var lanc76     = JSON.parse(localStorage.getItem(lancKey76) || '[]');
      var lancDirty76 = false;

      lanc76 = lanc76.map(function(r) {
        if (r.tipo !== 'saida') return r;
        if (r.dossierRef !== ref76 && r.dossierRef !== id) return r;

        /* Normalize from payments[] array if it exists */
        if (Array.isArray(r.payments) && r.payments.length > 0) {
          var norm = window.finRecomputeExpenseState(r);
          /* lancamentos only support pago/pendente (no parcial) */
          var newPago = norm.pago === 'parcial' ? 'pendente' : norm.pago;
          if (r.pago !== newPago || r.status !== norm.status) {
            lancDirty76 = true;
            return Object.assign({}, r, {
              pago:   newPago,
              status: norm.status === 'partial' ? 'pending' : norm.status,
              _updAt: new Date().toISOString()
            });
          }
        }
        /* Also fix: if paidAmount suggests paid but pago says pendente */
        else if ((parseFloat(r.paidAmount) || 0) > 0 && (parseFloat(r.amount || r.valor) || 0) > 0) {
          var rAmt  = parseFloat(r.amount || r.valor) || 0;
          var rPaid = parseFloat(r.paidAmount) || 0;
          if (rPaid >= rAmt && r.pago !== 'pago') {
            lancDirty76 = true;
            return Object.assign({}, r, { pago: 'pago', status: 'paid', _updAt: new Date().toISOString() });
          }
        }
        return r;
      });

      if (lancDirty76) {
        localStorage.setItem(lancKey76, JSON.stringify(lanc76));
      }
    }
  } catch(e) {}

  /* Step 3: Call the previous compute (v3.75 wrapper → _computeOverview352) */
  return _prev76Compute.call(this, id);
};

/* Keep dossFIN_computeOverview aliased to the wrapped version */
window.dossFIN_computeOverview = window._v36ComputeOverview;


/* ═══════════════════════════════════════════════════════════════════════
   §5.  HARDEN finApplySupplierPayment — STRICT LEGACY MIRRORING
   ═══════════════════════════════════════════════════════════════════════
   The v3.74 finApplySupplierPayment already calls finRecomputeExpenseState
   and persists the result.  The v3.75 wrapper adds _updAt.  We add one
   more guarantee: after the expense is written, verify that all five
   legacy fields are present and consistent.  If finRecomputeExpenseState
   is correct (which it is — verified), this is a safety net only.
*/

var _prev76ApplySupplier = window.finApplySupplierPayment;
window.finApplySupplierPayment = function(dossierId, expenseId, mutation) {
  var result = _prev76ApplySupplier.call(this, dossierId, expenseId, mutation);

  /* Safety net: re-read and verify legacy fields are consistent */
  if (result) {
    try {
      var dKey76  = 'expatur_doss_finance_' + dossierId;
      var dData76 = JSON.parse(localStorage.getItem(dKey76) || 'null');
      if (dData76 && Array.isArray(dData76.expenses)) {
        var repaired = false;
        dData76.expenses = dData76.expenses.map(function(e) {
          if (String(e.id) !== String(expenseId)) return e;

          var norm = window.finRecomputeExpenseState(e);
          /* Check all five canonical fields */
          if (e.status        !== norm.status ||
              e.pago          !== norm.pago ||
              e.paidAmount    !== norm.paidAmount ||
              e.balanceAmount !== norm.balanceAmount ||
              !e._updAt) {
            repaired = true;
            return Object.assign({}, e, {
              status:        norm.status,
              pago:          norm.pago,
              paidAmount:    norm.paidAmount,
              balanceAmount: norm.balanceAmount,
              payments:      norm.payments,
              _updAt:        new Date().toISOString()
            });
          }
          return e;
        });

        if (repaired) {
          localStorage.setItem(dKey76, JSON.stringify(dData76));
          console.log('[v3.76] finApplySupplierPayment: legacy field repair for', expenseId);
        }
      }
    } catch(e) {}
  }

  return result;
};


/* ═══════════════════════════════════════════════════════════════════════
   §6.  SUMMARY LOG
   ═══════════════════════════════════════════════════════════════════════ */

console.log('[Patch v3.76] Hardened OOB Sync + Deterministic Overview.',
  '§1 _v375OobForceAllStoresPaid replaced: scored matching (3=invoiceId, 2=amt+date, 1=amt), receipt URL mirrored to all stores.',
  '§2 savePaymentRecord: OOB+receipt forces status=paid BEFORE persist.',
  '§3 emCheckInvoiceStatus: receipt field sync + force-paid post-hook.',
  '§4 Overview: _v36ComputeOverview + dossFIN_computeOverview wrapper normalizes ALL expenses unconditionally. finExpensePaidAmount helper added.',
  '§5 finApplySupplierPayment: legacy field repair safety net (status/pago/paidAmount/balanceAmount/payments/_updAt).');

})(); // end Patch v3.76

