      /* §D2 — additional hardened write for payment history */
      if (!rec) return;
      var type81  = ((rec.type) || '').toLowerCase();
      var isOob81 = type81 === 'pix' || type81 === 'virement' || type81 === 'cash';
      if (!isOob81) return;

      var hasRcpt81 = !!(rec.stripeReceiptUrl || rec.receipt_pdf || rec.receiptPdfUrl);
      if (!hasRcpt81) return;

