/* ═══════════════════════════════════════════════════════════════════════
   GUARD: Detect later offline installments in payment history records.
   Used by v3.82/v3.84 normalizers to NOT force-paid on installments #2+.
   Works with both new records (have _installmentIndex) and legacy records
   (detect from mode field pattern like "PIX Versement 2/3").
   ═══════════════════════════════════════════════════════════════════════ */
window._isLaterOfflineInstallmentRecord = function(p) {
  if (!p) return false;
  // New records have explicit flag
  if (p._isOfflineInstallment && p._installmentIndex > 0) return true;
  // Legacy records: detect "Versement N/M" or "Facture N/M" where N > 1
  var mode = (p.mode || '');
  var match = mode.match(/(?:Versement|Facture)\s+(\d+)\s*\/\s*(\d+)/i);
  if (match) {
    var idx = parseInt(match[1], 10);
    var total = parseInt(match[2], 10);
    if (total > 1 && idx > 1) return true;
  }
  return false;
};

