      /* Find expense ID */
      var expenseId = _findExpenseId82(dossierId, supplier, pnrRef);
      if (!expenseId) return;

      /* Get the expense data to check partial status */
      var expData = _getExpenseData82(dossierId, expenseId);

      /* Create the Payer button */
      var lastTd = tds[tds.length - 1];

      var btn = document.createElement('button');
      btn.className = 'v382-global-payer-btn';
      btn.style.cssText = 'background:var(--navy,#06203b);color:#fff;border:none;border-radius:4px;padding:3px 8px;font-size:0.62rem;font-weight:700;cursor:pointer;margin-left:4px;white-space:nowrap;';

