  /* Helper: find dossier ID from booking ref */
  function _findDossierIdByRef82(ref) {
    if (!ref) return null;
    /* Direct match */
    var stored = localStorage.getItem('expatur_active_dossier');
    if (stored) {
      try {
        var dd = JSON.parse(localStorage.getItem('expatur_dossier_' + stored) || 'null');
        if (dd && dd.fields && dd.fields['booking-ref'] === ref) return stored;
      } catch(e) {}
    }
    /* Scan all dossiers */
    try {
      var keys = Object.keys(localStorage);
      for (var i = 0; i < keys.length; i++) {
        if (keys[i].indexOf('expatur_dossier_') !== 0) continue;
        try {
          var dd2 = JSON.parse(localStorage.getItem(keys[i]) || 'null');
          if (dd2 && dd2.fields && dd2.fields['booking-ref'] === ref) {
            return keys[i].replace('expatur_dossier_', '');
          }
        } catch(e) {}
      }
    } catch(e) {}

    /* Fallback: maybe the ref IS the dossier ID */
    if (localStorage.getItem('expatur_doss_finance_' + ref)) return ref;

    return null;
  }

  /* Helper: find expense ID by supplier + pnr within a dossier */
  function _findExpenseId82(dossierId, supplier, pnrRef) {
    try {
      var dKey = 'expatur_doss_finance_' + dossierId;
      var dRaw = localStorage.getItem(dKey);
      if (!dRaw) return null;
      var dData = JSON.parse(dRaw);
      if (!dData || !Array.isArray(dData.expenses)) return null;

      /* Try exact match on supplier + pnr */
      for (var i = 0; i < dData.expenses.length; i++) {
        var e = dData.expenses[i];
        var eSup = (e.supplier || e.fornecedor || '').trim();
        var ePnr = (e.pnrRef || e.source_id || '').trim();
        if (eSup === supplier || (pnrRef && ePnr === pnrRef)) {
          return e.id || e.source_id || null;
        }
      }

      /* Fallback: match by supplier name */
      for (var j = 0; j < dData.expenses.length; j++) {
        var e2 = dData.expenses[j];
        var eSup2 = (e2.supplier || e2.fornecedor || '').trim();
        if (eSup2 === supplier) return e2.id || e2.source_id || null;
      }

      /* Last resort: first expense */
      if (dData.expenses.length > 0) {
        return dData.expenses[0].id || dData.expenses[0].source_id || null;
      }
    } catch(e) {}
    return null;
  }

