/* ═══════════════════════════════════════════════════════════════════════
   PATCH v3.84 — Inline source edits: summary & payment history hardening
   ───────────────────────────────────────────────────────────────────────
   This patch was applied as DIRECT INLINE EDITS to the source code above,
   not as wrapper functions. The following were modified in-place:

   1) financeNormalizeEntry (line ~42457):
      BEFORE: amountBrl = brl_amount || amount_brl || valor_brl || amount || valor
      AFTER:  For non-BRL currencies, only accepts stamped BRL fields or derives
              via fx_rate_to_brl / _brlRateCache. Sets amountBrl = null (not raw
              foreign amount) when FX is unavailable.

   2) finFmt (line ~12885) + dossFIN_fmt (line ~15958):
      Added null guard: returns "FX indisponível" label when value is null.

   3) finRenderFluxo row builder (line ~13028):
      Replaced direct `it.valor` usage with safe BRL derivation per-row.
      Non-BRL rows without FX rate show "FX indisponível" + "Orig: XXX EUR".

   4) finRenderLancamentos row builder (line ~13162):
      Same safe BRL derivation per-row.

   5) finRenderKPIs accumulator (line ~12964):
      Safe BRL derivation; unconvertible rows contribute 0 to totals.

   6) _renderReceivables (line ~16182) + _renderExpenses (line ~16244):
      Per-dossier tab renderers: replaced dossFIN_fmt(r.amount, r.currency)
      with safe BRL derivation + "Orig:" annotation for foreign rows.

   7) All dossFIN_fmt(xxx,'EUR') hardcodes:
      Replaced with dossFIN_fmt(xxx,'BRL') across overview, dashboard, ledger,
      P&L, and supplier panels.

   SAFETY RULE ENFORCED:
     For non-BRL rows: valor, brl_amount, amount_brl are NEVER set to the raw
     foreign amount. They are either a real FX-converted value or null.
     The renderers check for null and display "FX indisponível" instead of
     a fake R$ value.
   ═══════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  if (window._v384InlineEdits) return;
  window._v384InlineEdits = true;

  /* §1. Harden renderPaymentHistory — normalise OOB history rows to paid
     This re-applies the v3.82 logic but as a direct pre-render normaliser
     on the ACTUAL stored rows, not just a badge wrapper. */

  if (typeof window.renderPaymentHistory === 'function' && !window._v384RenderPayWrap) {
    window._v384RenderPayWrap = true;
    var _origRenderPay84 = window.renderPaymentHistory;

    window.renderPaymentHistory = function () {
      /* Normalise payment history rows in ALL expatur_payments_* keys */
      try {
        var keys = Object.keys(localStorage);
        for (var ki = 0; ki < keys.length; ki++) {
          var k = keys[ki];
          if (k.indexOf('expatur_payments_') !== 0) continue;
          var raw = localStorage.getItem(k);
          if (!raw) continue;
          var hist = JSON.parse(raw);
          if (!Array.isArray(hist)) continue;
          var dirty = false;

          for (var i = 0; i < hist.length; i++) {
            var p = hist[i];
            /* Skip later offline installments — they must stay open */
            if (typeof window._isLaterOfflineInstallmentRecord === 'function' && window._isLaterOfflineInstallmentRecord(p)) continue;
            /* Already correct */
            if (p.status === 'paid' && p.pago === 'pago') continue;

            var pType = ((p.type) || '').toLowerCase();
            var isOob = pType === 'pix' || pType === 'virement' || pType === 'cash';
            var hasReceipt = !!(p.stripeReceiptUrl || p.receiptPdfUrl || p.receipt_pdf);

            /* OOB + receipt → paid */
            if (isOob && hasReceipt && p.status !== 'paid') {
              p.status = 'paid';
              p.pago = 'pago';
              p.paidAt = p.paidAt || p.registeredAt || new Date().toISOString();
              dirty = true;
            }
            /* OOB + paid_out_of_band flag → paid */
            if (isOob && p.paid_out_of_band && p.status !== 'paid') {
              p.status = 'paid';
              p.pago = 'pago';
              p.paidAt = p.paidAt || p.registeredAt || new Date().toISOString();
              dirty = true;
            }
            /* Fix mismatched status/pago */
            if (p.status === 'paid' && p.pago !== 'pago') { p.pago = 'pago'; dirty = true; }
            if (p.pago === 'pago' && p.status !== 'paid') { p.status = 'paid'; p.paidAt = p.paidAt || new Date().toISOString(); dirty = true; }
          }

          if (dirty) {
            localStorage.setItem(k, JSON.stringify(hist));
            console.log('[v3.84] normalised payment history rows in', k);
          }
        }
      } catch (ex) {
        console.warn('[v3.84] renderPaymentHistory normalisation error', ex);
      }

      /* Now render with the corrected data */
      _origRenderPay84.apply(this, arguments);
    };
  }

  /* §2. Harden emCheckInvoiceStatus — update payment history row after Stripe check */
  if (typeof window.emCheckInvoiceStatus === 'function' && !window._v384InvCheckWrap) {
    window._v384InvCheckWrap = true;
    var _origInvCheck84 = window.emCheckInvoiceStatus;

    window.emCheckInvoiceStatus = async function (invoiceId, dueDate) {
      var result;
      try { result = await _origInvCheck84.apply(this, arguments); } catch (e) {}

      /* After check, scan payment history for matching invoice and mark paid */
      try {
        var keys = Object.keys(localStorage);
        for (var ki = 0; ki < keys.length; ki++) {
          var k = keys[ki];
          if (k.indexOf('expatur_payments_') !== 0) continue;
          var raw = localStorage.getItem(k);
          if (!raw) continue;
          var hist = JSON.parse(raw);
          if (!Array.isArray(hist)) continue;
          var dirty = false;

          for (var i = 0; i < hist.length; i++) {
            if (hist[i].status === 'paid') continue;
            if (hist[i].stripeInvoiceId === invoiceId) {
              /* Installment guard: never force-paid on later offline installments */
              if (typeof window._isLaterOfflineInstallmentRecord === 'function' && window._isLaterOfflineInstallmentRecord(hist[i])) continue;
              hist[i].status = 'paid';
              hist[i].pago = 'pago';
              hist[i].paidAt = hist[i].paidAt || new Date().toISOString();
              dirty = true;
            }
          }

          if (dirty) {
            localStorage.setItem(k, JSON.stringify(hist));
            if (typeof window.renderPaymentHistory === 'function') window.renderPaymentHistory();
          }
        }
      } catch (e) {}

      return result;
    };
  }

  console.log('[Patch v3.84] Inline source edits applied.',
    '\n  financeNormalizeEntry: non-BRL amountBrl derived from fx_rate_to_brl / _brlRateCache only; null when FX unavailable.',
    '\n  finFmt + dossFIN_fmt: null → "FX indisponível".',
    '\n  finRenderFluxo + finRenderLancamentos: safe BRL per row; "Orig: XXX EUR" for foreign rows.',
    '\n  _renderReceivables + _renderExpenses: safe BRL derivation; "Orig:" annotation.',
    '\n  All dossFIN_fmt(x,"EUR") → dossFIN_fmt(x,"BRL").',
    '\n  renderPaymentHistory: pre-render normalisation of OOB rows (status+pago persist).',
    '\n  emCheckInvoiceStatus: post-check payment history row update.');

})(); // end Patch v3.84

