(function () {
  'use strict';
  if (window._v388CommFix) return;
  window._v388CommFix = true;

  /* ── Guard flags ── */
  window._blCalcPnLBusy        = false;  // re-entry guard for blCalcPnL
  window._blPnlEurRateWriting  = false;  // guard: we are writing the rate field ourselves
  window._vCurSelWriting       = false;  // guard: we are setting vend-cur-select ourselves

  /* ══════════════════════════════════════════════════════════════════
     §1 — Wrap blCalcPnL with a re-entry guard.
     The v3.72 wrapper already debounces syncCommissionToFinance;
     this guard prevents the FX-fetch→field-write→blCalcPnL loop.
  ══════════════════════════════════════════════════════════════════ */
  if (typeof window.blCalcPnL === 'function' && !window._v388CalcGuard) {
    window._v388CalcGuard = true;
    var _prevBlCalc = window.blCalcPnL;
    window.blCalcPnL = function () {
      if (window._blCalcPnLBusy) return; // drop re-entrant call
      window._blCalcPnLBusy = true;
      try {
        _prevBlCalc.apply(this, arguments);
      } finally {
        window._blCalcPnLBusy = false;
      }
    };
  }

  /* ══════════════════════════════════════════════════════════════════
     §2 — Fix the bl-pnl-eur-rate oninput="blCalcPnL()" loop.
     When WE write .value programmatically we must not also fire oninput.
     Strategy: remove the inline oninput handler and replace it with a
     delegated listener that checks _blPnlEurRateWriting.
  ══════════════════════════════════════════════════════════════════ */
  function _patchEurRateField() {
    var el = document.getElementById('bl-pnl-eur-rate');
    if (!el || el._v388Patched) return;
    el._v388Patched = true;
    // Remove the inline oninput so it won't fire on programmatic .value writes
    el.removeAttribute('oninput');
    el.addEventListener('input', function () {
      if (window._blPnlEurRateWriting) return; // skip if we wrote it
      if (typeof window.blCalcPnL === 'function') window.blCalcPnL();
    });
  }

  /* ══════════════════════════════════════════════════════════════════
     §3 — Safe helper: write bl-pnl-eur-rate without triggering oninput loop.
  ══════════════════════════════════════════════════════════════════ */
  window._writeCommFxRate = function (rateValue) {
    var el = document.getElementById('bl-pnl-eur-rate');
    if (!el) return;
    window._blPnlEurRateWriting = true;
    try {
      el.value = parseFloat(rateValue).toFixed(4);
    } finally {
      window._blPnlEurRateWriting = false;
    }
  };

  /* ══════════════════════════════════════════════════════════════════
     §4 — Fix vend-cur-select programmatic write causing onchange loop.
     blCalcPnL writes curSel.value to keep it in sync, but that fires
     onchange="_setVendeurCurrency(...)" → blCalcPnL → loop.
     Fix: use a guard in _setVendeurCurrency and wrap the curSel write.
  ══════════════════════════════════════════════════════════════════ */
  window._setVendeurCurrency = function (iso) {
    if (window._vCurSelWriting) return; // skip if triggered by our own .value write
    var hidden = document.getElementById('vendeur-commission-type');
    if (hidden) hidden.value = iso.toLowerCase();
    var btnPct = document.getElementById('vend-btn-pct');
    if (btnPct) btnPct.classList.remove('active-disc');
    // Highlight the select without re-triggering onchange
    var curSel = document.getElementById('vend-cur-select');
    if (curSel) curSel.style.background = 'var(--gold10)';
    // Trigger a single clean recalc, then fetch FX if needed
    _commFetchAndCalc(iso);
  };

  /* Also guard _setVendeurType so it doesn't loop through the select */
  var _origSetVendeurType = window._setVendeurType;
  window._setVendeurType = function (type) {
    if (typeof _origSetVendeurType === 'function') {
      _origSetVendeurType.apply(this, arguments);
    } else {
      var hidden = document.getElementById('vendeur-commission-type');
      if (hidden) hidden.value = type;
      var btnPct = document.getElementById('vend-btn-pct');
      if (btnPct) btnPct.classList.toggle('active-disc', type === 'pct');
      var curSel = document.getElementById('vend-cur-select');
      if (curSel) curSel.style.background = type !== 'pct' ? 'var(--gold10)' : 'var(--light)';
      if (typeof window.blCalcPnL === 'function') window.blCalcPnL();
    }
  };

  /* ══════════════════════════════════════════════════════════════════
     §5 — Safe helper that writes curSel.value without firing onchange.
  ══════════════════════════════════════════════════════════════════ */
  window._writeVendCurSel = function (isoUpper) {
    var curSel = document.getElementById('vend-cur-select');
    if (!curSel) return;
    window._vCurSelWriting = true;
    try {
      curSel.value = isoUpper;
    } finally {
      window._vCurSelWriting = false;
    }
  };

  /* ══════════════════════════════════════════════════════════════════
     §6 — _commFetchAndCalc: async FX fetch + single blCalcPnL call.
     Called from _setVendeurCurrency. Fetches rate asynchronously,
     stores it in cache + rate field, then calls blCalcPnL ONCE.
     Never re-calls itself. Always releases guard in finally.
  ══════════════════════════════════════════════════════════════════ */
  var _commFxFetchActive = false; // prevent concurrent fetches
  window._commFetchAndCalc = function (iso) {
    var isoUpper = (iso || 'EUR').toUpperCase();
    var symMap   = { EUR: '\u20ac', USD: '$', MAD: 'MAD', DOP: 'DOP', BRL: 'R$' };
    var sym      = symMap[isoUpper] || isoUpper;

    // BRL: no fetch needed, just recalc
    if (isoUpper === 'BRL') {
      if (typeof window.blCalcPnL === 'function') window.blCalcPnL();
      return;
    }

    // Check cache first
    var cached = window._brlRateCache
      ? (window._brlRateCache[isoUpper] || window._brlRateCache[sym] || 0)
      : 0;

    if (cached > 0) {
      window._writeCommFxRate(cached);
      if (typeof window.blCalcPnL === 'function') window.blCalcPnL();
      return;
    }

    // Need network fetch — do it async, never block
    if (_commFxFetchActive) {
      // A fetch is already running, just recalc with what we have
      if (typeof window.blCalcPnL === 'function') window.blCalcPnL();
      return;
    }

    // Do an immediate recalc with fallback rate so UI stays responsive
    if (typeof window.blCalcPnL === 'function') window.blCalcPnL();

    if (typeof window.fetchBRLRate !== 'function') return;

    _commFxFetchActive = true;
    window.fetchBRLRate(sym)
      .then(function (rate) {
        if (!rate || isNaN(rate)) return;
        window._writeCommFxRate(rate);
        // Single recalc after FX is loaded
        if (typeof window.blCalcPnL === 'function') window.blCalcPnL();
      })
      .catch(function () {
        if (typeof toast === 'function') toast('Taux ' + isoUpper + '/BRL indisponible — valeur approx.', 'error');
      })
      .finally(function () {
        _commFxFetchActive = false;
      });
  };

  /* ══════════════════════════════════════════════════════════════════
     §7 — Fix the inline blCalcPnL path that also does an async fetch
     and calls blCalcPnL() in the .then() — replace it with
     _commFetchAndCalc so all fetches go through one guarded path.
     We patch the installed blCalcPnL so the rogue fetchBRLRate().then
     inside it is neutralised.

     Strategy: override the section that triggers the background fetch
     by wrapping blCalcPnL and skipping the re-entrant fetch when
     _blCalcPnLBusy is set (already done in §1).
     The fetch inside blCalcPnL itself will simply be a no-op because
     its .then sets el.value and calls blCalcPnL() — but:
       • el.value write is guarded (§3)
       • blCalcPnL re-entry is guarded (§1)
     So the loop is broken even without removing the inline fetch code.
  ══════════════════════════════════════════════════════════════════ */

  /* ══════════════════════════════════════════════════════════════════
     §8 — Fix syncCommissionToFinance to respect multi-currency commType.
     The original only handles 'pct' vs "everything else = EUR".
     We patch it to use the correct commIso and description.
  ══════════════════════════════════════════════════════════════════ */
  if (typeof window.syncCommissionToFinance === 'function' && !window._v388CommSync) {
    window._v388CommSync = true;
    window.syncCommissionToFinance = function () {
      if (typeof window.financeUpsertEntry !== 'function') return;
      var id  = localStorage.getItem('expatur_active_dossier');
      if (!id) return;
      var sid = 'comm__' + id;

      var vendeur   = (document.getElementById('vendeur-select')          || {}).value || '';
      var commRaw   = parseFloat((document.getElementById('vendeur-commission')       || {}).value) || 0;
      var commType  = (document.getElementById('vendeur-commission-type') || {}).value || 'eur';
      var rateEl    = document.getElementById('bl-pnl-rate');
      var rate      = parseFloat(rateEl && rateEl.value) || 5.8;
      var eurRateEl = document.getElementById('bl-pnl-eur-rate');
      var eurRate   = parseFloat(eurRateEl && eurRateEl.value) || rate;
      var cur       = (typeof _quoteCurrency !== 'undefined') ? _quoteCurrency : '\u20ac';
      var price     = (typeof _quoteFinalPrice !== 'undefined') ? (_quoteFinalPrice || 0) : 0;
      var grossBRL  = (cur === 'R$') ? price : price * rate;

      var commIso  = commType.toUpperCase(); // 'PCT', 'EUR', 'USD', 'MAD', 'DOP', 'BRL'
      var commBRL  = 0;

      if (vendeur && commRaw > 0) {
        if (commType === 'pct') {
          commBRL = grossBRL * commRaw / 100;
        } else if (commType === 'brl') {
          commBRL = commRaw;
        } else {
          // Use eurRate field which holds the fetched rate for any foreign currency
          var fxRate = eurRate > 0 ? eurRate : rate;
          // Also check cache directly
          var symMap2 = { EUR: '\u20ac', USD: '$', MAD: 'MAD', DOP: 'DOP' };
          var sym2 = symMap2[commIso] || commIso;
          var cached2 = window._brlRateCache
            ? (window._brlRateCache[commIso] || window._brlRateCache[sym2] || 0)
            : 0;
          if (cached2 > 0) fxRate = cached2;
          commBRL = commRaw * fxRate;
        }
      }

      if (commBRL <= 0) {
        if (typeof window.financeDeleteEntry === 'function') window.financeDeleteEntry(sid);
        return;
      }

      // Build readable description using actual currency
      var commTypeLabel = commType === 'pct'
        ? commRaw.toFixed(1) + '%'
        : commRaw.toFixed(2) + ' ' + commIso;
      var descr = 'Commission ' + vendeur + ' (' + commTypeLabel + ')';

      // Ref
      var ref = '';
      try {
        var m = JSON.parse(localStorage.getItem('expatur_dossier_' + id) || 'null');
        ref = (m && (m.ref || m.dossierRef)) || id;
      } catch(e) { ref = id; }

      window.financeUpsertEntry({
        kind:        'expense',
        source_type: 'commission',
        source_id:   sid,
        dossierRef:  ref,
        descricao:   descr,
        currency:    'BRL',
        amount:      commBRL,
        amount_brl:  commBRL,
        status:      'pendente',
        date:        new Date().toISOString().slice(0, 10),
        vendor:      vendeur,
        categoria:   'Comiss\u00e3o Vendedor',
        notes:       'type=' + commType + ' raw=' + commRaw + ' rate=' + rate,
      });
    };
  }

  /* ══════════════════════════════════════════════════════════════════
     §9 — Also patch the inline blCalcPnL FX fetch so it uses
     _writeCommFxRate (guarded write) instead of bare el.value = ...
     We do this by wrapping blCalcPnL one more time to intercept the
     write inside the .then() via our write guard already in place.
     No further action needed — §1 + §3 together break the loop.
  ══════════════════════════════════════════════════════════════════ */

  /* ══════════════════════════════════════════════════════════════════
     §10 — DOM ready: patch the rate field to remove its inline oninput
  ══════════════════════════════════════════════════════════════════ */
  function _v388Init() {
    _patchEurRateField();
    // Also ensure vend-cur-select does not have a bare onchange that bypasses guard
    // (It was set in HTML as onchange="_setVendeurCurrency(this.value)" which is fine
    //  because _setVendeurCurrency itself now has the _vCurSelWriting guard.)
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _v388Init);
  } else {
    _v388Init();
  }

  console.log('[Patch v3.88] Commission currency freeze fix applied:',
    '\n  §1 blCalcPnL re-entry guard (_blCalcPnLBusy)',
    '\n  §2 bl-pnl-eur-rate oninput→blCalcPnL loop broken',
    '\n  §3 _writeCommFxRate: guarded programmatic rate write',
    '\n  §4 _setVendeurCurrency: _vCurSelWriting guard prevents onchange loop',
    '\n  §5 _writeVendCurSel: guarded select.value write',
    '\n  §6 _commFetchAndCalc: single async fetch path, never re-entrant',
    '\n  §8 syncCommissionToFinance: multi-currency aware description + BRL calc');
})();

