(function(){
  const FX_SYMBOL_TO_ISO = { '€':'EUR', '$':'USD', 'MAD':'MAD', 'R$':'BRL', 'R\$':'BRL', '£':'GBP', 'DOP':'DOP' };
  const HEADER_PAIRS = [['EUR','BRL'], ['USD','BRL'], ['MAD','BRL']];
  const FX_CACHE = Object.create(null);
  const FX_TTL_MS = 5 * 60 * 1000;

  function normalizeIso(v){
    if (!v) return 'EUR';
    return (FX_SYMBOL_TO_ISO[v] || v || 'EUR').toString().replace(/[^A-Za-z]/g,'').toUpperCase() || 'EUR';
  }

  function parseRateFromSerpData(data){
    const bag = [];
    const ab = data && data.answer_box ? data.answer_box : null;
    if (ab) {
      ['answer','result','snippet','currency','price','value','title'].forEach(function(k){ if (typeof ab[k] === 'string') bag.push(ab[k]); });
      if (Array.isArray(ab.conversions)) {
        ab.conversions.forEach(function(c){ ['price','value','currency'].forEach(function(k){ if (c && typeof c[k] === 'string') bag.push(c[k]); }); });
      }
      if (Array.isArray(ab.list)) {
        ab.list.forEach(function(c){ if (c && typeof c.answer === 'string') bag.push(c.answer); });
      }
    }
    const kg = data && data.knowledge_graph ? data.knowledge_graph : null;
    if (kg) ['description','title'].forEach(function(k){ if (typeof kg[k] === 'string') bag.push(kg[k]); });
    if (Array.isArray(data && data.organic_results)) {
      data.organic_results.slice(0,3).forEach(function(r){ ['snippet','title'].forEach(function(k){ if (r && typeof r[k] === 'string') bag.push(r[k]); }); });
    }
    const txt = bag.join(' | ').replace(/,/g,' ');
    const m = txt.match(/(?:^|\s)(\d+(?:\.\d+)?)(?=\s|$)/);
    return m ? Number(m[1]) : null;
  }

  async function serpQuery(query){
    const params = new URLSearchParams({ engine:'google', q:query, google_domain:'google.com', hl:'en', gl:'us', no_cache:'true' });
    if (typeof SERP_PROXY_URL === 'string' && SERP_PROXY_URL) {
      const r = await fetch(SERP_PROXY_URL + '?' + params.toString(), { credentials:'omit' });
      if (!r.ok) throw new Error('Proxy ' + r.status);
      return r.json();
    }
    if (typeof SERP_API_KEY !== 'string' || !SERP_API_KEY) throw new Error('Missing SerpApi key');
    params.set('api_key', SERP_API_KEY);
    params.set('output', 'json');
    const r2 = await fetch('https://serpapi.com/search.json?' + params.toString(), { credentials:'omit' });
    if (!r2.ok) throw new Error('SerpApi ' + r2.status);
    return r2.json();
  }

  async function getSerpRate(fromIso,toIso){
    fromIso = normalizeIso(fromIso);
    toIso = normalizeIso(toIso);
    if (fromIso === toIso) return 1;
    const key = fromIso + '_' + toIso;
    const now = Date.now();
    if (FX_CACHE[key] && (now - FX_CACHE[key].at) < FX_TTL_MS) return FX_CACHE[key].rate;
    const data = await serpQuery('1 ' + fromIso + ' to ' + toIso);
    const rate = parseRateFromSerpData(data);
    if (!(typeof rate === 'number' && isFinite(rate) && rate > 0)) throw new Error('No FX rate parsed for ' + key);
    FX_CACHE[key] = { rate: rate, at: now };
    return rate;
  }

  const oldFetchBRLRate = window.fetchBRLRate;
  window.fetchBRLRate = async function(currencySymbol){
    const iso = normalizeIso(currencySymbol);
    if (iso === 'BRL') return 1;
    return getSerpRate(iso, 'BRL');
  };

  function ensureFxStyles(){
    if (document.getElementById('fx-strip-serpapi-style')) return;
    const st = document.createElement('style');
    st.id = 'fx-strip-serpapi-style';
    st.textContent = `
      .fx-strip-serpapi{display:flex;align-items:center;gap:10px;margin-left:18px;padding-left:18px;border-left:1px solid rgba(6,32,59,.12);flex-wrap:wrap}
      .fx-strip-serpapi[hidden]{display:none !important}
      .fx-strip-serpapi .fx-chip{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;background:rgba(6,32,59,.04);border:1px solid rgba(6,32,59,.08);border-radius:8px;padding:6px 10px;min-width:84px}
      .fx-strip-serpapi .fx-chip .fx-pair{font-size:.54rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--navy-faint)}
      .fx-strip-serpapi .fx-chip .fx-val{font-size:.88rem;font-weight:800;color:var(--navy);line-height:1.1}
      .fx-strip-serpapi .fx-chip.loading .fx-val{opacity:.6}
      .fx-strip-serpapi .fx-chip.error .fx-val{color:var(--red)}
      @media(max-width:1100px){.fx-strip-serpapi{width:100%;order:3;margin-left:0;padding-left:0;border-left:none;padding-top:6px}}
      @media(max-width:700px){.fx-strip-serpapi{gap:6px}.fx-strip-serpapi .fx-chip{min-width:72px;padding:5px 8px}.fx-strip-serpapi .fx-chip .fx-val{font-size:.78rem}}
    `;
    document.head.appendChild(st);
  }

  function getTargetHeaders(){
    /* Return the clock-group div (right side) so the FX strip sits beside clocks */
    var targets = [];
    ['#section-welcome','#section-quoting','#section-financeiro'].forEach(function(sel){
      var hdr = document.querySelector(sel + ' .section-page-header');
      if (!hdr) return;
      /* The clock-group is the div with data-clock-tz descendants and flex-shrink:0 */
      var clockGroup = hdr.querySelector('div[style*="flex-shrink:0"]');
      targets.push(clockGroup || hdr);
    });
    return targets;
  }

  function ensureFxHeader(){
    ensureFxStyles();
    getTargetHeaders().forEach(function(header){
      if (!header.querySelector('.fx-strip-serpapi')) {
        const strip = document.createElement('div');
        strip.className = 'fx-strip-serpapi';
        strip.innerHTML = HEADER_PAIRS.map(function(pair){
          const key = pair[0] + '/' + pair[1];
          return '<div class="fx-chip loading" data-fx-key="'+key+'"><div class="fx-pair">'+key+'</div><div class="fx-val">…</div></div>';
        }).join('');
        header.appendChild(strip);
      }
    });
    updateFxVisibility();
  }

  function currentOpenSectionId(){
    const open = document.querySelector('.section-page.open');
    return open ? open.id : '';
  }

  function updateFxVisibility(){
    const openId = currentOpenSectionId();
    const visible = openId === 'section-welcome' || openId === 'section-quoting' || openId === 'section-financeiro';
    document.querySelectorAll('.fx-strip-serpapi').forEach(function(el){ el.hidden = !visible; });
  }

  async function refreshHeaderFx(force){
    ensureFxHeader();
    const strips = Array.from(document.querySelectorAll('.fx-strip-serpapi'));
    if (!strips.length) return;
    strips.forEach(function(strip){ strip.querySelectorAll('.fx-chip').forEach(function(chip){ chip.classList.add('loading'); chip.classList.remove('error'); }); });
    const results = {};
    for (const pair of HEADER_PAIRS) {
      const key = pair[0] + '/' + pair[1];
      try { results[key] = await getSerpRate(pair[0], pair[1]); }
      catch (e) { results[key] = null; console.error('FX header failed for', key, e); }
    }
    strips.forEach(function(strip){
      strip.querySelectorAll('.fx-chip').forEach(function(chip){
        const key = chip.getAttribute('data-fx-key');
        const val = chip.querySelector('.fx-val');
        chip.classList.remove('loading','error');
        if (results[key] == null) {
          chip.classList.add('error');
          if (val) val.textContent = 'ERR';
        } else if (val) {
          val.textContent = Number(results[key]).toFixed(2);
        }
      });
    });
    updateFxVisibility();
  }

  async function syncPricingFx(){
    try {
      const quoteSym = (document.getElementById('currency') || {}).value || '€';
      const quoteIso = normalizeIso(quoteSym);
      const rateInput = document.getElementById('bl-pnl-rate');
      if (rateInput && quoteIso) {
        const rate = await window.fetchBRLRate(quoteIso);
        if (isFinite(rate) && rate > 0) {
          const changed = String(rateInput.value || '') !== rate.toFixed(4);
          rateInput.value = rate.toFixed(4);
          if (typeof window.blCalcPnL === 'function' && changed) window.blCalcPnL();
        }
      }
      const eurRateInput = document.getElementById('bl-pnl-eur-rate');
      if (eurRateInput) {
        const eurRate = await getSerpRate('EUR','BRL');
        const changed2 = String(eurRateInput.value || '') !== eurRate.toFixed(4);
        eurRateInput.value = eurRate.toFixed(4);
        if (typeof window.blCalcPnL === 'function' && changed2) window.blCalcPnL();
      }
    } catch (e) {
      console.error('Pricing FX sync failed', e);
    }
  }

  function bindPricingHooks(){
    const currencyEl = document.getElementById('currency');
    if (currencyEl && !currencyEl.__fxBound) {
      currencyEl.__fxBound = true;
      currencyEl.addEventListener('change', function(){ setTimeout(syncPricingFx, 80); setTimeout(refreshHeaderFx, 80); });
    }
    const quoteHost = document.getElementById('section-quoting');
    if (quoteHost && !quoteHost.__fxObs) {
      const obs = new MutationObserver(function(){ updateFxVisibility(); });
      obs.observe(document.body, { attributes:true, subtree:true, attributeFilter:['class'] });
      quoteHost.__fxObs = obs;
    }
  }

  function bootFxPatch(){
    ensureFxHeader();
    bindPricingHooks();
    refreshHeaderFx(true);
    syncPricingFx();
    updateFxVisibility();
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bootFxPatch);
  else bootFxPatch();
  window.addEventListener('load', function(){ setTimeout(bootFxPatch, 120); });
  setInterval(function(){ refreshHeaderFx(false); syncPricingFx(); }, 300000);
})();

