(function(){
  /* Remove ONLY the legacy System 1 cross-rate chips (USD/EUR, EUR/USD, BRL/USD).
     Do NOT remove .fx-strip-serpapi — that is System 2 (the correct BRL-centric display). */
  function cleanLegacyFx(){
    document.querySelectorAll('.header-fx-item .fx-pair').forEach(function(el){
      var txt = (el.textContent||'').trim();
      if (txt === 'USD/EUR' || txt === 'EUR/USD' || txt === 'BRL/USD') {
        var item = el.closest('.header-fx-item');
        if (item) item.remove();
      }
    });
    /* Also remove empty legacy .header-fx-strip containers left behind */
    document.querySelectorAll('.header-fx-strip').forEach(function(strip){
      if (!strip.querySelector('.header-fx-item')) strip.remove();
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', cleanLegacyFx);
  else cleanLegacyFx();
  window.addEventListener('load', function(){ setTimeout(cleanLegacyFx, 250); });
})();

