(function(){
  'use strict';
  if (window._welcomeTaskPopupServerFix) return;
  window._welcomeTaskPopupServerFix = true;

  function allTasksCanonical(){
    try {
      if (window.taskStore && typeof window.taskStore.getAllTasks === 'function') {
        var arr = window.taskStore.getAllTasks();
        if (Array.isArray(arr) && arr.length) return arr.slice();
      }
    } catch(e) {}
    try {
      if (typeof window.getAllTasks === 'function') {
        var arr2 = window.getAllTasks();
        if (Array.isArray(arr2)) return arr2.slice();
      }
    } catch(e) {}
    return [];
  }

  function tasksForRefCanonical(ref){
    ref = String(ref || '').trim();
    var all = allTasksCanonical();
    return all.filter(function(t){ return String(t._ref || t.ref || '').trim() === ref; });
  }

  function findTaskCanonical(taskId, ref){
    var id = String(taskId);
    var task = null;
    try {
      if (window.taskStore && typeof window.taskStore.getTaskById === 'function') {
        task = window.taskStore.getTaskById(taskId);
      }
    } catch(e) {}
    if (task) return task;
    var all = ref ? tasksForRefCanonical(ref) : allTasksCanonical();
    for (var i=0;i<all.length;i++) {
      if (String(all[i].id) === id) return all[i];
    }
    return null;
  }

  function persistWelcomeTaskEdits(ref, tasks){
    try {
      if (window._tpWriteDossierTasks && ref) {
        window._tpWriteDossierTasks(ref, tasks);
      }
    } catch(e) {}
    try {
      if (window.taskStore && typeof window.taskStore.saveTask === 'function') {
        (tasks || []).forEach(function(t){
          var payload = Object.assign({}, t);
          payload._ref = ref || payload._ref || payload.ref || '';
          window.taskStore.saveTask(payload._ref, payload);
        });
      }
    } catch(e) {}
  }

  function _welcomeHardRefreshTasks(){
    function run(){
      try { if (typeof window.welcomeRefresh === 'function') window.welcomeRefresh(); } catch(e) {}
      try { if (typeof window._v359InjectTaskIds === 'function') window._v359InjectTaskIds(); } catch(e) {}
      try { if (typeof window._v359InstallWelcomeCapture === 'function') window._v359InstallWelcomeCapture(); } catch(e) {}
    }
    run();
    setTimeout(run, 120);
    setTimeout(run, 450);
    setTimeout(run, 1100);
  }

  window._welcomeOpenTask = function(taskId, ref){
    var found = findTaskCanonical(taskId, ref);
    if (!found) {
      console.warn('[welcome-fix] task not found', taskId, ref);
      return;
    }
    var targetRef = String(found._ref || found.ref || ref || '').trim();
    var crossTasks = targetRef ? tasksForRefCanonical(targetRef) : [found];
    if (!crossTasks.length) crossTasks = [found];

    if (!found.cat && found.category) found.cat = found.category;
    if (!found.category && found.cat) found.category = found.cat;
    if (!found.text && found.title) found.text = found.title;
    if (!found.title && found.text) found.title = found.text;
    if (!found.cat) found.cat = 'Diversos';
    if (typeof window.ensureTaskCategoryDefaults === 'function') {
      try { window.ensureTaskCategoryDefaults(found); } catch(e) {}
    }

    var origTasks = window._tasks ? window._tasks.slice() : [];
    var origOverride = window._uniTaskKeyOverride;
    var origClose = window.closeTaskDetail;
    var origSave = window._saveTasks;

    if (window._tasks) {
      window._tasks.length = 0;
      crossTasks.forEach(function(t){ window._tasks.push(Object.assign({}, t)); });
    }
    if (targetRef) window._uniTaskKeyOverride = 'tasks_v2_' + targetRef;

    window._saveTasks = function(){
      persistWelcomeTaskEdits(targetRef, window._tasks ? window._tasks.slice() : []);
    };

    window.closeTaskDetail = function(){
      var modal = document.getElementById('task-detail-modal');
      if (modal) modal.style.display = 'none';
      window._taskDetailId = null;

      try { persistWelcomeTaskEdits(targetRef, window._tasks ? window._tasks.slice() : []); } catch(e) {}

      if (window._tasks) {
        window._tasks.length = 0;
        origTasks.forEach(function(t){ window._tasks.push(t); });
      }

      window._uniTaskKeyOverride = origOverride;
      window.closeTaskDetail = origClose;
      window._saveTasks = origSave;

      _welcomeHardRefreshTasks();
    };

    if (typeof window.openTaskDetail === 'function') {
      try { window.openTaskDetail(found.id); } catch(e) { console.error('[welcome-fix] openTaskDetail error', e); }
    }
  };

  var prevWR = window.welcomeRefresh;
  if (typeof prevWR === 'function') {
    window.welcomeRefresh = function(){
      prevWR.apply(this, arguments);
      var tasksEl = document.getElementById('welcome-tasks-today');
      if (!tasksEl) return;
      try {
        var allDossiers = (typeof _getAllDossiersWithTasks === 'function') ? _getAllDossiersWithTasks() : [];
        var standalone = allTasksCanonical().filter(function(t){
          var ref = String(t._ref || t.ref || '').trim();
          return ref === 'STANDALONE' || ref === 'IMPORTADAS' || ref === 'DEVIS';
        });
        var td0 = new Date(); td0.setHours(0,0,0,0);
        var tdTomorrow = new Date(td0); tdTomorrow.setDate(td0.getDate()+1);
        var tdWeekEnd = new Date(td0); tdWeekEnd.setDate(td0.getDate()+14);
        var taskBuckets={today:[],tomorrow:[],upcoming:[]};
        var seen={};
        function pushItem(item){
          var due = new Date(item.due); due.setHours(0,0,0,0); if (isNaN(due.getTime())) return;
          var dt = due.getTime();
          if (dt===td0.getTime()) taskBuckets.today.push(item);
          else if (dt===tdTomorrow.getTime()) taskBuckets.tomorrow.push(item);
          else if (dt>td0.getTime() && dt<=tdWeekEnd.getTime()) taskBuckets.upcoming.push(item);
        }
        allDossiers.forEach(function(d){
          var pax = (d.fields && d.fields['pax-name-1']) || d.ref || '—';
          (d.tasks||[]).forEach(function(t){
            if (t.done || !t.due) return;
            var real = findTaskCanonical(t.id, d.ref) || t;
            var tid = String(real.id || t.id || '');
            if (tid) seen[tid] = true;
            pushItem({ref:d.ref,pax:pax,label:real.title||real.text||t.title||'(tâche)',due:real.dueDate||real.due||t.due,prio:real.prio||t.prio||'normale',taskId:tid});
          });
        });
        standalone.forEach(function(t){
          if (t.done) return;
          var tid = String(t.id||''); if (seen[tid]) return;
          pushItem({ref:String(t._ref||t.ref||'STANDALONE'),pax:String(t._ref||t.ref||'STANDALONE'),label:t.title||t.text||'(tâche)',due:t.dueDate||t.due||'',prio:t.prio||'normale',taskId:tid});
          seen[tid]=true;
        });
        ['today','tomorrow','upcoming'].forEach(function(b){ taskBuckets[b].sort(function(a,b2){ return new Date(a.due)-new Date(b2.due); }); });
        function esc(s){ return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
        function card(t){ var prioStyle = t.prio === 'haute' ? 'color:var(--red);' : 'color:var(--navy);';
          return '<div data-task-id="'+esc(t.taskId)+'" data-task-ref="'+esc(t.ref)+'" style="padding:0.42rem 0.5rem;border-bottom:1px solid rgba(6,32,59,0.07);font-size:0.74rem;cursor:pointer;">'
          + '<div style="font-weight:700;font-size:0.78rem;'+prioStyle+'">'+esc(t.label)+'</div>'
          + '<div style="font-size:0.68rem;color:var(--navy-soft);font-family:monospace;">'+esc(t.ref)+'</div>'
          + '<div style="font-size:0.68rem;color:var(--navy-soft);">'+esc(t.pax)+'</div></div>'; }
        function col(label, items, accent, maxV){
          var lim = (maxV != null && items.length > maxV) ? maxV : null;
          var vis = lim != null ? items.slice(0, lim) : items;
          var hid = lim != null ? items.slice(lim) : [];
          var uid = 'wfix-' + label.replace(/\W/g, '');
          return '<div style="border:1px solid var(--border);border-radius:8px;overflow:hidden;min-height:80px;">'
            + '<div style="padding:0.35rem 0.5rem;background:'+accent+';font-size:0.55rem;font-weight:700;letter-spacing:0.18em;text-transform:uppercase;color:#fff;">'+label+' <span style="opacity:0.7;font-size:0.65em;">('+items.length+')</span></div>'
            + (items.length===0 ? '<div style="padding:0.7rem 0.5rem;font-size:0.72rem;color:var(--navy-faint);font-style:italic;">—</div>' : vis.map(card).join('') + (hid.length>0 ? '<div id="'+uid+'" style="display:none;">'+hid.map(card).join('')+'</div><button onclick="(function(b,d){var o=d.style.display!==\'none\';d.style.display=o?\'none\':\''+';b.textContent=o?\'Voir tout (▾ '+hid.length+')\':\'Voir moins (▴)\';})(this,document.getElementById(\''+uid+'\'))" style="width:100%;padding:0.38rem 0.5rem;border:none;border-top:1px solid rgba(6,32,59,0.08);background:rgba(182,146,73,0.07);font-size:0.63rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:#b69249;cursor:pointer;font-family:inherit;text-align:center;">Voir tout (▾ '+hid.length+')</button>' : ''))
            + '</div>';
        }
        tasksEl.innerHTML = col("Aujourd'hui", taskBuckets.today, '#d80505') + col('Demain', taskBuckets.tomorrow, '#06203b') + col('Prochains', taskBuckets.upcoming, '#b69249', 3);
      } catch(e) { console.warn('[welcome-fix] welcomeRefresh task rebuild error', e); }
    };
  }

  document.addEventListener('click', function(e){
    var container = document.getElementById('welcome-tasks-today');
    if (!container || !container.contains(e.target)) return;
    var card = e.target.closest('[data-task-id]');
    if (!card) return;
    e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation && e.stopImmediatePropagation();
    var tid = card.getAttribute('data-task-id');
    var tref = card.getAttribute('data-task-ref') || '';
    if (tid) window._welcomeOpenTask(tid, tref);
  }, true);

  console.log('[welcome-fix] Welcome task popup uses canonical taskStore source and stays on Welcome after close.');
})();

