(function(){
  const LIVE_STRIPE_WORKER_URL = 'https://expatur-stripe.administration-a14.workers.dev/';
  const PW_SESSION_KEY = 'expatur_stripe_pw_cache';
  const POLL_MS = 15000;

  function getActiveRef(){
    try { return document.getElementById('booking-ref')?.value?.trim() || 'DEVIS'; } catch(e) { return 'DEVIS'; }
  }
  function paymentKey(){
    const ref = getActiveRef();
    return 'expatur_payments_' + ref.replace(/[^a-zA-Z0-9]/g, '_');
  }
  function invoiceKey(){
    const ref = getActiveRef();
    return 'expatur_em_invoice_' + ref.replace(/[^a-zA-Z0-9]/g, '_');
  }
  function readJson(k, fallback){
    try {
      const raw = localStorage.getItem(k);
      return raw ? JSON.parse(raw) : fallback;
    } catch(e) { return fallback; }
  }
  function writeJson(k, v){
    try {
      if (typeof window._lsSetSafe === 'function') window._lsSetSafe(k, v);
      else localStorage.setItem(k, JSON.stringify(v));
    } catch(e) {}
  }
  function storePw(pw){
    if (!pw) return;
    try { sessionStorage.setItem(PW_SESSION_KEY, pw); } catch(e) {}
    try { window._emLastUsedPw = pw; } catch(e) {}
    try {
      if (window._lastStripeInvoiceData) window._lastStripeInvoiceData.password = pw;
    } catch(e) {}
  }
  function getPw(){
    const pw = document.getElementById('em-stripe-pw')?.value || window._emLastUsedPw || (window._lastStripeInvoiceData && window._lastStripeInvoiceData.password) || sessionStorage.getItem(PW_SESSION_KEY) || '';
    if (pw) storePw(pw);
    return pw;
  }
  function attachPwCache(){
    const el = document.getElementById('em-stripe-pw');
    if (!el || el.__stripePwBound) return;
    el.__stripePwBound = true;
    el.addEventListener('input', function(){ storePw(el.value || ''); });
    if (el.value) storePw(el.value);
  }
  function normalizeStripeData(data){
    const snap = data && data.snapshot ? data.snapshot : (data || {});
    const invoiceStatus = snap.app_status || snap.status || snap.invoice_status || null;
    return {
      raw: snap,
      status: invoiceStatus,
      invoiceId: snap.invoice_id || snap.invoiceId || snap.id || null,
      invoicePdfUrl: snap.invoice_pdf || snap.invoicePdfUrl || null,
      receiptPdfUrl: snap.receipt_url || snap.receipt_pdf || snap.receiptPdfUrl || null,
      hostedUrl: snap.hosted_invoice_url || snap.hostedUrl || snap.url || null,
      paidAt: snap.last_sync_at || snap.last_sync || null,
      amountPaid: snap.amount_paid || null,
      paymentStatus: snap.payment_status || null,
      failureMessage: snap.failure_message || null,
    };
  }
  function mergeInvoiceStore(normalized, pw){
    if (!normalized || !normalized.invoiceId) return;
    const current = readJson(invoiceKey(), {}) || {};
    const merged = Object.assign({}, current, {
      invoiceId: normalized.invoiceId,
      invoicePdfUrl: normalized.invoicePdfUrl || current.invoicePdfUrl || null,
      receiptPdfUrl: normalized.receiptPdfUrl || current.receiptPdfUrl || null,
      hostedUrl: normalized.hostedUrl || current.hostedUrl || null,
      status: normalized.status || current.status || 'open',
      savedAt: new Date().toISOString()
    });
    writeJson(invoiceKey(), merged);
    window._lastStripeInvoiceData = Object.assign({}, window._lastStripeInvoiceData || {}, merged, { password: pw || getPw() || (window._lastStripeInvoiceData && window._lastStripeInvoiceData.password) || '' });
  }
  function mergePaymentHistoryRow(invoiceId, normalized){
    if (!invoiceId) return false;
    let changed = false;
    const keys = [];
    try {
      for (let i=0;i<localStorage.length;i++) {
        const k = localStorage.key(i);
        if (k && k.indexOf('expatur_payments_') === 0) keys.push(k);
      }
    } catch(e) {}
    const status = normalized.status || 'open';
    keys.forEach(function(k){
      const arr = readJson(k, []);
      if (!Array.isArray(arr)) return;
      let dirty = false;
      const next = arr.map(function(p){
        if ((p.stripeInvoiceId || p.invoiceId) !== invoiceId) return p;
        const out = Object.assign({}, p);
        out.status = status;
        if (status === 'paid') {
          out.pago = 'pago';
          out.paidAt = out.paidAt || normalized.paidAt || new Date().toISOString();
        }
        if (normalized.invoicePdfUrl) out.stripePdfUrl = normalized.invoicePdfUrl;
        if (normalized.receiptPdfUrl) {
          out.stripeReceiptUrl = normalized.receiptPdfUrl;
          out.receiptPdfUrl = normalized.receiptPdfUrl;
          out.receipt_pdf = normalized.receiptPdfUrl;
        }
        if (normalized.hostedUrl) out.stripeUrl = normalized.hostedUrl;
        if (JSON.stringify(out) !== JSON.stringify(p)) dirty = true;
        return out;
      });
      if (dirty) {
        writeJson(k, next);
        changed = true;
      }
    });
    return changed;
  }
  async function fetchStripeSync(invoiceId, pw, useCacheFirst){
    if (!invoiceId) throw new Error('Invoice ID manquant');
    const password = pw || getPw();
    if (!password) throw new Error('Mot de passe Stripe manquant');
    const headers = {'Content-Type':'application/json'};
    if (useCacheFirst) {
      try {
        const cachedResp = await fetch(LIVE_STRIPE_WORKER_URL, { method:'POST', headers, body: JSON.stringify({ action:'get_cached_invoice_status', invoiceId }) });
        const cachedData = await cachedResp.json();
        if (cachedResp.ok && cachedData && cachedData.snapshot) {
          const normalizedCached = normalizeStripeData(cachedData);
          mergeInvoiceStore(normalizedCached, password);
          mergePaymentHistoryRow(invoiceId, normalizedCached);
        }
      } catch(e) {}
    }
    const resp = await fetch(LIVE_STRIPE_WORKER_URL, {
      method:'POST', headers,
      body: JSON.stringify({ action:'sync_invoice_status', password, invoiceId })
    });
    const data = await resp.json();
    if (!resp.ok || data.error) throw new Error((data && (data.error || data.warning)) || ('HTTP ' + resp.status));
    const normalized = normalizeStripeData(data);
    mergeInvoiceStore(normalized, password);
    mergePaymentHistoryRow(invoiceId, normalized);
    return normalized;
  }

  window.emCheckInvoiceStatus = async function(invoiceId, dueDate){
    attachPwCache();
    try {
      const normalized = await fetchStripeSync(invoiceId, getPw(), true);
      if (typeof window.renderPaymentHistory === 'function') window.renderPaymentHistory();
      if (typeof window._blUpdatePaymentSection === 'function') window._blUpdatePaymentSection();
      const label = normalized.status === 'paid' ? 'Payée' : normalized.status === 'open' ? 'En attente' : (normalized.status || 'Inconnu');
      if (typeof window.toast === 'function') window.toast('Statut facture : ' + label, normalized.status === 'paid' ? 'success' : 'info');
      return normalized;
    } catch(e) {
      if (typeof window.toast === 'function') window.toast('Erreur vérification : ' + e.message, 'error');
      throw e;
    }
  };

  window._blFetchAndRefreshStripeData = async function(invoiceId, pw){
    const linksEl = document.getElementById('bl-payment-links');
    if (linksEl) linksEl.style.opacity = '0.4';
    try {
      const normalized = await fetchStripeSync(invoiceId, pw || getPw(), true);
      if (typeof window._blUpdatePaymentSection === 'function') window._blUpdatePaymentSection();
      if (typeof window.renderPaymentHistory === 'function') window.renderPaymentHistory();
      if (typeof window.toast === 'function') window.toast('Données Stripe actualisées ✓', 'success');
      return normalized;
    } catch(e) {
      if (typeof window.toast === 'function') window.toast('Erreur rafraîchissement : ' + e.message, 'error');
      throw e;
    } finally {
      if (linksEl) linksEl.style.opacity = '1';
    }
  };

  async function autoSyncOpenInvoices(){
    attachPwCache();
    const pw = getPw();
    if (!pw) return;
    if (document.hidden) return;
    const arr = readJson(paymentKey(), []);
    if (!Array.isArray(arr) || !arr.length) return;
    const pendingIds = [];
    arr.forEach(function(p){
      const st = String(p.status || '').toLowerCase();
      const invoiceId = p.stripeInvoiceId || p.invoiceId || null;
      if (invoiceId && st !== 'paid' && pendingIds.indexOf(invoiceId) === -1) pendingIds.push(invoiceId);
    });
    if (!pendingIds.length) return;
    let changed = false;
    for (const invoiceId of pendingIds) {
      try {
        const normalized = await fetchStripeSync(invoiceId, pw, false);
        if (normalized.status === 'paid') changed = true;
      } catch(e) {
        console.warn('[stripe-auto-sync] sync failed for', invoiceId, e);
      }
    }
    if (changed) {
      if (typeof window.renderPaymentHistory === 'function') window.renderPaymentHistory();
      if (typeof window._blUpdatePaymentSection === 'function') window._blUpdatePaymentSection();
    }
  }

  function boot(){
    attachPwCache();
    setTimeout(autoSyncOpenInvoices, 2500);
    setInterval(autoSyncOpenInvoices, POLL_MS);
    document.addEventListener('visibilitychange', function(){ if (!document.hidden) setTimeout(autoSyncOpenInvoices, 500); });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();

