(function(){
  /* ===== Authoritative Airline Logo Resolution (consolidated) ===== */
  var AIRLINE_LOGO_BASE_URL_W = '/assets/airlines/'; // espelhado em public/
  window.AIRLINE_LOGO_BASE_URL = AIRLINE_LOGO_BASE_URL_W;
  window.AIRLINE_LOGO_DEFAULT  = AIRLINE_LOGO_BASE_URL_W + 'default.svg';
  window.AIRLINE_LOGO_CACHE_BUST = String(Date.now());

  function _escLogo(v){
    return String(v == null ? '' : v)
      .replace(/&/g,'&amp;').replace(/"/g,'&quot;')
      .replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }

  function sanitizeAirlineIata(value) {
    var raw = String(value || '').trim().toUpperCase();
    if (!raw) return '';
    return /^[A-Z0-9]{2,3}$/.test(raw) ? raw.toLowerCase() : '';
  }

  function extractAirlineIataFromFlightNumber(value) {
    var raw = String(value || '').trim().toUpperCase();
    if (!raw) return '';
    var m = raw.match(/^([A-Z0-9]{2,3})\s*\d+/);
    return m ? m[1].toLowerCase() : '';
  }

  window.getAirlineLogoCode = function(input) {
    if (!input) return '';

    if (typeof input === 'string') {
      return sanitizeAirlineIata(input) || extractAirlineIataFromFlightNumber(input) || '';
    }

    if (typeof input === 'object') {
      var code =
        sanitizeAirlineIata(input.iata) ||
        sanitizeAirlineIata(input.airline_iata) ||
        sanitizeAirlineIata(input.marketing_carrier) ||
        sanitizeAirlineIata(input.marketingCarrier) ||
        sanitizeAirlineIata(input.marketingCarrierCode) ||
        sanitizeAirlineIata(input.operating_carrier) ||
        sanitizeAirlineIata(input.operatingCarrier) ||
        sanitizeAirlineIata(input.operatingCarrierCode) ||
        sanitizeAirlineIata(input.carrier) ||
        sanitizeAirlineIata(input.carrierCode) ||
        sanitizeAirlineIata(input.airlineCode) ||
        sanitizeAirlineIata(input.code) ||
        sanitizeAirlineIata(input.linked_airline_iata);

      if (code) return code;

      if (Array.isArray(input.airlineCodes)) {
        for (var a = 0; a < input.airlineCodes.length; a++) {
          code = sanitizeAirlineIata(input.airlineCodes[a]);
          if (code) return code;
        }
      }

      code =
        extractAirlineIataFromFlightNumber(input.flight_number) ||
        extractAirlineIataFromFlightNumber(input.fn) ||
        extractAirlineIataFromFlightNumber(input.flightNumber) ||
        extractAirlineIataFromFlightNumber(input.flightNo) ||
        extractAirlineIataFromFlightNumber(input.display_flight_number) ||
        extractAirlineIataFromFlightNumber(input.label) ||
        extractAirlineIataFromFlightNumber(input.flight);

      if (code) return code;

      if (Array.isArray(input.segments)) {
        for (var s = 0; s < input.segments.length; s++) {
          var seg = input.segments[s];
          if (!seg) continue;
          code =
            sanitizeAirlineIata(seg.iata) ||
            sanitizeAirlineIata(seg.airline_iata) ||
            sanitizeAirlineIata(seg.marketing_carrier) ||
            sanitizeAirlineIata(seg.operating_carrier) ||
            sanitizeAirlineIata(seg.carrier) ||
            sanitizeAirlineIata(seg.linked_airline_iata) ||
            extractAirlineIataFromFlightNumber(seg.flight_number) ||
            extractAirlineIataFromFlightNumber(seg.fn) ||
            extractAirlineIataFromFlightNumber(seg.flightNo);
          if (code) return code;
        }
      }
    }

    return '';
  };

  window.getAirlineLogoUrl = function(input) {
    var iata = window.getAirlineLogoCode(input);
    if (!iata) return window.AIRLINE_LOGO_DEFAULT + '?v=' + window.AIRLINE_LOGO_CACHE_BUST;
    return AIRLINE_LOGO_BASE_URL_W + iata + '.svg?v=' + window.AIRLINE_LOGO_CACHE_BUST;
  };

  window.getAirlineLogo = function(airline){
    var label = (typeof airline === 'object' ? (airline.airline || airline.name || airline.fn || airline.flight_number || 'Airline') : (airline || 'Airline'));
    var src = window.getAirlineLogoUrl(airline);
    return '<img class="airline-logo-img" src="'+src+'" alt="'+_escLogo(label)+'" loading="eager" decoding="sync" crossorigin="anonymous" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src=\''+window.AIRLINE_LOGO_DEFAULT+'?v='+window.AIRLINE_LOGO_CACHE_BUST+'\';">';
  };

  window.guessAirlineIata = function(label){
    return window.getAirlineLogoCode(label || '');
  };

  /* Also expose helpers globally for other code paths */
  window.sanitizeAirlineIata = sanitizeAirlineIata;
  window.extractAirlineIataFromFlightNumber = extractAirlineIataFromFlightNumber;

  /* ===== New welcome task-card design ===== */
  var style = document.createElement('style');
  style.textContent = [
    '#welcome-tasks-today:not([data-render-ready="1"]){visibility:hidden;opacity:0;display:none;}',
    '.welcome-task-col{border:1px solid var(--border);border-radius:10px;overflow:hidden;background:#fff;min-height:94px;box-shadow:0 2px 10px rgba(6,32,59,0.04);}',
    '.welcome-task-col-h{padding:0.5rem 0.7rem;color:#fff;font-size:0.56rem;font-weight:700;letter-spacing:0.16em;text-transform:uppercase;display:flex;align-items:center;justify-content:space-between;}',
    '.welcome-task-col-b{display:flex;flex-direction:column;}',
    '.welcome-task-empty{padding:0.9rem 0.75rem;font-size:0.74rem;color:var(--navy-faint);font-style:italic;}',
    '.welcome-task-card{padding:0.72rem 0.75rem;border-bottom:1px solid rgba(6,32,59,0.07);cursor:pointer;transition:background 0.12s, transform 0.12s;display:flex;flex-direction:column;gap:0.32rem;background:#fff;}',
    '.welcome-task-card:last-child{border-bottom:none;}',
    '.welcome-task-card:hover{background:rgba(6,32,59,0.03);}',
    '.welcome-task-top{display:flex;align-items:flex-start;justify-content:space-between;gap:0.5rem;}',
    '.welcome-task-title{font-size:0.8rem;font-weight:700;color:var(--navy);line-height:1.25;}',
    '.welcome-task-meta{display:flex;align-items:center;gap:0.4rem;flex-wrap:wrap;font-size:0.67rem;color:var(--navy-soft);}',
    '.welcome-task-ref{font-family:monospace;font-weight:700;color:var(--gold);background:rgba(216,5,5,0.06);padding:1px 6px;border-radius:999px;}',
    '.welcome-task-pax{color:var(--navy-soft);}',
    '.welcome-task-prio{font-size:0.56rem;font-weight:700;padding:2px 7px;border-radius:999px;letter-spacing:0.08em;text-transform:uppercase;white-space:nowrap;}',
    '.welcome-task-prio.haute{background:rgba(216,5,5,0.1);color:var(--red);}',
    '.welcome-task-prio.normale{background:rgba(6,32,59,0.08);color:var(--navy);}',
    '.welcome-task-prio.basse{background:rgba(156,163,175,0.2);color:#6b7280;}',
    '.welcome-task-more{width:100%;padding:0.48rem 0.65rem;border:none;border-top:1px solid rgba(6,32,59,0.08);background:rgba(182,146,73,0.07);font-size:0.63rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:#b69249;cursor:pointer;font-family:inherit;text-align:center;}',
    '.welcome-task-more:hover{background:rgba(182,146,73,0.14);}'
  ].join('');
  document.head.appendChild(style);

  function _safe(v){
    if (typeof window._esc === 'function') return window._esc(v);
    return String(v == null ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }
  function _allTasksLookup(){
    var map = {};
    try {
      for (var i=0;i<localStorage.length;i++){
        var k = localStorage.key(i);
        if (!k || k.indexOf('tasks_v2_') !== 0) continue;
        var ref = k.replace('tasks_v2_','');
        try { map[ref] = JSON.parse(localStorage.getItem(k) || '[]'); } catch(_) {}
      }
    } catch(_) {}
    return map;
  }
  window._renderWelcomeTaskCardsFinal = _renderWelcomeTaskCardsFinal;
  function _renderWelcomeTaskCardsFinal(){
    var tasksEl = document.getElementById('welcome-tasks-today');
    if (!tasksEl) return;
    tasksEl.style.visibility = 'visible';
    tasksEl.style.opacity = '1';
    tasksEl.style.display = 'grid';
    tasksEl.style.gridTemplateColumns = 'repeat(3,1fr)';
    tasksEl.style.gap = '0.6rem';

    var allDossiers = (typeof window._getAllDossiersWithTasks === 'function') ? window._getAllDossiersWithTasks() : [];
    var lookup = _allTasksLookup();
    var today = new Date(); today.setHours(0,0,0,0);
    var tomorrow = new Date(today); tomorrow.setDate(today.getDate()+1);
    var horizon = new Date(today); horizon.setDate(today.getDate()+14);
    var buckets = { today: [], tomorrow: [], upcoming: [] };
    var seen = {};

    function pushItem(item, dueTs){
      if (dueTs === today.getTime()) buckets.today.push(item);
      else if (dueTs === tomorrow.getTime()) buckets.tomorrow.push(item);
      else if (dueTs > today.getTime() && dueTs <= horizon.getTime()) buckets.upcoming.push(item);
    }

    allDossiers.forEach(function(d){
      var ref = d.ref || '';
      var pax = (d.fields && d.fields['pax-name-1']) || ref || '—';
      var canonical = lookup[ref] || [];
      var byTitle = {};
      canonical.forEach(function(t){ byTitle[String(t.title||t.text||'').trim().toLowerCase()] = t; });
      (d.tasks || []).forEach(function(t){
        if (t.done || !t.due) return;
        var due = new Date(t.due); due.setHours(0,0,0,0);
        if (isNaN(due.getTime())) return;
        var match = byTitle[String(t.title||'').trim().toLowerCase()] || null;
        var taskId = match ? String(match.id || '') : '';
        if (taskId) seen[taskId] = true;
        pushItem({ taskId: taskId, ref: ref, pax: pax, label: t.title || '(tâche)', prio: t.prio || 'normale', due: due }, due.getTime());
      });
    });

    ['STANDALONE','IMPORTADAS','DEVIS'].forEach(function(ref){
      (lookup[ref] || []).forEach(function(t){
        var tid = String(t.id || '');
        if (!tid || seen[tid] || t.done) return;
        var due = new Date(t.dueDate || t.due || ''); due.setHours(0,0,0,0);
        if (isNaN(due.getTime())) return;
        seen[tid] = true;
        pushItem({ taskId: tid, ref: ref, pax: ref, label: t.title || t.text || '(tâche)', prio: t.prio || 'normale', due: due }, due.getTime());
      });
    });

    ['today','tomorrow','upcoming'].forEach(function(k){ buckets[k].sort(function(a,b){ return a.due - b.due; }); });

    function card(item){
      return '<div class="welcome-task-card" data-task-id="'+_safe(item.taskId)+'" data-task-ref="'+_safe(item.ref)+'">'
        + '<div class="welcome-task-top">'
        +   '<div class="welcome-task-title">'+_safe(item.label)+'</div>'
        +   '<span class="welcome-task-prio '+_safe(item.prio)+'">'+_safe(item.prio)+'</span>'
        + '</div>'
        + '<div class="welcome-task-meta">'
        +   '<span class="welcome-task-ref">'+_safe(item.ref)+'</span>'
        +   '<span class="welcome-task-pax">'+_safe(item.pax)+'</span>'
        + '</div>'
        + '</div>';
    }
    function col(label, items, accent, maxVisible){
      var vis = items, hid = [];
      if (typeof maxVisible === 'number' && items.length > maxVisible) {
        vis = items.slice(0, maxVisible);
        hid = items.slice(maxVisible);
      }
      var uid = 'welcome-task-more-' + label.replace(/\W/g,'');
      return '<div class="welcome-task-col">'
        + '<div class="welcome-task-col-h" style="background:'+accent+'"><span>'+label+'</span><span style="opacity:.75">('+items.length+')</span></div>'
        + '<div class="welcome-task-col-b">'
        +   (items.length ? vis.map(card).join('') : '<div class="welcome-task-empty">—</div>')
        +   (hid.length ? '<div id="'+uid+'" style="display:none;">'+hid.map(card).join('')+'</div><button class="welcome-task-more" onclick="(function(b,d){var o=d.style.display!==\'none\';d.style.display=o?\'none\':\'\';b.textContent=o?\'Voir tout ('+hid.length+')\':\'Voir moins\';})(this,document.getElementById(\''+uid+'\'))">Voir tout ('+hid.length+')</button>' : '')
        + '</div></div>';
    }

    tasksEl.innerHTML = col("Aujourd'hui", buckets.today, '#d80505')
      + col('Demain', buckets.tomorrow, '#06203b')
      + col('Prochains', buckets.upcoming, '#b69249', 3);
  }

  var _prevFinalWelcomeRefresh = window.welcomeRefresh;
  window.welcomeRefresh = function(){
    if (typeof _prevFinalWelcomeRefresh === 'function') _prevFinalWelcomeRefresh.apply(this, arguments);
    try { _renderWelcomeTaskCardsFinal(); } catch(e) { console.warn('[final] welcome task render fix failed', e); }
  };

  var _prevFinalSidebarGo = window.sidebarGo;
  if (typeof _prevFinalSidebarGo === 'function') {
    window.sidebarGo = function(section){
      var out = _prevFinalSidebarGo.apply(this, arguments);
      if (section === 'welcome') {
        try { setTimeout(function(){ if (typeof window.welcomeRefresh === 'function') window.welcomeRefresh(); }, 0); } catch(_) {}
      }
      return out;
    };
  }

  document.addEventListener('DOMContentLoaded', function(){
    try { _renderWelcomeTaskCardsFinal(); } catch(_) {}
  });
})();

