/* ======================================================================
   First-load Welcome task flash killer
   Prevent any legacy card HTML from painting on first Accueil load.
   ====================================================================== */
(function(){
  'use strict';
  if (window._welcomeFirstPaintNoFlash) return;
  window._welcomeFirstPaintNoFlash = true;

  function el(){ return document.getElementById('welcome-tasks-today'); }
  function seal(){
    var n = el();
    if (!n) return;
    n.setAttribute('data-render-ready','0');
    n.style.display = 'none';
    n.style.visibility = 'hidden';
    n.style.opacity = '0';
    n.style.contentVisibility = 'hidden';
    n.innerHTML = '';
  }
  function reveal(){
    var n = el();
    if (!n) return;
    n.setAttribute('data-render-ready','1');
    n.style.display = 'grid';
    n.style.gridTemplateColumns = 'repeat(3,1fr)';
    n.style.gap = '0.6rem';
    n.style.visibility = 'visible';
    n.style.opacity = '1';
    n.style.contentVisibility = 'visible';
  }

  // apply as early as possible during first parse
  seal();

  var prevWR = window.welcomeRefresh;
  if (typeof prevWR === 'function') {
    window.welcomeRefresh = function(){
      seal();
      var out = prevWR.apply(this, arguments);
      try {
        requestAnimationFrame(function(){
          requestAnimationFrame(function(){
            reveal();
          });
        });
      } catch(_) { reveal(); }
      return out;
    };
  }

  var prevSG = window.sidebarGo;
  if (typeof prevSG === 'function') {
    window.sidebarGo = function(section){
      if (section === 'welcome') seal();
      var out = prevSG.apply(this, arguments);
      if (section === 'welcome') {
        try {
          requestAnimationFrame(function(){
            requestAnimationFrame(function(){
              reveal();
            });
          });
        } catch(_) { reveal(); }
      }
      return out;
    };
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', seal, { once:true });
  } else {
    seal();
  }
})();

