/* ==========================================================================
   Patch v3.92 — Welcome tasks no-flash final gate
   Fixes:
   1) Prevent legacy welcome task columns/cards from ever becoming visible.
   2) Debounce multiple welcomeRefresh/sidebarGo startup calls into one paint.
   3) Eliminate first-load flash and open/close task popup reflash.
   ========================================================================== */
(function(){
  'use strict';
  if (window._v392WelcomeNoFlashFinal) return;
  window._v392WelcomeNoFlashFinal = true;

  var _raf = 0, _to = 0;
  function _el(){ return document.getElementById('welcome-tasks-today'); }
  function _injectLockCss(){
    if (document.getElementById('welcome-task-lock-style')) return;
    var st = document.createElement('style');
    st.id = 'welcome-task-lock-style';
    st.textContent =
      '#welcome-tasks-today[data-v392-lock="1"]{' +
      'display:none !important;visibility:hidden !important;opacity:0 !important;content-visibility:hidden !important;}' +
      '#welcome-tasks-today[data-v392-lock="1"] *{' +
      'visibility:hidden !important;opacity:0 !important;animation:none !important;transition:none !important;}' +
      '#welcome-tasks-today[data-v392-lock="1"] .welcome-task-card,' +
      '#welcome-tasks-today[data-v392-lock="1"] .welcome-task-col{' +
      'display:none !important;}';
    document.head.appendChild(st);
  }
  function _lock(clear){
    _injectLockCss();
    var n = _el();
    if (!n) return;
    n.setAttribute('data-v392-lock','1');
    n.setAttribute('data-render-ready','0');
    if (clear) n.innerHTML = '';
  }
  function _unlock(){
    var n = _el();
    if (!n) return;
    n.removeAttribute('data-v392-lock');
    n.setAttribute('data-render-ready','1');
    n.style.display = 'grid';
    n.style.gridTemplateColumns = 'repeat(3,1fr)';
    n.style.gap = '0.6rem';
    n.style.visibility = 'visible';
    n.style.opacity = '1';
    n.style.contentVisibility = 'visible';
  }
  function _finalRender(){
    _raf = 0; _to = 0;
    try {
      /* Prefer v3.90 renderer if available (it has airline logos + canonical taskStore) */
      if (typeof window._v390RenderAndShow === 'function') {
        window._v390RenderAndShow();
      } else if (typeof window._renderWelcomeTaskCardsFinal === 'function') {
        window._renderWelcomeTaskCardsFinal();
      }
    } catch (e) {
      console.warn('[v3.92] final welcome render failed', e);
    }
    _unlock();
  }
  function _scheduleFinal(){
    try { if (_raf) cancelAnimationFrame(_raf); } catch(_) {}
    try { if (_to) clearTimeout(_to); } catch(_) {}
    _raf = requestAnimationFrame(function(){
      _to = setTimeout(_finalRender, 0);
    });
  }

  _lock(true);

  var _baseWelcomeRefresh = window.welcomeRefresh;
  if (typeof _baseWelcomeRefresh === 'function') {
    window.welcomeRefresh = function(){
      _lock(false);
      var out = _baseWelcomeRefresh.apply(this, arguments);
      _scheduleFinal();
      return out;
    };
  }

  var _baseSidebarGo = window.sidebarGo;
  if (typeof _baseSidebarGo === 'function') {
    window.sidebarGo = function(section){
      if (section === 'welcome') _lock(true);
      var out = _baseSidebarGo.apply(this, arguments);
      if (section === 'welcome') _scheduleFinal();
      return out;
    };
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function(){
      _lock(true);
      if (typeof window._currentSection !== 'undefined' && window._currentSection === 'welcome') {
        _scheduleFinal();
      }
    }, {once:true});
  } else {
    _lock(true);
    if (typeof window._currentSection !== 'undefined' && window._currentSection === 'welcome') {
      _scheduleFinal();
    }
  }
  /* Safety net: ensure tasks become visible after all scripts have run */
  setTimeout(function(){
    var n = _el();
    if (!n) return;
    if (n.getAttribute('data-render-ready') !== '1' &&
        typeof window._currentSection !== 'undefined' && window._currentSection === 'welcome') {
      _finalRender();
    }
  }, 500);
  setTimeout(function(){
    var n = _el();
    if (!n) return;
    if (n.getAttribute('data-render-ready') !== '1' &&
        typeof window._currentSection !== 'undefined' && window._currentSection === 'welcome') {
      _finalRender();
    }
  }, 1500);
})();

