/* ── vInstallmentOfflineActions: wheel actions for invoices ── */
function _getInvoiceItemsStore() {
  if (!Array.isArray(window.__emStripeItems)) window.__emStripeItems = [];
  return window.__emStripeItems;
}
function _setInvoiceItemsStore(items) {
  window.__emStripeItems = Array.isArray(items) ? items : [];
}
function _sumInvoiceItems(items) {
  return _roundMoney((items || []).reduce((s, x) => s + _roundMoney(x.total ?? x.amount_value ?? x.amount ?? 0), 0));
}
function _normalizeInvoiceItemAmounts(items) {
  return (items || []).map(function(x){
    const n = _roundMoney(x.total ?? x.amount_value ?? x.amount ?? 0);
    return { ...x, total:n, amount_value:n, amount:n, quantity:1 };
  });
}
/* ── Stripe sync helpers — keep app ↔ Stripe aligned ── */
function _getStripePassword() {
  return window._emLastUsedPw || document.getElementById('em-stripe-pw')?.value || '';
}
function _findStripeInvoiceIdForIndex(idx) {
  // Try __emStripeItems first
  var items = Array.isArray(window.__emStripeItems) ? window.__emStripeItems : [];
  if (items[idx] && items[idx].stripeInvoiceId) return items[idx].stripeInvoiceId;
  // Fall back to payment history records (match by _installmentIndex)
  try {
    var hist = (typeof loadPaymentHistory === 'function') ? loadPaymentHistory() : [];
    var match = hist.filter(function(r) { return r._installmentIndex === idx && !!r.stripeInvoiceId; });
    if (match.length) return match[match.length - 1].stripeInvoiceId;
    // If only one record at this index position, use it
    if (idx < hist.length && hist[idx].stripeInvoiceId) return hist[idx].stripeInvoiceId;
  } catch (_e) {}
  return null;
}
function _syncStripeMarkPaid(invoiceId) {
  if (!invoiceId) return;
  var pw = _getStripePassword();
  if (!pw) { console.warn('[StripeSync] No password — skipping mark-paid sync'); return; }
  var url = (typeof STRIPE_WORKER_URL !== 'undefined') ? STRIPE_WORKER_URL : '';
  if (!url) return;
  fetch(url, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ type: 'mark_paid', password: pw, invoice_id: invoiceId, paid_out_of_band: true })
  }).then(function(r) {
    if (!r.ok) console.warn('[StripeSync] mark_paid HTTP', r.status);
    else console.log('[StripeSync] Invoice', invoiceId, 'marked paid in Stripe');
  }).catch(function(e) { console.warn('[StripeSync] mark_paid failed:', e); });
}
function _syncStripeMarkOpen(invoiceId) {
  if (!invoiceId) return;
  var pw = _getStripePassword();
  if (!pw) return;
  var url = (typeof STRIPE_WORKER_URL !== 'undefined') ? STRIPE_WORKER_URL : '';
  if (!url) return;
  fetch(url, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ type: 'mark_open', password: pw, invoice_id: invoiceId })
  }).then(function(r) {
    if (!r.ok) console.warn('[StripeSync] mark_open HTTP', r.status);
    else console.log('[StripeSync] Invoice', invoiceId, 'marked open in Stripe');
  }).catch(function(e) { console.warn('[StripeSync] mark_open failed:', e); });
}
function _syncStripeUpdateAmount(invoiceId, newAmountDecimal, currency) {
  if (!invoiceId || !newAmountDecimal) return;
  var pw = _getStripePassword();
  if (!pw) return;
  var url = (typeof STRIPE_WORKER_URL !== 'undefined') ? STRIPE_WORKER_URL : '';
  if (!url) return;
  var amountCents = Math.round(newAmountDecimal * 100);
  fetch(url, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ type: 'update_amount', password: pw, invoice_id: invoiceId, amount: amountCents, currency: (currency || '').toLowerCase() })
  }).then(function(r) {
    if (!r.ok) console.warn('[StripeSync] update_amount HTTP', r.status);
    else console.log('[StripeSync] Invoice', invoiceId, 'amount updated to', newAmountDecimal);
  }).catch(function(e) { console.warn('[StripeSync] update_amount failed:', e); });
}

function _toggleInvoicePaidState(itemIndex, paid) {
  try {
    const items = _normalizeInvoiceItemAmounts(_getInvoiceItemsStore());
    if (itemIndex < 0 || itemIndex >= items.length) return;

    // First invoice remains paid in offline installment flow.
    if (itemIndex === 0 && paid === false && _isOfflineMethod(_getPaymentMethodLive()) && _isInstallmentMode(_getPaymentModeLive())) {
      return;
    }

    items[itemIndex].manual_paid = !!paid;
    items[itemIndex].marked_paid_manually = !!paid;
    items[itemIndex].invoice_status = paid ? 'paid' : 'open';
    items[itemIndex].status = items[itemIndex].invoice_status;
    items[itemIndex].paid_at = paid ? (items[itemIndex].paid_at || new Date().toISOString()) : null;

    _setInvoiceItemsStore(items);
    populateStripeItems();
    if (typeof emOnSplitAmtChange === 'function') emOnSplitAmtChange();
    if (typeof _refreshEmissionTotal === 'function') _refreshEmissionTotal();
    if (typeof refreshPaymentHistoryPanel === 'function') refreshPaymentHistoryPanel();

    // ── Stripe sync: push paid/open status ──
    var stripeId = _findStripeInvoiceIdForIndex(itemIndex);
    if (stripeId) {
      if (paid) _syncStripeMarkPaid(stripeId);
      else _syncStripeMarkOpen(stripeId);
    }
    // Also update localStorage payment record status
    try {
      var hist = (typeof loadPaymentHistory === 'function') ? loadPaymentHistory() : [];
      var rec = hist.filter(function(r) { return r._installmentIndex === itemIndex; });
      if (rec.length) {
        rec[rec.length - 1].status = paid ? 'paid' : 'open';
        rec[rec.length - 1].paidAt = paid ? (rec[rec.length - 1].paidAt || new Date().toISOString()) : null;
        rec[rec.length - 1].marked_paid_manually = !!paid;
        var key = (typeof _paymentKey === 'function') ? _paymentKey() : null;
        if (key) localStorage.setItem(key, JSON.stringify(hist));
      }
    } catch (_e2) {}
  } catch (e) {
    console.warn('[vInstallmentOfflineActions] toggle paid failed:', e);
  }
}
function _rebalanceAfterInvoiceAmountEdit(itemIndex, newAmount) {
  try {
    let items = _normalizeInvoiceItemAmounts(_getInvoiceItemsStore());
    if (itemIndex < 0 || itemIndex >= items.length) return;
    const target = items[itemIndex];
    const st = String(target.invoice_status || target.status || '').toLowerCase();
    if (st === 'paid') return;

    const newVal = _roundMoney(newAmount);
    if (newVal < 0) return;

    const unpaidIdx = items.map((x,i)=>({x,i})).filter(({x}) => String(x.invoice_status || x.status || '').toLowerCase() !== 'paid').map(({i}) => i);
    if (!unpaidIdx.includes(itemIndex)) return;

    target.total = newVal;
    target.amount_value = newVal;
    target.amount = newVal;

    const cur = (typeof _getInvoiceCurrency === 'function') ? _getInvoiceCurrency() : '';
    const othersUnpaid = unpaidIdx.filter(i => i !== itemIndex);
    if (!othersUnpaid.length) {
      _setInvoiceItemsStore(items);
      populateStripeItems();
      if (typeof emOnSplitAmtChange === 'function') emOnSplitAmtChange();
      if (typeof _refreshEmissionTotal === 'function') _refreshEmissionTotal();
      if (typeof refreshPaymentHistoryPanel === 'function') refreshPaymentHistoryPanel();
      // ── Stripe sync: push edited amount ──
      var sid = _findStripeInvoiceIdForIndex(itemIndex);
      if (sid) _syncStripeUpdateAmount(sid, newVal, cur);
      _syncPaymentRecordAmount(itemIndex, newVal);
      return;
    }

    const lastOtherUnpaid = othersUnpaid[othersUnpaid.length - 1];
    const targetTotal = _roundMoney(_getInvoiceAmount());
    const sumExceptLast = _roundMoney(items.reduce((s, x, i) => {
      if (i === lastOtherUnpaid) return s;
      return s + _roundMoney(x.total ?? x.amount_value ?? x.amount ?? 0);
    }, 0));

    const remainder = _roundMoney(targetTotal - sumExceptLast);
    if (remainder < 0) return;

    items[lastOtherUnpaid].total = remainder;
    items[lastOtherUnpaid].amount_value = remainder;
    items[lastOtherUnpaid].amount = remainder;

    _setInvoiceItemsStore(items);
    populateStripeItems();
    if (typeof emOnSplitAmtChange === 'function') emOnSplitAmtChange();
    if (typeof _refreshEmissionTotal === 'function') _refreshEmissionTotal();
    if (typeof refreshPaymentHistoryPanel === 'function') refreshPaymentHistoryPanel();
    // ── Stripe sync: push both edited + rebalanced amounts ──
    var sid1 = _findStripeInvoiceIdForIndex(itemIndex);
    if (sid1) _syncStripeUpdateAmount(sid1, newVal, cur);
    _syncPaymentRecordAmount(itemIndex, newVal);
    var sid2 = _findStripeInvoiceIdForIndex(lastOtherUnpaid);
    if (sid2) _syncStripeUpdateAmount(sid2, remainder, cur);
    _syncPaymentRecordAmount(lastOtherUnpaid, remainder);
  } catch (e) {
    console.warn('[vInstallmentOfflineActions] rebalance edit failed:', e);
  }
}
/* Helper: sync amount change back to localStorage payment record */
function _syncPaymentRecordAmount(itemIndex, newAmount) {
  try {
    var hist = (typeof loadPaymentHistory === 'function') ? loadPaymentHistory() : [];
    var rec = hist.filter(function(r) { return r._installmentIndex === itemIndex; });
    if (rec.length) {
      rec[rec.length - 1].amount = newAmount;
      var key = (typeof _paymentKey === 'function') ? _paymentKey() : null;
      if (key) localStorage.setItem(key, JSON.stringify(hist));
    }
  } catch (_e) {}
}
function _invoiceActionMenuHtml(idx, isPaid) {
  const isOfflineInstallment = _isOfflineMethod(_getPaymentMethodLive()) && _isInstallmentMode(_getPaymentModeLive());
  const canMarkOpen = !(isOfflineInstallment && idx === 0);
  return '<div class="em-invoice-actions" style="position:relative;display:inline-block;">'
    + '<button type="button" class="btn btn-gold btn-sm" data-invoice-menu-btn="' + idx + '" style="min-width:auto;padding:4px 8px;">⚙</button>'
    + '<div class="em-invoice-menu" data-invoice-menu="' + idx + '" style="display:none;position:absolute;right:0;top:calc(100% + 4px);background:#fff;border:1px solid var(--border);border-radius:8px;box-shadow:0 10px 30px rgba(6,32,59,0.14);padding:6px;z-index:50;min-width:180px;">'
    +   (isPaid
          ? (canMarkOpen ? '<button type="button" class="btn btn-gold btn-sm" data-invoice-mark-open="' + idx + '" style="width:100%;justify-content:flex-start;padding:6px 10px;">Mark as open</button>' : '')
          : '<button type="button" class="btn btn-gold btn-sm" data-invoice-mark-paid="' + idx + '" style="width:100%;justify-content:flex-start;padding:6px 10px;">Mark as paid</button>')
    +   (!isPaid ? '<button type="button" class="btn btn-gold btn-sm" data-invoice-edit-amount="' + idx + '" style="width:100%;justify-content:flex-start;padding:6px 10px;margin-top:4px;">Edit invoice amount</button>' : '')
    + '</div></div>';
}
function _bindInvoiceMenuActions(cont) {
  if (!cont) return;
  cont.querySelectorAll('[data-invoice-menu-btn]').forEach(function(btn){
    btn.addEventListener('click', function(e){
      e.stopPropagation();
      const idx = this.getAttribute('data-invoice-menu-btn');
      cont.querySelectorAll('.em-invoice-menu').forEach(function(m){
        if (m.getAttribute('data-invoice-menu') === idx) {
          m.style.display = m.style.display === 'block' ? 'none' : 'block';
        } else {
          m.style.display = 'none';
        }
      });
    });
  });
  cont.querySelectorAll('[data-invoice-mark-paid]').forEach(function(btn){
    btn.addEventListener('click', function(e){
      e.stopPropagation();
      _toggleInvoicePaidState(parseInt(this.getAttribute('data-invoice-mark-paid') || '-1', 10), true);
    });
  });
  cont.querySelectorAll('[data-invoice-mark-open]').forEach(function(btn){
    btn.addEventListener('click', function(e){
      e.stopPropagation();
      _toggleInvoicePaidState(parseInt(this.getAttribute('data-invoice-mark-open') || '-1', 10), false);
    });
  });
  cont.querySelectorAll('[data-invoice-edit-amount]').forEach(function(btn){
    btn.addEventListener('click', function(e){
      e.stopPropagation();
      const idx = parseInt(this.getAttribute('data-invoice-edit-amount') || '-1', 10);
      const items = _normalizeInvoiceItemAmounts(_getInvoiceItemsStore());
      const current = items[idx];
      if (!current) return;
      const val = window.prompt('New invoice amount', String(_roundMoney(current.total ?? current.amount_value ?? current.amount ?? 0).toFixed(2)));
      if (val == null) return;
      const num = parseFloat(String(val).replace(',', '.'));
      if (!Number.isFinite(num)) return;
      _rebalanceAfterInvoiceAmountEdit(idx, num);
    });
  });
  document.addEventListener('click', function(){
    document.querySelectorAll('.em-invoice-menu').forEach(function(m){ m.style.display = 'none'; });
  }, { once:true });
}

function _canIssueTicketsAgainstInvoices() {
  try {
    const items = Array.isArray(window.__emStripeItems) ? window.__emStripeItems : [];
    const method = _getPaymentMethodLive();
    const mode = _getPaymentModeLive();
    if (!_isOfflineMethod(method) || !_isInstallmentMode(mode)) {
      return items.some(function(x){ return String(x.invoice_status || x.status || '').toLowerCase() === 'paid'; });
    }
    const first = items[0];
    return !!first && String(first.invoice_status || first.status || '').toLowerCase() === 'paid';
  } catch (e) {
    return false;
  }
}

