/* ==========================================================================
   Patch v3.98 — Vendedores: server persistence, detail popup, linked dossiers
   ========================================================================== */
(function(){
  'use strict';
  if (window._v398VendedoresComplete) return;
  window._v398VendedoresComplete = true;

  function _esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
  function _fmtDate(iso){ if (!iso) return '—'; try { var d = new Date(iso); return d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit',year:'numeric'}); } catch(e){ return iso; } }
  function _fmtMoney(v, cur){ var n = parseFloat(v)||0; return n.toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2}) + (cur ? ' ' + cur : ''); }

  /* ── 1. Server persistence: wrap vendSave / vendDelete ──────────── */

  var _origVendSave = window.vendSave;
  window.vendSave = async function() {
    var nome = (document.getElementById('vend-f-nome')?.value || '').trim();
    if (!nome) { alert('O nome é obrigatório.'); return; }

    var data = [];
    try { data = JSON.parse(localStorage.getItem('expatur_vendedores') || '[]'); } catch(e) { data = []; }

    var record = {
      nome: nome,
      papel: document.getElementById('vend-f-papel')?.value || '',
      email: document.getElementById('vend-f-email')?.value || '',
      whatsapp: document.getElementById('vend-f-whatsapp')?.value || '',
      comissao: document.getElementById('vend-f-comissao')?.value || '',
      estado: document.getElementById('vend-f-estado')?.value || 'Ativo',
      notas: document.getElementById('vend-f-notas')?.value || '',
      updatedAt: new Date().toISOString()
    };

    if (typeof _vendEditIndex !== 'undefined' && _vendEditIndex >= 0 && _vendEditIndex < data.length) {
      record.createdAt = data[_vendEditIndex].createdAt || record.updatedAt;
      data[_vendEditIndex] = record;
    } else {
      record.createdAt = record.updatedAt;
      data.push(record);
    }

    /* Save to localStorage (triggers proxy → server persist) */
    try { localStorage.setItem('expatur_vendedores', JSON.stringify(data)); } catch(e) {}

    /* Explicit server save for reliability + error handling */
    try {
      if (typeof window.saveData === 'function') {
        var res = await window.saveData('vendedores_collection', 'main', data);
        if (res && res.error) throw new Error(res.error);
      }
    } catch(err) {
      console.error('[vendSave] Server persist failed:', err);
      if (typeof toast === 'function') toast('Erreur serveur : ' + (err.message || 'échec de sauvegarde'), 'error');
      return;
    }

    if (typeof vendModalClose === 'function') vendModalClose();
    if (typeof vendRender === 'function') vendRender();
    if (typeof toast === 'function') toast('✓ Vendedor guardado', 'success');
    if (typeof _populateVendeurSelect === 'function') setTimeout(_populateVendeurSelect, 50);
  };

  var _origVendDelete = window.vendDelete;
  window.vendDelete = async function(idx) {
    var data = [];
    try { data = JSON.parse(localStorage.getItem('expatur_vendedores') || '[]'); } catch(e) {}
    var v = data[idx];
    if (!v) return;
    if (!confirm('Eliminar "' + v.nome + '"?')) return;
    data.splice(idx, 1);

    try { localStorage.setItem('expatur_vendedores', JSON.stringify(data)); } catch(e) {}

    try {
      if (typeof window.saveData === 'function') {
        var res = await window.saveData('vendedores_collection', 'main', data);
        if (res && res.error) throw new Error(res.error);
      }
    } catch(err) {
      console.error('[vendDelete] Server persist failed:', err);
      if (typeof toast === 'function') toast('Erreur serveur : ' + (err.message || 'échec de suppression'), 'error');
      return;
    }

    if (typeof vendRender === 'function') vendRender();
    if (typeof toast === 'function') toast('Vendedor eliminado');
    if (typeof _populateVendeurSelect === 'function') setTimeout(_populateVendeurSelect, 50);
  };

  /* ── 2. Scan all dossiers linked to a vendedor ──────────────────── */

  function _scanLinkedDossiers(vendorName) {
    var results = [];
    if (!vendorName) return results;
    var nameNorm = vendorName.trim().toLowerCase();
    var list = [];
    try { list = JSON.parse(localStorage.getItem('expatur_dossier_list') || '[]'); } catch(e) {}

    for (var i = 0; i < list.length; i++) {
      var entry = list[i];
      if (!entry || !entry.id) continue;
      var dossier = null;
      try { dossier = JSON.parse(localStorage.getItem('expatur_dossier_' + entry.id) || 'null'); } catch(e) {}
      if (!dossier || !dossier.fields) continue;

      var dVendeur = (dossier.fields['vendeur-select'] || '').trim().toLowerCase();
      if (dVendeur !== nameNorm) continue;

      var ref = dossier.fields['booking-ref'] || entry.ref || entry.id;
      var clientName = dossier.fields['pax-name-1'] || '—';
      var dep = (dossier.fields['dep1'] || '').toUpperCase();
      var arr = (dossier.fields['arr1'] || '').toUpperCase();
      var cur = dossier.fields['currency'] || '€';

      /* Calculate deal value */
      var priceA = parseFloat(dossier.fields['price-adulte']) || 0;
      var priceE = parseFloat(dossier.fields['price-enfant']) || 0;
      var priceB = parseFloat(dossier.fields['price-bebe']) || 0;
      var nA = parseInt(dossier.fields['pax-adultes']) || 0;
      var nE = parseInt(dossier.fields['pax-enfants']) || 0;
      var nB = parseInt(dossier.fields['pax-bebes']) || 0;
      var dealValue = (priceA * nA) + (priceE * nE) + (priceB * nB);

      /* Discount */
      var discVal = parseFloat(dossier.fields['discount-value']) || 0;
      var discType = dossier.fields['discount-type'] || '';
      if (discVal > 0) {
        dealValue -= (discType === '%') ? dealValue * discVal / 100 : discVal;
      }

      /* PNR from billet data */
      var pnr = '—';
      try {
        var billetKey = 'expatur_billet_' + String(ref).replace(/[^a-zA-Z0-9]/g, '_');
        var billet = JSON.parse(localStorage.getItem(billetKey) || 'null');
        if (billet) {
          pnr = billet.masterPnr || '';
          if (!pnr && billet.legs && billet.legs.length) {
            pnr = billet.legs[0].pnr || '';
          }
          pnr = pnr || '—';
        }
      } catch(e) {}

      /* Date: use dossier creation or billet saved date */
      var dateStr = '';
      try {
        if (dossier.createdAt) dateStr = dossier.createdAt;
        else if (entry.createdAt) dateStr = entry.createdAt;
      } catch(e) {}

      /* Commission */
      var commRaw = parseFloat(dossier.fields['vendeur-commission']) || 0;
      var commType = dossier.fields['vendeur-commission-type'] || 'eur';

      results.push({
        ref: ref,
        date: dateStr,
        pnr: pnr,
        client: clientName,
        dep: dep,
        arr: arr,
        dealValue: dealValue,
        currency: cur,
        commRaw: commRaw,
        commType: commType
      });
    }

    /* Sort by date descending */
    results.sort(function(a, b) {
      return (new Date(b.date || 0)).getTime() - (new Date(a.date || 0)).getTime();
    });

    return results;
  }

  /* ── 3. Detail popup ────────────────────────────────────────────── */

  window.vendDetailOpen = function(idx) {
    var data = [];
    try { data = JSON.parse(localStorage.getItem('expatur_vendedores') || '[]'); } catch(e) {}
    var v = data[idx];
    if (!v) return;

    /* Title */
    var titleEl = document.getElementById('vend-detail-name');
    if (titleEl) titleEl.textContent = v.nome || 'Vendedor';

    /* Info cards */
    var infoEl = document.getElementById('vend-detail-info');
    if (infoEl) {
      var cards = '';
      function infoCard(label, value, color) {
        if (!value) return '';
        return '<div style="background:' + (color || 'rgba(6,32,59,0.03)') + ';border:1px solid rgba(6,32,59,0.08);border-radius:8px;padding:0.6rem 0.8rem;">'
          + '<div style="font-size:0.55rem;font-weight:700;letter-spacing:0.14em;text-transform:uppercase;color:var(--navy);opacity:0.5;margin-bottom:0.25rem;">' + _esc(label) + '</div>'
          + '<div style="font-size:0.85rem;font-weight:600;color:var(--navy);">' + _esc(value) + '</div>'
          + '</div>';
      }
      cards += infoCard('Papel / Cargo', v.papel);
      cards += infoCard('Email', v.email);
      cards += infoCard('WhatsApp', v.whatsapp);
      cards += infoCard('Comissão', v.comissao ? v.comissao + ' %' : '');
      cards += infoCard('Estado', v.estado, v.estado === 'Ativo' ? 'rgba(22,163,106,0.08)' : 'rgba(220,38,38,0.08)');
      if (v.notas) cards += infoCard('Notas', v.notas);
      cards += infoCard('Créé le', _fmtDate(v.createdAt));
      cards += infoCard('Mis à jour', _fmtDate(v.updatedAt));
      infoEl.innerHTML = cards;
    }

    /* Linked dossiers table */
    var dealsEl = document.getElementById('vend-detail-deals');
    if (dealsEl) {
      var deals = _scanLinkedDossiers(v.nome);
      if (!deals.length) {
        dealsEl.innerHTML = '<div style="padding:1rem 0;font-size:0.8rem;color:var(--navy-faint);font-style:italic;">Aucun dossier lié à ce vendedor.</div>';
      } else {
        var totalValue = 0;
        var html = '<table style="width:100%;border-collapse:collapse;font-size:0.78rem;">'
          + '<thead><tr style="background:var(--navy);color:#fff;">'
          + '<th style="padding:8px 10px;text-align:left;font-size:0.62rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;">Date</th>'
          + '<th style="padding:8px 10px;text-align:left;font-size:0.62rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;">PNR</th>'
          + '<th style="padding:8px 10px;text-align:left;font-size:0.62rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;">Client</th>'
          + '<th style="padding:8px 10px;text-align:center;font-size:0.62rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;">Départ</th>'
          + '<th style="padding:8px 10px;text-align:center;font-size:0.62rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;">Arrivée</th>'
          + '<th style="padding:8px 10px;text-align:right;font-size:0.62rem;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;">Valeur</th>'
          + '</tr></thead><tbody>';

        deals.forEach(function(d, i) {
          totalValue += d.dealValue || 0;
          var bg = i % 2 === 0 ? '#fff' : 'rgba(6,32,59,0.02)';
          html += '<tr style="background:' + bg + ';border-bottom:1px solid rgba(6,32,59,0.06);cursor:pointer;" onclick="if(typeof _dossierSwitchTo===\'function\')_dossierSwitchTo(\'' + _esc(d.ref) + '\');vendDetailClose();" title="Ouvrir dossier ' + _esc(d.ref) + '">'
            + '<td style="padding:7px 10px;white-space:nowrap;">' + _fmtDate(d.date) + '</td>'
            + '<td style="padding:7px 10px;font-family:monospace;font-weight:700;color:var(--gold);">' + _esc(d.pnr) + '</td>'
            + '<td style="padding:7px 10px;font-weight:600;">' + _esc(d.client) + '</td>'
            + '<td style="padding:7px 10px;text-align:center;font-weight:700;">' + _esc(d.dep || '—') + '</td>'
            + '<td style="padding:7px 10px;text-align:center;font-weight:700;">' + _esc(d.arr || '—') + '</td>'
            + '<td style="padding:7px 10px;text-align:right;font-weight:700;color:' + (d.dealValue >= 0 ? '#16a34a' : '#dc2626') + ';">' + _fmtMoney(d.dealValue, d.currency) + '</td>'
            + '</tr>';
        });

        /* Total row */
        html += '<tr style="background:rgba(182,146,73,0.08);border-top:2px solid var(--gold);">'
          + '<td colspan="5" style="padding:8px 10px;font-weight:700;font-size:0.72rem;text-align:right;text-transform:uppercase;letter-spacing:0.08em;">Total (' + deals.length + ' dossier' + (deals.length > 1 ? 's' : '') + ')</td>'
          + '<td style="padding:8px 10px;text-align:right;font-weight:700;font-size:0.85rem;color:var(--navy);">' + _fmtMoney(totalValue, deals[0]?.currency || '') + '</td>'
          + '</tr>';

        html += '</tbody></table>';
        dealsEl.innerHTML = html;
      }
    }

    /* Show overlay */
    var ov = document.getElementById('vend-detail-overlay');
    if (ov) { ov.style.display = 'flex'; }
  };

  window.vendDetailClose = function() {
    var ov = document.getElementById('vend-detail-overlay');
    if (ov) ov.style.display = 'none';
  };

  /* Close on overlay click (outside modal) */
  var ovEl = document.getElementById('vend-detail-overlay');
  if (ovEl) {
    ovEl.addEventListener('click', function(e) {
      if (e.target === ovEl) vendDetailClose();
    });
  }

  /* ── 4. Override vendRender to make names clickable ──────────────── */

  var _origVendRender = window.vendRender;
  window.vendRender = function() {
    if (typeof _origVendRender === 'function') _origVendRender();

    /* Post-process: make each nome cell clickable to open detail popup */
    var tbody = document.getElementById('vend-table-body');
    if (!tbody) return;
    var rows = tbody.querySelectorAll('tr');
    rows.forEach(function(tr, i) {
      var firstTd = tr.querySelector('td');
      if (!firstTd) return;
      /* Only patch if not already patched */
      if (firstTd.dataset.vendClick) return;
      firstTd.dataset.vendClick = '1';
      firstTd.style.cursor = 'pointer';
      firstTd.style.color = 'var(--navy)';
      firstTd.style.textDecoration = 'underline';
      firstTd.style.textDecorationColor = 'rgba(6,32,59,0.2)';
      firstTd.title = 'Voir détails';
      firstTd.addEventListener('click', function(e) {
        e.stopPropagation();
        vendDetailOpen(i);
      });
    });
  };

  /* ── 5. Helper: switch to a dossier from the deals table ────────── */

  window._dossierSwitchTo = window._dossierSwitchTo || function(ref) {
    /* Find dossier ID from list */
    var list = [];
    try { list = JSON.parse(localStorage.getItem('expatur_dossier_list') || '[]'); } catch(e) {}
    var match = list.find(function(d) {
      if (!d) return false;
      var dRef = d.ref || d.id || '';
      return dRef === ref;
    });
    if (!match && list.length) {
      /* Try loading dossier data to match by booking-ref field */
      for (var j = 0; j < list.length; j++) {
        try {
          var dd = JSON.parse(localStorage.getItem('expatur_dossier_' + list[j].id) || 'null');
          if (dd && dd.fields && dd.fields['booking-ref'] === ref) { match = list[j]; break; }
        } catch(e) {}
      }
    }
    if (match && match.id) {
      try { localStorage.setItem('expatur_active_dossier', match.id); } catch(e) {}
      if (typeof _dossierLoad === 'function') _dossierLoad(match.id);
      if (typeof sidebarGo === 'function') sidebarGo('quoting');
    }
  };

  console.log('[Patch v3.98] Vendedores: server persistence, detail popup, linked dossiers.');
})();

// ─────────────────────────────────────

/* ==========================================================================
   Patch v3.99 — Unified FinanceStore: canonical data model, server persistence,
   Tarification/Paiement sync, Ticketing sync, Stripe reconciliation,
   deduplication, BRL normalization, and unified surface refresh.
   ========================================================================== */
(function(){
  'use strict';
  if (window._v399FinanceStoreReady) return;
  window._v399FinanceStoreReady = true;

  var FIN_KEY = 'expatur_financeiro_lancamentos';
  var STRIPE_WORKER = (typeof STRIPE_WORKER_URL !== 'undefined') ? STRIPE_WORKER_URL : '';

  /* ══════════════════════════════════════════════════════════════════
     §1. CANONICAL TRANSACTION MODEL
     ══════════════════════════════════════════════════════════════════ */

  /**
   * Normalize any raw lançamento/payment record into the canonical model.
   * Fills missing fields with defaults so every downstream consumer sees
   * a consistent shape. Non-destructive: preserves existing fields.
   */
  function normalizeTransaction(raw) {
    var t = Object.assign({}, raw);
    t.id               = t.id || _finUID();
    t.dossierId        = t.dossierId || t.dossierRef || '';
    t.dossierRef       = t.dossierRef || t.dossierId || '';
    t.clientName       = t.clientName || t.client || '';
    t.pnr              = t.pnr || '';
    t.type             = t.type || _mapTipo(t.tipo);
    t.tipo             = t.tipo || _mapType(t.type);
    t.source           = t.source || 'manual';
    t.sourceId         = t.sourceId || '';
    t.invoiceId        = t.invoiceId || '';
    t.stripeInvoiceId  = t.stripeInvoiceId || '';
    t.stripePaymentIntentId = t.stripePaymentIntentId || '';
    t.status           = t.status || _mapPago(t.pago);
    t.pago             = t.pago || _mapStatus(t.status);
    t.amount           = t.amount != null ? parseFloat(t.amount) || 0 : parseFloat(t.valor) || 0;
    t.valor            = t.valor != null ? parseFloat(t.valor) || 0 : t.amount;
    t.currency         = t.currency || t.moeda || 'R$';
    t.moeda            = t.moeda || t.currency || 'R$';
    t.originalAmount   = t.originalAmount != null ? parseFloat(t.originalAmount) || 0
                         : (t.original_amount != null ? parseFloat(t.original_amount) || 0 : t.amount);
    t.original_amount  = t.originalAmount;
    t.originalCurrency = t.originalCurrency || t.original_currency || _isoFromSymbol(t.currency);
    t.original_currency= t.originalCurrency;
    t.brlAmount        = t.brlAmount != null ? parseFloat(t.brlAmount) : (t.brl_amount != null ? parseFloat(t.brl_amount) : null);
    t.brl_amount       = t.brlAmount;
    t.fxRateToBrl      = t.fxRateToBrl != null ? parseFloat(t.fxRateToBrl) : (t.fx_rate != null ? parseFloat(t.fx_rate) : null);
    t.fx_rate          = t.fxRateToBrl;
    t.pnlSnapshot      = t.pnlSnapshot || t.issueTicketSnapshot || null;
    t.issueTicketSnapshot = t.pnlSnapshot;
    t.nfValue          = t.nfValue != null ? parseFloat(t.nfValue) || 0 : 0;
    t.ravBrute         = t.ravBrute != null ? parseFloat(t.ravBrute) || 0 : 0;
    t.paidAt           = t.paidAt || null;
    t.createdAt        = t.createdAt || new Date().toISOString();
    t.updatedAt        = t.updatedAt || t.createdAt;
    /* Compute BRL amount if missing */
    if (t.brlAmount == null || isNaN(t.brlAmount)) {
      t.brlAmount = _computeBRL(t.originalAmount, t.originalCurrency, t.fxRateToBrl);
      t.brl_amount = t.brlAmount;
    }
    return t;
  }

  function _finUID() { return 'fin_' + Date.now() + '_' + Math.random().toString(36).slice(2,7); }

  function _isoFromSymbol(s) {
    var map = {'R$':'BRL','\u20ac':'EUR','$':'USD','MAD':'MAD','\u00a3':'GBP','DOP':'DOP'};
    return map[s] || (s && s.length === 3 ? s.toUpperCase() : 'BRL');
  }
  function _mapTipo(tipo) {
    if (tipo === 'entrada') return 'receivable';
    if (tipo === 'saida') return 'payable';
    return 'cashflow';
  }
  function _mapType(type) {
    if (type === 'receivable') return 'entrada';
    if (type === 'payable') return 'saida';
    return 'entrada';
  }
  function _mapPago(pago) {
    if (pago === 'pago') return 'paid';
    if (pago === 'pendente') return 'open';
    return 'open';
  }
  function _mapStatus(status) {
    if (status === 'paid') return 'pago';
    return 'pendente';
  }

  function _computeBRL(amount, isoCurrency, fxRate) {
    if (!amount) return 0;
    var iso = (isoCurrency || 'BRL').toUpperCase();
    if (iso === 'R$') iso = 'BRL';
    if (iso === '\u20ac') iso = 'EUR';
    if (iso === 'BRL') return amount;
    if (fxRate && fxRate > 0) return parseFloat((amount * fxRate).toFixed(2));
    /* Try cached FX rate */
    var cache = window._brlRateCache || {};
    var rate = cache[iso] || cache[iso.toLowerCase()];
    if (rate && rate > 0) return parseFloat((amount * rate).toFixed(2));
    return null; /* Cannot convert — FX unavailable */
  }

  /* ══════════════════════════════════════════════════════════════════
     §2. FINANCE STORE — CRUD + SERVER PERSISTENCE
     ══════════════════════════════════════════════════════════════════ */

  var _store = {
    /** Load all transactions from localStorage (which is server-backed via proxy). */
    loadAll: function() {
      try { return JSON.parse(localStorage.getItem(FIN_KEY) || '[]'); } catch(e) { return []; }
    },
    /** Save all transactions to localStorage → server. Returns a Promise. */
    saveAll: function(arr) {
      try { localStorage.setItem(FIN_KEY, JSON.stringify(arr)); } catch(e) {}
      /* Explicit server save for reliability */
      if (typeof window.saveData === 'function') {
        return window.saveData('financeiro_lancamentos', 'main', arr).then(function(res) {
          if (res && res.error) throw new Error(res.error);
          return res;
        });
      }
      return Promise.resolve();
    },

    /** Find by ID */
    findById: function(id) {
      return _store.loadAll().find(function(t) { return t.id === id; }) || null;
    },

    /** Find by dedupe key */
    findByDedupeKey: function(dedupeKey) {
      if (!dedupeKey) return null;
      return _store.loadAll().find(function(t) {
        return _dedupeKey(t) === dedupeKey;
      }) || null;
    },

    /** Find by Stripe invoice ID */
    findByStripeId: function(stripeId) {
      if (!stripeId) return null;
      return _store.loadAll().find(function(t) {
        return t.stripeInvoiceId === stripeId || t.invoiceId === stripeId;
      }) || null;
    },

    /** Upsert: insert or update a transaction. Deduplicates automatically. */
    upsert: function(txn, opts) {
      var t = normalizeTransaction(txn);
      var items = _store.loadAll();
      var existIdx = -1;

      /* Dedupe: find existing by stripeInvoiceId, then sourceId, then id */
      if (t.stripeInvoiceId) {
        existIdx = items.findIndex(function(x) { return x.stripeInvoiceId === t.stripeInvoiceId; });
      }
      if (existIdx < 0 && t.sourceId) {
        var dk = _dedupeKey(t);
        existIdx = items.findIndex(function(x) { return _dedupeKey(x) === dk; });
      }
      if (existIdx < 0) {
        existIdx = items.findIndex(function(x) { return x.id === t.id; });
      }

      t.updatedAt = new Date().toISOString();

      if (existIdx >= 0) {
        /* Merge: preserve fields not in the update */
        var existing = items[existIdx];
        t = Object.assign({}, existing, t);
        t.createdAt = existing.createdAt || t.createdAt;
        items[existIdx] = t;
      } else {
        items.push(t);
      }

      var promise = _store.saveAll(items);

      if (!(opts && opts.skipRefresh)) {
        promise.then(function() {
          _refreshFinanceSurfaces({ dossierId: t.dossierId });
        }).catch(function(err) {
          console.error('[FinanceStore] Server save failed:', err);
          if (typeof toast === 'function') toast('Erreur serveur Financeiro: ' + (err.message || 'échec'), 'error');
        });
      }

      return t;
    },

    /** Remove a transaction by ID */
    remove: function(id) {
      var items = _store.loadAll().filter(function(t) { return t.id !== id; });
      return _store.saveAll(items).then(function() {
        _refreshFinanceSurfaces({});
      });
    },

    /** Bulk upsert (skip individual refreshes, do one at end) */
    bulkUpsert: function(txns) {
      var items = _store.loadAll();
      txns.forEach(function(txn) {
        var t = normalizeTransaction(txn);
        var existIdx = -1;
        if (t.stripeInvoiceId) {
          existIdx = items.findIndex(function(x) { return x.stripeInvoiceId === t.stripeInvoiceId; });
        }
        if (existIdx < 0 && t.sourceId) {
          var dk = _dedupeKey(t);
          existIdx = items.findIndex(function(x) { return _dedupeKey(x) === dk; });
        }
        if (existIdx < 0) {
          existIdx = items.findIndex(function(x) { return x.id === t.id; });
        }
        t.updatedAt = new Date().toISOString();
        if (existIdx >= 0) {
          t = Object.assign({}, items[existIdx], t);
          t.createdAt = items[existIdx].createdAt || t.createdAt;
          items[existIdx] = t;
        } else {
          items.push(t);
        }
      });
      return _store.saveAll(items).then(function() {
        _refreshFinanceSurfaces({});
      });
    }
  };

  /** Dedupe key: dossierId + source + sourceId */
  function _dedupeKey(t) {
    var did = t.dossierId || t.dossierRef || '';
    var src = t.source || '';
    var sid = t.sourceId || t.nota || '';
    return did + '|' + src + '|' + sid;
  }

  /* Expose globally */
  window.FinanceStore = _store;
  window.normalizeFinanceTransaction = normalizeTransaction;

  /* ══════════════════════════════════════════════════════════════════
     §3. TARIFICATION / PAIEMENT → FINANCEIRO SYNC
     ══════════════════════════════════════════════════════════════════ */

  /**
   * Called after savePaymentRecord to sync the receivable into Financeiro.
   * Maps payment record fields to the canonical model.
   */
  function _syncPaymentToFinanceiro(record, ref) {
    if (!record) return;
    var dRef = ref || (document.getElementById('booking-ref') || {}).value || '';
    var clientName = '';
    try { clientName = (document.getElementById('pax-name-1') || {}).value || ''; } catch(e) {}

    /* PNR from billet or current UI */
    var pnr = '';
    try {
      var billetKey = 'expatur_billet_' + String(dRef).replace(/[^a-zA-Z0-9]/g, '_');
      var billet = JSON.parse(localStorage.getItem(billetKey) || 'null');
      if (billet) pnr = billet.masterPnr || (billet.legs && billet.legs[0] ? billet.legs[0].pnr : '') || '';
    } catch(e) {}
    if (!pnr) {
      try { pnr = (document.getElementById('bl-master-pnr') || {}).value || ''; } catch(e) {}
    }

    /* Determine FX rate */
    var cur = record.currency || '';
    var isoCur = _isoFromSymbol(cur);
    var fxRate = null;
    try { fxRate = (window._brlRateCache || {})[isoCur] || null; } catch(e) {}

    var txn = {
      dossierId: dRef,
      dossierRef: dRef,
      clientName: clientName,
      pnr: pnr,
      tipo: 'entrada',
      type: 'receivable',
      source: record.stripeInvoiceId ? 'stripe' : (record.type || 'manual'),
      sourceId: record.stripeInvoiceId || ('payment_' + dRef + '_' + (record._installmentIndex != null ? record._installmentIndex : 'single')),
      invoiceId: record.stripeInvoiceId || '',
      stripeInvoiceId: record.stripeInvoiceId || '',
      status: (record.status || 'open').toLowerCase() === 'paid' ? 'paid' : 'open',
      pago: (record.status || 'open').toLowerCase() === 'paid' ? 'pago' : 'pendente',
      amount: parseFloat(record.amount) || 0,
      valor: parseFloat(record.amount) || 0,
      currency: cur,
      moeda: cur,
      originalAmount: parseFloat(record.amount) || 0,
      originalCurrency: isoCur,
      fxRateToBrl: fxRate,
      descricao: 'Recebimento ' + (record.mode || 'Facture') + (dRef ? ' — ' + dRef : ''),
      categoria: 'Receita - Booking',
      fornecedor: clientName,
      vencimento: record.date || new Date().toISOString().slice(0,10),
      paidAt: (record.status === 'paid') ? (record.date || new Date().toISOString().slice(0,10)) : null,
      nota: record.stripeInvoiceId || ('payment_' + dRef + '_' + (record._installmentIndex != null ? record._installmentIndex : 'single'))
    };

    _store.upsert(txn, { skipRefresh: false });
  }

  /* Wrap savePaymentRecord to auto-sync to Financeiro */
  var _origSavePaymentRecord = window.savePaymentRecord;
  window.savePaymentRecord = function(record) {
    if (typeof _origSavePaymentRecord === 'function') _origSavePaymentRecord(record);
    try { _syncPaymentToFinanceiro(record); } catch(e) { console.warn('[FinanceStore] payment sync error:', e); }
  };

  /* ── Wheel edit sync: when invoice amount changes via wheel ─────── */
  var _origRebalance = window._rebalanceAfterInvoiceAmountEdit;
  if (typeof _origRebalance === 'function') {
    window._rebalanceAfterInvoiceAmountEdit = function(idx, newValue) {
      _origRebalance.apply(this, arguments);
      /* Re-sync the changed payment record to Financeiro */
      try {
        var hist = (typeof loadPaymentHistory === 'function') ? loadPaymentHistory() : [];
        if (hist[idx]) _syncPaymentToFinanceiro(hist[idx]);
      } catch(e) {}
    };
  }

  /* ── Mark paid/unpaid sync ──────────────────────────────────────── */
  var _origTogglePaid = window._toggleInvoicePaidState;
  if (typeof _origTogglePaid === 'function') {
    window._toggleInvoicePaidState = function() {
      _origTogglePaid.apply(this, arguments);
      /* Re-sync after status change */
      try {
        var hist = (typeof loadPaymentHistory === 'function') ? loadPaymentHistory() : [];
        hist.forEach(function(rec) { _syncPaymentToFinanceiro(rec); });
      } catch(e) {}
    };
  }

  /* ══════════════════════════════════════════════════════════════════
     §4. TICKETING / ISSUE TICKET → FINANCEIRO + P&L SNAPSHOT
     ══════════════════════════════════════════════════════════════════ */

  /**
   * Called after "Issue ticket" to create cost (payable) entries from
   * the P&L snapshot + supplier costs. Wraps finAutoCreateCostPayments.
   */
  var _origFinAutoCost = window.finAutoCreateCostPayments;
  window.finAutoCreateCostPayments = function() {
    /* Call the original implementation */
    if (typeof _origFinAutoCost === 'function') _origFinAutoCost();

    /* Now also store the P&L snapshot into any existing receivable for this dossier */
    try {
      var ref = (document.getElementById('booking-ref') || {}).value || '';
      if (!ref) return;
      var pnlKey = 'expatur_pnl_' + ref;
      var snap = JSON.parse(localStorage.getItem(pnlKey) || 'null');
      if (!snap) return;

      var items = _store.loadAll();
      var changed = false;
      items.forEach(function(t) {
        if (t.dossierRef === ref || t.dossierId === ref) {
          if (!t.pnlSnapshot || !t.issueTicketSnapshot) {
            t.pnlSnapshot = snap;
            t.issueTicketSnapshot = snap;
            t.ravBrute = snap.ravBrut || 0;
            t.nfValue = snap.ravBrut || 0;
            t.updatedAt = new Date().toISOString();
            changed = true;
          }
        }
      });
      if (changed) {
        _store.saveAll(items).catch(function(err) {
          console.warn('[FinanceStore] P&L snapshot save error:', err);
        });
      }
    } catch(e) { console.warn('[FinanceStore] ticketing sync error:', e); }
  };

  /* Also wrap finAutoCreateFluxoEntrada to use canonical model */
  var _origFluxoEntrada = window.finAutoCreateFluxoEntrada;
  window.finAutoCreateFluxoEntrada = function(opts) {
    /* Call original */
    if (typeof _origFluxoEntrada === 'function') _origFluxoEntrada(opts);

    /* Also upsert into FinanceStore with proper dedupe */
    try {
      _store.upsert({
        tipo: 'entrada',
        type: 'receivable',
        descricao: opts.descricao || 'Recebimento',
        valor: opts.valor || 0,
        amount: opts.valor || 0,
        moeda: opts.moeda || '\u20ac',
        currency: opts.moeda || '\u20ac',
        categoria: 'Receita - Booking',
        fornecedor: opts.fornecedor || '',
        dossierRef: opts.dossierRef || '',
        dossierId: opts.dossierRef || '',
        vencimento: opts.vencimento || new Date().toISOString().slice(0,10),
        pago: opts.status || 'pendente',
        status: (opts.status === 'pago') ? 'paid' : 'open',
        source: 'tarification',
        sourceId: 'fluxo_' + (opts.dossierRef || '') + '_' + Date.now(),
        nota: opts.nota || 'Auto-créé'
      }, { skipRefresh: true });
    } catch(e) {}
  };

  /* ══════════════════════════════════════════════════════════════════
     §5. STRIPE WEBHOOK / EVENT RECONCILIATION
     ══════════════════════════════════════════════════════════════════ */

  /**
   * Reconcile a Stripe event with local finance data.
   * Called from webhook handler or manual status check.
   */
  window.finReconcileStripeEvent = function(event) {
    if (!event || !event.type) return;
    var obj = event.data ? event.data.object : event;
    var invoiceId = obj.id || obj.invoice || '';
    if (!invoiceId) return;

    var txn = _store.findByStripeId(invoiceId);
    if (!txn) {
      console.warn('[FinanceStore] No local transaction for Stripe invoice:', invoiceId);
      return;
    }

    var updated = false;

    switch(event.type) {
      case 'invoice.paid':
      case 'invoice.payment_succeeded':
        if (txn.status !== 'paid') {
          txn.status = 'paid';
          txn.pago = 'pago';
          txn.paidAt = new Date().toISOString().slice(0,10);
          if (obj.payment_intent) txn.stripePaymentIntentId = obj.payment_intent;
          if (obj.receipt_url) txn.receiptUrl = obj.receipt_url;
          updated = true;
        }
        break;

      case 'invoice.payment_failed':
        txn.status = 'failed';
        txn.pago = 'pendente';
        updated = true;
        break;

      case 'invoice.voided':
        txn.status = 'voided';
        txn.pago = 'pendente';
        updated = true;
        break;

      case 'charge.refunded':
        txn.status = 'refunded';
        txn.pago = 'pendente';
        if (obj.amount_refunded) {
          txn.refundedAmount = obj.amount_refunded / 100;
        }
        updated = true;
        break;

      case 'invoice.updated':
      case 'invoice.finalized':
        if (obj.amount_due != null) {
          txn.amount = obj.amount_due / 100;
          txn.valor = txn.amount;
          txn.originalAmount = txn.amount;
          txn.original_amount = txn.amount;
          txn.brlAmount = _computeBRL(txn.amount, txn.originalCurrency, txn.fxRateToBrl);
          txn.brl_amount = txn.brlAmount;
        }
        if (obj.status === 'paid') {
          txn.status = 'paid';
          txn.pago = 'pago';
          txn.paidAt = txn.paidAt || new Date().toISOString().slice(0,10);
        }
        updated = true;
        break;

      case 'invoice.created':
        /* Only update if we have a partial record */
        if (obj.amount_due != null) {
          txn.amount = obj.amount_due / 100;
          txn.valor = txn.amount;
        }
        updated = true;
        break;
    }

    if (updated) {
      txn.updatedAt = new Date().toISOString();
      _store.upsert(txn);

      /* Also update payment history if this dossier has one */
      _syncBackToPaymentHistory(txn);
    }
  };

  /**
   * Sync finance transaction status back to the per-dossier payment history.
   */
  function _syncBackToPaymentHistory(txn) {
    if (!txn.dossierRef || !txn.stripeInvoiceId) return;
    try {
      var phKey = 'expatur_payments_' + txn.dossierRef.replace(/[^a-zA-Z0-9]/g, '_');
      var hist = JSON.parse(localStorage.getItem(phKey) || '[]');
      var changed = false;
      hist.forEach(function(rec) {
        if (rec.stripeInvoiceId === txn.stripeInvoiceId) {
          if (rec.status !== txn.status) {
            rec.status = txn.status;
            if (txn.paidAt) rec.paidAt = txn.paidAt;
            if (txn.status === 'paid') rec.marked_paid_manually = true;
            changed = true;
          }
          if (Math.abs((rec.amount || 0) - txn.amount) > 0.01) {
            rec.amount = txn.amount;
            changed = true;
          }
        }
      });
      if (changed) {
        try { localStorage.setItem(phKey, JSON.stringify(hist)); } catch(e) {}
      }
    } catch(e) {}
  }

  /**
   * Enhanced emCheckInvoiceStatus: after checking, reconcile with FinanceStore.
   */
  var _origCheckInvoice = window.emCheckInvoiceStatus;
  window.emCheckInvoiceStatus = async function(invoiceId, dueDate) {
    /* Call the original checker */
    if (typeof _origCheckInvoice === 'function') {
      await _origCheckInvoice(invoiceId, dueDate);
    }

    /* Now also fetch latest status from Stripe and reconcile */
    if (!invoiceId || !STRIPE_WORKER) return;
    try {
      var pw = window._emLastUsedPw || '';
      if (!pw) { try { pw = document.getElementById('em-stripe-pw').value || ''; } catch(e){} }
      if (!pw) return;
      var resp = await fetch(STRIPE_WORKER, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'check_invoice', password: pw, invoice_id: invoiceId })
      });
      if (resp.ok) {
        var data = await resp.json();
        if (data && data.status) {
          window.finReconcileStripeEvent({
            type: 'invoice.' + (data.status === 'paid' ? 'paid' : 'updated'),
            data: { object: { id: invoiceId, status: data.status, amount_due: data.amount_due } }
          });
        }
      }
    } catch(e) { console.warn('[FinanceStore] Stripe check reconciliation failed:', e); }
  };

  /* ══════════════════════════════════════════════════════════════════
     §6. UNIFIED refreshFinanceSurfaces
     ══════════════════════════════════════════════════════════════════ */

  var _refreshDebounce = 0;

  function _refreshFinanceSurfaces(opts) {
    /* Debounce rapid successive calls (e.g. bulk upsert) */
    clearTimeout(_refreshDebounce);
    _refreshDebounce = setTimeout(function() {
      _doRefresh(opts || {});
    }, 80);
  }

  function _doRefresh(opts) {
    /* 1. Financeiro dashboard (if visible) */
    try { if (typeof window.finRefresh === 'function') window.finRefresh(); } catch(e) {}

    /* 2. Per-dossier finance panel */
    try { if (typeof window.dossFinRenderPanel === 'function') window.dossFinRenderPanel(); } catch(e) {}

    /* 3. Payment history (Encaissement/Tarification) */
    try { if (typeof window.renderPaymentHistory === 'function') window.renderPaymentHistory(); } catch(e) {}

    /* 4. Refresh Ticketing finance summary if present */
    try { if (typeof window.blCalcPnL === 'function') window.blCalcPnL(); } catch(e) {}

    /* 5. Refresh invoice wheel */
    try { if (typeof window._renderPHInvoiceWheelSection === 'function') window._renderPHInvoiceWheelSection(); } catch(e) {}

    /* 6. Populate vendeur select (commission data may have changed) */
    try { if (typeof window._populateVendeurSelect === 'function') window._populateVendeurSelect(); } catch(e) {}
  }

  window.refreshFinanceSurfaces = _refreshFinanceSurfaces;

  /* ══════════════════════════════════════════════════════════════════
     §7. BRL NORMALIZATION — fix existing data on load
     ══════════════════════════════════════════════════════════════════ */

  /**
   * On page load, scan all existing transactions and fix any
   * missing BRL amounts using current FX rates.
   */
  function _normalizeExistingBRL() {
    var items = _store.loadAll();
    var changed = false;
    items.forEach(function(t) {
      /* Ensure original_currency / original_amount are set */
      if (!t.original_currency && t.moeda) {
        t.original_currency = _isoFromSymbol(t.moeda);
        t.originalCurrency = t.original_currency;
        changed = true;
      }
      if (t.original_amount == null && t.valor != null) {
        t.original_amount = parseFloat(t.valor) || 0;
        t.originalAmount = t.original_amount;
        changed = true;
      }

      /* Compute BRL if missing */
      var iso = (t.original_currency || 'BRL').toUpperCase();
      if (iso === 'R$') iso = 'BRL';
      if (iso !== 'BRL' && (t.brl_amount == null || isNaN(t.brl_amount))) {
        var brl = _computeBRL(t.original_amount || t.valor, iso, t.fx_rate);
        if (brl != null) {
          t.brl_amount = brl;
          t.brlAmount = brl;
          t.valor = brl; /* Update valor to BRL for totals */
          changed = true;
        }
      }
    });
    if (changed) {
      try { localStorage.setItem(FIN_KEY, JSON.stringify(items)); } catch(e) {}
    }
  }

  /* Run BRL normalization after FX rates are available */
  var _brlNormDone = false;
  function _tryBRLNorm() {
    if (_brlNormDone) return;
    if (window._brlRateCache && Object.keys(window._brlRateCache).length > 0) {
      _brlNormDone = true;
      _normalizeExistingBRL();
    }
  }
  setTimeout(_tryBRLNorm, 3000);
  setTimeout(_tryBRLNorm, 8000);
  setTimeout(_tryBRLNorm, 15000);

  /* ══════════════════════════════════════════════════════════════════
     §8. MIGRATION — index existing payment records into FinanceStore
     ══════════════════════════════════════════════════════════════════ */

  /**
   * On first load, scan all expatur_payments_* and create Financeiro
   * entries for any that don't already exist. This bridges the gap
   * between the old per-dossier payment records and the central ledger.
   */
  function _migratePaymentRecords() {
    var items = _store.loadAll();
    var existingStripeIds = {};
    var existingSourceIds = {};
    items.forEach(function(t) {
      if (t.stripeInvoiceId) existingStripeIds[t.stripeInvoiceId] = true;
      if (t.sourceId) existingSourceIds[t.sourceId] = true;
    });

    var added = 0;
    var allKeys = [];
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (k && k.indexOf('expatur_payments_') === 0) allKeys.push(k);
    }

    var newTxns = [];
    allKeys.forEach(function(key) {
      var ref = key.replace('expatur_payments_', '').replace(/_/g, '-').replace(/^-+|-+$/g, '');
      try {
        var hist = JSON.parse(localStorage.getItem(key) || '[]');
        hist.forEach(function(rec, idx) {
          /* Skip if already in Financeiro */
          if (rec.stripeInvoiceId && existingStripeIds[rec.stripeInvoiceId]) return;
          var sid = 'payment_' + ref + '_' + (rec._installmentIndex != null ? rec._installmentIndex : idx);
          if (existingSourceIds[sid]) return;

          newTxns.push({
            tipo: 'entrada',
            type: 'receivable',
            source: rec.stripeInvoiceId ? 'stripe' : (rec.type || 'manual'),
            sourceId: sid,
            stripeInvoiceId: rec.stripeInvoiceId || '',
            dossierId: ref,
            dossierRef: ref,
            amount: parseFloat(rec.amount) || 0,
            valor: parseFloat(rec.amount) || 0,
            currency: rec.currency || '',
            moeda: rec.currency || '',
            status: (rec.status || 'open').toLowerCase() === 'paid' ? 'paid' : 'open',
            pago: (rec.status || 'open').toLowerCase() === 'paid' ? 'pago' : 'pendente',
            vencimento: rec.date || '',
            descricao: 'Recebimento ' + (rec.mode || '') + ' — ' + ref,
            categoria: 'Receita - Booking',
            paidAt: rec.status === 'paid' ? (rec.date || null) : null,
            createdAt: rec.registeredAt || rec.date || new Date().toISOString(),
            nota: rec.stripeInvoiceId || sid
          });
          added++;
        });
      } catch(e) {}
    });

    if (newTxns.length > 0) {
      _store.bulkUpsert(newTxns).then(function() {
        console.log('[FinanceStore] Migrated ' + added + ' payment records to central ledger.');
      }).catch(function(err) {
        console.warn('[FinanceStore] Migration save failed:', err);
      });
    }
  }

  /* Run migration once on load */
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() { setTimeout(_migratePaymentRecords, 2000); });
  } else {
    setTimeout(_migratePaymentRecords, 2000);
  }

  console.log('[Patch v3.99] Unified FinanceStore loaded — canonical model, server persistence, Stripe reconciliation, BRL normalization.');
})();

