        stripeInvoiceId:       record.stripeInvoiceId || '',
        stripePaymentIntentId: record.stripePaymentIntentId || '',
        invoiceId:             stableId,
        paymentLinkId:         record.paymentLinkId || '',
        dossierId:             dossierId,
        dossierRef:            dRef,
        paymentNumber:         record._installmentIndex != null ? record._installmentIndex : 0,
        amount:                parseFloat(record.amount) || 0,
        originalAmount:        parseFloat(record.amount) || 0,
        originalCurrency:      record.currency || 'EUR',
        currency:              record.currency || 'EUR',
        status:                record.status || 'open',
        paidAmount:            record.status === 'paid' ? parseFloat(record.amount) || 0 : 0,
