            stripeInvoiceId:       norm.stripeInvoiceId || '',
            invoiceId:             norm.id,
            dossierId:             dossierId,
            dossierRef:            ref,
            paymentNumber:         norm._installmentIndex,
            amount:                norm.amount,
            originalAmount:        norm.amount,
            originalCurrency:      norm.currency,
            currency:              norm.currency,
            status:                norm.status,
            paidAmount:            norm.paidAmount,
            payMethod:             norm.payMethod,
            description:           norm.label,
            date:                  norm.registeredAt ? String(norm.registeredAt).slice(0,10) : new Date().toISOString().slice(0,10),
            dueDate:               norm.vencimento,
