      'iata', 'airline_iata', 'marketing_carrier', 'marketingCarrier',
      'marketingCarrierCode', 'operating_carrier', 'operatingCarrier',
      'operatingCarrierCode', 'carrier', 'carrierCode', 'airlineCode',
      'code', 'linked_airline_iata'
