(function() {
  'use strict';

  /* ══════════════════════════════════════════════════════════════════
     §1. Guard saveBilletData — prevent empty-DOB overwrite
     ══════════════════════════════════════════════════════════════════ */

  var _prevSaveBillet116 = window.saveBilletData;
  window.saveBilletData = function() {
    var body = document.getElementById('bl-body');
    if (!body) {
      /* No billet body at all — skip save entirely */
      return;
    }

    /* Check if the billet form is actually populated with pax inputs */
    var firstPaxNom = document.getElementById('bl-pax-0-nom');
    if (!firstPaxNom) {
      /* Form not built yet (bl-body exists but innerHTML is empty/default).
         Don't save — it would overwrite existing stored data with blanks. */
      console.log('[v3.116] saveBilletData skipped: billet form not populated');
      return;
    }

    /* Read current DOB values from the form */
    var nPax = parseInt(body.dataset.paxCount) || 1;
    var currentDobs = [];
    var hasAnyDob = false;
    for (var pi = 0; pi < nPax; pi++) {
      var dobEl = document.getElementById('bl-pax-' + pi + '-dob');
      var dob = (dobEl && dobEl.value) || '';
      currentDobs.push(dob);
      if (dob) hasAnyDob = true;
    }

    /* Call the original save */
    _prevSaveBillet116.apply(this, arguments);

    /* If the form had all-empty DOBs, check if we just overwrote stored DOBs
       and restore them if so (merge strategy) */
    if (!hasAnyDob) {
      try {
        var ref = (document.getElementById('booking-ref') || {}).value || '';
        var key = 'expatur_billet_' + ref.replace(/[^a-zA-Z0-9]/g, '_');
        var stored = JSON.parse(localStorage.getItem(key) || 'null');
        if (stored && stored.pax) {
          /* Check all previous stored DOBs — if any were non-empty,
             the save just wiped them. Merge them back. */
          var needsRestore = false;

          /* We need to get the PREVIOUS data. Since we just overwrote it,
             check the dossier's savedBilletData as fallback. */
          var dossierId = localStorage.getItem('expatur_active_dossier') || '';
          var dosData = null;
          if (dossierId) {
            try { dosData = JSON.parse(localStorage.getItem('expatur_dossier_' + dossierId) || 'null'); } catch(e) {}
          }
          var prevPax = (dosData && dosData.savedBilletData && dosData.savedBilletData.pax) || [];

          stored.pax.forEach(function(p, i) {
            if (!p.dob && prevPax[i] && prevPax[i].dob) {
              p.dob = prevPax[i].dob;
              needsRestore = true;
            }
          });

          if (needsRestore) {
            localStorage.setItem(key, JSON.stringify(stored));
            console.log('[v3.116] Restored DOB values that were about to be overwritten');
          }
        }
      } catch(e) {
        console.warn('[v3.116] DOB restore error:', e);
      }
    }
  };

  /* ══════════════════════════════════════════════════════════════════
     §2. Also protect DOB during openBilletModal rebuild window
     When openBilletModal rebuilds the form, there's a 150ms gap
     where inputs exist but are empty. If saveBilletData is called
     during that window (via quotingSwitch), DOBs would be lost.
     We set a flag during rebuild to block saves.
     ══════════════════════════════════════════════════════════════════ */

  var _billetRebuilding116 = false;

  var _prevOpenBillet116 = window.openBilletModal;
  if (typeof _prevOpenBillet116 === 'function') {
    window.openBilletModal = function() {
      _billetRebuilding116 = true;
      try {
        _prevOpenBillet116.apply(this, arguments);
      } finally {
        /* The auto-load runs at 150ms; clear the guard after 200ms */
        setTimeout(function() {
          _billetRebuilding116 = false;
        }, 200);
      }
    };
  }

  /* Re-wrap saveBilletData to also check the rebuilding flag */
  var _prevSaveBillet116b = window.saveBilletData;
  window.saveBilletData = function() {
    if (_billetRebuilding116) {
      console.log('[v3.116] saveBilletData skipped: billet form rebuilding');
      return;
    }
    return _prevSaveBillet116b.apply(this, arguments);
  };

  /* ══════════════════════════════════════════════════════════════════
     §3. Fix editBilletBanner restore — handle empty DOB correctly
     Line 8289 uses `if(el&&val)` which drops empty strings.
     We patch to use `val!==undefined` like the main load at line 7168.
     ══════════════════════════════════════════════════════════════════ */

  var _prevEditBanner116 = window.editBilletBanner;
  if (typeof _prevEditBanner116 === 'function') {
    window.editBilletBanner = function() {
      _prevEditBanner116.apply(this, arguments);
      /* After the original runs (which has a setTimeout), re-apply DOB
         from the banner's stored record to fix the `if(el&&val)` bug */
      setTimeout(function() {
        var banner = document.getElementById('billet-banner');
        if (!banner) return;
        var record;
        try { record = JSON.parse(banner.dataset.record || '{}'); } catch(_) { return; }
        (record.pax || []).forEach(function(p, pi) {
          var el = document.getElementById('bl-pax-' + pi + '-dob');
          if (el && p.dob !== undefined) {
            el.value = p.dob;
          }
        });
      }, 150); /* after editBilletBanner's own setTimeout(120ms) */
    };
  }

  /* ══════════════════════════════════════════════════════════════════
     §4. Sync billet DOB → dossier paxRows on save
     When billet is saved with DOB data, propagate it to the dossier's
     savedBilletData so it persists across dossier switches.
     (This is already done by v3.73, but we ensure the dossier's own
     paxRows field also gets DOB from the billet.)
     ══════════════════════════════════════════════════════════════════ */

  /* Already handled by v3.73 _writeSnapshot which reads bil.pax.
     No additional code needed — just ensuring the save chain is intact. */

  console.log('[Patch v3.116] DOB persistence: guarded saveBilletData against empty-form overwrite, rebuild window protection, editBanner DOB fix. LATAM/GOL PDF links restored in preLegsBox.');
})();

