(function(){
  'use strict';

  var DEBUG_FINANCE_FX = false;
  try { DEBUG_FINANCE_FX = localStorage.getItem('DEBUG_FINANCE_FX') === '1'; } catch(e){}

  function _dbg122() {
    if (!DEBUG_FINANCE_FX) return;
    var args = ['[FX-122]'].concat(Array.prototype.slice.call(arguments));
    console.debug.apply(console, args);
  }

  /* ══════════════════════════════════════════════════════════════════
     §1. SYMBOL → ISO MAP (comprehensive, reused everywhere)
     ══════════════════════════════════════════════════════════════════ */

  var _SYM2ISO122 = {
    'R$':'BRL', '€':'EUR', '$':'USD', 'US$':'USD',
    'MAD':'MAD', '£':'GBP', 'DOP':'DOP', 'COP':'COP',
    'CHF':'CHF', 'ARS':'ARS', 'BRL':'BRL', 'EUR':'EUR',
    'USD':'USD', 'GBP':'GBP'
  };

  function _toIso122(currency) {
    if (!currency) return 'BRL';
    var c = String(currency).trim();
    return _SYM2ISO122[c] || (c.length <= 3 ? c.toUpperCase() : 'BRL');
  }

  /* ══════════════════════════════════════════════════════════════════
     §2. READ FX RATE FROM HEADER DOM (primary source of truth)

     The header FX strip has elements like:
       <div class="header-fx-item" data-fx-key="EUR/BRL">
         <div class="fx-pair">EUR/BRL</div>
         <div class="fx-val">5.87</div>
       </div>

     We parse .fx-val textContent to get the live displayed rate.
     ══════════════════════════════════════════════════════════════════ */

  function _readHeaderFxDom(iso) {
    if (iso === 'BRL') return 1;
    var key = iso + '/BRL';
    var items = document.querySelectorAll('.header-fx-item[data-fx-key]');
    for (var i = 0; i < items.length; i++) {
      var dk = items[i].getAttribute('data-fx-key');
      if (dk === key) {
        /* Skip items still loading or in error state */
        if (items[i].classList.contains('loading') || items[i].classList.contains('error')) {
          _dbg122('Header DOM item', key, 'is loading/error — skipping');
          return null;
        }
        var valEl = items[i].querySelector('.fx-val');
        if (valEl) {
          var txt = (valEl.textContent || '').trim();
          var rate = parseFloat(txt);
          if (rate > 0 && isFinite(rate)) {
            _dbg122('Header DOM rate for', iso, '=', rate);
            return rate;
          }
        }
      }
    }
    _dbg122('No header DOM item found for', key);
    return null;
  }

  /* ══════════════════════════════════════════════════════════════════
     §3. READ FX RATE FROM CACHE (secondary source)
     ══════════════════════════════════════════════════════════════════ */

  function _readFxCache122(iso) {
    try {
      var cache = JSON.parse(localStorage.getItem('expatur_fx_rate_cache') || '{}');
      var rate = parseFloat(cache[iso]);
      if (rate > 0 && isFinite(rate)) {
        _dbg122('Cache rate for', iso, '=', rate);
        return rate;
      }
      /* Try lowercase key too */
      rate = parseFloat(cache[iso.toLowerCase()]);
      if (rate > 0 && isFinite(rate)) {
        _dbg122('Cache rate (lowercase) for', iso, '=', rate);
        return rate;
      }
    } catch(e) {
      _dbg122('Cache read error:', e.message);
    }
    return null;
  }

  /* ══════════════════════════════════════════════════════════════════
     §4. CANONICAL getActiveHeaderFxRate — NO HARDCODED FALLBACKS

     Priority: header DOM → localStorage cache → null
     NEVER returns 6.10 or any hardcoded value.
     Returns null when rate is unavailable (caller must handle).
     Returns 1 for BRL.
     ══════════════════════════════════════════════════════════════════ */

  window.getActiveHeaderFxRate = function(currency) {
    if (!currency) return 1;
    var iso = _toIso122(currency);
    if (iso === 'BRL') return 1;

    /* 1. Header DOM — live displayed rate */
    var rate = _readHeaderFxDom(iso);
    if (rate !== null) return rate;

    /* 2. localStorage cache — written by header on fetch */
    rate = _readFxCache122(iso);
    if (rate !== null) return rate;

    /* 3. NO FALLBACK — rate is unavailable */
    _dbg122('getActiveHeaderFxRate: NO rate for', iso, '— returning null');
    return null;
  };

  /* ══════════════════════════════════════════════════════════════════
     §5. CANONICAL _fxRateFor — delegates entirely to header FX

     Returns the rate or 0 if unavailable (never 1 as false-fallback).
     BRL returns 1.
     ══════════════════════════════════════════════════════════════════ */

  window._fxRateFor = function(moeda) {
    if (!moeda) return 1;
    var iso = _toIso122(moeda);
    if (iso === 'BRL') return 1;

    var rate = window.getActiveHeaderFxRate(iso);
    _dbg122('_fxRateFor(' + moeda + ') → iso=' + iso + ', rate=' + rate);
    return (rate !== null && rate > 0) ? rate : 0;
  };

  /* ══════════════════════════════════════════════════════════════════
     §6. CANONICAL convertToBRL — NO hardcoded defaults

     Uses header FX as sole source. If explicit fxRates arg has a rate
     AND header has none, uses explicit. If nothing, returns null.
     ══════════════════════════════════════════════════════════════════ */

  window.convertToBRL = function(amount, currency, fxRates) {
    if (amount == null || isNaN(parseFloat(amount))) return { brlAmount: 0, fxRateToBrl: 1 };
    amount = parseFloat(amount);
    var iso = _toIso122(currency);
    if (iso === 'BRL') return { brlAmount: amount, fxRateToBrl: 1 };

    /* Primary: header FX rate */
    var rate = window.getActiveHeaderFxRate(iso);

    /* Secondary: explicit fxRates argument (e.g. from record's own fx_rate_to_brl) */
    if (rate === null && fxRates) {
      var explicit = parseFloat(fxRates[iso + 'BRL'] || fxRates[iso] || fxRates[iso.toLowerCase()] || 0);
      if (explicit > 0) {
        _dbg122('convertToBRL: using explicit fxRates for', iso, '=', explicit);
        rate = explicit;
      }
    }

    /* NO hardcoded defaults — if rate is still null, return null */
    if (rate === null || rate <= 0) {
      _dbg122('convertToBRL: NO rate for', iso, '— returning null');
      return null;
    }

    _dbg122('convertToBRL:', amount, iso, '× rate', rate, '=', (amount * rate).toFixed(2));
    return { brlAmount: parseFloat((amount * rate).toFixed(2)), fxRateToBrl: rate };
  };

  /* ══════════════════════════════════════════════════════════════════
     §7. OVERRIDE computeRecebimentoValorBRL — no FB fallback

     The v3.115/v3.120 versions had FB = { EUR: 6.10, … }.
     This override removes ALL hardcoded fallbacks.
     ══════════════════════════════════════════════════════════════════ */

  window.computeRecebimentoValorBRL = function(rec) {
    if (!rec) return 0;

    /* If already stamped with a BRL amount, use it */
    var stamped = parseFloat(rec.brl_amount || rec.amount_brl || 0);
    if (stamped > 0) return stamped;

    var origAmt = parseFloat(rec.originalAmount || rec.original_amount || rec.amount || rec.valor || 0) || 0;
    if (origAmt <= 0) return 0;

    var iso = _toIso122(rec.originalCurrency || rec.original_currency || rec.currency || rec.moeda || 'BRL');
    if (iso === 'BRL') return origAmt;

    /* Try record's own fx_rate_to_brl first (set at creation time) */
    var recRate = parseFloat(rec.fx_rate_to_brl || 0);
    if (recRate > 0) {
      _dbg122('computeRecebimentoValorBRL: using record fx_rate_to_brl=', recRate);
      return parseFloat((origAmt * recRate).toFixed(2));
    }

    /* Then header FX */
    var headerRate = window.getActiveHeaderFxRate(iso);
    if (headerRate !== null && headerRate > 0) {
      _dbg122('computeRecebimentoValorBRL: using header rate=', headerRate);
      return parseFloat((origAmt * headerRate).toFixed(2));
    }

    /* No rate available — return 0 (caller renders "FX indisponível") */
    _dbg122('computeRecebimentoValorBRL: NO rate for', iso, '— returning 0');
    return 0;
  };

  /* ══════════════════════════════════════════════════════════════════
     §8. OVERRIDE formatRecebimentoValorBRL — "FX indisponível" on null

     Already mostly correct in v3.120, but re-override to ensure
     getActiveHeaderFxRate (now patched) flows through properly.
     ══════════════════════════════════════════════════════════════════ */

  var _CSYM122 = { EUR:'€', USD:'$', GBP:'£', CHF:'CHF', COP:'COP', ARS:'ARS', MAD:'MAD', DOP:'DOP' };

  function _fmtBRL122(v) {
    var n = parseFloat(v) || 0;
    return 'R$\u00a0' + n.toLocaleString('pt-BR', { minimumFractionDigits:2, maximumFractionDigits:2 });
  }

  window.formatRecebimentoValorBRL = function(invoice) {
    if (!invoice) return '—';

    var iso = _toIso122(invoice.originalCurrency || invoice.original_currency || invoice.currency || 'BRL');
    var origAmt = parseFloat(invoice.originalAmount || invoice.original_amount || invoice.amount || 0) || 0;
    if (origAmt <= 0) return '—';

    var brlAmt;
    if (iso === 'BRL') {
      brlAmt = origAmt;
    } else {
      /* Check for pre-stamped BRL amount */
      var stamped = parseFloat(invoice.amount_brl || invoice.brl_amount || 0);
      if (stamped > 0 && Math.abs(stamped - origAmt) > 0.005) {
        brlAmt = stamped;
      } else {
        var rate = window.getActiveHeaderFxRate(iso);
        if (rate !== null && rate > 0) {
          brlAmt = origAmt * rate;
        } else {
          /* FX unavailable — show clear indicator */
          return '<div class="fin-main-value" style="color:var(--navy-faint,#8899aa);font-style:italic;">FX indisponível</div>';
        }
      }
    }

    /* Format with origin note for non-BRL */
    var html = '<div class="fin-main-value">' + _fmtBRL122(brlAmt) + '</div>';
    if (iso !== 'BRL') {
      var sym = _CSYM122[iso] || iso;
      html += '<div class="fin-origin-note" style="font-size:0.78em;color:var(--navy-faint,#8899aa);">';
      html += sym + '\u00a0' + origAmt.toLocaleString('pt-BR', { minimumFractionDigits:2, maximumFractionDigits:2 });
      html += ' × ' + (window.getActiveHeaderFxRate(iso) || 0).toFixed(4);
      html += '</div>';
    }
    return html;
  };

  /* ══════════════════════════════════════════════════════════════════
     §9. OVERRIDE _v36BrlOf — overview helper uses unified FX

     The original at ~line 19988 calls convertToBRL with the record's
     own fx_rate_to_brl. We keep that behavior but never fall back
     to hardcoded rates.
     ══════════════════════════════════════════════════════════════════ */

  window._v36BrlOf = function(r) {
    if (!r) return 0;

    /* Pre-stamped BRL amount takes priority */
    if (r.brl_amount != null && r.brl_amount !== '') {
      var brl = parseFloat(r.brl_amount);
      if (brl > 0) return brl;
    }

    var iso = _toIso122(r.original_currency || r.moeda || r.currency || 'BRL');
    var raw = parseFloat(r.original_amount || r.valor || r.amount || 0) || 0;
    if (raw <= 0) return 0;
    if (iso === 'BRL') return raw;

    /* Use record's own fx rate if available */
    var recRate = parseFloat(r.fx_rate_to_brl || 0);
    if (recRate > 0) return parseFloat((raw * recRate).toFixed(2));

    /* Otherwise, header FX */
    var headerRate = window.getActiveHeaderFxRate(iso);
    if (headerRate !== null && headerRate > 0) return parseFloat((raw * headerRate).toFixed(2));

    return 0;
  };

  /* ══════════════════════════════════════════════════════════════════
     §10. HOOK HEADER FX UPDATES → TRIGGER FINANCE RE-RENDER

     When the header strip updates rates (DOM write + cache write),
     we invalidate the content hash and trigger a debounced
     finRenderRecebimentos so Finance picks up the new rate immediately.
     ══════════════════════════════════════════════════════════════════ */

  var _fxRefreshTimer122 = null;

  function _refreshFinanceAfterFxChange() {
    if (_fxRefreshTimer122) clearTimeout(_fxRefreshTimer122);
    _fxRefreshTimer122 = setTimeout(function() {
      _dbg122('FX changed — invalidating finance hash and re-rendering');

      /* Invalidate v3.120's content hash so finRenderRecebimentos re-renders */
      if (window._lastRecvHash120_ref) {
        try { window._lastRecvHash120_ref.set(null); } catch(e) {}
      }

      /* Trigger re-render */
      if (typeof window.finRenderRecebimentos === 'function') {
        try { window.finRenderRecebimentos(); } catch(e) {
          _dbg122('finRenderRecebimentos error:', e.message);
        }
      }
      if (typeof window.finRenderDespesas === 'function') {
        try { window.finRenderDespesas(); } catch(e) {}
      }
    }, 300);
  }

  /* Expose for manual use / debugging */
  window.refreshFinanceAfterHeaderFxChange = _refreshFinanceAfterFxChange;

  /* Intercept _fxSetRate to trigger finance refresh on FX cache writes */
  if (typeof window._fxSetRate === 'function') {
    var _origFxSetRate122 = window._fxSetRate;
    window._fxSetRate = function(moeda, rate) {
      _origFxSetRate122.apply(this, arguments);
      _dbg122('_fxSetRate intercepted:', moeda, '=', rate, '— triggering finance refresh');
      _refreshFinanceAfterFxChange();
    };
  }

  /* Also observe header FX strip DOM mutations for immediate DOM updates */
  try {
    var headerStrip = document.querySelector('.header-fx-strip');
    if (headerStrip) {
      var _mo122 = new MutationObserver(function(mutations) {
        var fxChanged = false;
        for (var i = 0; i < mutations.length; i++) {
          var target = mutations[i].target;
          if (target && (target.classList && target.classList.contains('fx-val') ||
              (target.parentElement && target.parentElement.classList && target.parentElement.classList.contains('fx-val')))) {
            fxChanged = true;
            break;
          }
        }
        if (fxChanged) {
          _dbg122('Header FX DOM mutation detected — triggering finance refresh');
          _refreshFinanceAfterFxChange();
        }
      });
      _mo122.observe(headerStrip, { childList: true, subtree: true, characterData: true });
      _dbg122('MutationObserver attached to .header-fx-strip');
    } else {
      /* Header strip may not exist yet — attach observer when it appears */
      var _stripCheckInterval = setInterval(function() {
        var strip = document.querySelector('.header-fx-strip');
        if (strip) {
          clearInterval(_stripCheckInterval);
          var mo = new MutationObserver(function(mutations) {
            var fxChanged = mutations.some(function(m) {
              var t = m.target;
              return t && ((t.classList && t.classList.contains('fx-val')) ||
                (t.parentElement && t.parentElement.classList && t.parentElement.classList.contains('fx-val')));
            });
            if (fxChanged) {
              _dbg122('Header FX DOM mutation detected (deferred) — triggering finance refresh');
              _refreshFinanceAfterFxChange();
            }
          });
          mo.observe(strip, { childList: true, subtree: true, characterData: true });
          _dbg122('MutationObserver attached to .header-fx-strip (deferred)');
        }
      }, 1000);
      /* Stop checking after 30s */
      setTimeout(function() { clearInterval(_stripCheckInterval); }, 30000);
    }
  } catch(e) {
    _dbg122('MutationObserver setup error:', e.message);
  }

  /* Storage event for cross-tab FX cache updates */
  window.addEventListener('storage', function(e) {
    if (e.key === 'expatur_fx_rate_cache') {
      _dbg122('Cross-tab FX cache update detected');
      _refreshFinanceAfterFxChange();
    }
  });

  /* ══════════════════════════════════════════════════════════════════
     §11. DEBUG UTILITIES

     Set localStorage.setItem('DEBUG_FINANCE_FX', '1') to enable.
     Console: window._dumpFxState122() to see all rates.
     ══════════════════════════════════════════════════════════════════ */

  window._dumpFxState122 = function() {
    var currencies = ['EUR', 'USD', 'GBP', 'CHF', 'MAD', 'DOP', 'COP', 'ARS'];
    console.group('[FX-122] FX State Dump');
    currencies.forEach(function(iso) {
      var dom = _readHeaderFxDom(iso);
      var cache = _readFxCache122(iso);
      var active = window.getActiveHeaderFxRate(iso);
      console.log(iso + ':', 'DOM=' + dom, 'Cache=' + cache, 'Active=' + active);
    });
    console.groupEnd();
  };

  console.log('[Patch v3.122] Unified FX source of truth: header DOM → cache → null (no hardcoded 6.10 fallbacks). Finance shows "FX indisponível" when rate unavailable. Set localStorage DEBUG_FINANCE_FX=1 for logging.');

})();

