(function() {
  'use strict';
  console.log('[Patch v3.125] Finance architecture fixes: P1 (Stripe propagation), P2 (retry+toast), P3 (status normalization), P4 (dead FX defaults removed).');

  /* ══════════════════════════════════════════════════════════════════
     P3: PAYMENT STATUS NORMALIZATION

     Centralizes the "is this record paid?" check into a single helper.
     Adds a migration that normalizes existing payment records so
     status='paid' is the single canonical flag going forward.
     ══════════════════════════════════════════════════════════════════ */

  /**
   * Canonical paid check — replaces scattered OR-logic.
   * @param {Object} rec - Payment history record
   * @returns {boolean}
   */
  window._isRecordPaid = function(rec) {
    if (!rec) return false;
    return String(rec.status || '').toLowerCase() === 'paid'
        || !!rec.marked_paid_manually
        || !!rec.manual_paid
        || !!rec.paid_via_card;
  };

  /**
   * Normalize a payment record: if any paid flag is true, set status='paid'.
   * Returns true if the record was modified.
   */
  function _normalizePaymentRecord(rec) {
    if (!rec) return false;
    var wasPaid = window._isRecordPaid(rec);
    if (wasPaid && String(rec.status || '').toLowerCase() !== 'paid') {
      rec.status = 'paid';
      return true;
    }
    return false;
  }

  /**
   * Migrate all payment stores in localStorage.
   * Finds all expatur_payments_* keys and normalizes records.
   */
  function _migratePaymentStatuses() {
    var migrated = 0;
    try {
      for (var i = 0; i < localStorage.length; i++) {
        var key = localStorage.key(i);
        if (!key || key.indexOf('expatur_payments_') !== 0) continue;
        try {
          var arr = JSON.parse(localStorage.getItem(key) || '[]');
          if (!Array.isArray(arr)) continue;
          var changed = false;
          arr.forEach(function(rec) {
            if (_normalizePaymentRecord(rec)) changed = true;
          });
          if (changed) {
            localStorage.setItem(key, JSON.stringify(arr));
            migrated++;
          }
        } catch(e) { /* skip corrupt keys */ }
      }
    } catch(e) {}
    if (migrated > 0) console.log('[v3.125-P3] Normalized payment status in', migrated, 'store(s).');
  }

  // Run migration once on load
  _migratePaymentStatuses();


  /* ══════════════════════════════════════════════════════════════════
     P1: STRIPE STATUS PROPAGATION

     Override emCheckInvoiceStatus to also update:
     1. FinanceStore (fin_v1_entries) — mark matching transaction
     2. Per-dossier store (expatur_doss_finance_[id]) — update payment status
     After status check completes.
     ══════════════════════════════════════════════════════════════════ */

  var _origEmCheckInvoiceStatus = window.emCheckInvoiceStatus;

  window.emCheckInvoiceStatus = async function(invoiceId, dueDate) {
    // Call original implementation first
    await _origEmCheckInvoiceStatus.call(this, invoiceId, dueDate);

    // Now propagate the updated status to other stores
    try {
      // 1. Read the updated payment record to get the new status
      var paymentKey = (typeof _paymentKey === 'function') ? _paymentKey() : null;
      if (!paymentKey) return;

      var arr = [];
      try { arr = JSON.parse(localStorage.getItem(paymentKey) || '[]'); } catch(_) {}
      var updatedRec = null;
      for (var i = 0; i < arr.length; i++) {
        if (arr[i].stripeInvoiceId === invoiceId) { updatedRec = arr[i]; break; }
      }
      if (!updatedRec) return;

      var newStatus = String(updatedRec.status || '').toLowerCase();
      var isPaidNow = window._isRecordPaid(updatedRec);

      // 2. Propagate to FinanceStore
      if (window.FinanceStore && typeof window.FinanceStore.loadAll === 'function') {
        var items = window.FinanceStore.loadAll();
        var fsChanged = false;
        items.forEach(function(item) {
          if (item.stripeInvoiceId === invoiceId || item.sourceId === invoiceId) {
            item.status = isPaidNow ? 'pago' : (newStatus === 'open' ? 'pendente' : newStatus);
            item.updatedAt = new Date().toISOString();
            fsChanged = true;
          }
        });
        if (fsChanged && typeof window.FinanceStore.saveAll === 'function') {
          window.FinanceStore.saveAll(items);
          console.log('[v3.125-P1] Propagated Stripe status "' + newStatus + '" to FinanceStore for invoice', invoiceId);
        }
      }

      // 3. Propagate to per-dossier store
      var bookingRef = (document.getElementById('booking-ref') || {}).value || '';
      bookingRef = bookingRef.trim();
      if (bookingRef && bookingRef !== 'DEVIS') {
        // Find dossier ID from ref — look for dossier-id field or parse from ref
        var dossierId = (document.getElementById('dossier-id') || {}).value
                     || (document.getElementById('dossier-ref') || {}).value
                     || bookingRef;
        dossierId = (dossierId || '').trim();
        if (dossierId) {
          var dossKey = 'expatur_doss_finance_' + dossierId;
          try {
            var dossData = JSON.parse(localStorage.getItem(dossKey) || 'null');
            if (dossData) {
              // Update payment status in dossier finance data
              if (!dossData.payments) dossData.payments = {};
              dossData.payments[invoiceId] = {
                status: newStatus,
                updatedAt: new Date().toISOString(),
                stripeInvoiceId: invoiceId
              };
              // Also update the dossier-level paid status if applicable
              if (dossData.entries && Array.isArray(dossData.entries)) {
                dossData.entries.forEach(function(e) {
                  if (e.stripeInvoiceId === invoiceId || e.sourceId === invoiceId) {
                    e.status = isPaidNow ? 'pago' : (newStatus === 'open' ? 'pendente' : newStatus);
                  }
                });
              }
              localStorage.setItem(dossKey, JSON.stringify(dossData));
              console.log('[v3.125-P1] Propagated Stripe status "' + newStatus + '" to per-dossier store', dossKey);
            }
          } catch(e) { console.warn('[v3.125-P1] Per-dossier propagation error:', e); }
        }
      }

      // 4. Trigger finance surface refresh
      if (typeof _refreshFinanceSurfaces === 'function') {
        _refreshFinanceSurfaces({});
      } else if (typeof window.dossFinRenderPanel === 'function') {
        try { window.dossFinRenderPanel(); } catch(e) {}
      }

    } catch(e) {
      console.warn('[v3.125-P1] Status propagation error:', e);
    }
  };


  /* ══════════════════════════════════════════════════════════════════
     P2: STRIPE SYNC RETRY + ERROR TOAST

     Override _syncStripeMarkPaid, _syncStripeMarkOpen, and
     _syncStripeUpdateAmount with retry logic (max 2 retries)
     and a user-visible error toast on final failure.
     ══════════════════════════════════════════════════════════════════ */

  /**
   * Generic Stripe sync with retry.
   * @param {string} label - Human label for logging/toast
   * @param {Object} payload - POST body
   * @param {number} maxRetries - Max retry count (default 2)
   */
  function _stripeSyncWithRetry(label, payload, maxRetries) {
    maxRetries = maxRetries || 2;
    var pw = (typeof _getStripePassword === 'function') ? _getStripePassword() : '';
    if (!pw) { console.warn('[StripeSync] No password — skipping', label); return; }
    var url = (typeof STRIPE_WORKER_URL !== 'undefined') ? STRIPE_WORKER_URL : '';
    if (!url) return;

    payload.password = pw;

    function attempt(retryCount) {
      fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      }).then(function(r) {
        if (!r.ok) {
          if (retryCount < maxRetries) {
            console.warn('[StripeSync]', label, 'HTTP', r.status, '— retry', retryCount + 1);
            setTimeout(function() { attempt(retryCount + 1); }, 1000 * (retryCount + 1));
          } else {
            console.error('[StripeSync]', label, 'FAILED after', maxRetries, 'retries. HTTP', r.status);
            if (typeof toast === 'function') {
              toast('Erreur Stripe (' + label + ') : HTTP ' + r.status, 'error');
            }
          }
        } else {
          console.log('[StripeSync]', label, 'OK');
        }
      }).catch(function(e) {
        if (retryCount < maxRetries) {
          console.warn('[StripeSync]', label, 'error — retry', retryCount + 1, ':', e.message);
          setTimeout(function() { attempt(retryCount + 1); }, 1000 * (retryCount + 1));
        } else {
          console.error('[StripeSync]', label, 'FAILED after', maxRetries, 'retries:', e.message);
          if (typeof toast === 'function') {
            toast('Erreur Stripe (' + label + ') : ' + e.message, 'error');
          }
        }
      });
    }

    attempt(0);
  }

  /* Override the three fire-and-forget sync functions */

  window._syncStripeMarkPaid = function(invoiceId) {
    if (!invoiceId) return;
    _stripeSyncWithRetry('mark_paid', {
      type: 'mark_paid',
      invoice_id: invoiceId,
      paid_out_of_band: true
    });
  };

  window._syncStripeMarkOpen = function(invoiceId) {
    if (!invoiceId) return;
    _stripeSyncWithRetry('mark_open', {
      type: 'mark_open',
      invoice_id: invoiceId
    });
  };

  window._syncStripeUpdateAmount = function(invoiceId, newAmountDecimal, currency) {
    if (!invoiceId || !newAmountDecimal) return;
    var amountCents = Math.round(newAmountDecimal * 100);
    _stripeSyncWithRetry('update_amount', {
      type: 'update_amount',
      invoice_id: invoiceId,
      amount: amountCents,
      currency: (currency || '').toLowerCase()
    });
  };

})();

