/* ════════════════════════════════════════════════════════════════════════
   v3.126 — DOSSIER+TICKETING AUDIT — SAFE READ-ONLY DIAGNOSTIC HELPERS
   ────────────────────────────────────────────────────────────────────────
   Pure additions. No existing function is wrapped, replaced, or modified.
   The setItem hook only LOGS when DEBUG_DOSSIER_SYNC is explicitly set
   to true; otherwise it is a pass-through.
   ════════════════════════════════════════════════════════════════════════ */
(function(){
  'use strict';

  if (window.__V3126_AUDIT_INSTALLED__) return;
  window.__V3126_AUDIT_INSTALLED__ = true;

  // Toggle once in console: window.DEBUG_DOSSIER_SYNC = true
  if (typeof window.DEBUG_DOSSIER_SYNC === 'undefined') {
    window.DEBUG_DOSSIER_SYNC = false;
  }

  function _safeParse(s, fallback){
    try { return JSON.parse(s); } catch(_) { return fallback; }
  }
  function _refKey(ref){
    return String(ref || '').replace(/[^a-zA-Z0-9]/g, '_');
  }

  /**
   * Snapshot what the dossier engine, billet, finance and server currently
   * "see" for a given (or active) dossier. NO mutations.
   */
  window.logDossierTicketingState = function(id){
    try {
      id = id || localStorage.getItem('expatur_active_dossier');
      if (!id) { console.warn('[v3.126] no active dossier'); return null; }
      var dossier = _safeParse(localStorage.getItem('expatur_dossier_' + id), null);
      var ref = (dossier && dossier.fields && dossier.fields['booking-ref']) || '';
      var rk = _refKey(ref);
      var paymentsArr = _safeParse(localStorage.getItem('expatur_payments_' + rk), []);
      var isPaid = Array.isArray(paymentsArr) && paymentsArr.some(
        typeof window._isRecordPaid === 'function' ? window._isRecordPaid : function(){ return false; }
      );
      var report = {
        id: id,
        ref: ref,
        refKey: rk,
        dossier: dossier,
        booked:       localStorage.getItem('expatur_booked_'    + id),
        bookedAt:     localStorage.getItem('expatur_bookedAt_'  + id),
        billet:       _safeParse(localStorage.getItem('expatur_billet_'     + rk), null),
        frozen:       localStorage.getItem('billetFrozen_'      + ref),
        payments:     paymentsArr,
        pnl:          _safeParse(localStorage.getItem('expatur_pnl_'        + ref), null),
        emState:      _safeParse(localStorage.getItem('expatur_em_state_'   + rk), null),
        emInvoice:    _safeParse(localStorage.getItem('expatur_em_invoice_' + rk), null),
        dossFinance:  _safeParse(localStorage.getItem('expatur_doss_finance_' + id), null),
        statusMenu:  (typeof _tsComputeStatus === 'function') ? _tsComputeStatus(id) : '?',
        isIssuedIdx: (typeof _diIsIssued      === 'function') ? _diIsIssued(ref)    : '?',
        isPaid:      isPaid
      };
      try {
        console.table([{
          id: id, ref: ref,
          statusMenu: report.statusMenu, isIssuedIdx: report.isIssuedIdx,
          booked: !!report.booked, frozen: report.frozen === '1',
          hasBillet: !!report.billet, hasPnl: !!report.pnl,
          paymentCount: paymentsArr.length, isPaid: report.isPaid
        }]);
      } catch(_) {}
      console.log('[v3.126] dossier+ticketing state', report);
      return report;
    } catch(e) {
      console.warn('[v3.126] logDossierTicketingState failed:', e);
      return null;
    }
  };

  /**
   * Compare local (memoryStore) vs server-of-record for the dossier blob.
   * Read-only round-trip via window.loadData if the bridge is up.
   */
  window.validateDossierTicketingPersistence = async function(id){
    try {
      id = id || localStorage.getItem('expatur_active_dossier');
      if (!id) { console.warn('[v3.126] no active dossier'); return null; }
      var local = _safeParse(localStorage.getItem('expatur_dossier_' + id), null);
      var rows = (typeof window.loadData === 'function')
        ? await window.loadData('dossier').catch(function(){ return []; })
        : [];
      var srv = (rows || []).find(function(r){ return r && r.name === id; });
      var serverData = srv && (srv.data !== undefined ? srv.data : srv);
      var equal;
      try { equal = JSON.stringify(local) === JSON.stringify(serverData); }
      catch(_) { equal = false; }
      var result = { id: id, equal: equal, local: local, server: serverData };
      console.log('[v3.126] validateDossierTicketingPersistence', result);
      return result;
    } catch(e) {
      console.warn('[v3.126] validate failed:', e);
      return null;
    }
  };

  /**
   * Optional setItem logger. Pass-through unless DEBUG_DOSSIER_SYNC is true.
   * Installed only once; never alters values.
   */
  try {
    var _origSet = Storage.prototype.setItem;
    if (!_origSet.__v3126_logged__) {
      Storage.prototype.setItem = function(k, v) {
        try {
          if (window.DEBUG_DOSSIER_SYNC && typeof k === 'string' &&
              /^(expatur_(dossier|billet|payments|pnl|em_state|em_invoice|booked|bookedAt|doss_finance)|billetFrozen_)/.test(k)) {
            var preview = '';
            try { preview = (v == null ? '' : String(v)).slice(0, 160); } catch(_) {}
            console.log('[v3.126 setItem]', k, '←', preview);
          }
        } catch(_) {}
        return _origSet.apply(this, arguments);
      };
      Storage.prototype.setItem.__v3126_logged__ = true;
    }
  } catch(_) {}

  console.log('[v3.126] Dossier+Ticketing audit helpers ready: '
    + 'window.logDossierTicketingState() · '
    + 'window.validateDossierTicketingPersistence() · '
    + 'window.DEBUG_DOSSIER_SYNC = true to log key writes.');
})();

