      existing.id          = id;
      existing.tripType    = harvest.tripType;
      existing.segments    = harvest.segments;
      existing.dep         = harvest.segments[0].dep || existing.dep || '';
      existing.arr         = harvest.segments[0].arr || existing.arr || '';
      existing.dod         = harvest.segments[0].date || existing.dod || '';
      existing.dor         = (harvest.segments.length > 1)
                              ? (harvest.segments[harvest.segments.length - 1].date || '')
                              : (existing.dor || '');
      existing.itineraryConfirmedAt = new Date().toISOString();
      existing.lastModified = existing.itineraryConfirmedAt;

